def _mail_fs_prefs_tpl(request=None):
    """11-23 대표 「조정한 글자 크기 꼭 기억 · 새로고침·업데이트해도 가장 최근 값」 — 서버에 기억한 글자 크기를 화면에 바로 실어 보냄
    (mail_fs.html 이 이 컴퓨터 값과 바꾼 시각을 견줘 더 최근 것을 씀). 실패해도 화면은 그대로(None)."""
    try:
        u = get_user(request) if request is not None else None
        if not u:
            return None
        from . import mail_ui_prefs as _mup
        with db_session() as c:
            return _mup.get_fs(c, u["id"])
    except Exception as e:   # 화면을 막지 않되 흔적은 남김
        print("[mail_fs_prefs] " + repr(e)[:200])
        return None


tpl.env.globals["mail_fs_prefs"] = _mail_fs_prefs_tpl


# =====================================================
# v5H226z144 (2026-06-01): 직원 이름 공통 표기 함수 (대표 지시)
#   베트남 직원은 기본 표기를 "베트남어 (한국발음)" 으로.
#   예: Nguyễn Văn A (응우옌반아)  /  한국 직원은 한국 이름 그대로.
#   템플릿: {{ vname(user) }}  또는  {{ user|vname }}  또는  {{ vname(name, name_vi) }}
# =====================================================
def vname(u, name_vi=None, entity=None):
    """직원 표시 이름. 베트남 직원(name_vi 보유) → 'name_vi (name)'.
    u: users dict/Row (name·name_vi·entity 포함) 또는 이름 문자열."""
    try:
        if isinstance(u, str):
            name = u
        elif hasattr(u, "get"):                      # dict
            name = u.get("name") or ""
            name_vi = name_vi if name_vi is not None else u.get("name_vi")
            entity = entity if entity is not None else u.get("entity")
        else:                                          # sqlite3.Row 등
            keys = set(u.keys()) if hasattr(u, "keys") else set()
            name = (u["name"] if "name" in keys else "") or ""
            if name_vi is None and "name_vi" in keys:
                name_vi = u["name_vi"]
            if entity is None and "entity" in keys:
                entity = u["entity"]
    except Exception:
        return str(u or "")
    name = (name or "").strip()
    nv = (name_vi or "").strip()
    # 베트남어 이름이 있고 한국발음과 다르면 병기. (name_vi 는 VN 직원만 채워짐)
    if nv and nv != name:
        return f"{nv} ({name})" if name else nv
    return name
tpl.env.globals["vname"] = vname


# v5H226z799 (대표 지시·규칙): 이름 표시는 항상 '이름 직책 부서'. 이름=vname()(본사=한국이름 / VN=베트남어(한국발음)).
#   dept 미지정 시 u의 team_name/dept/team 사용. 신규 이름 표시는 이 헬퍼로 통일.
# z1163 (대표 지시 2026-10-11 「직책도 … 베트남은 영어로」): lang 을 주면 **직책만** 그 사람 말로
#   바꿔 보여 준다(이음 확정 표 · i18n.rank_label). 🔴 저장값(users.rank)은 그대로다.
#   lang 을 안 주면 지금까지와 **글자 하나도 다르지 않다** — 옛 부르는 곳이 안 바뀌게.
def vname_full(u, dept=None, lang=None):
    try:
        nm = vname(u)
        rank = ""
        dept_s = (dept or "")
        if hasattr(u, "get"):
            rank = rank_label((u.get("rank") or "").strip(), lang or "ko")
            if not dept_s:
                dept_s = (u.get("team_name") or u.get("dept") or u.get("team") or "").strip()
        parts = [nm]
        if rank:
            parts.append(rank)
        if dept_s:
            parts.append(dept_s)
        return " ".join([p for p in parts if p])
    except Exception:
        return vname(u)
tpl.env.globals["vname_full"] = vname_full
# z1163: 화면에서 직책만 그 사람 말로 — {{ rank_label(u.rank, lang) }}
tpl.env.globals["rank_label"] = rank_label


# v5H226z800 (대표 지시·규칙): user id → '이름 직책 부서'(VN=베트남어(한국발음)). 이름만 스냅샷(..._by_name)을
#   발행자·작성자 표시 시 그 id로 현재 직책·부서를 붙여 규칙 통일. 없으면 fallback(스냅샷 이름). [[knk_name_display_rule]]
def user_disp_by_id(c, uid, fallback="", lang=None):
    try:
        if uid:
            r = c.execute(
                "SELECT u.name, u.name_vi, COALESCE(u.rank,'') AS rank, "
                "COALESCE(t.name,'') AS team_name FROM users u "
                "LEFT JOIN teams t ON u.team_id=t.id WHERE u.id=?", (uid,)).fetchone()
            if r:
                s = vname_full(dict(r), lang=lang)   # z1200: 직책을 보는 사람의 말로
                if s:
                    return s
    except Exception:
        pass
    return fallback or ""
tpl.env.filters["vname"] = vname


# =====================================================
# v5H226z175 (2026-06-03): 상태(status) 영문 enum → 한글 표기 공통 필터 (대표 지시)
#   매출·수출·진행현황 등에서 SHIPPED / IN_PRODUCTION 같은 영문 코드가 그대로
#   보이는 문제 해결. "한글(큰글씨) + 영문(작은글씨)" 2줄로 통일 표기.
#   - 매핑에 없는 값(이미 한글이거나 미지정)은 원문 그대로 통과 → 기존 화면 안전.
#   - 색상 판정용 조건(== 'PAID' 등)은 영문 원본을 그대로 두고, 보이는 글자만 교체.
#   사용:  {{ s.status|status_kr }}        (pill 안 — 2줄)
#          {{ quote.status|status_kr('inline') }}  (한 줄 텍스트 — "한글(영문)")
# =====================================================
_STATUS_KR_MAP = {
    # --- 수주(SO) / 매출 ---
    "DRAFT": "임시", "CONFIRMED": "수주확정", "IN_PRODUCTION": "진행중",
    "READY_TO_SHIP": "납품대기", "SHIPPED": "출하", "INVOICED": "송장발행",
    "PAID": "수금완료", "CANCELLED": "취소", "CANCELED": "취소", "HOLD": "보류",
    # --- 수출(export order / CI / PL / BL / 통관) ---
    "CI_ISSUED": "CI발행", "PL_READY": "PL준비", "CLEARED": "통관완료",
    "ISSUED": "발행", "DELIVERED": "출하", "SUBMITTED": "제출",
    "REJECTED": "반려", "APPROVED": "승인",
    # --- 진행현황(progress) ---
    "DONE": "완료", "DELAY": "지연", "PROGRESS": "진행중",
    # --- 공통 ---
    "PENDING": "대기", "PARTIAL": "부분", "COMPLETED": "완료",
    "OPEN": "진행", "CLOSED": "마감", "ADJUSTED": "조정완료",
}
def status_kr(val, mode="stack"):
    """상태 영문 enum → '한글 + 영문' 표기. 매핑 없으면 원문 그대로."""
    from markupsafe import Markup, escape
    s = "" if val is None else str(val).strip()
    if not s:
        return Markup("—")
    kr = _STATUS_KR_MAP.get(s.upper())
    if not kr:                                   # 이미 한글이거나 미지정 → 원문
        return Markup(escape(s))
    if mode == "inline":
        return Markup(f'{escape(kr)} <span class="st-en">({escape(s)})</span>')
    return Markup(f'<span class="st-kr">{escape(kr)}</span>'
                  f'<span class="st-en">{escape(s)}</span>')
tpl.env.filters["status_kr"] = status_kr
tpl.env.globals["status_kr"] = status_kr


# v5H226z507 (대표 지시): 수량·단가 표시 전역 통일.
#   수량=정수면 소수점 제거(1.0→1·실제 소수 1.5는 유지). 단가=원화(KRW)만 소수점 숨김·외화는 소수 2자리 유지.
def _fmt_qty(v):
    try:
        f = float(str(v).replace(",", "")) if v not in (None, "") else 0.0
    except Exception:
        return v
    return str(int(f)) if f == int(f) else ("%g" % f)


def _fmt_price(v, ccy="KRW"):
    try:
        f = float(str(v).replace(",", "")) if v not in (None, "") else 0.0
    except Exception:
        return v
    # z1191z56 (대표 11-18): 끝자리 5 는 엑셀처럼 올림(41.355 → 41.36 · 전엔 파이썬 반올림이라 41.35) — 표시만 · 저장값 그대로
    from decimal import Decimal as _D56, ROUND_HALF_UP as _HU56
    try:
        _d56 = _D56(str(v).replace(",", "").strip()) if v not in (None, "") else _D56(0)
    except Exception:
        _d56 = _D56(repr(f))
    if (str(ccy or "KRW").upper()) == "KRW":
        return "{:,.0f}".format(_d56.quantize(_D56("1"), rounding=_HU56))      # 원화: 소수점 없음
    return "{:,.2f}".format(_d56.quantize(_D56("0.01"), rounding=_HU56))       # 외화: 소수 2자리 유지


_CCY_SYMBOL = {"USD": "$", "KRW": "₩", "VND": "₫", "EUR": "€", "JPY": "¥", "CNY": "元"}


def _fmt_money(v, ccy="KRW"):
    """z750→z751(대표 지시) 통화 표시 표준: '기호+숫자'(통화기호 앞) + 자릿수구분 + KRW 정수·외화 소수 2자리
    (3째 자리 반올림 — ROUND_HALF_UP). 기호: USD $·KRW ₩·VND ₫·EUR €·JPY ¥·CNY 元(¥ 겹침 회피). 미지정 통화는 '코드 ' 폴백.
    예: money(4390.735,'USD')→'$4,390.74' · money(1430000,'KRW')→'₩1,430,000'."""
    from decimal import Decimal, ROUND_HALF_UP, InvalidOperation
    c = str(ccy or "KRW").upper()
    sym = _CCY_SYMBOL.get(c, c + " ")   # 미지정 통화는 코드+공백(명확성 유지)
    try:
        d = Decimal(str(v).replace(",", "").strip()) if v not in (None, "") else Decimal(0)
    except (InvalidOperation, ValueError, TypeError):
        return f"{sym}{v}"
    q = Decimal("1") if c == "KRW" else Decimal("0.01")
    d = d.quantize(q, rounding=ROUND_HALF_UP)
    return sym + ("{:,.0f}".format(d) if c == "KRW" else "{:,.2f}".format(d))


def _ccy_sym(ccy):
    """z758: 통화 기호만 반환(편집 입력칸 앞 표기용). 미지정 통화는 코드 그대로."""
    return _CCY_SYMBOL.get(str(ccy or "KRW").upper(), str(ccy or ""))


tpl.env.filters["qtyfmt"] = _fmt_qty

# z1191z4e (이새롬 프로 요청 · 대표 결정): 작업일정표·부서 일정표·엑셀 수량 단위 — 한 곳에서 정한다
_QTY_UNIT_BY_FORM_Z4E = {"완제품": "대", "제품": "EA", "기타": "식", "소모품": "건", "상품": "식"}


# z1191z15 (안지연 프로 요청 · 대표 「개조는 모두 식으로 1식, 2식, 3식」 2026-11-10): 상품(부품 묶음) 수량 단위 = PO유형으로.
#   개조 = N식(1식·2식…) · 신규·추가(그 밖) = 완제품 N대분(1대분 포함). 예전엔 PO유형과 상관없이 2+ 대분 · 1 식이라
#   신규·추가 1대가 「1식」으로 보였다. 수량 0·빈칸은 1로 본다(화면 숫자와 같게). 한 곳 — 작업일정표·부서 일정표·엑셀·
#   상세 수주 카드·합계·수정 화면 표가 모두 이 함수를 쓴다(템플릿 전역 partsqty).
def _parts_qty_unit_z15(po_type) -> str:
    return "식" if str(po_type or "").strip() == "개조" else "대분"


def _parts_qty_z15(qty, po_type) -> dict:
    try:
        _n = int(float(qty or 0))
    except (TypeError, ValueError):
        _n = 0
    _u = _parts_qty_unit_z15(po_type)
    # z1191z16 (안지연 프로 확인 · 대표 「1,2,3 진행해」 2026-11-10): 수량 0·빈칸을 1 로 보이면 안 넣은 줄을 못 찾는다 → 「⚠ 미입력」
    if _n < 1:
        return {"n": 0, "unit": _u, "short": "미입력", "label": "⚠ 수량 미입력", "missing": True}
    return {"n": _n, "unit": _u, "short": "%d%s" % (_n, _u), "missing": False,
            "label": ("%d식" % _n) if _u == "식" else ("완제품 %d대분" % _n)}


def _board_qty_unit(r) -> str:
    """줄(dict) → 수량 단위. 소모품 줄 = 건 · 상품 = PO유형 개조면 식, 그 밖은 대분(z1191z15) · 적어 둔 단위(제품 표시수량·기타) ·
    형태별 기본(완제품 대 · 제품 EA · 기타 식) · 모르면 대(호기)."""
    r = r or {}
    if r.get("kind") == "consumable":
        return "건"
    if r.get("is_parts"):
        return _parts_qty_unit_z15(r.get("po_type"))
    bu = str(r.get("board_unit") or "").strip()
    if bu:
        return bu
    ft = str(r.get("qty_form") or r.get("form_type") or "").strip()
    if ft == "상품":   # z1191z16: 수주로 안 갈라진 상품 줄도 PO유형 규칙(z1191z15)
        return _parts_qty_unit_z15(r.get("po_type"))
    return _QTY_UNIT_BY_FORM_Z4E.get(ft, "대")


tpl.env.filters["qtyunit"] = _board_qty_unit


# z1191z89 (안지연 프로 요청 · 대표 11-20 「단위, 원화등 … 전체적으로 맞는지 다시 검증해」 → 11-21 「다음 진행할것 진행해」):
#   수주 하나의 수량 단위 = 작업일정표 수량 칸과 **같은 규칙**(_board_qty_unit) — 적어 둔 단위(board_unit) → 없으면 형태별 기본 하나
#   (완제품 대 · 제품 EA · 기타 식 · 소모품 건 · 상품 PO유형). 전: 프로젝트 상세(수주 카드·프로젝트 정보·오른쪽 「단가 × N대」)는
#   빈 단위를 「개」·「대」로 따로 붙여 일정표(식·EA)와 글자가 달랐다(001E2611 E-260624-1: 일정표 1 식 · 정보 1 개 · 금액 × N대).
_FORM_LABEL_BY_KEY_Z89 = {"assembly": "완제품", "semi": "제품", "etc": "기타", "consumable": "소모품", "parts": "상품"}


def _so_qty_unit_z89(so) -> str:
    so = so or {}
    _g = so.get if hasattr(so, "get") else (lambda k, d=None: getattr(so, k, d))
    _fk = str(_g("form_key") or "").strip()
    # 추가 검토(11-21): 소모품 수주도 고른 단위(식·EA·SET)가 먼저 — 일정표 수주 줄과 같다(「건」은 비었을 때만)
    return _board_qty_unit({"board_unit": _g("board_unit"),
                            "qty_form": (_FORM_LABEL_BY_KEY_Z89.get(_fk) or str(_g("form_label") or "").strip()),
                            "po_type": _g("po_type")})


def _so_qty_z89(so) -> int:
    """수주 하나의 수량 — 등록 때 적은 「작업일정표 수량」(board_qty)이 있으면 그것(일정표·수정 화면과 같은 수) ·
    없으면 호기·품목 줄 수량 합(v5H226z627) · 그것도 없으면 unit_qty."""
    so = so or {}
    _g = so.get if hasattr(so, "get") else (lambda k, d=None: getattr(so, k, d))
    try:
        _b = int(float(_g("board_qty") or 0))
    except (TypeError, ValueError):
        _b = 0
    if _b > 0:
        return _b
    _s = 0
    for _u in (_g("units") or []):
        try:
            _s += int(float((_u.get("qty") if hasattr(_u, "get") else getattr(_u, "qty", 0)) or 0))
        except (TypeError, ValueError):
            pass
    if _s:
        return _s
    try:
        return int(float(_g("unit_qty") or 1))
    except (TypeError, ValueError):
        return 1


def _so_qty_lines_z89(so) -> int:
    """호기·품목 줄 수량 합(취소 줄 포함 · 예전 카드 숫자 _qq 와 같은 셈)."""
    # z1191z132 (대표 11-24 「같은 유형 미리 막기」): 「취소」 줄은 수량 합에서 뺀다 — _so_qty_note_z89 의 줄 수(_nl)와 같은 기준.
    #   (부르는 곳 = _so_qty_note_z89 하나뿐 · 취소 줄이 없으면 합은 예전과 같다)
    so = so or {}
    _g = so.get if hasattr(so, "get") else (lambda k, d=None: getattr(so, k, d))
    _s = 0
    for _u in (_g("units") or []):
        if str((_u.get("unit_status") if hasattr(_u, "get") else getattr(_u, "unit_status", "")) or "") == "취소":
            continue
        try:
            _s += int(float((_u.get("qty") if hasattr(_u, "get") else getattr(_u, "qty", 0)) or 0))
        except (TypeError, ValueError):
            pass
    return _s


# z1191z117 ①: 입금 완료(PAID)·계산서 발행(INVOICED) 수주 = 「닫힌 수주」. 화면 [✏️ 수정]에서 한 번 확인하면 고칠 수 있다.
#   (취소 수주는 그대로 못 고침.) 확인 표시 = 요청 머리 X-KNK-Closed-OK: 1 (또는 폼 closed_ok=1).
_Z117_CLOSED = ("INVOICED", "PAID")


def _closed_ok_z117(req, form=None) -> bool:
    try:
        if str(req.headers.get("x-knk-closed-ok") or "").strip() == "1":
            return True
    except Exception:
        pass
    try:
        return form is not None and str(form.get("closed_ok") or "").strip() == "1"
    except Exception:
        return False


def _closed_msg_z117(st: str) -> str:
    _k = "입금 완료" if st == "PAID" else "계산서 발행"
    return (f"{_k}된 수주입니다 — 프로젝트 상세에서 [✏️ 수정]을 눌러 「입금 완료 수주 고치기」를 확인한 뒤 고쳐 주세요. "
            "(세금계산서·입금 기록은 그대로 남습니다)")


def _quick_target_so_z117(c, pid, so_no):
    """z1191z117k: 수정 화면(등록과 같은 화면)이 고치는 수주 — 그 프로젝트의 취소 아닌 수주 중 수주번호가 맞는 것 · 없으면 최신."""
    _n = str(so_no or "").strip()
    if _n:
        r = c.execute("SELECT id FROM orders WHERE project_id=? AND order_no=? AND COALESCE(status,'')<>'CANCELLED'", (pid, _n)).fetchone()
        if r:
            return r[0]
    r = c.execute("SELECT id FROM orders WHERE project_id=? AND COALESCE(status,'')<>'CANCELLED' ORDER BY id DESC LIMIT 1", (pid,)).fetchone()
    return r[0] if r else None


# ═══ z1191z152 (대표 11-25 「사용자가 확정하지 않은 데이터를 마음대로 연결해서 입력한 걸 자꾸 틀어 버리면 … 신뢰할 수 없어」 · 원칙 4개 · 1단계) ═══
#   수주가 2개 이상(취소 빼고)인 관리번호 = 정보 수정의 고객사·2차 고객·거래구분·형태·통화·PO유형·모델·장비는 화면 위 「고치는 수주」에만 저장.
#   프로젝트 대표값·첫 수주·다른 수주는 건드리지 않는다(001M2603~004M2603 사고: 고객사 바꾸면 첫 수주 고객사까지 바뀜).
#   바뀐 칸만 그 수주에 실제 값으로(안 바꾼 빈칸은 비워 둠 — 대표 「빈칸 고정은 하지 않음」) · 이력 = 어느 수주 · 무엇 · 전→후 · 누가.
_Z152_SO_FIELDS = (   # (화면 이름, 수주 칸, 프로젝트 칸, 이력 글자)
    ("customer_id", "customer_id", "customer_id", "고객사"),
    ("secondary_customer", "end_customer", "secondary_customer", "2차 고객"),
    ("is_export", "@items", "is_export", "거래구분"),   # 수주 거래구분 = 그 수주 품목 줄 is_export(작업일정표 z1191 과 같음)
    ("shipment_form", "so_form", "shipment_form", "형태"),   # 수주 형태 = orders.so_form(작업일정표 z1191z19 과 같음)
    ("currency", "currency", "currency", "통화"),
    ("po_type", "po_type", "po_type", "PO유형"),
    ("model", "model_name", "model_name", "모델"),
    ("equip_name", "equip_name", "equip_name", "장비"),
)
_Z152_FORM_LB = {"ASSEMBLY": "완제품", "SEMI": "제품", "PARTS": "상품", "ETC": "기타"}


def _z152_multi(c, pid):
    return (c.execute("SELECT COUNT(*) FROM orders WHERE project_id=? AND COALESCE(status,'')<>'CANCELLED'",
                      (int(pid),)).fetchone()[0] or 0) >= 2


def _z152_norm(key, v):
    if v is None:
        return ""
    s = str(v).strip()
    if key == "is_export":
        return "1" if s in ("1", "True", "true", "수출") else "0"
    if key in ("currency", "shipment_form"):
        return s.upper()
    if key == "customer_id":
        try:
            return str(int(float(s))) if s else ""
        except (TypeError, ValueError):
            return ""
    return s


def _z152_effective(proj, so):
    """수주 화면 값 = 수주 칸에 값이 있으면 그것 · 비었으면 프로젝트 값(지금 화면 규칙 그대로)."""
    out = {}
    for fk, sk, pk, _lb in _Z152_SO_FIELDS:
        sv = so.get(sk) if so else None
        out[fk] = sv if (sv is not None and str(sv).strip() != "") else proj.get(pk)
    if so and so.get("so_customer") and so.get("customer_id"):
        out["customer_name"] = so.get("so_customer")
    else:
        out["customer_name"] = proj.get("customer_name")
    # 2차 고객 = 상세 화면과 같은 규칙: 수주 칸 → 없으면 (수주 고객사가 대표 고객사와 같을 때만) 프로젝트 2차
    if so is not None and so.get("end_customer") is not None:   # z1191z153: '' = 사람이 일부러 비움 → 빈칸 그대로
        out["secondary_customer"] = str(so.get("end_customer") or "").strip()
    elif so is not None:
        same = (not so.get("customer_id")) or _z152_norm("customer_id", so.get("customer_id")) == _z152_norm("customer_id", proj.get("customer_id"))
        out["secondary_customer"] = (proj.get("secondary_customer") or "") if same else ""
    return out


def _z152_so_row(c, oid):
    cols = {r[1] for r in c.execute("PRAGMA table_info(orders)").fetchall()}
    want = [sk for _f, sk, _p, _l in _Z152_SO_FIELDS if sk in cols]
    r = c.execute("SELECT id, order_no, COALESCE(status,'') AS status, " + ", ".join(want) +
                  ", (SELECT name FROM customers WHERE customers.id=orders.customer_id) AS so_customer FROM orders WHERE id=?",
                  (int(oid),)).fetchone()
    d = dict(r) if r else None
    if d is not None:   # 거래구분 = 품목 줄이 모두 같으면 그 값 · 섞였거나 없으면 None(프로젝트 값을 따름)
        try:
            ex = {(None if x[0] is None else int(x[0])) for x in c.execute(
                "SELECT is_export FROM order_items WHERE order_id=? AND COALESCE(unit_status,'')<>'취소'", (int(oid),)).fetchall()}
            d["@items"] = (next(iter(ex)) if len(ex) == 1 else None)
            d["@n_items"] = c.execute("SELECT COUNT(*) FROM order_items WHERE order_id=?", (int(oid),)).fetchone()[0] or 0
        except Exception:
            d["@items"], d["@n_items"] = None, 0
        if not d.get("so_form"):   # 형태 = 작업일정표·상세와 같은 라벨 규칙(so_form 비면 수주 종류·호기로 정함)
            try:
                d["so_form"] = _Z19_FORM_CODE.get(_z19_so_form_label(c, oid) or "") or None
            except Exception:
                pass
        cols = set(cols) | {"@items"}
    return d, cols


def _z152_show(c, key, v):
    if key == "customer_id" and v:
        r = c.execute("SELECT name FROM customers WHERE id=?", (int(v),)).fetchone()
        return r[0] if r else v
    if key == "is_export":
        return "수출" if v == "1" else "내수"
    if key == "shipment_form":
        return _Z152_FORM_LB.get(v, v)
    return v


def _z152_save_so_fields(c, pid, form, proj_old, user, allow_single=False):
    """고른 수주에만 저장 → 바뀐 칸 [(이력 글자, 전, 후)] · 수주가 1개이거나 고를 수주가 없으면 None(예전 흐름).
    z1191z154 (대표 11-25 「관리번호 = 공통만 · 나머지는 수주번호」): allow_single=True 면 수주 1개 관리번호도 그 수주 칸에 저장
    (프로젝트 쪽 저장은 예전 흐름이 함께 — 수주 1개 = 프로젝트와 같은 값)."""
    _single154 = False
    if not _z152_multi(c, pid):
        if not allow_single:
            return None
        _one154 = c.execute("SELECT id FROM orders WHERE project_id=? AND COALESCE(status,'')<>'CANCELLED'", (int(pid),)).fetchall()
        if len(_one154) != 1:
            return None
        _single154 = True
    oid = (c.execute("SELECT id FROM orders WHERE project_id=? AND COALESCE(status,'')<>'CANCELLED'", (int(pid),)).fetchone()[0]
           if _single154 else _quick_target_so_z117(c, pid, form.get("target_so")))
    if not oid:
        return None
    so, cols = _z152_so_row(c, oid)
    if not so:
        return None
    proj_old = proj_old or {}
    eff = _z152_effective(proj_old, so)
    uid = user.get("id") if isinstance(user, dict) else None
    who = (vname_full(user) or user.get("name") or "") if isinstance(user, dict) else ""
    has_rp = bool(c.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='receipts_payment'").fetchone())
    changed = []
    for fk, sk, pk, lb in _Z152_SO_FIELDS:
        if sk not in cols:
            continue
        if fk == "customer_id":
            raw = (form.get("customer_id") or "").strip()
            if not raw.isdigit():
                nm = (form.get("customer_name") or "").strip()
                if not nm:
                    continue
                try:
                    _rc152 = _logi.resolve_customer_id(c, nm, prefer_id=so.get("customer_id") or proj_old.get("customer_id"))
                    raw = str((_rc152[0] if isinstance(_rc152, tuple) else _rc152) or "")
                except Exception:
                    raw = ""
                if not raw:
                    continue
            new = raw
        else:
            if fk not in form:
                continue
            new = form.get(fk)
        old_n, new_n = _z152_norm(fk, eff.get(fk)), _z152_norm(fk, new)
        if old_n == new_n:
            continue
        # z1191z154: 수주 1개 = 화면이 관리번호 값을 보여 준다 → 사람이 화면에서 바꾼 칸(관리번호 옛 값과 다른 칸)만 수주에 쓴다
        #   (수주 칸이 관리번호와 일부러 다르게 적혀 있으면 안 바꾼 칸으로 덮지 않음)
        if _single154 and _z152_norm(fk, proj_old.get(pk)) == new_n:
            continue
        if _single154 and sk != "@items" and so.get(sk) is not None and str(so.get(sk)).strip() != ""                 and _z152_norm(fk, so.get(sk)) != _z152_norm(fk, proj_old.get(pk)):
            # 수주 칸에 사람이 관리번호와 다르게 적어 둔 값 = 사람이 넣은 값 우선 → 덮지 않고 알림만(이력)
            changed.append((lb, _z152_show(c, fk, _z152_norm(fk, so.get(sk))), "수주 칸 값이 관리번호와 달라 그대로(수주 카드에서 고치세요)"))
            try:
                _logi.log_project_change(c, int(pid), uid, lb, _z152_show(c, fk, _z152_norm(fk, so.get(sk))), "(그대로)",
                                         note=f"z1191z154 수주 {so.get('order_no')} 칸이 관리번호와 달라 정보 수정이 덮지 않음 · {who}")
            except Exception as _e:
                print(f"[z1191z154] 이력 실패: {_e}")
            continue
        if fk == "currency":
            st = str(so.get("status") or "").upper()
            paid = has_rp and c.execute("SELECT 1 FROM receipts_payment WHERE order_id=? LIMIT 1", (int(oid),)).fetchone()
            if st in ("INVOICED", "PAID") or paid:
                changed.append((lb, old_n, old_n + " (계산서·입금 있어 그대로)"))
                continue
        if fk == "is_export":
            if not so.get("@n_items"):
                changed.append((lb, _z152_show(c, fk, old_n), "품목 줄이 없어 그대로(작업일정표에서 품목을 넣은 뒤 고쳐 주세요)"))
                continue
            c.execute("UPDATE order_items SET is_export=? WHERE order_id=?", (int(new_n or 0), int(oid)))
        elif fk == "shipment_form":
            if new_n not in _Z22_SF2SO:
                continue
            c.execute("UPDATE orders SET so_form=? WHERE id=?", (_Z22_SF2SO[new_n], int(oid)))
        else:
            val = (int(new_n) if new_n != "" else None) if fk == "customer_id" else (new_n if (new_n != "" or sk == "end_customer") else None)   # z1191z153: 2차 비움 = 
            c.execute(f"UPDATE orders SET {sk}=? WHERE id=?", (val, int(oid)))
        if fk == "currency":
            c.execute("UPDATE order_items SET currency=? WHERE order_id=? AND COALESCE(currency,'') NOT IN ('', ?)",
                      (new_n, int(oid), new_n))
        ov, nv = _z152_show(c, fk, old_n), _z152_show(c, fk, new_n)
        changed.append((lb, ov, nv))
        try:
            _logi.log_project_change(c, int(pid), uid, lb, ov, nv,
                                     note=(f"z1191z154 수주 {so.get('order_no')} 칸에 저장 · 정보 수정(수주 1개 — 관리번호와 같은 값) · {who}" if _single154
                                           else f"z1191z152 수주 {so.get('order_no')} 만 · 정보 수정(수주 2개 이상 — 다른 수주·대표값 그대로) · {who}"))
        except Exception as _e:
            print(f"[z1191z152] 이력 실패: {_e}")
    return changed


def _z152_form_view(c, pid, proj, so_no):
    """정보 수정 화면 — 수주 2개 이상이면 칸에 「고치는 수주」 값을 채우고, 수주마다 다른 값을 알림 글로."""
    if not _z152_multi(c, pid):
        return None
    oid = _quick_target_so_z117(c, pid, so_no)
    if not oid:
        return None
    so, _cols = _z152_so_row(c, oid)
    eff = _z152_effective(proj, so)
    notes = []
    for r in c.execute("SELECT id FROM orders WHERE project_id=? AND COALESCE(status,'')<>'CANCELLED' AND id<>? ORDER BY id",
                       (int(pid), int(oid))).fetchall():
        o, _x = _z152_so_row(c, r[0])
        e = _z152_effective(proj, o)
        diff = []
        if _z152_norm("customer_id", e.get("customer_id")) != _z152_norm("customer_id", eff.get("customer_id")):
            diff.append("고객사 " + str(e.get("customer_name") or "—"))
        if _z152_norm("currency", e.get("currency")) != _z152_norm("currency", eff.get("currency")):
            diff.append("통화 " + str(e.get("currency") or "—"))
        if _z152_norm("shipment_form", e.get("shipment_form")) != _z152_norm("shipment_form", eff.get("shipment_form")):
            diff.append("형태 " + str(_Z152_FORM_LB.get(_z152_norm("shipment_form", e.get("shipment_form")), e.get("shipment_form") or "—")))
        if _z152_norm("is_export", e.get("is_export")) != _z152_norm("is_export", eff.get("is_export")):
            diff.append("거래구분 " + ("수출" if _z152_norm("is_export", e.get("is_export")) == "1" else "내수"))
        if diff:
            notes.append({"no": o.get("order_no") or "", "diff": " · ".join(diff)})
    return {"so": so.get("order_no") or "", "eff": eff, "notes": notes}


def _price_tbd_col_z117(c):
    try:
        if "price_tbd" not in {r[1] for r in c.execute("PRAGMA table_info(orders)").fetchall()}:
            c.execute("ALTER TABLE orders ADD COLUMN price_tbd INTEGER DEFAULT 0")
        return True
    except Exception as _e:
        print(f"[z1191z117 price_tbd col] {_e}")
        return False


def _tbd_mark_z117(form, pid, maxoid):
    """⑤: 등록 화면 ☐ 단가 미정 → 이번에 새로 생긴 수주(id > 등록 전 최대)에 price_tbd=1."""
    try:
        if str(form.get("price_tbd") or "").strip() != "1" or maxoid is None or not pid:
            return
        with db_session() as c:
            if _price_tbd_col_z117(c):
                c.execute("UPDATE orders SET price_tbd=1 WHERE project_id=? AND id>?", (int(pid), int(maxoid)))
    except Exception as _e:
        print(f"[z1191z117 price_tbd mark] {_e}")


def _board_sum_z117(c, oid):
    """수주 하나의 (board_qty, 품목 줄 수량 합)."""
    try:
        _b = c.execute("SELECT board_qty FROM orders WHERE id=?", (oid,)).fetchone()
        _b = int(float((_b[0] if _b else 0) or 0))
    except Exception:
        _b = 0
    try:
        _s = c.execute("SELECT COALESCE(SUM(qty),0) FROM order_items WHERE order_id=?", (oid,)).fetchone()
        _s = int(round(float((_s[0] if _s else 0) or 0)))
    except Exception:
        _s = 0
    return _b, _s


def _board_follow_z117(c, oid, before):
    """⑦-1: 고치기 전 작업일정표 수량(board_qty)이 줄 합과 같았으면(맞아 있던 것) 새 줄 합으로 같이 바꾼다.
    처음부터 달랐던 것(일부러 다르게 적은 표시 수량)은 건드리지 않는다. 바뀌면 (전, 후) 를 돌려준다."""
    try:
        _b0, _s0 = before or (0, 0)
        if not _b0 or _b0 != _s0:
            return None
        _b1, _s1 = _board_sum_z117(c, oid)
        if _s1 > 0 and _s1 != _b0:
            c.execute("UPDATE orders SET board_qty=? WHERE id=?", (_s1, oid))
            return (_b0, _s1)
    except Exception as _e:
        print(f"[z1191z117 board_qty] {_e}")
    return None


def _so_qty_note_z89(so) -> str:
    """등록 때 적은 수량(board_qty)과 줄 합이 다르면 「(품목 줄 합 N)」 — 숫자를 숨기지 않는다."""
    so = so or {}
    _g = so.get if hasattr(so, "get") else (lambda k, d=None: getattr(so, k, d))
    try:
        _b = int(float(_g("board_qty") or 0))
    except (TypeError, ValueError):
        _b = 0
    _l = _so_qty_lines_z89(so)
    # z1191z123 (대표·안지연·이새롬 11-24 답 「① 맞음」): 품목 줄이 **두 줄 이상**(소켓+PCB 세트 · 여러 품목 한 세트)이면
    #   작업일정표 수량 = 세트 수가 기준 — 서로 다른 품목 수량을 더한 수와 비교하지 않는다(「(품목 줄 합 N)」·「↻ 맞추기」 안 띄움).
    #   한 줄(추가 발주 「N개」)일 때만 다르면 알림 — ③ 처럼 두 칸에 다른 값을 넣은 실수를 잡는다.
    try:
        _nl = len([_u for _u in (_g("units") or []) if str((_u.get("unit_status") if hasattr(_u, "get") else getattr(_u, "unit_status", "")) or "") != "취소"])
    except Exception:
        _nl = 0
    if _nl >= 2:
        return ""
    return ("(품목 줄 합 {:,})".format(_l)) if (_b > 0 and _l and _l != _b) else ""


def _so_qty_sum_z89(orders) -> dict:
    """프로젝트 (취소 아닌) 수주 수량 합 + 수주별 단가(금액 ÷ 수량)가 서로 다른가 — 오른쪽 곱셈 줄용."""
    _n, _ps = 0, set()
    for _o in (orders or []):
        _g = _o.get if hasattr(_o, "get") else (lambda k, d=None, _o=_o: getattr(_o, k, d))
        if str(_g("status") or "").upper() == "CANCELLED":
            continue
        _q = _so_qty_z89(_o)
        _n += _q
        try:
            _a = float(_g("total_amount") or 0)
        except (TypeError, ValueError):
            _a = 0.0
        if _a and _q:
            _ps.add(round(_a / _q, 2))
    return {"n": _n, "uneven": len(_ps) > 1}


def _qty_with_unit_z89(n, unit) -> str:
    """숫자 + 단위 — 한글 단위(대·개·식·건·대분)는 붙이고 그 밖(EA·SET)은 띄운다(수주 카드 원래 모양)."""
    _u = str(unit or "").strip()
    try:
        _n = "{:,}".format(int(float(n or 0)))
    except (TypeError, ValueError):
        _n = str(n or "")
    return ("%s%s" % (_n, _u)) if _u in ("대", "개", "식", "건", "대분") else ("%s %s" % (_n, _u)).strip()


def _so_unit_one_z89(orders) -> str:
    """프로젝트의 (취소 아닌) 수주 단위가 하나면 그 단위 · 섞였으면 빈칸(= 곱셈 문장을 쓰지 않는다) · 수주가 없으면 대(예전 그대로)."""
    _us = set()
    for _o in (orders or []):
        _st = (_o.get("status") if hasattr(_o, "get") else getattr(_o, "status", "")) or ""
        if str(_st).upper() == "CANCELLED":
            continue
        _us.add(_so_qty_unit_z89(_o))
    if not _us:
        return "대"
    return _us.pop() if len(_us) == 1 else ""


def _unit_price_uneven_z89(rows) -> bool:
    """줄마다 (금액 ÷ 수량) 이 다른가 — 오른쪽 「단가 (평균)」 표시용."""
    _ps = set()
    for _r in (rows or []):
        _g = _r.get if hasattr(_r, "get") else (lambda k, d=None, _r=_r: getattr(_r, k, d))
        try:
            _q = max(1, int(float(_g("qty") or 1)))
            _a = float(_g("amount") or 0)
        except (TypeError, ValueError):
            continue
        if _a:
            _ps.add(round(_a / _q, 2))
    return len(_ps) > 1


