# ─── z1191z24 (대표 2026-11-16 「묶어 발행만 보류하고 나머지는 진행」 · 안지연·이새롬 프로 답) ───
#   수주(호기) 세금계산서 최대 10장 — 「비율로 나누지 말고 ＋로 한 장씩 추가 · 합이 수주금액과 맞으면 끝」.
#   작업일정표엔 세금계산서 1칸(첫 장 + 「＋N장 · 합」) · 누르면 1~10차 입력 창(knk_tax_multi.html).
#   미수금 이름 = 1차·2차·3차… · 소모품은 1~3차 그대로(해당 없음) · 묶어 발행은 1~3차 그대로(보류).
#   ⚠ 차수 칸 이름은 이 함수들로만 만든다 — 1·2·3 을 손으로 늘어놓으면 한 곳이 빠져 매출·미수금에서 금액이 빠진다.
_TI_MAX = 10          # 수주(호기 order_items) 차수 1~10 — database.TAX_TIER_MAX 와 같아야 한다(시험이 본다)
_TI_MAX_CONS = 3      # 소모품(consumable_orders) 차수 1~3


def _ti_dcol(n):
    return "tax_invoice_date" if int(n) == 1 else "tax_invoice_date%d" % int(n)


def _ti_acol(n):
    return "tax_invoice_amt%d" % int(n)


_TI_DCOLS = tuple(_ti_dcol(_n) for _n in range(1, _TI_MAX + 1))
_TI_ACOLS = tuple(_ti_acol(_n) for _n in range(1, _TI_MAX + 1))


def _ti_mcol(n):
    """z1191z29 (대표 2026-11-16): 세금계산서 차수별 「설명」 칸 — 발행 때 참고할 내용 · 나중에 추적 · 작업일정표 찾기에 걸림."""
    return "tax_invoice_memo%d" % int(n)


_TI_MCOLS = tuple(_ti_mcol(_n) for _n in range(1, _TI_MAX + 1))
_TI_MEMO_MAXLEN = 300


def _ti_get(o, k):
    try:
        return o.get(k)
    except AttributeError:
        try:
            return o[k]
        except Exception:
            return None


def _ti_tiers(o, mx=_TI_MAX):
    """줄·호기 dict → [{n, d(발행일), a(금액 float|None)}] — 차수 1..mx(빈 차수 포함)."""
    out = []
    for n in range(1, int(mx) + 1):
        d = str(_ti_get(o, _ti_dcol(n)) or "").strip()[:10]
        a = _ti_get(o, _ti_acol(n))
        try:
            a = float(str(a).replace(",", "")) if a not in (None, "") else None
        except (TypeError, ValueError):
            a = None
        m = str(_ti_get(o, _ti_mcol(n)) or "").strip()   # z1191z29: 설명
        out.append({"n": n, "d": d, "a": a, "m": m})
    return out


def _ti_json(o, mx=_TI_MAX):
    """data-tis 속성 — [[발행일, 금액|null, 설명], …](차수 1..mx 순서). 입력 창(knkTaxMulti)이 읽는다. z1191z29: 설명 추가."""
    import json as _json_z24
    return _json_z24.dumps([[t["d"], t["a"], t["m"]] for t in _ti_tiers(o, mx)], ensure_ascii=False)


def _ti_bundle_json(ti_map, sig):
    """묶어 발행(1~3차 · z488) 차수 → {"1": {"id":…, "no":…}} — 입력 창에서 그 차수는 보기만."""
    import json as _json_z24
    out = {}
    if ti_map and sig:
        for n in (1, 2, 3):
            b = ti_map.get("%s|%d" % (sig, n))
            if b:
                out[str(n)] = {"id": _ti_get(b, "id"), "no": _ti_get(b, "no")}
    return _json_z24.dumps(out, ensure_ascii=False)


def _ti_cell_html(o, ccy="KRW", is_exp=False, mx=_TI_MAX, bundle=None):
    """세금계산서 1칸 표시 — 첫 장(발행일·금액) + 「＋N장 · 합 …」. 빈 칸은 「＋」.
    ⚠ knk_tax_multi.html 의 knkTaxMulti.cellHtml 과 같은 모양(저장 뒤 화면이 다시 그린다)."""
    from markupsafe import Markup, escape
    ts = [t for t in _ti_tiers(o, mx) if t["d"] or t["a"]]
    if not ts:
        return Markup("＋" + ('<span class="ti-mk" title="설명 있음 — 눌러서 보기">📝</span>'
                              if any(t["m"] for t in _ti_tiers(o, mx)) else ""))   # z1191z29
    f, h = ts[0], ""
    if is_exp:
        h += '<span class="ti-inv" title="수출 — 인보이스 발행 금액(세금계산서 아님)">INV</span>'
    if bundle and f["n"] == 1:
        h += '<span class="ti-bundle-chip">📄 #%s</span>' % escape(_ti_get(bundle, "no") or "")
        h += '<div class="ti-a">%s</div>' % (escape(_fmt_money(f["a"], ccy)) if f["a"] else "")
    else:
        if f["n"] != 1:
            h += '<span class="ti-n">%d차</span>' % f["n"]
        h += '<div class="ti-d">%s</div>' % escape(f["d"] or "–")
        h += '<div class="ti-a">%s</div>' % (escape(_fmt_money(f["a"], ccy)) if f["a"] else "")
    if len(ts) > 1:
        h += '<div class="ti-more">＋%d장 · <span class="ti-sum">합 %s</span></div>' % (len(ts) - 1, escape(_fmt_money(sum((t["a"] or 0) for t in ts), ccy)))
    if any(t["m"] for t in _ti_tiers(o, mx)):   # z1191z29: 설명이 있으면 📝(내용은 풍선 도움말·입력 창)
        h += '<span class="ti-mk" title="설명 있음 — 눌러서 보기">📝</span>'
    return Markup(h)


def _ti_title(o, ccy="KRW", mx=_TI_MAX):
    """칸 풍선 도움말 — 1차 2026-09-16 ₩371,200,000 / 2차 … / 합계 …"""
    ts = [t for t in _ti_tiers(o, mx) if t["d"] or t["a"] or t["m"]]   # z1191z29: 설명만 있는 차수도
    if not ts:
        return "세금계산서 — 눌러서 발행일·금액 입력(최대 %d장)" % mx
    ln = ["%d차 %s %s%s" % (t["n"], t["d"] or "–", _fmt_money(t["a"], ccy) if t["a"] else "",
                             (" — " + t["m"]) if t["m"] else "") for t in ts]
    ln.append("합계 %s — 눌러서 보기·추가" % _fmt_money(sum((t["a"] or 0) for t in ts), ccy))
    return "\n".join(ln)


def _so_tax_issued_z30(c, oid):
    """z1191z30 (대표 2026-11-16): 이 수주(SO)에 세금계산서가 발행됐나 — 호기(order_items) 1~10차 발행일·금액 중 하나라도
    (작업일정표·호기 표·묶어 발행 모두 호기 칸에 적힌다) · 옛 수주 칸(orders 1~3차)도 본다. 반환 = 발행 흔적 있는 호기 수(0 = 없음)."""
    oic = {r[1] for r in c.execute("PRAGMA table_info(order_items)").fetchall()}
    conds = (["COALESCE(TRIM(%s),'')<>''" % d for d in _TI_DCOLS if d in oic] +
             ["COALESCE(%s,0)<>0" % a for a in _TI_ACOLS if a in oic])
    n = 0
    if conds:
        n = c.execute("SELECT COUNT(*) FROM order_items WHERE order_id=? AND (" + " OR ".join(conds) + ")", (oid,)).fetchone()[0] or 0
    if not n:
        oc = {r[1] for r in c.execute("PRAGMA table_info(orders)").fetchall()}
        oconds = (["COALESCE(TRIM(%s),'')<>''" % d for d in _TI_DCOLS[:3] if d in oc] +
                  ["COALESCE(%s,0)<>0" % a for a in _TI_ACOLS[:3] if a in oc])
        if oconds and c.execute("SELECT 1 FROM orders WHERE id=? AND (" + " OR ".join(oconds) + ")", (oid,)).fetchone():
            n = 1
    return int(n)


_Z30_MSG = ("⚠ 세금계산서가 발행 완료된 항목입니다 (수주번호 %s).\n"
            "「전체 교체」를 하면 기존 부품 줄이 지워지면서 세금계산서 발행 기록(발행일·금액·설명)도 함께 지워지므로 할 수 없습니다.\n"
            "부품이 더 생겼으면 「부품 추가」로 올려 주세요.")


def _ti_so_issued_tpl(oid):
    """z1191z30: 상세 화면 「전체 교체」 단추 — 그릴 때 발행 여부(서버 저장 경로가 마지막에 한 번 더 막는다)."""
    try:
        with db_session() as c:
            return _so_tax_issued_z30(c, int(oid)) > 0
    except Exception:
        return False


tpl.env.globals["ti_so_issued"] = _ti_so_issued_tpl


def _z117_parts_checks_tpl(so, ccy="KRW"):
    """z1191z117 ④: 상세 화면 상품 표 — 줄 id → [문구…] (화면 줄 순서 = id 순)."""
    try:
        _us = sorted(list((so.get("units") if hasattr(so, "get") else getattr(so, "units", None)) or []), key=lambda x: (x.get("id") or 0))
        _fx = str(ccy or "KRW").upper() != "KRW"
        _r = _parts_checks_z117(_us, fx_line=lambda _x: _fx)
        return {_us[i].get("id"): m for i, m in _r.items()}
    except Exception as _e:
        print(f"[z1191z117 checks tpl] {_e}")
        return {}


