@app.post("/api/meeting/{mid:int}/summary")
async def api_meeting_summary_save(req: Request, mid: int):
    """z1139 (대표 지시 2026-10-05): 「📋 회의록 정리」 글을 **사람이 바로 고친다**.
    음성→글자가 낱말을 잘못 들었을 때, 전에는 원문을 고쳐 「🔄 다시 정리」로 AI 를 통째로 다시 돌려야 했고
    그러면 다른 문장 표현까지 바뀌었다. 여기서는 **고친 글을 그대로 저장**한다(AI 를 부르지 않는다).
    body: {summary: 고친 글, base_ts: 내가 보던 시각}
    권한은 회의록 고치기와 같다(작성자·이음 등록 담당·관리자/대표·그 회의 참석자 — z1133)."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    try:
        d = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "본문을 읽지 못했습니다."}, 400)
    if not isinstance(d, dict) or d.get("summary") is None:
        return JSONResponse({"ok": False, "error": "고친 정리 글이 없습니다."}, 400)
    summary = str(d.get("summary")).replace("\r\n", "\n").strip()[:20000]
    with db_session() as c:
        m = c.execute("SELECT * FROM meetings WHERE id=?", (mid,)).fetchone()
        if not m:
            return JSONResponse({"ok": False, "error": "없는 회의록입니다."}, 404)
        m = dict(m)
        if not _can_edit_meeting(u, m, c):
            return JSONResponse({"ok": False, "error": "수정 권한이 없습니다."}, 403)
        _conf, _cur = _edit_conflict(c, "meetings", mid, d.get("base_ts"))
        if _conf:
            return _conflict_resp(_cur)
        if summary == (m.get("summary") or "").strip():
            return JSONResponse({"ok": True, "updated_at": _row_ts(c, "meetings", mid), "changed": False})
        # z1183: 사람이 고친 표시 — 나중에 「🔄 다시 정리」·새 녹음 자동 정리가 **먼저 묻는다**
        c.execute("UPDATE meetings SET summary=?, summary_edited_at=datetime('now','localtime'), "
                  "updated_at=datetime('now','localtime') WHERE id=?",
                  (summary, mid))
        _bf = _mtg_body_fix(c, u, mid, d.get("fix"))   # z1202: 고친 낱말 → 회의 원문에도(같은 글자 전부)
        try:    # 누가 고쳤는지 남긴다(AI 정리와 사람이 고친 것을 나중에 가릴 수 있게)
            log_activity(c, u["id"], "meeting_summary_edit",
                         f"{u['name']} 회의록 정리 고침: {(m.get('title') or '')[:60]}",
                         team_id=u.get("team_id"))
        except Exception:
            pass
        new_ts = _row_ts(c, "meetings", mid)
        _mw = dict(c.execute("SELECT * FROM meetings WHERE id=?", (mid,)).fetchone())
    _tr_kick("mtg", mid, "edit")   # z1199
    return JSONResponse({"ok": True, "updated_at": new_ts, "changed": True,   # z1185: 판정도 함께
                         "body_written": _meeting_body_written(_mw), "has_minutes": _meeting_has_minutes(_mw),
                         **_mtg_body_fix_out(_bf)})   # z1202


def _mtg_ai_items(c, mid: int) -> dict:
    """z1183: 지금 AI 가 만든 결정·할 일(사람이 넣은 것·일일카드로 보낸 할 일은 빼고) — 이전 정리와 같이 보관한다."""
    decs = [{"who": r["who"] or "", "what": r["what"] or "", "due": r["due"] or ""} for r in c.execute(
        "SELECT who, what, due FROM meeting_decisions WHERE meeting_id=? AND source='ai' ORDER BY id", (mid,))]
    acts = [{"assignee_name": r["assignee_name"] or "", "assignee_user_id": r["assignee_user_id"],
             "task": r["task"] or "", "due_date": r["due_date"] or ""} for r in c.execute(
        "SELECT assignee_name, assignee_user_id, task, due_date FROM meeting_actions "
        "WHERE meeting_id=? AND source='ai' AND linked_task_id IS NULL ORDER BY id", (mid,))]
    return {"decisions": decs, "actions": acts}


@app.post("/api/meeting/{mid:int}/summary-restore")
async def api_meeting_summary_restore(req: Request, mid: int):
    """z1183 (대표 확인 「확인 + 이전 정리 보관」): 「↩ 이전 정리」 — 지금 정리와 이전 정리를 **맞바꾼다**
    (정리 글 + 그때의 AI 결정·할 일). 맞바꾸므로 한 번 더 누르면 돌아온다.
    사람이 넣은 결정·할 일 · 일일카드로 보낸 할 일은 그대로. 권한은 회의록 고치기와 같다."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    try:
        d = await req.json()
    except Exception:
        d = {}
    import json as _j83
    with db_session() as c:
        m = c.execute("SELECT * FROM meetings WHERE id=?", (mid,)).fetchone()
        if not m:
            return JSONResponse({"ok": False, "error": "없는 회의록입니다."}, 404)
        m = dict(m)
        if not _can_edit_meeting(u, m, c):
            return JSONResponse({"ok": False, "error": "수정 권한이 없습니다."}, 403)
        _conf, _cur = _edit_conflict(c, "meetings", mid, (d or {}).get("base_ts") if isinstance(d, dict) else None)
        if _conf:
            return _conflict_resp(_cur)
        prev = (m.get("summary_prev") or "").strip()
        if not prev:
            return JSONResponse({"ok": False, "error": "되돌릴 이전 정리가 없습니다."}, 400)
        try:
            prev_items = _j83.loads(m.get("summary_prev_items") or "{}") or {}
        except Exception:
            prev_items = {}
        cur_sum = (m.get("summary") or "").strip()
        cur_items = _mtg_ai_items(c, mid)
        c.execute("DELETE FROM meeting_decisions WHERE meeting_id=? AND source='ai'", (mid,))
        c.execute("DELETE FROM meeting_actions WHERE meeting_id=? AND source='ai' AND linked_task_id IS NULL", (mid,))
        for dec in (prev_items.get("decisions") or []):
            c.execute("INSERT INTO meeting_decisions(meeting_id, who, what, due, source) VALUES(?,?,?,?,'ai')",
                      (mid, dec.get("who") or "", dec.get("what") or "", dec.get("due") or ""))
        for act in (prev_items.get("actions") or []):
            c.execute("INSERT INTO meeting_actions(meeting_id, assignee_name, assignee_user_id, task, due_date, source) "
                      "VALUES(?,?,?,?,?,'ai')",
                      (mid, act.get("assignee_name") or "", act.get("assignee_user_id"),
                       act.get("task") or "", act.get("due_date") or ""))
        #  되돌린 정리 = 사람이 고른 것 → 다음 「다시 정리」도 먼저 묻는다
        c.execute("UPDATE meetings SET summary=?, summary_prev=?, summary_prev_items=?, "
                  "summary_prev_at=datetime('now','localtime'), summary_edited_at=datetime('now','localtime'), "
                  "updated_at=datetime('now','localtime') WHERE id=?",
                  (prev, cur_sum, _j83.dumps(cur_items, ensure_ascii=False), mid))
        try:
            log_activity(c, u["id"], "meeting_summary_restore",
                         f"{u['name']} 회의록 이전 정리로 맞바꿈: {(m.get('title') or '')[:60]}",
                         team_id=u.get("team_id"))
        except Exception:
            pass
        new_ts = _row_ts(c, "meetings", mid)
        _pv = c.execute("SELECT summary_prev_at FROM meetings WHERE id=?", (mid,)).fetchone()
        _mw = dict(c.execute("SELECT * FROM meetings WHERE id=?", (mid,)).fetchone())   # z1185
        decisions = [dict(r2) for r2 in c.execute(
            "SELECT * FROM meeting_decisions WHERE meeting_id=? ORDER BY id", (mid,))]
        actions = [dict(r2) for r2 in c.execute(
            "SELECT * FROM meeting_actions WHERE meeting_id=? ORDER BY id", (mid,))]
    _tr_kick("mtg", mid, "edit")   # z1199
    return JSONResponse({"ok": True, "summary": prev, "decisions": decisions, "actions": actions,
                         "updated_at": new_ts, "has_prev": bool(cur_sum),
                         "prev_at": ((_pv["summary_prev_at"] if _pv else "") or "")[:16] if cur_sum else "",
                         "body_written": _meeting_body_written(_mw), "has_minutes": _meeting_has_minutes(_mw)})


@app.delete("/api/meeting/{mid:int}")
async def api_meeting_delete(req: Request, mid: int):
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    with db_session() as c:
        m = c.execute("SELECT * FROM meetings WHERE id=?", (mid,)).fetchone()
        if not m:
            return JSONResponse({"ok": False, "error": "없는 회의록입니다."}, 404)
        m = dict(m)
        if not _can_delete_meeting(u, m):   # 등록 담당은 고치기만(삭제 X) — 2026-09-15 대표 결정 · 작성자·관리자만(09-21 대표 재확인)
            return JSONResponse({"ok": False, "error": "삭제 권한이 없습니다."}, 403)
    # z1122 (대표 결정 2026-09-21): 이음에서 온 회의면 이음 회의(🗓 달력·회의 알림 카드·모아보기 카드)도 함께 지운다.
    #   이음 회의까지 지우는 건 이음 등록자·관리자만 — 이음이 판단(아니면 회의록만 지우고 까닭을 알린다).
    #   🔴 이음에 닿지 못하면(연결 실패·키 거부·오류) 아무것도 지우지 않는다 — 한쪽만 지워진 채 남지 않게.
    #   이음에 삭제 입구가 아직 없으면(세션 10 배포 전) 회의록만 지우고 알린다.
    msg = {"linked": False}
    if m.get("msg_meeting_id"):
        from . import sso_client
        from starlette.concurrency import run_in_threadpool
        res = await run_in_threadpool(sso_client.delete_msg_meeting, m["msg_meeting_id"],
                                      u.get("employee_no") or "", mid)
        kind = res.get("kind") or "unreachable"
        if kind in ("unreachable", "refused"):
            return JSONResponse({"ok": False, "error": (res.get("error") or "이음에 연결하지 못했습니다.")
                                 + " 회의록을 지우지 않았습니다 — 잠시 뒤 다시 눌러 주세요."}, 503)
        msg = {"linked": True, "deleted": kind in ("deleted", "already"), "reason": kind}
        if res.get("notified"):   # z1123: 시작 전 회의면 이음이 참석자에게 「회의가 취소되었습니다」 — 몇 명에게 갔나(대표 결정 2026-09-22)
            msg["notified"] = res["notified"]
    with db_session() as c:
        # 자식(결정·할일·참석자)은 FK ON DELETE CASCADE 로 정리.
        # 단, 일일카드(tasks)로 연동된 것은 카드 자체를 지우지 않음(이미 독립 업무).
        # z1148: 권한 표는 CASCADE 에 맡기지 않고 확실히 지운다(남아 돌면 안 될 사람이 본다).
        c.execute("DELETE FROM meeting_viewers WHERE meeting_id=?", (mid,))
        c.execute("DELETE FROM meetings WHERE id=?", (mid,))
    # z1125 (대표 결정 2026-09-26): 그 회의의 녹음 파일도 함께 — 디스크가 느릴 수 있어 스레드에서
    #   🔴 이음과 무관한 회의는 위 블록을 건너뛰어 run_in_threadpool 이름이 없다 → 여기서 다시 불러온다
    from starlette.concurrency import run_in_threadpool
    await run_in_threadpool(_meeting_audio_purge, mid)
    try:   # z1122: 「🗓 회의 카드 모아보기」가 30초 저장본을 보여 주지 않게 — 지운 회의가 바로 빠진다
        with _MSG_CARDS_LOCK:
            _MSG_CARDS_CACHE.clear()
    except Exception as _e:
        print(f"[MSG-CARDS] 저장본 비우기 실패(무시): {_e}")
    return JSONResponse({"ok": True, "msg": msg})


# ── z1170: AI 정리 = 백그라운드 작업 + 상태 폴링 (대표 지시 2026-10-13 「회의록도 같은 방식으로」) ──
#  까닭: 받아쓰기는 2026-08-24(z1090)에 같은 까닭으로 이미 뒤로 보냈는데 **정리는 안 옮겼다.**
#        앞단(NAS 리버스프록시) 기다림 한도에 60초짜리가 있어, 정리가 길어지면 연결이 먼저 끊긴다.
#        그러면 화면은 비-JSON 쪽지를 받아 「AI 정리 실패」만 띄우는데 **서버는 성공해 저장까지 한다.**
#        실제로 음성 메모에서 그 일이 났다(z1168→z1169 · 원문 27,950자 → 정리 4,032자 · 실측).
#  해결: POST /extract 는 **시작만** 알리고, 화면이 GET /extract-status 를 물어본다(요청당 수 ms).
#  🔵 사람이 바로 알아야 할 것(로그인·AI 꺼짐·없는 회의·권한·내용 없음)은 **여기서 그대로** 답한다.
import threading as _mtg_thr
_MTG_SUM_JOBS: dict = {}      # {meeting_id: {"state": …, "error": str, "result": {...}}}
_MTG_SUM_LOCK = _mtg_thr.Lock()


def _ko_wd(d) -> str:
    """z1184: 'YYYY-MM-DD…' → ' (화)' — 정리 지시문에 날짜와 요일을 함께 준다(「다음 주 화요일」 같은 약속을
    실제 날짜로 바꿀 근거 · AI 가 요일을 잘못 세지 않게). 날짜가 아니면 빈 글."""
    try:
        return " (%s)" % "월화수목금토일"[datetime.strptime(str(d or "")[:10], "%Y-%m-%d").weekday()]
    except ValueError:
        return ""


def _mtg_sum_worker(mid: int):
    """회의 원문 → 결정사항·할 일·요약 (백그라운드 · z1170).
    🔴 하는 일은 옛 코드와 **글자 그대로 같다** — 바뀐 건 기다리는 방식뿐이다.
    z1183: 덮어쓰기 전 정리(글 + 그때의 AI 결정·할 일)를 「이전 정리」로 보관 · 새 AI 정리는 「사람이 고친 표시」를 지운다."""
    from . import ai_client
    err, payload = "", None
    try:
        with db_session() as c:
            r = c.execute("SELECT * FROM meetings WHERE id=?", (mid,)).fetchone()
            m = dict(r) if r else None
        if not m:
            err = "없는 회의록입니다."
        else:
            body = m.get("body") or ""
            # 회사 맥락 주입 — 참석자 이름 귀속·구조화 정리에 사용
            _ctx_parts = []
            if (m.get("title") or "").strip():
                _ctx_parts.append(f"회의 제목: {m['title'].strip()}")
            if (m.get("meeting_date") or "").strip():
                _ctx_parts.append(f"날짜: {m['meeting_date'].strip()}{_ko_wd(m['meeting_date'])}")   # z1184 — 요일도
            if (m.get("attendees_text") or "").strip():
                _ctx_parts.append(f"참석자: {m['attendees_text'].strip()}")
            ok, result = ai_client.ai_extract_meeting(body, context="\n".join(_ctx_parts))
            if not ok:
                err = result.get("error", "빅터AI 정리 실패")
            else:
                # z971: 제목이 비었거나 기본값('제목 없는 회의 …' — 녹음 자동생성)이면 AI 제안 제목으로
                #   교체. 사용자가 직접 지은 제목은 절대 건드리지 않는다.
                _cur_title = (m.get("title") or "").strip()
                _ai_title = (result.get("title") or "").strip()[:200]
                new_title = _ai_title if (_ai_title and (not _cur_title
                                          or _cur_title.startswith("제목 없는 회의"))) else ""
                with db_session() as c:
                    # z1183: 다시 정리 전 정리를 보관한다(정리 글 + 그때의 AI 결정·할 일) — 「↩ 이전 정리」로 맞바꿀 수 있게
                    _old = c.execute("SELECT summary FROM meetings WHERE id=?", (mid,)).fetchone()
                    _old_sum = ((_old["summary"] if _old else "") or "").strip()
                    _old_items = _mtg_ai_items(c, mid)
                    # AI 추출분만 교체(수기 추가분·이미 일일카드 연동분은 보존)
                    c.execute("DELETE FROM meeting_decisions WHERE meeting_id=? AND source='ai'", (mid,))
                    c.execute("DELETE FROM meeting_actions WHERE meeting_id=? AND source='ai' AND linked_task_id IS NULL", (mid,))
                    for dec in result["decisions"]:
                        c.execute(
                            "INSERT INTO meeting_decisions(meeting_id, who, what, due, source) VALUES(?,?,?,?,'ai')",
                            (mid, dec["who"], dec["what"], dec["due"]),
                        )
                    for act in result["actions"]:
                        c.execute(
                            """INSERT INTO meeting_actions(meeting_id, assignee_name, assignee_user_id, task, due_date, source)
                               VALUES(?,?,?,?,?,'ai')""",
                            (mid, act["assignee"], _meeting_match_user_id(c, act["assignee"]),
                             act["task"], act["due"]),
                        )
                    if result["summary"]:
                        if _old_sum and _old_sum != result["summary"].strip():
                            import json as _j83
                            c.execute("UPDATE meetings SET summary_prev=?, summary_prev_items=?, "
                                      "summary_prev_at=datetime('now','localtime') WHERE id=?",
                                      (_old_sum, _j83.dumps(_old_items, ensure_ascii=False), mid))
                        # 새 AI 정리 = 사람이 고친 것이 아니다 → 고친 표시를 지운다
                        c.execute("UPDATE meetings SET summary=?, summary_edited_at='', "
                                  "updated_at=datetime('now','localtime') WHERE id=?",
                                  (result["summary"], mid))
                    if new_title:
                        c.execute("UPDATE meetings SET title=?, updated_at=datetime('now','localtime') WHERE id=?",
                                  (new_title, mid))
                    new_ts = _row_ts(c, "meetings", mid)
                    _pv = c.execute("SELECT summary_prev, summary_prev_at FROM meetings WHERE id=?", (mid,)).fetchone()
                    prev_at = ((_pv["summary_prev_at"] or "")[:16]) if (_pv and (_pv["summary_prev"] or "").strip()) else ""
                    decisions = [dict(r2) for r2 in c.execute(
                        "SELECT * FROM meeting_decisions WHERE meeting_id=? ORDER BY id", (mid,))]
                    actions = [dict(r2) for r2 in c.execute(
                        "SELECT * FROM meeting_actions WHERE meeting_id=? ORDER BY id", (mid,))]
                payload = {"summary": result["summary"], "title": new_title,
                           "decisions": decisions, "actions": actions, "updated_at": new_ts,
                           "prev_at": prev_at}   # z1183 — 「↩ 이전 정리」 단추를 켤지
    except Exception as _e:
        err = err or f"빅터AI 정리에 실패했습니다: {_e}"
    with _MTG_SUM_LOCK:
        _MTG_SUM_JOBS[mid] = {"state": ("error" if err else "done"),
                              "error": err, "result": payload or {}}
    if not err:
        _tr_kick("mtg", mid, "sum")   # z1199: 정리 직후 — 베트남어 참석자가 있으면 뒤에서 번역


@app.post("/api/meeting/{mid:int}/extract")
async def api_meeting_extract(req: Request, mid: int):
    """회의 원문 → AI 결정사항·할 일·요약 **시작**(백그라운드 · z1170).
    결과는 GET /extract-status 로 본다. 자동 일일카드 등록 X."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    from . import ai_client
    if not ai_client.ai_available():
        return JSONResponse({"ok": False, "error": "빅터AI가 비활성 상태입니다(키 미설정). "
                             "결정사항·할 일은 직접 추가할 수 있습니다."}, 400)
    with db_session() as c:
        m = c.execute("SELECT * FROM meetings WHERE id=?", (mid,)).fetchone()
        if not m:
            return JSONResponse({"ok": False, "error": "없는 회의록입니다."}, 404)
        m = dict(m)
        if not _can_edit_meeting(u, m, c):
            return JSONResponse({"ok": False, "error": "권한이 없습니다."}, 403)
        body = m.get("body") or ""
        _edited = (m.get("summary_edited_at") or "").strip() if (m.get("summary") or "").strip() else ""
        _written = _meeting_body_written(m)   # z1185
        _why = "stt_short" if "[음성 변환]" in body else "memo"   # z1187: 안내 글을 가른다
    if not body.strip():
        return JSONResponse({"ok": False, "error": "회의 내용이 비어 있습니다. 내용을 먼저 입력·저장하세요."}, 400)
    # 🔴 z1185 (대표 2026-10-16 「녹음 원문 또는 수기 작성이 되지 않았을때는 …」): 원문이 이음 회의 메모(씨앗)뿐이면
    #    빅터AI 정리를 돌리지 않는다 — 회의 내용 없는 정리가 「정리 끝」이 되던 길(운영 3건). 판정은 _meeting_body_written 한 곳.
    #    🔵 200 으로 답한다(ok:false · no_minutes) — 안내는 정상 흐름이다(z1183: 409·400 은 콘솔에 빨간 오류).
    if not _written:
        # z1187: 받아쓴 글은 있는데 알아들을 말이 거의 없으면(헛말·시험 한두 마디) 그렇게 알린다(reason = stt_short)
        return JSONResponse({"ok": False, "no_minutes": True, "reason": _why,
                             "error": ("녹음에서 알아들을 수 있는 말이 거의 없습니다 — 녹음이 제대로 됐는지 확인해 다시 올리거나 "
                                       "「회의 내용」 칸에 적어 주세요." if _why == "stt_short" else
                                       "아직 회의 내용이 없습니다 — 녹음을 올리거나 「회의 내용」 칸에 먼저 적어 주세요"
                                       "(이음 회의 메모만으로는 정리하지 않습니다).")})
    # 🔴 z1183 (대표 확인 「확인 + 이전 정리 보관」): 사람이 고친 정리가 있으면 **먼저 묻는다** — 화면이 확인을 받아
    #    confirm_overwrite 로 다시 보낸다. 다시 정리하면 지금 정리는 「이전 정리」로 보관된다(_mtg_sum_worker).
    #    전에는 같은 화면을 띄운 채 고쳤을 때만 화면이 물었다 → 나중에 누가 누르면 **확인 없이 덮어썼다**.
    #    🔵 200 으로 답한다(ok:false · need_confirm) — 묻기는 정상 흐름이다. 409 로 답하면 브라우저가 콘솔에 빨간 오류를 찍는다.
    try:
        _d = await req.json()
    except Exception:
        _d = {}
    if _edited and not (isinstance(_d, dict) and _d.get("confirm_overwrite")):
        return JSONResponse({"ok": False, "need_confirm": True, "edited_at": _edited[:16],
                             "error": "사람이 고친 정리가 있습니다 — 다시 정리하면 새 정리로 바뀝니다"
                                      "(고친 정리는 「이전 정리」로 보관되어 되돌릴 수 있습니다)."})
    import time as _time
    with _MTG_SUM_LOCK:
        if (_MTG_SUM_JOBS.get(mid) or {}).get("state") == "running":
            return JSONResponse({"ok": True, "already": True})
        # z1177: 시작 시각 — 다시 연 화면·다른 창이 「몇 초째」를 이어 보여 준다(/extract-status 의 elapsed)
        _MTG_SUM_JOBS[mid] = {"state": "running", "error": "", "result": {}, "t0": _time.time()}
    _mtg_thr.Thread(target=_mtg_sum_worker, args=(mid,), daemon=True).start()
    return JSONResponse({"ok": True, "started": True})


@app.get("/api/meeting/{mid:int}/extract-status")
async def api_meeting_extract_status(req: Request, mid: int):
    """AI 정리가 끝났나 (z1170). state = idle | running | done | error
    done 이면 옛 POST 가 돌려주던 것(summary·title·decisions·actions·updated_at)을 그대로 담는다."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    with db_session() as c:
        m = c.execute("SELECT * FROM meetings WHERE id=?", (mid,)).fetchone()
        if not m:
            return JSONResponse({"ok": False, "error": "없는 회의록입니다."}, 404)
        if not _can_edit_meeting(u, dict(m), c):
            return JSONResponse({"ok": False, "error": "권한이 없습니다."}, 403)
    with _MTG_SUM_LOCK:
        j = dict(_MTG_SUM_JOBS.get(mid) or {"state": "idle", "error": "", "result": {}})
    out = {"ok": True, "state": j.get("state"), "error": j.get("error") or ""}
    if j.get("state") == "done":
        out.update(j.get("result") or {})
    # z1177: 돌고 있으면 몇 초째인지(서버 시계로) — 화면의 ⏱ 시계가 다시 열어도·다른 창에서도 맞는다
    if j.get("state") == "running" and j.get("t0"):
        import time as _time
        out["elapsed"] = max(0, int(_time.time() - j["t0"]))
    return JSONResponse(out)


