@app.post("/api/meeting/{mid:int}/action/{aid:int}/to-daily")
async def api_meeting_action_to_daily(req: Request, mid: int, aid: int):
    """할 일 1-클릭 → 일일업무카드(tasks) 등록. 중복 등록 방지(linked_task_id).
    담당자가 단일후보로 연결돼 있으면 그 사람 카드로, 아니면 등록자 본인 카드로."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    with db_session() as c:
        m = c.execute("SELECT * FROM meetings WHERE id=?", (mid,)).fetchone()
        if not m:
            return JSONResponse({"ok": False, "error": "없는 회의록입니다."}, 404)
        m = dict(m)
        if not _can_view_meeting(c, u, m):
            return JSONResponse({"ok": False, "error": "권한이 없습니다."}, 403)
        a = c.execute("SELECT * FROM meeting_actions WHERE id=? AND meeting_id=?", (aid, mid)).fetchone()
        if not a:
            return JSONResponse({"ok": False, "error": "없는 할 일입니다."}, 404)
        a = dict(a)
        if a.get("linked_task_id"):
            return JSONResponse({"ok": False, "error": "이미 일일카드로 등록된 할 일입니다.",
                                 "task_id": a["linked_task_id"]}, 409)
        target_uid = a.get("assignee_user_id") or u["id"]
        title = (a.get("task") or "")[:200]
        note = f"[회의록] {m['title']} ({m['meeting_date']})"
        if a.get("assignee_name"):
            note += f" · 담당: {a['assignee_name']}"
        cur = c.execute(
            """INSERT INTO tasks(user_id, work_date, title, category, status, hours, notes, due_date)
               VALUES(?,?,?,?,?,?,?,?)""",
            (target_uid, date.today().isoformat(), title, "회의", "진행중", 0,
             note, _meeting_due_or_none(a.get("due_date"))),
        )
        tid = cur.lastrowid
        c.execute("UPDATE meeting_actions SET linked_task_id=?, status='linked' WHERE id=?", (tid, aid))
        try:
            log_activity(c, u["id"], "meeting_to_daily",
                         f"회의 할 일→일일카드: {title[:50]}",
                         task_id=tid, team_id=u.get("team_id"))
        except Exception:
            pass
    return JSONResponse({"ok": True, "task_id": tid, "assigned_to": target_uid})


def _meeting_audio_purge(mid: int) -> dict:
    """회의록을 지울 때 그 회의의 녹음 파일도 함께 지운다 (z1125 · 대표 결정 2026-09-26 「지울때 함께 지워」).
    전에는 DB 줄만 지우고 `meeting_audio/meeting_<번호>/` 는 서버에 남았다(화면에선 안 보이지만 파일은 남음).
    🔴 그 회의 폴더 하나만 — 폴더 이름·경로를 다시 확인해 `meeting_audio` 밖이나 `_share`(아직 어느 회의인지 정해지지 않은 파일)는 건드리지 않는다.
    🔴 지우다 실패해도 회의록 삭제는 이미 끝났다 → 실패는 기록만 남기고 넘어간다(삭제를 되돌리지 않는다).
    디스크가 느릴 수 있어(NAS) 부르는 쪽에서 스레드로 돌린다."""
    out = {"files": 0, "bytes": 0}
    try:
        mid = int(mid)
        base = os.path.abspath("meeting_audio")
        d = os.path.abspath(os.path.join("meeting_audio", f"meeting_{mid}"))
        if os.path.basename(d) != f"meeting_{mid}" or os.path.dirname(d) != base:
            print(f"[MEETING-AUDIO] 지우지 않음(폴더 자리가 이상): {d}")
            return out
        if not os.path.isdir(d):
            return out
        for root, _dirs, files in os.walk(d):
            for fn in files:
                out["files"] += 1
                try:
                    out["bytes"] += os.path.getsize(os.path.join(root, fn))
                except OSError:
                    pass
        import shutil as _sh
        _sh.rmtree(d)
        print(f"[MEETING-AUDIO] 회의 {mid} 녹음 파일 {out['files']}개({out['bytes'] // 1024}KB) 함께 지움")
    except Exception as _e:
        print(f"[MEETING-AUDIO] 녹음 파일 지우기 실패(회의록은 지워짐): {type(_e).__name__}: {str(_e)[:160]}")
    return out


# ── 모드 B: 음성 녹음 → Whisper 음성→글자 (z412+ ) ──────────────────────────
#  음성은 민감(제약2) → 정적 마운트(/uploads) 가 아니라 'meeting_audio/'(비공개 폴더)에
#  저장하고, 열람은 권한 게이트 GET 라우트로만 서빙. Whisper 는 OpenAI 키 필요(없으면 graceful).
_MEETING_AUDIO_EXT = (".webm", ".m4a", ".mp4", ".mp3", ".wav", ".ogg", ".oga",
                      ".aac", ".3gp", ".mpeg", ".mpga", ".caf")
_MEETING_AUDIO_MIME = {
    ".webm": "audio/webm", ".m4a": "audio/mp4", ".mp4": "audio/mp4",
    ".mp3": "audio/mpeg", ".mpeg": "audio/mpeg", ".mpga": "audio/mpeg",
    ".wav": "audio/wav", ".ogg": "audio/ogg", ".oga": "audio/ogg",
    ".aac": "audio/aac", ".3gp": "audio/3gpp", ".caf": "audio/x-caf",
}
# 2026-09-17 대표 지시: 음성 파일 올리기 60MB → 300MB (긴 폰 녹음). 글자 변환은 _stt_worker 가 줄이고 _STT_SEG_SEC 마다 나눠서.
#   ⭐ 한도 숫자는 여기 한 곳 — 화면(meeting_form.html)은 window.__MTG.audio_max_mb 로 같은 값을 받는다.
_MEETING_AUDIO_MAX_MB = 300
_MEETING_AUDIO_BLOCK = 1024 * 1024
tpl.env.globals["MEETING_AUDIO_MAX_MB"] = _MEETING_AUDIO_MAX_MB


def _meeting_audio_too_big(n: int, exact: bool = True) -> str:
    return (f"음성은 {_MEETING_AUDIO_MAX_MB}MB 이하만 올릴 수 있습니다"
            + (f"(이 파일 {n // 1024 // 1024}MB)." if exact else f"(이 파일은 {_MEETING_AUDIO_MAX_MB}MB 를 넘습니다)."))


def _meeting_audio_save(src, dest: str, limit: int) -> int:
    """올린 음성(서버가 받아 둔 임시 파일)을 1MB 씩 dest 로 옮겨 적는다 — 300MB 를 메모리에 통째로 올리지 않게.
    반환 = 옮긴 바이트 수. limit 을 넘거나 100바이트 미만이면 옮기던 조각 파일을 지우고 그 수를 돌려준다(호출부가 안내)."""
    part = dest + ".part"
    n = 0
    try:
        try:
            src.seek(0)
        except Exception:
            pass
        with open(part, "wb") as out:
            while True:
                b = src.read(_MEETING_AUDIO_BLOCK)
                if not b:
                    break
                n += len(b)
                if n > limit:
                    break
                out.write(b)
        if n > limit or n < 100:
            os.remove(part)
            return n
        os.replace(part, dest)
        return n
    except Exception:
        try:
            os.remove(part)
        except Exception:
            pass
        raise


@app.post("/api/meeting/{mid:int}/audio")
async def api_meeting_audio_upload(req: Request, mid: int, file: UploadFile = File(...)):
    """휴대폰/브라우저 녹음 업로드. meeting_audio/meeting_{id}/ 에 저장 + mode='B'."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    with db_session() as c:
        m = c.execute("SELECT * FROM meetings WHERE id=?", (mid,)).fetchone()
        if not m:
            return JSONResponse({"ok": False, "error": "없는 회의록입니다."}, 404)
        m = dict(m)
        if not _can_edit_meeting(u, m, c):
            return JSONResponse({"ok": False, "error": "권한이 없습니다."}, 403)
    orig = file.filename or "rec.webm"
    ext = os.path.splitext(orig)[1].lower() or ".webm"
    if ext not in _MEETING_AUDIO_EXT:
        return JSONResponse({"ok": False, "error": f"지원하지 않는 음성 형식({ext})."}, 400)
    _lim = _MEETING_AUDIO_MAX_MB * 1024 * 1024
    _sz = getattr(file, "size", None)          # 서버가 이미 임시 파일로 다 받아 둔 크기(있으면 옮기기 전에 거른다)
    if _sz is not None and _sz > _lim:
        return JSONResponse({"ok": False, "error": _meeting_audio_too_big(_sz)}, 400)
    if _sz is not None and _sz < 100:
        return JSONResponse({"ok": False, "error": "빈/손상 음성 파일입니다."}, 400)
    import time as _time
    from starlette.concurrency import run_in_threadpool
    audio_dir = os.path.join("meeting_audio", f"meeting_{mid}")
    os.makedirs(audio_dir, exist_ok=True)
    ts = int(_time.time())
    disk_path = os.path.join(audio_dir, f"rec_{ts}{ext}")
    _n = await run_in_threadpool(_meeting_audio_save, file.file, disk_path, _lim)   # 일꾼 1개 — 디스크 쓰기는 스레드에서
    if _n > _lim:
        return JSONResponse({"ok": False, "error": _meeting_audio_too_big(_n, exact=False)}, 400)
    if _n < 100:
        return JSONResponse({"ok": False, "error": "빈/손상 음성 파일입니다."}, 400)
    rel = disk_path.replace("\\", "/")
    old = (m.get("audio_path") or "").strip()
    with db_session() as c:
        c.execute("UPDATE meetings SET audio_path=?, mode='B', updated_at=datetime('now','localtime') WHERE id=?",
                  (rel, mid))
        _mtg_audio_uploaded(c, mid, u.get("id"))   # z1197: 작성자 기본 = 녹음 올린 사람
        _new_ts = _row_ts(c, "meetings", mid)
    # z1092 (대표 지시 2026-09-07): 이전 녹음 파일을 지우지 않는다(보존).
    #   전엔 '단일 음성 정책'으로 새 녹음 업로드 시 앞 파일을 삭제했다 → 회의를 이어서
    #   녹음하면 1차 파일이 사라져 다시 변환·확인할 방법이 없었다(회의 17 실사고).
    #   재생·변환은 최신 것을 쓰되 파일 자체는 남겨 증거와 재변환 여지를 지킨다.
    _prev_audio_kept = old  # 보존됨(삭제하지 않음)
    _rec_add_pending(mid, rel)   # z1113: 올린 파일도 '아직 글자로 안 바꾼 녹음'에 — 끊긴 조각과 차례로 변환
    return JSONResponse({"ok": True, "audio_url": f"/api/meeting/{mid}/audio?v={ts}",
                         "size_kb": _n // 1024, "updated_at": _new_ts})


# ── 📤 휴대폰 녹음기 「공유」 → 회의록 (z1117 · 대표 지시 2026-09-20) ──────────────
#   대표 지시: 「녹음기로 녹음한 것이 자동으로 요약되게.」
#   평소엔 녹음기가 파일을 회의록 화면으로 직접 돌려준다(z1115 · input capture) → 그대로 자동.
#   회의가 길어 크롬이 그 화면을 버리면 돌려줄 곳이 없어진다 → 「공유」로 들어오는 두 번째 길.
#   받은 파일은 잠깐 `meeting_audio/_share/` 에 두었다가, 어느 회의록인지 정해지면 그 회의 폴더로 옮긴다.
_SHARE_DIR = os.path.join("meeting_audio", "_share")
_SHARE_OK = set("abcdefghijklmnopqrstuvwxyz0123456789_")


def _share_sweep(hours: int = 24):
    """붙이지 않고 버려진 공유 파일 치우기(하루 지난 것)."""
    import time as _t
    try:
        cut = _t.time() - hours * 3600
        for fn in os.listdir(_SHARE_DIR):
            p = os.path.join(_SHARE_DIR, fn)
            try:
                if os.path.isfile(p) and os.path.getmtime(p) < cut:
                    os.remove(p)
            except OSError:
                pass
    except OSError:
        pass


def _share_find(token: str, uid: int) -> str:
    """받은 파일 찾기 — 표는 올린 사람 번호를 품고 있어 남의 것은 집히지 않는다."""
    token = (token or "").strip()
    if not token or len(token) > 64 or not set(token) <= _SHARE_OK:
        return ""
    if not token.startswith("s_%d_" % int(uid)):
        return ""
    try:
        for fn in os.listdir(_SHARE_DIR):
            if fn.rsplit(".", 1)[0] == token:
                return os.path.join(_SHARE_DIR, fn).replace("\\", "/")
    except OSError:
        pass
    return ""


def _share_attach(mid: int, path: str, uid: int = 0) -> int:
    """받은 파일을 그 회의 폴더로 옮기고 '아직 글자로 안 바꾼 녹음'에 넣는다. 크기(바이트) 반환."""
    import time as _time
    import shutil as _sh
    ext = os.path.splitext(path)[1].lower() or ".m4a"
    audio_dir = os.path.join("meeting_audio", "meeting_%d" % mid)
    os.makedirs(audio_dir, exist_ok=True)
    rel = os.path.join(audio_dir, "rec_%d%s" % (int(_time.time()), ext)).replace("\\", "/")
    _sh.move(path, rel)
    n = os.path.getsize(rel)
    with db_session() as c:
        c.execute("UPDATE meetings SET audio_path=?, mode='B', updated_at=datetime('now','localtime') WHERE id=?",
                  (rel, mid))
        _mtg_audio_uploaded(c, mid, uid)   # z1197: 작성자 기본 = 녹음 올린(공유로 붙인) 사람
    _rec_add_pending(mid, rel)   # z1113: 끊긴 조각과 차례로 변환돼 본문에 이어 붙는다
    return n


_SHARE_LOGIN_HTML = """<!DOCTYPE html><html lang="ko"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0"><title>로그인 필요 · KNK HAIST WORKS</title>
<style>body{font-family:-apple-system,BlinkMacSystemFont,'Malgun Gothic',sans-serif;margin:0;padding:32px 22px;
color:#1f2328;line-height:1.8}h1{font-size:19px;margin:0 0 12px}a{display:inline-block;margin-top:18px;
background:#A5282C;color:#fff;text-decoration:none;padding:14px 20px;border-radius:12px;font-weight:800}</style>
</head><body><h1>🔒 로그인이 풀려 있습니다</h1>
<p>아래 단추로 WORKS 를 연 뒤 로그인하고, <b>녹음기에서 한 번 더 공유</b>해 주세요.<br>
<b>녹음 파일은 휴대폰에 그대로 있습니다.</b></p>
<a href="/app">WORKS 열기</a></body></html>"""


@app.post("/share/audio", response_class=HTMLResponse)
async def share_audio_receive(req: Request):
    """휴대폰 녹음기 등에서 「공유 → KNK Eum WORKS」로 보낸 음성 받기(설치된 앱의 공유 대상)."""
    u = get_user(req)
    if not u:
        return HTMLResponse(_SHARE_LOGIN_HTML, status_code=401)
    form = await req.form()
    f = form.get("audio")
    if f is None or not hasattr(f, "filename"):
        f = None
        for _v in form.values():                       # 이름이 다른 기기도 있다 — 파일이면 받는다
            if hasattr(_v, "filename") and getattr(_v, "filename", ""):
                f = _v
                break
    if f is None or not getattr(f, "filename", ""):
        return ctx(req, "share_audio.html", user=u, share=None, meetings=[], ok_ids=[], err="nofile", errmsg="")
    ext = os.path.splitext(f.filename)[1].lower()
    if ext not in _MEETING_AUDIO_EXT:
        return ctx(req, "share_audio.html", user=u, share=None, meetings=[], ok_ids=[],
                   err="ext", errmsg="지원하지 않는 음성 형식(%s)입니다." % (ext or "알 수 없음"))
    _lim = _MEETING_AUDIO_MAX_MB * 1024 * 1024
    _sz = getattr(f, "size", None)
    if _sz is not None and _sz > _lim:
        return ctx(req, "share_audio.html", user=u, share=None, meetings=[], ok_ids=[],
                   err="toobig", errmsg=_meeting_audio_too_big(_sz))
    import time as _time
    import binascii as _bl
    from starlette.concurrency import run_in_threadpool
    os.makedirs(_SHARE_DIR, exist_ok=True)
    _share_sweep()
    token = "s_%d_%d_%s" % (u["id"], int(_time.time()), _bl.hexlify(os.urandom(4)).decode())
    path = os.path.join(_SHARE_DIR, token + ext)
    n = await run_in_threadpool(_meeting_audio_save, f.file, path, _lim)
    if n > _lim:
        try:
            os.remove(path)
        except OSError:
            pass
        return ctx(req, "share_audio.html", user=u, share=None, meetings=[], ok_ids=[],
                   err="toobig", errmsg=_meeting_audio_too_big(n, exact=False))
    if n < 100:
        try:
            os.remove(path)
        except OSError:
            pass
        return ctx(req, "share_audio.html", user=u, share=None, meetings=[], ok_ids=[],
                   err="nofile", errmsg="")
    # 붙일 수 있는 최근 회의(내가 고칠 수 있는 것만) — 표시가 없을 때 고르게
    with db_session() as c:
        rows = c.execute("""SELECT * FROM meetings
                            ORDER BY meeting_date DESC, id DESC LIMIT 60""").fetchall()
        mine = [dict(r) for r in rows if _can_edit_meeting(u, dict(r), c)][:12]
    print(f"[SHARE-AUDIO] uid={u['id']} {f.filename} {n // 1024}KB → {token}", flush=True)
    return ctx(req, "share_audio.html", user=u,
               share={"token": token, "name": f.filename[:80], "mb": round(n / 1048576, 1)},
               meetings=[{"id": x["id"], "title": x["title"], "meeting_date": x["meeting_date"]} for x in mine],
               ok_ids=[x["id"] for x in mine], err="", errmsg="")


@app.post("/api/meeting/{mid:int}/attach-share")
async def api_meeting_attach_share(req: Request, mid: int):
    """공유로 받은 음성을 이 회의록에 붙인다(그 뒤 화면이 자동 정리를 잇는다)."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "error": "로그인 필요"}, 401)
    d = await req.json()
    with db_session() as c:
        r = c.execute("SELECT * FROM meetings WHERE id=?", (mid,)).fetchone()
        if not r:
            return JSONResponse({"ok": False, "error": "없는 회의록입니다."}, 404)
        if not _can_edit_meeting(u, dict(r), c):
            return JSONResponse({"ok": False, "error": "권한이 없습니다."}, 403)
    path = _share_find(d.get("token") or "", u["id"])
    if not path or not os.path.exists(path):
        return JSONResponse({"ok": False, "error": "받은 녹음을 찾지 못했습니다 — 녹음기에서 다시 공유해 주세요."}, 404)
    from starlette.concurrency import run_in_threadpool
    n = await run_in_threadpool(_share_attach, mid, path, u["id"])
    print(f"[SHARE-AUDIO] uid={u['id']} → 회의 {mid} 붙임 {n // 1024}KB", flush=True)
    return JSONResponse({"ok": True, "id": mid, "size_kb": n // 1024})


@app.post("/api/meeting/share-new")
async def api_meeting_share_new(req: Request):
    """공유로 받은 음성으로 새 회의록을 만들고 붙인다(제목은 AI 정리 때 자동으로 지어진다)."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "error": "로그인 필요"}, 401)
