@app.get("/api/meeting/{mid:int}/audio")
async def api_meeting_audio_get(req: Request, mid: int):
    """녹음 재생 — 권한 게이트(정적 노출 금지). _can_view_meeting 통과자만."""
    u = get_user(req)
