@app.post("/api/voice-note/{nid:int}/transcribe")
async def api_voice_note_transcribe(req: Request, nid: int):
    """음성 → 글자 (백그라운드 시작). 상태는 /stt-status 로 본다."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    from . import ai_client
    if not ai_client.transcribe_available():
        return JSONResponse({"ok": False, "error": "음성→글자는 OpenAI 키가 필요합니다(현재 미설정/무효). "
                                                   "관리자 → AI 설정에서 등록하면 즉시 동작합니다."}, 400)
    try:                                   # z1165: 화면이 고른 「쓰는 말」(없으면 자동 감지)
        _d = await req.json()
    except Exception:
        _d = {}
    lang = _d.get("lang") if _d.get("lang") in ("ko", "vi", "en", "mix") else ""   # z1188: mix = 한국어+베트남어 섞임
    with db_session() as c:
        n = _vn_row(c, nid)
    if not _vn_mine(u, n):
        return JSONResponse({"ok": False, "error": _vnv.server_text("없거나 볼 수 없는 메모입니다.", (u or {}).get("lang"))}, 404)
    disk = (n.get("audio_path") or "").strip()
    if not disk or not os.path.exists(disk):
        return JSONResponse({"ok": False, "error": _vnv.server_text("녹음 파일이 없습니다. 먼저 올려 주세요.", (u or {}).get("lang"))}, 400)
    with _VN_LOCK:
        if (_VN_JOBS.get(nid) or {}).get("state") == "running":
            return JSONResponse({"ok": True, "already": True})
        _VN_JOBS[nid] = {"state": "running", "progress": "", "error": "", "warn": ""}
    _rep = bool(isinstance(_d, dict) and _d.get("replace") is True)   # z1195 — 「📁 녹음 다시 올리기」면 원문을 바꾼다
    _stt_thr.Thread(target=_vn_worker, args=(nid, disk, lang or "", _rep), daemon=True).start()
    return JSONResponse({"ok": True, "started": True})


