def _vn_sum_worker(nid: int):
    """🎤 받아쓴 원문 → 요점·할 일 정리 (백그라운드 · z1169).
    🔴 원문(body)은 바꾸지 않는다. 🔴 개인 메모라 활동 기록에 남기지 않는다."""
    from . import ai_client
    err = ""
    try:
        with db_session() as c:
            n = _vn_row(c, nid)
        body = ((n or {}).get("body") or "").strip()
        if not body:
            err = "정리할 내용이 없습니다."
        else:
            # z1184: [메모 정보] — 메모 날짜(요일)를 함께 준다(「오늘」「다음 달 10일」 같은 기한을 실제 날짜로 바꿀 근거)
            _vd = ((n or {}).get("created_at") or "")[:10]
            _ctx = (f"메모 날짜: {_vd}{_ko_wd(_vd)}" if _vd else "")
            with db_session() as c:   # z1200: 메모 주인 화면 언어가 베트남어면 처음부터 베트남어로 정리(한국어 지시문은 그대로)
                _own = c.execute("SELECT lang FROM users WHERE id=?", ((n or {}).get("owner_id"),)).fetchone()
            if _own and _own["lang"] == "vi":
                ok, r = _vnv.extract(body, context=_ctx)
            else:
                ok, r = ai_client.ai_extract_note(body, context=_ctx)
            if not ok:
                err = r.get("error") or "정리 실패"
            else:
                summary = (r.get("summary") or "").strip()[:20000]
                title = ((n or {}).get("title") or "").strip()
                #  사람이 지은 제목은 건드리지 않는다
                new_title = title or (r.get("title") or "").strip()[:200]
                with db_session() as c:
                    # z1183: 덮어쓰기 전 정리를 보관한다 — 「↩ 이전 정리」로 맞바꿀 수 있게 · 새 AI 정리 = 고친 표시 지움
                    _old = c.execute("SELECT summary FROM voice_notes WHERE id=?", (nid,)).fetchone()
                    _old_sum = ((_old["summary"] if _old else "") or "").strip()
                    if _old_sum and _old_sum != summary:
                        c.execute("UPDATE voice_notes SET summary_prev=?, summary_prev_at=datetime('now','localtime') "
                                  "WHERE id=?", (_old_sum, nid))
                    c.execute("UPDATE voice_notes SET summary=?, title=?, summary_edited_at='', "
                              "updated_at=datetime('now','localtime') WHERE id=?",
                              (summary, new_title, nid))
    except Exception as _e:
        err = err or f"정리하지 못했습니다: {_e}"
    with _VN_LOCK:
        _VN_SUM_JOBS[nid] = {"state": ("error" if err else "done"), "error": err}


@app.post("/api/voice-note/{nid:int}/extract")
async def api_voice_note_extract(req: Request, nid: int):
    """받아쓴 원문 → 요점·할 일 정리 **시작**(백그라운드). 상태는 /extract-status 로 본다.

    🔴 z1169 (대표 신고 2026-10-13 「다시 정리 눌렀는데 정리하지 못했습니다」):
       전에는 이 한 요청 안에서 AI 를 다 기다렸다. 그런데 **앞단 웹서버의 기다림 한도가 60초**라,
       z1168 로 정리가 길어지자(원문 27,950자 → 정리 4,032자) **60초를 넘겨 앞단이 먼저 끊었다.**
       서버는 끝까지 해서 **저장까지 됐는데** 화면에는 「정리하지 못했습니다」가 떴다(실측).
       → 받아쓰기와 **같은 방식**으로 바꾼다: 바로 시작만 알리고, 화면이 상태를 물어 본다.
    🔵 사람이 바로 알아야 할 것(로그인·AI 꺼짐·남의 메모·내용 없음)은 **여기서 그대로** 답한다."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    from . import ai_client
    if not ai_client.ai_available():
        return JSONResponse({"ok": False, "error": _vnv.server_text("빅터AI가 비활성 상태입니다(키 미설정).", (u or {}).get("lang"))}, 400)
    with db_session() as c:
        n = _vn_row(c, nid)
    if not _vn_mine(u, n):
        return JSONResponse({"ok": False, "error": _vnv.server_text("없거나 볼 수 없는 메모입니다.", (u or {}).get("lang"))}, 404)
    body = (n.get("body") or "").strip()
    if not body:
        return JSONResponse({"ok": False, "error": _vnv.server_text("정리할 내용이 없습니다. 녹음을 먼저 올리세요.", (u or {}).get("lang"))}, 400)
    # 🔴 z1183: 사람이 고친 정리가 있으면 먼저 묻는다(회의록과 같다 · 200 + need_confirm) — 다시 정리하면 지금 정리는
    #    「이전 정리」로 보관
    _edited = (n.get("summary_edited_at") or "").strip() if (n.get("summary") or "").strip() else ""
    try:
        _d = await req.json()
    except Exception:
        _d = {}
    if _edited and not (isinstance(_d, dict) and _d.get("confirm_overwrite")):
        return JSONResponse({"ok": False, "need_confirm": True, "edited_at": _edited[:16],
                             "error": "사람이 고친 정리가 있습니다 — 다시 정리하면 새 정리로 바뀝니다"
                                      "(고친 정리는 「이전 정리」로 보관되어 되돌릴 수 있습니다)."})
    import time as _time
    with _VN_LOCK:
        if (_VN_SUM_JOBS.get(nid) or {}).get("state") == "running":
            return JSONResponse({"ok": True, "already": True})
        # z1177: 시작 시각 — 다시 연 화면·다른 창이 「몇 초째」를 이어 보여 준다(/extract-status 의 elapsed)
        _VN_SUM_JOBS[nid] = {"state": "running", "error": "", "t0": _time.time()}
    _stt_thr.Thread(target=_vn_sum_worker, args=(nid,), daemon=True).start()
    return JSONResponse({"ok": True, "started": True})


@app.get("/api/voice-note/{nid:int}/extract-status")
async def api_voice_note_extract_status(req: Request, nid: int):
    """정리가 끝났나 (z1169). state = idle | running | done | error"""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    with db_session() as c:
        n = _vn_row(c, nid)
    if not _vn_mine(u, n):
        return JSONResponse({"ok": False, "error": _vnv.server_text("없거나 볼 수 없는 메모입니다.", (u or {}).get("lang"))}, 404)
    with _VN_LOCK:
        j = dict(_VN_SUM_JOBS.get(nid) or {"state": "idle", "error": ""})
    if j.get("error"):   # z1200
        j["error"] = _vnv.server_text(j["error"], u.get("lang"))
    # z1177: 시작 시각은 그대로 내보내지 않고, 돌고 있으면 몇 초째인지(서버 시계로)만 알려 준다
    t0 = j.pop("t0", None)
    if j.get("state") == "running" and t0:
        import time as _time
        j["elapsed"] = max(0, int(_time.time() - t0))
    j["ok"] = True
    return JSONResponse(j)


@app.post("/api/voice-note/{nid:int}/save")
async def api_voice_note_save(req: Request, nid: int):
    """제목·원문·정리 글 고치기 — 보낸 칸만 바꾼다."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    try:
        d = await req.json()
    except Exception:
        d = {}
    with db_session() as c:
        n = _vn_row(c, nid)
    if not _vn_mine(u, n):
        return JSONResponse({"ok": False, "error": _vnv.server_text("없거나 볼 수 없는 메모입니다.", (u or {}).get("lang"))}, 404)
    sets, args = [], []
    if d.get("title") is not None:
        sets.append("title=?")
        args.append(str(d.get("title")).strip()[:200])
    if d.get("body") is not None:
        sets.append("body=?")
        args.append(str(d.get("body")).replace("\r\n", "\n").strip()[:200000])
    for _k, _v in _vn_meta_from(d, keep_empty=True).items():   # z1194 — 일시·장소·참여자(지우기도 된다)
        sets.append(_k + "=?")
        args.append(_v)
    if d.get("summary") is not None:
        _ns = str(d.get("summary")).replace("\r\n", "\n").strip()[:20000]
        sets.append("summary=?")
        args.append(_ns)
        # z1183: 사람이 고친 표시(바뀌었을 때만) — 나중에 「🔄 다시 정리」가 먼저 묻는다
        if _ns != ((n or {}).get("summary") or "").strip():
            sets.append("summary_edited_at=datetime('now','localtime')")
    if not sets:
        return JSONResponse({"ok": False, "error": _vnv.server_text("바꿀 내용이 없습니다.", (u or {}).get("lang"))}, 400)
    args.append(nid)
    with db_session() as c:
        c.execute("UPDATE voice_notes SET " + ", ".join(sets)
                  + ", updated_at=datetime('now','localtime') WHERE id=?", tuple(args))
        ts = _row_ts(c, "voice_notes", nid)
    return JSONResponse({"ok": True, "updated_at": ts})


@app.post("/api/voice-note/{nid:int}/summary-restore")
async def api_voice_note_summary_restore(req: Request, nid: int):
    """z1183: 🎤 「↩ 이전 정리」 — 지금 정리와 이전 정리를 맞바꾼다(한 번 더 누르면 돌아온다) · 내 메모만."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    with db_session() as c:
        n = _vn_row(c, nid)
        if not _vn_mine(u, n):
            return JSONResponse({"ok": False, "error": _vnv.server_text("없거나 볼 수 없는 메모입니다.", (u or {}).get("lang"))}, 404)
        prev = (n.get("summary_prev") or "").strip()
        if not prev:
            return JSONResponse({"ok": False, "error": _vnv.server_text("되돌릴 이전 정리가 없습니다.", (u or {}).get("lang"))}, 400)
        cur = (n.get("summary") or "").strip()
        c.execute("UPDATE voice_notes SET summary=?, summary_prev=?, summary_prev_at=datetime('now','localtime'), "
                  "summary_edited_at=datetime('now','localtime'), updated_at=datetime('now','localtime') WHERE id=?",
                  (prev, cur, nid))
        n2 = _vn_row(c, nid)
    return JSONResponse({"ok": True, "summary": prev, "has_prev": bool(cur),
                         "prev_at": ((n2 or {}).get("summary_prev_at") or "")[:16] if cur else ""})


@app.delete("/api/voice-note/{nid:int}")
async def api_voice_note_delete(req: Request, nid: int):
    """메모 지우기 — 올린 녹음 파일도 함께. 🔴 내 것만."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    with db_session() as c:
        n = _vn_row(c, nid)
    if not _vn_mine(u, n):
        return JSONResponse({"ok": False, "error": _vnv.server_text("없거나 볼 수 없는 메모입니다.", (u or {}).get("lang"))}, 404)
    import shutil as _sh
    try:
        _dir = os.path.join(_VN_DIR, f"note_{nid}")
        if os.path.isdir(_dir):
            _sh.rmtree(_dir, ignore_errors=True)
    except Exception as _e:
        print(f"[VOICE-NOTE] 녹음 폴더 삭제 실패(무시): {_e}")
    with db_session() as c:
        c.execute("DELETE FROM voice_notes WHERE id=?", (nid,))
    with _VN_LOCK:
        _VN_JOBS.pop(nid, None)
        _VN_SUM_JOBS.pop(nid, None)        # z1169 — 정리 상태도 같이 치운다
    return JSONResponse({"ok": True})


# ════════════════════════════════════════════════════════════════════════
#  회의 알림(이음 메신저) ↔ 회의록 연결 — 서버끼리 쓰는 입구 2개 (2026-09-15 대표 지시)
#  흐름: 메신저 회의 알림 카드 「▶ 회의 시작」(참석자 누구나 · 먼저 누른 사람이 녹음 담당)
#        → 메신저 서버가 POST /api/meeting/msg/start → 회의 1건당 회의록 1개 생성·연결
#        → 누른 사람의 WORKS 창에 /meetings/{id}?autorec=1 (녹음 자동 시작 시도)
#        → 녹음 종료 → 기존 자동 정리 → 카드는 POST /api/meeting/msg/status 로
#          '진행 중/정리 중/실패/완료' + '이 직원이 볼 수 있나'를 WORKS 에 묻는다.
#  ⭐ 열람 권한 판단은 WORKS(_can_view_meeting) 한 곳에서만 — 메신저가 규칙을 흉내내면
#     WORKS 에서 공개범위를 바꿨을 때 두 쪽이 어긋난다(대표 결정 '볼 수 있는 사람에게만').
#  인증: 기존 서버간 공유키(X-SSO-Service-Key = sso_client.get_service_key()). 키가 비었으면 항상 거부.
#  대표 결정: 녹음=WORKS 녹음창 · 시작=참석자 누구나 · 보기=볼 수 있는 사람에게만 · WORKS 먼저.
# ════════════════════════════════════════════════════════════════════════
_MSG_VIS_MAP = {"all": "all", "hq": "hq", "vn": "vn", "private": "private"}   # 메신저 공개범위 = WORKS 그대로


def _msg_service_key_ok(req) -> bool:
    """서버간 공유키 확인 — 비교는 시간 일정(hmac). WORKS 쪽 키가 비어 있으면 무엇이 와도 거부."""
    import hmac as _hm
    got = (req.headers.get("X-SSO-Service-Key") or "").strip()
    if not got:
        return False
    try:
        from . import sso_client as _sc
        want = (_sc.get_service_key() or "").strip()
    except Exception:
        return False
    return bool(want) and _hm.compare_digest(got.encode("utf-8"), want.encode("utf-8"))


def _msg_user_by_empno(c, emp):
    """사번 → 활성 WORKS 사용자(dict). 정확히 1명일 때만(대소문자 무관 — VN 사번 규칙). 아니면 None."""
    emp = str(emp or "").strip()
    if not emp:
        return None
    rows = c.execute("SELECT * FROM users WHERE UPPER(COALESCE(employee_no,''))=UPPER(?) AND is_active=1",
                     (emp,)).fetchall()
    return dict(rows[0]) if len(rows) == 1 else None


def _msg_sync_attendees(c, m, att_emps, externals) -> dict:
    """z1134: 이음 참석자 명단 → 그 회의의 WORKS 명단(meeting_attendees)을 그대로 맞춘다.
    - 사번은 `_msg_user_by_empno` 로 **정확히 1명**일 때만 연결(추측 연결 금지 · 사람 참조는 ID)
    - 계정 없는 참석자(externals)는 이름만(user_id=NULL)
    - 🔴 **녹음 중인 사람은 빼지 않는다**(대표 결정 2026-09-29) — 명단에서 빠져도 녹음이 끊기면 안 된다
    - 작성자(owner)·이음 등록 담당(msg_organizer_id)의 권한은 명단과 무관(권한 함수가 따로 본다)
    - `meetings.attendees_text` 도 같은 순서로 다시 적는다(대표 결정: 이음 명단이 기준)
    반환: {"added":[이름], "removed":[이름], "kept":그대로인 수, "held":[녹음 중이라 남긴 이름]}
    """
    out = {"added": [], "removed": [], "kept": 0, "held": []}
    mid = (m or {}).get("id")
    if not mid or c is None:
        return out
    # ① 받은 사번 → 계정(정확히 1명만) · 보낸 순서 유지 · 중복 제거
    want_users, want_uid = [], set()
    for e in (att_emps or []):
        au = _msg_user_by_empno(c, e)
        if au and au["id"] not in want_uid:
            want_uid.add(au["id"])
            want_users.append(au)
    want_ext, want_nm = [], set()
    for nm in (externals or []):
        nm = str(nm or "").strip()
        if nm and nm not in want_nm:
            want_nm.add(nm)
            want_ext.append(nm)
    # ② 지금 녹음 중인 사람(rec_json 의 by) 은 명단에서 빼지 않는다
    hold_uid = None
    if str((m.get("rec_state") or "")).strip() == "recording":
        try:
            hold_uid = (_rec_info(m) or {}).get("by") or None
        except Exception:
            hold_uid = None
    # ③ 지금 명단과 견줘 뺄 사람만 뺀다
    cur = [dict(r) for r in c.execute(
        "SELECT id, user_id, name FROM meeting_attendees WHERE meeting_id=? ORDER BY id", (mid,))]
    for r in cur:
        uid, nm = r.get("user_id"), str(r.get("name") or "")
        if uid:
            if uid in want_uid:
                out["kept"] += 1
                continue
            if hold_uid and uid == hold_uid:      # 녹음 중 — 그대로 둔다
                out["held"].append(nm)
                out["kept"] += 1
                continue
        elif nm and nm in want_nm:
            out["kept"] += 1
            continue
        c.execute("DELETE FROM meeting_attendees WHERE id=?", (r["id"],))
        out["removed"].append(nm)
    # ④ 새로 온 사람만 넣는다
    have_uid = set(r["user_id"] for r in cur if r.get("user_id"))
    have_nm = set(str(r.get("name") or "") for r in cur if not r.get("user_id"))
    for au in want_users:
        if au["id"] not in have_uid:
            c.execute("INSERT INTO meeting_attendees(meeting_id, user_id, name) VALUES(?,?,?)",
                      (mid, au["id"], au["name"]))
            out["added"].append(au["name"])
    for nm in want_ext:
        if nm not in have_nm:
            c.execute("INSERT INTO meeting_attendees(meeting_id, user_id, name) VALUES(?,?,?)",
                      (mid, None, nm))
            out["added"].append(nm)
    # ⑤ 참석자 칸 글도 같은 순서로(녹음 중이라 남긴 사람은 뒤에 붙인다)
    seen, uniq = set(), []
    for n in ([au["name"] for au in want_users] + want_ext + list(out["held"])):
        n = str(n or "").strip()
        if n and n not in seen:
            seen.add(n)
            uniq.append(n)
    c.execute("UPDATE meetings SET attendees_text=? WHERE id=?", (", ".join(uniq)[:1000], mid))
    return out


def _msg_owner_disp(c, uid) -> str:
    """녹음 담당(회의록 작성자) 표시 — 이름 직책 부서 규칙, 조회가 비면 이름만(빈칸 금지)."""
    s = user_disp_by_id(c, uid, "")
    if s:
        return s
    r = c.execute("SELECT name FROM users WHERE id=?", (uid,)).fetchone() if uid else None
    return (r[0] if r else "") or ""


_MTG_STALL_MIN = 10   # z1179: 녹음은 있는데 이만큼(분) 아무것도 안 돌면 「멈춤」 — 사람 손이 필요하다


def _meeting_idle_min(m) -> float:
    """회의록을 마지막으로 고친 뒤 몇 분 지났나(서버 시계 · DB 의 localtime 저장값과 같은 기준). 모르면 0."""
    try:
        t = datetime.strptime(str(m.get("updated_at") or "")[:19], "%Y-%m-%d %H:%M:%S")
    except ValueError:
        return 0.0
    return max(0.0, (datetime.now() - t).total_seconds() / 60.0)


def _mtg_text_key(s) -> str:
    """z1185: 원문 비교용 — 띄어쓰기·줄바꿈 차이는 같은 글로 본다(「사람이 고쳤나」 판정)."""
    return " ".join(str(s or "").split())


import re as _re87
#  🔴 z1187 (대표 2026-10-16 「이전에 회의록들은 확인을 안한건가?? 이전 회의록 등록안한건 아직 그대로 인데...」 · 사진 09-30 회의):
#    녹음은 있으나 받아쓴 글에 회의 말이 거의 없는 회의록(무음에서 받아쓰기가 지어낸 헛말 · 외국 글자 · 「녹음 한번 해보고 있어」 ·
#    잡담 몇 마디)도 정리가 「판독되지 않아 확인할 수 없음」으로 남아 「정리 끝」이었다(운영 5건 — z1185 는 받아쓴 글이 있기만 하면 봤다).
#    운영 실측(10-16 · 받아쓴 글 있는 회의록 33건): 그 5건의 알아들을 말 0·0·10·15·70자 ↔ 진짜 회의 가장 짧은 것 426자(그다음 1,853자)
_MTG_STT_MIN_CHARS = 200     # 받아쓴 글에서 알아들을 말(글자)이 이만큼은 있어야 「녹음 원문 있음」 — 말로 약 40초
#  받아쓰기 헛말(무음·잡음에서 받아쓰기가 지어내는 말) — 세지 않는다
_STT_HALLU_RE = _re87.compile(
    r"시청\s*해\s*주셔서\s*감사합니다|구독\s*(과|와)?\s*좋아요|좋아요\s*(와|과)?\s*구독|알림\s*설정|"
    r"다음\s*영상에서\s*(만나요|뵙겠습니다)|MBC\s*뉴스|KBS\s*뉴스|SBS\s*뉴스|"
    r"thank(s| you) for watching|please subscribe", _re87.I)
#  알아들을 수 있는 글자 = 한글 음절 · 라틴 글자(베트남어 성조 글자 포함) · 숫자 — 받아쓰기가 지어낸 외국 글자는 세지 않는다
_STT_READ_RE = _re87.compile(r"[가-힣A-Za-z0-9À-ɏḀ-ỿ]")


def _mtg_split_stt(body):
    """z1187: 원문 → (받아쓴 글 앞(사람이 쓴 글 · 이음 메모), 받아쓴 글).
    받아쓴 글 = 첫 「[음성 변환]」부터 끝까지(_stt_append_body 가 「🎤 [음성 변환]」 머리를 붙여 덧붙인다)."""
    b = str(body or "")
    i = b.find("[음성 변환]")
    if i < 0:
        return b, ""
    return b[:i].replace("🎤", "").replace("🎙", ""), b[i:]


def _stt_meaningful_len(stt) -> int:
    """z1187: 받아쓴 글에서 알아들을 수 있는 말의 양(글자 수) — 머리 「[음성 변환]」 · 받아쓰기 헛말 ·
    같은 문장 되풀이(한 번만 센다)는 빼고 한글·라틴·숫자 글자만 센다."""
    t = str(stt or "").replace("🎤", " ").replace("🎙", " ").replace("[음성 변환]", " ")
    t = _STT_HALLU_RE.sub(" ", t)
    seen, n = set(), 0
    for s in _re87.split(r"[.!?。！？\n]+", t):
        k = " ".join(s.split())
        if not k or k in seen:
            continue
        seen.add(k)
        n += len(_STT_READ_RE.findall(k))
    return n


def _meeting_body_written(m) -> bool:
    """🔴 z1185 (대표 2026-10-16 · 세션 10 전달 · 사진): 「회의록이 녹음 원문 또는 수기 작성이 되지 않았을때는
    회의록보기 아이콘은 비활성화가 되어야함.. 회의록보기 아이콘은 회의록이 작성되었을때만 활성화하는게 맞음.」
    원문에 **회의 내용**이 있나 — 판정은 여기 한 곳(이음 카드 단계 · 목록 📄 · 상세 「📄 회의록 양식」 · 빅터AI 정리 입구).
      ① 녹음을 받아쓴 글이 있다(「[음성 변환]」 — _stt_append_body 가 붙이는 머리)
      ② 사람이 이음웍스에서 원문을 쓰거나 고쳤다(body_edited_at · 저장할 때 적힌다 · z1185 부터)
      ③ 이음웍스에서 직접 만든 회의록(이음 회의와 안 이어짐)의 원문 — 사람이 쓴 것뿐이다(씨앗이 없다)
    ⛔ 이음 「▶ 회의 시작」으로 만든 회의록의 원문 = 이음 회의 메모(씨앗)일 뿐 — 회의 내용이 아니다
       (운영 2026-10-16: 메모만 있는 채로 정리를 눌러 회의 내용 없는 정리가 「정리 끝」이 된 회의 3건).
    🔴 z1187: ① 은 받아쓴 글에 **알아들을 말이 _MTG_STT_MIN_CHARS 자 이상**일 때만(헛말·외국 글자·시험 한두 마디는 아님 —
       운영 5건) · ③ 은 받아쓴 글 **앞**의 글만 본다(받아쓴 글이 헛말뿐인 직접 회의록은 아님)."""
    body = (m.get("body") or "").strip()
    if not body:
        return False
    if (m.get("body_edited_at") or "").strip():
        return True
    head, stt = _mtg_split_stt(body)
    if stt and _stt_meaningful_len(stt) >= _MTG_STT_MIN_CHARS:
        return True
    return (not m.get("msg_meeting_id")) and bool(head.strip())


def _meeting_has_minutes(m) -> bool:
    """z1185: 회의록이 **작성됐나** = 원문에 회의 내용이 있다(_meeting_body_written) · 또는 사람이 정리 글을 직접 고쳤다
    (z1183 「✏ 고치기」 → summary_edited_at). 「📋 회의록 보기」(이음)·목록 「📄 회의록」·상세 「📄 회의록 양식」은
    이것이 참일 때만 켠다.
    🔵 「↩ 이전 정리」 맞바꾸기는 사람이 쓴 것이 아니다 — 그때는 고친 시각과 보관 시각이 **같은 값**으로 함께 적힌다
       (summary-restore 의 UPDATE 한 줄 · SQLite 의 now 는 한 문장 안에서 같다). 사람이 고치면 고친 시각만 새로 적힌다."""
    if _meeting_body_written(m):
        return True
    ed = (m.get("summary_edited_at") or "").strip()
    return bool(ed and ed != (m.get("summary_prev_at") or "").strip() and (m.get("summary") or "").strip())


def _meeting_msg_stage(m) -> str:
    """카드 표시 단계: started(진행 중) / recorded(녹음됨·정리 대기) / processing(글자 변환·AI 정리 중) / failed / done.
    🔴 z1179 (이음 v854 와 맞추며 · 대표 확인 2026-10-13): 「⏳ 정리 중」은 **정말 무언가 돌 때만**.
       전에는 받아쓰기 작업만 봐서 ① AI 정리(z1170 부터 뒤에서 돈다)가 실패해도 「실패」가 안 떴고
       ② 녹음은 있는데 아무것도 안 돌아도(창이 닫혀 시작 못 함 · 서버가 다시 켜져 작업 기록이 사라짐) 영영 「정리 중」이었다
       (운영 2026-10-13 실측: 33건 중 2건). 이음 v854 는 이 단계에 단추 없이 「끝나면 알려 드려요」라 **막다른 곳**이 됐다.
       → AI 정리도 보고 · 녹음이 있는데 _MTG_STALL_MIN 분째 아무것도 안 돌면 failed(= 「🔄 다시 정리」 단추가 뜬다).
       단계 값 다섯 개는 그대로(이음과의 약속) — 뜻만 정확해진다. done(정리 글 있음)은 그대로(이음 「회의록 등록」 알림 기준).
    🔴 z1185 (대표 2026-10-16 「회의록보기 아이콘은 회의록이 작성되었을때만 활성화」): done = 정리 글 + **회의록 작성됨**
       (_meeting_has_minutes). 이음 메모만으로 만든 정리는 done 이 아니다 → 이음 카드는 「📁 녹음 올리기」·「✏️ 작성하기」 ·
       「회의록 등록」 알림도 안 간다(세션 10: 이음은 바꿀 것 없음 — 이 단계 값을 그대로 따른다)."""
    if (m.get("summary") or "").strip() and _meeting_has_minutes(m):
        return "done"
    with _STT_LOCK:
        job = dict(_STT_JOBS.get(m["id"]) or {})
    with _MTG_SUM_LOCK:
        sj = dict(_MTG_SUM_JOBS.get(m["id"]) or {})
    if job.get("state") == "running" or sj.get("state") == "running":
        return "processing"
    if job.get("state") == "error" or sj.get("state") == "error":
        return "failed"
    if (m.get("rec_state") or "") == "recording":
        # z1114: 녹음 중(창이 닫혀 끊긴 녹음 포함)은 앞 조각 파일이 있어도 '진행 중' — 카드가 「녹음됨·정리 대기」로 잘못 보이지 않게
        return "started"
    if (m.get("audio_path") or "").strip() or "[음성 변환]" in (m.get("body") or ""):
        # 🔴 z1187: 받아쓰기는 끝났는데 알아들을 말이 거의 없으면(무음의 헛말 · 외국 글자 · 시험 한두 마디) 기다릴 것도
        #    「실패」도 아니다 → 시작 상태(이음 카드 「📁 녹음 올리기」·「✏️ 작성하기」 — 녹음을 다시 올리거나 적게 한다)
        if "[음성 변환]" in (m.get("body") or "") and not _meeting_body_written(m):
            return "started"
        # z1179: 녹음이 막 들어와 다음 단계가 곧 시작될 짧은 사이만 「정리 대기」 — 그 뒤엔 멈춘 것
        return "failed" if _meeting_idle_min(m) >= _MTG_STALL_MIN else "recorded"
    return "started"


@app.post("/api/meeting/msg/start")
async def api_meeting_msg_start(req: Request):
    """[서버 전용] 메신저 「▶ 회의 시작」 → 회의 1건당 회의록 1개(이미 있으면 그대로) · 연결 정보 반환.
    누를 자격(참석자인가)은 메신저가 확인한다(참석자 명단은 메신저만 안다) — WORKS 는 공유키로 신뢰."""
    if not _msg_service_key_ok(req):
        return JSONResponse({"ok": False, "error": "forbidden"}, 403)
    try:
        d = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "json_required"}, 400)
    if not isinstance(d, dict):
        return JSONResponse({"ok": False, "error": "json_required"}, 400)
    try:
        msg_id = int(d.get("msg_meeting_id") or 0)
    except (TypeError, ValueError):
        msg_id = 0
    if msg_id <= 0:
        return JSONResponse({"ok": False, "error": "msg_meeting_id_required"}, 400)
    title = str(d.get("title") or "").strip()[:200]
    if not title:
        return JSONResponse({"ok": False, "error": "title_required"}, 400)
    mdate = str(d.get("start_at") or "").strip()[:10]   # 메신저 start_at = 등록자 소속 현지 'YYYY-MM-DDTHH:MM'
    try:
        datetime.strptime(mdate, "%Y-%m-%d")
    except ValueError:
        return JSONResponse({"ok": False, "error": "start_at_invalid"}, 400)
    vis = _MSG_VIS_MAP.get(str(d.get("visibility") or "").strip())
    if not vis:
        return JSONResponse({"ok": False, "error": "visibility_invalid"}, 400)
    externals = [str(x).strip()[:80] for x in (d.get("externals") or []) if str(x).strip()][:30]
    att_emps = [str(x).strip() for x in (d.get("attendee_employee_nos") or []) if str(x).strip()][:200]
    import sqlite3 as _sq3
    with db_session() as c:
        starter = _msg_user_by_empno(c, d.get("starter_employee_no"))
        if not starter:
            return JSONResponse({"ok": False, "error": "starter_not_found"}, 404)
        # 등록 담당(회의를 만든 사람) — 녹음을 안 해도 회의록을 고칠 수 있다(대표 결정 2026-09-15).
        #   사번이 없거나 WORKS 에서 정확히 1명으로 안 찾아지면 비워 둔다(추측 연결 금지).
        organizer = _msg_user_by_empno(c, d.get("organizer_employee_no")) if d.get("organizer_employee_no") else None
        org_id = organizer["id"] if organizer else None
        created = False
        row = c.execute("SELECT * FROM meetings WHERE msg_meeting_id=?", (msg_id,)).fetchone()
        if not row:
            att_users, seen = [], set()
            for e in att_emps:
                au = _msg_user_by_empno(c, e)
                if au and au["id"] not in seen:
                    seen.add(au["id"])
                    att_users.append(au)
            names = [au["name"] for au in att_users] + externals
            try:
                cur = c.execute(
                    """INSERT INTO meetings(title, meeting_date, mode, team_id, owner_id, location, tags,
                                            attendees_text, body, visibility, status, msg_meeting_id, msg_started_at,
                                            msg_organizer_id)
                       VALUES(?,?,?,?,?,?,?,?,?,?,?,?,datetime('now','localtime'),?)""",
                    (title, mdate, "A", starter.get("team_id"), starter["id"],
                     str(d.get("location") or "").strip()[:200], str(d.get("tags") or "").strip()[:200],
                     ", ".join(names)[:1000], str(d.get("note") or "").strip()[:4000], vis, "draft", msg_id,
                     org_id),
                )
                new_id = cur.lastrowid
                for au in att_users:      # 사번으로 정확히 연결 — 사람 참조는 ID(이름 매칭 X)
                    c.execute("INSERT INTO meeting_attendees(meeting_id, user_id, name) VALUES(?,?,?)",
                              (new_id, au["id"], au["name"]))
                for nm in externals:      # 외부 참석자 = 계정 없음 → 이름만
                    c.execute("INSERT INTO meeting_attendees(meeting_id, user_id, name) VALUES(?,?,?)",
                              (new_id, None, nm))
                created = True
            except _sq3.IntegrityError:
                created = False           # 거의 같은 순간 다른 사람이 먼저 만들었다 → 그 회의록을 쓴다
            row = c.execute("SELECT * FROM meetings WHERE msg_meeting_id=?", (msg_id,)).fetchone()
        m = dict(row)
        if not created and isinstance(d.get("attendee_employee_nos"), list):
            # z1134 안전망: 이미 있는 회의록이면 그때의 이음 명단으로 다시 맞춘다(그 사이 참석자가 바뀌었을 수 있다)
            try:
                _sr = _msg_sync_attendees(c, m, att_emps, externals)
                if _sr["added"] or _sr["removed"]:
                    print("[MSG-ATT] 회의 시작 때 명단 맞춤 — 회의 %s +%d -%d"
                          % (m["id"], len(_sr["added"]), len(_sr["removed"])))
                    m = dict(c.execute("SELECT * FROM meetings WHERE id=?", (m["id"],)).fetchone())
            except Exception as _se:
                print("[MSG-ATT] 회의 시작 때 명단 맞추기 실패(회의록은 그대로): %r" % (_se,))
        if org_id and not m.get("msg_organizer_id"):   # 먼저 만들어진 회의록에 등록 담당이 비어 있으면 채움(있으면 안 바꿈)
            c.execute("UPDATE meetings SET msg_organizer_id=? WHERE id=?", (org_id, m["id"]))
            m["msg_organizer_id"] = org_id
        if created:
            try:
                log_activity(c, starter["id"], "meeting_create",
                             f"{starter['name']} 회의 알림에서 회의 시작: {title[:60]}",
                             team_id=starter.get("team_id"))
            except Exception as _le:
                print(f"[MEETING-MSG] 활동기록 실패(회의록 생성은 완료): {_le}")
        is_starter = (m.get("owner_id") == starter["id"])
        # z1149: 녹음 자동 시작은 막혔다(_MEETING_AUTOREC_ON=False).
        #   \U0001F534 다만 **이음에서 들어왔다는 표시**는 보내야 한다 — 착지 화면이 그 표시를 보고
        #   「\U0001F527 다시 하기」를 펴서 **휴대폰 녹음기 안내**(z1116·z1130)를 보여 주기 때문이다.
        #   처음에 이 표시까지 껐다가 안내가 접힌 채 숨었다(회귀 ui_lead·ui_first 가 잡음).
        #   \U0001F534 이름을 autorec → fromeum 으로 바꾼 까닭: ①이음 v843 이 autorec 만 떼어 낸다
        #     ②autorec 은 '녹음을 자동으로 켠다'는 뜻이라 이제 사실과 다르다.
        _land = bool(is_starter and not (m.get("audio_path") or "").strip())
        autorec = bool(_MEETING_AUTOREC_ON and _land)
        out = {
            "ok": True, "created": created, "meeting_id": m["id"], "is_starter": is_starter,
            "started_by": _msg_owner_disp(c, m.get("owner_id")),
            "started_at": m.get("msg_started_at") or "",
            "stage": _meeting_msg_stage(m),
            "organizer_set": bool(m.get("msg_organizer_id")),
            "url": f"/meetings/{m['id']}" + ("?autorec=1" if autorec
                                              else ("?fromeum=1" if _land else "")),
        }
    return JSONResponse(out)


@app.post("/api/meeting/msg/attendees")
async def api_meeting_msg_attendees(req: Request):
    """[서버 전용] z1134 — 이음에서 참석자를 바꿔 **저장한 뒤** 부르는 입구.
    그 회의의 WORKS 명단(meeting_attendees · 참석자 칸)을 이음 명단으로 맞춘다.
    body: {msg_meeting_id: 이음 회의 id, attendee_employee_nos: [사번...], externals: [계정 없는 이름...]}
    - 회의록이 아직 없으면(「▶ 회의 시작」 전) **아무것도 만들지 않는다** → {"ok":true,"result":"none"}
    - 🔴 이음을 되부르지 않는다(z1123 규칙 그대로).
    - 🔴 `attendee_employee_nos` 칸이 아예 없으면 거절한다 — 부르는 쪽 실수로 전원이 지워지지 않게."""
    if not _msg_service_key_ok(req):
        return JSONResponse({"ok": False, "error": "forbidden"}, 403)
    try:
        d = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "json_required"}, 400)
    if not isinstance(d, dict):
        return JSONResponse({"ok": False, "error": "json_required"}, 400)
    try:
        msg_id = int(d.get("msg_meeting_id") or 0)
    except (TypeError, ValueError):
        msg_id = 0
    if msg_id <= 0:
        return JSONResponse({"ok": False, "error": "msg_meeting_id_required"}, 400)
    if not isinstance(d.get("attendee_employee_nos"), list):
        return JSONResponse({"ok": False, "error": "attendee_employee_nos_required"}, 400)
    att_emps = [str(x).strip() for x in d["attendee_employee_nos"] if str(x).strip()][:200]
    externals = [str(x).strip()[:80] for x in (d.get("externals") or []) if str(x).strip()][:30]
    with db_session() as c:
        row = c.execute("SELECT * FROM meetings WHERE msg_meeting_id=?", (msg_id,)).fetchone()
        if not row:
            return JSONResponse({"ok": True, "result": "none"})
        m = dict(row)
        r = _msg_sync_attendees(c, m, att_emps, externals)
    if r["added"] or r["removed"]:
        print("[MSG-ATT] 회의 %s 참석자 +%d -%d (그대로 %d)%s"
              % (m["id"], len(r["added"]), len(r["removed"]), r["kept"],
                 (" · 녹음 중이라 남김 %d" % len(r["held"])) if r["held"] else ""))
    return JSONResponse({"ok": True, "result": "synced", "meeting_id": m["id"],
                         "added": len(r["added"]), "removed": len(r["removed"]),
                         "kept": r["kept"], "held": len(r["held"])})


@app.post("/api/meeting/msg/status")
async def api_meeting_msg_status(req: Request):
    """[서버 전용] 메신저 회의 카드 표시용 — 회의별 단계 + '이 직원이 볼 수 있나'(WORKS 권한 단일 판단). 최대 50건.
    body: {employee_no: 사번, msg_meeting_ids: [메신저 회의 id...]}"""
    if not _msg_service_key_ok(req):
        return JSONResponse({"ok": False, "error": "forbidden"}, 403)
    try:
        d = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "json_required"}, 400)
    if not isinstance(d, dict):
        return JSONResponse({"ok": False, "error": "json_required"}, 400)
    ids = []
    for x in (d.get("msg_meeting_ids") or [])[:50]:
        try:
            v = int(x)
        except (TypeError, ValueError):
            continue
        if v > 0 and v not in ids:
            ids.append(v)
    items = {}
    with db_session() as c:
        viewer = _msg_user_by_empno(c, d.get("employee_no"))
        for msg_id in ids:
            row = c.execute("SELECT * FROM meetings WHERE msg_meeting_id=?", (msg_id,)).fetchone()
            if not row:
                items[str(msg_id)] = {"stage": "none", "can_view": False}
                continue
            m = dict(row)
            can_view = bool(viewer) and _can_view_meeting(c, viewer, m)
            _rv = _rec_view(m, viewer)   # z1114: 녹음 중인가 · 서버에 저장된 초(창이 닫혀 끊긴 녹음도)
            it = {"stage": _meeting_msg_stage(m), "can_view": can_view,
                  "started_by": _msg_owner_disp(c, m.get("owner_id")),
                  "started_at": m.get("msg_started_at") or "",
                  "recording": _rv["state"] == "recording",
                  "rec_secs": _rv["secs"] if _rv["state"] == "recording" else 0,
                  # z1121: 보는 사람이 그 녹음을 시작했나 — 창을 닫아 멈춘 녹음이면 이음 카드 단추를 그 사람에게만
                  #   「🎤 이어서 녹음」으로(대표 지시 2026-09-21 · 세션 10). WORKS 회의 화면의 REC.mine(z1120)과 같은 판단.
                  "rec_mine": _rv["state"] == "recording" and bool(_rv["mine"]),
                  # z1131: 사람이 「⏹ 회의 종료」를 눌렀나 — 이음 카드가 시간 규칙보다 먼저 본다
                  "ended": _meeting_ended(m),
                  "ended_at": (m.get("ended_at") or ""),
                  # z1123: 보는 사람이 이 회의록을 지울 수 있나(작성자·관리자 = WORKS 🗑 삭제와 같은 판단) — 이음 🗓 회의 「삭제」
                  #   확인 창이 「📋 WORKS 회의록도 함께 지워집니다 / 남습니다」를 미리 보이게(대표 결정 2026-09-22).
                  "can_delete": bool(viewer) and _can_delete_meeting(viewer, m)}
            # 🔁 z1209 (대표 지시 2026-11-11 · 세션 10 요청 · 이음 v935 짝): 이음웍스 회의록에서 고친 제목·참석자를
            #   이음 회의·카드가 따라가게 — 이음이 1분마다 묻는 이 답에 싣는다(이음웍스는 이음을 되부르지 않는다 · z1123).
            #   서버끼리만 받는 답(공유키)이라 볼 수 있는지(can_view)와 무관하게 싣는다 — 이음은 화면에 그대로 주지 않는다.
            #   att_emps = 계정이 연결된 참석자의 사번 · att_ext = 계정 없는 참석자 이름(고객사 분 등) ·
            #   계정은 연결됐는데 사번이 빈 사람은 어느 쪽에도 넣지 않는다(이음이 사번으로만 사람을 찾는다).
            _ar = [dict(r) for r in c.execute(
                "SELECT a.user_id, a.name, u.employee_no FROM meeting_attendees a "
                "LEFT JOIN users u ON u.id=a.user_id WHERE a.meeting_id=? ORDER BY a.id", (m["id"],))]
            it["title"] = str(m.get("title") or "")
            it["att_emps"] = [str(r["employee_no"]).strip() for r in _ar
                              if r.get("user_id") and str(r.get("employee_no") or "").strip()]
            it["att_ext"] = [str(r.get("name") or "").strip() for r in _ar
                             if not r.get("user_id") and str(r.get("name") or "").strip()]
            if can_view:                  # 볼 수 없는 사람에겐 회의록 주소 자체를 주지 않는다
                it["meeting_id"] = m["id"]
                # 「📋 회의록 보기」 착지 (대표 지시 2026-09-16): 정리가 끝났으면 **회의록 양식**으로 바로.
                #   양식은 읽기 전용이라, 아직 손봐야 하는 단계(정리 실패 등)는 고칠 수 있는 회의록 화면으로 보낸다
                #   — 카드 안내문이 "회의록에서 다시 시도"라고 말하는 그 화면.
                #   z1114: 녹음 중이면(창이 닫혀 끊겼어도) 녹음을 끝낼 수 있는 회의록 화면으로 — 이음 카드 「🔴 회의 진행 중」 → 여기
                it["url"] = (f"/meetings/{m['id']}/doc" if (it["stage"] == "done" and not it["recording"])
                             else f"/meetings/{m['id']}")
            items[str(msg_id)] = it
    return JSONResponse({"ok": True, "items": items})


@app.post("/api/meeting/{mid:int}/end")
async def api_meeting_end(req: Request, mid: int):
    """z1131 (대표 지시 2026-09-27): 예정 끝 시각보다 일찍 끝났을 때 사람이 회의를 끝낸다.
    끝낸 시각을 `meetings.ended_at` 에 적고, 회의 카드(이음·모아보기)가 그 값을 시간 규칙보다 먼저 본다.
    🔴 z1152 (대표 지시 2026-10-08 「되돌리기는 웍스화면에서도 지워줘」): **되돌리기는 없앴다.**
      실수로 끝냈으면 관리자가 서버에서 고친다. `undo` 를 보내도 무시한다(갈래 자체가 없다)."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "error": "login"}, 401)
    try:
        d = await req.json()
    except Exception:
        d = {}
    with db_session() as c:
        row = c.execute("SELECT * FROM meetings WHERE id=?", (mid,)).fetchone()
        if not row:
            return JSONResponse({"ok": False, "error": "not_found"}, 404)
        m = dict(row)
        if not _can_end_meeting(u, m, c):
            return JSONResponse({"ok": False, "error": "not_allowed"}, 403)
        if _meeting_ended(m):
            return JSONResponse({"ok": True, "ended": True, "ended_at": m.get("ended_at") or "",
                                 "already": True})
        c.execute("UPDATE meetings SET ended_at=datetime('now','localtime'),"
                  " updated_at=datetime('now','localtime') WHERE id=?", (mid,))
        _r2 = c.execute("SELECT ended_at FROM meetings WHERE id=?", (mid,)).fetchone()
        now = (dict(_r2).get("ended_at") if _r2 else "") or ""
        print(f"[MEETING-END] 회의 {mid} 종료 — {u.get('name')} {now}", flush=True)
    return JSONResponse({"ok": True, "ended": True, "ended_at": now})


@app.post("/api/meeting/msg/end")
async def api_meeting_msg_end(req: Request):
    """[서버 전용] z1150 (대표 지시 2026-10-08): 이음 🗓 회의 카드의 「⏹ 회의 종료」가 부른다.

    왜 따로 두나 — `POST /api/meeting/{mid}/end` 는 `get_user(req)` 라 **브라우저 로그인**이 있어야 한다.
    이음 **서버**는 사람 세션이 없어 그 길을 못 쓴다(세션 10 요청 2026-10-08).
    🔴 누가 끝낼 수 있는지는 **WORKS 가 판정한다** — 이음은 화면에서 1차로만 거른다.
      판정 기준은 사람이 누르는 길과 **똑같이** `_can_end_meeting`(회의록 작성자·관리자/대표·
      이음 등록 담당·그 회의 참석자). 사람은 **사번**으로 찾는다(이름 맞추기 금지 — 사람 참조는 ID).
    🔴 녹음 중이면 끝내지 않는다 — 녹음은 그 사람의 WORKS 창 안에서 돌아 서버가 마칠 수 없고,
      여기서 끝내 버리면 녹음이 계속 돌면서 회의록 정리도 시작되지 않는다. `recording` 을 돌려준다
      (z1149 로 새 녹음은 안 생기지만, 그 전에 시작돼 안 끝난 녹음이 남아 있을 수 있다).

    body: {msg_meeting_id, employee_no(누르는 사람 사번)}
    🔴 되돌리기는 **만들지 않는다**(대표 지시 2026-10-08 「되돌리기 만들지마」 · 세션 10 전달).
      WORKS 자기 화면의 「↩ 종료 되돌리기」(z1131)는 그대로 — 사람이 자기 화면에서 쓰는 것이다.
    → 200 {ok:true, ended, ended_at, works_meeting_id}
       200 {ok:false, error: "not_found"|"no_user"|"not_allowed"|"recording", works_meeting_id?}
       403 {ok:false, error:"forbidden"}  (공유키 불일치)
    """
    if not _msg_service_key_ok(req):
        return JSONResponse({"ok": False, "error": "forbidden"}, 403)
    try:
        d = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "json_required"}, 400)
    if not isinstance(d, dict):
        return JSONResponse({"ok": False, "error": "json_required"}, 400)
    try:
        msg_id = int(d.get("msg_meeting_id") or 0)
    except (TypeError, ValueError):
        msg_id = 0
    if msg_id <= 0:
        return JSONResponse({"ok": False, "error": "msg_meeting_id_required"}, 400)
    with db_session() as c:
        row = c.execute("SELECT * FROM meetings WHERE msg_meeting_id=?", (msg_id,)).fetchone()
        if not row:
            return JSONResponse({"ok": False, "error": "not_found"})
        m = dict(row)
        mid = m["id"]
        actor = _msg_user_by_empno(c, d.get("employee_no"))
        if not actor:
            return JSONResponse({"ok": False, "error": "no_user", "works_meeting_id": mid})
        if not _can_end_meeting(actor, m, c):
            return JSONResponse({"ok": False, "error": "not_allowed", "works_meeting_id": mid})
        if str((m.get("rec_state") or "")).strip() == "recording":
            # 🔴 녹음 중 — 이음에서 끝내지 않는다. 그 사람 WORKS 창의 「⏹」로 마쳐야 정리가 돈다.
            return JSONResponse({"ok": False, "error": "recording", "works_meeting_id": mid})
        if _meeting_ended(m):
            return JSONResponse({"ok": True, "ended": True, "ended_at": m.get("ended_at") or "",
                                 "already": True, "works_meeting_id": mid})
        c.execute("UPDATE meetings SET ended_at=datetime('now','localtime'),"
                  " updated_at=datetime('now','localtime') WHERE id=?", (mid,))
        _r = c.execute("SELECT ended_at FROM meetings WHERE id=?", (mid,)).fetchone()
        ended_at = (_r["ended_at"] if _r else "") or ""
        try:
            log_activity(c, actor["id"], "meeting_end",
                         f"{actor['name']} 이음 🗓 회의 카드에서 종료: {(m.get('title') or '')[:60]}",
                         team_id=actor.get("team_id"))
        except Exception:
            pass
    print(f"[MEETING-END-MSG] 회의 {mid} 종료 — {actor.get('name')} ({ended_at})", flush=True)
    return JSONResponse({"ok": True, "ended": True, "ended_at": ended_at, "works_meeting_id": mid})


@app.post("/api/meeting/msg/delete")
async def api_meeting_msg_delete(req: Request):
    """[서버 전용] 이음 🗓 회의에서 회의를 지울 때 그 회의의 WORKS 회의록도 함께 지운다 (z1123 · 대표 결정 2026-09-22).
    ⭐ 이음은 자기 회의를 지우기 **전에** 이것을 부르고 200 ok 를 받아야 지운다 — WORKS 에 못 닿으면 이음도 안 지운다
      (한쪽만 지워진 채 남지 않게 · WORKS 🗑 삭제 z1122 와 거꾸로 같은 규칙).
    회의록은 WORKS 규칙 그대로 작성자(▶ 회의 시작을 누른 사람)·관리자(admin/ceo)가 지울 때만 — 아니면 남기고 까닭을 돌려준다.
    🔴 여기서는 이음을 다시 부르지 않는다(이음이 지우는 중 — 서로 부르며 돌지 않게).
    body: {msg_meeting_id, employee_no(지우는 사람 사번)}
    → 200 {ok: true, result: "deleted" | "none"(회의록 없음) | "kept", reason?: "not_allowed" | "viewer_not_found", works_meeting_id?}"""
    if not _msg_service_key_ok(req):
        return JSONResponse({"ok": False, "error": "forbidden"}, 403)
    try:
        d = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "json_required"}, 400)
    if not isinstance(d, dict):
        return JSONResponse({"ok": False, "error": "json_required"}, 400)
    try:
        msg_id = int(d.get("msg_meeting_id") or 0)
    except (TypeError, ValueError):
        msg_id = 0
    if msg_id <= 0:
        return JSONResponse({"ok": False, "error": "msg_meeting_id_required"}, 400)
    out = {"ok": True, "result": "none"}
    with db_session() as c:
        row = c.execute("SELECT * FROM meetings WHERE msg_meeting_id=?", (msg_id,)).fetchone()
        if row:
            m = dict(row)
            out["works_meeting_id"] = m["id"]
            viewer = _msg_user_by_empno(c, d.get("employee_no"))
            if not viewer:
                out.update(result="kept", reason="viewer_not_found")
            elif not _can_delete_meeting(viewer, m):
                out.update(result="kept", reason="not_allowed")
            else:
                # 자식(결정·할일·참석자)은 FK ON DELETE CASCADE — WORKS 🗑 삭제(api_meeting_delete)와 같은 한 줄
                c.execute("DELETE FROM meetings WHERE id=?", (m["id"],))
                out["result"] = "deleted"
                try:
                    log_activity(c, viewer["id"], "meeting_delete",
                                 f"{viewer['name']} 이음 🗓 회의에서 삭제 — 회의록도 함께: {(m.get('title') or '')[:60]}",
                                 team_id=viewer.get("team_id"))
                except Exception as _le:
                    print(f"[MEETING-MSG] 활동기록 실패(삭제는 완료): {_le}")
    if out.get("result") == "deleted":   # z1125: 그 회의의 녹음 파일도 함께(대표 결정 2026-09-26)
        from starlette.concurrency import run_in_threadpool
        await run_in_threadpool(_meeting_audio_purge, out["works_meeting_id"])
    try:   # 이음 회의가 곧 지워진다 — 「🗓 회의 카드 모아보기」 30초 저장본을 비워 바로 빠지게(z1122 와 같게)
        with _MSG_CARDS_LOCK:
            _MSG_CARDS_CACHE.clear()
    except Exception as _e:
        print(f"[MSG-CARDS] 저장본 비우기 실패(무시): {_e}")
    return JSONResponse(out)


# ════════════════════════════════════════════════════════════════════════
#  🗓 회의 카드 모아보기 (2026-09-17 대표 지시)
#  「이음에서 등록한 회의 카드(회의 정보·회의록)를 회의록 화면 탭에서 한 번에」
#  ⭐ 어떤 회의 카드가 보이나 = 이음 🗓 회의와 똑같이 — 이음 서버가 판단(POST /api/works/meetings).
#  ⭐ 회의록 버튼 = WORKS _can_view_meeting — 회의 알림 카드(msg/status)와 같은 판단·같은 착지.
#  🔴 WORKS 는 일꾼 1개 — 이음 호출은 스레드에서(8초 제한). 보는 사람+기간별 30초 캐시.
#  🔴 이음을 못 부르면 이 탭에만 안내문 — 회의록 탭은 그대로.
#  보기 전용 — 참석 응답·수정·삭제·「▶ 회의 시작」은 이음 회의 카드에서.
# ════════════════════════════════════════════════════════════════════════
_MSG_CARDS_TTL = 30                 # 초
_MSG_CARDS_SPAN_MAX = 450           # 한 번에 묻는 기간(일) 상한 — 이음 입구와 같은 값
_MSG_CARDS_CACHE = {}               # (user_id, from, to) → (저장 시각, 이음 결과)
_MSG_CARDS_LOCK = _stt_thr.Lock()
_MSG_CARDS_DOWN = {"until": 0.0}    # 이음 연결 실패 직후 15초는 다시 부르지 않는다(스레드가 8초씩 묶이지 않게)
_MSG_RESP_OK = ("attending", "declined", "change")


def _msg_card_clean(it):
    """이음이 준 회의 1건 → 화면에 쓰는 칸만(글자 길이 제한). 형식이 틀리면 None."""
    if not isinstance(it, dict):
        return None
    try:
        mid = int(it.get("id") or 0)
    except (TypeError, ValueError):
        return None
    start_at = str(it.get("start_at") or "").strip()[:16]
    try:
        datetime.strptime(start_at, "%Y-%m-%dT%H:%M")
    except ValueError:
        return None
    if mid <= 0:
        return None

    def _int(v, dflt, lo, hi):
        try:
            v = int(v)
        except (TypeError, ValueError):
            return dflt
        return v if lo <= v <= hi else dflt

    atts = []
    for a in (it.get("attendees") or [])[:300]:
        if not isinstance(a, dict):
            continue
        nm = str(a.get("name") or "").strip()[:60]
        if not nm:
            continue
        r = str(a.get("response") or "")
        atts.append({"name": nm, "response": r if r in _MSG_RESP_OK else "",
                     "is_organizer": bool(a.get("is_organizer"))})
    me = it.get("me") if isinstance(it.get("me"), dict) else {}
    my_r = str(me.get("response") or "")
    org = it.get("organizer") if isinstance(it.get("organizer"), dict) else {}
    vis = str(it.get("visibility") or "")
    return {
        "id": mid,
        "title": str(it.get("title") or "").strip()[:200] or "(제목 없음)",
        "start_at": start_at,
        "tz_offset": _int(it.get("tz_offset"), 9, -12, 14),
        "tz_label": str(it.get("tz_label") or "").strip()[:20],
        "duration_min": _int(it.get("duration_min"), 30, 1, 7 * 24 * 60),
        "location": str(it.get("location") or "").strip()[:200],
        "visibility": vis if vis in ("all", "hq", "vn", "private") else "",
        "organizer": str(org.get("name") or "").strip()[:80],
        "attendees": atts,
        "externals": [str(x).strip()[:80] for x in (it.get("externals") or [])[:30] if str(x).strip()],
        "me": {"is_organizer": bool(me.get("is_organizer")), "is_attendee": bool(me.get("is_attendee")),
               "response": my_r if my_r in _MSG_RESP_OK else ""},
    }


@app.get("/api/meetings/msg-cards")
async def api_meetings_msg_cards(req: Request):
    """🗓 회의 카드 모아보기 — 이음 회의(나에게 보이는 것) + WORKS 회의록 단계·버튼.
    ?from=YYYY-MM-DD&to=YYYY-MM-DD (시작일 기준 · 없으면 60일 전 ~ 1년 뒤)."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "error": "로그인이 필요합니다."}, 401)
    from datetime import timezone as _tz
    with db_session() as c:
        ent = _meeting_user_entity(c, u)
    # 날짜 경계 = 보는 사람 소속(본사 +9 · 베트남 +7) — KNK 시간대 표준
    today = (datetime.now(_tz.utc) + timedelta(hours=7 if ent == "VN" else 9)).date()
    try:
        d_from = datetime.strptime(req.query_params.get("from") or "", "%Y-%m-%d").date()
    except ValueError:
        d_from = today - timedelta(days=60)
    try:
        d_to = datetime.strptime(req.query_params.get("to") or "", "%Y-%m-%d").date()
    except ValueError:
        d_to = today + timedelta(days=366)
    if d_to < d_from or (d_to - d_from).days > _MSG_CARDS_SPAN_MAX:
        return JSONResponse({"ok": False, "error": "기간이 올바르지 않습니다."}, 400)
    emp = str(u.get("employee_no") or "").strip()      # 사람 참조 = 사번 (회의 알림 연결과 같은 기준)
    key = (u.get("id"), d_from.isoformat(), d_to.isoformat())
    now_t = datetime.now().timestamp()
    with _MSG_CARDS_LOCK:
        hit = _MSG_CARDS_CACHE.get(key)
    if hit and now_t - hit[0] < _MSG_CARDS_TTL:
        res = hit[1]
    elif now_t < _MSG_CARDS_DOWN["until"]:
        res = {"ok": False, "error": "이음에 연결하지 못했습니다. 잠시 뒤 다시 눌러 주세요."}
    else:
        from . import sso_client
        from starlette.concurrency import run_in_threadpool
        res = await run_in_threadpool(sso_client.fetch_msg_meetings, emp, d_from.isoformat(), d_to.isoformat())
        if res.get("code") == "conn":
            _MSG_CARDS_DOWN["until"] = datetime.now().timestamp() + 15
        if res.get("ok"):
            with _MSG_CARDS_LOCK:
                if len(_MSG_CARDS_CACHE) > 500:          # 오래 쌓이지 않게
                    _MSG_CARDS_CACHE.clear()
                _MSG_CARDS_CACHE[key] = (now_t, res)
    if not res.get("ok"):
        return JSONResponse({"ok": False, "error": res.get("error") or "이음 회의 목록을 가져오지 못했습니다."})
    cards, _seen = [], set()
    for it in res.get("items") or []:
        x = _msg_card_clean(it)
        if x and x["id"] not in _seen:          # 같은 회의가 두 번 오면 한 장만
            _seen.add(x["id"])
            cards.append(x)
    with db_session() as c:
        rows = {}
        ids = [x["id"] for x in cards]
        for i in range(0, len(ids), 200):
            part = ids[i:i + 200]
            for r in c.execute(
                "SELECT m.*, (SELECT COUNT(*) FROM meeting_decisions WHERE meeting_id=m.id) AS dec_cnt, "
                "(SELECT COUNT(*) FROM meeting_actions WHERE meeting_id=m.id) AS act_cnt "
                "FROM meetings m WHERE m.msg_meeting_id IN (%s)" % ",".join("?" * len(part)), part
            ).fetchall():
                rows[r["msg_meeting_id"]] = dict(r)
        for x in cards:
            m = rows.get(x["id"])
            if not m:
                x["minutes"] = {"stage": "none", "can_view": False}
                continue
            can_view = _can_view_meeting(c, u, m)
            _rv = _rec_view(m, u)   # z1119: 녹음 중인가(이음 msg/status 와 같은 값) — 탭이 「녹음 중」과 「시작만 누름」을 가른다
            mn = {"stage": _meeting_msg_stage(m), "can_view": can_view,
                  "started_by": _msg_owner_disp(c, m.get("owner_id")),
                  "recording": _rv["state"] == "recording",
                  "rec_secs": _rv["secs"] if _rv["state"] == "recording" else 0,
                  # z1131: 사람이 「⏹ 회의 종료」를 눌렀나(모아보기 탭 카드가 먼저 본다)
                  "ended": _meeting_ended(m),
                  "ended_at": (m.get("ended_at") or ""),
                  # z1122: 보는 사람이 그 녹음을 시작했나(msg/status z1121 과 같은 값) — 이음 v817 처럼 본인에게만 「🎤 이어서 녹음」
                  "rec_mine": _rv["state"] == "recording" and bool(_rv["mine"])}
            if can_view:      # 볼 수 없는 사람에겐 회의록 주소·내용 수를 주지 않는다
                # z1122: 주소는 msg/status(z1114)와 같게 — 정리가 끝났어도 녹음이 열려 있으면 녹음을 이어가거나 끝낼 화면
                mn["url"] = (f"/meetings/{m['id']}/doc" if (mn["stage"] == "done" and not mn["recording"])
                             else f"/meetings/{m['id']}")
                mn["dec_cnt"] = m.get("dec_cnt") or 0
                mn["act_cnt"] = m.get("act_cnt") or 0
                # z1179: 정리 전 단추(📁 녹음 올리기 · ✏️ 작성하기 · 🔄 다시 정리)는 **고칠 수 있는 사람에게만**
                #   (이음 v854 와 같은 규칙 · 판정은 _can_edit_meeting 한 곳)
                mn["can_edit"] = bool(_can_edit_meeting(u, m, c))
                # z1180: 🔍 모아보기 탭 검색 — 회의록 내용으로 찾은 것(/api/meetings/search 의 id)을 이 카드에 잇는다
                #   (볼 수 있는 회의록에만 준다 — 검색 API 도 목록과 같은 공개 범위)
                mn["mid"] = m["id"]
            x["minutes"] = mn
    return JSONResponse({"ok": True, "from": d_from.isoformat(), "to": d_to.isoformat(),
                         "today": today.isoformat(), "items": cards,
                         "truncated": bool(res.get("truncated"))})


# ── z1148 (대표 지시 2026-10-08): 「이 사람들도 보기」 ─────────────────
#   대표 지시: 「회의 참석하지 않은 특정 인원들에게도 보일 수 있게 공개범위를 직원 선택이 가능하도록」
#   대표 결정: 공개 범위 5가지는 그대로 · 명단을 고치는 사람 = 회의록을 고칠 수 있는 사람
#   🔵 고른 사람은 **보기만** 한다(고치기·지우기·녹음은 그대로 참석자 권한).
def _meeting_viewer_ids(c, mid: int) -> list:
    try:
        return [r["user_id"] for r in c.execute(
            "SELECT user_id FROM meeting_viewers WHERE meeting_id=?", (mid,))]
    except Exception:
        return []


def _meeting_viewer_rows(c, mid: int, lang: str = "ko") -> list:
    """화면에 보여 줄 명단 — 이름은 「이름 직책 부서」 규칙(vname_full).
    z1163: lang 을 주면 직책만 그 사람 말로(기본 ko = 지금까지와 같다)."""
    try:
        return [{"id": r["id"], "label": vname_full(dict(r), lang=lang)} for r in c.execute(
            "SELECT u.id, u.name, u.rank, t.name AS team_name "
            "FROM meeting_viewers mv JOIN users u ON u.id=mv.user_id "
            "LEFT JOIN teams t ON t.id=u.team_id "
            "WHERE mv.meeting_id=? ORDER BY u.name", (mid,))]
    except Exception:
        return []


@app.get("/api/meeting/{mid:int}/viewers")
async def api_meeting_viewers_get(req: Request, mid: int):
    """고를 수 있는 직원 명단 + 지금 고른 사람.
    이미 다른 규칙으로 볼 수 있는 사람은 「이미 볼 수 있음」으로 알려만 준다(막지는 않는다)."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    with db_session() as c:
        m = c.execute("SELECT * FROM meetings WHERE id=?", (mid,)).fetchone()
        if not m:
            return JSONResponse({"ok": False, "error": "없는 회의록입니다."}, 404)
        m = dict(m)
        if not _can_edit_meeting(u, m, c):
            return JSONResponse({"ok": False, "error": "수정 권한이 없습니다."}, 403)
        chosen = set(_meeting_viewer_ids(c, mid))
        _me_ent = _meeting_user_entity(c, u)   # z1151: 'KOR' / 'VN' — 먼저 열 탭
        rows = [dict(r) for r in c.execute(
            "SELECT u.id, u.name, u.rank, u.team_id, u.role, t.name AS team_name, "
            "       COALESCE(t.display_order, 999) AS t_ord, "
            "       COALESCE(t.entity,'KOR') AS t_ent "
            "FROM users u LEFT JOIN teams t ON t.id=u.team_id "
            "WHERE COALESCE(u.is_active,1)=1 "
            "ORDER BY t_ord, u.name")]
        out = []
        for r in rows:
            already = False
            if r["id"] not in chosen:
                try:
                    already = _can_view_meeting(c, {"id": r["id"], "role": r.get("role"),
                                                    "team_id": r.get("team_id")}, m)
                except Exception:
                    already = False
            # z1151 (대표 지시 2026-10-08 「본사, 베트남은 탭으로 구분해줘」):
            #   \U0001F534 같은 이름의 팀이 양쪽 법인에 있다(가공팀·품질팀·관리팀·구매팀·설계팀·
            #   소프트웨어팀·총괄 — 운영 실측 7쌍) → 법인을 안 주면 화면에서 구분할 길이 없다.
            #   판정은 공개 범위 「본사/법인 공개」와 **같은 단일소스**(teams.entity · z747).
            out.append({"id": r["id"], "label": vname_full(r, lang=(u.get("lang") or "ko")),
                        "team": (r.get("team_name") or "부서 없음"),
                        "entity": ("VN" if str(r.get("t_ent") or "KOR").strip().upper() == "VN"
                                   else "KOR"),
                        "on": r["id"] in chosen, "already": bool(already)})
    # me_entity = 보는 사람의 법인 — 그 탭이 먼저 열린다(대표 결정)
    return JSONResponse({"ok": True, "users": out, "me_entity": _me_ent})


@app.post("/api/meeting/{mid:int}/viewers")
async def api_meeting_viewers_save(req: Request, mid: int):
    """명단을 통째로 맞춘다. body: {"user_ids": [1,2,3]}"""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    d = await req.json()
    ids = []
    for x in (d.get("user_ids") or [])[:200]:
        try:
            n = int(x)
        except (ValueError, TypeError):
            continue
        if n > 0 and n not in ids:
            ids.append(n)
    with db_session() as c:
        m = c.execute("SELECT * FROM meetings WHERE id=?", (mid,)).fetchone()
        if not m:
            return JSONResponse({"ok": False, "error": "없는 회의록입니다."}, 404)
        m = dict(m)
        if not _can_edit_meeting(u, m, c):
            return JSONResponse({"ok": False, "error": "수정 권한이 없습니다."}, 403)
        ok_ids = []
        if ids:
            _q = ",".join("?" * len(ids))
            ok_ids = [r["id"] for r in c.execute(
                "SELECT id FROM users WHERE id IN (" + _q + ") AND COALESCE(is_active,1)=1", ids)]
        before = set(_meeting_viewer_ids(c, mid))
        c.execute("DELETE FROM meeting_viewers WHERE meeting_id=?", (mid,))
        for _i in ok_ids:
            c.execute("INSERT INTO meeting_viewers(meeting_id, user_id, added_by) VALUES(?,?,?)",
                      (mid, _i, u["id"]))
        rows = _meeting_viewer_rows(c, mid, lang=(u.get("lang") or "ko"))
        if set(ok_ids) != before:   # 권한을 넓힌 기록은 남긴다
            try:
                log_activity(c, u["id"], "meeting_viewers",
                             f"{u['name']} 회의록 「이 사람들도 보기」 {len(ok_ids)}명: "
                             f"{(m.get('title') or '')[:50]}",
                             team_id=u.get("team_id"))
            except Exception:
                pass
    return JSONResponse({"ok": True, "viewers": rows, "dropped": len(ids) - len(ok_ids)})


@app.post("/api/meeting/{mid:int}/link")
async def api_meeting_link(req: Request, mid: int):
    """회의록 ↔ 프로젝트·영업기회 연결 저장. 명시적 선택만(자동매칭 없음, 데이터 연결 안전).
    z1147 (대표 지시 2026-10-08): 지금은 쓰지 않는다 — 화면도 회색이고 여기서도 막는다."""
    if not _MEETING_LINK_ON:
        return JSONResponse({"ok": False, "error": "「연결」 기능은 지금 사용하지 않습니다."}, 403)
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    d = await req.json()

    def _toint(x):
        try:
            return int(x) if x not in (None, "", "0", 0) else None
        except (ValueError, TypeError):
            return None
    pid = _toint(d.get("project_id"))
    oid = _toint(d.get("opportunity_id"))
    with db_session() as c:
        m = c.execute("SELECT * FROM meetings WHERE id=?", (mid,)).fetchone()
        if not m:
            return JSONResponse({"ok": False, "error": "없는 회의록입니다."}, 404)
        m = dict(m)
        if not _can_edit_meeting(u, m, c):
            return JSONResponse({"ok": False, "error": "수정 권한이 없습니다."}, 403)
        if pid is not None:
            if not can_view_sales(u):
                return JSONResponse({"ok": False, "error": "프로젝트 연결 권한이 없습니다."}, 403)
            if not c.execute("SELECT 1 FROM projects WHERE id=?", (pid,)).fetchone():
                pid = None
        if oid is not None:
            if not can_use_sales(u):
                return JSONResponse({"ok": False, "error": "영업기회 연결은 영업 권한이 필요합니다."}, 403)
            if not c.execute("SELECT 1 FROM sales_opportunities WHERE id=?", (oid,)).fetchone():
                oid = None
        c.execute("UPDATE meetings SET project_id=?, opportunity_id=?, updated_at=datetime('now','localtime') WHERE id=?",
                  (pid, oid, mid))
        if oid:  # 영업기회 역참조 동기화(비어있을 때만 — 기존 연결 보존)
            try:
                c.execute("UPDATE sales_opportunities SET meeting_id=? WHERE id=? AND meeting_id IS NULL", (mid, oid))
            except Exception:
                pass
        new_ts = _row_ts(c, "meetings", mid)
    return JSONResponse({"ok": True, "project_id": pid, "opportunity_id": oid, "updated_at": new_ts})


@app.post("/api/meeting/{mid:int}/to-opportunity")
async def api_meeting_to_opportunity(req: Request, mid: int):
    """회의록 정보(제목·요약·날짜·작성자)로 영업기회를 새로 만들고 양방향 연결. 영업 권한 필요.
    z1147 (대표 지시 2026-10-08): 지금은 쓰지 않는다 — 화면도 회색이고 여기서도 막는다."""
    if not _MEETING_LINK_ON:
        return JSONResponse({"ok": False, "error": "「새 영업기회 등록」 은 지금 사용하지 않습니다."}, 403)
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"ok": False, "error": "영업기회 등록은 영업 권한이 필요합니다."}, 403)
    with db_session() as c:
        m = c.execute("SELECT * FROM meetings WHERE id=?", (mid,)).fetchone()
        if not m:
            return JSONResponse({"ok": False, "error": "없는 회의록입니다."}, 404)
        m = dict(m)
        if not _can_view_meeting(c, u, m):
            return JSONResponse({"ok": False, "error": "권한이 없습니다."}, 403)
        if m.get("opportunity_id"):
            return JSONResponse({"ok": False, "error": "이미 영업기회와 연결돼 있습니다.",
                                 "opportunity_id": m["opportunity_id"],
                                 "url": f"/sales/opportunities/{m['opportunity_id']}"}, 409)
        memo = (_md_plain((m.get("summary") or "").strip()) or (m.get("body") or "").strip())[:1500]   # z1183 — 기호 없이
        fields = {
            "opp_no": _gen_opp_no(c),
            "title": (m.get("title") or "제목 없는 영업기회")[:200],
            "owner_user_id": u.get("id"),
            "stage": "미팅", "status": "active",
            "meeting_done": 1,
            "meeting_date": (m.get("meeting_date") or None),
            "meeting_memo": memo,
            "meeting_id": mid,
            "created_by": u.get("id"),
        }
        cols = list(fields.keys())
        ph = ",".join("?" * len(cols))
        cur = c.execute(f"INSERT INTO sales_opportunities({','.join(cols)}) VALUES({ph})",
                        [fields[k] for k in cols])
        oid = cur.lastrowid
        c.execute("UPDATE meetings SET opportunity_id=?, updated_at=datetime('now','localtime') WHERE id=?",
                  (oid, mid))
        try:
            log_activity(c, u["id"], "meeting_to_opp",
                         f"회의록→영업기회 등록: {fields['title'][:50]}", team_id=u.get("team_id"))
        except Exception:
            pass
    return JSONResponse({"ok": True, "opportunity_id": oid, "url": f"/sales/opportunities/{oid}"})


@app.put("/api/task/{tid}")
async def api_update_task(req: Request, tid: int):
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    d = await req.json()
    # v5H121: 정합성 검증
    try:
        title, category, new_status, hours = _validate_task_payload(d)
    except ValueError as ve:
        return JSONResponse({"ok": False, "error": str(ve)}, 400)
    with db_session() as c:
        prev = c.execute("SELECT user_id, status, title, project_id FROM tasks WHERE id=?", (tid,)).fetchone()
        if not prev or prev["user_id"] != u["id"]:
            return JSONResponse({"error": "권한 없음"}, 403)
        # v5H226z405: 동시 편집 감지(낙관적 잠금)
        _conf, _cur = _edit_conflict(c, "tasks", tid, d.get("base_ts"))
        if _conf:
            return _conflict_resp(_cur)
        c.execute(
            """UPDATE tasks SET title=?, category=?, project_id=?, customer_id=?,
                               status=?, hours=?, notes=?, next_plan=?, due_date=?,
                               updated_at=datetime('now','localtime')
               WHERE id=?""",
            (
                title,
                category,
                d.get("project_id") or None,
                d.get("customer_id") or None,
                new_status,
                hours,
                d.get("notes") or "",
                (d.get("next_plan") or "").strip(),
                d.get("due_date") or None,
                tid,
            ),
        )
        if prev["status"] != new_status:
            log_activity(c, u["id"], "task_status",
                         title=f"{u['name']}: {prev['title'][:50]} — {prev['status']} → {new_status}",
                         task_id=tid, project_id=prev["project_id"], team_id=u.get("team_id"))
        _new_ts = _row_ts(c, "tasks", tid)
    if prev["status"] != new_status and new_status == "지연":
        notify_status_change(tid, u["id"], prev["status"], new_status)
    return JSONResponse({"ok": True, "updated_at": _new_ts})


@app.delete("/api/task/{tid}")
async def api_delete_task(req: Request, tid: int):
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    try:
        with db_session() as c:
            # v5H36: 실제 권한 확인 — 카드 존재 여부 + 작성자/관리자 검증
            row = c.execute("SELECT user_id FROM tasks WHERE id=?", (tid,)).fetchone()
            if not row:
                return JSONResponse({"ok": False, "error": "카드를 찾을 수 없습니다"}, 404)
            is_owner = (int(row["user_id"]) == int(u["id"]))
            is_admin = u.get("role","") in ("ceo","admin")
            if not (is_owner or is_admin):
                return JSONResponse({"ok": False, "error": "작성자만 삭제 가능"}, 403)
            # v5H37: carry_from_id 자기참조 FK가 CASCADE 아님 → 자식(이월된 카드)의 참조 NULL 처리 후 삭제
            c.execute("UPDATE tasks SET carry_from_id=NULL WHERE carry_from_id=?", (tid,))
            # activity_logs / notifications 등 task_id 참조도 안전하게 정리 (CASCADE 미설정 가능성)
            try: c.execute("UPDATE activity_logs SET task_id=NULL WHERE task_id=?", (tid,))
            except Exception: pass
            try: c.execute("UPDATE notifications SET task_id=NULL WHERE task_id=?", (tid,))
            except Exception: pass
            # 본 카드 삭제 (task_comments/task_reactions 등은 ON DELETE CASCADE)
            c.execute("DELETE FROM tasks WHERE id=?", (tid,))
        return JSONResponse({"ok": True})
    except Exception as e:
        # FK violation 또는 기타 오류 → 명확한 메시지
        import traceback; traceback.print_exc()
        return JSONResponse({"ok": False, "error": f"DB 오류: {type(e).__name__}: {str(e)[:200]}"}, 500)


# v5H226z112 (2026-05-31): 메모 인라인 편집 자동저장 (daily.html debounce 600ms)
# notes 만 단독 PATCH (PUT /api/task/{tid} 는 title required 라 부분 업데이트 불가)
