@app.get("/admin/console", response_class=HTMLResponse)   # z1191z83: 예전 관리자 화면 — /admin 은 새 관리 홈(app/admin_people.py)
async def admin_page(req: Request):
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    with db_session() as c:
        teams = [dict(r) for r in c.execute(
            """SELECT t.*, u.name AS leader_name,
                      (SELECT COUNT(*) FROM users WHERE team_id=t.id AND is_active=1) AS member_count
               FROM teams t LEFT JOIN users u ON t.leader_id=u.id
               ORDER BY t.display_order"""
        ).fetchall()]
        users = [dict(r) for r in c.execute(
            """SELECT u.*, t.name AS team_name, t.entity AS team_entity FROM users u
               LEFT JOIN teams t ON u.team_id=t.id
               ORDER BY CASE WHEN (COALESCE(t.entity,'')='VN' OR u.team_id=12) THEN 1 ELSE 0 END,
                        CASE WHEN COALESCE(u.employee_no,'')='' THEN 1 ELSE 0 END,
                        CAST(u.employee_no AS INTEGER), u.employee_no, u.id"""
        ).fetchall()]   # z747: 법인=팀(teams.entity) 단일소스·본사 먼저→베트남, 각 그룹 사번순 (u.entity SQL 미의존)
        projects = [dict(r) for r in c.execute(
            """SELECT p.*, cu.name AS customer_name FROM projects p
               LEFT JOIN customers cu ON p.customer_id=cu.id ORDER BY p.id DESC"""
        ).fetchall()]
        customers = [dict(r) for r in c.execute("SELECT * FROM customers ORDER BY " + _TIER_ORDER_SQL + ", name").fetchall()]
    # z1191z181 (대표 11-27 「남은 처음 등록 값」): 프로젝트 표 고객사·수주액 = 수주마다(공용 orders_summary · 화면에 보이는 50건만)
    _so181 = _z165_so_map([p["id"] for p in projects[:50]])
    return ctx(req, "admin.html", so165=_so181,
               user=u, teams=teams, users=users, projects=projects, customers=customers,
               active="admin", can_work_patterns=can_view_work_patterns(u))


@app.get("/admin/field-access", response_class=HTMLResponse)
async def admin_field_access(req: Request, saved: int = 0):
    """v5H226z822 (대표 지시): 정보 열람 권한 — 매출금액·구매단가·구매처 정보를 팀별로 열람 제어.
    체크박스 표(세로=3분류·가로=활성 팀 전체·총괄 먼저)로 현재 정책 표시·수정. ceo·admin 전용.
    1단계는 정책 저장만(화면 적용은 2단계). 대표/관리자는 정책과 무관하게 항상 전체 열람."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    with db_session() as c:
        # 활성 팀 전체 — 총괄(display_order=-1) 먼저 [[knk_dept_order_rule]]
        teams = [dict(r) for r in c.execute(
            "SELECT id, name, code, COALESCE(entity,'') AS entity FROM teams "
            "ORDER BY display_order, id"
        ).fetchall()]
        policy = load_field_access_policy(c)   # {category: set(team_id)}
    # 표시용: 분류 목록(고정 순서) + 각 분류별 허용 team_id set(템플릿에서 in 판정)
    categories = [
        {"code": code, "label": FIELD_ACCESS_LABELS[code],
         "allowed": sorted(policy.get(code) or set())}
        for code in ("sales_amount", "purchase_price", "supplier_info")
    ]
    return ctx(req, "admin_field_access.html",
               user=u, active="admin", teams=teams, categories=categories,
               saved=bool(saved))


@app.post("/admin/field-access")
async def admin_field_access_save(req: Request):
    """v5H226z822: 체크값을 읽어 field_access_policy 를 트랜잭션서 전체 재작성(DELETE 후 INSERT).
    체크박스 name = 'fa__{category}__{team_id}'. ceo·admin 아니면 거부."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    form = await req.form()
    # 유효 분류·유효 팀만 반영(폼 위조 방지)
    valid_categories = set(FIELD_ACCESS_LABELS.keys())
    pairs = []
    with db_session() as c:
        valid_team_ids = {r[0] for r in c.execute("SELECT id FROM teams").fetchall()}
        for key in form.keys():
            if not key.startswith("fa__"):
                continue
            parts = key.split("__")
            if len(parts) != 3:
                continue
            _, cat, tid_s = parts
            if cat not in valid_categories:
                continue
            try:
                tid = int(tid_s)
            except (TypeError, ValueError):
                continue
            if tid in valid_team_ids:
                pairs.append((cat, tid))
        # 전체 재작성(트랜잭션): 기존 삭제 후 체크된 것만 삽입
        c.execute("DELETE FROM field_access_policy")
        for cat, tid in pairs:
            c.execute(
                "INSERT OR IGNORE INTO field_access_policy(category, team_id) VALUES(?,?)",
                (cat, tid),
            )
    return RedirectResponse("/admin/field-access?saved=1", 303)


@app.get("/admin/user-trace", response_class=HTMLResponse)
async def admin_user_trace(req: Request, q: str = ""):
    """z748(대표 지시·읽기전용 진단): 직원의 실제 저장값(사번·로그인ID·한글/베트남이름·법인·팀·부서코드)과
    화면 표시(vname)를 그대로 보여줘 '한국인인데 베트남 이름' 같은 이상의 원인을 추적.
    같은 베트남이름(name_vi)을 여러 명이 쓰는 중복도 빨강 표시. 데이터 변경 없음(전부 SELECT). admin/ceo 전용."""
    from fastapi.responses import HTMLResponse
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    q = (q or "").strip()

    def _e(x):
        return (str(x if x is not None else "")).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

    with db_session() as c:
        base = ("SELECT u.id, COALESCE(u.employee_no,'') emp, COALESCE(u.login_id,'') lid, "
                "COALESCE(u.name,'') nm, COALESCE(u.name_vi,'') nvi, COALESCE(u.entity,'') uent, "
                "u.team_id, COALESCE(t.name,'') tnm, COALESCE(t.entity,'') tent, "
                "COALESCE(u.dept_code,'') dc, COALESCE(u.is_active,1) act "
                "FROM users u LEFT JOIN teams t ON t.id=u.team_id ")
        if q:
            like = f"%{q}%"
            rows = c.execute(base + "WHERE u.name LIKE ? OR u.name_vi LIKE ? OR u.employee_no LIKE ? "
                             "OR u.login_id LIKE ? ORDER BY u.name_vi, u.employee_no", (like, like, like, like)).fetchall()
        else:
            rows = c.execute(base + "WHERE COALESCE(u.name_vi,'')<>'' ORDER BY u.name_vi, u.employee_no").fetchall()
        rows = [dict(r) for r in rows]
        dup = {}
        for r in c.execute("SELECT COALESCE(name_vi,'') nvi, COUNT(*) c FROM users "
                           "WHERE COALESCE(name_vi,'')<>'' AND COALESCE(is_active,1)=1 "
                           "GROUP BY name_vi HAVING c>1").fetchall():
            rd = dict(r) if not isinstance(r, dict) else r
            dup[rd["nvi"]] = rd["c"]

    H = ["<html><head><meta charset='utf-8'><title>직원 저장값 진단</title><style>",
         "body{font-family:system-ui,'Malgun Gothic';font-size:13px;padding:18px;color:#1f2937;}",
         "table{border-collapse:collapse;margin:8px 0 20px;}th,td{border:1px solid #cbd5e1;padding:4px 8px;white-space:nowrap;}",
         "th{background:#f1f5f9;}code{background:#f1f5f9;padding:1px 5px;border-radius:3px;}",
         ".dup{background:#fef2f2;color:#b91c1c;font-weight:700;}</style></head><body>",
         "<h2>🔎 직원 저장값 진단 <span style='font-weight:400;color:#64748b;'>(읽기전용 · 데이터 변경 없음)</span></h2>",
         "<form method='get' style='margin:8px 0;'><input name='q' value='" + _e(q) +
         "' placeholder='이름·사번·로그인ID·베트남이름' style='padding:5px 8px;width:280px;'> "
         "<button type='submit'>검색</button> <span style='color:#64748b;'>비우면 베트남이름 있는 직원 전체</span></form>",
         "<p style='color:#64748b;'>표시(vname)=화면에 뜨는 이름. <b class='dup'>빨강 베트남이름</b>=여러 명이 같은 값(중복·오류 의심).</p>",
         "<table><tr><th>사번</th><th>로그인ID</th><th>한글이름</th><th>베트남이름(name_vi)</th><th>표시(vname)</th>"
         "<th>users.entity</th><th>팀</th><th>팀법인</th><th>부서코드</th><th>활성</th></tr>"]
    for r in rows:
        _nvi = r["nvi"]
        _dupcls = " class='dup'" if (_nvi and _nvi in dup) else ""
        _dupnote = f" ({dup[_nvi]}명 중복)" if (_nvi and _nvi in dup) else ""
        disp = vname({"name": r["nm"], "name_vi": r["nvi"], "entity": r["uent"]})
        H.append("<tr><td><code>" + _e(r["emp"]) + "</code></td><td>" + _e(r["lid"]) + "</td><td>" + _e(r["nm"]) +
                 "</td><td" + _dupcls + ">" + _e(_nvi or "—") + _e(_dupnote) + "</td><td><b>" + _e(disp) +
                 "</b></td><td>" + _e(r["uent"] or "—") + "</td><td>" + _e(r["tnm"] or "—") + "</td><td>" +
                 _e(r["tent"] or "—") + "</td><td>" + _e(r["dc"] or "—") + "</td><td>" + ("✓" if r["act"] else "—") + "</td></tr>")
    H.append("</table>")
    H.append(f"<p style='color:#64748b;'>총 {len(rows)}명. 베트남이름(name_vi)은 <b>메신저 SSO 동기화</b>(sso_client)로 들어옴 — "
             "여기 값이 곧 화면 표시의 원천. 한국인인데 name_vi가 차 있으면 메신저 원본/동기화 문제.</p></body></html>")
    return HTMLResponse("".join(H))


@app.post("/api/admin/user")
async def api_admin_user(req: Request):
    u = require(req, ["admin"])
    if not u:
        return JSONResponse({"error": "권한 없음"}, 401)
    d = await req.json()
    with db_session() as c:
        if d.get("id"):
            c.execute(
                "UPDATE users SET name=?, team_id=?, rank=?, role=?, is_active=? WHERE id=?",
                (d["name"], d.get("team_id") or None, d.get("rank", ""),
                 d.get("role", "member"), int(d.get("is_active", 1)), d["id"]),
            )
            if d.get("password"):
                c.execute("UPDATE users SET password=? WHERE id=?", (hash_pw(d["password"]), d["id"]))
        else:
            # v5H226z533 (대표 지시): 메신저가 사용자 등록 기준 → WORKS 직접 생성 차단.
            return JSONResponse({"ok": False, "error": "사용자 신규 등록은 KNK Eum 메신저에서 합니다(메신저가 기준). WORKS는 로그인·동기화로 자동 반영됩니다."}, 400)
    return JSONResponse({"ok": True})


