@app.get("/admin/ai-settings", response_class=HTMLResponse)
async def admin_ai_settings_page(req: Request):
    """AI 공급사·모델 설정 (admin/ceo 전용). 환경변수 > 앱설정 > 기본 순."""
    u = require(req, ["admin", "ceo"])
    if not u:
        _au = get_user(req)
        return RedirectResponse(role_home(_au) if _au else "/login", 303)
    from . import ai_client
    prov = ai_client.get_provider()
    info = {
        "available": ai_client.ai_available(),
        "provider": prov or "(비활성)",
        "model": ai_client.default_model() if prov else "",
        "set_provider": (get_setting("ai_provider", "") or ""),
        "set_model": (get_setting("ai_model", "") or ""),
        "env_provider": (os.environ.get("KNK_AI_PROVIDER", "") or ""),
        "env_model": (os.environ.get("KNK_AI_MODEL", "") or ""),
        "default_openai": ai_client.DEFAULT_MODEL_OPENAI,
        "default_claude": ai_client.DEFAULT_MODEL_CLAUDE,
    }
    # v5H226z381 (대표 지시): 화면에서 키 입력 — 공급사별 키 상태(마스킹·출처) + SDK 설치 여부
    _ki = ai_client.key_info()
    info["openai_key"] = _ki["openai"]
    info["claude_key"] = _ki["claude"]
    info["sdk_claude"] = ai_client._ANTHROPIC_OK
    info["sdk_openai"] = ai_client._OPENAI_OK
    # z1142(대표 지시): 회의록 정리에서 바로잡을 「우리 회사 말」 — 빈 값이면 기본 목록
    info["meeting_terms"] = (get_setting("meeting_terms", "") or "")
    info["meeting_terms_default"] = ai_client._MEETING_TERMS_DEFAULT
    return ctx(req, "admin_ai_settings.html", user=u, active="admin",
               info=info, saved=(req.query_params.get("saved") == "1"))


@app.post("/admin/ai-settings")
async def admin_ai_settings_save(req: Request,
                                 ai_provider: str = Form(""), ai_model: str = Form(""),
                                 openai_api_key: str = Form(""), anthropic_api_key: str = Form(""),
                                 openai_key_clear: str = Form(""), anthropic_key_clear: str = Form(""),
                                 meeting_terms: str = Form("")):
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    from . import ai_client
    with db_session() as c:
        for k, v in (("ai_provider", (ai_provider or "").strip()),
                     ("ai_model", (ai_model or "").strip()),
                     # z1142 — 회의록에서 바로잡을 우리 회사 말(빈 값=기본 목록 · "-"=끄기)
                     ("meeting_terms", (meeting_terms or "").strip()[:4000])):
            c.execute(
                "INSERT INTO app_settings(key, value) VALUES(?, ?) "
                "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (k, v))
    # v5H226z381 (대표 지시): API 키 화면 입력 — 비우면 유지, '삭제' 체크면 제거, 값 있으면 난독화 저장.
    _clr = lambda x: (x or "").strip().lower() in ("1", "on", "true", "yes")
    if _clr(openai_key_clear):
        ai_client.clear_api_key("openai")
    elif (openai_api_key or "").strip():
        ai_client.save_api_key("openai", openai_api_key.strip())
    if _clr(anthropic_key_clear):
        ai_client.clear_api_key("claude")
    elif (anthropic_api_key or "").strip():
        ai_client.save_api_key("claude", anthropic_api_key.strip())
    return RedirectResponse("/admin/ai-settings?saved=1", 303)


@app.post("/admin/ai-settings/test")
async def admin_ai_settings_test(req: Request):
    """두 공급사(OpenAI·Claude) 키를 각각 실제 호출 점검 + 음성→글자(Whisper, OpenAI) 가능 여부.
    각 키를 따로 검사하므로 둘 다 등록했을 때 각각 유효한지 한 번에 확인 가능."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return JSONResponse({"ok": False, "error": "forbidden"}, 403)
    from . import ai_client
    from starlette.concurrency import run_in_threadpool
    ki = ai_client.key_info()
    providers = {}
    for prov in ("openai", "claude"):
        if ki[prov]["set"]:
            ok, msg = await run_in_threadpool(lambda p=prov: ai_client.test_provider(p))
            providers[prov] = {"set": True, "ok": bool(ok), "masked": ki[prov]["masked"],
                               "msg": (msg or "")[:200]}
        else:
            providers[prov] = {"set": False, "ok": False, "masked": "", "msg": "미설정"}
    return JSONResponse({
        "ok": True,
        "providers": providers,
        "whisper": {"ok": bool(providers["openai"]["set"] and providers["openai"]["ok"])},
        "active_provider": ai_client.get_provider() or "(비활성)",
        "model": ai_client.default_model() if ai_client.get_provider() else "",
    })


def _a_prefix_prod_notif_ids(c) -> list:
    """v5H226z877 (대표 지시): 테스트(A접두) 제작요청 WORKS 알림(notifications kind='prod_request') id 목록.
    판정 = 알림 link(/project/{pid}/prod-request/edit)의 프로젝트 mgmt_code 가 A접두 OR 제목에 A접두 관리번호
    패턴(A+2자리+영문+4자리, 예 A01T2607) — 프로젝트가 이미 삭제됐어도 제목으로 커버."""
    import re as _re_n
    _rx = _re_n.compile(r"A\d{2}[A-Z]\d{4}")
    try:
        _a_pids = {r[0] for r in c.execute(
            "SELECT id FROM projects WHERE UPPER(COALESCE(mgmt_code,'')) LIKE 'A%'").fetchall()}
    except Exception:
        _a_pids = set()
    out = []
    try:
        for r in c.execute("SELECT id, title, link FROM notifications WHERE kind='prod_request'").fetchall():
            _id, _ttl, _lnk = r[0], (r[1] or ""), (r[2] or "")
            _m = _re_n.match(r"^/project/(\d+)/", _lnk)
            if (_m and int(_m.group(1)) in _a_pids) or _rx.search(_ttl):
                out.append(_id)
    except Exception:
        return []
    return out


def _prod_notif_ids_by_code(c, mgmt: str) -> list:
    """v5H226z879 (대표 지시): 특정 관리번호(mgmt)의 제작요청 WORKS 알림 id 목록 — 테스트 중 잘못 발행된 알림을
    관리번호로 지정해 전 직원 알림함에서 삭제. 판정 = 알림 link 의 프로젝트 mgmt_code == 그 관리번호 OR 제목에 그 관리번호 포함
    (프로젝트가 이미 삭제됐어도 제목으로 커버). A접두든 실코드든 정확히 지정한 것만."""
    import re as _re_c
    mc = (mgmt or "").strip().upper()
    if not mc:
        return []
    try:
        _pids = {r[0] for r in c.execute(
            "SELECT id FROM projects WHERE UPPER(COALESCE(mgmt_code,''))=?", (mc,)).fetchall()}
    except Exception:
        _pids = set()
    out = []
    try:
        for r in c.execute("SELECT id, title, link FROM notifications WHERE kind='prod_request'").fetchall():
            _id, _ttl, _lnk = r[0], (r[1] or ""), (r[2] or "")
            _m = _re_c.match(r"^/project/(\d+)/", _lnk)
            if (_m and int(_m.group(1)) in _pids) or (mc in (_ttl or "").upper()):
                out.append(_id)
    except Exception:
        return []
    return out


@app.get("/admin/test-data", response_class=HTMLResponse)
async def admin_test_data_page(req: Request):
    """v5H226z386 (대표 지시): 검증(테스트) 데이터 관리 — 검증 모드 토글(관리번호 A 접두 발급) + A 관리번호 일괄 삭제(서버 백업 없이 즉시).
    v5H226z877: 테스트 제작요청 WORKS 알림만 전 직원 알림함에서 삭제하는 버튼 추가."""
    u = require(req, ["admin", "ceo"])
    if not u:
        _au = get_user(req)
        return RedirectResponse(role_home(_au) if _au else "/login", 303)
    test_on = (get_setting("test_mode", "") or "").strip().lower() in ("1", "on", "true", "yes")
    with db_session() as c:
        a_total = c.execute("SELECT COUNT(*) FROM projects WHERE mgmt_code LIKE 'A%'").fetchone()[0]
        a_by_div = [dict(r) for r in c.execute(
            "SELECT substr(mgmt_code,4,1) AS div, COUNT(*) AS n FROM projects "
            "WHERE mgmt_code LIKE 'A%' GROUP BY substr(mgmt_code,4,1) ORDER BY div").fetchall()]
        a_notif = len(_a_prefix_prod_notif_ids(c))   # v5H226z877: 전 직원 알림함의 A접두 제작요청 알림 총 건수
    return ctx(req, "admin_test_data.html", user=u, active="admin",
               test_on=test_on, a_total=a_total, a_by_div=a_by_div, a_notif=a_notif,
               saved=(req.query_params.get("saved") == "1"),
               deleted=req.query_params.get("deleted"),
               notif_deleted=req.query_params.get("notif_deleted"),
               code_deleted=req.query_params.get("code_deleted"),
               code=req.query_params.get("code"),
               code_err=(req.query_params.get("code_err") == "1"))


