@app.post("/admin/ti-from-xlsx", response_class=HTMLResponse)
async def admin_ti_from_xlsx_apply(req: Request, xlsx: UploadFile = File(...)):
    """v5H226z659 (대표 지시): 위 폼 처리 — 기존 프로젝트에 세금계산서/거래명세서만 반영(생성 무·멱등)."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    def _esc(s):
        return (str(s) if s is not None else "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    try:
        body = await xlsx.read()
        rows = _proj_import_parse_xlsx(body)
    except Exception as e:
        return HTMLResponse("<meta charset='utf-8'><p>파싱 실패: " + _esc(str(e)) + "</p>")
    _ti_rows = []
    matched = 0
    unmatched = []
    with db_session() as c:
        for r in rows:
            _mc = (r.get("mgmt_code_input") or "").strip().upper()
            if not _mc:
                continue
            _pr = c.execute("SELECT id, customer_name FROM projects WHERE UPPER(mgmt_code)=? LIMIT 1", (_mc,)).fetchone()
            if not _pr:
                unmatched.append(_mc)
                continue
            _pid = _pr["id"] if isinstance(_pr, dict) else _pr[0]
            _pcust = (_pr["customer_name"] if isinstance(_pr, dict) else _pr[1]) or ""
            _sd = (str(r.get("statement_date") or ""))[:10]
            _ti = []
            for _k in (1, 2, 3):
                _d = (str(r.get("ti%d_date" % _k) or ""))[:10]
                if _d:
                    try:
                        _a = float(r.get("ti%d_amt" % _k) or 0)
                    except Exception:
                        _a = 0.0
                    _ti.append((_k, _d, str(r.get("ti%d_bundle" % _k) or "").strip(), _a))
            if not _sd and not _ti:
                continue
            matched += 1
            _ti_rows.append({"pid": _pid, "mgmt": _mc, "customer": (r.get("customer_name") or _pcust or ""),
                             "label": (r.get("model_name") or ""), "currency": (r.get("currency") or "KRW"),
                             "statement_date": _sd, "ti": _ti})
        # v5H226z660 (대표 지시): 묶음(작업일정표만 보임) 대신 호기(order_items)에 직접 기록 → 작업일정표·상세 동기화.
        ti_made = ti_lines = stmt_n = 0
        ti_warns = []
        removed_bundles = 0
        try:
            removed_bundles = _delete_import_ti_bundles(c)   # 기존 import 묶음 제거(보드 우선표시로 상세와 어긋남 방지)
            ti_made, ti_lines = _apply_import_ti_to_units(c, _ti_rows)
            stmt_n = sum(1 for tr in _ti_rows if tr.get("statement_date"))
        except Exception as _te:
            ti_warns.append(f"오류: {str(_te)[:120]}")
    _h = ["<meta charset='utf-8'><div style='font-family:system-ui,sans-serif;max-width:720px;margin:40px auto;color:#1f2937;'>",
          "<h2 style='color:#15803d;'>✅ 세금계산서 반영 완료 (호기에 기록 — 작업일정표·상세 동기화 / 프로젝트·수주는 안 건드림)</h2>",
          f"<p>매칭된 행 <b>{matched}</b> · 세금계산서 반영 <b>{ti_made}</b>건(차수 {ti_lines}) · 거래명세서 <b>{stmt_n}</b>건 · 기존 묶음 제거 <b>{removed_bundles}</b>장</p>"]
    if unmatched:
        _h.append(f"<p style='color:#b45309;'>미등록 관리번호 {len(unmatched)}건(반영 안 됨): " + _esc(", ".join(unmatched[:30])) + (" …" if len(unmatched) > 30 else "") + "</p>")
    if ti_warns:
        _h.append("<p style='color:#b91c1c;'>경고: " + _esc(" / ".join(ti_warns[:10])) + "</p>")
    _h.append("<p style='margin-top:16px;'><a href='/sales/schedule' style='color:#1d4ed8;'>작업일정표로</a></p></div>")
    return HTMLResponse("".join(_h))


@app.get("/admin/dup-so", response_class=HTMLResponse)
async def admin_dup_so(req: Request):
    """v5H226z659 (대표 지시): 재업로드로 생긴 '중복 수주(SO)' 진단 — 같은 프로젝트에 (발주일·납기·금액)이 같은 SO가 2개 이상이면
    가장 오래된 1개만 남기고 나머지(나중 생성=중복)를 후보로 표시. 읽기전용. 실행은 아래 버튼."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    def _esc(s):
        return (str(s) if s is not None else "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    from collections import defaultdict as _dd
    with db_session() as c:
        rows = [dict(r) for r in c.execute(
            "SELECT o.id AS oid, o.order_no AS sono, o.project_id AS pid, p.mgmt_code AS mc, p.name AS pname, "
            "COALESCE(o.order_date,'') AS od, COALESCE(o.due_date,'') AS dd, COALESCE(o.total_amount,0) AS amt, "
            "COALESCE(o.created_at,'') AS ca, COALESCE(o.status,'') AS st "
            "FROM orders o JOIN projects p ON p.id=o.project_id "
            "WHERE COALESCE(o.status,'')<>'CANCELLED' ORDER BY o.project_id, o.id").fetchall()]
    grp = _dd(list)
    for r in rows:
        grp[(r["pid"], r["od"], r["dd"], round(float(r["amt"] or 0)))].append(r)
    dups = []
    for _k, members in grp.items():
        if len(members) > 1:
            members.sort(key=lambda x: x["oid"])
            for d in members[1:]:
                dups.append((members[0], d))
    body = ["<meta charset='utf-8'><div style='font-family:Pretendard,system-ui,sans-serif;margin:24px 0;padding:0 24px;color:#1f2937;'>",
            "<h2>🧹 중복 수주(SO) 진단·정리</h2>",
            "<p style='color:#555;line-height:1.7;'>같은 프로젝트에 <b>발주일·납기·금액이 동일한 수주(SO)가 2개 이상</b>인 경우입니다(재업로드로 중복 생성된 흔적). "
            "가장 <b>오래된 1개(원본)는 보존</b>하고 나중에 생긴 것만 삭제 후보로 표시합니다. 아래 표를 확인하고 '중복 삭제 실행'을 누르세요.</p>"]
    if not dups:
        body.append("<p style='color:#15803d;font-weight:700;padding:14px;background:#f0fdf4;border-radius:8px;'>✅ 중복 수주 없음.</p></div>")
        return HTMLResponse("".join(body))
    body.append("<p style='font-size:16px;'>삭제 후보(중복) <b style='color:#b91c1c;'>" + str(len(dups)) + "건</b> · 원본은 보존</p>")
    body.append("<form method='post' action='/admin/dup-so' onsubmit=\"return confirm('중복 수주 " + str(len(dups)) + "건을 삭제합니다(원본 보존). 되돌릴 수 없습니다. 진행할까요?');\" style='margin:8px 0 18px;'>"
                "<input type='hidden' name='confirm' value='중복정리'>"
                "<button type='submit' style='padding:9px 18px;background:#b91c1c;color:#fff;border:0;border-radius:8px;font-size:14px;font-weight:800;cursor:pointer;'>🗑 중복 삭제 실행 (" + str(len(dups)) + "건)</button></form>")
    body.append("<table style='border-collapse:collapse;font-size:12px;width:100%;'><thead><tr>"
                + "".join("<th style='border-bottom:2px solid #ddd;padding:5px;text-align:left;'>" + h + "</th>"
                          for h in ("관리번호", "프로젝트", "보존 SO(원본)", "생성일", "삭제 SO(중복)", "생성일", "금액")) + "</tr></thead><tbody>")
    for keep, d in dups[:600]:
        body.append("<tr>"
                    + "<td style='border-bottom:1px solid #eee;padding:4px;font-family:monospace;'>" + _esc(d.get("mc")) + "</td>"
                    + "<td style='border-bottom:1px solid #eee;padding:4px;'>" + _esc(d.get("pname")) + "</td>"
                    + "<td style='border-bottom:1px solid #eee;padding:4px;color:#15803d;'>" + _esc(keep.get("sono")) + "</td>"
                    + "<td style='border-bottom:1px solid #eee;padding:4px;'>" + _esc(str(keep.get("ca"))[:16]) + "</td>"
                    + "<td style='border-bottom:1px solid #eee;padding:4px;color:#b91c1c;font-weight:700;'>" + _esc(d.get("sono")) + "</td>"
                    + "<td style='border-bottom:1px solid #eee;padding:4px;'>" + _esc(str(d.get("ca"))[:16]) + "</td>"
                    + "<td style='border-bottom:1px solid #eee;padding:4px;'>" + _esc("{:,.0f}".format(float(d.get('amt') or 0))) + "</td></tr>")
    body.append("</tbody></table>")
    if len(dups) > 600:
        body.append("<p style='color:#888;'>… 외 " + str(len(dups) - 600) + "건 (실행 시 전체 삭제)</p>")
    body.append("</div>")
    return HTMLResponse("".join(body))


@app.post("/admin/dup-so")
async def admin_dup_so_apply(req: Request):
    """v5H226z659 (대표 지시): 중복 수주(SO) 삭제 실행 — 각 (프로젝트·발주일·납기·금액) 그룹의 최오래된 1개 보존, 나머지 삭제."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    form = await req.form()
    if (form.get("confirm") or "").strip() != "중복정리":
        return RedirectResponse("/admin/dup-so", 303)
    from collections import defaultdict as _dd
    deleted = 0
    errs = []
    with db_session() as c:
        rows = [dict(r) for r in c.execute(
            "SELECT o.id AS oid, o.project_id AS pid, COALESCE(o.order_date,'') AS od, "
            "COALESCE(o.due_date,'') AS dd, COALESCE(o.total_amount,0) AS amt "
            "FROM orders o WHERE COALESCE(o.status,'')<>'CANCELLED' ORDER BY o.project_id, o.id").fetchall()]
        grp = _dd(list)
        for r in rows:
            grp[(r["pid"], r["od"], r["dd"], round(float(r["amt"] or 0)))].append(r["oid"])
        del_ids = []
        for _k, ids in grp.items():
            if len(ids) > 1:
                ids.sort()
                del_ids.extend(ids[1:])   # 최오래(최소 id) 보존, 나머지 삭제
        for _oid in del_ids:
            try:
                _pwf.delete_order(c, _oid, restore_project=True)
                deleted += 1
            except Exception as _e:
                errs.append(f"SO#{_oid}: {str(_e)[:60]}")
    _h = ["<meta charset='utf-8'><div style='font-family:system-ui,sans-serif;max-width:700px;margin:48px auto;text-align:center;color:#1f2937;'>",
          "<h2 style='color:#15803d;'>✅ 중복 수주 " + str(deleted) + "건 삭제 완료</h2>",
          "<p>각 프로젝트의 원본(가장 오래된 SO)은 보존했습니다.</p>"]
    if errs:
        _h.append("<p style='color:#b91c1c;'>일부 실패: " + str(len(errs)) + "건</p>")
    _h.append("<p style='margin-top:16px;'><a href='/sales/schedule' style='color:#1d4ed8;'>작업일정표로</a> · <a href='/admin/dup-so' style='color:#1d4ed8;'>다시 보기</a></p></div>")
    return HTMLResponse("".join(_h))


@app.get("/admin/ship-overdue", response_class=HTMLResponse)
async def admin_ship_overdue(req: Request):
    """v5H226z658 (대표 지시): 납품일이 오늘 이전(지난) 호기/품목을 일괄 '출하' 처리 — 미리보기(읽기전용).
    대상 = 취소 아닌 SO 의 order_items 중 unit_status 가 출하·취소가 아니고, 유효 납품일(호기 override 우선)이 오늘보다 과거인 건."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    from datetime import datetime as _dt
    today = _dt.now().strftime("%Y-%m-%d")   # 본사 KST(서버 로컬)
    def _esc(s):
        return (str(s) if s is not None else "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    _DUE = "COALESCE(NULLIF(TRIM(oi.due_date),''), o.due_date)"
    rows = []
    with db_session() as c:
        try:
            rows = [dict(r) for r in c.execute(
                "SELECT oi.unit_label AS lbl, COALESCE(oi.unit_status,'') AS ust, " + _DUE + " AS eff_due, "
                "       p.mgmt_code AS mc, p.name AS pname, p.customer_name AS cust, "
                "       COALESCE(p.shipment_form,'ASSEMBLY') AS sf "
                "FROM order_items oi JOIN orders o ON o.id=oi.order_id JOIN projects p ON p.id=o.project_id "
                "WHERE COALESCE(o.status,'')<>'CANCELLED' "
                "  AND COALESCE(oi.unit_status,'') NOT IN ('출하','취소') "
                "  AND COALESCE(" + _DUE + ",'')<>'' AND " + _DUE + " < ? "
                "ORDER BY eff_due, p.mgmt_code", (today,)
            ).fetchall()]
        except Exception as e:
            return HTMLResponse("<meta charset='utf-8'><p>조회 오류: " + _esc(str(e)) + "</p>")
    _sfk = {"ASSEMBLY": "완제품", "SEMI": "제품", "PARTS": "상품", "ETC": "기타"}
    body = ["<meta charset='utf-8'><div style='font-family:Pretendard,system-ui,sans-serif;margin:24px 0;padding:0 24px;color:#1f2937;'>",
            "<h2>🚚 납품일 지난 건 일괄 출하 (미리보기)</h2>",
            "<p style='color:#555;line-height:1.7;'>오늘(<b>" + today + "</b>) 기준 <b>납품일이 지난</b> 호기/품목 중 아직 '출하'·'취소'가 아닌 건입니다. "
            "'출하 처리 실행'을 누르면 모두 <b>출하</b> 상태로 바꿉니다. (정식 출하전표가 아닌, 작업일정표 상태 변경 — 되돌리려면 해당 행 상태를 다시 변경)</p>"]
    if not rows:
        body.append("<p style='color:#15803d;font-weight:700;padding:14px;background:#f0fdf4;border-radius:8px;'>✅ 대상 없음 — 납품일 지난 미출하 건이 없습니다.</p></div>")
        return HTMLResponse("".join(body))
    body.append("<p style='font-size:16px;'>대상 <b style='color:#b45309;'>" + str(len(rows)) + "건</b></p>")
    body.append("<form method='post' action='/admin/ship-overdue' "
                "onsubmit=\"return confirm('대상 " + str(len(rows)) + "건을 모두 출하 처리합니다. 진행할까요?');\" style='margin:8px 0 18px;'>"
                "<input type='hidden' name='confirm' value='출하처리'>"
                "<button type='submit' style='padding:9px 18px;background:#15803d;color:#fff;border:0;border-radius:8px;font-size:14px;font-weight:800;cursor:pointer;'>🚚 출하 처리 실행 (" + str(len(rows)) + "건)</button></form>")
    body.append("<table style='border-collapse:collapse;font-size:12.5px;width:100%;'><thead><tr>"
                + "".join("<th style='border-bottom:2px solid #ddd;padding:6px;text-align:left;'>" + h + "</th>"
                          for h in ("관리번호", "프로젝트", "형태", "호기/품목", "현재상태", "납품일", "고객사")) + "</tr></thead><tbody>")
    for d in rows[:500]:
        body.append("<tr>"
                    + "<td style='border-bottom:1px solid #eee;padding:5px;font-family:monospace;'>" + _esc(d.get("mc")) + "</td>"
                    + "<td style='border-bottom:1px solid #eee;padding:5px;'>" + _esc(d.get("pname")) + "</td>"
                    + "<td style='border-bottom:1px solid #eee;padding:5px;'>" + _esc(_sfk.get((d.get("sf") or "").upper(), d.get("sf"))) + "</td>"
                    + "<td style='border-bottom:1px solid #eee;padding:5px;'>" + _esc(d.get("lbl")) + "</td>"
                    + "<td style='border-bottom:1px solid #eee;padding:5px;'>" + _esc(d.get("ust") or "진행중") + "</td>"
                    + "<td style='border-bottom:1px solid #eee;padding:5px;'>" + _esc(str(d.get("eff_due"))[:10]) + "</td>"
                    + "<td style='border-bottom:1px solid #eee;padding:5px;'>" + _esc(d.get("cust")) + "</td></tr>")
    body.append("</tbody></table>")
    if len(rows) > 500:
        body.append("<p style='color:#888;'>… 외 " + str(len(rows) - 500) + "건 (실행 시 전체 처리)</p>")
    body.append("</div>")
    return HTMLResponse("".join(body))


@app.post("/admin/ship-overdue")
async def admin_ship_overdue_apply(req: Request):
    """v5H226z658 (대표 지시): 납품일 지난 호기/품목 일괄 출하 실행(unit_status='출하'). confirm 토큰 필요."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    form = await req.form()
    if (form.get("confirm") or "").strip() != "출하처리":
        return RedirectResponse("/admin/ship-overdue", 303)
    from datetime import datetime as _dt
    today = _dt.now().strftime("%Y-%m-%d")
    _DUE = "COALESCE(NULLIF(TRIM(oi.due_date),''), o.due_date)"
    n = 0
    with db_session() as c:
        _ids = [(r[0] if not isinstance(r, dict) else r["id"]) for r in c.execute(
            "SELECT oi.id FROM order_items oi JOIN orders o ON o.id=oi.order_id "
            "WHERE COALESCE(o.status,'')<>'CANCELLED' "
            "  AND COALESCE(oi.unit_status,'') NOT IN ('출하','취소') "
            "  AND COALESCE(" + _DUE + ",'')<>'' AND " + _DUE + " < ?", (today,)
        ).fetchall()]
        for _iid in _ids:
            try:
                c.execute("UPDATE order_items SET unit_status='출하' WHERE id=?", (_iid,))
                n += 1
            except Exception:
                pass
    return HTMLResponse("<meta charset='utf-8'><div style='font-family:system-ui,sans-serif;max-width:680px;margin:48px auto;text-align:center;color:#1f2937;'>"
                        "<h2 style='color:#15803d;'>✅ " + str(n) + "건 출하 처리 완료</h2>"
                        "<p>납품일이 " + today + " 이전인 호기/품목을 '출하'로 변경했습니다.</p>"
                        "<p style='margin-top:18px;'><a href='/sales/schedule' style='color:#1d4ed8;'>작업일정표로</a> &nbsp;·&nbsp; "
                        "<a href='/admin/ship-overdue' style='color:#1d4ed8;'>다시 보기</a></p></div>")


def _so_no_to_date(so_no):
    """z1017: 수주번호에서 YYMMDD를 뽑아 ISO 날짜(YYYY-MM-DD). 표준 [사업부]-YYMMDD-N(예: M-260707-1).
    유효 날짜만 반환(2/30 등 무효는 date()가 걸러 ''). 못 뽑으면 ''."""
    if not so_no:
        return ""
    import re as _re
    from datetime import date as _date
    s = str(so_no).strip()
    m = _re.search(r"-(\d{6})-", s) or _re.search(r"(?<!\d)(\d{6})(?!\d)", s)
    if not m:
        return ""
    g = m.group(1)
    try:
        return _date(2000 + int(g[:2]), int(g[2:4]), int(g[4:6])).isoformat()
    except Exception:
        return ""


@app.get("/admin/order-dates-audit", response_class=HTMLResponse)
async def admin_order_dates_audit(req: Request):
    """z1017 (대표 지시): 발주일(order_date) 누락 진단·백필 미리보기(읽기전용).
    작업일정표는 발주일·납기가 둘 다 없으면 그 행을 숨김 → 발주일 없는 건이 '갑자기 사라짐'.
    이 화면은 ① 발주일 빈 주문(orders) ② 발주일 빈 프로젝트(projects)를 수주번호(YYMMDD)에서 날짜를 뽑아
    채울 목록으로 보여주고(적용은 아래 버튼), ③ 납기일 빈 건은 자동으로 안 채우고 대표 수동입력용 목록으로만 표시."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)

    def _esc(s):
        return (str(s) if s is not None else "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

    def _thead(headers):
        return ("<table style='border-collapse:collapse;font-size:12.5px;width:100%;margin:6px 0 18px;'><thead><tr>"
                + "".join("<th style='border-bottom:2px solid #ddd;padding:6px;text-align:left;'>" + h + "</th>" for h in headers)
                + "</tr></thead><tbody>")

    def _tr(cells):
        return "<tr>" + "".join("<td style='border-bottom:1px solid #eee;padding:5px;'>" + x + "</td>" for x in cells) + "</tr>"

    def _mono(x):
        return "<span style='font-family:monospace;'>" + _esc(x) + "</span>"

    orders_fill, orders_noparse, projs_fill, projs_noparse = [], [], [], []
    with db_session() as c:
        _orows = [dict(r) for r in c.execute(
            "SELECT o.id AS oid, COALESCE(o.order_no,'') AS sono, o.project_id AS pid, "
            "COALESCE(p.mgmt_code,'') AS mc, COALESCE(p.name,'') AS pname, COALESCE(p.customer_name,'') AS cust "
            "FROM orders o LEFT JOIN projects p ON p.id=o.project_id "
            "WHERE COALESCE(o.status,'')<>'CANCELLED' "
            "  AND (o.order_date IS NULL OR TRIM(o.order_date)='') "
            "ORDER BY o.project_id, o.id").fetchall()]
        for r in _orows:
            d = _so_no_to_date(r["sono"])
            (orders_fill if d else orders_noparse).append((r, d))
        # 프로젝트별 최소 SO 날짜 맵(한 번에) — 발주일 빈 프로젝트에 '최초 수주' 날짜를 채우기 위함
        proj_min = {}
        for r in [dict(x) for x in c.execute(
            "SELECT project_id AS pid, COALESCE(order_no,'') AS sono FROM orders "
            "WHERE project_id IS NOT NULL AND COALESCE(status,'')<>'CANCELLED'").fetchall()]:
            d = _so_no_to_date(r["sono"])
            if d and (r["pid"] not in proj_min or d < proj_min[r["pid"]]):
                proj_min[r["pid"]] = d
        _prows = [dict(r) for r in c.execute(
            "SELECT id AS pid, COALESCE(mgmt_code,'') AS mc, COALESCE(name,'') AS pname, COALESCE(customer_name,'') AS cust "
            "FROM projects WHERE (order_date IS NULL OR TRIM(order_date)='') ORDER BY id").fetchall()]
        for r in _prows:
            d = proj_min.get(r["pid"], "")
            (projs_fill if d else projs_noparse).append((r, d))
        due_empty = [dict(r) for r in c.execute(
            "SELECT o.id AS oid, COALESCE(o.order_no,'') AS sono, COALESCE(p.mgmt_code,'') AS mc, "
            "COALESCE(p.name,'') AS pname, COALESCE(p.customer_name,'') AS cust, COALESCE(o.status,'') AS st, "
            "COALESCE(o.order_date,'') AS od "
            "FROM orders o LEFT JOIN projects p ON p.id=o.project_id "
            "WHERE COALESCE(o.status,'')<>'CANCELLED' AND (o.due_date IS NULL OR TRIM(o.due_date)='') "
            "ORDER BY o.project_id, o.id").fetchall()]

    n_of, n_onp, n_pf, n_pnp, n_due = len(orders_fill), len(orders_noparse), len(projs_fill), len(projs_noparse), len(due_empty)
    body = ["<meta charset='utf-8'><div style='font-family:Pretendard,system-ui,sans-serif;margin:24px 0;padding:0 24px;color:#1f2937;'>",
            "<h2>📅 발주일 누락 진단·백필 (미리보기)</h2>",
            "<p style='color:#555;line-height:1.7;'>작업일정표는 <b>발주일·납기가 둘 다 없으면</b> 그 항목을 숨깁니다(그래서 '있던 게 갑자기 안 보임'). "
            "아래 <b>발주일이 빈 건</b>을 <b>수주번호에서 날짜를 뽑아</b>(예: <code>M-260707-1 → 2026-07-07</code>) 채웁니다. "
            "<b>납기일은 자동으로 채우지 않고</b> 목록으로만 알려드립니다(대표님이 직접 입력). 소모품(별도 표)은 이 화면 대상 아님.</p>",
            "<div style='background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;padding:14px 16px;margin:10px 0 6px;line-height:2;'>"
            "<b>발주일 채울 주문</b> : <b style='color:#15803d;'>" + str(n_of) + "건</b>"
            + ("  <span style='color:#b45309;'>(수주번호로 날짜 못 뽑음 " + str(n_onp) + "건)</span>" if n_onp else "") + "<br>"
            "<b>발주일 채울 프로젝트</b> : <b style='color:#15803d;'>" + str(n_pf) + "건</b>"
            + ("  <span style='color:#b45309;'>(못 뽑음 " + str(n_pnp) + "건)</span>" if n_pnp else "") + "<br>"
            "<b>납기일 없음</b>(대표 입력용·자동 안 채움) : <b style='color:#b91c1c;'>" + str(n_due) + "건</b></div>"]
    if not (n_of or n_pf):
        body.append("<p style='color:#15803d;font-weight:700;padding:14px;background:#f0fdf4;border-radius:8px;'>✅ 발주일 백필 대상 없음.</p>")
    else:
        body.append("<form method='post' action='/admin/order-dates-audit' "
                    "onsubmit=\"return confirm('발주일을 주문 " + str(n_of) + "건, 프로젝트 " + str(n_pf) + "건에 채웁니다(수주번호 날짜). 납기일은 손대지 않습니다. 진행할까요?');\" style='margin:10px 0 20px;'>"
                    "<input type='hidden' name='confirm' value='발주일백필'>"
                    "<button type='submit' style='padding:10px 20px;background:#15803d;color:#fff;border:0;border-radius:8px;font-size:14px;font-weight:800;cursor:pointer;'>📅 발주일 백필 실행 (주문 " + str(n_of) + " · 프로젝트 " + str(n_pf) + "건)</button></form>")
    if orders_fill:
        body.append("<h3 style='margin:18px 0 4px;'>발주일 채울 주문 (" + str(n_of) + ")</h3>")
        body.append(_thead(("관리번호", "프로젝트", "고객사", "수주번호", "→ 채울 발주일")))
        for (r, d) in orders_fill[:600]:
            body.append(_tr([_mono(r["mc"]), _esc(r["pname"]), _esc(r["cust"]), _mono(r["sono"]), "<b style='color:#15803d;'>" + _esc(d) + "</b>"]))
        body.append("</tbody></table>")
        if n_of > 600:
            body.append("<p style='color:#888;'>… 외 " + str(n_of - 600) + "건 (실행 시 전체 처리)</p>")
    if projs_fill:
        body.append("<h3 style='margin:18px 0 4px;'>발주일 채울 프로젝트 (" + str(n_pf) + ") — 최초 수주번호 기준</h3>")
        body.append(_thead(("관리번호", "프로젝트", "고객사", "→ 채울 발주일")))
        for (r, d) in projs_fill[:600]:
            body.append(_tr([_mono(r["mc"]), _esc(r["pname"]), _esc(r["cust"]), "<b style='color:#15803d;'>" + _esc(d) + "</b>"]))
        body.append("</tbody></table>")
        if n_pf > 600:
            body.append("<p style='color:#888;'>… 외 " + str(n_pf - 600) + "건</p>")
    if orders_noparse or projs_noparse:
        body.append("<h3 style='margin:18px 0 4px;color:#b45309;'>⚠ 수주번호로 날짜 못 뽑음 (수동 확인 필요)</h3>")
        body.append(_thead(("종류", "관리번호", "프로젝트", "수주번호")))
        for (r, d) in orders_noparse[:200]:
            body.append(_tr(["주문", _mono(r["mc"]), _esc(r["pname"]), _mono(r["sono"])]))
        for (r, d) in projs_noparse[:200]:
            body.append(_tr(["프로젝트", _mono(r["mc"]), _esc(r["pname"]), "(연결 수주 없음/파싱불가)"]))
        body.append("</tbody></table>")
    if due_empty:
        body.append("<h3 style='margin:22px 0 4px;color:#b91c1c;'>납기일(due_date) 없는 건 — 대표님 직접 입력용 (" + str(n_due) + ")</h3>")
        body.append("<p style='color:#777;margin:0 0 6px;'>이 목록은 <b>자동으로 채우지 않습니다.</b> 각 건의 납기를 확인해 작업일정표/수주에서 입력해 주세요.</p>")
        body.append(_thead(("관리번호", "프로젝트", "고객사", "수주번호", "상태", "발주일")))
        for r in due_empty[:800]:
            body.append(_tr([_mono(r["mc"]), _esc(r["pname"]), _esc(r["cust"]), _mono(r["sono"]), _esc(r["st"] or "진행중"), _esc(r["od"])]))
        body.append("</tbody></table>")
        if n_due > 800:
            body.append("<p style='color:#888;'>… 외 " + str(n_due - 800) + "건</p>")
    body.append("<p style='margin-top:20px;'><a href='/sales/schedule' style='color:#1d4ed8;'>작업일정표로</a></p></div>")
    return HTMLResponse("".join(body))


@app.post("/admin/order-dates-audit")
async def admin_order_dates_audit_apply(req: Request):
    """z1017 (대표 지시): 발주일 백필 실행 — 발주일 빈 주문/프로젝트에 수주번호(YYMMDD) 날짜 채움.
    납기일(due_date)은 절대 손대지 않음. confirm 토큰 '발주일백필' 필요."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    form = await req.form()
    if (form.get("confirm") or "").strip() != "발주일백필":
        return RedirectResponse("/admin/order-dates-audit", 303)
    n_ord, n_proj = 0, 0
    with db_session() as c:
        _o = [dict(r) for r in c.execute(
            "SELECT id, COALESCE(order_no,'') AS sono FROM orders "
            "WHERE COALESCE(status,'')<>'CANCELLED' AND (order_date IS NULL OR TRIM(order_date)='')").fetchall()]
        proj_min = {}
        for r in [dict(x) for x in c.execute(
            "SELECT project_id AS pid, COALESCE(order_no,'') AS sono FROM orders "
            "WHERE project_id IS NOT NULL AND COALESCE(status,'')<>'CANCELLED'").fetchall()]:
            d = _so_no_to_date(r["sono"])
            if d and (r["pid"] not in proj_min or d < proj_min[r["pid"]]):
                proj_min[r["pid"]] = d
        _p = [dict(r) for r in c.execute(
            "SELECT id FROM projects WHERE (order_date IS NULL OR TRIM(order_date)='')").fetchall()]
        for r in _o:
            d = _so_no_to_date(r["sono"])
            if d:
                c.execute("UPDATE orders SET order_date=? WHERE id=?", (d, r["id"]))
                n_ord += 1
        for r in _p:
            d = proj_min.get(r["id"], "")
            if d:
                c.execute("UPDATE projects SET order_date=? WHERE id=?", (d, r["id"]))
                n_proj += 1
    return HTMLResponse("<meta charset='utf-8'><div style='font-family:system-ui,sans-serif;max-width:700px;margin:48px auto;text-align:center;color:#1f2937;'>"
                        "<h2 style='color:#15803d;'>✅ 발주일 백필 완료</h2>"
                        "<p>주문 <b>" + str(n_ord) + "건</b>, 프로젝트 <b>" + str(n_proj) + "건</b>의 발주일을 수주번호 날짜로 채웠습니다.</p>"
                        "<p style='color:#777;'>납기일은 변경하지 않았습니다(없는 건은 미리보기 목록 참조·직접 입력).</p>"
                        "<p style='margin-top:18px;'><a href='/sales/schedule' style='color:#1d4ed8;'>작업일정표로</a> &nbsp;·&nbsp; "
                        "<a href='/admin/order-dates-audit' style='color:#1d4ed8;'>다시 보기</a></p></div>")


@app.get("/admin/so-audit-dump")
async def admin_so_audit_dump(req: Request, like: str = "T", dl: str = "", mode: str = ""):
    """z1061 (대표 지시): 일괄등록 엑셀 원본 ↔ 저장값 전수 대조용 **읽기전용** 덤프.
    프로젝트 SO별로 저장된 모델명·장비명(SO값 없으면 프로젝트 대표 폴백=화면 표시값)·형태·수량·단가·금액을 JSON.
    (엑셀 export 는 현재 월만 뽑아 전수 대조 불가 → 전체를 한 번에.) 전부 SELECT·아무것도 안 바꿈.
    v5H226z1062: mode=board — 실제 작업일정표 조립함수(_board_split_lines_map)가 뽑는 **줄 그대로** 노출
      + 그 줄의 order_items(iids) 수량합(correct_qty) 계산. 화면에 보이는 수량(board_qty) vs 실제 수량(correct_qty)을
      대조해 '수량 표시버그' 영향 줄을 지상검증(추정 배제). 역시 전부 SELECT + 순수 표시함수 호출(무변경)."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    _like = f"%{(like or '').strip()}%" if (like or "").strip() else "%"
    if (mode or "").strip() == "board":
        # v5H226z1062: 작업일정표 실제 줄 노출(읽기전용) — board_qty(화면 수량) vs correct_qty(order_items 수량합) 대조.
        with db_session() as c:
            _pmap = {r["id"]: (r["mc"] or "") for r in c.execute(
                "SELECT id, COALESCE(mgmt_code,'') AS mc FROM projects WHERE COALESCE(mgmt_code,'') LIKE ?", (_like,)).fetchall()}
            _qmap = {r["id"]: int(r["q"] or 1) for r in c.execute(
                "SELECT id, COALESCE(qty,1) AS q FROM order_items").fetchall()}
        _brows = []
        _bmap = _board_split_lines_map(unfold_sos=True, pids=list(_pmap.keys()))   # 순수 조립(자체 커넥션·무변경)
        for _pid, _lines in _bmap.items():
            _mc = _pmap.get(_pid, "")
            for _ln in _lines:
                _iids = _ln.get("iids") or ([_ln.get("iid")] if _ln.get("iid") else [])
                _correct = (sum(_qmap.get(i, 1) for i in _iids) if _iids else None)
                _bq = _ln.get("qty")
                _brows.append({
                    "mc": _mc, "sono": _ln.get("so_no") or "", "so_type": _ln.get("so_type") or "",
                    "form_label": _ln.get("form_label") or "", "board_qty": _bq, "correct_qty": _correct,
                    "n_iids": len(_iids), "mismatch": (_correct is not None and int(_bq or 0) != int(_correct or 0)),
                    "price": _ln.get("price"), "amount": _ln.get("amount"), "ccy": _ln.get("currency") or "",
                    "label": _ln.get("label") or "",
                })
        _mism = sum(1 for _b in _brows if _b["mismatch"])
        _resp = JSONResponse({"ok": True, "mode": "board", "count": len(_brows), "mismatch_n": _mism, "rows": _brows})
        if (dl or "").strip():
            _resp.headers["Content-Disposition"] = 'attachment; filename="so_board_lines.json"'
        return _resp
    out = []
    with db_session() as c:
        for r in c.execute(
            "SELECT o.id AS oid, p.mgmt_code AS mc, COALESCE(o.order_no,'') AS sono, "   # v5H226z1064: order id(백필 대상 정확 지정용)
            "substr(COALESCE(NULLIF(TRIM(o.order_date),''),NULLIF(TRIM(p.order_date),''),''),1,10) AS od, "   # z1164: 빈 글자 = 빈칸
            "COALESCE(NULLIF(o.model_name,''), p.model_name, '') AS model, "        # 화면 표시 모델(SO값 우선, 없으면 대표)
            "COALESCE(NULLIF(o.equip_name,''), p.equip_name, '') AS equip, "        # 화면 표시 장비(SO값 우선, 없으면 대표)
            "COALESCE(o.model_name,'') AS so_model, COALESCE(o.equip_name,'') AS so_equip, "  # SO 자체값(빈값 여부 판별)
            "COALESCE(o.so_form,'') AS sf, COALESCE(o.total_amount,0) AS total, "
            "COALESCE(NULLIF(TRIM(o.currency),''), NULLIF(TRIM(p.currency),''), 'KRW') AS ccy, "   # z1164: 빈 글자 = 빈칸
            "(SELECT COALESCE(SUM(COALESCE(oi.qty,1)),0) FROM order_items oi WHERE oi.order_id=o.id) AS qty, "
            "(SELECT COUNT(*) FROM order_items oi WHERE oi.order_id=o.id) AS oi_n, "
            "(SELECT GROUP_CONCAT(COALESCE(NULLIF(oi.line_note,''), oi.unit_label), ' | ') "
            " FROM order_items oi WHERE oi.order_id=o.id) AS notes "
            "FROM orders o JOIN projects p ON p.id=o.project_id "
            "WHERE COALESCE(o.status,'')<>'CANCELLED' AND COALESCE(p.mgmt_code,'') LIKE ? "
            "ORDER BY p.mgmt_code, o.id", (_like,)).fetchall():
            out.append(dict(r))
    _resp = JSONResponse({"ok": True, "count": len(out), "rows": out})
    if (dl or "").strip():   # dl=1 → 브라우저가 파일로 저장(전수 대조용·get_page_text 5만자 잘림 회피)
        _resp.headers["Content-Disposition"] = 'attachment; filename="so_audit_dump.json"'
    return _resp


@app.post("/admin/so-fill-model-equip")
async def admin_so_fill_model_equip(req: Request):
    """v5H226z1064 (대표 지시·부분수정): 수주(SO)별 모델명·장비명 '빈칸만' 채움.
    ⭐서버는 매칭을 하지 않는다 — 어느 SO를 어떤 값으로 채울지는 로컬(원본 엑셀↔덤프)에서 전수 검토해
      정확한 order id(oid) 목록으로 넘긴다. 여기선 그 oid 에 대해서만 COALESCE(NULLIF(...))로 빈 곳을 채운다.
    ⛔상태·통화·세금계산서·거래명세서·고객사는 절대 건드리지 않음(원본 재업로드의 부작용 회피).
    dry=true → 아무것도 안 바꾸고 '바뀔 것'만 계산해 돌려줌(미리보기). 이미 값 있으면 안 덮음(빈칸만)."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return JSONResponse({"ok": False, "error": "login"}, 401)
    try:
        body = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "invalid_json"}, 400)
    pairs = body.get("pairs") or []
    dry = bool(body.get("dry"))
    if not isinstance(pairs, list) or not pairs:
        return JSONResponse({"ok": False, "error": "no_pairs"}, 400)
    applied = 0
    changed = []       # 실제(또는 예정) 변경 — oid·수주번호·채울 값
    skipped = 0        # 대상 없음/이미 채워짐
    with db_session() as c:
        for p in pairs:
            try:
                oid = int(p.get("oid"))
            except Exception:
                skipped += 1
                continue
            _m = (str(p.get("model") or "").strip() or None)
            _e = (str(p.get("equip") or "").strip() or None)
            if not _m and not _e:
                skipped += 1
                continue
            row = c.execute("SELECT COALESCE(model_name,'') AS m, COALESCE(equip_name,'') AS e, "
                            "COALESCE(order_no,'') AS sono FROM orders WHERE id=?", (oid,)).fetchone()
            if not row:
                skipped += 1
                continue
            _will_m = (_m if (not row["m"] and _m) else None)   # 빈 곳만
            _will_e = (_e if (not row["e"] and _e) else None)
            if not _will_m and not _will_e:
                skipped += 1
                continue
            changed.append({"oid": oid, "sono": row["sono"], "model": _will_m, "equip": _will_e})
            if not dry:
                # v5H226z981 과 동일한 '빈칸만 채움' UPDATE — 이미 값 있으면 보존.
                c.execute("UPDATE orders SET model_name=COALESCE(NULLIF(model_name,''),?), "
                          "equip_name=COALESCE(NULLIF(equip_name,''),?) WHERE id=?",
                          (_will_m, _will_e, oid))
                applied += 1
    return JSONResponse({"ok": True, "dry": dry, "input": len(pairs),
                         "applied": applied, "would_change": len(changed),
                         "skipped": skipped, "sample": changed[:8]})


@app.get("/admin/model-equip-fix", response_class=HTMLResponse)
async def admin_model_equip_fix_page(req: Request):
    """v5H226z1064 (대표 지시·부분수정): 로컬에서 만든 pairs JSON(oid·model·equip)을 올려
    수주별 모델·장비 '빈칸만' 채우는 작은 화면. 미리보기(dry)로 바뀔 건수 확인 후 적용.
    ⛔상태·통화·세금계산서·고객사 무변경. 서버는 매칭 안 함(매칭·검토는 로컬 대조에서 끝냄)."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    return HTMLResponse(
        "<meta charset='utf-8'><title>모델·장비 빈칸 채움</title>"
        "<div style='font-family:system-ui,sans-serif;margin:30px 0;padding:0 24px;color:#1f2937;'>"
        "<h2>🔧 수주별 모델·장비 빈칸 채움 <span style='font-size:14px;color:#64748b;'>(부분수정·z1064)</span></h2>"
        "<p style='color:#555;line-height:1.7;'>로컬에서 만든 <b>pairs JSON</b>(oid·model·equip 목록)을 올려 "
        "수주(SO)의 <b>모델·장비 빈칸만</b> 채웁니다. 상태·통화·세금계산서·고객사는 <b>건드리지 않습니다</b>. "
        "먼저 <b>미리보기</b>로 바뀔 건수를 확인하세요. 이미 값이 있으면 덮어쓰지 않습니다.</p>"
        "<input type='file' id='f' accept='.json,application/json'>"
        "<div style='margin:14px 0;'>"
        "<button id='dry' style='padding:8px 16px;font-weight:700;cursor:pointer;'>미리보기(dry)</button> "
        "<button id='apply' style='padding:8px 16px;font-weight:700;background:#b91c1c;color:#fff;border:0;border-radius:6px;cursor:pointer;'>적용</button>"
        "</div>"
        "<pre id='out' style='background:#0b1020;color:#d6e2ff;padding:14px;border-radius:8px;white-space:pre-wrap;font-size:13px;min-height:60px;'></pre>"
        "</div>"
        "<script>"
        "var PAIRS=null;"
        "function $(i){return document.getElementById(i);}"
        "$('f').addEventListener('change',function(e){var file=e.target.files[0];if(!file){return;}"
        "var rd=new FileReader();rd.onload=function(){try{PAIRS=JSON.parse(rd.result);$('out').textContent='읽음: '+PAIRS.length+'건 (미리보기부터 눌러 확인하세요)';}catch(err){PAIRS=null;$('out').textContent='JSON 파싱 실패: '+err;}};rd.readAsText(file);});"
        "function send(dry){if(!PAIRS){$('out').textContent='먼저 파일을 고르세요.';return;}"
        "if(!dry && !confirm('실제로 '+PAIRS.length+'건의 빈 모델·장비를 채웁니다. 진행할까요?')){return;}"
        "$('out').textContent=(dry?'미리보기':'적용')+' 중...';"
        "fetch('/admin/so-fill-model-equip',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify({dry:dry,pairs:PAIRS})})"
        ".then(function(r){return r.json();}).then(function(j){$('out').textContent=JSON.stringify(j,null,2);})"
        ".catch(function(err){$('out').textContent='요청 실패: '+err;});}"
        "$('dry').onclick=function(){send(true);};$('apply').onclick=function(){send(false);};"
        "</script>")


@app.get("/admin/so-fill-model-equip-run")
@app.post("/admin/so-fill-model-equip-run")   # z1191z153: 실제 반영은 POST 로만(주소 열기·미리 불러오기로는 안 바뀜)
async def admin_so_fill_model_equip_run(req: Request, apply: str = "", dl: str = ""):
    """v5H226z1064c (대표 지시·부분수정 적용): 리포지토리에 번들된 pairs(model_equip_backfill_z1064.json)로
    수주(SO)별 모델·장비 '빈칸만' 채움. (fetch/업로드가 WORKS 서비스워커에 막혀 GET=navigate 트리거로 실행.)
    기본 = dry(미리보기·아무것도 안 바꿈). apply=RUN-z1064 일 때만 실제 반영.
    ⛔상태·통화·세금계산서·고객사 무변경 — z981 과 동일한 COALESCE(NULLIF()) '빈칸만' UPDATE 만 수행."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    import json as _j
    _do = ((apply or "").strip() == "RUN-z1064") and req.method == "POST"   # z1191z153 (대표 11-25 원칙 ③): GET = 미리보기만
    _path = os.path.join(os.path.dirname(__file__), "model_equip_backfill_z1064.json")
    try:
        with open(_path, encoding="utf-8") as _f:
            pairs = _j.load(_f)
    except Exception as e:
        return JSONResponse({"ok": False, "error": f"pairs 파일 읽기 실패: {e}"}, 500)
    applied = 0
    changed = []
    skipped = 0
    with db_session() as c:
        for p in pairs:
            try:
                oid = int(p.get("oid"))
            except Exception:
                skipped += 1
                continue
            _m = (str(p.get("model") or "").strip() or None)
            _e = (str(p.get("equip") or "").strip() or None)
            if not _m and not _e:
                skipped += 1
                continue
            row = c.execute("SELECT COALESCE(model_name,'') AS m, COALESCE(equip_name,'') AS e, "
                            "COALESCE(order_no,'') AS sono FROM orders WHERE id=?", (oid,)).fetchone()
            if not row:
                skipped += 1
                continue
            _wm = (_m if (not row["m"] and _m) else None)   # 빈 곳만
            _we = (_e if (not row["e"] and _e) else None)
            if not _wm and not _we:
                skipped += 1
                continue
            changed.append({"oid": oid, "sono": row["sono"], "model": _wm, "equip": _we})
            if _do:
                c.execute("UPDATE orders SET model_name=COALESCE(NULLIF(model_name,''),?), "
                          "equip_name=COALESCE(NULLIF(equip_name,''),?) WHERE id=?",
                          (_wm, _we, oid))
                applied += 1
    _resp = JSONResponse({"ok": True, "applied_mode": _do, "input": len(pairs),
                          "applied": applied, "would_change": len(changed),
                          "skipped": skipped, "sample": changed[:10]})
    if (dl or "").strip():
        _resp.headers["Content-Disposition"] = 'attachment; filename="model_equip_fill_result.json"'
    return _resp


@app.get("/admin/consumable-sales-audit", response_class=HTMLResponse)
async def admin_consumable_sales_audit(req: Request, year: str = ""):
    """z1051 (대표 지시): 소모품 매출이 비정상으로 큰 원인 진단 — 읽기전용(전부 SELECT·아무것도 안 바꿈).
    매출 홈의 '수주매출' 계산(_sales_3way ①)을 그대로 재현해 소모품 금액을
      ① 프로젝트 쪽(관리번호 4번째 글자 = C)   ② 소모품 쪽(소모품 발주)
    두 출처로 쪼개고 ▸ 통화별 분해 ▸ 같은 관리번호가 양쪽에 있는 건(이중 계상 의심)
    ▸ 원화환산 큰 순 목록을 보여준다. 어느 쪽이 금액을 부풀리는지 눈으로 판별하기 위한 화면."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)

    def _esc(s):
        return (str(s) if s is not None else "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

    def _n(x):
        try:
            return f"{float(x or 0):,.0f}"
        except Exception:
            return "0"

    SRC_P, SRC_C = "프로젝트 쪽", "소모품 쪽"
    sel = (year or "").strip() or str(date.today().year)
    missing = set()
    rows = []
    with db_session() as c:
        rates = _fx_load_rates(c)
        # ① 프로젝트 쪽 — 매출 홈 ①과 동일 조건 + 관리번호 4번째 글자 C 만
        for r in c.execute(
                "SELECT COALESCE(p.mgmt_code,'') AS mc, COALESCE(o.order_no,'') AS no, p.id AS oid, "
                "COALESCE(p.customer_name,'') AS cust, oi.amount AS amount, "
                + SALES_CCY_ITEM + " AS ccy, "             # z1164: 매출 홈 ①과 같은 규칙(호기 → 수주 → 프로젝트 · 빈 글자 = 빈칸)
                + SALES_DD_ORDER + " AS dd, COALESCE(oi.unit_label,'') AS lbl "
                "FROM order_items oi JOIN orders o ON o.id=oi.order_id "
                "JOIN projects p ON p.id=o.project_id "
                "WHERE COALESCE(o.status,'')<>'CANCELLED' AND COALESCE(p.is_archived,0)=0 "
                "  AND UPPER(substr(COALESCE(p.mgmt_code,''),4,1))='C'").fetchall():
            d = dict(r); d["src"] = SRC_P; rows.append(d)
        # ② 소모품 쪽 — 매출 홈 ②와 동일 조건
        for r in c.execute(
                "SELECT COALESCE(mgmt_code,'') AS mc, COALESCE(co_no,'') AS no, id AS oid, "
                "COALESCE(customer_name,'') AS cust, total_amount AS amount, "
                "currency AS ccy, order_date AS dd, '' AS lbl "
                "FROM consumable_orders WHERE COALESCE(status,'')<>'CANCELLED'").fetchall():
            d = dict(r); d["src"] = SRC_C; rows.append(d)
        # ⑤ 저장된 합계(total_amount) vs 라인 합계 — recompute_co_total 이 안 돈 건 표면화
        mism_all = [dict(r) for r in c.execute(
            "SELECT COALESCE(co.mgmt_code,'') AS mc, COALESCE(co.co_no,'') AS no, co.id AS oid, "
            "COALESCE(co.customer_name,'') AS cust, COALESCE(co.currency,'KRW') AS ccy, "
            "COALESCE(co.order_date,'') AS dd, COALESCE(co.total_amount,0) AS saved, "
            "(SELECT COALESCE(SUM(COALESCE(i.amount,0)),0) FROM consumable_order_items i "
            " WHERE i.co_id=co.id) AS lsum "
            "FROM consumable_orders co WHERE COALESCE(co.status,'')<>'CANCELLED'").fetchall()]

    years = sorted({(d.get("dd") or "")[:4] for d in rows if (d.get("dd") or "")[:4].isdigit()}, reverse=True)
    kept = []
    for d in rows:
        dd = (d.get("dd") or "")
        if dd[:4] != sel:
            continue
        ccy = (d.get("ccy") or "KRW").strip().upper() or "KRW"
        raw = float(d.get("amount") or 0)
        d["ccy"] = ccy
        d["raw"] = raw
        d["krw"] = _fx_to_krw(rates, raw, ccy, dd[:7], missing)
        d["rate"] = _fx_rate_for(rates, ccy, dd[:7]) or 0
        kept.append(d)

    # 통화 확인 필요 = 외화 표기인데 금액이 원화급(소모품 발주 하나가 5만 달러 이상은 실무상 드묾)
    def _susp(d):
        return d["ccy"] != "KRW" and d["raw"] >= 50000

    src_agg, ccy_agg = {}, {}
    for d in kept:
        a = src_agg.setdefault(d["src"], {"cnt": 0, "krw": 0.0})
        a["cnt"] += 1
        a["krw"] += d["krw"]
        b = ccy_agg.setdefault((d["src"], d["ccy"]), {"cnt": 0, "raw": 0.0, "krw": 0.0})
        b["cnt"] += 1
        b["raw"] += d["raw"]
        b["krw"] += d["krw"]
    total_krw = sum(x["krw"] for x in src_agg.values())
    susp = [d for d in kept if _susp(d)]
    susp_krw = sum(d["krw"] for d in susp)
    mc_p = {d["mc"] for d in kept if d["src"] == SRC_P and d["mc"]}
    mc_c = {d["mc"] for d in kept if d["src"] == SRC_C and d["mc"]}
    dup_mc = sorted(mc_p & mc_c)
    dup_krw = sum(d["krw"] for d in kept if d["mc"] in mc_p and d["mc"] in mc_c)

    def _thead(hs):
        return ("<table style='border-collapse:collapse;font-size:12.5px;width:100%;margin:6px 0 20px;'><thead><tr>"
                + "".join("<th style='border-bottom:2px solid #ddd;padding:6px;text-align:left;white-space:nowrap;'>"
                          + h + "</th>" for h in hs) + "</tr></thead><tbody>")

    def _tr(cs):
        return "<tr>" + "".join("<td style='border-bottom:1px solid #eee;padding:5px;'>" + x + "</td>"
                                for x in cs) + "</tr>"

    def _lnk(d, src=None):
        """관리번호 → 그 건 상세(고치러 가는 길). §4 규칙 34: 보여주는 곳엔 고치는 자리도."""
        s = src or d.get("src") or SRC_C
        href = ("/consumables/" if s == SRC_C else "/projects/") + str(d.get("oid") or 0)
        return ("<a href='" + href + "' target='_blank' title='이 건 상세로 (새 창에서 열림)' "
                "style='font-family:monospace;color:#1d4ed8;font-weight:700;'>"
                + _esc(d.get("mc") or "—") + "</a>")

    B = ["<meta charset='utf-8'><div style='font-family:Pretendard,system-ui,sans-serif;"
         "margin:24px 0;padding:0 24px;color:#1f2937;'>",
         "<h2>🧾 소모품 매출 진단 — " + _esc(sel) + "년 <span style='font-size:14px;color:#15803d;'>(읽기전용)</span></h2>",
         "<p style='color:#555;line-height:1.75;'>매출 홈의 <b>수주매출</b> 계산을 <b>그대로 재현</b>해, 소모품 금액이 "
         "어디서 오는지 쪼개 봅니다. <b>이 화면은 아무것도 바꾸지 않습니다</b>(전부 조회).</p>"]
    if years:
        B.append("<p style='margin:6px 0 14px;'>연도 : " + " · ".join(
            ("<b>" + _esc(y) + "</b>" if y == sel else
             "<a href='/admin/consumable-sales-audit?year=" + _esc(y) + "' style='color:#1d4ed8;'>" + _esc(y) + "</a>")
            for y in years) + "</p>")
    B.append("<div style='background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;padding:14px 16px;"
             "margin:10px 0 18px;line-height:2;'>"
             "<b>소모품 수주매출 합계</b> : <b style='font-size:16px;'>" + _n(total_krw) + " 원</b>"
             " <span style='color:#777;'>(매출 홈 소모품 '수주매출'과 같아야 정상)</span><br>"
             "<b>통화 확인 필요</b> : <b style='color:#b91c1c;'>" + str(len(susp)) + "건 · " + _n(susp_krw) + " 원</b>"
             + (" <span style='color:#b91c1c;'>= 전체의 " + f"{(susp_krw / total_krw * 100):.1f}" + "%</span>"
                if total_krw else "") + "<br>"
             "<b>같은 관리번호가 양쪽에</b>(이중 계상 의심) : <b style='color:#b45309;'>" + str(len(dup_mc))
             + "개 · " + _n(dup_krw) + " 원</b></div>")

    B.append("<h3 style='margin:20px 0 4px;'>① 금액이 어디서 오나 — 출처별</h3>")
    B.append("<p style='color:#666;font-size:13px;margin:2px 0 6px;'>소모품은 <b>두 곳</b>에 저장될 수 있고, "
             "매출은 <b>두 곳을 더합니다</b>. 같은 건이 양쪽에 있으면 <b>2배</b>로 잡힙니다.</p>")
    B.append(_thead(("출처", "건수", "원화환산 합계", "비중")))
    for s in (SRC_P, SRC_C):
        a = src_agg.get(s) or {"cnt": 0, "krw": 0.0}
        pct = (a["krw"] / total_krw * 100) if total_krw else 0
        B.append(_tr((("<b>" + s + "</b>" + ("  <span style='color:#777;'>(관리번호 4번째 글자 = C 인 프로젝트)</span>"
                                             if s == SRC_P else "  <span style='color:#777;'>(소모품 발주)</span>")),
                      _n(a["cnt"]), "<b>" + _n(a["krw"]) + "</b>", f"{pct:.1f}%")))
    B.append("</tbody></table>")

    B.append("<h3 style='margin:20px 0 4px;'>② 통화별 분해</h3>")
    B.append("<p style='color:#666;font-size:13px;margin:2px 0 6px;'>'환산 전'은 적힌 그대로의 금액, "
             "'원화환산'은 그 달 기준환율로 바꾼 금액입니다. 원화 금액이 <b>외화로 잘못 적혀</b> 있으면 "
             "환산에서 <b>1,000배 이상</b> 부풀 수 있습니다.</p>")
    B.append(_thead(("출처", "통화", "건수", "환산 전 금액", "원화환산", "비중")))
    for (s, ccy) in sorted(ccy_agg, key=lambda k: -ccy_agg[k]["krw"]):
        v = ccy_agg[(s, ccy)]
        pct = (v["krw"] / total_krw * 100) if total_krw else 0
        warn = " <span style='color:#b91c1c;font-weight:800;'>⚠</span>" if ccy != "KRW" else ""
        B.append(_tr((s, "<b>" + _esc(ccy) + "</b>" + warn, _n(v["cnt"]), _n(v["raw"]),
                      "<b>" + _n(v["krw"]) + "</b>", f"{pct:.1f}%")))
    B.append("</tbody></table>")

    if dup_mc:
        B.append("<h3 style='margin:20px 0 4px;'>③ 같은 관리번호가 양쪽에 (" + str(len(dup_mc)) + "개) — 이중 계상 의심</h3>")
        B.append(_thead(("관리번호", "프로젝트 쪽", "소모품 쪽", "고객사")))
        for mc in dup_mc[:60]:
            pk = sum(d["krw"] for d in kept if d["src"] == SRC_P and d["mc"] == mc)
            ck = sum(d["krw"] for d in kept if d["src"] == SRC_C and d["mc"] == mc)
            cu = next((d["cust"] for d in kept if d["mc"] == mc and d["cust"]), "")
            B.append(_tr(("<span style='font-family:monospace;'>" + _esc(mc) + "</span>",
                          _n(pk), _n(ck), _esc(cu))))
        B.append("</tbody></table>")
        if len(dup_mc) > 60:
            B.append("<p style='color:#777;'>… 외 " + str(len(dup_mc) - 60) + "개</p>")
    else:
        B.append("<h3 style='margin:20px 0 4px;'>③ 이중 계상 의심</h3>"
                 "<p style='color:#15803d;font-weight:700;padding:12px;background:#f0fdf4;border-radius:8px;'>"
                 "✅ 같은 관리번호가 양쪽에 있는 건 없음 — 이중 계상 아님.</p>")

    top = sorted(kept, key=lambda d: -d["krw"])[:40]
    B.append("<h3 style='margin:20px 0 4px;'>④ 원화환산 큰 순 " + str(len(top)) + "건</h3>")
    B.append("<p style='color:#666;font-size:13px;margin:2px 0 6px;'>"
             "<b style='color:#b91c1c;'>⚠ 통화 확인</b> = 외화로 적혀 있는데 금액이 원화급인 건"
             "(외화 5만 이상). 원화를 외화로 잘못 고른 것으로 의심됩니다. · "
             "<b>관리번호를 누르면</b> 그 건 상세가 새 창으로 열립니다 — 거기서 통화를 고칠 수 있습니다.</p>")
    B.append(_thead(("", "출처", "관리번호", "수주번호", "고객사", "통화", "환산 전", "환율", "원화환산", "발주일")))
    for d in top:
        flag = ("<b style='color:#b91c1c;' title='외화 표기인데 금액이 원화급 — 확인 필요'>⚠</b>"
                if _susp(d) else "")
        B.append(_tr((flag, d["src"], _lnk(d),
                      "<span style='font-family:monospace;'>" + _esc(d["no"]) + "</span>",
                      _esc(d["cust"])[:24], _esc(d["ccy"]), _n(d["raw"]),
                      (_n(d["rate"]) if d["ccy"] != "KRW" else "—"),
                      "<b>" + _n(d["krw"]) + "</b>", _esc(d["dd"])[:10])))
    B.append("</tbody></table>")
    if missing:
        B.append("<p style='color:#b45309;'>⚠ 기준환율이 없어 <b>0원</b>으로 처리된 통화·월 : "
                 + _esc(", ".join(sorted(f"{a}/{b}" for (a, b) in missing)))
                 + " — <a href='/admin/fx-rates' style='color:#1d4ed8;'>환율 입력</a></p>")
    mism = [d for d in mism_all
            if (d["dd"] or "")[:4] == sel and abs(float(d["saved"] or 0) - float(d["lsum"] or 0)) >= 1]
    B.append("<h3 style='margin:20px 0 4px;'>⑤ 소모품 발주 — 저장된 합계와 라인 합계가 다른 건 ("
             + str(len(mism)) + ")</h3>")
    B.append("<p style='color:#666;font-size:13px;margin:2px 0 6px;'>매출은 <b>저장된 합계</b>를 씁니다. "
             "라인을 고친 뒤 합계가 다시 계산되지 않았다면 <b>매출만 옛 금액</b>으로 남습니다.</p>")
    if mism:
        B.append(_thead(("관리번호", "수주번호", "고객사", "통화", "저장된 합계", "라인 합계", "차이", "발주일")))
        for d in sorted(mism, key=lambda x: -abs(float(x["saved"] or 0) - float(x["lsum"] or 0)))[:60]:
            diff = float(d["saved"] or 0) - float(d["lsum"] or 0)
            B.append(_tr((_lnk(d, SRC_C),
                          "<span style='font-family:monospace;'>" + _esc(d["no"]) + "</span>",
                          _esc(d["cust"])[:24], _esc(d["ccy"]), _n(d["saved"]), _n(d["lsum"]),
                          "<b style='color:#b91c1c;'>" + _n(diff) + "</b>", _esc(d["dd"])[:10])))
        B.append("</tbody></table>")
    else:
        B.append("<p style='color:#15803d;font-weight:700;padding:12px;background:#f0fdf4;border-radius:8px;'>"
                 "✅ 저장된 합계와 라인 합계가 모두 일치.</p>")
    B.append("<p style='margin:24px 0;color:#777;'>이 화면은 조회만 합니다. 고칠 대상이 확인되면 알려주세요.</p></div>")
    return HTMLResponse("".join(B))


@app.get("/admin/customer-health", response_class=HTMLResponse)
async def admin_customer_health(req: Request):
    """v5H226z610 (대표 지시): 고객사 연결성 읽기전용 진단.
    ① 같은 고객사인데 표기가 갈린 그룹(마스터 중복 + 프로젝트/소모품 표기 분산)
    ② 고객사 미연결(customer_id NULL) 건수  ③ 세금계산서 ↔ 원천(프로젝트/소모품) 고객사명 불일치.
    데이터는 절대 변경하지 않음(전부 SELECT). 매출/세금계산서가 안 맞는 규모를 먼저 숫자로 파악하기 위한 화면."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    import re as _re
    from collections import defaultdict
    # 매칭과 동일한 정규화 규칙(법인격·기호·공백 제거 → 소문자)
    _lc = _re.compile(r"주식회사|유한책임회사|유한회사|\(주\)|\(유\)|\(有\)|㈜|㈲|株式会社")
    _sym = _re.compile(r"[\s\(\)\[\]\.,\-_/&'\"·｜|]")
    def _nc(s):
        s = (s or "").lower()
        s = _lc.sub("", s)
        s = _sym.sub("", s)
        return s.strip()

    custs = []
    master_dups, proj_split, co_split, ti_mismatch = [], [], [], []
    unlinked = {"projects": 0, "consumables": 0, "tax": 0}
    ti_repurposed = ti_overwritten = 0
    with db_session() as c:
        # A. 고객사 마스터 중복 의심 — 정규화 키는 같은데 등록명이 둘 이상
        custs = [dict(r) for r in c.execute("SELECT id, name, COALESCE(alias,'') AS alias, sub_biz_no FROM customers ORDER BY name").fetchall()]   # z1158-허용: 고르기 목록이 아니라 중복 의심 진단 — 정식 상호로 묶어 보므로 이름순
        gm = defaultdict(list)
        for r in custs:
            k = _nc(r["name"])
            if k:
                # v5H226z619 (대표 지시): 종사업장번호까지 키에 포함 — 같은 상호라도 종사업장이
                #   다르면 별개 사업장이라 '중복' 아님. 같은 상호+같은 종사업장에서 표기만 갈린 것만 후보.
                _sbn = (r.get("sub_biz_no") or "").strip()
                gm[(k, _sbn)].append(r)
        for (k, _sbn), lst in gm.items():
            if len({r["name"] for r in lst}) > 1:
                # 키 이름 'items'는 Jinja에서 dict.items() 메서드와 충돌 → 'members' 사용
                master_dups.append({"key": k, "members": lst})

        # B. 프로젝트 고객사 표기 분산 + 미연결(customer_id NULL)
        # z1097b (대표 지시 2026-09-10): 통화를 안 보고 더하면 달러 프로젝트가 '원'으로 둔갑한다.
        #   통화별로 읽어 월 기준환율로 환산한 뒤 합친다(대표규정 §4 규칙48).
        _rt_ch = _fx_load_rates(c)
        _praw = [dict(r) for r in c.execute(
            "SELECT customer_name AS nm, customer_id AS cid, "
            "COALESCE(currency,'KRW') AS currency, COALESCE(order_amount,0) AS order_amount, "
            "order_date, due_date FROM projects "
            "WHERE COALESCE(customer_name,'')<>''").fetchall()]
        _agg = {}
        for _r in _praw:
            _agg.setdefault((_r["nm"], _r["cid"]), []).append(_r)
        prows = []
        for (_nm, _cid), _lst in _agg.items():
            _bd = _ccy_breakdown(_lst, "order_amount", "currency",
                                 date_keys=("order_date", "due_date"), rates=_rt_ch)
            _t = _bd["krw"]
            if _t is None:      # 환율이 없는 통화가 섞였으면 원화분만 센다(달러를 원으로 더하지 않는다)
                _t = sum(x["total"] for x in _bd["by_ccy"] if x["currency"] == "KRW")
            prows.append({"nm": _nm, "cid": _cid, "cnt": len(_lst), "total": _t})
        gp = defaultdict(list)
        for r in prows:
            gp[_nc(r["nm"])].append(r)
            if not r["cid"]:
                unlinked["projects"] += r["cnt"]
        for k, lst in gp.items():
            names = sorted({r["nm"] for r in lst})
            if len(names) > 1:
                proj_split.append({"key": k, "names": names,
                                   "cnt": sum(r["cnt"] for r in lst),
                                   "total": sum(r["total"] for r in lst), "rows": lst})

        # C. 소모품 수주 고객사 표기 분산 + 미연결
        try:
            crows = [dict(r) for r in c.execute(
                "SELECT customer_name AS nm, customer_id AS cid, COUNT(*) AS cnt, "
                "COALESCE(SUM(total_amount),0) AS total FROM consumable_orders "
                "WHERE COALESCE(customer_name,'')<>'' GROUP BY customer_name, customer_id").fetchall()]
        except Exception:
            crows = []
        gc = defaultdict(list)
        for r in crows:
            gc[_nc(r["nm"])].append(r)
            if not r["cid"]:
                unlinked["consumables"] += r["cnt"]
        for k, lst in gc.items():
            names = sorted({r["nm"] for r in lst})
            if len(names) > 1:
                co_split.append({"key": k, "names": names,
                                 "cnt": sum(r["cnt"] for r in lst),
                                 "total": sum(r["total"] for r in lst), "rows": lst})

        # D. 세금계산서 미연결 + 원천 고객사명 불일치
        try:
            unlinked["tax"] = c.execute(
                "SELECT COUNT(*) FROM tax_invoices WHERE customer_id IS NULL "
                "AND COALESCE(status,'')<>'취소'").fetchone()[0]
        except Exception:
            pass
        try:
            for r in c.execute(
                "SELECT ti.ti_no AS ti_no, l.ref_kind AS rk, l.ref_id AS rid, "
                "       l.customer AS line_cust, l.mgmt_code AS snap_mgmt "
                "FROM tax_invoices ti JOIN tax_invoice_lines l ON l.ti_id=ti.id "
                "WHERE COALESCE(ti.status,'')<>'취소'"):
                rk, rid = r["rk"], r["rid"]
                # 지금 ref_id(행번호)가 가리키는 레코드의 '현재' 관리번호 + 고객사
                cur_mgmt, cur_cust = None, None
                try:
                    if rk == "consumable":
                        rr = c.execute("SELECT mgmt_code, customer_name FROM consumable_orders WHERE id=?", (rid,)).fetchone()
                    else:
                        rr = c.execute("SELECT mgmt_code, customer_name FROM projects WHERE id=?", (rid,)).fetchone()
                    if rr:
                        cur_mgmt, cur_cust = rr[0], rr[1]
                except Exception:
                    pass
                lc = r["line_cust"]
                snap = r["snap_mgmt"]
                if cur_cust and lc and lc != "—" and _nc(cur_cust) != _nc(lc):
                    # 판정: ref_id 가 다른 관리번호를 가리키면 '행번호 재배정'(재업로드로 id 바뀜),
                    #       관리번호는 같은데 고객사만 다르면 '고객사 덮어쓰기'.
                    repurposed = bool(cur_mgmt and snap and _nc(cur_mgmt) != _nc(snap))
                    if repurposed:
                        ti_repurposed += 1
                    else:
                        ti_overwritten += 1
                    ti_mismatch.append({"ti_no": r["ti_no"], "snap_mgmt": snap or "—",
                                        "cur_mgmt": cur_mgmt or "—", "line": lc, "src": cur_cust,
                                        "diag": "재배정" if repurposed else "덮어쓰기"})
        except Exception:
            pass

        # E. v5H226z651 (대표 지시): 미연결(customer_id NULL)인데 이름에 맞는 고객사 후보가 있는 건 → 종사업장 골라 수동 연결.
        #    같은 상호 여러 종사업장이라 자동연결이 (안전원칙상) 보류된 건들을 사람이 직접 종사업장을 골라 연결.
        link_targets = []
        try:
            # v5H226z654 (대표 지시): 후보 탐색을 상호(name) OR 시스템명(alias) 둘 다로 — 고객사칸에 시스템명이 저장된 건도 잡음
            _cust_by_key = defaultdict(list)
            for _cu in custs:
                _nm = (_cu["name"] or "").strip()
                _al = (_cu.get("alias") or "").strip()
                if _nm:
                    _cust_by_key[_nm].append(_cu)
                if _al and _al != _nm:
                    _cust_by_key[_al].append(_cu)
            # z1191z157: 옛 이름(이름 변경 이력)도 후보로 — 자동 연결 아님(사람이 고름)
            try:
                _cu_by_id157 = {x["id"]: x for x in custs}
                for _hc, _ho in c.execute("SELECT DISTINCT customer_id, TRIM(old_value) FROM customer_history "
                                          "WHERE field='고객사명' AND TRIM(COALESCE(old_value,''))<>''").fetchall():
                    if _hc in _cu_by_id157 and _cu_by_id157[_hc] not in _cust_by_key[_ho]:
                        _cust_by_key[_ho].append(_cu_by_id157[_hc])
            except Exception as _e157:
                print(f"[z1191z157] 연결 점검 옛 이름 후보 실패: {_e157}")

            def _mk_targets(_rows, _kind):
                for _r in _rows:
                    _cd = _cust_by_key.get((_r["customer_name"] or "").strip(), [])
                    if not _cd:
                        continue
                    link_targets.append({
                        "kind": _kind, "id": _r["id"], "mgmt_code": _r["mgmt_code"] or "—",
                        "name": (_r["name"] if "name" in _r.keys() else "") or "",
                        "customer_name": _r["customer_name"],
                        "candidates": [{"id": x["id"], "label": (x.get("alias") or x["name"]),
                                        "sub_biz_no": (x.get("sub_biz_no") or "")} for x in _cd],
                    })
            _mk_targets(c.execute("SELECT id, mgmt_code, name, customer_name FROM projects "
                                  "WHERE customer_id IS NULL AND COALESCE(customer_name,'')<>'' "
                                  "ORDER BY mgmt_code").fetchall(), "project")
            try:
                _mk_targets(c.execute("SELECT id, mgmt_code, customer_name FROM consumable_orders "
                                      "WHERE customer_id IS NULL AND COALESCE(customer_name,'')<>'' "
                                      "ORDER BY mgmt_code").fetchall(), "consumable")
            except Exception:
                pass
        except Exception:
            pass

    proj_split.sort(key=lambda x: -x["total"])
    co_split.sort(key=lambda x: -x["total"])
    # 재배정(행번호 어긋남)을 위로 — 더 위험
    ti_mismatch.sort(key=lambda x: 0 if x["diag"] == "재배정" else 1)
    summary = {
        "customers": len(custs),
        "master_dups": len(master_dups),
        "proj_split": len(proj_split),
        "co_split": len(co_split),
        "unlinked_proj": unlinked["projects"],
        "unlinked_co": unlinked["consumables"],
        "unlinked_tax": unlinked["tax"],
        "ti_mismatch": len(ti_mismatch),
        "ti_repurposed": ti_repurposed,
        "ti_overwritten": ti_overwritten,
        "link_targets": len(link_targets),
    }
    return ctx(req, "admin_customer_health.html", user=u, summary=summary,
               master_dups=master_dups, proj_split=proj_split,
               co_split=co_split, ti_mismatch=ti_mismatch[:300],
               link_targets=link_targets[:500])


@app.post("/admin/customer-autolink")
async def admin_customer_autolink(req: Request):
    """v5H226z654 (대표 지시): 미연결(customer_id NULL) 건을 상호(name) 또는 시스템명(alias) '정확히 1곳' 매칭으로 일괄 자동연결.
    여러 후보(같은 상호 여러 종사업장 등)는 손대지 않음(미연결 유지·수동 선택). 데이터 연결성 안전원칙 준수."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    n_proj = n_co = 0
    with db_session() as c:
        for _tbl in ("projects", "consumable_orders"):
            try:
                _rows = c.execute(
                    f"SELECT id, customer_name FROM {_tbl} "
                    "WHERE customer_id IS NULL AND COALESCE(customer_name,'')<>''"
                ).fetchall()
            except Exception:
                _rows = []
            for _r in _rows:
                _cid, _ = _logi.resolve_customer_id(c, _r["customer_name"])
                if _cid:
                    c.execute(f"UPDATE {_tbl} SET customer_id=? WHERE id=?", (_cid, _r["id"]))
                    if _tbl == "projects":
                        n_proj += 1
                    else:
                        n_co += 1
    return RedirectResponse(f"/admin/customer-health?autolinked={n_proj + n_co}", 303)


@app.post("/admin/customer-link")
async def admin_customer_link(req: Request):
    """v5H226z651 (대표 지시): 미연결 프로젝트/소모품을 사용자가 고른 종사업장(customer_id)에 수동 연결.
    같은 상호 여러 종사업장이라 자동연결이 보류된 건을 사람이 정확한 종사업장으로 직접 연결(데이터 연결성 안전원칙)."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    form = await req.form()
    kind = (form.get("kind") or "").strip()
    try:
        ref_id = int(form.get("ref_id") or 0)
        cid = int(form.get("customer_id") or 0)
    except (TypeError, ValueError):
        return RedirectResponse("/admin/customer-health?linkerr=1", 303)
    if kind not in ("project", "consumable") or ref_id <= 0 or cid <= 0:
        return RedirectResponse("/admin/customer-health?linkerr=1", 303)
    with db_session() as c:
        if not c.execute("SELECT 1 FROM customers WHERE id=?", (cid,)).fetchone():
            return RedirectResponse("/admin/customer-health?linkerr=1", 303)
        _tbl = "consumable_orders" if kind == "consumable" else "projects"
        c.execute(f"UPDATE {_tbl} SET customer_id=? WHERE id=?", (cid, ref_id))
    return RedirectResponse("/admin/customer-health?linked=1", 303)


@app.post("/admin/customer-merge")
async def admin_customer_merge(req: Request):
    """v5H226z616 (대표 지시): 고객사 마스터 병합 — 중복 등록된 고객사를 하나로 통합.
    drop_ids 가 달고 있는 모든 연결(customer_id 보유 전 테이블 + customer_name 스냅샷)을
    keep_id 로 옮기고 drop 고객사를 삭제. customers.name UNIQUE 라 이름 변경으로는 못 하는 병합.
    되돌릴 수 없음(관리자/대표 전용·UI에서 확인 후 실행)."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return JSONResponse({"ok": False, "error": "권한 없음"}, 403)
    try:
        b = await req.json()
    except Exception:
        b = {}
    try:
        keep_id = int(b.get("keep_id"))
    except Exception:
        return JSONResponse({"ok": False, "error": "보존할 고객사(keep_id)가 올바르지 않습니다"}, 400)
    drop_ids = []
    for x in (b.get("drop_ids") or []):
        try:
            xi = int(x)
            if xi != keep_id and xi not in drop_ids:
                drop_ids.append(xi)
        except Exception:
            pass
    if not drop_ids:
        return JSONResponse({"ok": False, "error": "합칠 대상(drop_ids)이 없습니다"}, 400)
    moved = {}
    dropped_names = []
    keep_name = ""
    try:
      with db_session() as c:
        # v5H226z617: get_db 가 FK=ON 이라 customers DELETE 가 잔여 참조에 막혀 500.
        #   초기화 함수들처럼 병합 동안만 FK OFF(모든 customer_id 는 이미 keep 로 이관함).
        try:
            c.execute("PRAGMA foreign_keys=OFF")
        except Exception:
            pass
        keep = c.execute("SELECT name FROM customers WHERE id=?", (keep_id,)).fetchone()
        if not keep:
            return JSONResponse({"ok": False, "error": "보존할 고객사를 찾을 수 없습니다"}, 404)
        keep_name = keep[0] if not isinstance(keep, dict) else keep["name"]
        tabs = [r[0] for r in c.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'").fetchall()]
        for did in drop_ids:
            drow = c.execute("SELECT name FROM customers WHERE id=?", (did,)).fetchone()
            if not drow:
                continue
            dname = drow[0] if not isinstance(drow, dict) else drow["name"]
            dropped_names.append(f"{dname}(#{did})")
            for t in tabs:
                if t == "customers":
                    continue
                try:
                    cols = {r[1] for r in c.execute(f"PRAGMA table_info('{t}')").fetchall()}
                except Exception:
                    continue
                if "customer_id" not in cols:
                    continue
                # 옮길 행의 이름 스냅샷을 보존 고객사명으로 먼저 동기화(옮긴 행만)
                if "customer_name" in cols:
                    try:
                        c.execute(f"UPDATE {t} SET customer_name=? WHERE customer_id=?", (keep_name, did))
                    except Exception:
                        pass
                try:
                    cur = c.execute(f"UPDATE {t} SET customer_id=? WHERE customer_id=?", (keep_id, did))
                    if cur.rowcount and cur.rowcount > 0:
                        moved[t] = moved.get(t, 0) + cur.rowcount
                except Exception:
                    pass
            # 세금계산서 라인의 고객사 스냅샷(이름만 보관·customer_id 없음) 동기화
            try:
                c.execute("UPDATE tax_invoice_lines SET customer=? WHERE customer=?", (keep_name, dname))
            except Exception:
                pass
            c.execute("DELETE FROM customers WHERE id=?", (did,))
    except Exception as e:
        return JSONResponse({"ok": False, "error": f"병합 중 오류: {str(e)[:200]}"}, 200)
    return JSONResponse({"ok": True, "keep_id": keep_id, "keep_name": keep_name,
                         "dropped": dropped_names, "moved": moved})


@app.get("/admin/proj-raw", response_class=HTMLResponse)
async def admin_proj_raw(req: Request, code: str = ""):
    """v5H226z627 (대표 지시): 관리번호의 '저장된 원시값' 그대로 보기(읽기전용) — 수량/단가 표시 불일치 진단용.
    projects(unit_qty/unit_price/order_amount) vs orders(unit_qty) vs order_items(qty/unit_price/amount) 비교."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    code = (code or req.query_params.get("code") or "").strip().upper()

    def _esc(s):
        return (str(s) if s is not None else "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    body = ["<meta charset='utf-8'><div style='font-family:Pretendard,system-ui,sans-serif;margin:24px 0;padding:0 24px;color:#1f2937;'>",
            "<h2>🔬 관리번호 원시 데이터 보기 (읽기전용)</h2>",
            "<form method='get' style='margin:10px 0;'><input name='code' value='" + _esc(code) +
            "' placeholder='관리번호 예: 001M2605' style='padding:7px 10px;border:1px solid #ccc;border-radius:6px;font-size:14px;'>"
            " <button type='submit' style='padding:7px 14px;'>조회</button></form>"]
    if not code:
        body.append("<p style='color:#888;'>관리번호를 입력하세요.</p></div>")
        return HTMLResponse("".join(body))
    with db_session() as c:
        prow = c.execute("SELECT * FROM projects WHERE UPPER(mgmt_code)=? LIMIT 1", (code,)).fetchone()
        if not prow:
            body.append(f"<p style='color:#b91c1c;'>'{_esc(code)}' 관리번호 프로젝트 없음.</p></div>")
            return HTMLResponse("".join(body))
        p = dict(prow); pid = p["id"]
        body.append("<h3>① projects (헤더)</h3><table border=1 cellpadding=6 style='border-collapse:collapse;font-size:13px;'>")
        for k in ("id", "mgmt_code", "name", "project_type", "shipment_form", "unit_qty", "unit_price", "order_amount", "currency", "customer_name", "customer_id"):
            body.append(f"<tr><th style='text-align:left;background:#f4f1e8;'>{k}</th><td>{_esc(p.get(k))}</td></tr>")
        body.append("</table>")
        orows = [dict(r) for r in c.execute(
            "SELECT id, order_no, unit_qty, unit_label, total_amount, status, COALESCE(currency,'KRW') AS currency, COALESCE(so_type,'') AS so_type FROM orders WHERE project_id=? ORDER BY id", (pid,)).fetchall()]
        body.append(f"<h3>② orders (수주/SO) — {len(orows)}건</h3><table border=1 cellpadding=6 style='border-collapse:collapse;font-size:13px;'><tr><th>id</th><th>order_no</th><th>unit_qty</th><th>unit_label</th><th>total_amount</th><th>status</th><th>so_type</th></tr>")
        for o in orows:
            body.append(f"<tr><td>{o['id']}</td><td>{_esc(o['order_no'])}</td><td><b>{_esc(o['unit_qty'])}</b></td><td>{_esc(o['unit_label'])}</td><td>{_esc(o['total_amount'])}</td><td>{_esc(o['status'])}</td><td>{_esc(o['so_type'])}</td></tr>")
        body.append("</table>")
        oids = [o["id"] for o in orows]
        items = []
        if oids:
            _ph = ",".join("?" * len(oids))
            items = [dict(r) for r in c.execute(
                f"SELECT id, order_id, qty, unit_price, amount, unit_label FROM order_items WHERE order_id IN ({_ph}) ORDER BY order_id, id", oids).fetchall()]
        body.append(f"<h3>③ order_items (호기/라인) — {len(items)}건</h3><table border=1 cellpadding=6 style='border-collapse:collapse;font-size:13px;'><tr><th>id</th><th>order_id</th><th>qty</th><th>unit_price</th><th>amount</th><th>unit_label</th></tr>")
        for it in items:
            body.append(f"<tr><td>{it['id']}</td><td>{it['order_id']}</td><td><b>{_esc(it['qty'])}</b></td><td>{_esc(it['unit_price'])}</td><td>{_esc(it['amount'])}</td><td>{_esc(it['unit_label'])}</td></tr>")
        body.append("</table>")
    body.append("<p style='color:#888;font-size:12px;margin-top:14px;'>읽기전용 — 데이터 변경 없음. 헤더 unit_qty 와 order_items 의 qty 합/줄수가 맞는지 보면 됩니다. "
                "<a href='/admin/unit-split'>🧩 완제품 호기 일괄 분할</a></p></div>")
    return HTMLResponse("".join(body))


def _unit_split_find(c):
    """v5H226z635: 호기 분할 대상 — 완제품(ASSEMBLY) SO 의 order_items 중 qty>1 (z629 시절 1줄 저장).
    부품(PARTS_EXPORT)·소모품·제품(SEMI)·기타(ETC)는 제외(거긴 1줄=낱개 수량이 정상)."""
    try:
        rows = c.execute(
            "SELECT oi.id, oi.order_id, oi.qty, oi.unit_price, oi.amount, oi.unit_label, "
            "       o.order_no, COALESCE(o.currency,'KRW') AS o_cur, "
            "       p.mgmt_code, COALESCE(p.project_type,'NEW_EQUIP') AS ptype, p.name, p.model_name, "
            "       COALESCE(p.unit_qty,1) AS p_unit_qty "
            "FROM order_items oi "
            "JOIN orders o ON o.id = oi.order_id "
            "JOIN projects p ON p.id = o.project_id "
            "WHERE ( COALESCE(oi.qty,1) > 1 "
            # v5H226z667: 자가치유가 만든 '수량=1·단가=총액 단일줄'(프로젝트 수량 N>1)도 대상 — 금액÷N 으로 호기 분할
            "        OR ( COALESCE(oi.qty,1) <= 1 AND COALESCE(p.unit_qty,1) > 1 "
            "             AND COALESCE(oi.amount,0) > 0 "
            "             AND ROUND(COALESCE(oi.amount,0)) = ROUND(COALESCE(oi.unit_price,0)) "
            "             AND (SELECT COUNT(*) FROM order_items oi2 WHERE oi2.order_id=oi.order_id) = 1 ) ) "
            "  AND COALESCE(p.project_type,'') <> 'CONSUMABLE' "
            "  AND COALESCE(NULLIF(UPPER(TRIM(p.shipment_form)),''),'ASSEMBLY') = 'ASSEMBLY' "
            "  AND COALESCE(UPPER(o.so_type),'') NOT IN ('PARTS_EXPORT','CONSUMABLE') "
            "ORDER BY p.mgmt_code, oi.id"
        ).fetchall()
        out = []
        for r in rows:
            d = dict(r)
            _q = int(round(float(d.get("qty") or 1)))
            # 분할 호기 수 = 라인 qty(>1) 또는 자가치유 단일줄이면 프로젝트 수량(p_unit_qty)
            d["split_n"] = _q if _q > 1 else int(d.get("p_unit_qty") or 1)
            out.append(d)
        return out
    except Exception:
        return []


