# ----- z421 2단계: 구성원 활동·시간(h) 기록 + 수주 전 활동 대시보드(부서별·유형별·대표 전용) -----
@app.post("/dept/requests/{rid:int}/activities/add")
async def dept_request_activity_add(request: Request, rid: int):
    """참여자(PM·구성원)가 활동·시간(h) 기록."""
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    form = await request.form()
    atype = (form.get("activity_type") or "기타").strip()
    if atype not in ACT_TYPES:
        atype = "기타"
    try:
        hours = float(str(form.get("hours") or "0").replace(",", "").strip() or 0)
    except Exception:
        hours = 0
    hours = max(0.0, min(hours, 1000.0))
    adate = (form.get("act_date") or "").strip() or None
    memo = (form.get("memo") or "").strip() or None
    with db_session() as c:
        r = c.execute("SELECT * FROM opp_dept_requests WHERE id=?", (rid,)).fetchone()
        if not r:
            return RedirectResponse("/dept/requests", 303)
        r = dict(r)
        if not _can_log_activity(c, u, r):
            return RedirectResponse("/dept/requests?err=forbidden", 303)
        if hours <= 0:
            return RedirectResponse("/dept/requests?err=hours", 303)
        c.execute("INSERT INTO opp_request_activities(request_id, user_id, activity_type, hours, act_date, memo) "
                  "VALUES(?,?,?,?, COALESCE(?, date('now','localtime')), ?)",
                  (rid, u.get("id"), atype, hours, adate, memo))
        c.execute("UPDATE opp_dept_requests SET "
                  "status=CASE WHEN status IN ('requested','assigned') THEN 'in_progress' ELSE status END, "
                  "updated_at=datetime('now','localtime') WHERE id=?", (rid,))
    return RedirectResponse("/dept/requests?ok=act", 303)


@app.post("/dept/requests/{rid:int}/activities/{aid:int}/delete")
async def dept_request_activity_delete(request: Request, rid: int, aid: int):
    """본인 기록(또는 PM·팀장)이 활동 기록 삭제."""
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    with db_session() as c:
        r = c.execute("SELECT * FROM opp_dept_requests WHERE id=?", (rid,)).fetchone()
        if not r:
            return RedirectResponse("/dept/requests", 303)
        r = dict(r)
        a = c.execute("SELECT user_id FROM opp_request_activities WHERE id=? AND request_id=?",
                      (aid, rid)).fetchone()
        if not a:
            return RedirectResponse("/dept/requests", 303)
        owner = (a[0] if not isinstance(a, dict) else a["user_id"])
        is_owner = bool(owner and int(owner) == int(u.get("id")))
        is_pm = bool(r.get("pm_user_id") and int(r["pm_user_id"]) == int(u.get("id")))
        if not (is_owner or is_pm or _is_team_leader(c, u, r.get("team_id"))):
            return RedirectResponse("/dept/requests?err=forbidden", 303)
        c.execute("DELETE FROM opp_request_activities WHERE id=? AND request_id=?", (aid, rid))
    return RedirectResponse("/dept/requests?ok=actdel", 303)


def _presales_activity_agg(c, start, end):
    """수주 전 활동 집계(기간 내) — 부서별·유형별·인별 시간/건수."""
    base = ("FROM opp_request_activities a "
            "JOIN opp_dept_requests r ON r.id=a.request_id "
            "LEFT JOIN teams t ON t.id=r.team_id "
            "LEFT JOIN users u ON u.id=a.user_id "
            "WHERE date(a.act_date) BETWEEN ? AND ?")
    args = (start, end)
    out = {}
    try:
        out["total_hours"] = round(float(c.execute(
            f"SELECT COALESCE(SUM(a.hours),0) {base}", args).fetchone()[0] or 0), 1)
        out["total_count"] = c.execute(f"SELECT COUNT(*) {base}", args).fetchone()[0]
        out["req_count"] = c.execute(f"SELECT COUNT(DISTINCT a.request_id) {base}", args).fetchone()[0]
        out["people_count"] = c.execute(f"SELECT COUNT(DISTINCT a.user_id) {base}", args).fetchone()[0]
        out["by_team"] = [dict(x) for x in c.execute(
            f"SELECT COALESCE(t.name,'(미지정)') AS name, ROUND(COALESCE(SUM(a.hours),0),1) AS hours, "
            f"COUNT(*) AS cnt {base} GROUP BY r.team_id ORDER BY hours DESC", args).fetchall()]
        out["by_type"] = [dict(x) for x in c.execute(
            f"SELECT COALESCE(a.activity_type,'기타') AS name, ROUND(COALESCE(SUM(a.hours),0),1) AS hours, "
            f"COUNT(*) AS cnt {base} GROUP BY a.activity_type ORDER BY hours DESC", args).fetchall()]
        out["by_person"] = [dict(x) for x in c.execute(
            f"SELECT COALESCE(u.name,'(미상)') AS name, COALESCE(t.name,'') AS team, "
            f"ROUND(COALESCE(SUM(a.hours),0),1) AS hours, COUNT(*) AS cnt {base} "
            f"GROUP BY a.user_id ORDER BY hours DESC LIMIT 30", args).fetchall()]
    except Exception as e:
        print(f"[PRESALES-AGG ERR] {e}")
        out = {"total_hours": 0, "total_count": 0, "req_count": 0, "people_count": 0,
               "by_team": [], "by_type": [], "by_person": []}
    return out


@app.get("/dept/activity-dashboard", response_class=HTMLResponse)
async def presales_activity_dashboard(request: Request):
    """수주 전 활동 대시보드 — 부서별·유형별·인별 시간/건수. 열람=대표 전용(can_view_work_patterns)."""
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_view_work_patterns(u):
        return RedirectResponse(role_home(u), 303)
    start, end, label, days = _wp_period(request)
    with db_session() as c:
        agg = _presales_activity_agg(c, start, end)
    with db_session() as c:
        demo_count = _demo_dept_requests_count(c)
    return ctx(request, "presales_activity_dashboard.html", user=u, agg=agg,
               start=start, end=end, label=label, days=days, act_types=ACT_TYPES,
               demo_count=demo_count)


# ----- z421 가상(데모) 데이터 — 검증용. 표식 ZZDEMO 로만 넣고, 한 번에 완전 삭제 (대표 지시: 실제 적용 전 반드시 삭제 가능) -----
DEMO_OPP_PREFIX = "ZZDEMO-"


def _demo_dept_requests_count(c):
    try:
        return c.execute("SELECT COUNT(*) FROM sales_opportunities WHERE opp_no LIKE ?",
                         (DEMO_OPP_PREFIX + "%",)).fetchone()[0]
    except Exception:
        return 0


def _demo_dept_requests_cleanup(c):
    """ZZDEMO 표식 영업기회 + 그에 달린 부서요청·구성원·활동·첨부 전부 삭제(실데이터 무관)."""
    oids = [r[0] for r in c.execute(
        "SELECT id FROM sales_opportunities WHERE opp_no LIKE ?", (DEMO_OPP_PREFIX + "%",)).fetchall()]
    rids = []
    if oids:
        qm = ",".join("?" * len(oids))
        rids = [r[0] for r in c.execute(
            f"SELECT id FROM opp_dept_requests WHERE opp_id IN ({qm})", oids).fetchall()]
    if rids:
        qr = ",".join("?" * len(rids))
        c.execute(f"DELETE FROM opp_request_activities WHERE request_id IN ({qr})", rids)
        c.execute(f"DELETE FROM opp_request_members WHERE request_id IN ({qr})", rids)
        c.execute(f"DELETE FROM opp_dept_requests WHERE id IN ({qr})", rids)
    if oids:
        qm = ",".join("?" * len(oids))
        try:
            c.execute(f"DELETE FROM sales_opportunity_files WHERE opp_id IN ({qm})", oids)
        except Exception:
            pass
        c.execute(f"DELETE FROM sales_opportunities WHERE id IN ({qm})", oids)
    return {"opps": len(oids), "reqs": len(rids)}


def _demo_dept_requests_seed(c):
    """검증용 가상 데이터 주입 — 전부 ZZDEMO 표식. 재실행 시 기존 데모 먼저 정리(중복 방지).
    실제 활성 직원을 PM/구성원으로 써서 업무패턴·대시보드가 실제처럼 채워지게 함."""
    import datetime as _dt
    _demo_dept_requests_cleanup(c)
    any_users = [r[0] for r in c.execute(
        "SELECT id FROM users WHERE COALESCE(is_active,1)=1 ORDER BY id LIMIT 60").fetchall()]
    if not any_users:
        return {"opps": 0, "reqs": 0, "acts": 0, "err": "활성 직원이 없습니다"}
    teams = [dict(r) for r in c.execute(
        "SELECT id, name FROM teams ORDER BY COALESCE(display_order,999), id").fetchall()]
    if not teams:
        return {"opps": 0, "reqs": 0, "acts": 0, "err": "부서(teams)가 없습니다"}
    eng = [t for t in teams if any(k in (t["name"] or "")
           for k in ("설계", "소프트", "전장", "검사", "제조", "가공", "품질", "개발"))]
    pool = eng or teams

    def team_users(tid):
        return [r[0] for r in c.execute(
            "SELECT id FROM users WHERE team_id=? AND COALESCE(is_active,1)=1 ORDER BY id LIMIT 6",
            (tid,)).fetchall()]

    today = _dt.date.today()
    ATYPES = ["검토", "시장조사", "기술조사", "제안", "기타"]
    demos = [
        ("[가상] 삼성 PBA 검사기 신규 문의", "(주)삼성전자", "T", "PBA-INSP-2026"),
        ("[가상] 배터리 모듈 자동화 라인", "이차전지 고객사", "M", "BAT-AUTO-LINE"),
        ("[가상] 전장 부품 검사 설비", "전장 고객사", "T", "EE-INSP-200"),
        ("[가상] 베트남공장 조립 자동화", "KNK Vina", "M", "VN-ASSY-AUTO"),
        ("[가상] 반도체 외관 검사기", "반도체 고객사", "T", "SEMI-VIS-100"),
    ]
    ym = today.strftime("%y%m")
    opps = reqs = acts = 0
    seq = 1
    for i, (title, cust, biz, model) in enumerate(demos):
        owner = any_users[i % len(any_users)]
        opp_no = f"{DEMO_OPP_PREFIX}{ym}-{seq:03d}"
        seq += 1
        oid = c.execute(
            "INSERT INTO sales_opportunities(opp_no,title,customer_name,biz_div,model_name,owner_user_id,"
            "expected_amount,currency,stage,status,note) VALUES(?,?,?,?,?,?,?,?,?,?,?)",
            (opp_no, title, cust, biz, model, owner, 50000000 * (i + 1), "KRW", "제안", "active",
             "[가상 데이터] 검증용 · 실제 적용 전 삭제하세요")).lastrowid
        opps += 1
        nreq = 1 + (i % 2)
        for j in range(nreq):
            t = pool[(i + j) % len(pool)]
            tu = team_users(t["id"]) or any_users
            pm = tu[0]
            members = tu[1:3] if len(tu) > 1 else []
            due = (today + _dt.timedelta(days=7 + j * 5)).isoformat()
            rid = c.execute(
                "INSERT INTO opp_dept_requests(opp_id,team_id,title,detail,due_date,status,pm_user_id,"
                "requested_by,assigned_by,assigned_at) VALUES(?,?,?,?,?,?,?,?,?,datetime('now','localtime'))",
                (oid, t["id"], title, f"[가상] {t['name']} 수주 전 기술검토·조사 요청", due,
                 "in_progress", pm, owner, owner)).lastrowid
            reqs += 1
            c.execute("INSERT OR IGNORE INTO opp_request_members(request_id,user_id,role_in_req,added_by) "
                      "VALUES(?,?,?,?)", (rid, pm, "pm", owner))
            for m in members:
                c.execute("INSERT OR IGNORE INTO opp_request_members(request_id,user_id,role_in_req,added_by) "
                          "VALUES(?,?,?,?)", (rid, m, "member", pm))
            doers = [pm] + members
            for k in range(3 + (i + j) % 3):
                doer = doers[k % len(doers)]
                at = ATYPES[k % 4]
                hrs = [1.0, 2.0, 4.0, 0.5, 8.0][k % 5]
                ad = (today - _dt.timedelta(days=(k * 3 + j) % 25)).isoformat()
                c.execute("INSERT INTO opp_request_activities(request_id,user_id,activity_type,hours,act_date,memo) "
                          "VALUES(?,?,?,?,?,?)", (rid, doer, at, hrs, ad, f"[가상] {at} 진행"))
                acts += 1
    return {"opps": opps, "reqs": reqs, "acts": acts}


@app.post("/dept/demo/seed")
async def dept_demo_seed(request: Request):
    """검증용 가상 데이터 넣기 — 대표 전용. ZZDEMO 표식."""
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_view_work_patterns(u):
        return RedirectResponse(role_home(u), 303)
    with db_session() as c:
        res = _demo_dept_requests_seed(c)
    if res.get("err"):
        return RedirectResponse("/dept/activity-dashboard?demo=err", 303)
    return RedirectResponse(f"/dept/activity-dashboard?demo=seeded&n={res['acts']}", 303)


@app.post("/dept/demo/cleanup")
async def dept_demo_cleanup(request: Request):
    """검증용 가상 데이터 전부 삭제 — 대표 전용. 실데이터 무관."""
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_view_work_patterns(u):
        return RedirectResponse(role_home(u), 303)
    try:
        _back = ((await request.form()).get("back") or "").strip()
    except Exception:
        _back = ""
    with db_session() as c:
        res = _demo_dept_requests_cleanup(c)
    # v5H226z850 (대표 지시): 부서 요청함에서 눌렀으면 거기로 복귀(그 외엔 기존대로 대시보드)
    if _back == "requests":
        return RedirectResponse(f"/dept/requests?demo=cleaned&n={res['opps']}", 303)
    return RedirectResponse(f"/dept/activity-dashboard?demo=cleaned&n={res['opps']}", 303)


@app.get("/projects/{pid:int}/orders/{so_id:int}/export-xlsx")
# v5H226z867: async→def 전환(FastAPI 스레드풀 실행·이벤트루프 비블로킹) — 본문 await 0건 AST 확인. 이 함수에 await를 추가하려면 반드시 async def로 되돌릴 것.
def projects_export_so_xlsx(req: Request, pid: int, so_id: int):
    """v5H226i: 수주(SO) 라인 항목을 엑셀로 다운로드.
    CONSUMABLE 은 품명·연결관리코드·이미지경로 포함, 그 외는 호기 위주."""
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_use_sales(u):
        return PlainTextResponse("권한 없음", 403)
    from openpyxl import Workbook
    from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
    from io import BytesIO
    with db_session() as c:
        prow = c.execute(
            "SELECT id, mgmt_code, name, project_type, currency, "
            "       COALESCE(shipment_form,'ASSEMBLY') AS shipment_form "
            "FROM projects WHERE id=?",
            (pid,)
        ).fetchone()
        if not prow:
            return PlainTextResponse("프로젝트 없음", 404)
        # v5H226z: SO 컬럼에 so_type 동적 포함 (백워드 호환)
        _ord_cols = {r[1] for r in c.execute("PRAGMA table_info(orders)").fetchall()}
        _so_type_col = ", COALESCE(so_type,'EQUIPMENT') AS so_type" if "so_type" in _ord_cols else ", 'EQUIPMENT' AS so_type"
        srow = c.execute(
            f"SELECT id, order_no, order_date, due_date, ship_to, currency, total_amount, status{_so_type_col} "
            f"FROM orders WHERE id=? AND project_id=?",
            (so_id, pid)
        ).fetchone()
        if not srow:
            return PlainTextResponse("수주번호 매칭 안됨", 404)
        oicols = {r[1] for r in c.execute("PRAGMA table_info(order_items)").fetchall()}
        sel_extra = []
        # v5H226z13: 다운로드 SELECT 에 모든 부품/통관 컬럼 포함
        for col in ("unit_label", "line_note", "order_date", "due_date", "ship_to",
                    "currency", "unit_status", "is_export", "image_path",
                    "image_thumb_path", "linked_project_id",
                    # PARTS 기본 메타
                    "maker", "origin", "box_no", "spec", "arrival_status",
                    "supplier", "unit",
                    # v5H226z460: 상품 원가관리 — 매입단가·마진%
                    "cost_price", "margin_pct",
                    # PARTS 통관 (v5H226z5)
                    "hs_code", "duty_rate", "vat_rate",
                    "invoice_unit_price", "invoice_amount",
                    "invoice_unit_price_usd", "invoice_amount_usd",
                    "duty_krw", "duty_usd", "final_amount_usd",
                    "description", "pallet_size", "weight_kg",
                    "updated_at"):   # v5H226z408: 동시 편집 감지(호기 base_ts)
            if col in oicols:
                sel_extra.append(col)
        sel_extra_sql = (", " + ", ".join("oi." + x for x in sel_extra)) if sel_extra else ""
        join_sql = ""
        link_cols = ""
        if "linked_project_id" in oicols:
            join_sql = " LEFT JOIN projects lp ON lp.id = oi.linked_project_id"
            link_cols = ", lp.mgmt_code AS linked_mgmt_code, lp.name AS linked_project_name"
        items = [dict(r) for r in c.execute(
            f"SELECT oi.id, oi.qty, oi.unit_price, oi.amount{sel_extra_sql}{link_cols} "
            f"FROM order_items oi{join_sql} "
            f"WHERE oi.order_id=? ORDER BY oi.id ASC",
            (so_id,)
        ).fetchall()]
    is_co = (prow["project_type"] or "").upper() == "CONSUMABLE"
    # v5H226z: 부품 수출 (정식 PACKING LIST) — so_type 또는 프로젝트 shipment_form 으로 판별
    is_parts = ((srow["so_type"] or "").upper() == "PARTS_EXPORT") or ((prow["shipment_form"] or "").upper() == "PARTS")
    so_ccy = srow["currency"] or prow["currency"] or "KRW"
    so_ord = srow["order_date"] or ""
    so_due = srow["due_date"] or ""
    so_ship = srow["ship_to"] or ""
    # v5H226k: 헤더를 파서(parse_consumable_xlsx) 가 인식하는 키워드로 정렬
    # → 다운로드한 파일을 그대로(또는 편집 후) 다시 업로드해도 자동 매칭됨
    # CONSUMABLE: A~H 는 파서 자동 인식 컬럼, I~P 는 추가 정보 (파서 무시)
    if is_parts:
        # v5H226z/z5: 정식 PACKING LIST — 원본 엑셀 28컬럼 헤더 그대로 반영
        headers = [
            "사진",                          # A
            "순번",                          # B
            "관리코드",                      # C
            "수주번호",                      # D
            "BOX번호",                       # E
            "품명",                          # F
            "규격",                          # G
            "메이커",                        # H
            "업체명",                        # I
            "단위",                          # J
            "원산지",                        # K
            "출고수량",                      # L
            "단가\n(VAT 별도)",              # M
            "금액\n(VAT 별도)",              # N
            "입고 일정",                     # O
            "HS CODE",                       # P
            "DUTY",                          # Q
            "VAT",                           # R
            "인보이스 단가\n(VAT 별도)",     # S
            "인보이스 금액\n(VAT 별도)",     # T
            "인보이스 단가\n(USD)",          # U
            "인보이스 금액\n(USD)",          # V
            "관세\n(KRW)",                   # W
            "관세\n(USD)",                   # X
            "최종 금액\n(USD)",              # Y
            "상세 내용",                     # Z
            "PALLET SIZE\n(가로*세로*높이)", # AA
            "중량\n(kg)",                    # AB
        ]
    elif is_co:
        headers = ["사진",
                   "NO",
                   "MODEL USE (모델)",
                   "SUPPLIER NAME (품명)",
                   "SPEC (규격)",
                   "Q'TY (수량)",
                   "UNIT (단위)",
                   "ORDER DATE (발주일)",
                   "단가",
                   "금액",
                   "통화",
                   "거래",
                   "납기일",
                   "납품처",
                   "상태",
                   "비고"]
    else:
        headers = ["NO", "호기", "수량", "단가", "금액", "통화",
                   "거래", "발주일", "납기일", "납품처", "상태", "비고"]
    wb = Workbook()
    ws = wb.active
    ws.title = "정식 PACKING LIST" if is_parts else ("소모품" if is_co else "수주라인")
    # v5H226z: 부품 수출 (정식 PACKING LIST) — KNK 표준 회사 양식 5줄 메타
    if is_parts:
        ws.append(["KNK HAIST WORKS — 정식 PACKING LIST"])
        ws.append([f"관리코드: {prow['mgmt_code'] or '-'}",
                   "", f"프로젝트: {prow['name'] or '-'}",
                   "", f"수주번호: {srow['order_no'] or '-'}",
                   "", f"발주일: {so_ord}", "", f"통화: {so_ccy}",
                   "", f"상태: {srow['status'] or '-'}"])
        ws.append([f"수주 총액: {float(srow['total_amount'] or 0):,.0f} {so_ccy}",
                   f"라인 수: {len(items)}건"])
        ws.append(["⚠ 헤더 행(5행)은 변경하지 마세요. 28컬럼 자동 인식 (순번/관리코드/품명/규격/메이커/업체명/원산지/수량/단가/금액/입고일정/HS CODE/DUTY/VAT/인보이스(KRW·USD)/관세(KRW·USD)/최종 USD/상세/PALLET/중량). 라인만 추가/수정."])
        ws.append([])  # 빈 줄
    elif is_co:
        ws.append(["KNK HAIST WORKS — 소모품 수주 표준 양식"])
        ws.append([f"관리코드: {prow['mgmt_code'] or '-'}",
                   "", f"프로젝트: {prow['name'] or '-'}"])
        ws.append([f"수주번호: {srow['order_no'] or '-'}",
                   "", f"발주일: {so_ord}",
                   "", f"납기: {so_due}",
                   "", f"통화: {so_ccy}",
                   "", f"상태: {srow['status'] or '-'}"])
        ws.append(["⚠ 헤더 행(6행)은 변경하지 마세요. NO/MODEL USE/SUPPLIER NAME/Q'TY/UNIT/ORDER DATE 자동 인식. 라인 데이터만 추가/수정 가능."])
        ws.append([])  # 빈 줄
    else:
        ws.append([f"관리코드: {prow['mgmt_code'] or '-'}",
                   f"프로젝트: {prow['name'] or '-'}"])
        ws.append([f"수주번호: {srow['order_no'] or '-'}",
                   f"발주일: {so_ord}", f"납기일: {so_due}",
                   f"납품처: {so_ship or '-'}",
                   f"통화: {so_ccy}",
                   f"상태: {srow['status'] or '-'}"])
        ws.append([f"수주 총액: {float(srow['total_amount'] or 0):,.0f} {so_ccy}",
                   f"라인 수: {len(items)}건"])
        ws.append([])  # 빈 줄
    # 헤더 행
    hdr_row_idx = ws.max_row + 1
    ws.append(headers)
    # v5H226z13: 통일 폰트 9pt (대표 지시) + 깔끔한 디자인
    BASE_FONT = "맑은 고딕"  # 한글/영문 모두 가독성 우수
    BASE_SIZE = 9
    hdr_fill = PatternFill("solid", start_color="F4F1E8")  # 옅은 베이지 (Excel 표준 헤더 느낌)
    hdr_font = Font(bold=True, name=BASE_FONT, size=BASE_SIZE, color="3D3328")
    thin = Side(border_style="thin", color="BFBFBF")
    border = Border(top=thin, bottom=thin, left=thin, right=thin)
    for col_i in range(1, len(headers) + 1):
        cell = ws.cell(hdr_row_idx, col_i)
        cell.fill = hdr_fill
        cell.font = hdr_font
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
        cell.border = border
    # 헤더 행 높이 — 줄바꿈 있으니 충분히 크게
    if is_parts:
        ws.row_dimensions[hdr_row_idx].height = 36
    elif is_co:
        ws.row_dimensions[hdr_row_idx].height = 28
    else:
        ws.row_dimensions[hdr_row_idx].height = 22
    # v5H226k/z/z13: 메타 영역 셀 스타일 (CONSUMABLE / PARTS) — 폰트 9pt 통일
    if is_co or is_parts:
        title_cell = ws.cell(1, 1)
        title_cell.font = Font(bold=True, size=13, color="7C4A03", name=BASE_FONT)
        ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=len(headers))
        title_cell.alignment = Alignment(horizontal="center", vertical="center")
        ws.row_dimensions[1].height = 22
        # 메타 라인 2,3행 폰트 9pt
        for _row_idx in (2, 3):
            for _col_idx in range(1, len(headers) + 1):
                _c = ws.cell(_row_idx, _col_idx)
                if _c.value:
                    _c.font = Font(name=BASE_FONT, size=BASE_SIZE, color="3D3328")
                    _c.alignment = Alignment(vertical="center")
        # 안내 행 (4행) — 작은 회색 안내문
        guide_cell = ws.cell(4, 1)
        guide_cell.font = Font(italic=True, size=8, color="888888", name=BASE_FONT)
        ws.merge_cells(start_row=4, start_column=1, end_row=4, end_column=len(headers))
    # 데이터 행
    for idx, it in enumerate(items, 1):
        eff_ord = it.get("order_date") or so_ord
        eff_due = it.get("due_date") or so_due
        eff_ship = it.get("ship_to") or so_ship
        eff_ccy = it.get("currency") or so_ccy
        iex_raw = it.get("is_export")
        iex_label = "수출" if iex_raw == 1 else "내수"
        ust = it.get("unit_status") or "진행중"
        if is_parts:
            # v5H226z/z5: 정식 PACKING LIST 28컬럼 풀
            row = [
                "",                                          # A: 사진
                idx,                                         # B: 순번
                prow["mgmt_code"] or "",                     # C: 관리코드
                srow["order_no"] or "",                      # D: 수주번호
                it.get("box_no") or "",                      # E: BOX번호
                it.get("unit_label") or "",                  # F: 품명
                it.get("spec") or "",                        # G: 규격
                it.get("maker") or "",                       # H: 메이커
                it.get("supplier") or "",                    # I: 업체명
                it.get("unit") or "EA",                      # J: 단위
                it.get("origin") or "",                      # K: 원산지
                float(it.get("qty") or 0),                   # L: 출고수량
                float(it.get("unit_price") or 0),            # M: 단가(VAT 별도)
                float(it.get("amount") or 0),                # N: 금액(VAT 별도)
                it.get("arrival_status") or "",              # O: 입고 일정
                it.get("hs_code") or "",                     # P: HS CODE
                float(it.get("duty_rate") or 0) if it.get("duty_rate") not in (None, "") else "",  # Q: DUTY
                float(it.get("vat_rate") or 0) if it.get("vat_rate") not in (None, "") else "",    # R: VAT
                float(it.get("invoice_unit_price") or 0) if it.get("invoice_unit_price") not in (None, "") else "",   # S
                float(it.get("invoice_amount") or 0) if it.get("invoice_amount") not in (None, "") else "",           # T
                float(it.get("invoice_unit_price_usd") or 0) if it.get("invoice_unit_price_usd") not in (None, "") else "",  # U
                float(it.get("invoice_amount_usd") or 0) if it.get("invoice_amount_usd") not in (None, "") else "",   # V
                float(it.get("duty_krw") or 0) if it.get("duty_krw") not in (None, "") else "",   # W
                float(it.get("duty_usd") or 0) if it.get("duty_usd") not in (None, "") else "",   # X
                float(it.get("final_amount_usd") or 0) if it.get("final_amount_usd") not in (None, "") else "",  # Y
                it.get("description") or "",                 # Z
                it.get("pallet_size") or "",                 # AA
                float(it.get("weight_kg") or 0) if it.get("weight_kg") not in (None, "") else "",  # AB
            ]
        elif is_co:
            # v5H226k: 파서 인식 컬럼 순서 (NO/MODEL USE/SUPPLIER NAME/SPEC/Q'TY/UNIT/ORDER DATE)
            #          + 추가 정보 (단가/금액/통화/거래/납기일/납품처/상태/비고)
            # MODEL USE 에는 연결관리코드 우선, 없으면 unit_label 끝의 model 토큰
            model_field = it.get("linked_mgmt_code") or ""
            row = [
                "",  # A: 사진 — 아래에서 Image 객체로 삽입
                idx,                                    # B: NO
                model_field,                            # C: MODEL USE (모델)
                it.get("unit_label") or "",             # D: SUPPLIER NAME (품명)
                it.get("spec") or "",                   # E: SPEC (규격)
                float(it.get("qty") or 0),              # F: Q'TY (수량)
                "EA",                                   # G: UNIT (단위)
                eff_ord,                                # H: ORDER DATE (발주일)
                float(it.get("unit_price") or 0),       # I: 단가
                float(it.get("amount") or 0),           # J: 금액
                eff_ccy,                                # K: 통화
                iex_label,                              # L: 거래
                eff_due,                                # M: 납기일
                eff_ship,                               # N: 납품처
                ust,                                    # O: 상태
                it.get("line_note") or "",              # P: 비고
            ]
        else:
            row = [
                idx,
                it.get("unit_label") or f"호기 {idx}",
                float(it.get("qty") or 0),
                float(it.get("unit_price") or 0),
                float(it.get("amount") or 0),
                eff_ccy,
                iex_label,
                eff_ord,
                eff_due,
                eff_ship,
                ust,
                it.get("line_note") or "",
            ]
        ws.append(row)
    # 컬럼 폭. v5H226k: CONSUMABLE / v5H226z: PARTS
    widths_co = [12, 5, 18, 30, 16, 8, 8, 13, 12, 14, 8, 8, 13, 18, 10, 28]
    widths_eq = [5, 14, 8, 14, 16, 8, 8, 12, 12, 18, 10, 24]
    # v5H226z5: 28컬럼 (사진/순번/관리코드/수주번호/BOX/품명/규격/메이커/업체명/단위/원산지/
    #          출고수량/단가/금액/입고일정/HS/DUTY/VAT/인보이스(KRW단가/금액)/(USD단가/금액)/
    #          관세(KRW)/관세(USD)/최종USD/상세/PALLET/중량)
    widths_parts = [12, 5, 13, 14, 7, 26, 18, 12, 12, 6, 10, 9, 12, 14, 13,
                    11, 7, 7, 13, 13, 13, 13, 12, 12, 13, 22, 14, 9]
    if is_parts:
        widths = widths_parts
    elif is_co:
        widths = widths_co
    else:
        widths = widths_eq
    from openpyxl.utils import get_column_letter as _gcl
    for i, w in enumerate(widths, 1):
        ws.column_dimensions[_gcl(i)].width = w
    # 숫자 포맷
    # PARTS: L=출고수량(12), M=단가(13), N=금액(14), 추가 숫자: Q DUTY(17), R VAT(18),
    #        S~V 인보이스(19~22), W,X 관세(23,24), Y 최종USD(25), AB 중량(28)
    # CONSUMABLE: F=qty, I=unit_price, J=amount (6,9,10)
    # EQ: C=qty, D=unit_price, E=amount (3,4,5)
    if is_parts:
        qty_col, price_col, amount_col = 12, 13, 14
    elif is_co:
        qty_col, price_col, amount_col = 6, 9, 10
    else:
        qty_col, price_col, amount_col = 3, 4, 5
    # v5H226z13: 데이터 행 일괄 스타일 — 폰트 9pt, 테두리, 줄무늬, None → "" 정리
    data_font = Font(name=BASE_FONT, size=BASE_SIZE, color="3D3328")
    data_font_bold = Font(name=BASE_FONT, size=BASE_SIZE, color="3D3328", bold=True)
    stripe_fill = PatternFill("solid", start_color="FAF9F5")  # 짝수 행 살짝 회색
    thin_data = Side(border_style="thin", color="E0DDD5")
    data_border = Border(top=thin_data, bottom=thin_data, left=thin_data, right=thin_data)
    for r in range(hdr_row_idx + 1, ws.max_row + 1):
        # 줄무늬 (짝수 데이터 행)
        is_stripe = ((r - hdr_row_idx) % 2 == 0)
        for c_idx in range(1, len(headers) + 1):
            cell = ws.cell(r, c_idx)
            cell.font = data_font
            cell.border = data_border
            if is_stripe:
                cell.fill = stripe_fill
            # None 값을 빈 문자열로 (엑셀에 None 표시 안 되도록)
            if cell.value is None:
                cell.value = ""
            # 정렬 — 숫자 컬럼은 우측, 텍스트는 좌측, 짧은 식별 컬럼은 가운데
            cell.alignment = Alignment(vertical="center", wrap_text=False)
        # 숫자 포맷
        for c_idx in (price_col, amount_col):
            ws.cell(r, c_idx).number_format = _z46_mfmt(so_ccy)   # z1191z46: 달러면 둘째 자리(전엔 #,##0 — 센트가 안 보였다)
            ws.cell(r, c_idx).alignment = Alignment(horizontal="right", vertical="center")
        ws.cell(r, qty_col).number_format = '#,##0.##'
        ws.cell(r, qty_col).alignment = Alignment(horizontal="right", vertical="center")
        # v5H226z5: 추가 숫자 컬럼 포맷
        if is_parts:
            # 가운데 정렬 컬럼 (B 순번, E BOX, J 단위)
            for c_idx in (2, 5, 10):
                ws.cell(r, c_idx).alignment = Alignment(horizontal="center", vertical="center")
            # DUTY/VAT 는 비율 (0.1 = 10%)
            for c_idx in (17, 18):
                ws.cell(r, c_idx).number_format = '0.0%'
                ws.cell(r, c_idx).alignment = Alignment(horizontal="right", vertical="center")
            # 인보이스 KRW 단가/금액 (정수)
            for c_idx in (19, 20):
                ws.cell(r, c_idx).number_format = '#,##0'
                ws.cell(r, c_idx).alignment = Alignment(horizontal="right", vertical="center")
            # 인보이스 USD 단가/금액, 관세 USD, 최종 USD (소수 2자리)
            for c_idx in (21, 22, 24, 25):
                ws.cell(r, c_idx).number_format = '#,##0.00'
                ws.cell(r, c_idx).alignment = Alignment(horizontal="right", vertical="center")
            # 관세 KRW (정수)
            ws.cell(r, 23).number_format = '#,##0'
            ws.cell(r, 23).alignment = Alignment(horizontal="right", vertical="center")
            # 중량 (소수)
            ws.cell(r, 28).number_format = '#,##0.##'
            ws.cell(r, 28).alignment = Alignment(horizontal="right", vertical="center")
            # 최종 금액 USD 굵게 강조
            ws.cell(r, 25).font = data_font_bold
            # HS CODE monospace 느낌 (가운데 정렬)
            ws.cell(r, 16).alignment = Alignment(horizontal="center", vertical="center")
        # 데이터 행 높이 (PARTS 는 사진 행이라 더 크게)
        if is_parts and (r > hdr_row_idx):
            ws.row_dimensions[r].height = 50
        elif is_co and (r > hdr_row_idx):
            ws.row_dimensions[r].height = 50
    # v5H226z13: 헤더 고정 (스크롤 시 헤더 보임)
    ws.freeze_panes = ws.cell(hdr_row_idx + 1, 3 if (is_co or is_parts) else 2).coordinate
    # v5H226j/z: CONSUMABLE / PARTS 일 때 썸네일 이미지를 사진 컬럼(A) 에 직접 삽입
    if is_co or is_parts:
        from openpyxl.drawing.image import Image as XLImage
        from PIL import Image as PILImage
        img_root = os.path.join(BASE, "uploads")
        for line_idx, it in enumerate(items):
            thumb_url = it.get("image_thumb_path") or ""
            if not thumb_url:
                continue
            # /uploads/consumables/proj_X/file.jpg → 디스크 절대 경로
            rel = thumb_url.lstrip("/").replace("uploads/", "", 1)
            disk_path = os.path.join(img_root, rel)
            if not os.path.isfile(disk_path):
                continue
            try:
                xli = XLImage(disk_path)
                # 셀 안에 들어가도록 80x60 픽셀로 축소 (썸네일이 240인 경우 줄임)
                xli.width = 80
                xli.height = 60
                cell_addr = ws.cell(hdr_row_idx + 1 + line_idx, 1).coordinate
                ws.add_image(xli, cell_addr)
                # 행 높이 (포인트 단위, 1pt ~ 1.33px)
                ws.row_dimensions[hdr_row_idx + 1 + line_idx].height = 50
            except Exception as e:
                print(f"[v5H226j] xlsx image insert err line {line_idx+1}: {e}")
    # 출력
    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)
    fn_safe = f"{prow['mgmt_code'] or 'NA'}_{srow['order_no'] or 'SO'}_{so_ord or ''}.xlsx".replace(" ", "_")
    from urllib.parse import quote
    headers_resp = {
        "Content-Disposition": f"attachment; filename*=UTF-8''{quote(fn_safe)}",
        "Cache-Control": "no-store",
    }
    return Response(
        content=buf.getvalue(),
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers=headers_resp,
    )


@app.post("/projects/{pid:int}/import-consumable-lines/parse")
async def projects_import_consumable_parse(req: Request, pid: int,
                                            file: UploadFile = File(...)):
    """v5H226: 소모품 엑셀 업로드 — 1단계: 파싱 + 미리보기 JSON 반환.
    기존 consumables.parse_consumable_xlsx 파서 재활용.
    각 라인의 model_use 로 장비 mgmt_code 자동 매칭 시도(linked_mgmt_code 필드)."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"ok": False, "message": "권한 없음"}, 403)
    try:
        from . import consumables as _co_local
    except Exception as e:
        return JSONResponse({"ok": False, "message": f"파서 로드 실패: {e}"}, 500)
    # v5H226f: 업로드 파일 검증 — 확장자 화이트리스트 + 크기 제한 (50MB)
    _orig_name = file.filename or "upload.xlsx"
    _ext = os.path.splitext(_orig_name)[1].lower()
    if _ext not in (".xlsx", ".xls"):
        return JSONResponse({"ok": False,
                              "message": f"엑셀 파일만 업로드 가능 (.xlsx/.xls). 현재: {_ext or '(확장자 없음)'}"}, 400)
    raw = await file.read()
    if len(raw) > 50 * 1024 * 1024:
        return JSONResponse({"ok": False,
                              "message": f"파일 크기가 너무 큽니다 ({len(raw)//1024//1024}MB). 최대 50MB."}, 400)
    if len(raw) < 100:
        return JSONResponse({"ok": False, "message": "빈 파일이거나 손상된 파일입니다"}, 400)
    # 안전한 파일명 (디렉토리 traversal 방지)
    _safe_name = "".join(c for c in os.path.basename(_orig_name) if c.isalnum() or c in "._-") or "upload.xlsx"
    tmp_dir = tempfile.mkdtemp(prefix=f"co_import_{pid}_")
    tmp_path = os.path.join(tmp_dir, _safe_name)
    with open(tmp_path, "wb") as f:
        f.write(raw)
    # v5H226c: 이미지 영구 저장 폴더 (프로젝트 단위) — /uploads/consumables/proj_{pid}/
    img_dir = os.path.join(BASE, "uploads", "consumables", f"proj_{pid}")
    os.makedirs(img_dir, exist_ok=True)
    try:
        result = _co_local.parse_consumable_xlsx(tmp_path, image_out_dir=img_dir)
    except Exception as e:
        return JSONResponse({"ok": False, "message": f"파싱 실패: {e}"}, 400)
    lines = result.get("lines") or []
    if not lines:
        return JSONResponse({"ok": False,
                              "message": result.get("error") or "유효한 라인이 없습니다"}, 400)
    # v5H226c: 헤더 raw text + col_map → 미리보기 모달에 노출 (학습형 매핑 가시화)
    col_map = result.get("col_map") or {}
    hdr_row = result.get("header_row") or 0
    images = result.get("images") or {}
    raw_headers = []
    try:
        from openpyxl import load_workbook
        _wb = load_workbook(tmp_path, data_only=True, read_only=True)
        _ws = _wb.worksheets[0]
        if hdr_row:
            for cidx in range(1, min(_ws.max_column or 30, 30) + 1):
                v = _ws.cell(hdr_row, cidx).value
                raw_headers.append(str(v) if v is not None else "")
        _wb.close()
    except Exception:
        pass
    # model_use → 장비 mgmt_code 자동 매칭 (간단 — projects.model_name 또는 mgmt_code substring)
    out_rows = []
    with db_session() as c:
        for ln in lines:
            mu = (ln.get("model_use") or "").strip()
            linked_pid = None
            linked_code = None
            if mu:
                try:
                    cand = c.execute(
                        "SELECT id, mgmt_code FROM projects WHERE "
                        "mgmt_code = ? OR model_name LIKE ? OR name LIKE ? "
                        "ORDER BY id DESC LIMIT 1",
                        (mu, f"%{mu}%", f"%{mu}%")
                    ).fetchone()
                    if cand:
                        linked_pid = cand["id"]
                        linked_code = cand["mgmt_code"]
                except Exception:
                    pass
            ln_no = ln.get("line_no")
            # v5H226c: 라인별 이미지 — 첫번째 컷만 사용 (다중 첨부는 추후)
            img_full = ""
            img_thumb = ""
            try:
                _imgs = images.get(ln_no) if isinstance(images, dict) else None
                if _imgs and isinstance(_imgs, list) and _imgs:
                    img_full = _imgs[0].get("full") or ""
                    img_thumb = _imgs[0].get("thumb") or ""
            except Exception:
                pass
            out_rows.append({
                "line_no": ln_no,
                "model_use": mu,
                "part_name": ln.get("part_name") or "",
                "spec": ln.get("spec") or "",
                "qty": float(ln.get("qty") or 0),
                "unit": ln.get("unit") or "EA",
                "unit_price": 0,  # 엑셀에 단가 컬럼 별도 매핑 시 보정
                "order_date": ln.get("order_date") or "",
                "linked_project_id": linked_pid,
                "linked_mgmt_code": linked_code,
                # 이미지 — 상대 파일명 (URL prefix 는 클라이언트에서 부착)
                "image_file": img_full,
                "image_thumb_file": img_thumb,
            })
    # 매핑 표시용 — col_idx 를 엑셀 컬럼문자(A/B/...) 로 변환
    def _col_letter(idx):
        s = ""
        n = int(idx)
        while n > 0:
            n, r = divmod(n - 1, 26)
            s = chr(65 + r) + s
        return s or "?"
    mapping_pretty = {}
    for k, cidx in col_map.items():
        try:
            mapping_pretty[k] = {
                "col": _col_letter(cidx),
                "header": raw_headers[cidx - 1] if cidx - 1 < len(raw_headers) else ""
            }
        except Exception:
            pass
    img_count = sum(len(v) for k, v in images.items()
                    if isinstance(v, list) and k != "_errors") if isinstance(images, dict) else 0
    return JSONResponse({
        "ok": True,
        "rows": out_rows,
        "count": len(out_rows),
        "header_row": hdr_row,
        "raw_headers": raw_headers,
        "mapping": mapping_pretty,
        "image_count": img_count,
        "image_url_prefix": f"/uploads/consumables/proj_{pid}/",
    })


@app.post("/projects/{pid:int}/import-consumable-lines/confirm")
async def projects_import_consumable_confirm(req: Request, pid: int):
    """v5H226: 소모품 엑셀 업로드 — 2단계: 미리보기 행을 order_items 에 일괄 INSERT.
    기존 SO(order_id) 에 라인 추가 + total_amount/unit_qty 자동 갱신."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"ok": False, "message": "권한 없음"}, 403)
    body = await req.json()
    so_id = int(body.get("so_id") or 0)
    rows = body.get("rows") or []
    if not so_id or not rows:
        return JSONResponse({"ok": False, "message": "so_id 또는 rows 누락"}, 400)
    inserted = 0
    last_err = None
    _ins = []   # (row, order_items.id) — 대표규정 §4 규칙47: 확정 후 '원본↔저장' 대조(방금 넣은 항목만 1:1)
    with db_session() as c:
        # SO 검증
        so = c.execute("SELECT id, project_id, currency FROM orders WHERE id=?",
                        (so_id,)).fetchone()
        if not so or so["project_id"] != pid:
            return JSONResponse({"ok": False, "message": "수주번호 매칭 안됨"}, 400)
        oicols = {r2[1] for r2 in c.execute("PRAGMA table_info(order_items)").fetchall()}
        for r in rows:
            try:
                qty = float(r.get("qty") or 0)
                up = float(r.get("unit_price") or 0)
                amt = round(qty * up, 2)
                cols = ["order_id", "unit_label", "qty",
                        "unit_price", "amount", "unit_status"]
                vals = [so_id, (r.get("part_name") or "").strip(),
                        qty, up, amt, "진행중"]
                # 라인 비고 (spec)
                if "line_note" in oicols:
                    cols.append("line_note")
                    vals.append((r.get("spec") or "").strip())
                # currency 부모 상속
                if "currency" in oicols:
                    cols.append("currency")
                    vals.append(so["currency"] or "KRW")
                # linked_project_id (장비 매칭)
                if "linked_project_id" in oicols and r.get("linked_project_id"):
                    cols.append("linked_project_id")
                    vals.append(int(r["linked_project_id"]))
                # v5H226c: order_date override
                if "order_date" in oicols and r.get("order_date"):
                    cols.append("order_date")
                    vals.append(str(r.get("order_date")).strip())
                # v5H226c: 이미지 경로 (URL prefix 포함)
                _img_pref = f"/uploads/consumables/proj_{pid}/"
                if "image_path" in oicols and r.get("image_file"):
                    cols.append("image_path")
                    vals.append(_img_pref + str(r.get("image_file")))
                if "image_thumb_path" in oicols and r.get("image_thumb_file"):
                    cols.append("image_thumb_path")
                    vals.append(_img_pref + str(r.get("image_thumb_file")))
                placeholders = ",".join(["?"] * len(vals))
                _cur = c.execute(
                    f"INSERT INTO order_items({','.join(cols)}) VALUES({placeholders})",
                    vals
                )
                inserted += 1
                _ins.append((r, _cur.lastrowid))   # §4 규칙47: 이 행이 넣은 호기(대조용)
            except Exception as e:
                last_err = str(e)
                print(f"[v5H226] line insert err: {e}")
        # SO 합계·수량 갱신
        try:
            agg = c.execute(
                "SELECT COALESCE(SUM(amount),0) AS t, COUNT(*) AS n "
                "FROM order_items WHERE order_id=?",
                (so_id,)
            ).fetchone()
            c.execute(
                "UPDATE orders SET total_amount=?, unit_qty=? WHERE id=?",
                (float(agg["t"] or 0), int(agg["n"] or 0), so_id)
            )
            # 프로젝트 order_amount 도 갱신
            proj_total = _apply_project_amount(c, pid) or 0  # z1097b: 통화별 환산(옛 SUM 은 원화+달러를 그냥 더했다)
        except Exception:
            pass
        # 변경 이력
        try:
            c.execute(
                "INSERT INTO project_history(project_id, changed_by, field, old_value, new_value, note) "
                "VALUES(?,?,?,?,?,?)",
                (pid, u.get("id"), "엑셀 업로드", "", f"{inserted}건",
                 f"수주번호 #{so_id} 에 라인 {inserted}건 일괄 추가")
            )
        except Exception:
            pass
        # 대표규정(2026-07-28·§4 규칙47): 확정 후 '엑셀 원본 ↔ 저장값' 대조 — 방금 넣은 항목만 그 행과 1:1(매칭 모호성 0).
        _vout = {"checked": 0, "ok": True, "diff": [], "fields": "품명·수량·단가·비고·발주일"}
        try:
            def _vs(v):
                return str(v).strip() if v not in (None, "") else ""

            def _vn(v):
                try:
                    return round(float(str(v).replace(",", "").strip()), 2)
                except Exception:
                    return None

            def _vadd(nm, fld, ex, sv):
                _vout["ok"] = False
                if len(_vout["diff"]) < 20:
                    _vout["diff"].append({"row": 0, "name": str(nm or "")[:24], "field": fld,
                                          "excel": ("" if ex is None else str(ex)), "saved": ("" if sv is None else str(sv))})

            for _r, _iid in _ins:
                _it = c.execute("SELECT unit_label, qty, unit_price, line_note, order_date "
                                "FROM order_items WHERE id=?", (_iid,)).fetchone()
                _pn = _vs(_r.get("part_name"))
                if not _it:
                    _vadd(_pn, "행", "있음", "저장 안 됨")
                    continue
                _d = dict(_it); _vout["checked"] += 1
                if _pn and _pn != _vs(_d.get("unit_label")):
                    _vadd(_pn, "품명", _pn, _vs(_d.get("unit_label")))
                _q = _vn(_r.get("qty"))
                if _q is not None and _q != _vn(_d.get("qty")):
                    _vadd(_pn, "수량", _q, _vn(_d.get("qty")))
                _up = _vn(_r.get("unit_price"))
                if _up is not None and _up != _vn(_d.get("unit_price")):
                    _vadd(_pn, "단가", _up, _vn(_d.get("unit_price")))
                if _vs(_r.get("spec")) and _vs(_r.get("spec")) != _vs(_d.get("line_note")):
                    _vadd(_pn, "비고", _vs(_r.get("spec")), _vs(_d.get("line_note")))
                if _vs(_r.get("order_date")):
                    _eo = _vs(_r.get("order_date"))[:10]
                    if _eo != _vs(_d.get("order_date"))[:10]:
                        _vadd(_pn, "발주일", _eo, _vs(_d.get("order_date"))[:10])
        except Exception as _ve:
            _vout["error"] = str(_ve)[:120]
    if inserted == 0:
        return JSONResponse({"ok": False,
                              "message": f"0건 등록 — DB 오류: {last_err or '알 수 없음'}"}, 500)
    return JSONResponse({"ok": True, "inserted": inserted, "verify": _vout})


# ============================================================
# v5H226z: 정식 PACKING LIST (부품 형태 출고) 엑셀 업로드 파서
# ============================================================
def _parse_packing_list_xlsx(file_path: str) -> dict:
    """KNK 정식 PACKING LIST 양식 파서.
    헤더 키워드 자동 인식: 순번/관리코드/수주번호/BOX/품명/규격/메이커/업체명/
                              단위/원산지/출고수량(수량)/단가/금액/입고일정"""
    from openpyxl import load_workbook
    import re as _re_pl
    # v5H226z2: 헤더 키워드 보강 — 원본 엑셀 표기(단가(VAT 별도) / 입고 일정 / 줄바꿈) 흡수
    # _norm() 가 공백·줄바꿈 제거 + 대문자화 → 키워드도 동일 정규화 후 부분일치
    HEADER_KEYS = [
        ("no",          ["순번", "NO", "번호", "ITEMNO", "SEQ"]),
        ("mgmt_code",   ["관리코드", "관리번호", "MGMTCODE", "MGMT", "MNGCODE"]),
        ("order_no",    ["수주번호", "수주No", "ORDERNO", "SO번호", "PO번호", "PONO"]),
        ("box_no",      ["BOX번호", "BOXNO", "BOX", "포장번호", "PALLET"]),
        ("part_name",   ["품명", "PARTNAME", "ITEMNAME", "SUPPLIERNAME", "DESCRIPTION", "PRODUCT"]),
        ("spec",        ["규격", "SPEC", "MODEL", "SPECIFICATION", "SIZE"]),
        ("maker",       ["메이커", "MAKER", "BRAND", "제조사", "MANUFACTURER", "MFR"]),
        ("supplier",    ["업체명", "SUPPLIER", "VENDOR", "공급사", "거래처"]),
        ("unit",        ["단위", "UNIT", "UOM"]),
        ("origin",      ["원산지", "ORIGIN", "MADEIN", "MADE IN", "COO", "COUNTRYOFORIGIN"]),
        # 출고수량/수량 — '단가/금액' 보다 먼저 평가되어 '수량' substring 충돌 회피
        ("qty",         ["출고수량", "수량", "Q'TY", "QTY", "QUANTITY", "EA"]),
        # v5H226z460(대표 지시): 상품 원가관리 — 매입단가·마진%. 반드시 unit_price('단가') 보다 먼저 평가
        #   ('매입단가'에 '단가' substring 포함 → 뒤에 두면 unit_price 가 매입단가 칸을 가로챔)
        ("cost_price",  ["매입단가", "매입가", "구매단가", "원가단가", "매입", "원가", "COST", "BUYINGPRICE", "PURCHASEPRICE", "BUYPRICE"]),
        ("margin_pct",  ["마진율", "마진%", "마진", "MARGINRATE", "MARGIN", "MARKUP"]),
        # 단가/금액 — VAT 별도 등 부속 텍스트 포함된 셀과 매칭. 'PRICE' 도 흡수 (판매단가)
        ("unit_price",  ["판매단가", "단가", "UNITPRICE", "UNIT PRICE", "PRICE", "U/PRICE", "UPRICE"]),
        ("amount",      ["금액", "AMOUNT", "TOTALPRICE", "TOTAL"]),
        # 입고 일정 (공백 포함 원본) / 입고일정 / ARRIVAL DATE / ETA 등
        ("arrival_status", ["입고일정", "입고", "ARRIVAL", "ETA", "DELIVERY"]),
        # v5H226z5: 통관 (정식 PACKING LIST 추가 컬럼)
        ("hs_code",                ["HSCODE", "HS코드", "HS"]),
        ("duty_rate",              ["DUTY", "관세율"]),
        ("vat_rate",               ["VAT", "부가세율"]),
        # 인보이스 단가/금액 (KRW VAT 별도)
        ("invoice_unit_price",     ["인보이스단가(VAT별도)", "인보이스단가(VAT", "인보이스단가KRW", "INVOICEUNITPRICEKRW"]),
        ("invoice_amount",         ["인보이스금액(VAT별도)", "인보이스금액(VAT", "인보이스금액KRW", "INVOICEAMOUNTKRW"]),
        # 인보이스 단가/금액 (USD)
        ("invoice_unit_price_usd", ["인보이스단가(USD)", "인보이스단가USD", "INVOICEPRICEUSD"]),
        ("invoice_amount_usd",     ["인보이스금액(USD)", "인보이스금액USD", "INVOICEAMOUNTUSD"]),
        # 관세 (KRW/USD)
        ("duty_krw",               ["관세KRW", "관세(KRW)", "관세원"]),
        ("duty_usd",               ["관세USD", "관세(USD)", "관세달러"]),
        # 최종 금액 USD (인보이스+관세)
        ("final_amount_usd",       ["최종금액USD", "최종금액", "FINALUSD", "TOTALUSD"]),
        # 상세 내용 / PALLET / 중량
        ("description",            ["상세내용", "DETAIL", "DESCRIPTION", "REMARK", "비고"]),
        ("pallet_size",            ["PALLETSIZE", "PALLET", "팔레트", "팔렛"]),
        ("weight_kg",              ["중량KG", "중량", "WEIGHT", "GROSSWEIGHT", "G/W"]),
    ]
    def _norm(s):
        if s is None: return ""
        return _re_pl.sub(r"\s+", "", str(s)).upper()
    wb = load_workbook(file_path, data_only=True)
    ws = wb.worksheets[0]
    # 헤더 행 자동 감지 (1~10행)
    best_row, best_map = 0, {}
    for r in range(1, min(ws.max_row, 10) + 1):
        cur_map, used = {}, set()
        for c in range(1, min(ws.max_column, 30) + 1):
            v = _norm(ws.cell(r, c).value)
            if not v:
                continue
            for key, kws in HEADER_KEYS:
                if key in cur_map or c in used:
                    continue
                for kw in kws:
                    if _norm(kw) in v:
                        cur_map[key] = c
                        used.add(c)
                        break
        if "part_name" in cur_map and "qty" in cur_map:
            if len(cur_map) > len(best_map):
                best_row, best_map = r, cur_map
    if best_row == 0 or "part_name" not in best_map:
        return {"lines": [], "header_row": 0, "col_map": {},
                "error": "헤더를 찾지 못했습니다 (품명/수량 컬럼이 1~10행 안에 있어야 합니다)"}
    # v5H226z5: 병합된 헤더 셀 처리 — '관세(KRW) (USD)' 같이 한 셀에 KRW/USD 합쳐진 경우
    # duty_krw 만 매핑되고 duty_usd 가 누락됐을 때 → 다음 컬럼이 비어있으면 duty_usd 로 추정
    if "duty_krw" in best_map and "duty_usd" not in best_map:
        _next_col = best_map["duty_krw"] + 1
        _next_v = _norm(ws.cell(best_row, _next_col).value)
        if not _next_v:  # 병합된 빈 헤더 — USD 라고 추정
            best_map["duty_usd"] = _next_col
    # v5H226z5: 다른 KRW/USD 페어도 동일 처리 (인보이스 단가/금액)
    for _krw_key, _usd_key in [("invoice_unit_price", "invoice_unit_price_usd"),
                                ("invoice_amount", "invoice_amount_usd")]:
        if _krw_key in best_map and _usd_key not in best_map:
            _next_col = best_map[_krw_key] + 1
            _next_v = _norm(ws.cell(best_row, _next_col).value)
            if not _next_v:
                best_map[_usd_key] = _next_col
    pn_col = best_map["part_name"]
    lines = []
    line_no = 0
    for r in range(best_row + 1, ws.max_row + 1):
        pn = ws.cell(r, pn_col).value
        if pn is None or str(pn).strip() == "":
            continue
        line_no += 1
        def gv(key):
            return ws.cell(r, best_map[key]).value if key in best_map else None
        def gnum(key):
            v = gv(key)
            if v is None or v == "": return 0
            try:
                return float(str(v).replace(",", "").strip())
            except Exception:
                return 0
        lines.append({
            "row": r, "line_no": line_no,
            "part_name": str(pn).strip(),
            "spec":      (str(gv("spec") or "").strip()),
            "maker":     (str(gv("maker") or "").strip()),
            "origin":    (str(gv("origin") or "").strip()),
            "box_no":    (str(gv("box_no") or "").strip()),
            "supplier":  (str(gv("supplier") or "").strip()),
            "unit":      (str(gv("unit") or "EA").strip()) or "EA",
            "qty":       gnum("qty"),
            "unit_price": gnum("unit_price"),
            "amount":    gnum("amount"),
            # v5H226z460(대표 지시): 상품 원가관리 — 매입단가·마진%(가산). 판매단가 비면 confirm 에서 매입×(1+마진) 산출
            "cost_price": gnum("cost_price"),
            "margin_pct": gnum("margin_pct"),
            "arrival_status": (str(gv("arrival_status") or "").strip()),
            "mgmt_code": (str(gv("mgmt_code") or "").strip()),
            # v5H226z5: 통관 (HS CODE / DUTY / VAT / 인보이스 / 관세 / 최종 / 상세 / PALLET / 중량)
            "hs_code":   (str(gv("hs_code") or "").strip()),
            "duty_rate": gnum("duty_rate"),
            "vat_rate":  gnum("vat_rate"),
            "invoice_unit_price":     gnum("invoice_unit_price"),
            "invoice_amount":         gnum("invoice_amount"),
            "invoice_unit_price_usd": gnum("invoice_unit_price_usd"),
            "invoice_amount_usd":     gnum("invoice_amount_usd"),
            "duty_krw":         gnum("duty_krw"),
            "duty_usd":         gnum("duty_usd"),
            "final_amount_usd": gnum("final_amount_usd"),
            "description":      (str(gv("description") or "").strip()),
            "pallet_size":      (str(gv("pallet_size") or "").strip()),
            "weight_kg":        gnum("weight_kg"),
        })
    return {"lines": lines, "header_row": best_row, "col_map": best_map}


@app.post("/projects/{pid:int}/import-parts-lines/parse")
async def projects_import_parts_parse(req: Request, pid: int,
                                       file: UploadFile = File(...)):
    """v5H226z: 정식 PACKING LIST 엑셀 업로드 — 1단계: 파싱 + 미리보기 JSON.
    소모품 흐름과 동일 패턴, 다만 PACKING LIST 14컬럼 헤더 자동 인식."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"ok": False, "message": "권한 없음"}, 403)
    raw = await file.read()
    if len(raw) > 50 * 1024 * 1024:
        return JSONResponse({"ok": False, "message": "파일 크기 50MB 초과"}, 413)
    if not (file.filename or "").lower().endswith((".xlsx", ".xls")):
        return JSONResponse({"ok": False, "message": "엑셀 파일(.xlsx/.xls) 만 허용"}, 400)
    tmp_dir = tempfile.mkdtemp(prefix=f"parts_import_{pid}_")
    tmp_path = os.path.join(tmp_dir, file.filename or "upload.xlsx")
    with open(tmp_path, "wb") as f:
        f.write(raw)
    # 이미지 영구 저장 폴더
    img_dir = os.path.join(BASE, "uploads", "consumables", f"proj_{pid}")
    os.makedirs(img_dir, exist_ok=True)
    try:
        result = _parse_packing_list_xlsx(tmp_path)
    except Exception as e:
        return JSONResponse({"ok": False, "message": f"파싱 실패: {e}"}, 400)
    lines = result.get("lines") or []
    if not lines:
        return JSONResponse({"ok": False,
                              "message": result.get("error") or "유효한 라인이 없습니다"}, 400)
    # v5H226z: 이미지 추출 (소모품과 동일 — anchor row 매칭)
    images = {}
    try:
        from . import consumables as _co_local
        from PIL import Image as _PIL
        from openpyxl import load_workbook as _lwb
        _wb_img = _lwb(tmp_path, data_only=True)
        _ws_img = _wb_img.worksheets[0]
        for idx, img in enumerate(getattr(_ws_img, "_images", []) or []):
            try:
                a = img.anchor
                row1 = a._from.row + 1
                raw_img = img._data()
                if not raw_img:
                    continue
                # 가장 가까운 라인 매칭
                cands = [ln for ln in lines if ln["row"] <= row1 + 2]
                matched = max(cands, key=lambda ln: ln["row"]) if cands else min(lines, key=lambda ln: abs(ln["row"] - row1))
                if not matched:
                    continue
                fn = f"parts_line_{matched['line_no']:03d}_{idx+1}.jpg"
                fn_thumb = f"parts_line_{matched['line_no']:03d}_{idx+1}_thumb.jpg"
                full = os.path.join(img_dir, fn)
                thumb = os.path.join(img_dir, fn_thumb)
                big_b, thumb_b, _ = _co_local.compress_image_bytes(raw_img)
                with open(full, "wb") as f: f.write(big_b)
                with open(thumb, "wb") as f: f.write(thumb_b)
                images.setdefault(matched["line_no"], []).append({"full": fn, "thumb": fn_thumb})
            except Exception:
                pass
    except Exception:
        pass
    out_rows = []
    for ln in lines:
        ln_no = ln.get("line_no")
        img_full = ""
        img_thumb = ""
        _imgs = images.get(ln_no) if isinstance(images, dict) else None
        if _imgs and _imgs:
            img_full = _imgs[0].get("full") or ""
            img_thumb = _imgs[0].get("thumb") or ""
        out_rows.append({
            "line_no": ln_no,
            "part_name": ln["part_name"],
            "spec": ln["spec"],
            "maker": ln["maker"],
            "supplier": ln["supplier"],
            "origin": ln["origin"],
            "box_no": ln["box_no"],
            "qty": ln["qty"],
            "unit": ln["unit"],
            "unit_price": ln["unit_price"],
            "amount": ln["amount"],
            "arrival_status": ln["arrival_status"],
            "mgmt_code": ln["mgmt_code"],
            # v5H226z5: 통관 메타
            "hs_code":  ln.get("hs_code", ""),
            "duty_rate": ln.get("duty_rate", 0),
            "vat_rate":  ln.get("vat_rate", 0),
            "invoice_unit_price":     ln.get("invoice_unit_price", 0),
            "invoice_amount":         ln.get("invoice_amount", 0),
            "invoice_unit_price_usd": ln.get("invoice_unit_price_usd", 0),
            "invoice_amount_usd":     ln.get("invoice_amount_usd", 0),
            "duty_krw":         ln.get("duty_krw", 0),
            "duty_usd":         ln.get("duty_usd", 0),
            "final_amount_usd": ln.get("final_amount_usd", 0),
            "description":      ln.get("description", ""),
            "pallet_size":      ln.get("pallet_size", ""),
            "weight_kg":        ln.get("weight_kg", 0),
            "image_file": img_full,
            "image_thumb_file": img_thumb,
        })
    img_count = sum(len(v) for v in images.values() if isinstance(v, list))
    # mapping 미리보기
    def _col_letter(idx):
        s = ""
        n = int(idx)
        while n > 0:
            n, r = divmod(n - 1, 26)
            s = chr(65 + r) + s
        return s or "?"
    mapping = {k: _col_letter(c) for k, c in result["col_map"].items()}
    return JSONResponse({
        "ok": True, "rows": out_rows, "count": len(out_rows),
        "header_row": result["header_row"],
        "mapping": mapping,
        "image_count": img_count,
        "image_url_prefix": f"/uploads/consumables/proj_{pid}/",
    })


def _so_is_parts974(c, oid) -> bool:
    """v5H226z974 (대표 지시): 이 SO가 상품(PARTS_EXPORT)인지 — 상품 수주의 unit_qty 는
    '완제품 몇 대분'(사람 입력값·1이면 1식)이라, 부품 줄 수(1줄=부품 1종)로 자동 재계산하면 안 됨(보존 게이트).
    so_type 컬럼이 없거나 조회 실패면 False(=기존 동작 그대로)."""
    try:
        r = c.execute("SELECT COALESCE(so_type,'') FROM orders WHERE id=?", (oid,)).fetchone()
        return str((r[0] if r else "") or "").upper() == "PARTS_EXPORT"
    except Exception:
        return False


_BOARD_UNITS_Z4D = ("EA", "식", "SET", "대")   # z1191z4d (대표 지시): 「대」 추가 — 제품 표시수량·기타 수량 단위


def _z4d_set_unit(c, pid, unit, latest_only=True):
    """z1191z4d: 형태=기타 수주의 수량 단위(orders.board_unit) 기록 — 표시 전용(금액·수량 계산 무관).
    latest_only=True: 대표 SO(취소 제외 · 최신 1건 = 수정 화면이 읽는 SO) / False: 이 프로젝트 SO 전부(신규 등록 직후)."""
    cols = {r[1] for r in c.execute("PRAGMA table_info(orders)").fetchall()}
    if "board_unit" not in cols or unit not in _BOARD_UNITS_Z4D:
        return 0
    if latest_only:
        r = c.execute("SELECT id FROM orders WHERE project_id=? AND COALESCE(status,'')<>'CANCELLED' "
                      "ORDER BY id DESC LIMIT 1", (pid,)).fetchone()
        if not r:
            return 0
        return c.execute("UPDATE orders SET board_unit=? WHERE id=?", (unit, r[0])).rowcount
    return c.execute("UPDATE orders SET board_unit=? WHERE project_id=?", (unit, pid)).rowcount


def _so_is_semi_z4c(c, oid) -> bool:
    """z1191z4c (이새롬 프로 요청 · 대표 결정): 이 수주가 「제품」인가 — 상세 수주 카드 배지와 **같은 판정**
    (get_project_orders → so_form_label_key: so_form · so_type · 'N호기' 줄 수 · 프로젝트 유형) +
    프로젝트 형태가 제품(SEMI)인 경우. 소모품 프로젝트·상품은 아니다(각자 경로가 따로 있다)."""
    import re as _re_s
    o = c.execute("SELECT * FROM orders WHERE id=?", (oid,)).fetchone()
    if not o:
        return False
    o = dict(o)
    pr = c.execute("SELECT COALESCE(project_type,'NEW_EQUIP') AS pt, COALESCE(shipment_form,'') AS sf "
                   "FROM projects WHERE id=?", (o.get("project_id"),)).fetchone()
    pt = ((pr["pt"] if pr else "") or "NEW_EQUIP").upper()
    psf = ((pr["sf"] if pr else "") or "").upper()
    if pt == "CONSUMABLE" or psf == "PARTS":   # 화면도 이 둘은 소모품·상품 칸(제품 표 아님)
        return False
    labels = [r[0] or "" for r in c.execute("SELECT unit_label FROM order_items WHERE order_id=?", (oid,))]
    hogi_n = sum(1 for l in labels if _re_s.match(r"^\d+", l))
    key = _pwf.so_form_label_key(so_form=o.get("so_form"), so_type=o.get("so_type"),
                                 shipment_form=o.get("shipment_form"), hogi_n=hogi_n, proj_ptype=pt)[1]
    return key == "semi" or (psf == "SEMI" and key not in ("parts", "consumable", "etc"))


@app.post("/projects/{pid:int}/import-parts-lines/confirm")
async def projects_import_parts_confirm(req: Request, pid: int):
    """v5H226z: 정식 PACKING LIST 라인 일괄 INSERT.
    필요 컬럼: maker / origin / box_no / spec / arrival_status (v5H226z ALTER)."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"ok": False, "message": "권한 없음"}, 403)
    body = await req.json()
    so_id = int(body.get("so_id") or 0)
    rows = body.get("rows") or []
    if not so_id or not rows:
        return JSONResponse({"ok": False, "message": "so_id 또는 rows 누락"}, 400)
    inserted = 0
    last_err = None
    _ins = []   # (row, order_items.id) — 대표규정 §4 규칙47: 확정 후 '원본↔저장' 대조(방금 넣은 항목만 1:1)
    with db_session() as c:
        so = c.execute("SELECT id, project_id, currency FROM orders WHERE id=?",
                        (so_id,)).fetchone()
        if not so or so["project_id"] != pid:
            return JSONResponse({"ok": False, "message": "수주번호 매칭 안됨"}, 400)
        oicols = {r2[1] for r2 in c.execute("PRAGMA table_info(order_items)").fetchall()}
        for r in rows:
            try:
                qty = float(r.get("qty") or 0)
                up = float(r.get("unit_price") or 0)
                amt = float(r.get("amount") or 0)
                # v5H226z460(대표 지시): 상품 원가관리 — 매입단가·마진%.
                #   '단가'(판매)=기존 유지. 판매단가 비었고 매입가+마진 있으면 판매가 자동산출(매입×(1+마진%)).
                try:
                    _cost = float(r.get("cost_price") or 0)
                except (ValueError, TypeError):
                    _cost = 0.0
                try:
                    _margin = float(r.get("margin_pct") or 0)
                except (ValueError, TypeError):
                    _margin = 0.0
                if up <= 0 and _cost > 0 and _margin != 0:
                    up = _sell_from_cost(_cost, _margin)   # v5H226z1026: 소수점 버림(대표 확정)
                if amt <= 0 and qty > 0 and up > 0:
                    amt = round(qty * up, 2)
                cols = ["order_id", "unit_label", "qty",
                        "unit_price", "amount", "unit_status"]
                vals = [so_id, (r.get("part_name") or "").strip(),
                        qty, up, amt, "진행중"]
                # v5H226z 부품 메타 / v5H226z4: supplier/unit / v5H226z5: 통관
                _img_pref = f"/uploads/consumables/proj_{pid}/"
                _meta_cols = [
                    ("maker", r.get("maker")),
                    ("origin", r.get("origin")),
                    ("box_no", r.get("box_no")),
                    ("spec", r.get("spec")),
                    ("arrival_status", r.get("arrival_status")),
                    ("supplier", r.get("supplier")),
                    ("unit", r.get("unit") or "EA"),
                    ("currency", so["currency"] or "KRW"),
                    # v5H226z460: 상품 원가관리 — 매입단가·마진%(매입가 있을 때만 저장)
                    ("cost_price", _cost if _cost > 0 else None),
                    ("margin_pct", _margin if _cost > 0 else None),
                    # v5H226z5: 통관 메타 (정식 PACKING LIST 추가 컬럼)
                    ("hs_code",                r.get("hs_code")),
                    ("duty_rate",              r.get("duty_rate")),
                    ("vat_rate",               r.get("vat_rate")),
                    ("invoice_unit_price",     r.get("invoice_unit_price")),
                    ("invoice_amount",         r.get("invoice_amount")),
                    ("invoice_unit_price_usd", r.get("invoice_unit_price_usd")),
                    ("invoice_amount_usd",     r.get("invoice_amount_usd")),
                    ("duty_krw",               r.get("duty_krw")),
                    ("duty_usd",               r.get("duty_usd")),
                    ("final_amount_usd",       r.get("final_amount_usd")),
                    ("description",            r.get("description")),
                    ("pallet_size",            r.get("pallet_size")),
                    ("weight_kg",              r.get("weight_kg")),
                ]
                for col_name, col_val in _meta_cols:
                    if col_name in oicols and col_val not in (None, ""):
                        cols.append(col_name)
                        vals.append(str(col_val).strip() if isinstance(col_val, str) else col_val)
                if "image_path" in oicols and r.get("image_file"):
                    cols.append("image_path"); vals.append(_img_pref + str(r.get("image_file")))
                if "image_thumb_path" in oicols and r.get("image_thumb_file"):
                    cols.append("image_thumb_path"); vals.append(_img_pref + str(r.get("image_thumb_file")))
                placeholders = ",".join(["?"] * len(vals))
                _cur = c.execute(
                    f"INSERT INTO order_items({','.join(cols)}) VALUES({placeholders})",
                    vals
                )
                inserted += 1
                _ins.append((r, _cur.lastrowid))   # §4 규칙47: 이 행이 넣은 호기(대조용)
            except Exception as e:
                last_err = str(e)
                print(f"[v5H226z] parts insert err: {e}")
        # SO 합계 갱신
        try:
            agg = c.execute(
                "SELECT COALESCE(SUM(amount),0) AS t, COUNT(*) AS n "
                "FROM order_items WHERE order_id=?", (so_id,)
            ).fetchone()
            if _so_is_parts974(c, so_id):
                # v5H226z974: 상품 SO — unit_qty(완제품 대분)는 보존, 합계만 갱신
                c.execute("UPDATE orders SET total_amount=? WHERE id=?",
                          (float(agg["t"] or 0), so_id))
            else:
                c.execute(
                    "UPDATE orders SET total_amount=?, unit_qty=? WHERE id=?",
                    (float(agg["t"] or 0), int(agg["n"] or 0), so_id)
                )
            proj_total = _apply_project_amount(c, pid) or 0  # z1097b: 통화별 환산(옛 SUM 은 원화+달러를 그냥 더했다)
        except Exception:
            pass
        try:
            c.execute(
                "INSERT INTO project_history(project_id, changed_by, field, old_value, new_value, note) "
                "VALUES(?,?,?,?,?,?)",
                (pid, u.get("id"), "정식 PACKING LIST 업로드", "", f"{inserted}건",
                 f"수주번호 #{so_id} 에 부품 {inserted}건 일괄 추가")
            )
        except Exception:
            pass
        # 대표규정(2026-07-28·§4 규칙47): 확정 후 '엑셀 원본 ↔ 저장값' 대조 — 방금 넣은 항목만 그 행과 1:1(매칭 모호성 0).
        _vout = {"checked": 0, "ok": True, "diff": [], "fields": "품명·수량·단가·금액"}
        try:
            def _vs(v):
                return str(v).strip() if v not in (None, "") else ""

            def _vn(v):
                try:
                    return round(float(str(v).replace(",", "").strip()), 2)
                except Exception:
                    return None

            def _vadd(nm, fld, ex, sv):
                _vout["ok"] = False
                if len(_vout["diff"]) < 20:
                    _vout["diff"].append({"row": 0, "name": str(nm or "")[:24], "field": fld,
                                          "excel": ("" if ex is None else str(ex)), "saved": ("" if sv is None else str(sv))})

            for _r, _iid in _ins:
                _it = c.execute("SELECT unit_label, qty, unit_price, amount FROM order_items WHERE id=?", (_iid,)).fetchone()
                _pn = _vs(_r.get("part_name"))
                if not _it:
                    _vadd(_pn, "행", "있음", "저장 안 됨")
                    continue
                _d = dict(_it); _vout["checked"] += 1
                if _pn and _pn != _vs(_d.get("unit_label")):
                    _vadd(_pn, "품명", _pn, _vs(_d.get("unit_label")))
                _q = _vn(_r.get("qty"))
                if _q is not None and _q != _vn(_d.get("qty")):
                    _vadd(_pn, "수량", _q, _vn(_d.get("qty")))
                _up = _vn(_r.get("unit_price"))
                if _up is not None and _up != _vn(_d.get("unit_price")):
                    _vadd(_pn, "단가", _up, _vn(_d.get("unit_price")))
                _am = _vn(_r.get("amount"))
                if _am is not None and _am > 0 and _am != _vn(_d.get("amount")):
                    _vadd(_pn, "금액", _am, _vn(_d.get("amount")))
        except Exception as _ve:
            _vout["error"] = str(_ve)[:120]
    if inserted == 0:
        return JSONResponse({"ok": False,
                              "message": f"0건 등록 — DB 오류: {last_err or '알 수 없음'}"}, 500)
    return JSONResponse({"ok": True, "inserted": inserted, "verify": _vout})


@app.post("/projects/{pid:int}/quick-status")
async def projects_quick_status(req: Request, pid: int):
    """v5H97: 프로젝트 상태 인라인 변경 (상세 페이지에서 클릭 한 번).
    v5H130 (2026-05-05): WON_STATUSES 진입 시 SO 자동 발행 (1호기) — form-POST
    경로(projects/new, projects/{pid}/edit)와 동일한 v5H87 안전망. 인라인
    경로에서 SO 누락 → '추가 발주' 버튼이 1호기를 덮어쓰던 결함을 차단."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"error": "권한 없음"}, 403)
    form = await req.form()
    new_status = (form.get("status") or "").strip()
    if new_status not in _logi.LOGI_STATUSES:
        return JSONResponse({"ok": False, "message": "유효하지 않은 상태"}, 400)
    auto_so_issued = False
    auto_so_no = None
    try:
      with db_session() as c:
        cur = c.execute(
            "SELECT status, mgmt_code, biz_div, order_amount, order_date, "
            "due_date, customer_po, "
            "COALESCE(unit_qty,1) AS unit_qty, unit_price, "
            "COALESCE(currency,'KRW') AS currency, "
            "COALESCE(project_type,'NEW_EQUIP') AS project_type, "
            "COALESCE(shipment_form,'ASSEMBLY') AS shipment_form "
            "FROM projects WHERE id=?", (pid,)
        ).fetchone()
        if not cur:
            return JSONResponse({"ok": False, "message": "프로젝트 없음"}, 404)
        old_status = cur["status"] or ""
        # v5H143: project_type 먼저 확정 (이전엔 분기 이후에 정의돼 NameError → HTTP 500 결함 1)
        try:
            _cur_ptype = (cur["project_type"] if "project_type" in cur.keys() else "") or "NEW_EQUIP"
        except Exception:
            _cur_ptype = "NEW_EQUIP"
        # v5H214: status 변경 시 stage 도 자동 동기화 (수주확정 코드 발급 분기 전에 선반영)
        _new_stage = stage_from_status(new_status)
        c.execute("UPDATE projects SET status=?, stage=?, updated_at=? WHERE id=?",
                  (new_status, _new_stage, _logi._logi_now() if hasattr(_logi, "_logi_now") else None, pid))
        # v5H101: 변경 이력
        _logi.log_project_change(c, pid, u.get("id"), "상태", old_status, new_status,
                                  note="인라인 빠른 변경")
        # status 가 won 으로 바뀌었는데 mgmt_code 없으면 발급
        # v5H142: NEW_EQUIP(T/M) 만 관리번호 발급
        # v5H150: OTHER 는 'K' prefix 로 발급
        # v5H223: CONSUMABLE 도 수주확정 시 관리코드 발급 (다른 3종과 동일)
        _need_code_qs = (
            new_status in _logi.WON_STATUSES and not cur["mgmt_code"]
            and (
                (cur["biz_div"] in ("T", "M", "L") and _cur_ptype in ("NEW_EQUIP", "CONSUMABLE"))
                or _cur_ptype == "OTHER"
            )
        )
        if _need_code_qs:
            try:
                # v5H225: OTHER → E, CONSUMABLE → C, NEW_EQUIP → biz_div
                if _cur_ptype == "OTHER":
                    _prefix_qs = "E"
                elif _cur_ptype == "CONSUMABLE":
                    _prefix_qs = "C"
                else:
                    _prefix_qs = cur["biz_div"]
                code = _logi.generate_mgmt_code(_prefix_qs)
                c.execute("UPDATE projects SET mgmt_code=?, stage='수주확정' WHERE id=?",
                          (code, pid))
            except Exception:
                pass
        # v5H130: WON_STATUSES + SO 0건 + order_amount > 0 → 자동 SO 발행
        # v5H132: unit_qty N → N개 호기 라인 (단가=unit_price 또는 amt/qty)
        # v5H223: CONSUMABLE 도 자동 SO 발행 (단, 라인이 없는 빈 SO 로 시작)
        # v5H226z: shipment_form='PARTS' 도 빈 SO (라인은 정식 PACKING LIST 양식으로 후속 추가)
        _ship_form_q = (cur["shipment_form"] if "shipment_form" in cur.keys() else "ASSEMBLY") or "ASSEMBLY"
        _is_parts_q = (_ship_form_q.upper() == "PARTS")
        if new_status in _logi.WON_STATUSES and _cur_ptype in ("NEW_EQUIP", "CONSUMABLE"):
            try:
                amt0 = float(cur["order_amount"] or 0)
                # CONSUMABLE/PARTS 는 amt=0 이어도 빈 SO 발행 (라인은 후속 추가)
                if amt0 > 0 or _cur_ptype == "CONSUMABLE" or _is_parts_q:
                    exists = c.execute(
                        "SELECT 1 FROM orders WHERE project_id=? LIMIT 1", (pid,)
                    ).fetchone()
                    if not exists:
                        try:
                            _qty0 = max(1, min(100, int(cur["unit_qty"] or 1)))
                        except Exception:
                            _qty0 = 1
                        try:
                            _up0 = float(cur["unit_price"]) if cur["unit_price"] is not None else 0.0
                        except Exception:
                            _up0 = 0.0
                        if _up0 <= 0 and _qty0 > 0:
                            _up0 = amt0 / _qty0 if _qty0 else 0
                        _ptype_q = cur["project_type"] or "NEW_EQUIP"
                        # v5H223: CONSUMABLE 은 빈 SO (라인은 상세에서 후속 추가)
                        # v5H226z: PARTS shipment_form 도 동일 (정식 PACKING LIST)
                        if _ptype_q == "CONSUMABLE" or _is_parts_q:
                            _units_list = []
                        else:
                            # v5H226z633 (대표 지시): 완제품 수량 N → 호기별 N줄. z629(1줄 qty=N) 되돌림.
                            _units_list = [{
                                "label": _logi.project_unit_label(_ptype_q, i + 1),
                                "amount": _up0,
                                "due_date": cur["due_date"] or "",
                                "ship_to": "",
                                "note": "",
                            } for i in range(_qty0)]
                        # v5H226z: so_type 결정 (PARTS → PARTS_EXPORT)
                        _so_type_q = "PARTS_EXPORT" if _is_parts_q else None
                        res = _pwf.confirm_order_multi(
                            c, int(pid),
                            units=_units_list,
                            order_date=cur["order_date"] or "",
                            created_by=u.get("id") or 0,
                            po_number=cur["customer_po"] or "",
                            so_type=_so_type_q,
                        )
                        if res and res.get("ok"):
                            auto_so_issued = True
                            grp = (res.get("groups") or [{}])[0]
                            auto_so_no = grp.get("so_no") or res.get("so_no")
                            # v5H137: project_type 라벨
                            _lbl = (_logi.project_unit_label(_ptype_q, _qty0)
                                    if _qty0 > 1
                                    else _logi.project_unit_label(_ptype_q, 1))
                            # v5H183: SO 발행 상세 — 통화·납기·단가·합계 풀 로깅
                            _ccy_h = (cur["currency"] if "currency" in cur.keys() else None) or "KRW"
                            _due_h = cur["due_date"] or "(미지정)"
                            _logi.log_project_change(
                                c, pid, u.get("id"), "수주발행(자동)",
                                "", auto_so_no or _lbl,
                                note=(f"진행중 진입 시 {_qty0}대 SO 자동 발행 — "
                                      f"단가 {_up0:,.0f} {_ccy_h} × {_qty0}대 = {amt0:,.0f} {_ccy_h} · "
                                      f"납기 {_due_h} · 라벨 {_lbl}")
                            )
                            # 각 호기 라인 개별 기록
                            for _i in range(_qty0):
                                _i_lbl = _logi.project_unit_label(_ptype_q, _i + 1)
                                _logi.log_project_change(
                                    c, pid, u.get("id"), f"호기 추가({_i_lbl})",
                                    "", f"{_up0:,.0f} {_ccy_h}",
                                    note=f"SO {auto_so_no} · 납기 {_due_h}"
                                )
            except Exception:
                pass
        # v5H226r: 프로젝트 status 변경 → SO/호기 cascade (보호 SO 제외)
        try:
            from . import project_workflow as _pwf_csc
            _csc = _pwf_csc.cascade_project_status_to_so(c, pid, new_status, u.get("id"))
        except Exception as _csc_err:
            print(f"[v5H226r] quick-status cascade err: {_csc_err}")
    except Exception as _qs_err:
        # v5H143: HTTP 500 대신 친절 JSON (모달/토스트 표시 가능)
        return JSONResponse({"ok": False,
                             "message": f"상태 변경 중 오류: {type(_qs_err).__name__} — {str(_qs_err)[:160]}"},
                            500)
    msg = f"상태 → {new_status}"
    if auto_so_issued:
        msg += f" · SO {auto_so_no or ''} 자동 발행"
    return JSONResponse({"ok": True, "message": msg,
                         "auto_so_issued": auto_so_issued,
                         "auto_so_no": auto_so_no})


def _z1173_autofill_guard(u, pairs):
    """z1173 (대표 승인 2026-10-13 · 이새롬 프로 신고 「비고에 적은 내용이 사번으로 바뀐다」):
    크롬은 저장해 둔 로그인 정보의 로그인 ID(=사번)를 autocomplete=off 와 상관없이 글자 입력칸에 저절로 채운다
    (z983 뒤에도 7번 저장됨 · 운영 이력 실측). 서버에서도 막는다 — 글자 칸 값이 **저장하는 사람 자신의**
    로그인 ID·사번과 똑같으면 그 칸 이름을 돌려준다(막아야 함). 다른 사람 사번·긴 글·숫자 칸은 건드리지 않는다.
    pairs = [(칸 이름, 값), …]. 화면(project_detail.html 읽기전용·knkDropAutofill)과 한 묶음."""
    ids = set()
    for k in ("login_id", "employee_no"):
        v = str((u or {}).get(k) or "").strip().upper()
        if v:
            ids.add(v)
    if not ids:
        return None
    for name, val in pairs:
        if str(val or "").strip().upper() in ids:
            return name
    return None


def _z1173_autofill_msg(name):
    """z1173: 거부 안내문 — 왜 막혔고 무엇을 하면 되는지(「먹통」으로 보이지 않게)."""
    return ("%s 칸에 로그인 ID(사번)가 들어왔습니다 — 브라우저가 저절로 채운 값입니다. "
            "그 칸을 비우거나 다시 적은 뒤 저장해 주세요." % name)


@app.post("/sales/orders/items/{iid:int}/edit")
async def sales_order_item_edit(req: Request, iid: int):
    """v5H93: 호기 라인(order_items) 인라인 편집 — 라벨/금액/비고."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"error": "권한 없음"}, 403)
    form = await req.form()
    for _k56 in ("amount", "unit_price", "cost_price", "margin_pct", "qty", "invoice_unit_price_usd", "invoice_amount_usd",
                 "duty_krw", "duty_usd", "final_amount_usd", "cost_krw", "sell_krw", "weight_kg", "duty_rate", "vat_rate", "fx_rate"):
        if _k56 in form and _logi.num_swap_hint(form.get(_k56)) is not None:   # z1191z56: 점·쉼표 바꿔 친 숫자
            return JSONResponse({"ok": False, "message": _logi.num_swap_msg(form.get(_k56))}, 400)
    label = (form.get("label") or "").strip()
    raw_a = (form.get("amount") or "0").strip().replace(",", "")
    note  = (form.get("note") or "").strip()
    # v5H177: 호기별 발주일/납기/납품처 override
    u_order = (form.get("order_date") or "").strip() or None
