                if _parts117 and _old_up117 not in (None, "") and abs(float(_up_for_save or 0) - float(_old_up117)) > 0.0001:
                    _detail_changes.append(f"단가 {float(_old_up117):,.4g} → {float(_up_for_save or 0):,.4g} {_ccy}")
