UNIT_STATUSES = ("진행중", "출하", "취소", "보류")


@app.post("/sales/orders/{oid:int}/board-qty-sync")
async def sales_order_board_qty_sync(req: Request, oid: int):
    """z1191z117 ⑦-1: 작업일정표 수량(board_qty) = 품목 줄 수량 합으로 맞추기(수주 카드 「↻ N으로 맞추기」)."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"ok": False, "message": "권한 없음"}, 403)
    with db_session() as c:
        o = c.execute("SELECT id, order_no, project_id, status FROM orders WHERE id=?", (oid,)).fetchone()
        if not o:
            return JSONResponse({"ok": False, "message": "수주를 찾을 수 없습니다"}, 404)
        if str(o["status"] or "").upper() == "CANCELLED":
            return JSONResponse({"ok": False, "message": "취소된 수주입니다"}, 400)
        _b, _s = _board_sum_z117(c, oid)
        if _s <= 0:
            return JSONResponse({"ok": False, "message": "품목 줄 수량이 없습니다"}, 400)
        c.execute("UPDATE orders SET board_qty=? WHERE id=?", (_s, oid))
        try:
            _logi.log_project_change(c, o["project_id"], u.get("id"), "작업일정표 수량", str(_b or ""), str(_s), note=f"SO {o['order_no']} · 품목 줄 합으로 맞춤")
        except Exception:
            pass
    return JSONResponse({"ok": True, "board_qty": _s})


@app.post("/sales/orders/{oid:int}/price-tbd")
async def sales_order_price_tbd(req: Request, oid: int):
    """z1191z117 ⑤: 수주 「단가 미정」 켜기·끄기(프로젝트 상세 수주 카드)."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"ok": False, "message": "권한 없음"}, 403)
    form = await req.form()
    on = 1 if str(form.get("on") or "").strip() == "1" else 0
    with db_session() as c:
        o = c.execute("SELECT id, order_no, project_id, status FROM orders WHERE id=?", (oid,)).fetchone()
        if not o:
            return JSONResponse({"ok": False, "message": "수주를 찾을 수 없습니다"}, 404)
        if not _price_tbd_col_z117(c):
            return JSONResponse({"ok": False, "message": "저장 칸을 만들지 못했습니다"}, 500)
        c.execute("UPDATE orders SET price_tbd=? WHERE id=?", (on, oid))
        try:
            _logi.log_project_change(c, o["project_id"], u.get("id"), "단가 미정", "", ("켬" if on else "끔"), note=f"SO {o['order_no']}")
        except Exception:
            pass
    return JSONResponse({"ok": True, "on": on})


@app.post("/sales/orders/items/{iid:int}/status")
async def sales_order_item_status(req: Request, iid: int):
    """v5H186: 호기 라인 상태 변경 (개별)."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"error": "권한 없음"}, 403)
    form = await req.form()
    new_status = (form.get("status") or "").strip()
    if new_status not in UNIT_STATUSES:
        return JSONResponse({"ok": False,
                              "message": f"허용: {' / '.join(UNIT_STATUSES)}"}, 400)
    with db_session() as c:
        try:
            _oicols = {r[1] for r in c.execute("PRAGMA table_info(order_items)").fetchall()}
        except Exception:
            _oicols = set()
        if "unit_status" not in _oicols:
            return JSONResponse({"ok": False,
                                  "message": "unit_status 컬럼 미생성 — 서버 재시작 필요"}, 500)
        it = c.execute(
            "SELECT oi.unit_label, oi.unit_status, o.project_id, o.order_no "
            "FROM order_items oi JOIN orders o ON o.id = oi.order_id "
            "WHERE oi.id=?", (iid,)
        ).fetchone()
        if not it:
            return JSONResponse({"ok": False, "message": "라인 없음"}, 404)
        old_st = it["unit_status"] or "진행중"
        if old_st == new_status:
            return JSONResponse({"ok": True, "message": "변동 없음"})
        c.execute("UPDATE order_items SET unit_status=? WHERE id=?",
                  (new_status, iid))
        # 이력 기록
        try:
            _logi.log_project_change(
                c, it["project_id"], u.get("id"),
                f"호기 상태({it['unit_label'] or '—'})",
                old_st, new_status,
                note=f"SO {it['order_no']} · 인라인 변경"
            )
        except Exception:
            pass
        # v5H226r: 호기 → 프로젝트 cascade (모든 호기 동일 terminal 상태일 때)
        try:
            _pwf.cascade_unit_status_to_project(c, it["project_id"], u.get("id"),
                                                order_ids=[r[0] for r in c.execute("SELECT order_id FROM order_items WHERE id=?", (iid,)).fetchall()])   # z1191z122: 이 수주만
        except Exception as _csc_err:
            print(f"[v5H226r] item-status cascade err: {_csc_err}")
    return JSONResponse({"ok": True, "old": old_st, "new": new_status})


@app.post("/projects/{pid:int}/units/bulk-status")
async def projects_units_bulk_status(req: Request, pid: int):
    """v5H186: 프로젝트 전체 호기 라인 상태 일괄 변경.
    옵션: order_id 지정 시 해당 SO 호기들만, 미지정 시 프로젝트 전체."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"error": "권한 없음"}, 403)
    form = await req.form()
    new_status = (form.get("status") or "").strip()
    if new_status not in UNIT_STATUSES:
        return JSONResponse({"ok": False,
                              "message": f"허용: {' / '.join(UNIT_STATUSES)}"}, 400)
    scope_oid = form.get("order_id")
    try:
        scope_oid_i = int(scope_oid) if scope_oid else None
    except (TypeError, ValueError):
        scope_oid_i = None
    with db_session() as c:
        try:
            _oicols = {r[1] for r in c.execute("PRAGMA table_info(order_items)").fetchall()}
        except Exception:
            _oicols = set()
        if "unit_status" not in _oicols:
            return JSONResponse({"ok": False,
                                  "message": "unit_status 컬럼 미생성"}, 500)
        # z1191z11 (데이터 꼬임 점검 · 대표 「중간 위험 진행」): 보낸 수주가 이 관리번호 소속인지 — 아니면 아무것도 안 바꿈
        if scope_oid_i and not c.execute("SELECT 1 FROM orders WHERE id=? AND project_id=?", (scope_oid_i, pid)).fetchone():
            return JSONResponse({"ok": False, "message": "다른 관리번호의 호기·수주가 섞여 있습니다 — 새로 고침(F5) 뒤 다시 해 주세요(이번 요청은 반영 안 됨)"}, 409)
        if scope_oid_i:
            r = c.execute(
                "UPDATE order_items SET unit_status=? "
                "WHERE order_id=? AND COALESCE(unit_status,'진행중') != ?",
                (new_status, scope_oid_i, new_status)
            )
        else:
            r = c.execute(
                "UPDATE order_items SET unit_status=? "
                "WHERE order_id IN (SELECT id FROM orders WHERE project_id=?) "
                "  AND COALESCE(unit_status,'진행중') != ?",
                (new_status, pid, new_status)
            )
        # 이력 기록
        try:
            scope_lbl = (f"SO #{scope_oid_i}" if scope_oid_i else "전체 호기")
            _logi.log_project_change(
                c, pid, u.get("id"),
                f"호기 상태 일괄 변경 ({scope_lbl})",
                "", new_status,
                note=f"{r.rowcount}건 변경"
            )
        except Exception:
            pass
        # v5H226r: 일괄 변경 후도 프로젝트 cascade
        try:
            _pwf.cascade_unit_status_to_project(c, pid, u.get("id"), order_ids=([scope_oid_i] if scope_oid_i else None))   # z1191z122
        except Exception as _csc_err:
            print(f"[v5H226r] bulk-status cascade err: {_csc_err}")
    return JSONResponse({"ok": True, "changed": r.rowcount,
                          "message": f"{r.rowcount}건 변경 완료"})


@app.post("/sales/orders/items/{iid:int}/delete")
async def sales_order_item_delete(req: Request, iid: int):
    """v5H93: 호기 라인 삭제 — 1건만 제거. unit_qty/total_amount 자동 재계산."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"error": "권한 없음"}, 403)
    with db_session() as c:
        # v5H100: 삭제 전 값 캡처
        it = c.execute(
            "SELECT oi.order_id, oi.unit_label AS lbl, oi.amount AS amt, oi.line_note AS lnote, "
            "       o.status, o.project_id, o.total_amount AS old_total "
            "FROM order_items oi JOIN orders o ON o.id = oi.order_id "
            "WHERE oi.id=?", (iid,)
        ).fetchone()
        if not it:
            return JSONResponse({"ok": False, "message": "라인을 찾을 수 없습니다"}, 404)
        st = (it["status"] or "").upper()
        if st == "CANCELLED" or (st in _Z117_CLOSED and not _closed_ok_z117(req)):   # z1191z117 ①
            return JSONResponse({
                "ok": False, "need_closed_ok": st in _Z117_CLOSED,
                "message": (_closed_msg_z117(st) if st in _Z117_CLOSED else "취소된 수주의 줄은 지울 수 없습니다")
            }, 409 if st in _Z117_CLOSED else 400)
        # z1191z4: 「호기·일련번호 관리」(project_units)에 등록된 호기의 출처 줄은 지우지 않는다
        #   — 지우면 일련번호 기록이 가리키는 수주 줄이 사라진다. 상태 '취소'로 처리하게 안내.
        import sqlite3 as _sq_z4
        try:
            _pu_link = c.execute(
                "SELECT COALESCE(current_unit_no, working_name, '') FROM project_units "
                "WHERE seed_order_item_id=? LIMIT 1", (iid,)).fetchone()
        except _sq_z4.OperationalError:   # 표가 없는 옛 DB
            _pu_link = None
        if _pu_link is not None:
            _pu_no = (_pu_link[0] or "").strip()
            return JSONResponse({
                "ok": False,
                "message": "이 줄은 「호기·일련번호 관리」에 등록된 호기" + (f"({_pu_no})" if _pu_no else "")
                           + "와 연결돼 있어 지울 수 없습니다. 상태를 '취소'로 바꿔 주세요."
            }, 400)
        oid = it["order_id"]
        del_lbl = it["lbl"] or "—"
        del_amt = float(it["amt"] or 0)
        old_total = float(it["old_total"] or 0)
        _isp974 = _so_is_parts974(c, oid)  # v5H226z1018b: 상품 여부 (unit_qty 보존 + 이력 표현 공용)
        _issemi = (not _isp974) and _so_is_semi_z4c(c, oid)   # z1191z4c: 제품 — 수량 = 품목 수량 합
        _bq_before117 = _board_sum_z117(c, oid)   # z1191z117 ⑦-1
        c.execute("DELETE FROM order_items WHERE id=?", (iid,))
        _board_follow_z117(c, oid, _bq_before117)
        # SO 재계산
        rows = c.execute(
            "SELECT unit_label, amount FROM order_items WHERE order_id=? ORDER BY id ASC",
            (oid,)
        ).fetchall()
        new_total = sum(float(r["amount"] or 0) for r in rows)
        new_qty = max(1, len(rows))
        if _issemi:
            new_qty = max(1, int(float(c.execute("SELECT COALESCE(SUM(qty),0) FROM order_items WHERE order_id=?",
                                                 (oid,)).fetchone()[0] or 0)))
        new_label = " · ".join((r["unit_label"] or f"호기 {i+1}") for i, r in enumerate(rows))
        if _isp974:
            # v5H226z974: 상품 SO — unit_qty(완제품 대분) 보존, 합계·라벨만 재계산
            c.execute("UPDATE orders SET total_amount=?, unit_label=? WHERE id=?",
                      (new_total, new_label, oid))
        else:
            c.execute("UPDATE orders SET total_amount=?, unit_qty=?, unit_label=? WHERE id=?",
                      (new_total, new_qty, new_label, oid))
        # 프로젝트 합계 동기화
        try:
            pid = it["project_id"]
            if pid:
                _apply_project_amount(c, pid)  # z1097b: 통화별 환산(옛 SUM 은 원화+달러를 그냥 더했다)
        except Exception:
            pass
        # v5H100: 삭제 이력  (v5H226z1018b: 상품은 '부품 행' 표현)
        try:
            if _issemi:
                note_msg = (f"품목 줄 삭제 [{del_lbl}] · 금액 {del_amt:,.0f} 제거 · "
                            f"SO 합계 {old_total:,.0f} → {new_total:,.0f}")
            elif _isp974:
                note_msg = (f"부품 행 삭제 [{del_lbl}] · 금액 {del_amt:,.0f} 제거 · "
                            f"SO 합계 {old_total:,.0f} → {new_total:,.0f}")
            else:
                note_msg = (f"호기 라인 삭제 [{del_lbl}] · 단가 {del_amt:,.0f} 제거 · "
                            f"SO 합계 {old_total:,.0f} → {new_total:,.0f}")
            c.execute(
                "INSERT INTO order_status_history(order_id, from_status, to_status, "
                "changed_by, note) VALUES(?,?,?,?,?)",
                (oid, st, st, u.get("id"), note_msg)
            )
        except Exception:
            pass
    return JSONResponse({"ok": True, "message": "라인 삭제 완료"})


@app.post("/sales/orders/{oid:int}/add-unit")
async def sales_orders_add_unit(req: Request, oid: int):
    """v5H90: 기존 SO 에 호기 라인 추가 (단가가 다른 추가 발주 대응).
    동일 SO 안에서 호기별 단가가 다를 수 있게 order_items 새 행 INSERT
    + orders.unit_qty++/total_amount += amount 갱신."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"error": "권한 없음"}, 403)
    form = await req.form()
    for _k56 in ("amount", "unit_price", "cost_price", "margin_pct", "qty", "invoice_unit_price_usd", "invoice_amount_usd",
                 "duty_krw", "duty_usd", "final_amount_usd", "cost_krw", "sell_krw", "weight_kg", "duty_rate", "vat_rate", "fx_rate"):
        if _k56 in form and _logi.num_swap_hint(form.get(_k56)) is not None:   # z1191z56: 점·쉼표 바꿔 친 숫자
            return JSONResponse({"ok": False, "message": _logi.num_swap_msg(form.get(_k56))}, 400)
    label = (form.get("label") or "").strip()
    raw_a = (form.get("amount") or "0").strip().replace(",", "")
    note  = (form.get("note") or "").strip()
    spec_v = (form.get("spec") or "").strip()[:200]   # z1191z4c: 제품 품목 규격
    _af1173 = _z1173_autofill_guard(u, [("비고", note), ("호기", label), ("규격", spec_v)])   # z1173: 브라우저가 저절로 채운 로그인 ID(사번) 막기
    if _af1173:
        return JSONResponse({"ok": False, "message": _z1173_autofill_msg(_af1173)}, 400)
    cur_v = (form.get("currency") or "").strip().upper() or "KRW"
    # v5H226z357 (통화 중대버그): 6종 통화 허용 (EUR/JPY/CNY 누락 수정)
    if cur_v not in ("KRW", "USD", "VND", "JPY", "CNY", "EUR"):
        cur_v = "KRW"
    # v5H110: 수량 — N대 한 번에 추가 (모두 같은 단가, 라벨은 자동 증가)
    raw_qty = (form.get("qty") or "1").strip()
    try:
        bulk_qty = int(float(raw_qty))
    except ValueError:
        bulk_qty = 1
    if bulk_qty < 1:
        bulk_qty = 1
    # v5H226z1018: 절대 상한만 여기서 — 장비(호기 100대) 상한은 SO 종류 확인 후 아래에서(상품=낱개 수량이라 9999까지)
    if bulk_qty > 9999:
        return JSONResponse({"ok": False, "message": "한 번에 9,999개 초과 불가"}, 400)
    try:
        amt = float(raw_a) if raw_a else 0
    except ValueError:
        return JSONResponse({"ok": False, "message": "금액 형식 오류"}, 400)
    amt = _logi.money_r2(amt)   # z1191z56: 호기 추가 금액 = 둘째 자리 반올림
    # v5H226z460(대표 지시): 상품 원가관리 — 매입단가·마진%. 마진은 등록 후 정리 가능 → 매입가만으로도 추가 허용.
    _raw_cost = (form.get("cost_price") or "").strip().replace(",", "")
    _raw_margin = (form.get("margin_pct") or "").strip().replace(",", "")
    try:
        _cost_v = float(_raw_cost) if _raw_cost else None
    except ValueError:
        _cost_v = None
    try:
        _margin_v = float(_raw_margin) if _raw_margin else None
    except ValueError:
        _margin_v = None
    if amt <= 0 and not (_cost_v and _cost_v > 0):
        return JSONResponse({"ok": False, "message": "판매단가 또는 매입단가를 입력해주세요"}, 400)
    with db_session() as c:
        cur = c.execute(
            "SELECT status, project_id, unit_qty, unit_label, total_amount "
            "FROM orders WHERE id=?", (oid,)
        ).fetchone()
        if not cur:
            return JSONResponse({"ok": False, "message": "수주를 찾을 수 없습니다"}, 404)
        st = (cur["status"] or "").upper()
        if st == "CANCELLED" or (st in _Z117_CLOSED and not _closed_ok_z117(req)):   # z1191z117 ①
            return JSONResponse({
                "ok": False, "need_closed_ok": st in _Z117_CLOSED,
                "message": (_closed_msg_z117(st) if st in _Z117_CLOSED else "취소된 수주에는 줄을 더할 수 없습니다")
            }, 409 if st in _Z117_CLOSED else 400)
        # v5H109: 자동 라벨은 프로젝트 전체 호기 라인 개수 기준 (관리코드 우선)
        try:
            items_in_so = c.execute(
                "SELECT COUNT(*) FROM order_items WHERE order_id=?", (oid,)
            ).fetchone()[0] or 0
            _bq_before117 = _board_sum_z117(c, oid)   # z1191z117 ⑦-1
            project_id_local = cur["project_id"]
            items_in_project = c.execute(
                "SELECT COUNT(*) FROM order_items oi "
                "JOIN orders o ON o.id = oi.order_id WHERE o.project_id=?",
                (project_id_local,)
            ).fetchone()[0] or 0
        except Exception:
            items_in_so = 0
            items_in_project = 0
        # v5H226z974 (대표 지시): 상품(PARTS) SO 는 unit_qty='완제품 몇 대분' 보존 — 부품 추가로 증가시키지 않음
        _isp974 = _so_is_parts974(c, oid)
        # z1191z4c: 제품 수주 = 품목 1줄(수량 N · 금액 = 단가×N) — 호기로 나누지 않고 'N호기' 이름도 안 붙인다
        _issemi = (not _isp974) and _so_is_semi_z4c(c, oid)
        # v5H226z1018: 장비(호기) 상한 100대는 그대로 — 상품은 낱개 수량이라 위 9999 상한만 적용
        if not _isp974 and not _issemi and bulk_qty > 100:
            return JSONResponse({"ok": False, "message": "한 번에 100대 초과 불가"}, 400)
        # v5H110: 시작 라벨에서 숫자 추출 → bulk 시 N개 자동 증가
        import re as _re
        base_no = None
        if label:
            m = _re.match(r"^(\d+)호기$", label)
            if m:
                base_no = int(m.group(1))
        if base_no is None:
            base_no = items_in_project + 1
        # v5H226z1018 (대표 지시): 상품(PARTS) SO 의 '부품 추가' = 품명 1줄 + 낱개 수량 N (호기 분할 ⛔).
        #   기존엔 장비 호기 로직(수량 N=호기 N줄)이 상품에도 적용돼 'CYLINDER 12개'가 12줄(CYLINDER·2호기~12호기)로
        #   쪼개짐(2026-07-16 M-260707-1 실사례·대표 신고). 상품 줄=부품 1종(qty=낱개 수량) —
        #   등록폼(z430)·상품 양식 업로드(import-parts-lines)와 동일 규칙. 장비·소모품=기존 그대로(대표 승인: 상품만).
        if _isp974 or _issemi:
            labels_bulk = [label or "(품명 미입력)"]
        else:
            # bulk_qty 만큼 라벨 생성: ['5호기', '6호기', ...]
            labels_bulk = [f"{base_no + i}호기" for i in range(bulk_qty)]
            # bulk 0번째가 사용자 입력 커스텀 라벨이면 그대로 첫 라벨 사용
            if label and not _re.match(r"^\d+호기$", label):
                labels_bulk[0] = label  # 커스텀 라벨 유지, 나머지는 N호기 형식
        if _isp974:
            new_qty = int(cur["unit_qty"] or 1)
        elif _issemi:   # z1191z4c: 제품 SO 수량 = 품목 수량 합(z1050 규칙)
            new_qty = int(float(c.execute("SELECT COALESCE(SUM(qty),0) FROM order_items WHERE order_id=?",
                                          (oid,)).fetchone()[0] or 0)) + bulk_qty
        else:
            new_qty = items_in_so + bulk_qty
        new_total = float(cur["total_amount"] or 0) + amt * bulk_qty
        old_lbl = (cur["unit_label"] or "").strip()
        new_lbl = (old_lbl + " · " + " · ".join(labels_bulk)) if old_lbl else " · ".join(labels_bulk)

        # order_items INSERT — bulk_qty 개 모두
        # v5H226z460: 매입단가·마진% 컬럼이 있고 매입가 입력 시 함께 저장
        try:
            _oicols_au = {r2[1] for r2 in c.execute("PRAGMA table_info(order_items)").fetchall()}
        except Exception:
            _oicols_au = set()
        _has_cm = ("cost_price" in _oicols_au) and ("margin_pct" in _oicols_au)
        # v5H226z1018: 장비=호기 N줄(각 qty=1·금액=단가) / 상품=품명 1줄(qty=낱개 N·금액=단가×N)
        _row_qty = bulk_qty if (_isp974 or _issemi) else 1
        _row_amt = round(amt * bulk_qty, 2) if (_isp974 or _issemi) else amt
        for _lbl in labels_bulk:
            try:
                if _has_cm and (_cost_v is not None):
                    c.execute(
                        "INSERT INTO order_items(order_id, qty, unit_price, amount, "
                        "unit_label, line_note, cost_price, margin_pct) VALUES(?,?,?,?,?,?,?,?)",
                        (oid, _row_qty, amt, _row_amt, _lbl, note, _cost_v, (_margin_v if _cost_v else None))
                    )
                else:
                    c.execute(
                        "INSERT INTO order_items(order_id, qty, unit_price, amount, "
                        "unit_label, line_note) VALUES(?,?,?,?,?,?)",
                        (oid, _row_qty, amt, _row_amt, _lbl, note)
                    )
            except Exception:
                pass
        # z1191z4c: 제품 품목 규격(칸이 있을 때) — 방금 넣은 1줄
        if _issemi and spec_v and "spec" in _oicols_au:
            c.execute("UPDATE order_items SET spec=? WHERE id=(SELECT MAX(id) FROM order_items WHERE order_id=?)",
                      (spec_v, oid))
        # orders 누적 (+ currency 필요 시 갱신)
        try:
            c.execute(
                "UPDATE orders SET unit_qty=?, total_amount=?, unit_label=?, currency=? WHERE id=?",
                (new_qty, new_total, new_lbl, cur_v, oid)
            )
        except Exception:
            c.execute(
                "UPDATE orders SET unit_qty=?, total_amount=?, unit_label=? WHERE id=?",
                (new_qty, new_total, new_lbl, oid)
            )
        try:
            _board_follow_z117(c, oid, _bq_before117)   # z1191z117 ⑦-1
        except NameError:
            pass
        # 프로젝트 합계 동기화
        try:
            pid = cur["project_id"]
            if pid:
                _apply_project_amount(c, pid)  # z1097b: 통화별 환산(옛 SUM 은 원화+달러를 그냥 더했다)
        except Exception:
            pass
        # 이력 (v5H100: SO 합계 변동 명시 / v5H110: bulk 표시)
        try:
            old_total = float(cur["total_amount"] or 0)
            old_qty = int(cur["unit_qty"] or 1)
            range_str = (labels_bulk[0] if len(labels_bulk) == 1
                         else f"{labels_bulk[0]}~{labels_bulk[-1]}")
            if _isp974:   # v5H226z1018: 상품 = 부품 1줄(낱개 N개) — '호기/대' 표현 안 씀
                note_msg = (f"부품 추가 [{labels_bulk[0]}] · {bulk_qty}개 × 단가 {amt:,.0f} {cur_v} · "
                            f"SO 합계 {old_total:,.0f} → {new_total:,.0f}")
            else:
                note_msg = (f"호기 추가 [{range_str}] · {bulk_qty}대 × 단가 {amt:,.0f} {cur_v} · "
                            f"수량 {old_qty} → {new_qty}대 · "
                            f"SO 합계 {old_total:,.0f} → {new_total:,.0f}")
            if note:
                note_msg += f" ({note})"
            c.execute(
                "INSERT INTO order_status_history(order_id, from_status, to_status, "
                "changed_by, note) VALUES(?,?,?,?,?)",
                (oid, st, st, u.get("id"), note_msg)
            )
        except Exception:
            pass
    if _isp974:   # v5H226z1018: 상품 — 품명 1줄 + 낱개 수량
        msg = f"부품 '{labels_bulk[0]}' {bulk_qty}개 추가 완료"
    else:
        msg = (f"호기 '{labels_bulk[0]}' 추가 완료" if bulk_qty == 1
               else f"호기 {labels_bulk[0]}~{labels_bulk[-1]} ({bulk_qty}대) 추가 완료")
    return JSONResponse({"ok": True, "message": msg})


@app.post("/sales/orders/{oid:int}/quick-edit")
async def sales_orders_quick_edit(req: Request, oid: int):
    """v5H84: SO 인라인 빠른 수정 — 호기수(unit_qty) / 금액(total_amount) 즉시 변경.
    프로젝트 상세에서 인라인 편집용. 출하/송장/취소 SO 는 거부."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"error": "권한 없음"}, 403)
    form = await req.form()
    raw_q = (form.get("unit_qty") or "").strip()
    raw_a = (form.get("total_amount") or "").strip().replace(",", "")
    raw_c = (form.get("currency") or "").strip().upper()
    raw_due = (form.get("due_date") or "").strip()
    raw_ord = (form.get("order_date") or "").strip()
    raw_ship = (form.get("ship_to") or "").strip()
    # z1173: 브라우저가 저절로 채운 로그인 ID(사번) 막기(수주 머리 글자 칸)
    _af1173 = _z1173_autofill_guard(u, [("납품처", raw_ship), ("비고", form.get("line_note")),
                                        ("모델명", form.get("model_name")), ("장비명", form.get("equip_name")),
                                        ("2차 발주처", form.get("end_customer"))])   # z1190
    if _af1173:
        return JSONResponse({"ok": False, "message": _z1173_autofill_msg(_af1173)}, 400)
    sets, vals = [], []
    # v5H226z357 (통화 중대버그): 6종 통화 허용 (EUR/JPY/CNY 선택 시 통화만 저장 안 되던 버그 수정)
    if raw_c in ("KRW", "USD", "VND", "JPY", "CNY", "EUR"):
        sets.append("currency=?"); vals.append(raw_c)
    if raw_q:
        try:
            q = int(float(raw_q))
            if q < 1:
                return JSONResponse({"ok": False, "message": "호기 수는 1 이상이어야 합니다"}, 400)
            sets.append("unit_qty=?"); vals.append(q)
        except ValueError:
            return JSONResponse({"ok": False, "message": "호기 수 형식 오류"}, 400)
    if raw_a:
        try:
            a = float(raw_a)
            if a < 0:
                return JSONResponse({"ok": False, "message": "금액은 0 이상이어야 합니다"}, 400)
            sets.append("total_amount=?"); vals.append(a)
        except ValueError:
            return JSONResponse({"ok": False, "message": "금액 형식 오류"}, 400)
    # v5H106: SO 헤더 필드 (납기/발주일/납품처) 도 인라인 편집
    if "due_date" in form:
        sets.append("due_date=?"); vals.append(raw_due or None)
    if "order_date" in form:
        sets.append("order_date=?"); vals.append(raw_ord or None)
    if "ship_to" in form:
        sets.append("ship_to=?"); vals.append(raw_ship or None)
    # v5H226z1079 (이새롬 프로 신고): SO별 발주처(order_customer) 인라인 편집 — 등록 고객사 '정확 일치'
    #   (정식명 또는 시스템명)로만 연결. 오타·미등록은 저장 거부(연결 없는 이름 저장 금지 — 데이터 연결성 안전).
    #   빈 값 = 발주처 해제(프로젝트 고객 상속). 작업일정표 고객사1 은 SO 발주처 우선(z705)이라
    #   여기서 바로잡으면 일정표도 따라온다(015T2607 드림텍 본사↔아산 사례).
    if "order_customer" in form:
        _ocv = (form.get("order_customer") or "").strip()
        if not _ocv:
            sets.append("customer_id=?"); vals.append(None)
        else:
            # v5H226z1079b: 같은 법인 종사업장은 정식명이 동일(예: '(주) 드림텍' = 본사/아산 공통)라
            #   정식명 매칭 LIMIT 1 은 아무 지점이나 잡는 비결정 연결 — 자동연결은 '명확한 단일후보'만.
            #   시스템명(alias) 정확 일치 우선, 정식명은 유일할 때만. 다지점 동명이면 거부하고 시스템명 유도.
            with db_session() as _coc:
                _oc_hits = _coc.execute("SELECT id FROM customers WHERE alias=?", (_ocv,)).fetchall()
                if not _oc_hits:
                    _oc_hits = _coc.execute("SELECT id FROM customers WHERE name=?", (_ocv,)).fetchall()
                _o157 = None
                if not _oc_hits:   # z1191z157: 옛 이름(이름 변경 이력) — 딱 한 고객사일 때만
                    _o157 = _logi.customer_old_name_match(_coc, _ocv)
                    if _o157["id"]:
                        _oc_hits = [(_o157["id"],)]
            if not _oc_hits and _o157 and _o157["reason"] in ("ambiguous", "unsafe"):
                return JSONResponse({"ok": False, "message": "👉 " + _o157["note"]}, 400)
            if not _oc_hits:
                return JSONResponse({"ok": False, "message":
                    f"발주처 '{_ocv}' 를 등록 고객사에서 찾을 수 없습니다 — 고객사 화면의 시스템명(또는 정식명) 그대로 입력해 주세요. 비우면 프로젝트 고객사를 따릅니다."}, 400)
            if len(_oc_hits) > 1:
                return JSONResponse({"ok": False, "message":
                    f"'{_ocv}' 이름의 등록 고객사가 {len(_oc_hits)}곳입니다(같은 정식명의 지점들) — 어느 지점인지 시스템명(예: 드림텍(아산))으로 입력해 주세요."}, 400)
            sets.append("customer_id=?"); vals.append(_oc_hits[0][0])
    # z1190 (대표 2026-10-16 「수주마다 1차·2차 발주처」): 이 수주의 2차 발주처(최종 고객) — 자유 글(프로젝트 고객사2 와 같은 꼴).
