#  전사 공유 연락처(주소록) — v5H227 (2026-05-31 대표 지시)
#  열람·검색: 전 직원 / 수정·삭제: 등록 본인 + 관리자
#  자동등록 3경로: 명함 사진(OCR) · 메일 서명 · 직접 입력
# ═══════════════════════════════════════════════════════════════════════════
from . import contacts as _contacts

_CONTACT_IMG_DIR = os.path.join(BASE, "uploads", "contacts")
_CARD_EXTS = (".jpg", ".jpeg", ".png", ".bmp", ".tif", ".tiff", ".pdf")


def _contact_form_data(form) -> dict:
    """폼/요청에서 연락처 입력 필드 추출."""
    d = {}
    for k in _contacts.FIELD_KEYS:
        d[k] = (form.get(k) or "").strip()
    cid = (form.get("customer_id") or "").strip()
    d["customer_id"] = int(cid) if cid.isdigit() else None
    d["card_image"] = (form.get("card_image") or "").strip()
    d["source"] = (form.get("source") or "manual").strip()
    d["visibility"] = (form.get("visibility") or "private").strip()   # v5H226z580 공유 범위
    return d


@app.get("/contacts")
async def contacts_list(req: Request):
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    q = (req.query_params.get("q") or "").strip()
    # z1191z77 (대표 11-19): 책갈피 — 전체 · 🔒 개인(나만) · 👥 부서(부서원 누구나) · 🌐 전사(회사 전체 누구나) · 🏢 우리 회사 직원
    tab = (req.query_params.get("tab") or "all").strip()
    if tab not in ("all", "private", "dept", "company", "staff"):
        tab = "all"
    with db_session() as c:
        items = _contacts.list_contacts(c, q, user=u)   # v5H226z580 가시성 필터
        staff = _contacts.list_staff(c, q)
    for d in items:
        d["tab"] = _contacts.tab_of(d)
        d["name_disp"] = _contacts.display_name(d.get("name"))
        for _k in ("mobile", "phone", "fax"):
            d[_k + "_disp"] = _contacts.phone_display(d.get(_k))
            d[_k + "_tel"] = _contacts.tel_href(d.get(_k))
        d["mine"] = _contacts.can_edit(d, u)
    for d in staff:
        d["phone_disp"] = _contacts.phone_display(d.get("phone"))
        d["phone_tel"] = _contacts.tel_href(d.get("phone"))
    items.sort(key=lambda d: (d["name_disp"] or "").lower())
    counts = {"all": len(items), "staff": len(staff)}
    # z1191z79 (대표 11-19 「우리회사직원은 본사,법인 인원을 따로 볼수있게」): 직원 = 전체 · KNK 본사 · KNK VINA 법인
    corp = (req.query_params.get("corp") or "").strip().lower()
    if corp not in ("kr", "vn"):
        corp = ""
    counts["staff_kr"] = sum(1 for d in staff if _contacts.staff_corp_key(d) == "kr")
    counts["staff_vn"] = sum(1 for d in staff if _contacts.staff_corp_key(d) == "vn")
    if corp:
        staff = [d for d in staff if _contacts.staff_corp_key(d) == corp]
    for _t in ("private", "dept", "company"):
        counts[_t] = sum(1 for d in items if d["tab"] == _t)
    shown = items if tab == "all" else [d for d in items if d["tab"] == tab]
    # z1191z81: 총괄 = 모든 부서 주소록 → 부서 책갈피에서 부서별로 골라 보기
    chief = _contacts.chief_scope(u)   # z1191z82: "" · "all"(본사 총괄) · "vn"(법인 총괄)
    dept_teams, dteam = [], (req.query_params.get("team") or "").strip()
    if chief:
        _dt = {}
        for d in items:
            if d["tab"] == "dept":
                _k = (d.get("share_team_id") or 0, d.get("share_team_name") or "부서 없음")
                _dt[_k] = _dt.get(_k, 0) + 1
        dept_teams = [{"id": k[0], "name": k[1], "n": v} for k, v in sorted(_dt.items(), key=lambda kv: (-kv[1], kv[0][1]))]
        if tab == "dept" and dteam.isdigit():
            shown = [d for d in shown if str(d.get("share_team_id") or "") == dteam]
    for d in items:
        d["movable"] = _contacts.can_move_company(d, u)
    my_team = ""
    if u.get("team_id"):
        with db_session() as c:
            _r = c.execute("SELECT name FROM teams WHERE id=?", (u.get("team_id"),)).fetchone()
            my_team = (_r[0] if _r else "") or ""
    return ctx(req, "contacts_list.html", user=u, contacts=shown, q=q,
               total=len(items), tab=tab, counts=counts, staff=staff, my_team=my_team, corp=corp,
               chief=chief, dept_teams=dept_teams, dteam=dteam)


