@app.post("/contacts/bulk-delete")
async def contacts_bulk_delete(req: Request):
    """여러 연락처 일괄 삭제 — v5H226z584. body: {ids:[...]}. 권한=등록 본인·관리자만.
    가시성 없는(내가 못 보는) 항목은 건너뜀."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    try:
        body = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "message": "요청 형식 오류."}, 400)
    ids = body.get("ids") or []
    ids = [int(x) for x in ids if str(x).isdigit()]
    if not ids:
        return JSONResponse({"ok": False, "message": "삭제할 항목이 없습니다."}, 400)
    deleted, skipped = 0, 0
    with db_session() as c:
        for cid in ids:
            contact = _contacts.get_contact(c, cid)
            if not contact or not _contacts.can_see(contact, u) or not _contacts.can_edit(contact, u):
                skipped += 1
                continue
            _contacts.delete_contact(c, cid)
            deleted += 1
    msg = f"{deleted}명을 삭제했습니다."
    if skipped:
        msg += f" (권한 없음 {skipped}명 건너뜀)"
    return JSONResponse({"ok": True, "deleted": deleted, "skipped": skipped, "message": msg})


@app.post("/api/contacts/from-eum")
async def api_contacts_from_eum(req: Request):
    """z1191z78 (대표 11-19 「초대시 등록하고 QR이 발행된 고객사 협력사 담당자 정보는 연락처로 … 우리부서공개 연락처에 저장」):
    이음(세션 10) 서버 → WORKS 서버. 머리글 X-SSO-Service-Key(회의록 입구와 같은 공유키 · 서버끼리만).
    본문 {"inviter_employee_no": 사번, "contacts": [{name, position, company, department, mobile, email, kind, note, eum_invite_id}] (최대 10명)}
    저장 = 초대한 직원 부서의 👥 부서 연락처 · 등록자 = 그 직원 · 같은 사람이 있으면 빈 칸만 채움(contacts.upsert_from_eum)."""
    if not _msg_service_key_ok(req):
        return JSONResponse({"ok": False, "error": "unauthorized"}, 401)
    try:
        body = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "bad_json", "message": "본문(JSON)을 읽지 못했습니다."}, 400)
    if not isinstance(body, dict):
        return JSONResponse({"ok": False, "error": "bad_json", "message": "본문 모양이 다릅니다."}, 400)
    items = body.get("contacts")
    if not isinstance(items, list) or not items:
        return JSONResponse({"ok": False, "error": "no_contacts", "message": "contacts 가 비었습니다."}, 400)
    if len(items) > _contacts.EUM_MAX:
        return JSONResponse({"ok": False, "error": "too_many", "message": "한 번에 %d명까지입니다." % _contacts.EUM_MAX}, 400)
    with db_session() as c:
        inv = _msg_user_by_empno(c, body.get("inviter_employee_no"))
        if not inv:
            return JSONResponse({"ok": False, "error": "inviter_not_found",
                                 "message": "사번 「%s」에 맞는 재직 직원이 없습니다." % str(body.get("inviter_employee_no") or "")[:40]}, 400)
        results = [_contacts.upsert_from_eum(c, inv, it if isinstance(it, dict) else {}) for it in items]
    return JSONResponse({"ok": True, "results": results})


@app.post("/contacts/bulk-share")
async def contacts_bulk_share(req: Request):
    """z1191z77 (대표 11-19): 고른 연락처의 공유 범위를 한 번에 — 🔒 개인 · 👥 우리 부서 · 🌐 전사. body {ids, visibility}.
    바꿀 수 있는 것 = 내가 등록한 것(관리자·대표는 전부 · 기존 규칙 can_edit 그대로). 부서 = 바꾸는 사람의 부서."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    try:
        body = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "message": "요청 형식 오류."}, 400)
    vis = str(body.get("visibility") or "").strip()
    if vis not in _contacts.VISIBILITIES:
        return JSONResponse({"ok": False, "message": "잘못된 공유 범위입니다."}, 400)
    ids = [int(x) for x in (body.get("ids") or []) if str(x).isdigit()]
    if not ids:
        return JSONResponse({"ok": False, "message": "고른 연락처가 없습니다."}, 400)
    tid = u.get("team_id") if vis == "dept" else None
    if vis == "dept" and not tid:
        return JSONResponse({"ok": False, "message": "소속 부서가 없어 부서 연락처로 바꿀 수 없습니다(관리자에게 부서 배정 요청)."}, 400)
    done, skipped = 0, 0
    with db_session() as c:
        for cid in ids:
            ct = _contacts.get_contact(c, cid)
            if not ct or not _contacts.can_see(ct, u) or not (
                    _contacts.can_edit(ct, u) or (vis == "company" and _contacts.can_move_company(ct, u))):   # z1191z81
                skipped += 1
                continue
            _contacts.set_share(c, cid, vis, tid, u["id"])
            done += 1
    lab = {"private": "🔒 개인", "dept": "👥 부서공유", "company": "🌐 전사공유"}[vis]
    msg = f"{done}명을 {lab} 연락처로 바꿨습니다."
    if skipped:
        msg += f" (바꿀 수 없는 {skipped}명은 그대로)"
    return JSONResponse({"ok": True, "done": done, "skipped": skipped, "message": msg})


@app.post("/contacts/bulk-copy-dept")
async def contacts_bulk_copy_dept(req: Request):
    """z1191z81 (대표 「각 부서에 주소록 등록은 개인주소록에 주소록을 복사」): 고른 내 🔒 개인 연락처 → 내 부서 주소록에 복사(개인 것은 남김)."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    try:
        body = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "message": "요청 형식 오류."}, 400)
    ids = [int(x) for x in (body.get("ids") or []) if str(x).isdigit()]
    if not ids:
        return JSONResponse({"ok": False, "message": "고른 연락처가 없습니다."}, 400)
    if not u.get("team_id"):
        return JSONResponse({"ok": False, "message": "소속 부서가 없어 부서공유 주소록에 복사할 수 없습니다(관리자에게 부서 배정 요청)."}, 400)
    res = []
    with db_session() as c:
        for cid in ids:
            res.append(_contacts.copy_to_dept(c, cid, u))
    n_c = sum(1 for r in res if r["status"] == "copied")
    n_e = sum(1 for r in res if r["status"] == "exists")
    n_s = sum(1 for r in res if r["status"] == "skipped")
    msg = f"{n_c}명을 부서공유 주소록에 복사했습니다(내 개인 연락처는 그대로)."
    if n_e:
        msg += f" 이미 부서공유 주소록에 있는 {n_e}명은 건너뜀."
    if n_s:
        msg += f" 내 개인 연락처가 아닌 {n_s}명은 건너뜀."
    return JSONResponse({"ok": True, "copied": n_c, "exists": n_e, "skipped": n_s, "results": res, "message": msg})


