def _mail_inbound_token() -> str:
    """받는 구멍 비밀토큰 — WORKS 관리자 설정(app_settings) 우선, 없으면 환경변수."""
    t = (get_setting("mail_inbound_token", "") or "").strip()
    if t:
        return t
    return (os.environ.get("KNK_MAIL_INBOUND_TOKEN") or "").strip()


@app.post("/api/mail/inbound")
async def mail_inbound(req: Request):
    """Cloudflare Email Routing(Worker)가 받은 메일을 밀어넣는 받는 구멍.
    보안: 비밀토큰 일치 필수(관리자 설정 mail_inbound_token 또는 환경변수). 미설정 시 비활성.
    payload: {to, from, subject, raw(MIME 원문), ...} — raw 있으면 파이썬으로 파싱."""
    import hmac as _hmac
    import json
    from starlette.concurrency import run_in_threadpool
    _ip = ((req.headers.get("x-forwarded-for") or "").split(",")[0].strip()
           or (req.client.host if req.client else ""))[:64]
    token_cfg = _mail_inbound_token()
    if not token_cfg:
        return JSONResponse({"ok": False, "message": "수신 기능 비활성 — 관리자 '메일 받기 설정'에서 토큰을 먼저 생성하세요."}, 403)
    # 11-27 머리글로만 받는다(주소 뒤 값은 접속 기록에 남을 수 있음) · 같은 시간 비교
    token = (req.headers.get("X-KNK-Mail-Token") or "").strip()
    if not token or not _hmac.compare_digest(token.encode("utf-8"), token_cfg.encode("utf-8")):
        _mail_inbound_log(_ip, "", "", 0, "인증 실패")
        return JSONResponse({"ok": False, "message": "인증 실패"}, 401)
    try:
        _clen = int(req.headers.get("content-length") or 0)
    except Exception:
        _clen = 0
    if _clen > MAIL_INBOUND_MAX_BYTES:
        _mail_inbound_log(_ip, "", "", _clen, "너무 큼")
        return JSONResponse({"ok": False, "message": "메일이 너무 큽니다."}, 413)
    try:
        _body = await req.body()
        if len(_body) > MAIL_INBOUND_MAX_BYTES:
            _mail_inbound_log(_ip, "", "", len(_body), "너무 큼")
            return JSONResponse({"ok": False, "message": "메일이 너무 큽니다."}, 413)
        d = json.loads(_body or b"{}")
        if not isinstance(d, dict):
            raise ValueError("not object")
    except Exception:
        return JSONResponse({"ok": False, "message": "JSON 본문이 필요합니다."}, 400)
    _to0 = _mailbox._norm_addr(d.get("to") or "")
    if _mail_inbound_too_many(_to0):
        _mail_inbound_log(_ip, _to0, d.get("from") or "", len(_body), "너무 많이 들어옴")
        return JSONResponse({"ok": False, "message": "잠시 뒤 다시 보내 주세요(짧은 시간에 너무 많이 들어옴)."}, 429)

    f = {"to_email": (d.get("to") or "").strip(),
         "from_email": d.get("from") or "", "from_name": d.get("from_name") or "",
         "subject": d.get("subject") or "", "text": d.get("text") or "",
         "html": d.get("html") or "", "cc": d.get("cc") or "",
         "size": d.get("size") or 0, "message_id": d.get("message_id") or ""}
    raw = d.get("raw") or ""
    _atts = None
    _auth, _reply_to = None, ""
    _raw_hdr = ""
    _sent_at = ""
    if raw:
        parsed = await run_in_threadpool(_mailbox.parse_raw_email, raw)   # 11-27 일꾼 밖에서
        if parsed:
            for k in ("from_email", "from_name", "subject", "text", "html", "cc", "message_id"):
                if parsed.get(k):
                    f[k] = parsed[k]
            if not f["to_email"] and parsed.get("to_email"):
                f["to_email"] = parsed["to_email"]
            f["size"] = len(raw)
            _atts = parsed.get("attachments")
            _auth, _reply_to = parsed.get("auth"), parsed.get("reply_to", "")
            _raw_hdr = parsed.get("raw_headers", "")
            _sent_at = parsed.get("sent_at", "")

    if not f["to_email"]:
        _mail_inbound_log(_ip, "", f["from_email"], len(_body), "받는 주소 없음")
        return JSONResponse({"ok": False, "message": "수신 주소(to)가 없습니다."}, 400)
    # 11-27 받는 주소 = 우리가 받는 도메인(회사·시험 도메인·등록된 별칭)만 — 아무 주소나 기본 받는 사람에게 넣지 않게
    if not _mail_inbound_domain_ok(f["to_email"]):
        _mail_inbound_log(_ip, f["to_email"], f["from_email"], len(_body), "받지 않는 주소")
        return JSONResponse({"ok": False, "message": "받지 않는 주소입니다."}, 422)
    # 11-27 이 입구(바깥 받기)로 들어온 것 표시 — 우리 회사 주소로 왔는데 서버 확인(통과)이 없으면 경고하려고
    _auth = dict(_auth or {})
    _auth["via"] = "inbound"
    _ai_ids = []

    def _store():
        with db_session() as c:
            return _mailbox.store_inbound(
                c, to_email=f["to_email"], from_email=f["from_email"],
                from_name=f["from_name"], subject=f["subject"], text=f["text"],
                html=f["html"], cc=f["cc"], size=f["size"], run_ai=None,   # 11-18: 받는 사람의 메일 AI 허용(OpenAI)일 때만
                attachments=_atts, message_id=f.get("message_id", ""),
                auth=_auth, reply_to=_reply_to, raw_headers=_raw_hdr,   # 11-22 원문 머리글 보관
                sent_at=_sent_at,                                        # 11-23 원래 날짜
                ai_later=_ai_ids,                                        # 11-27 AI 는 저장 뒤
            )
    mid, owner = await run_in_threadpool(_store)   # 11-27 일꾼을 붙잡지 않게
    if not mid:
        # 데이터 연결성 원칙: 조용히 버리지 않고 사유 표면화
        _mail_inbound_log(_ip, f["to_email"], f["from_email"], len(_body), "받는 사람 못 찾음")
        return JSONResponse({"ok": False, "message": "수신자 매핑 실패(받는 사람을 찾지 못함)"}, 422)
    _mail_inbound_log(_ip, f["to_email"], f["from_email"], len(_body), "받음")
    if _ai_ids:
        await run_in_threadpool(_mailbox.ai_fill_later, db_session, _ai_ids)
    return JSONResponse({"ok": True})   # 11-27 받는 사람·메일 번호는 돌려주지 않음


MAIL_INBOUND_MAX_BYTES = int(os.environ.get("KNK_MAIL_INBOUND_MAX_MB") or 40) * 1024 * 1024   # 한 통(JSON 전체) 최대
MAIL_INBOUND_PER_MIN = 120        # 1분에 전체 최대 통수(이 일꾼 기준)
MAIL_INBOUND_PER_MIN_ADDR = 30    # 1분에 한 받는 주소 최대 통수
_MAIL_INBOUND_HITS = []           # (시각, 받는 주소)
_MAIL_INBOUND_DOMAINS = ("knknara.co.kr", "knk-mailtest.com")


def _mail_inbound_too_many(to_addr) -> bool:
    """수신 입구 횟수 한도(11-27) — 1분 동안 전체·같은 주소 통수. 넘으면 True(이번 것은 세지 않음)."""
    import time as _t
    now = _t.time()
    _MAIL_INBOUND_HITS[:] = [h for h in _MAIL_INBOUND_HITS if now - h[0] < 60]
    if len(_MAIL_INBOUND_HITS) >= MAIL_INBOUND_PER_MIN:
        return True
    if to_addr and sum(1 for h in _MAIL_INBOUND_HITS if h[1] == to_addr) >= MAIL_INBOUND_PER_MIN_ADDR:
        return True
    _MAIL_INBOUND_HITS.append((now, to_addr or ""))
    return False


def _mail_inbound_domain_ok(to_addr) -> bool:
    """받는 주소가 우리가 받는 곳인가 — 회사 도메인·시험 도메인 · 또는 별칭 표(mail_aliases)에 있는 주소."""
    a = _mailbox._norm_addr(to_addr)
    dom = a.split("@")[-1] if "@" in a else ""
    if dom in _MAIL_INBOUND_DOMAINS:
        return True
    try:
        with db_session() as c:
            return bool(c.execute("SELECT 1 FROM mail_aliases WHERE address=?", (a,)).fetchone())
    except Exception:
        return False


def _mail_inbound_log(ip, to_addr, from_addr, size, result):
    """수신 입구 기록(11-27) — 언제·어디서·누구에게·크기·결과만(메일 내용은 남기지 않음). 90일 지난 줄은 지움. 실패해도 받기는 계속."""
    try:
        with db_session() as c:
            c.execute("CREATE TABLE IF NOT EXISTS mail_inbound_log (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                      "at TEXT DEFAULT (datetime('now','localtime')), ip TEXT, to_addr TEXT, from_addr TEXT, size INTEGER, result TEXT)")
            c.execute("INSERT INTO mail_inbound_log(ip, to_addr, from_addr, size, result) VALUES(?,?,?,?,?)",
                      ((ip or "")[:64], (to_addr or "")[:200], (from_addr or "")[:200], int(size or 0), (result or "")[:40]))
            if c.execute("SELECT MAX(id) FROM mail_inbound_log").fetchone()[0] % 200 == 0:
                c.execute("DELETE FROM mail_inbound_log WHERE at < datetime('now','localtime','-90 days')")
    except Exception as _e:
        print("[MAIL-INBOUND-LOG] 기록 실패(받기는 계속): %s" % str(_e)[:120], flush=True)


_MAIL_POC_ADDR = "test@knk-mailtest.com"


def _mail_inbound_owner(req):
    """메일 받기 설정(토큰·바깥 메일 받는 사람)은 대표 한 사람만(11-27) — 관리자라도 안 됨."""
    u = get_user(req)
    if not u:
        return None
    try:
        with db_session() as c:
            return u if _mailbox.default_owner(c) == u["id"] else None
    except Exception as _e:
        print("[MAIL-INBOUND] 대표 확인 실패(막음): %s" % str(_e)[:120], flush=True)
        return None


@app.get("/admin/mail-inbound", response_class=HTMLResponse)
async def admin_mail_inbound_page(req: Request):
    """메일 받기 설정 (11-27 대표 한 사람만) — 토큰 + 받는 사람 + Cloudflare 연결 안내."""
    u = _mail_inbound_owner(req)
    if not u:
        _au = get_user(req)
        return RedirectResponse(("/mail/tools?owner_only=1" if _au else "/login"), 303)
    with db_session() as c:
        rid = _mailbox.resolve_recipient(c, _MAIL_POC_ADDR)
        rrow = c.execute("SELECT name, role FROM users WHERE id=?", (rid,)).fetchone() if rid else None
        recip_name = (rrow["name"] if rrow else "(미지정)")
    recip_is_me = bool(rid and rid == u["id"])
    return ctx(req, "admin_mail_inbound.html", user=u, active="admin",
               token=_mail_inbound_token(), inbound_url=_MAIL_INBOUND_URL,
               poc_addr=_MAIL_POC_ADDR, recip_name=recip_name, recip_is_me=recip_is_me,
               bound=req.query_params.get("bound"),
               saved=(req.query_params.get("saved") == "1"))


@app.post("/admin/mail-inbound")
async def admin_mail_inbound_gen(req: Request):
    """새 비밀토큰 생성·저장(app_settings). 기존 토큰은 즉시 무효. 11-27 대표 한 사람만 · 기록 남김."""
    u = _mail_inbound_owner(req)
    if not u:
        return JSONResponse({"ok": False, "message": "대표만 바꿀 수 있습니다."}, 403)
    _mail_inbound_log("", "", "", 0, "토큰 다시 만듦(%s)" % u["id"])
    import secrets
    new_token = secrets.token_urlsafe(32)
    with db_session() as c:
        c.execute(
            "INSERT INTO app_settings(key, value) VALUES(?, ?) "
            "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
            ("mail_inbound_token", new_token))
    return RedirectResponse("/admin/mail-inbound?saved=1", 303)


@app.post("/admin/mail-inbound/bind-me")
async def admin_mail_inbound_bind(req: Request):
    """받는 사람을 '지금 로그인한 본인' 으로 지정 — 운영 DB 동명 계정 혼동 방지.
    ① 기본 수신자 설정 ② test@ 별칭 ③ 이미 들어온 test@ 메일을 내 메일함으로 이동. 11-27 대표 한 사람만 · 기록 남김."""
    u = _mail_inbound_owner(req)
    if not u:
        return JSONResponse({"ok": False, "message": "대표만 바꿀 수 있습니다."}, 403)
    _mail_inbound_log("", "", "", 0, "받는 사람 바꿈(%s)" % u["id"])
    with db_session() as c:
        c.execute("INSERT INTO app_settings(key, value) VALUES('mail_default_user_id', ?) "
                  "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (str(u["id"]),))
        c.execute("INSERT INTO mail_aliases(address, user_id) VALUES(?, ?) "
                  "ON CONFLICT(address) DO UPDATE SET user_id=excluded.user_id",
                  (_MAIL_POC_ADDR, u["id"]))
        moved = c.execute(
            "UPDATE mail_messages SET user_id=? WHERE to_email=? AND is_deleted=0",
            (u["id"], _MAIL_POC_ADDR)).rowcount
    return RedirectResponse(f"/admin/mail-inbound?bound={moved}", 303)


@app.get("/mail/inbox")
def mail_inbox_page(req: Request, cat: str = "", q: str = "", star: int = 0, unread: int = 0,
                          df: str = "", dt: str = "", att: int = 0, thread: int = 1, cust: str = "",
                          reply: int = 0, fd: str = "", qf: str = "all", where: str = "", per: str = "",
                          who: str = "", dom: str = "", noad: int = 0, off: int = 0, frag: int = 0, prev: str = "",
                          arc: int = 0, flag: int = 0, snz: int = 0, boss: int = 0, kd: str = "", ad: int = 0):
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    fd = (fd or "").strip()
    # 11-23 대표 「🏷 종류를 내가 지정」 — 내 종류 목록(mail_ui_prefs) · kd = 내 종류 하나로 모아 보기
    from . import mail_ui_prefs as _mup
    with db_session() as c:
        _my_kinds = _mup.get_kinds(c, u["id"])
        # 11-23 대표 「거르기 줄에서 선택한 건 내가 풀 때까지」 — cs=1(거르기 줄 단추로 바꾼 주소) = 그 상태를 내 계정에 기억 ·
        #   그 밖(왼쪽 폴더·위 메뉴·옮긴 뒤 다시 열기·더 보기) = 기억한 것으로 채움(주소에 직접 적힌 값이 먼저)
        _qk = set(req.query_params.keys())
        if req.query_params.get("cs") == "1":
            _mup.save_chips(c, u["id"], {"unread": unread, "att": att, "noad": noad, "thread": thread, "cat": cat, "kd": kd})
        else:
            _chips = _mup.get_chips(c, u["id"])
            if _chips:
                unread = unread if "unread" in _qk else _chips["unread"]
                att = att if "att" in _qk else _chips["att"]
                noad = noad if "noad" in _qk else _chips["noad"]
                thread = thread if "thread" in _qk else _chips["thread"]
                if "cat" not in _qk and "kd" not in _qk:
                    cat, kd = _chips["cat"], _chips["kd"]
    kd = (kd or "").strip()[:12]
    _kd_item = next((x for x in _my_kinds if x.get("id") == kd and x.get("w")), None) if kd else None
    if not _kd_item:
        kd = ""
    # (11-18 대표 「쉽게 찾기」 2단계) 기간 단추 → 날짜 · 보낸 메일 함께(폴더·거래처·회신 보기는 받은 메일만) · 이어서 더 보기
    q = (q or "").strip()[:200]
    who = (who or "").strip().lower()[:120]
    dom = (dom or "").strip().lower().lstrip("@")[:80]
    per = per if per in ("today", "week", "month", "3m", "year") else ""
    if per and not (df or dt):
        df, dt = _mail_find.period_range(per)
    qf = qf if qf in ("all", "from", "subj", "att") else "all"
    where = "in" if where == "in" else ""
    off = max(0, min(int(off or 0), 200000))
    _PAGE = 200
    _terms = _mailbox.search_terms(q)
    with db_session() as c:
        # 받은 메일 폴더(아웃룩식 · 11-17) — 대표 계정은 처음 열 때 아웃룩 구조 그대로 만든다. 실패해도 받은편지함은 연다.
        mf = None
        try:
            _mail_folders.seed_if_owner(c, u["id"])
            if _mail_folders.has_tree(c, u["id"]):
                mf = _mail_folders.classify(c, u["id"])
        except Exception as _e:
            print(f"[MAIL-FOLDERS ERR] {type(_e).__name__}: {_e}")
            mf = None
        if mf is None or fd not in mf["keys_of"]:
            fd = ""
        # ④ 회신 필요(추정) — 규칙으로만(AI·외부 전송 없음). 실패해도 받은편지함은 연다.
        try:
            reply_map = _mail_reply.scan(c, u["id"])
        except Exception:
            reply_map = {}
        # 11-21 다 묶음 — 사내 보낸 사람 「이름 직책 부서」 · 👔 윗분(임원·우리 팀장·우리 팀 윗 직책) · 👔 윗분 지시 = 회신 필요 중 윗분 메일
        _mpst, _mpme, _boss_ids = {}, {}, set()
        try:
            _mpst = _mpeople.staff(c)
            _mpme = _mpeople.me_of(c, u["id"], _mpst)
            _boss_ids = _mail_boss_ids(c, u["id"], reply_map, _mpst, _mpme)
        except Exception as _e:
            print("[MAIL-PEOPLE] 받은편지함 윗분 표시 실패(목록은 그대로): %s" % str(_e)[:160], flush=True)
        _bulk = _mail_find.bulk_map(c, u["id"])   # 11-23 {주소: 그때부터} — 내가 날짜부터 표시한 것까지
        # 11-23 대표 「광고·알림 칸에만 보이게」 — 받은편지함 그냥 목록(안 읽음·첨부·종류 거르기 포함)에서는 광고·알림을 뺌
        #   폴더·찾기·이 사람/회사·중요·회신 필요·기한·다시 알림·보관함·거래처·📢 칸 에서는 그대로 보임(찾을 때 안 사라지게)
        _hide_ad = not (ad or fd or _terms or who or dom or star or reply or flag or snz or arc or (cust or "").strip())
        _qs = _mail_find.q_senders(mf, _terms) if (_terms and mf and not fd) else None
        # 11-19 2단계 — 시간이 된 「⏰ 다시 알림」 메일은 안 읽음으로 돌아옴 · 🚩 기한 날짜 = 보는 사람 소속 날짜
        try:
            _mailbox.snooze_wake(c, u["id"])
        except Exception:
            pass
        _moff = _mail_off(c, u)
        _mtoday = _mail_local_today(_moff)
        _kw = dict(category=cat, q=q, starred=bool(star), unread=bool(unread),
                   date_from=df, date_to=dt, has_att=bool(att), cust=cust,
                   only_ids=((sorted(_boss_ids) if boss else list(reply_map.keys())) if reply else None),
                   senders=(_mail_folders.senders_in(mf, fd) if fd else None),
                   qf=qf, with_sent=bool((_terms or who or dom) and where != "in"), who=who, dom=dom,
                   q_senders=_qs, noad=(_bulk if (noad or _hide_ad) else None),
                   arc=bool(arc), fd_keys=(sorted((mf or {}).get("keys_of", {}).get(fd, set())) if fd else None),
                   flagged=bool(flag), snoozed=bool(snz and not flag),
                   kind_words=(_kd_item["w"] if _kd_item else None), ad_only=(_bulk if ad else None))
        mails = _mailbox.list_inbox(c, u["id"], limit=_PAGE, offset=off, **_kw)
        total_n = _mailbox.list_inbox(c, u["id"], count_only=True, **_kw) or 0
        # 11-23 왼쪽 「📢 광고·알림」 숫자 — 받은편지함(보관 뺌)에서 광고·알림 통수
        try:
            _ad_n = int(_mailbox.list_inbox(c, u["id"], count_only=True, ad_only=_bulk) or 0)
        except Exception as _e:
            print("[MAIL ad_n ERR] %s: %s" % (type(_e).__name__, _e))
            _ad_n = 0
        _kinds = _mail_find.folder_kinds(mf) if mf else {}
        _mine = _mail_find.my_addresses(c, u["id"])
        for _m in mails:
            _m["reply"] = reply_map.get(_m["id"])
            _m["tlabel"] = _mail_find.time_label(_m.get("received_at"))
            _m["day"] = _mail_find.day_label(_m.get("received_at"))
            _inb = (_m.get("direction") or "in") == "in"
            _m["ad"] = bool(_inb and _mail_find.is_ad(_m, _bulk))
            _m["ccme"] = _mail_find.is_cc(_m, _mine)
            _sp = _mpeople.sender(_mpst, _mpme, _m.get("from_email")) if _inb else {}
            _m["staff"], _m["boss"] = _sp.get("disp", ""), _sp.get("boss", "")
            if int(_m.get("risk_level") or 0) >= 2:
                _m["boss"] = ""   # 11-27 의심 메일엔 👔 윗분 표시 안 함(회사 주소는 흉내 낼 수 있음)
            _m["kind"] = _mailbox.mail_kind(_m)
            _m["flag_late"] = bool(_m.get("flag_due") and _m["flag_due"] < _mtoday)
            _m["flag_today"] = bool(_m.get("flag_due") and _m["flag_due"] == _mtoday)
            _m["snz_label"] = _mail_local_label(_m.get("snooze_until") or "", _moff)
            _m["snzb_label"] = _mail_local_label(_m.get("snooze_back") or "", _moff)
            # 목록 꼬리표 = 폴더 이름(11-18 대표 「쉽게 구분」) — 「일반」은 안 붙임(모두 같아 정보가 없음) · 색 = 묶음 갈래
            _m["fdname"], _m["fdkind"], _m["fdkey"] = "", "", ""
            if mf and _inb:
                try:
                    _fk0 = _m.get("fd_key") or ""                      # 11-22 메일 한 통마다 정한 폴더(이 메일만·내 규칙·받은 때 부서)
                    if _fk0 and _fk0 in (mf.get("labels") or {}):
                        _f = {"key": _fk0, "name": mf["labels"][_fk0]}
                    else:
                        _f = _mail_folders.folder_of(mf, _m.get("from_email") or "")
                    _m["fdkey"] = _f.get("key") or ""
                    if _f.get("key") != "gen":
                        _m["fdname"] = _f.get("name") or ""
                        _m["fdkind"] = _kinds.get(_f.get("key"), "")
                except Exception:
                    pass
        unread_n = _mail_unread(c, u["id"])
        cat_counts = _mailbox.category_counts(c, u["id"])
        drafts_n = _mailbox.count_drafts(c, u["id"])
        # C1 거래처 폴더 — 보낸사람→연락처→거래처 매핑 집계(전체·거래처별·미분류). 매핑은 이메일 정확일치만.
        folders = _mailbox.customer_folder_counts(c, u["id"])
    # B1 대화 묶기: 같은 제목(RE/FW 접두 제거) 받은 메일을 한 대화로(기본 ON). thread=0 이면 평면 목록.
    thread_on = bool(thread)
    threads = _mailbox.group_threads(mails) if thread_on else None
    # 이어서 더 보기 — 같은 조건 그대로 다음 200통(조각만)
    from urllib.parse import urlencode as _ue
    _keep_q = [(k, v) for k, v in req.query_params.multi_items() if k not in ("off", "frag", "prev")]
    more_href = ("/mail/inbox?" + _ue(_keep_q + [("off", str(off + _PAGE)), ("frag", "1")])) if (off + len(mails) < total_n and len(mails) >= _PAGE) else ""
    _base_q = [(k, v) for k, v in req.query_params.multi_items()
               if k not in ("off", "frag", "prev", "unread", "att", "thread", "noad", "app", "cs")]
    _base_nc = [(k, v) for k, v in _base_q if k not in ("cat", "kd")]   # 11-19 종류 단추는 cat(기본 셋)·kd(11-23 내 종류)만 바꿔 끼움
    with db_session() as c:
        _arc_n = _mailbox.count_archived(c, u["id"])
        _spam_n = _mailbox.count_blocked(c, u["id"])
        try:
            _flag_c = _mailbox.count_flag(c, u["id"], _mtoday)
            _snz_n = _mailbox.count_snoozed(c, u["id"])
        except Exception:
            _flag_c, _snz_n = {"n": 0, "due": 0}, 0
        # 11-21 마 묶음 — 오늘 챙길 메일 더: 📭 2일 넘게 안 읽음(최근 30일 · 광고·알림 빼고 · 누르면 같은 조건 목록) · 🚩 내일까지 · 🚫 스팸함 새(오늘)
        _day_more = {"old": 0, "old_href": "", "tmr": 0, "spam_new": 0}
        try:
            _td = date.fromisoformat(_mtoday)
            _o_from, _o_to = (_td - timedelta(days=30)).isoformat(), (_td - timedelta(days=2)).isoformat()
            _day_more["old"] = int(_mailbox.list_inbox(c, u["id"], count_only=True, unread=True, date_from=_o_from,
                                                       date_to=_o_to, noad=_bulk) or 0)
            _day_more["old_href"] = "/mail/inbox?unread=1&noad=1&df=%s&dt=%s" % (_o_from, _o_to)
            _day_more["tmr"] = int(c.execute("SELECT COUNT(*) FROM mail_messages WHERE user_id=? AND is_deleted=0 AND flag_due=?",
                                             (u["id"], (_td + timedelta(days=1)).isoformat())).fetchone()[0] or 0)
            _mid0 = _mail_local_to_server(datetime.combine(_td, datetime.min.time()), _moff)
            _day_more["spam_new"] = int(c.execute("SELECT COUNT(*) FROM mail_messages WHERE user_id=? AND direction='in' AND is_deleted=0 "
                                                  "AND COALESCE(is_blocked,0)=1 AND received_at>=?", (u["id"], _mid0)).fetchone()[0] or 0)
        except Exception as _e:
            print("[MAIL-DAY] 오늘 챙길 메일 더 세기 실패(목록은 그대로): %s" % str(_e)[:160], flush=True)
        _ar_info = _mail_autoreply_info(c, u)
        _wait_c = _mwork.count_waiting(c, u["id"], _mtoday, _mailbox._normalize_subject)   # 11-19 1단계 ②
        # 11-20 2단계 ⑥ 메일 하루 숫자 — 오늘(보는 사람 소속 날짜) 보낼 예약 · 못 보낸 예약
        try:
            _end_loc = datetime.combine(_mail_now_local(_moff).date() + timedelta(days=1), datetime.min.time())
            _sc_t = _mglance.count_sched_today(c, u["id"], _mail_local_to_server(_end_loc, _moff))
        except Exception:
            _sc_t = {"today": 0, "fail": 0}
        # 11-20 대표 「받은편지함 목록에도 👉 표시」 — 맡긴 메일 줄에 「👉 담당 · 상태」(저장된 마지막 상태 · 새 상태는 화면이 따로 물음)
        _dlg_m = _mdlg.marks_for(c, u["id"], [_m["id"] for _m in mails])
    for _m in mails:
        _m["dlg"] = _dlg_m.get(_m["id"])
    for _t in (threads or []):          # 대화로 묶인 줄 — 맨 위 줄에 없으면 대화 안 다른 메일의 표시를 올려 보여 줌
        _L = _t.get("latest")
        if _L is not None and not _L.get("dlg"):
            _x = next((_i.get("dlg") for _i in (_t.get("items") or []) if _i.get("dlg")), None)
            if _x:
                _L["dlg"] = dict(_x, thread=True)
    _day = {"reply": len(reply_map), "boss": len(_boss_ids), "flag": int(_flag_c.get("due") or 0), "wait": int((_wait_c or {}).get("all") or 0),
            "wait_due": int((_wait_c or {}).get("due") or 0), "sched": int(_sc_t.get("today") or 0), "sched_fail": int(_sc_t.get("fail") or 0)}
    _day.update(_day_more)
    _day["any"] = any(_day[k] for k in ("reply", "flag", "wait", "sched", "sched_fail", "old", "tmr", "spam_new"))
    _ctx_more = dict(more_href=more_href, total_n=total_n, cur_arc=bool(arc), arc_n=_arc_n, spam_n=_spam_n, wait_c=_wait_c, day=_day,
                     flag_n=_flag_c["n"], flag_due_n=_flag_c["due"], snz_n=_snz_n, ar_info=_ar_info,
                     hides_arc=bool(not arc and not fd and not _terms and not who and not dom and not star and not reply and not cust),
                     fd_choices=((_mail_folders.assignable_list(mf) if mf else [])), remain_n=max(0, total_n - off - len(mails)),
                     prev_day=(prev or "")[:40], page_off=off,
                     base_q=_ue(_base_q), base_nc=_ue(_base_nc), cur_flag=bool(flag), cur_snz=bool(snz and not flag),
                     my_kinds=[x for x in _my_kinds if x.get("on")], cur_kd=kd, cur_kd_name=(_kd_item["n"] if _kd_item else ""),
                     cur_ad=bool(ad), ad_n=_ad_n, ad_hidden=_hide_ad,
                     search_on=bool(_terms or who or dom or per or df or dt),
                     terms=_terms, cur_qf=qf, cur_where=where, cur_per=per, cur_who=who, cur_dom=dom,
                     cur_noad=bool(noad), periods=_mail_find.PERIOD_NAMES,
                     fd_hits=(_mail_find.matched_folders(mf, _terms) if (_terms and not fd) else []),
                     per_name=(dict(_mail_find.PERIOD_NAMES).get(per, "") if per else ""))
    if frag:
        return ctx(req, "_v5_partials/mail_inbox_rows.html", user=u, mails=mails, box="in",
                   thread_on=thread_on, threads=threads, **_ctx_more)
    return ctx(req, "mail_inbox.html", user=u, mails=mails, unread=unread_n,
               cat_counts=cat_counts, cur_cat=cat, categories=_MAIL_CATEGORIES, cur_df=df, cur_dt=dt, cur_att=bool(att),
               ai_on=mail_ai_enabled_for(u), q=q, cur_star=bool(star), cur_unread=bool(unread),
               drafts_n=drafts_n, thread_on=thread_on, threads=threads,
               folders=folders, cur_cust=(cust or "").strip(),
               reply_n=len(reply_map), cur_reply=bool(reply), cur_boss=bool(reply and boss),
               mf=mf, cur_fd=fd, cur_fd_name=((mf or {}).get("labels", {}).get(fd, "") if fd else ""),
               **_ctx_more)


@app.get("/mail/tools", response_class=HTMLResponse)
async def mail_tools_page(req: Request):
    """⚙ 설정·정리 — 한 달에 한 번 쓰는 메일 도구를 한 화면에(11-18 대표 「쉽게 보이고 쉽게 사용」).
    매일 화면(받은편지함)에서는 뺀 단추들이 모두 여기에 있다. 화면만 — 새 기능·저장 칸 없음."""
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    has_tree = False
    gen_n = 0
    blocked_n = 0
    with db_session() as c:
        try:
            _mail_folders.seed_if_owner(c, u["id"])
            has_tree = bool(_mail_folders.has_tree(c, u["id"]))
            if has_tree:
                gen_n = int(((_mail_folders.classify(c, u["id"]) or {}).get("gen") or {}).get("n") or 0)
        except Exception:
            has_tree = False
        try:
            blocked_n = int(c.execute("SELECT COUNT(*) FROM mail_messages WHERE user_id=? AND direction='in' "
                                      "AND is_deleted=0 AND COALESCE(is_blocked,0)=1", (u["id"],)).fetchone()[0] or 0)
        except Exception:
            blocked_n = 0
        # 11-18 「딱 들어가면 바로 알 수 있게」 — 정리할 것·설정 상태를 숫자로(읽기만)
        st = {"trash_n": 0, "ad_n": 0, "has_sig": False, "has_acct": False, "folder_n": 0, "rule_n": 0}
        try:
            st["trash_n"] = int(_mailbox.count_trash(c, u["id"]) or 0)
        except Exception:
            pass
        try:
            st["ad_n"] = len(_mail_find.bulk_senders(c, u["id"]) or ())
        except Exception:
            pass
        try:
            st["has_sig"] = bool((_mailbox.get_signature(c, u["id"]) or "").strip())
        except Exception:
            pass
        try:
            from . import mail_fetch as _mfx
            st["has_acct"] = bool(_mfx.get_account(c, u["id"]))
        except Exception:
            pass
        try:
            st["folder_n"] = len(_mail_folders.folders(c, u["id"]) or [])
            st["rule_n"] = len(_mail_folders.rules(c, u["id"]) or [])
        except Exception:
            pass
        st["ar_info"] = _mail_autoreply_info(c, u)   # 11-19 2단계-나 🏖
        try:   # 11-20 그룹 메일 명단(하이웍스 파일) 마지막으로 올린 때
            st["grp_imp"] = _mwork.import_last(c)
            st["grp_n"] = c.execute("SELECT COUNT(*) FROM mail_groups WHERE kind='company'").fetchone()[0]
        except Exception:
            st["grp_imp"], st["grp_n"] = {}, 0
        try:
            st["sig_n"] = len(_mailbox.get_signatures(c, u["id"]) or [])
        except Exception:
            st["sig_n"] = 1
    with db_session() as c:
        _inb_owner = (_mailbox.default_owner(c) == u["id"])   # 11-27 받기 설정 줄 = 대표에게만
    return ctx(req, "mail_tools.html", user=u, has_tree=has_tree, gen_n=gen_n, blocked_n=blocked_n,
               is_inbound_owner=_inb_owner, owner_only=(req.query_params.get("owner_only") == "1"), **st)


# ── 메일 = 설치형 앱(PWA) — KNK Eum 처럼 바탕화면/홈 아이콘으로 설치 (대표 지시 2026-06-14) ──
_MAIL_PWA_ICON_CACHE = {}
# =====================================================
# v5H226z422 (대표 지시): KNK Eum WORKS — 설치형 앱(PWA). 시스템 기본 이름 'KNK Eum' 아래
#   WORKS/MAIL/메신저 통일. WORKS도 메일(KNK Eum MAIL)·메신저(KNK Eum)처럼 바탕화면/홈 아이콘·
#   독립 창으로 설치 가능. scope '/' (앱 전체). 아이콘=KNK 빨강 라운드 + 흰 '음'(KNK Eum 정체성).
# =====================================================
#   v5H226z426 (대표 지시): 아이콘이 빨강만 나오는 문제 — NAS 에 한글폰트가 없어 PNG '음' 렌더 실패.
#   → '음'(ㅇ 원 + ㅡ 가로획 + ㅁ 네모)을 **폰트 없이 도형으로** 그림(어느 서버에서나 동일).
_WORKS_PWA_ICON_SVG = (
    "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 512 512'>"
    "<rect width='512' height='512' rx='104' fill='#A5282C'/>"
    "<ellipse cx='256' cy='150' rx='92' ry='68' fill='none' stroke='#fff' stroke-width='26'/>"
    "<rect x='148' y='236' width='216' height='26' rx='13' fill='#fff'/>"
    "<rect x='170' y='292' width='172' height='122' rx='12' fill='none' stroke='#fff' stroke-width='26'/>"
    "</svg>"
)
_WORKS_PWA_ICON_CACHE = {}


def _works_pwa_icon_png(size: int) -> bytes:
    """KNK 빨강 라운드(풀블리드 maskable) + 흰 '음'. 폰트 의존 없이 도형(ㅇ 원·ㅡ 가로획·ㅁ 네모)으로
    그림 → NAS 등 한글폰트 없는 환경에서도 항상 '음'이 보임(폰트 폴백으로 빨강만 나오던 문제 해결)."""
    if size in _WORKS_PWA_ICON_CACHE:
        return _WORKS_PWA_ICON_CACHE[size]
    from PIL import Image, ImageDraw
    import io as _io
    S = size
    W = (255, 255, 255, 255)
    img = Image.new("RGBA", (S, S), (165, 40, 44, 255))   # KNK 빨강 #A5282C 풀블리드
    d = ImageDraw.Draw(img)
    sw = max(3, int(round(S * 0.05)))
    # ㅇ (원/링)
    d.ellipse([int(S * 0.320), int(S * 0.160), int(S * 0.680), int(S * 0.426)], outline=W, width=sw)
    # ㅡ (가로획)
    by = int(S * 0.460)
    d.rounded_rectangle([int(S * 0.289), by, int(S * 0.711), by + sw], radius=sw // 2, fill=W)
    # ㅁ (네모)
    d.rounded_rectangle([int(S * 0.332), int(S * 0.570), int(S * 0.668), int(S * 0.808)],
                        radius=max(2, int(S * 0.024)), outline=W, width=sw)
    buf = _io.BytesIO(); img.save(buf, "PNG")
    data = buf.getvalue(); _WORKS_PWA_ICON_CACHE[size] = data
    return data


@app.get("/manifest.webmanifest")
async def works_manifest():
    return JSONResponse({
        "id": "/?app=works",
        "name": "KNK Eum WORKS",
        "short_name": "Eum WORKS",
        "description": "KNK Eum WORKS — 통합 업무 시스템",
        "start_url": "/app",
        "scope": "/",
        # z1117 (대표 지시 2026-09-20): 휴대폰 녹음기 등의 「공유」 목록에 WORKS 를 띄운다.
        #   회의가 길어 크롬이 녹음 화면을 버려도, 녹음기에서 공유 한 번으로 회의록에 붙고 자동 정리된다.
        #   ⚠ 설치된 앱(WebAPK)에만 뜬다 — manifest 가 바뀌면 크롬이 앱을 다시 만들 때까지(보통 하루) 걸린다.
        "share_target": {
            "action": "/share/audio",
            "method": "POST",
            "enctype": "multipart/form-data",
            "params": {"files": [{"name": "audio", "accept": ["audio/*"]}]},
        },
        "display": "standalone",
        "background_color": "#ffffff",
        "theme_color": "#A5282C",
        "lang": "ko",
        "icons": [
            {"src": "/icon-192.png?v=2", "sizes": "192x192", "type": "image/png", "purpose": "any maskable"},
            {"src": "/icon-512.png?v=2", "sizes": "512x512", "type": "image/png", "purpose": "any maskable"},
            {"src": "/icon.svg?v=2", "sizes": "any", "type": "image/svg+xml", "purpose": "any"},
        ],
        "categories": ["business", "productivity"],
        # v5H226z424 (대표 지시): 메신저 등에서 앱 범위(/) 링크 클릭 시 '브라우저'가 아니라
        #   '설치된 KNK Eum WORKS 앱'으로 열리게(링크 캡처). 이미 열려 있으면 그 창으로.
        # ⚠ navigate-existing 필수 (2026-07-03 대표 제보): focus-existing 은 이미 열린 앱을 '앞으로만' 가져오고
        #   URL 이동을 안 해, 메신저 '📋 회의록' 등 딥링크가 원래 보던 화면 그대로 멈춤. navigate-existing 은 그 창을 대상 주소(/meetings 등)로 이동시킴.
        "launch_handler": {"client_mode": ["navigate-existing", "auto"]},
        "handle_links": "preferred",
        # v5H226z831 (대표 지시): 자기 앱 등록 — 브라우저로 열렸을 때 navigator.getInstalledRelatedApps()로
        #   '이미 설치돼 있음'을 감지해(안드로이드 크롬만 지원) 설치안내(z827) 대신 '📲 앱에서 열기'를 안내.
        "related_applications": [{"platform": "webapp", "url": "https://works.knknara.co.kr/manifest.webmanifest"}],
    }, media_type="application/manifest+json")


@app.get("/sw.js")
async def works_sw():
    js = (
        "// KNK Eum WORKS PWA 서비스워커 — 설치 가능 + 네트워크 기본(pass-through) + 활성화 시 옛 캐시 전부 삭제(설치앱 stale 방지·z767)\n"
        "const KNKWORKS_V='knkworks-v3';\n"
        "self.addEventListener('install',function(e){self.skipWaiting();});\n"
        "self.addEventListener('activate',function(e){e.waitUntil((async function(){try{var ks=await caches.keys();await Promise.all(ks.map(function(k){return caches.delete(k);}));}catch(_e){}try{await self.clients.claim();}catch(_e){}try{var cs=await self.clients.matchAll({type:'window'});cs.forEach(function(c){try{c.navigate(c.url);}catch(_e){}});}catch(_e){}})());});\n"
        "self.addEventListener('fetch',function(e){});\n"
    )
    return Response(js, media_type="application/javascript",
                    headers={"Service-Worker-Allowed": "/", "Cache-Control": "no-cache"})


