@app.get("/mail/{mail_id:int}")
def mail_view_page(req: Request, mail_id: int, img: int = 0, win: int = 0):
    # 11-26 대표 「메일 누르면 2초」 — def(스레드)로 돌려 다른 직원 요청을 막지 않음 · 읽음 표시는 끝에 짧게 따로 저장
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    with db_session() as c:
        m = _mailbox.get_mail(c, mail_id, u["id"])
        if not m:
            return RedirectResponse("/mail/inbox", 303)
        all_atts = _mailbox.list_attachments(c, mail_id)
        # 11-23 대표 「애플 영수증 빈 화면」 — 예전에 본문이 인라인 첨부로 잘못 저장된 메일은 그 부분을 본문으로(보기 때만 · DB 그대로)
        _bh, _bt, _bused = _mailbox.view_body_fallback(c, m, all_atts)
        if _bused:
            m = dict(m, body_html=_bh, body_text=_bt)
            all_atts = [a for a in all_atts if a["id"] not in _bused]
        inline_atts = [a for a in all_atts if a.get("is_inline") and not _mailbox.inline_is_file(a)]
        file_atts = [a for a in all_atts if not a.get("is_inline") or _mailbox.inline_is_file(a)]   # 11-23 inline 표시 붙은 파일도 첨부로
        safe_html = _mailbox.sanitize_html_for_view(m.get("body_html") or "", mail_id, inline_atts,
                                                    defang=int(m.get("risk_level") or 0) >= 2)
        # (11-18 「쉽게 보기」) 이전 대화(인용)는 접어 두고 새로 쓴 내용만 먼저 — 서식 메일·글 메일 모두
        safe_html = _mail_find.fold_quote_html(safe_html)
        body_own, body_quote = _mail_find.split_quote_text(m.get("body_text") or "")
        # 11-18 「안전하게」: 처음 보는 곳(아는 사람 아님)·의심 메일은 바깥 그림을 꺼 둔다(읽음 추적·피싱 그림 막기) — 「그림 보기」로 켬
        img_off = False
        try:
            _in = (m.get("direction") or "in") == "in"
            if _in and not img and (int(m.get("risk_level") or 0) >= 2 or not _mailbox.is_known_sender(c, u["id"], m.get("from_email"))):
                _s2 = _mailbox.strip_remote_refs(safe_html)
                img_off = (_s2 != safe_html)
                safe_html = _s2
        except Exception:
            img_off = False
        from . import mail_attcheck as _macheck
        for _a in file_atts:
            try:
                _a["chk"] = _macheck.quick(_a.get("filename"), _a.get("mime"))
            except Exception:
                _a["chk"] = {"kind": "ok", "why": ""}
        # 보낸사람 ↔ 연락처 자동연결 — 이메일 '정확 일치 1건'이면 링크, 없으면 등록 유도.
        #   (데이터 연결 안전: 추측 매칭 안 함. 정확히 같은 이메일만 단일 후보로 연결)
        sender_contact = None
        _fe = (m.get("from_email") or "").strip()
        if _fe:
            _sc = c.execute("SELECT id, name, company FROM shared_contacts "
                            "WHERE email IS NOT NULL AND lower(email)=lower(?) ORDER BY id LIMIT 1",
                            (_fe,)).fetchone()
            sender_contact = dict(_sc) if _sc else None
        try:
            reply_info = _mail_reply.one(c, u["id"], m["id"])
        except Exception:
            reply_info = {}
        _fres = _mail_folders_res(c, u["id"])   # 11-26 폴더 나누기는 한 번만(예전엔 폴더 줄·같은 대화가 따로 두 번)
        folder_info = _mail_folder_info(c, u["id"], m, _fres)
        m = dict(m, thread=_mail_thread_info(c, u["id"], m, _fres))   # 11-22 밤 「💬 같은 대화」(옮기지 않고 한눈에)
        who_info = _mail_who_info(m, folder_info)
        nav = _mailbox.nav_ids(c, u["id"], m)
        fu = _mail_follow_info(c, u, m)   # 11-19 2단계 — 🚩 기한 · ⏰ 다시 알림 표시(보는 사람 소속 시각)
        pp = _mail_view_people(c, u, m)   # 11-21 다 묶음 — 사내 보낸 사람 「이름 직책 부서」·👔 · 나=받는 사람/참조
        dl = _mdlg_ctx(c, u, mail_id)     # 11-20 👉 맡기기(이음 요청) — 단추·상태 띠
        lgf, cpg = _mail_glance_view(c, u, m)   # 11-20 2단계 — ⑦ 큰 파일 받아 간 시각 · 🏢 거래처 진행 상황(읽기만)
    _mail_mark_read_short(mail_id, u["id"])
    return ctx(req, "mail_view_win.html" if win else "mail_view.html", user=u, m=m, ai_on=mail_ai_enabled_for(u),
               safe_html=safe_html, file_atts=file_atts, has_html=_mailbox.html_has_content(safe_html),
               sender_contact=sender_contact, reply_info=reply_info, folder_info=folder_info,
               who_info=who_info, body_own=body_own, body_quote=body_quote, quote_css=_mail_find.QUOTE_CSS,
               nav=nav, img_off=img_off, fu=fu, dl=dl, lgf=lgf, cpg=cpg, pp=pp)


