@app.post("/mail/bulk")
async def mail_bulk(req: Request):
    """여러 통 한 번에 — op = read·unread·star·unstar·archive·unarchive·delete·restore·pin(folder_id · 0=자동으로) · 내 메일만 · 500통까지."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    form = await req.form()
    op = (form.get("op") or "").strip()
    ids = [x for x in (form.get("ids") or "").replace(" ", "").split(",") if x][:500]
    if not ids:
        return JSONResponse({"ok": False, "message": "고른 메일이 없습니다."}, 400)
    with db_session() as c:
        if op == "pin":
            key = (form.get("key") or "").strip()[:20]
            try:
                fid = int(form.get("folder_id") or 0)
            except Exception:
                fid = 0
            if fid and not key:
                key = "f%d" % fid
            if key:
                _res = _mail_folders.classify(c, u["id"]) if _mail_folders.has_tree(c, u["id"]) else {}
                if key not in (_res.get("valid") or ()):
                    return JSONResponse({"ok": False, "message": "옮길 수 없는 폴더입니다."}, 400)
            n = _mailbox.set_pin(c, u["id"], ids, key)
        elif op in ("read", "unread", "star", "unstar", "archive", "unarchive", "delete", "restore"):
            n = _mailbox.bulk_apply(c, u["id"], ids, op)
        else:
            return JSONResponse({"ok": False, "message": "모르는 일입니다."}, 400)
    return JSONResponse({"ok": True, "n": n})


@app.post("/mail/read-all")
async def mail_read_all(req: Request):
    """11-22 대표 「읽지 않은 메일을 한 번에 읽음으로」 — fd 없음 = 받은편지함 전체 · fd=폴더 열쇠 = 그 폴더만.
    dry=1 이면 셈만(확인 창) · 하면 바꾼 번호를 돌려줌(↺ 되돌리기). 이음웍스 메일 안 표시만 바뀜(하이웍스 원본은 그대로)."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    form = await req.form()
    fd = (form.get("fd") or "").strip()[:20]
    dry = (form.get("dry") or "") == "1"
    with db_session() as c:
        name = "받은편지함"
        if fd:
            try:
                mf = _mail_folders.classify(c, u["id"]) if _mail_folders.has_tree(c, u["id"]) else None
            except Exception:
                mf = None
            if not mf or fd not in mf["keys_of"]:
                return JSONResponse({"ok": False, "message": "없는 폴더입니다."}, 400)
            name = mf["labels"].get(fd, "폴더")
            ids = _mailbox.unread_ids(c, u["id"], senders=_mail_folders.senders_in(mf, fd),
                                      fd_keys=sorted(mf["keys_of"].get(fd, set())))
        else:
            ids = _mailbox.unread_ids(c, u["id"], noad=_mail_find.bulk_map(c, u["id"]))
        if dry or not ids:
            return JSONResponse({"ok": True, "n": len(ids), "name": name, "dry": True})
        n = _mailbox.set_read_many(c, u["id"], ids, True)
    return JSONResponse({"ok": True, "n": n, "name": name, "ids": ",".join(str(i) for i in ids)})


@app.post("/mail/from-refill")
async def mail_from_refill_start(req: Request):
    """11-22 대표 「보낸 사람 없는 메일 다시 읽어서 채워 줘」 — 내 받은 메일 중 보낸 사람 주소가 빈 메일을 하이웍스 원본 머리에서 다시 읽어 채움.
    dry=1 = 셈만(찾은 통수만 · 주소는 안 돌려줌) · undo=1 = 마지막으로 채운 묶음 되돌림 · 뒤에서 돌고 GET 으로 진행 상황."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    from . import mail_from_refill as _mfr
    form = await req.form()
    if (form.get("undo") or "") == "1":
        with db_session() as c:
            n = _mfr.undo(c, u["id"])
        _mail_folders._CACHE.pop(u["id"], None)
        return JSONResponse({"ok": True, "undone": n})
    if (form.get("hold") or "") in ("1", "0"):
        # 11-22 옛 원본 다시 읽기 준비 — 하이웍스 「전체 메일」로 바꾸기 **전에** 켬(옛 메일이 새 메일로 다시 들어오지 않게) · 0 = 끔
        from . import mail_fetch as _mfx
        with db_session() as c:
            if form.get("hold") == "1":
                _mfx.set_hold(c, u["id"], "원본 다시 읽기 준비(대표)")
            else:
                _mfx.clear_hold(c, u["id"])
            info = _mfx.hold_info(c, u["id"])
        return JSONResponse(dict(info, ok=True))
    with db_session() as c:
        protocol, host, port, ssl, user, pw, acct = _mailfetch_creds(c, u, None)
    if not (host and user and pw):
        return JSONResponse({"ok": False, "message": "메일함 계정 정보가 없습니다."}, 400)
    st = _mfr.start(u["id"], (protocol, host, port, ssl, user, pw), (form.get("dry") or "") == "1", db_session,
                    on_done=lambda uid: _mail_folders._CACHE.pop(uid, None))
    return JSONResponse(dict(st, ok=True))


