@app.post("/mail/archive/recent")
async def mail_archive_recent(req: Request):
    """11-23 대표 「보관함 메일도 3·6·12개월 받은편지함으로 되돌리기」 — months(3·6·12) · dry=1 셈만 ·
    undo=번호들 = 방금 꺼낸 메일을 다시 보관함으로. 내 받은 메일만."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    form = await req.form()
    undo = (form.get("undo") or "").strip()
    with db_session() as c:
        if undo:
            n = _mailbox.rearchive_ids(c, u["id"], undo.split(","))
            return JSONResponse({"ok": True, "n": n})
        months = (form.get("months") or "3").strip()
        if (form.get("dry") or "1") != "0":
            n, cut = _mailbox.unarchive_recent(c, u["id"], months, dry=True)
            return JSONResponse({"ok": True, "n": n, "since": (cut or "")[:10], "dry": True})
        ids, cut = _mailbox.unarchive_recent(c, u["id"], months, dry=False)
    _mail_folders._CACHE.pop(u["id"], None)
    return JSONResponse({"ok": True, "n": len(ids), "since": (cut or "")[:10], "ids": ",".join(str(i) for i in ids)})


@app.post("/mail/{mail_id:int}/folder")
async def mail_set_folder(req: Request, mail_id: int):
    """「📁 이 폴더로」 — 이 메일 보낸 곳(회사 주소 @ 뒤, 개인 메일은 그 주소)을 그 폴더로 기억.
    11-25 knk-no-silent-change: dry=1 = 몇 통인지만 · when=all(지난 메일도)/new(지금부터) 를 꼭 골라야 바꿈 · ↺ /mail/move/undo."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    form = await req.form()
    try:
        fid = int(form.get("folder_id") or 0)
    except Exception:
        fid = 0
    with db_session() as c:
        m = _mailbox.get_mail(c, mail_id, u["id"])
        if not m or m.get("direction") == "out":
            return JSONResponse({"ok": False, "message": "메일을 찾을 수 없습니다(본인 받은 메일만)."}, 404)
        r = _mail_folders.set_rule(c, u["id"], fid, m.get("from_email") or "", _mail_folders.classify(c, u["id"]),
                                   when=(form.get("when") or "").strip() or None, dry=(form.get("dry") or "") == "1")
        if not r.get("ok"):
            return JSONResponse(r, 400)
        if r.get("dry"):
            return JSONResponse(r)
        res = _mail_folders.classify(c, u["id"])
        cur = _mail_folders.folder_of(res, m.get("from_email") or "")
    return JSONResponse({"ok": True, "folder": cur["name"], "key": cur["key"], "kind": r["kind"],
                         "pattern": r["pattern"], "moved": r["moved"], "when": r.get("when"), "undo": True})


@app.post("/mail/move")
async def mail_move(req: Request):
    """11-22 대표 「내가 옮기면 옮긴 위치가 기준 · 관련 메일 따라 · 새 메일도 · 옮길 때 지금부터만/지난 메일도 꼭 묻기 · 부서 폴더로도」
    ids = 고른 받은 메일 · key = 옮길 곳(f…·t…·gen) · dry=1 → 묻는 창에 보일 범위·통수만
    when = new(지금부터 오는 메일 + 고른 메일) · all(지난 메일도 모두) · one(고른 메일만) · scope = company · person · 나에게만."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    form = await req.form()
    ids = [x for x in (form.get("ids") or "").replace(" ", "").split(",") if x][:500]
    if not ids:
        return JSONResponse({"ok": False, "message": "고른 메일이 없습니다."}, 400)
    with db_session() as c:
        if not _mail_folders.has_tree(c, u["id"]):
            return JSONResponse({"ok": False, "message": "폴더가 없습니다."}, 400)
        res = _mail_folders.classify(c, u["id"])
        if (form.get("dry") or "") == "1":
            r = _mail_folders.move_scopes(c, u["id"], res, ids, (form.get("key") or "").strip()[:20] or None)
        else:
            r = _mail_folders.move(c, u["id"], res, ids, (form.get("key") or "").strip()[:20],
                                   (form.get("when") or "").strip(), (form.get("scope") or "company").strip())
    return JSONResponse(r, 200 if r.get("ok") else 400)


