@app.get("/mail/folders", response_class=HTMLResponse)
async def mail_folders_page(req: Request, msg: str = ""):
    """폴더 관리 — 더하기·이름 바꾸기·순서·지우기 · 내가 정한 규칙 보기·지우기(나에게만)."""
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    with db_session() as c:
        _mail_folders.ensure(c)
        fl = _mail_folders.folders(c, u["id"])
        rl = _mail_folders.rules(c, u["id"])
        res = _mail_folders.classify(c, u["id"]) if fl else None
        tl = _mail_folders.teams(c)
    groups = [f for f in fl if not f["parent_id"]]
    for g in groups:
        g["kids"] = [f for f in fl if f["parent_id"] == g["id"]]
        for k in g["kids"]:   # 11-22 아래 폴더(삼성그룹 → 삼성전자·삼성전기)
            k["kids"] = [f for f in fl if f["parent_id"] == k["id"]]
        # 「위치」 고르기 = 이 묶음 바로 아래 · 이 묶음의 다른 폴더 아래(아래 폴더가 없는 폴더만 그 아래로 감)
        g["places"] = [(g["id"], "「%s」 바로 아래" % g["name"])] + [(k["id"], "　└ %s 아래" % k["name"]) for k in g["kids"]]
    cnt = {}
    for g in ((res or {}).get("nodes") or []):
        cnt[g["key"]] = (g["n"], g["u"])
        for k in g["children"]:
            cnt[k["key"]] = (k["n"], k["u"])
            for k2 in k.get("children") or []:
                cnt[k2["key"]] = (k2["n"], k2["u"])
    # 11-19 부서 폴더 편집용 — 지금 나무 · 지운 부서 · 옮길 곳·합칠 곳 고르기
    staff_tree, staff_gone, staff_parents, staff_into = [], [], [("top", "6.케이엔케이 바로 아래")], []
    try:
        with db_session() as c:
            _tp = _mail_folders.team_prefs(c, u["id"])
        stn = [g for g in ((res or {}).get("nodes") or []) if g.get("kind") == "staff"]
        if stn:
            staff_tree = [x for x in stn[0]["children"] if x["key"][:1] in ("t", "g")]
        labels = (res or {}).get("labels") or {}
        for x in staff_tree:
            if x.get("group"):
                staff_parents.append((x["key"], x["name"]))
        for gk2, pr in _tp.items():
            if gk2.startswith("g") and gk2 not in dict(staff_parents):
                staff_parents.append((gk2, pr.get("name") or gk2))
        for _gk, _gn in (("th", _mail_folders.HQ_FOLDER_NAME), ("tv", _mail_folders.VN_FOLDER_NAME)):
            if _gk not in dict(staff_parents) and not _tp.get(_gk, {}).get("merge"):
                staff_parents.append((_gk, _tp.get(_gk, {}).get("name") or _gn))
        for x in staff_tree:
            staff_into.append((x["key"], x["name"]))
            for y in x.get("children") or []:
                staff_into.append((y["key"], "　└ " + y["name"]))
        staff_into.append(("tx", "KNK 기타(부서 모름)"))
        for k3, pr in _tp.items():
            if pr.get("merge") and k3.startswith("t") and k3 not in ("tv", "th"):
                staff_gone.append({"key": k3, "name": labels.get(k3, k3), "into": labels.get(pr["merge"], "KNK 기타(부서 모름)")})
            elif k3 in ("tv", "th") and pr.get("merge"):
                staff_gone.append({"key": k3, "name": pr.get("name") or (_mail_folders.VN_FOLDER_NAME if k3 == "tv" else _mail_folders.HQ_FOLDER_NAME),
                                   "into": "", "group": True})
    except Exception:
        pass
    try:   # 11-22 밤 대표 「메일 규칙을 쉽게」 2 — 폴더마다 「📥 들어온 까닭 · 통수」
        with db_session() as c:
            _why = _mail_folders.folder_reasons(c, u["id"], res) if res else {}
    except Exception as _e:
        print("[MAIL-FOLDERS] 들어온 까닭 셈 실패(화면은 그대로): %s" % str(_e)[:160], flush=True)
        _why = {}
    _seed_full = True
    if not groups:   # 11-24 대표: 직원 기본 폴더 = 회사 부서만(대표 고객사 목록은 대표만)
        try:
            with db_session() as _c2:
                _seed_full = (_mail_folders._owner_id(_c2) == u["id"])
        except Exception:
            _seed_full = False
    return ctx(req, "mail_folders.html", user=u, groups=groups, rules=rl, res=res, msg=msg, cnt=cnt, why=_why,
               gen=((res or {}).get("gen") or {"n": 0, "u": 0}),
               team_labels=[_mail_folders.team_label(t) for t in tl],
               staff_tree=staff_tree, staff_gone=staff_gone, staff_parents=staff_parents, staff_into=staff_into,
               seed_full=_seed_full)


@app.post("/mail/folders/team")
async def mail_folders_team(req: Request):
    """메일 부서 폴더(6.케이엔케이 아래) — 이름 바꾸기 · 위치 옮기기 · 지우기(합칠 곳) · 되살리기 · 부서 폴더 더하기·지우기.
    11-19 대표 「부서이름 수정·삭제·추가」 → 「메일에서만 고치기」: 회사 부서표·권한·결재·이음은 그대로 · 나에게만."""
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    form = await req.form()
    op = (form.get("op") or "").strip()
    key = (form.get("key") or "").strip()
    msg = ""
    try:
        with db_session() as c:
            if op == "rename":
                nm = (form.get("name") or "").strip()
                _mail_folders.set_team_pref(c, u["id"], key, name=nm)
                msg = "이름을 바꿨습니다(메일에서만)" if nm else "원래 이름으로 되돌렸습니다"
            elif op == "move":
                _mail_folders.set_team_pref(c, u["id"], key, parent=(form.get("parent") or "").strip())
                msg = "위치를 옮겼습니다"
            elif op == "merge":
                into = (form.get("into") or "tx").strip() or "tx"
                if into == key:
                    into = "tx"
                _mail_folders.set_team_pref(c, u["id"], key, merge=into)
                msg = "부서 폴더를 지웠습니다 — 그 메일은 합친 곳에서 보입니다(아래 「지운 부서」에서 되살릴 수 있음)"
            elif op == "unmerge":
                _mail_folders.set_team_pref(c, u["id"], key, merge="")
                msg = "되살렸습니다"
            elif op == "reset":
                _mail_folders.del_team_pref(c, u["id"], key)
                msg = "처음(회사 부서표) 상태로 되돌렸습니다"
            elif op == "addgroup":
                _mail_folders.add_team_group(c, u["id"], form.get("name") or "")
                msg = "부서 폴더를 더했습니다 — 각 부서의 「위치」에서 이 폴더를 고르면 그 안으로 들어갑니다"
            elif op == "delgroup":
                _mail_folders.del_team_group(c, u["id"], key)
                msg = "부서 폴더를 지웠습니다 — 안에 있던 부서는 6.케이엔케이 바로 아래로"
            elif op == "restoregroup":
                _mail_folders.set_team_pref(c, u["id"], key, merge="")
                msg = "되살렸습니다"
            else:
                msg = "모르는 일입니다"
    except ValueError as e:
        msg = "⚠ " + str(e)
    import urllib.parse as _up
    # 11-22 대표 「저장이 된 건지 헷갈려」 — 저장한 줄로 돌아가 「✓ 저장됨」 표시(hl)
    return RedirectResponse("/mail/folders?msg=" + _up.quote(msg) + ("&hl=" + _up.quote(key) if key else "") + "#staff", 303)


@app.get("/mail/folders/general", response_class=HTMLResponse)
async def mail_folders_general_page(req: Request):
    """「일반」 정리 — 일반에 남은 메일을 보낸 곳(회사 주소·개인 메일 주소)별로 묶고, 고른 폴더로 한 번에(나에게만)."""
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    with db_session() as c:
        _mail_folders.seed_if_owner(c, u["id"])
        if not _mail_folders.has_tree(c, u["id"]):
            return RedirectResponse("/mail/folders", 303)
        res = _mail_folders.classify(c, u["id"])
        groups = _mail_folders.general_groups(c, u["id"], res)
        choices = _mail_folders.assignable(c, u["id"])
        robots = _mail_folders.robot_senders(c, u["id"], res)
        _oth = next((g for g in _mail_folders.folders(c, u["id"]) if not g["parent_id"] and g["kind"] == "other_customer"), None)
    # 11-22 「＋ 새 폴더로」 넣을 곳 = 묶음·폴더(3단계까지) · 기본 = 기타 고객사
    parents = [f for f in choices if f["depth"] in (0, 1)]
    return ctx(req, "mail_folders_general.html", user=u, groups=groups, choices=choices, parents=parents,
               parent_default=(_oth["id"] if _oth else (parents[0]["id"] if parents else 0)),
               robot_n=len(robots), robot_m=sum(robots.values()), robot_name=_mail_folders.ROBOT_FOLDER,
               gen=res.get("gen") or {"n": 0, "u": 0})


