@app.post("/mail/folders/op")
async def mail_folders_op(req: Request):
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    form = await req.form()
    op = (form.get("op") or "").strip()

    def _i(k):
        try:
            return int(form.get(k) or 0)
        except Exception:
            return 0
    msg = ""
    with db_session() as c:
        uid = u["id"]
        if op == "seed":
            _own_seed = (_mail_folders._owner_id(c) == uid)
            _made = _mail_folders.seed(c, uid) if _own_seed else _mail_folders.seed_staff(c, uid)
            msg = (("아웃룩 폴더를 만들었습니다." if _own_seed else "회사 부서 폴더(케이엔케이)를 만들었습니다.")
                   if _made else "이미 폴더가 있어 그대로 두었습니다.")
        elif op == "add":
            pid = _i("parent_id") or None
            msg = "폴더를 더했습니다." if _mail_folders.add_folder(c, uid, form.get("name"), pid,
                                                                 (form.get("kind") or "").strip()) else "이름을 적어 주세요."
        elif op == "rename":
            msg = "이름을 바꿨습니다." if _mail_folders.rename_folder(c, uid, _i("id"), form.get("name")) else ""
        elif op in ("up", "down"):
            _mail_folders.move_folder(c, uid, _i("id"), -1 if op == "up" else 1)
        elif op == "delete":
            n = _mail_folders.delete_folder(c, uid, _i("id"))
            msg = ("폴더 %d개를 지웠습니다(메일은 그대로 · 자동 분류나 일반으로 돌아갑니다)." % n) if n else ""
        elif op == "aliases":
            msg = "다른 이름을 저장했습니다." if _mail_folders.set_aliases(c, uid, _i("id"), form.get("aliases")) else ""
        elif op == "subjtags" and not _mail_folders.SUBJECT_RULES_ON:   # 11-22 밤 대표 취소(회신 메일까지 옮겨짐)
            msg = "제목 꼬리표 규칙은 쓰지 않습니다(회신 메일까지 옮겨져 취소)."
        elif op == "subjtags":   # 11-22 폴더마다 「🏷 제목 꼬리표」 칸
            r = _mail_folders.set_subject_tags(c, uid, _i("id"), form.get("tags") or "")
            msg = ((("제목 꼬리표 규칙을 저장했습니다 — " + ", ".join("[%s…]" % t for t in r["tags"]) + " 메일 %d통이 이 폴더에 있습니다." % r["n"])
                    if r.get("tags") else "제목 꼬리표 규칙을 비웠습니다.") if r.get("ok") else (r.get("message") or ""))
        elif op == "delrule":
            msg = "규칙을 지웠습니다." if _mail_folders.delete_rule(c, uid, _i("id")) else ""
        elif op == "parent":   # 11-22 폴더 위치(묶음 바로 아래 · 다른 폴더 아래)
            msg = "위치를 바꿨습니다." if _mail_folders.set_parent(c, uid, _i("id"), _i("parent_id")) else "그 자리로는 옮길 수 없습니다(3단계까지 · 아래 폴더가 있는 폴더는 묶음 바로 아래만)."
    from urllib.parse import quote
    _hl = ("f%d" % _i("id")) if (_i("id") and op in ("rename", "aliases", "subjtags", "parent", "up", "down")) else ""
    _q = [x for x in (("msg=" + quote(msg)) if msg else "", ("hl=" + _hl) if _hl else "") if x]
    return RedirectResponse("/mail/folders" + (("?" + "&".join(_q)) if _q else ""), 303)


@app.post("/mail/{mail_id:int}/reply-mark")
async def mail_reply_mark(req: Request, mail_id: int):
    """④ 회신 필요 표시를 본인이 고친다 — state=done(회신 안 해도 됨) / need(회신 필요로 표시) / clear(규칙대로)."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    form = await req.form()
    state = (form.get("state") or "").strip()
    if state not in ("done", "need", "clear"):
        return JSONResponse({"ok": False, "message": "잘못된 요청"}, 400)
    with db_session() as c:
        if not _mail_reply.set_mark(c, u["id"], mail_id, state):
            return JSONResponse({"ok": False, "message": "메일을 찾을 수 없습니다(본인 받은 메일만)."}, 404)
        info = _mail_reply.one(c, u["id"], mail_id)
    return JSONResponse({"ok": True, "lv": info.get("lv", 0), "why": info.get("why", ""), "state": info.get("state")})


@app.post("/mail/{mail_id:int}/to-task")
async def mail_to_task(req: Request, mail_id: int):
    """받은 메일 → 내 '할 일'(일일카드) 등록 — 메일을 업무로 전환(메일=업무 관문).
    ⚠ 프로젝트·고객 자동연결은 하지 않음(데이터 연결 안전 원칙): 애매한 추측 대신
    사용자가 일일카드에서 직접 연결하도록 유도. 출처(보낸이·원문링크)는 메모에 남김."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    # 11-19 2단계 — 날짜를 고르면 그날 할 일(달력에도 그날로) · 없으면 오늘
    try:
        _f = await req.form()
        _wd = (_f.get("work_date") or "").strip()
    except Exception:
        _wd = ""
    import re as _re_td
    if not _re_td.match(r"^\d{4}-\d{2}-\d{2}$", _wd or ""):
        _wd = ""
    with db_session() as c:
        m = _mailbox.get_mail(c, mail_id, u["id"])
        if not m:
            return JSONResponse({"ok": False, "message": "메일을 찾을 수 없습니다(본인 메일만)."}, 404)
        if not _wd:
            _wd = _mail_local_today(_mail_off(c, u))
        subj = ((m.get("subject") or "").strip() or "(제목 없음)")[:180]
        frm = (m.get("from_name") or "").strip()
        fmail = (m.get("from_email") or "").strip()
        who = (frm + (f" <{fmail}>" if fmail else "")).strip() or "(보낸이 미상)"
        summ = (m.get("summary") or "").strip()
        notes = f"📧 메일에서 생성 · 보낸이: {who}"
        if summ:
            notes += "\n" + summ
        notes += f"\n원문: {_WORKS_PUBLIC_BASE}/mail/{mail_id}"
        _cur = c.execute(
            "INSERT INTO tasks(user_id, work_date, title, category, status, notes) "
            "VALUES(?,?,?,?,?,?)",
            (u["id"], _wd, f"[메일] {subj}", "고객대응", "진행중", notes),
        )
        tid = _cur.lastrowid   # 11-19 고침: 전에는 c.lastrowid(연결에는 없음) → 늘 오류 · 저장도 되돌려졌음
    return JSONResponse({"ok": True, "task_id": tid, "work_date": _wd,
                         "message": "내 할 일(일일카드) %s에 추가했습니다." % _wd[5:].replace("-", "/")})


@app.post("/mail/{mail_id:int}/to-contact")
async def mail_to_contact(req: Request, mail_id: int):
    """받은 메일의 보낸사람을 전사 연락처(주소록)로 등록 — 데이터 연결(메일↔주소록).
    이미 같은 이메일이 있으면 새로 만들지 않고 그 연락처로 안내(중복 방지)."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    # 2026-11-16: 화면에서 확인한 칸(이름·직급·회사·휴대폰…)이 함께 오면 그대로 저장. 안 오면 옛 방식(이름·메일만).
    try:
        _form = await req.form()
    except Exception:
        _form = {}
    with db_session() as c:
        m = _mailbox.get_mail(c, mail_id, u["id"])
        if not m:
            return JSONResponse({"ok": False, "message": "메일을 찾을 수 없습니다(본인 메일만)."}, 404)
        email = (m.get("from_email") or "").strip()
        if not email or "@" not in email:
            return JSONResponse({"ok": False, "message": "보낸사람 이메일이 없어 등록할 수 없습니다."}, 400)
        name = (m.get("from_name") or "").strip() or email.split("@")[0]
        _email_form = (_form.get("email") or "").strip()
        row = c.execute("SELECT id, name, company FROM shared_contacts WHERE email IS NOT NULL "
                        "AND (lower(email)=lower(?) OR (?<>'' AND lower(email)=lower(?))) ORDER BY id LIMIT 1",
                        (email, _email_form, _email_form)).fetchone()
        if row:
            return JSONResponse({"ok": True, "contact_id": row["id"], "existed": True,
                                 "name": row["name"] or "", "company": row["company"] or "",
                                 "message": "이미 등록된 연락처입니다."})
        if (_form.get("name") or "").strip():
            # 화면에서 사람이 확인한 칸 그대로(서명에서 읽은 초안을 고친 것) — 주소록 직접 등록과 같은 저장 길
            data = _contact_form_data(_form)
            for _k in _contacts.FIELD_KEYS:
                data[_k] = (data.get(_k) or "")[:300 if _k in ("address", "note") else 120]
            data["name"] = data["name"][:80]
            data["email"] = data["email"] if "@" in data["email"] else email[:120]
            data["source"], data["card_image"] = "signature", ""
            if data.get("visibility") == "dept":
                data["share_team_id"] = u.get("team_id")
            if data.get("customer_id") and not c.execute(
                    "SELECT 1 FROM customers WHERE id=?", (data["customer_id"],)).fetchone():
                data["customer_id"] = None
            cid = _contacts.create_contact(c, data, u["id"])
            return JSONResponse({"ok": True, "contact_id": cid, "existed": False,
                                 "name": data["name"], "company": data.get("company") or "",
                                 "message": "주소록에 저장했습니다."})
        cur = c.execute("INSERT INTO shared_contacts(name, email, source) VALUES(?,?,'signature')",
                        (name[:80], email[:120]))
        cid = cur.lastrowid
    return JSONResponse({"ok": True, "contact_id": cid, "existed": False,
                         "message": "연락처로 등록했습니다. (상세에서 회사·연락처를 채워주세요)"})


@app.api_route("/mail/{mail_id:int}/contact-draft", methods=["GET", "POST"])
async def mail_contact_draft(req: Request, mail_id: int):
    """받은 메일의 서명에서 연락처 칸(이름·직급·회사·부서·휴대폰·전화·팩스·주소)을 채운 「초안」(JSON).
    저장하지 않는다 — 사람이 화면에서 확인한 뒤 to-contact 로 저장. POST text= 면 사람이 고친(붙여 넣은) 서명으로 다시 읽는다.
    규칙으로만 읽는다(AI·외부 전송 없음 · app/mail_signature.py)."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    text = ""
    if req.method == "POST":
        try:
            text = ((await req.form()).get("text") or "").strip()[:4000]
        except Exception:
            text = ""
    with db_session() as c:
        m = _mailbox.get_mail(c, mail_id, u["id"])
        if not m:
            return JSONResponse({"ok": False, "message": "메일을 찾을 수 없습니다(본인 메일만)."}, 404)
        if text:
            d = _mail_sig.draft_from_text(text, m.get("from_name") or "", m.get("from_email") or "", is_block=True)
            d["customer_id"] = _mail_sig.company_hint(c, m.get("from_email") or "")["customer_id"]
        else:
            d = _mail_sig.draft_from_mail(m, c)
        cust = None
        if d.get("customer_id"):
            _cu = c.execute("SELECT " + _CUST_PICK_COLS + " FROM customers WHERE id=?",
                            (d["customer_id"],)).fetchone()
            if _cu:
                cust = {"id": _cu["id"], "label": _cust_pick_label(dict(_cu))}
        # 같은 휴대폰·메일의 기존 연락처 — 내가 볼 수 있는 것만 알린다(남의 개인 연락처는 드러내지 않는다)
        dups = [{"id": x["id"], "name": x["name"], "company": x.get("company") or ""}
                for x in _contacts.find_duplicates(c, mobile=d["fields"].get("mobile") or "",
                                                   email=d["fields"].get("email") or "")
                if _contacts.can_see(x, u)][:3]
    return JSONResponse({"ok": True, "fields": d["fields"], "sig_text": d.get("sig_text") or "",
                         "notes": d.get("notes") or [], "filled": d.get("filled") or [],
                         "customer": cust, "dups": dups},
                        headers={"Cache-Control": "no-store"})


# ─── 메일 자동분류 규칙 (Phase2) — 보낸사람/제목 키워드 → 카테고리 강제 ───
def _mail_unread(c, uid):
    """11-23 대표 「광고·알림 칸에만 보이게」 — 받은편지함 안 읽음 숫자(광고·알림 뺌 · 📢 칸에만 보이므로). 실패하면 예전 숫자."""
    try:
        return int(_mailbox.count_unread(c, uid, noad=_mail_find.bulk_map(c, uid)) or 0)
    except Exception as e:
        print("[MAIL unread-noad ERR] %s: %s" % (type(e).__name__, e))
        return int(_mailbox.count_unread(c, uid) or 0)


def _mail_ad_senders_of(c, uid, ids):
    """고른 메일들의 보낸 사람(받은 메일 · 회사 밖 주소만) — [{addr, name, first(고른 것 중 가장 이른 받은 때)}]."""
    ids = [int(x) for x in ids if str(x).strip().isdigit()][:500]
    if not ids:
        return []
    rows = c.execute("SELECT lower(COALESCE(from_email,'')) AS a, MAX(COALESCE(from_name,'')) AS nm, MIN(received_at) AS f FROM mail_messages "
                     "WHERE user_id=? AND direction='in' AND id IN (" + ",".join("?" * len(ids)) + ") GROUP BY lower(COALESCE(from_email,''))",
                     (uid, *ids)).fetchall()
    return [{"addr": r["a"], "name": r["nm"] or r["a"], "first": r["f"] or ""} for r in rows
            if r["a"] and "@" in r["a"] and not r["a"].endswith("@knknara.co.kr")]


@app.post("/mail/ad-mark")
async def mail_ad_mark(req: Request):
    """11-23 대표 「광고·알림은 내가 지정할 수 있어?」 — 보낸 사람(주소)을 광고·알림으로 / 아님으로 / 자동 판단으로(나에게만).
    form: addr 또는 ids(고른 메일 → 그 보낸 사람들) · mode(on|off|'') · since(on 일 때 그때 받은 메일부터 · 없으면 지난 메일도 모두)
          dry=1 = 묻는 창에 보일 숫자만(보낸 사람별 지금 통수 · 고른 메일 날짜부터 통수)"""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    form = await req.form()
    from . import mail_ui_prefs as _mup
    addr = (form.get("addr") or "").strip().lower()
    ids = [x for x in (form.get("ids") or "").split(",") if x.strip()]
    mode = (form.get("mode") or "").strip()
    since = (form.get("since") or "").strip()
    if addr.endswith("@knknara.co.kr"):
        return JSONResponse({"ok": False, "message": "회사 안 주소는 광고·알림으로 정할 수 없습니다"})
    with db_session() as c:
        snd = _mail_ad_senders_of(c, u["id"], ids) if ids else ([{"addr": addr, "name": addr, "first": ""}] if addr else [])
        if not snd:
            return JSONResponse({"ok": False, "message": "회사 밖에서 받은 메일이 아니어서 광고·알림으로 정할 수 없습니다" if ids else "보낸 사람 주소가 없습니다"})
        first = min([x["first"] for x in snd if x["first"]] or [""])
        if (form.get("dry") or "") == "1":
            q = ("SELECT COUNT(*) FROM mail_messages WHERE user_id=? AND direction='in' AND is_deleted=0 AND COALESCE(is_blocked,0)=0 "
                 "AND lower(from_email) IN (" + ",".join("?" * len(snd)) + ")")
            a = [x["addr"] for x in snd]
            n_all = c.execute(q, (u["id"], *a)).fetchone()[0]
            n_first = c.execute(q + " AND received_at >= ?", (u["id"], *a, first)).fetchone()[0] if first else n_all
            return JSONResponse({"ok": True, "senders": snd[:20], "n_send": len(snd), "first": first, "n_all": n_all, "n_first": n_first})
        out = None
        for x in snd:
            out = _mup.set_ad_mark(c, u["id"], x["addr"], mode, since if mode == "on" else "")
    if out is None:
        return JSONResponse({"ok": False, "message": "보낸 사람 주소가 없습니다"})
    _mail_find._BULK.pop(u["id"], None)   # 받은편지함 광고·알림 표시를 바로 다시 셈
    return JSONResponse({"ok": True, "mode": out, "n_send": len(snd), "since": _mup._since(since) if mode == "on" else ""})


@app.post("/mail/ad/trash")
async def mail_ad_trash(req: Request):
    """11-23 대표 「광고·알림에 모아 놓은 건 필요하면 한꺼번에 삭제」 — 📢 광고·알림 칸 메일 모두 휴지통으로(지우지 않음 · 되돌리기).
    form: dry=1 = 통수만 · undo=번호들 = 방금 휴지통으로 보낸 것 되살리기."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    form = await req.form()
    with db_session() as c:
        undo = (form.get("undo") or "").strip()
        if undo:
            _u = [int(x) for x in undo.split(",") if x.strip().isdigit()]
            n = sum(_mailbox.bulk_apply(c, u["id"], _u[i:i + 500], "restore") for i in range(0, len(_u), 500))
            return JSONResponse({"ok": True, "n": n})
        bm = _mail_find.bulk_map(c, u["id"])
        if (form.get("dry") or "") == "1":
            return JSONResponse({"ok": True, "n": int(_mailbox.list_inbox(c, u["id"], count_only=True, ad_only=bm) or 0)})
        ids = []
        while True:
            part = [m["id"] for m in _mailbox.list_inbox(c, u["id"], ad_only=bm, limit=500, offset=len(ids))]
            ids += part
            if len(part) < 500 or len(ids) >= 20000:
                break
        n = sum(_mailbox.bulk_apply(c, u["id"], ids[i:i + 500], "delete") for i in range(0, len(ids), 500))
    _mail_folders._CACHE.pop(u["id"], None)
    return JSONResponse({"ok": True, "n": n, "ids": ",".join(str(i) for i in ids)})


