@app.get("/api/mail/contacts")
async def mail_contacts_api(req: Request, q: str = "", browse: int = 0):
    """메일 쓰기 받는사람 자동완성 — 연락처(shared_contacts)에서 추천.
    (11-18) 연락처 공개 범위(내가 등록 · 전사 공유 · 내 부서 공유)만 · browse=1 = 📇 주소록에서 고르기(검색어 없이도 300명까지)."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False}, 401)
    with db_session() as c:
        items = _mailbox.search_contacts(c, q, limit=(300 if browse else 8), user=u, browse=bool(browse))
        if q and not browse:   # 11-19 1단계 ④ — 회사 그룹 메일 · 내 묶음 · 부서 묶음을 맨 위에
            try:
                _gi = _mwork.ac_items(c, u["id"], q)
                _ge = {g["email"].lower() for g in _gi if g.get("email")}
                items = _gi + [i for i in items if (i.get("email") or "").lower() not in _ge]
            except Exception as e:
                print("[MAIL-GRP] 자동완성 묶음 실패: %s" % str(e)[:120], flush=True)
    return JSONResponse({"ok": True, "items": items})


@app.post("/api/mail/ai-compose")
async def mail_ai_compose(req: Request):
    """메일 쓰기 'AI로 정리' — 거친 메모를 정중한 업무 메일로 다듬어 {subject, body} 반환."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    form = await req.form()
    rough = (form.get("body") or "").strip()
    cur_subject = (form.get("subject") or "").strip()
    if not rough:
        return JSONResponse({"ok": False, "message": "먼저 본문에 요점을 적어주세요."})
    try:
        import json as _json
        from . import ai_client
        if not ai_client.mail_ai_available():   # 11-18 메일 AI = OpenAI 만
            return JSONResponse({"ok": False, "message": "AI가 꺼져 있습니다(메일 AI = OpenAI 키 필요)."})
        system = (
            "당신은 ㈜케이엔케이(KNK·검사기/자동화 설비 제조)의 비즈니스 이메일 작성 도우미입니다. "
            "사용자가 적은 거친 메모·요점을 정중하고 명확한 업무 이메일로 다듬으세요. "
            "규칙: ①인사말·본문·맺음말을 갖춘 자연스러운 메일 ②메모에 없는 사실(수치·날짜·금액·약속)을 "
            "절대 지어내지 말 것 ③서명은 넣지 말 것(시스템이 따로 붙임) ④간결·정중·과장 금지 "
            "⑤원문이 베트남어면 베트남어로, 한국어면 한국어로 작성. "
            '출력은 JSON 한 줄만: {"subject":"제목 제안","body":"메일 본문"} . 다른 텍스트·설명·코드블록 금지.'
        )
        prompt = f"[현재 제목]\n{cur_subject or '(없음)'}\n\n[거친 메모]\n{rough[:4000]}"
        ok, resp = ai_client.ai_chat(prompt, system=system, max_tokens=900, temperature=0.4,
                                     provider=ai_client.MAIL_AI_PROVIDER)
        if not ok:
            return JSONResponse({"ok": False, "message": "AI 정리 실패 — 잠시 후 다시 시도해주세요."})
        subject, bodyout = cur_subject, (resp or "").strip()
        try:
            s = resp or ""
            i, j = s.find("{"), s.rfind("}")
            if i >= 0 and j > i:
                d = _json.loads(s[i:j + 1])
                bodyout = (d.get("body") or "").strip() or bodyout
                if not cur_subject:
                    subject = (d.get("subject") or "").strip() or subject
        except Exception:
            pass  # 파싱 실패 시 응답 전체를 본문으로
        return JSONResponse({"ok": True, "subject": subject, "body": bodyout})
    except Exception as e:
        return JSONResponse({"ok": False, "message": f"오류: {str(e)[:80]}"})


@app.get("/mail/signature", response_class=HTMLResponse)
async def mail_signature_page(req: Request, slot: int = 0):
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    slot = slot if slot in (0, 1, 2) else 0
    _co_info = _mguide_company()
    with db_session() as c:
        cur = _mailbox.get_signature_slot(c, u["id"], slot)
        alts = [_mailbox.get_signature_slot(c, u["id"], k) for k in (0, 1, 2)]
        co_sigs = _mguide_sigs(c, u, _co_info, _mail_from_address_for(c, u))   # 11-20 3단계 ⑧ 🏢 회사 서명(내 정보로 채운 것)
        try:
            sig_default = _mguide.default_slot(c, u["id"], co_sigs)
            sig_pref = _mguide.get_pref(c, u["id"], _mguide.SIG_PREF, "")
        except Exception:
            sig_default, sig_pref = "", ""
        try:   # 11-22 대표 「개인적인 부분만 고칠 수 있게」 — 칸마다 자동 값 · 고친 값
            _pv = _mguide.person_values(c, u["id"], rank_label, _mail_from_address_for(c, u))
            me_fields = [{"key": k, "label": lb, "auto": _pv["auto"].get(k, ""), "ov": _pv["ov"].get(k, ""),
                          "has_ov": k in _pv["ov"], "val": _pv["value"].get(k, "")}
                         for k, lb, vn_only in _mguide.ME_FIELDS if (not vn_only) or _pv["corp"] == "vn"]
        except Exception:
            me_fields = []
    return ctx(req, "mail_signature.html", user=u, sig=cur["body"], sig_slot=slot, sig_name=cur["name"], sig_alts=alts,
               co_sigs=co_sigs, can_company=_mw_admin(u), sig_choices=co_sigs, sig_default=sig_default, sig_pref=sig_pref,
               me_fields=me_fields)


