    want = [int(x) for x in (ids or "").split(",") if x.strip().isdigit()][:400]
    if not want:
        return JSONResponse({"ok": True, "marks": {}})
    with db_session() as c:
        rows = _mdlg.rows_for_mails(c, u["id"], want)
