def _mail_notice(user_id, subject, text):
    """메일 시스템이 나에게 남기는 알림(받은편지함에 한 통) — 예약 메일을 못 보냈을 때 등."""
    try:
        with db_session() as c:
            _mailbox.store_inbound(c, to_email="notice@knknara.co.kr", from_email="knk-mail-notice@knknara.co.kr",
                                   from_name="KNK 메일 알림", subject=subject, text=text, owner_id=user_id, run_ai=False,
                                   message_id="notice-%s-%s@knk" % (user_id, _ms_time.time()))
    except Exception as e:
        print("[MAIL-NOTICE ERR] %s" % str(e)[:160], flush=True)


def _mail_sched_run_once():
    """보낼 때가 된 예약을 보냄 — 한 통씩 「보내는 중」으로 잡은 것만(두 번 안 보냄) · 실패하면 사유를 남기고 알림."""
    import json as _json
    with db_session() as c:
        due = _mailbox.due_scheduled(c)
    for d in due:
        with db_session() as c:
            if not _mailbox.claim_scheduled(c, d["id"]):
                continue
            row = dict(c.execute("SELECT * FROM mail_messages WHERE id=?", (d["id"],)).fetchone())
            ur = c.execute("SELECT * FROM users WHERE id=?", (row["user_id"],)).fetchone()
            atts, total = [], 0
            for a in _mailbox.list_attachments(c, row["id"]):
                g = _mailbox.get_attachment(c, a["id"], row["user_id"])
                if g:
                    atts.append((g["filename"], g["data"], g["mime"]))
                    total += len(g["data"])
        u = dict(ur) if ur else None
        try:
            meta = _json.loads(row.get("sched_meta") or "{}")
        except Exception:
            meta = {}
        if not u or not u.get("is_active", 1):
            with db_session() as c:
                _mailbox.scheduled_fail(c, row["id"], "보내는 사람 계정을 찾을 수 없습니다")
            continue
        try:
            res = _mail_send_core(u, row.get("to_email") or "", row.get("cc") or "", row.get("bcc") or "", row.get("subject") or "",
                                  row.get("body_text") or "", row.get("body_html") or "", atts, total, meta.get("large_tokens") or [])
        except Exception as e:
            res = {"ok": False, "message": "보내는 중 오류: %s" % str(e)[:120]}
        with db_session() as c:
            if res.get("ok"):
                _mailbox.scheduled_done(c, row["id"])
            else:
                _mailbox.scheduled_fail(c, row["id"], res.get("message") or "")
        if not res.get("ok"):
            _mail_notice(row["user_id"], "⚠ 예약 메일을 보내지 못했습니다 — " + (row.get("subject") or ""),
                         "예약해 둔 메일을 보내지 못했습니다.\n\n제목: %s\n받는 사람: %s\n까닭: %s\n\n「📤 보낸편지함」 위 「보낼 예정」에서 「지금 다시 보내기」나 「취소(임시보관함으로)」를 누르세요."
                         % (row.get("subject") or "", row.get("to_email") or "", res.get("message") or ""))
        elif res.get("refused"):
            _mail_notice(row["user_id"], "⚠ 예약 메일 일부 주소에 못 갔습니다 — " + (row.get("subject") or ""),
                         "예약 메일은 보냈지만 아래 주소는 메일 서버가 받지 않았습니다.\n\n" +
                         "\n".join("%s — %s" % (x["addr"], x["why"]) for x in res["refused"]))


def _mail_sched_tick():
    """1분마다 — 보낼 예약 보내기. 나스 백업 시간(월 02:00~07:30)엔 쉼(그 뒤에 보냄)."""
    import threading as _th
    try:
        if not _nas_quiet_now():
            _mail_sched_run_once()
    except Exception as e:
        print("[MAIL-SCHED tick ERR] %s" % str(e)[:200], flush=True)
    finally:
        t = _th.Timer(60, _mail_sched_tick)
        t.daemon = True
        t.start()


# ─── 11-19 2단계-나 🏖 부재중 자동 응답 — 새로 받은 메일에만 · 조심스럽게(하나라도 걸리면 안 보냄) ───
def _mail_autoreply_run(owner_user, cand):
    """cand = [(메일 번호, 자동 발송 표시)] — 받아 온 직후 부름. 보낼 것은 기록부터 남기고(두 번 안 보냄) 보냄."""
    if not cand:
        return
    uid = owner_user.get("id")
    todo = []
    with db_session() as c:
        st = _mailbox.get_autoreply(c, uid)
        if not st.get("enabled"):
            return
        off = _mail_off(c, owner_user)
        today = _mail_local_today(off)
        try:
            mine = set(_mail_find.my_addresses(c, uid) or [])
        except Exception:
            mine = set()
        try:
            mine.add((_mail_from_address_for(c, owner_user) or "").lower())
        except Exception:
            pass
        try:
            bulk = _mail_find.bulk_senders(c, uid)
        except Exception:
            bulk = set()
        for mid, auto in cand:
            m = _mailbox.get_mail(c, mid, uid)
            if not m:
                continue
            ok, why = _mailbox.autoreply_should(c, uid, m, today, mine, auto, bulk)
            if ok:
                _mailbox.autoreply_log(c, uid, m.get("from_email") or "", mid)
                todo.append(m)
    import html as _h
    for m in todo:
        subj = (st.get("subject") or "").strip() or ("[자동 회신] " + (m.get("subject") or ""))
        body = (st.get("body") or "").strip()
        try:
            res = _mail_send_core(owner_user, m.get("from_email") or "", "", "", subj, body,
                                  "<div>" + _h.escape(body).replace("\n", "<br>") + "</div>", [], 0, [],
                                  extra_headers={"Auto-Submitted": "auto-replied", "X-Auto-Response-Suppress": "All", "Precedence": "auto_reply"})
            if not res.get("ok"):
                print("[MAIL-AUTOREPLY] 못 보냄(user=%s, mail=%s): %s" % (uid, m.get("id"), (res.get("message") or "")[:120]), flush=True)
        except Exception as e:
            print("[MAIL-AUTOREPLY ERR] %s" % str(e)[:160], flush=True)


# ─── 🔒 메일 읽기 전용 조회 (AI 비서 '락아' 용 · 대표 지시 2026-11-09) ──────────
# 목표: 락아가 메일을 확인해도 **읽음·안읽음 상태와 읽은 시각이 바뀌지 않는다.**
#       대표가 기존 화면에서 직접 열 때는 지금처럼 읽음 처리된다(화면 라우트는 건드리지 않음).
# ⭐설계: 새 조회 로직을 짜지 않는다. mail_store 의 get_mail/list_*/get_attachment 는 이미
#        "순수 SELECT + 소유권을 SQL 에 박은" 함수다. 화면 라우트가 그 뒤에 따로 부르던
#        mark_read 를 **부르지 않는** 경로를 둘 뿐이다.
#        (읽은 뒤 다시 안읽음으로 되돌리는 방식은 쓰지 않는다 — 대표 지시)
# 🔴 이 구역에서 절대 부르지 않는 것: mark_read · set_read · 삭제/휴지통/복구/분류 변경 ·
#    bump_large_download (/dl/{token} 은 다운로드 횟수를 올린다 → 읽기 전용에 쓰면 안 된다)
# 🔴 소유자는 **서버 세션**으로만 정한다. 요청이 보낸 사용자 번호는 절대 믿지 않는다.
# 🔴 list_attachments 에는 user_id 인자가 없다 → 반드시 get_mail 로 소유권을 먼저 확인한 뒤에만 부른다.
# ⛔ 로그에 메일 내용·주소를 남기지 않는다(번호만).

def _mail_ro_user(req: Request):
    """읽기 전용 조회를 허용할 로그인 사용자. 아니면 None. 판정은 mail_store.ro_allowed 한 곳."""
    u = get_user(req)
    if not u:
        return None
    return u if _mailbox.ro_allowed(dict(u)) else None


@app.get("/api/mail/ro/list")
async def mail_ro_list(req: Request, box: str = "inbox", q: str = "", unread: int = 0,
                       df: str = "", dt: str = "", limit: int = 50, offset: int = 0):
    """메일 목록·검색(읽기 전용). box=inbox|sent|drafts|trash. 상태를 바꾸지 않는다."""
    u = _mail_ro_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "권한이 없습니다."}, 403)
    try:
        limit = max(1, min(int(limit or 50), 200))
        offset = max(0, int(offset or 0))
    except Exception:
        limit, offset = 50, 0
    box = (box or "inbox").strip().lower()
    with db_session() as c:
        if box == "inbox":
            rows = _mailbox.list_inbox(c, u["id"], q=q, unread=bool(unread),
                                       date_from=df, date_to=dt, limit=limit, offset=offset)
        elif box == "sent":
            rows = _mailbox.list_sent(c, u["id"], q=q, limit=limit, offset=offset)
        elif box == "drafts":
            rows = _mailbox.list_drafts(c, u["id"])
        elif box == "trash":
            rows = _mailbox.list_trash(c, u["id"], limit=limit)
        else:
            return JSONResponse({"ok": False, "message": "box 는 inbox/sent/drafts/trash 중 하나"}, 400)
    return JSONResponse({"ok": True, "box": box, "count": len(rows), "mails": rows})


@app.get("/api/mail/ro/mail/{mail_id:int}")
async def mail_ro_detail(req: Request, mail_id: int, html: int = 0):
    """메일 1통 상세(읽기 전용) — mark_read 를 부르지 않는다. 기본은 본문 텍스트."""
    u = _mail_ro_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "권한이 없습니다."}, 403)
    with db_session() as c:
        m = _mailbox.get_mail(c, mail_id, u["id"])          # 소유권을 SQL 에서 강제
        if not m:
            return JSONResponse({"ok": False, "message": "메일을 찾을 수 없습니다."}, 404)
        atts = _mailbox.list_attachments(c, mail_id)        # 위에서 소유권 확인된 뒤에만
    out = {k: m.get(k) for k in ("id", "direction", "from_email", "from_name", "to_email",
                                 "cc", "subject", "category", "received_at",
                                 "is_read", "read_at", "is_starred")}
    out["body_text"] = m.get("body_text") or ""
    if html:
        out["body_html"] = _mailbox.strip_remote_refs(m.get("body_html") or "")
    out["attachments"] = atts
    return JSONResponse({"ok": True, "mail": out})


@app.get("/api/mail/ro/mail/{mail_id:int}/attachment/{att_id:int}")
async def mail_ro_attachment(req: Request, mail_id: int, att_id: int):
    """첨부 1건(읽기 전용) — 소유권 2겹 확인. 대용량 링크(/dl)의 횟수 증가 경로를 쓰지 않는다."""
    u = _mail_ro_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "권한이 없습니다."}, 403)
    with db_session() as c:
        m = _mailbox.get_mail(c, mail_id, u["id"])          # ① 메일 소유권
        if not m:
            return JSONResponse({"ok": False, "message": "메일을 찾을 수 없습니다."}, 404)
        ids = {int(a["id"]) for a in _mailbox.list_attachments(c, mail_id)}
        if int(att_id) not in ids:                          # ② 그 메일의 첨부가 맞는지
            return JSONResponse({"ok": False, "message": "첨부를 찾을 수 없습니다."}, 404)
        a = _mailbox.get_attachment(c, att_id, u["id"])     # ③ 첨부 소유권(JOIN) — 횟수 안 올림
    if not a or a.get("data") is None:
        return JSONResponse({"ok": False, "message": "첨부 내용이 없습니다."}, 404)
    import urllib.parse as _up
    fn = a.get("filename") or "attachment"
    return Response(content=a["data"], media_type=a.get("mime") or "application/octet-stream",
                    headers={"Content-Disposition": "attachment; filename*=UTF-8''" + _up.quote(fn),
                             "X-Content-Type-Options": "nosniff"})


# ─── KNK 대용량 첨부 (큰 파일 → NAS 업로드 + 다운로드 링크) ───────────
_WORKS_PUBLIC_BASE = "https://works.knknara.co.kr"
_LARGE_MAX = 500 * 1024 * 1024   # 1파일 최대 500MB


@app.post("/mail/large/upload")
async def mail_large_upload(req: Request):
    """대용량 첨부 1개 업로드 → NAS 보관 + 토큰 발급. (로그인 직원만)"""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인 필요"}, 401)
    import os as _os, shutil as _sh
    # 11-27 받기 전에 먼저 — 한 사람 하루 한도 · 서버 남은 공간(파일을 다 받은 뒤 거절하면 그사이 디스크를 씀)
    with db_session() as c:
        _dn, _db_ = _mailbox.large_today(c, u["id"])
    if _dn >= _mailbox.LARGE_DAY_MAX_N or _db_ >= _mailbox.LARGE_DAY_MAX_BYTES:
        return JSONResponse({"ok": False, "message": "오늘 올릴 수 있는 큰 파일 한도(하루 %d개 · %s)를 다 썼습니다. 내일 다시 올려 주세요."
                             % (_mailbox.LARGE_DAY_MAX_N, _mailbox.human_size(_mailbox.LARGE_DAY_MAX_BYTES))}, 429)
    try:
        from .mail_import_outlook import disk_state as _dstate
        if not _dstate().get("ok", True):
            return JSONResponse({"ok": False, "message": "서버 저장 공간이 모자라 지금은 큰 파일을 받을 수 없습니다. 관리자에게 알려 주세요."}, 507)
    except Exception as _e:
        print("[MAIL-LARGE] 남은 공간 확인 실패(그대로 받음): %s" % str(_e)[:120], flush=True)
    form = await req.form()
    f = form.get("file")
    if not f or not hasattr(f, "read"):
        return JSONResponse({"ok": False, "message": "파일이 없습니다."}, 400)
    fname = getattr(f, "filename", "") or "file"
    mime = getattr(f, "content_type", "") or "application/octet-stream"
    token = _mailbox.new_large_token()
    d = _mailbox.large_file_dir(token)
    _os.makedirs(d, exist_ok=True)
    path = _os.path.join(d, _mailbox.safe_filename(fname))
    size = 0
    try:
        with open(path, "wb") as out:
            while True:
                chunk = await f.read(1024 * 1024)
                if not chunk:
                    break
                size += len(chunk)
                if size > _LARGE_MAX:
                    out.close()
                    _sh.rmtree(d, ignore_errors=True)
                    return JSONResponse({"ok": False, "message": "파일이 너무 큽니다(최대 500MB)."}, 400)
                out.write(chunk)
    except Exception as e:
        _sh.rmtree(d, ignore_errors=True)
        return JSONResponse({"ok": False, "message": f"업로드 실패: {str(e)[:80]}"}, 500)
    with db_session() as c:
        exp = _mailbox.register_large_file(c, token=token, user_id=u["id"], filename=fname,
                                           mime=mime, path=path, size=size, expiry_days=30)
    return JSONResponse({"ok": True, "token": token, "filename": fname, "size": size,
                         "size_h": _mailbox.human_size(size),
                         "url": f"{_WORKS_PUBLIC_BASE}/dl/{token}", "expires_at": exp})


@app.get("/dl/{token}")
async def mail_large_download(req: Request, token: str):
    """대용량 첨부 다운로드 — 공개(로그인 불필요), 토큰·만료 검사. 외부 수신자도 받을 수 있음."""
    import os as _os
    def _msg(title, sub, code):
        return HTMLResponse(
            f"<!doctype html><meta charset=utf-8><div style='font-family:system-ui,sans-serif;"
            f"max-width:520px;margin:80px auto;text-align:center;color:#374151'>"
            f"<div style='font-size:40px'>📭</div><h2>{title}</h2>"
            f"<p style='color:#6b7280'>{sub}</p></div>", status_code=code)
    with db_session() as c:
        info = _mailbox.get_large_file(c, token)
        if not info:
            return _msg("다운로드할 수 없습니다", "링크가 잘못되었거나 파일이 삭제되었습니다.", 404)
        if info.get("expired"):
            return _msg("유효기간이 지났습니다", "이 다운로드 링크는 만료되었습니다(보낸 지 30일 경과).", 410)
        if not info.get("path") or not _os.path.exists(info["path"]):
            return _msg("파일을 찾을 수 없습니다", "파일이 서버에서 삭제되었을 수 있습니다.", 404)
        _mailbox.bump_large_download(c, token)
    import urllib.parse as _up
    fn = info["filename"] or "download"
    headers = {
        "Content-Disposition": f"attachment; filename*=UTF-8''{_up.quote(fn)}",
        "X-Content-Type-Options": "nosniff",
    }
    return FileResponse(info["path"], media_type=info["mime"] or "application/octet-stream",
                        headers=headers)


