@app.get("/admin/mail-send", response_class=HTMLResponse)
async def admin_mail_send_page(req: Request):
    """메일 보내기 설정 (admin/ceo) — 발송망(Cloudflare/AWS SMTP) 자격 + 보내는 주소."""
    u = require(req, ["admin", "ceo"])
    if not u:
        _au = get_user(req)
        return RedirectResponse(role_home(_au) if _au else "/login", 303)
    with db_session() as c:
        ready = _mail.system_send_ready(c, u["id"])
        fetch_mode = _mail.via_fetch_mode(c)
        fetch_st = _mail.fetch_send_status(c, u["id"])
        my_from = _mail_from_address_for(c, u)
        # 아래 '발송망(SMTP) 자격' 카드는 시스템 발송망만의 상태를 보여야 한다.
        # (ready 는 '내 받기 계정으로 보내기' 까지 합친 값이라, 그걸 쓰면 그 카드가
        #  설정이 비어 있어도 '발송 준비됨' 으로 보여 사람을 헷갈리게 한다.)
        relay_ready = _mail.get_send_config(c) is not None
        # ⭐「계정이 연결됐나」(fetch_st.ok)와 「내가 실제로 내 주소로 보내나」는 다른 물음이다.
        #   「고른 사람만」인데 내가 명단에 없으면, 계정이 연결돼 있어도 내 메일은
        #   시스템 발송망으로 나간다(_mail_from_address_for 가 그렇게 돌아간다).
        #   🔴2026-11-14: 대표가 본인을 빼고 저장했는데 화면이 초록으로 「지금 바로 쓸 수
        #   있습니다」라고 해서 「나는 계속 내 주소로 보낸다」고 믿으셨다. 그 거짓말을 없앤다.
        me_on_list = _mail.via_fetch_allowed(c, u["id"])
        me_via_on = me_on_list and bool(fetch_st.get("ok"))
        via_on = me_via_on
        # 명단 모드용 — 고를 수 있는 직원을 ⭐법인(본사/베트남) → 부서로 묶어서 넘긴다.
        # 화면은 KNK 공용 선택위젯(z886 대표 지시 규정)을 쓴다: 책갈피 + 검색 + 선택칩.
        # 🔴법인 구분의 단일 기준은 teams.entity (z747 — users.entity 는 신뢰하지 않는다).
        from . import mail_fetch as _mailfetch
        _mailfetch._ensure_table(c)
        fetch_uids = _mail.via_fetch_uids(c)
        _lang = (u.get("lang") or "ko")
        emp_groups = {"KOR": [], "VN": [], "ETC": []}
        _bucket = {}
        for _r in c.execute(
                "SELECT u.id, u.name, COALESCE(u.name_vi,'') AS name_vi, u.rank, u.team_id, "
                "       u.employee_no, t.name AS team_name, "
                "       COALESCE(t.display_order,999) AS t_ord, "
                "       COALESCE(t.entity,'KOR') AS t_ent, "
                "       (SELECT COUNT(*) FROM mail_fetch_accounts a "
                "          WHERE a.owner_user_id=u.id "
                "            AND COALESCE(a.password_enc,'')<>'') AS linked "
                "FROM users u LEFT JOIN teams t ON t.id=u.team_id "
                "WHERE COALESCE(u.is_active,1)=1 ORDER BY t_ord, t.name, u.name"):
            _d = dict(_r)
            _e = (str(_d.get("t_ent") or "KOR")).strip().upper()
            _e = "VN" if _e in ("VN", "VNM") else ("KOR" if _e in ("KOR", "KR", "KO") else "ETC")
            _team = (_d.get("team_name") or "부서 없음").strip() or "부서 없음"
            _key = (_e, _d.get("team_id"), _team)
            if _key not in _bucket:
                _bucket[_key] = {"team": _team, "members": [], "has_checked": False}
                emp_groups[_e].append(_bucket[_key])
            _uid = str(_d["id"])
            _bucket[_key]["members"].append({
                "id": _uid,
                "label": vname_full(_d, lang=_lang),
                "no": (_d.get("employee_no") or ""),
                "linked": bool(_d.get("linked")),
            })
            if _uid in fetch_uids:
                _bucket[_key]["has_checked"] = True
    return ctx(req, "admin_mail_send.html", user=u, active="admin",
               ready=ready, relay_ready=relay_ready, via_on=via_on,
               me_on_list=me_on_list, me_id=str(u["id"]), me_name=(u.get("name") or "나"),
               mail_key=_mail.mail_available(),
               cur_host=get_setting("mail_send_host", ""),
               cur_port=(get_setting("mail_send_port", "") or "465"),
               cur_user=get_setting("mail_send_user", ""),
               has_pass=bool(get_setting("mail_send_pass_enc", "")),
               cur_from=_mail_from_address(),
               fetch_mode=fetch_mode, fetch_st=fetch_st, my_from=my_from,
               emp_groups=emp_groups, fetch_uids=fetch_uids,
               cur_fetch_host=get_setting("mail_send_fetch_host", ""),
               cur_fetch_port=(get_setting("mail_send_fetch_port", "") or "465"),
               saved=(req.query_params.get("saved") == "1"))


@app.post("/admin/mail-send")
async def admin_mail_send_save(req: Request):
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    if not _mail.mail_available():
        return JSONResponse({"ok": False, "message": "메일 암호화 키(KNK_MAIL_KEY)가 서버에 없습니다. 전산담당자에게 .env 등록 요청."}, 400)
    form = await req.form()
    # ⭐화면에 폼이 둘(발송망 자격 / 내 받기 계정으로 보내기)이고 주소가 같다.
    #   section 으로 갈라야 한 폼을 저장할 때 다른 폼의 값이 빈 값으로 덮이지 않는다.
    section = (form.get("section") or "smtp").strip().lower()
    with db_session() as c:
        def _set_opt(k, v):
            c.execute("INSERT INTO app_settings(key, value) VALUES(?, ?) "
                      "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (k, v))
        if section == "via_fetch":
            vf = (form.get("via_fetch") or "off").strip().lower()
            if vf not in ("off", "one", "all", "list"):
                vf = "off"
            _set_opt("mail_send_via_fetch", vf)
            if vf == "one":
                _set_opt("mail_send_via_fetch_uid", str(u["id"]))
            if vf == "list":
                picked = [str(x).strip() for x in form.getlist("via_fetch_uids")
                          if str(x).strip().isdigit()]
                _set_opt("mail_send_via_fetch_uids", ",".join(sorted(set(picked), key=int)))
            _set_opt("mail_send_fetch_host", (form.get("fetch_host") or "").strip())
            _set_opt("mail_send_fetch_port", (form.get("fetch_port") or "465").strip())
        else:
            _mail.save_send_config(c, (form.get("host") or "").strip(),
                                   (form.get("port") or "465").strip(),
                                   (form.get("user") or "").strip(),
                                   (form.get("password") or "").strip())
            from_addr = (form.get("from_address") or "").strip()
            if from_addr:
                _set_opt("mail_from_address", from_addr)
    return RedirectResponse("/admin/mail-send?saved=1", 303)


