# =====================================================
# v5H226z58 (2026-05-12) — 자재 일괄 등록 (Excel)
# 라우터:
#   GET  /parts/import              → 업로드 폼 + 가이드
#   POST /parts/import              → 업로드 → 검증 → 미리보기 (dry_run)
#   POST /parts/import/apply        → 실제 INSERT 실행
#   GET  /parts/import/template.xlsx → 빈 템플릿 다운로드
# =====================================================
@app.get("/parts/import", response_class=HTMLResponse)
async def parts_import_page(req: Request):
    """일괄 등록 페이지 진입 — view 권한이면 페이지는 보이고, 실제 등록(POST)에서만 use 권한 확인.
       이래야 권한 부족 시 사용자에게 정확한 안내가 가능 (조용한 /home redirect 방지)."""
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_view_logistics(u):
        return RedirectResponse("/home", 303)
    # 쓰기 권한 여부 → 템플릿에서 안내 배너 표시용
    has_write = can_use_logistics(u)
    return ctx(req, "parts_import.html", user=u, active="parts",
               result=None, mode="upload", has_write=has_write)


@app.post("/parts/import")
async def parts_import_submit(req: Request, file: UploadFile = File(...)):
    """엑셀 업로드 → 검증 + 미리보기 (dry_run=True). 실제 INSERT는 /apply 에서."""
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_use_logistics(u):
        return RedirectResponse("/home", 303)
    raw = await file.read()
    if not raw:
        return ctx(req, "parts_import.html", user=u, active="parts",
                   result={"error": "빈 파일입니다"}, mode="upload")
    if len(raw) > 10 * 1024 * 1024:
        return ctx(req, "parts_import.html", user=u, active="parts",
                   result={"error": "파일이 너무 큽니다 (10MB 제한)"}, mode="upload")
    fname = (file.filename or "upload.xlsx")
    if not fname.lower().endswith((".xlsx", ".xlsm")):
        return ctx(req, "parts_import.html", user=u, active="parts",
                   result={"error": "Excel 파일(.xlsx)만 지원합니다 (현재: " + fname + ")"},
                   mode="upload")

    # 임시 저장 → 파싱 → 결과 (DB INSERT 안 함)
    import tempfile, os, base64
    tmp_dir = tempfile.mkdtemp(prefix="parts_import_")
    tmp_path = os.path.join(tmp_dir, "upload.xlsx")
    with open(tmp_path, "wb") as f:
        f.write(raw)
    try:
        from .database import parts_bulk_import_excel as _pbi
        result = _pbi(tmp_path, dry_run=True, force_similar=False)
    except Exception as e:
        result = {"error": f"파싱 오류: {e}"}
    # 파일은 apply 단계에서 다시 필요 → base64로 form에 hidden 전달
    file_b64 = base64.b64encode(raw).decode("ascii") if not result.get("error") else ""
    try:
        os.remove(tmp_path)
        os.rmdir(tmp_dir)
    except Exception:
        pass
    return ctx(req, "parts_import.html", user=u, active="parts",
               result=result, mode="preview",
               file_b64=file_b64, filename=fname)


def _parts_import_verify_saved(raw_bytes):
    """대표규정(2026-07-28·§4 규칙47): 자재 일괄등록 '엑셀 원본 ↔ 저장값' 대조(읽기전용).
    ⛔세션 05(자재구매)의 저장 로직(parts_bulk_import_excel)은 건드리지 않는다 — dry_run=True 로 호출해 '파싱행'만
    얻고, 자재번호(part_no) 정확일치로 저장값과 비교(검증층만). 금액(매입가·마진 등 환율·산출 필드)은
    세션 05의 파서검증 영역이라 이 층에선 **저장 그대로 들어가는 텍스트 필드**(품명·규격·제작사·단위·통화)만 대조(거짓경고 방지).
    반환 {checked, ok, diff:[{row,name,field,excel,saved}], skipped, fields}."""
    out = {"checked": 0, "ok": True, "diff": [], "fields": "품명·규격·제작사·단위·통화"}
    import tempfile as _tf, os as _os
    _tmp = None
    try:
        _td = _tf.mkdtemp(prefix="parts_verify_")
        _tmp = _os.path.join(_td, "u.xlsx")
        with open(_tmp, "wb") as _f:
            _f.write(raw_bytes)
        from .database import parts_bulk_import_excel as _pbi
        pre = _pbi(_tmp, dry_run=True)   # 파싱만(DB 변경 0) — 저장 로직 재사용, 무접촉
    except Exception as _e:
        return {"checked": 0, "ok": True, "diff": [], "fields": out["fields"],
                "skipped": f"엑셀을 다시 열지 못했습니다({str(_e)[:60]})"}
    finally:
        try:
            if _tmp:
                _os.remove(_tmp); _os.rmdir(_os.path.dirname(_tmp))
        except Exception:
            pass
    if isinstance(pre, dict) and pre.get("error"):
        out["skipped"] = pre["error"]
        return out
    rows = (pre.get("preview") or []) if isinstance(pre, dict) else []

    def _s(v):
        return str(v).strip() if v not in (None, "") else ""

    def _add(idx, name, field, ex, sv):
        out["ok"] = False
        if len(out["diff"]) < 20:
            out["diff"].append({"row": idx, "name": str(name or "")[:24], "field": field,
                                "excel": ("" if ex is None else str(ex)), "saved": ("" if sv is None else str(sv))})

    _FIELDS = [("품명", "part_name"), ("규격", "spec"), ("제작사", "maker"),
               ("단위", "unit"), ("통화", "currency")]
    try:
        with db_session() as c:
            _cols = {r[1] for r in c.execute("PRAGMA table_info(parts)").fetchall()}
            for _idx, pr in enumerate(rows, 1):
                if pr.get("errors"):
                    continue
                d = pr.get("data") or {}
                _pno = _s(d.get("part_no"))
                if not _pno:
                    continue
                _cand = c.execute("SELECT * FROM parts WHERE part_no=?", (_pno,)).fetchall()
                if len(_cand) != 1:
                    continue   # 없거나 복수(모호) → 대조 보류(거짓경고 방지)
                _sd = dict(_cand[0]); out["checked"] += 1
                _nm = _s(d.get("part_name")) or _pno
                for _f, _k in _FIELDS:
                    if _k not in _cols:
                        continue
                    _ev = _s(d.get(_k))
                    if _ev and _ev != _s(_sd.get(_k)):
                        _add(_idx, _nm, _f, _ev, _s(_sd.get(_k)))
    except Exception as _e:
        out["error"] = str(_e)[:120]
    return out


@app.post("/parts/import/apply")
async def parts_import_apply(req: Request,
                              file_b64: str = Form(""),
                              filename: str = Form("upload.xlsx"),
                              force_similar: str = Form("0")):
    """미리보기 후 사용자 confirm → 실제 INSERT 실행."""
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_use_logistics(u):
        return RedirectResponse("/home", 303)
    import base64, tempfile, os
    try:
        raw = base64.b64decode(file_b64 or "")
    except Exception:
        return ctx(req, "parts_import.html", user=u, active="parts",
                   result={"error": "파일 데이터 손상 — 다시 업로드해주세요"}, mode="upload")
    if not raw:
        return ctx(req, "parts_import.html", user=u, active="parts",
                   result={"error": "파일 데이터 없음 — 다시 업로드해주세요"}, mode="upload")
    tmp_dir = tempfile.mkdtemp(prefix="parts_import_apply_")
    tmp_path = os.path.join(tmp_dir, "upload.xlsx")
    with open(tmp_path, "wb") as f:
        f.write(raw)
    try:
        from .database import parts_bulk_import_excel as _pbi
        result = _pbi(tmp_path, dry_run=False, force_similar=(force_similar == "1"))
    except Exception as e:
        result = {"error": f"등록 오류: {e}"}
    try:
        os.remove(tmp_path)
        os.rmdir(tmp_dir)
    except Exception:
        pass
    # v5H226z98: 파싱/실행 오류는 import 페이지에 유지, 정상 완료 시 자재 목록으로 리다이렉트
    if result.get("error"):
        return ctx(req, "parts_import.html", user=u, active="parts",
                   result=result, mode="result", filename=filename)
    # 대표규정(2026-07-28·§4 규칙47): 확정 후 '엑셀 원본 ↔ 저장값' 대조(검증층만·저장 로직 무접촉).
    #   전엔 곧장 /parts 리다이렉트라 대조가 없었음 → 결과 화면에 ✅/⚠ 보여주고 '자재 목록으로' 링크.
    _vfy = None
    try:
        _vfy = _parts_import_verify_saved(raw)
    except Exception:
        _vfy = None
    return ctx(req, "parts_import.html", user=u, active="parts",
               result=result, mode="result", filename=filename, verify=_vfy)


# v5H226z648 (2026-06-25) — 검증결과 색칠 엑셀 다운로드 (구매팀 원본 정리용)
@app.post("/parts/import/marked-xlsx")
async def parts_import_marked_xlsx(req: Request,
                                    file_b64: str = Form(""),
                                    filename: str = Form("upload.xlsx")):
    """업로드한 엑셀에 검증 결과를 색칠해서 다운로드. 미리보기 단계에서 호출.
    행 색: 빨강=엑셀 내부 중복 / 노랑=DB 중복 / 주황=오류 / 연두=유사자재 / 흰=정상.
    헤더 끝에 [검증 결과 / 사유] 컬럼 추가."""
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_use_logistics(u):
        return RedirectResponse("/home", 303)
    import base64, tempfile, os
    try:
        raw = base64.b64decode(file_b64 or "")
    except Exception:
        return RedirectResponse("/parts/import", 303)
    if not raw:
        return RedirectResponse("/parts/import", 303)
    tmp_dir = tempfile.mkdtemp(prefix="parts_import_mark_")
    tmp_path = os.path.join(tmp_dir, "upload.xlsx")
    with open(tmp_path, "wb") as f:
        f.write(raw)
    try:
        from .database import parts_bulk_import_export_xlsx as _exp
        xlsx_bytes, info = _exp(tmp_path)
    except Exception as e:
        xlsx_bytes, info = None, {"error": f"생성 실패: {e}"}
    finally:
        try:
            os.remove(tmp_path)
            os.rmdir(tmp_dir)
        except Exception:
            pass
    if not xlsx_bytes:
        return ctx(req, "parts_import.html", user=u, active="parts",
                   result={"error": (info or {}).get("error", "검증결과 엑셀 생성 실패")},
                   mode="upload")
    base_name = (filename or "upload.xlsx").rsplit(".", 1)[0] or "upload"
    dl_name = f"{base_name}_검증결과.xlsx"
    from urllib.parse import quote
    return Response(
        content=xlsx_bytes,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={
            "Content-Disposition": (
                'attachment; filename="marked.xlsx"; '
                f"filename*=UTF-8''{quote(dl_name)}"
            )
        },
    )


