# ── 매출·영업 홈 (신규 · 2026-04-21 도메인 분리) ──────────────
@app.get("/sales", response_class=HTMLResponse)
async def sales_dashboard(request: Request):
    """매출·영업 센터 (프로젝트·관리코드·고객사·수주·매출 KPI)"""
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    # Plan Y S1 회귀 #2: /sales 는 can_use_sales (도메인 분리). /logistics 와 권한 독립
    if not can_view_sales(u):
        return RedirectResponse("/home?no_perm=sales", 303)   # z1191x: 말없이 돌려보내지 않는다(chrome.html 이 안내)
    proj_stats = _logi.projects_count_logi()
    # 매출 KPI (Victor sales 핸들러와 동일 로직)
    today = date.today()
    ym = today.strftime("%Y-%m")
    year = today.year
    # v5H226z925 (대표 지시): 매출 3지표(수주매출·진행매출·최종매출) + 기간(연간/분기별/월간)
    qp = request.query_params
    _sy = (qp.get("year") or "").strip()
    sel_year = _sy if (_sy.isdigit() and len(_sy) == 4) else str(year)
    mode = (qp.get("mode") or "year").strip().lower()
    if mode not in ("year", "quarter", "month"):
        mode = "year"
    _q = (qp.get("q") or "").strip()
    sel_q = _q if _q in ("1", "2", "3", "4") else str((today.month - 1) // 3 + 1)
    _m = (qp.get("m") or "").strip()
    sel_m = _m if (_m.isdigit() and 1 <= int(_m) <= 12) else str(today.month)
    # 세금계산서 차수 발행액(단일소스) — 자체 db_session 열므로 아래 with 밖에서 호출
    oi_map, _pi = _board_tax_oi_map()
    with db_session() as c:
        rates = _fx_load_rates(c)   # z900: 월 기준환율(각 기준월 원화 환산)
        s3 = _sales_3way(c, rates, oi_map, mode, sel_year, sel_q, sel_m)
        s3["biz_merged"] = _z179_biz_merged(s3.get("biz_rows"))   # z1191z179: 화면 사업부 줄(소모품 = 그 사업부 안 「└ 소모품」)
        s3["od_fb181"] = _z181_od_fb(c, s3.get("sel_year"), mode, sel_q, sel_m)   # z1191z181 ⑤: 처음 등록 발주일로 센 수주(계산 그대로 · 화면에 밝힘)
        open_proj = _z40_open_projects(c)   # z1191z40: 진행 프로젝트 = 출하 전 품목이 남은 프로젝트(+ 목록 창)
        # 최근 프로젝트 — 참고 목록(그 프로젝트의 계약금액을 원화 환산해 표시)
        _miss = set()
        recent = [dict(r) for r in c.execute(
            """SELECT id, mgmt_code, name, customer_name, customer_id, stage, order_amount,
                      order_date, due_date, biz_div, currency
               FROM projects
               WHERE mgmt_code IS NOT NULL AND mgmt_code != ''
                 AND COALESCE(is_archived,0)=0
               ORDER BY id DESC LIMIT 10""").fetchall()]
        for d in recent:
            _ref = ((d.get("order_date") or d.get("due_date") or "") or "")[:7]   # z1191z115: 발주 달 먼저
            d["amount_krw_disp"] = _fx_to_krw(rates, d.get("order_amount"),
                                              d.get("currency"), _ref, _miss)
        # z1191z104 (대표 11-22): 원래 통화로 크게 + 「≈ ₩」 작게(마우스 → 몇 월 기준환율·얼마).
        #   숫자 = 프로젝트 상세 「수주액」과 같게: 수주가 있으면 수주 합계(각 수주 발주 달 기준환율 · z1191z115), 없으면 프로젝트 금액.
        _ids104 = [d["id"] for d in recent]
        _so104 = {}
        _cu161 = {}   # z1191z161: {프로젝트: [수주 1차 고객사 …]}
        if _ids104:
            for _r104 in c.execute(
                    "SELECT o.project_id, o.total_amount, o.currency, o.due_date, o.order_date, "
                    "COALESCE((SELECT COALESCE(NULLIF(TRIM(cu.alias),''), NULLIF(TRIM(cu.name),'')) FROM customers cu "
                    "WHERE cu.id=o.customer_id), '') FROM orders o "
                    "WHERE o.project_id IN (%s) AND COALESCE(o.status,'')<>'CANCELLED' "   # z1191z161: 취소 수주 제외
                    "ORDER BY o.id" % ",".join("?" * len(_ids104)), _ids104).fetchall():
                _so104.setdefault(_r104[0], []).append(
                    {"total_amount": _r104[1], "currency": _r104[2], "due_date": _r104[3], "order_date": _r104[4]})
                _l161 = _cu161.setdefault(_r104[0], [])
                _n161 = _r104[5] or Z161_CUST_TBD
                if _n161 not in _l161:
                    _l161.append(_n161)
        for d in recent:
            # z1191z161 (대표 11-26): 고객 = 수주 1차 고객사(여럿이면 「외 N곳」) · 금액 = 살아 있는 수주 합 · 수주가 없으면 「—」
            #   (관리번호 금액·고객은 처음 등록 때 값이라 쓰지 않는다)
            d["custs_z161"] = _cu161.get(d["id"]) or []
            if _so104.get(d["id"]):
                _bd104 = _ccy_breakdown(_so104[d["id"]], "total_amount", "currency",
                                        date_keys=("order_date", "due_date"), rates=rates)   # z1191z115: 발주 달
                d["fx_bd_z104"] = _bd104
                d["fx_show_z104"] = any(abs(float(x["total"] or 0)) >= 0.005 for x in _bd104["by_ccy"])
            else:
                d["fx_bd_z104"] = None
                d["fx_show_z104"] = False
    sales_kpi = {
        "recent": recent,
        "ym": ym, "year": year,
    }
    # 연도 선택 옵션 — 데이터에 있는 연도 + 최근 3년 + 선택 연도(멱등)
    year_span = sorted(set(s3.get("year_choices") or [])
                       | {str(year), str(year - 1), str(year - 2), str(sel_year)},
                       reverse=True)
    return ctx(request, "sales_home.html",
               user=u, active="sales",
               proj_stats=proj_stats, sales_kpi=sales_kpi,
               s3=s3, year_span=year_span, open_proj=open_proj, today_iso=today.isoformat())


# ── z1191z75 매출영업센터 「📊 한눈에 보기」 (대표 2026-11-19) ─────────────────────────────────────────
#   「숫자로만 되어 있어 읽기가 불편하고 한눈에 안 들어온다 · 지금 페이지는 그냥 두고 책갈피로 한 장 더 · 그래프로 누구나 쉽게」
#   숫자 = 매출 홈과 같은 _sales_3way(같은 기간 · 같은 줄) — 따로 다시 세지 않는다(두 화면 합계가 늘 같게).
#   금액은 「억 · 만」으로 줄여 보이고, 정확한 원 단위는 마우스를 올리면(title) 보인다.
_Z75_METRICS = (("prog", "진행매출", "출하(납품)한 금액", "#15803d", "출하일(없으면 납기) 기준"),   # z1191z161: 실제 계산 = 출하 표시 날 → 없으면 납기
                ("order", "수주매출", "주문(발주) 받은 금액", "#2563eb", "발주일 기준"),
                ("final", "최종매출", "세금계산서 발행한 금액", "#b45309", "세금계산서 발행일 기준"))


def _z75_won(v):
    """금액을 한눈에: ₩368.0억 · ₩4,900만 · ₩0. z1191z103 (대표 11-22 「금액 앞에는 화폐단위가 항상」): 앞에 ₩."""
    try:
        v = float(v or 0)
    except (TypeError, ValueError):
        v = 0.0
    a = abs(v)
    if a >= 1e8:
        return "₩%s억" % "{:,.1f}".format(v / 1e8)
    if a >= 1e4:
        return "₩%s만" % "{:,.0f}".format(v / 1e4)
    if a < 0.5:
        return "₩0"
    return "₩%s" % "{:,.0f}".format(v)


# ── z1191z104 (대표 11-22 「원화에 마우스 포인트 올리면 적용 환율이 언제 기준환율이고 얼마로 적용됐는지」) ──
#   외화 금액 = 원래 통화로 크게 + 「≈ ₩」 작게. 「≈ ₩」에 마우스를 올리면 아래 글이 뜨고, 치우면 사라진다
#   (화면 쪽 = 공용 _v5_partials/knk_fx_tip.html · 금액 묶음 = _v5_partials/knk_fx_amt.html).
#   ⭐ 환율은 월 기준환율 한 벌(대표규정 §4 규칙48 · _fx_pick 대체 규칙 그대로) — 다른 환율로 「≈ ₩」을 만들지 말 것.
_FX_BASIS_NAME_Z104 = {"due_date": "납기", "order_date": "발주", "expected_date": "입고 예정",
                       "last_so_date": "마지막 수주", "date": "매출"}


def _fx_basis_txt_z104(date_keys):
    """기준 날짜 이름: ('due_date','order_date') → 「납기 달 기준(납기가 없으면 발주 달)」."""
    names = [_FX_BASIS_NAME_Z104.get(k, k) for k in (date_keys or ())]
    if not names:
        return ""
    s = "%s 달 기준" % names[0]
    if len(names) > 1:
        s += "(없으면 %s 달)" % " → ".join(names[1:])
    return s


def _fx_ym_txt_z104(ym):
    try:
        return "%s년 %d월" % (ym[:4], int(ym[5:7]))
    except (TypeError, ValueError, IndexError):
        return str(ym or "?")


def _fx_rate_num_z104(rate):
    r = float(rate or 0)
    return "{:,.2f}".format(r) if r >= 1 else "{:,.4f}".format(r)


def _fx_unit_txt_z104(ccy, rate):
    """1 USD = ₩1,487.39 · 작은 통화는 입력 단위 그대로(100 VND = ₩5.41)."""
    c = str(ccy or "").upper()
    unit = FX_INPUT_UNIT.get(c, 1)
    return "%s %s = ₩%s" % ("{:,}".format(unit), c, _fx_rate_num_z104(float(rate or 0) * unit))


def _fx_tip_z104(bd, basis=""):
    """「≈ ₩」 풍선 글(여러 줄). 한 건이면 「몇 월 기준환율 · 1 USD = ₩… · 계산식」, 여러 건이면 달마다 한 줄."""
    if not bd:
        return ""
    used = bd.get("used") or []
    if bd.get("krw") is None:
        miss = ", ".join("%s %s" % (m[0], _fx_ym_txt_z104(m[1])) for m in (bd.get("missing") or []))
        return "기준환율이 없어 원화로 바꾸지 못했습니다" + (" — " + miss if miss else "") + "\n(관리 → 월 기준환율에서 넣으면 바로 반영)"
    if not used:
        return ""
    lines = []

    def _fb(e):
        req = [r for r in (e.get("req") or []) if r != e["ym"]]
        if not req:
            return ""
        if req == [""]:
            return "※ 날짜가 비어 가장 이른 달(%s) 환율로 계산" % _fx_ym_txt_z104(e["ym"])
        return "※ %s 기준환율이 아직 없어 %s 환율로 계산" % (
            "·".join(_fx_ym_txt_z104(r) for r in req if r), _fx_ym_txt_z104(e["ym"]))

    if not bd.get("mixed") and len(used) == 1 and used[0]["cnt"] == 1:
        e = used[0]
        lines.append("%s 기준환율 적용%s" % (_fx_ym_txt_z104(e["ym"]), (" · " + basis) if basis else ""))
        lines.append(_fx_unit_txt_z104(e["ccy"], e["rate"]))
        lines.append("%s × %s = %s" % (_fmt_money(e["amt"], e["ccy"]), _fx_rate_num_z104(e["rate"]),
                                       _fmt_money(e["krw"], "KRW")))
        if _fb(e):
            lines.append(_fb(e))
    else:
        lines.append("건마다 그 달 기준환율로 바꾼 합계%s" % ((" · " + basis) if basis else ""))
        for e in used[:8]:
            lines.append("%s · %s · %d건 %s → %s" % (_fx_ym_txt_z104(e["ym"]), _fx_unit_txt_z104(e["ccy"], e["rate"]),
                                                    e["cnt"], _fmt_money(e["amt"], e["ccy"]), _fmt_money(e["krw"], "KRW")))
            if _fb(e):
                lines.append("   " + _fb(e))
        if len(used) > 8:
            lines.append("… 외 %d개 달" % (len(used) - 8))
        for _b in (bd.get("by_ccy") or []):   # 통화가 섞이면 원화 건은 그대로 더한다는 것도 적는다
            if _b["currency"] == "KRW" and _b["total"]:
                lines.append("원화 %d건 %s — 그대로 더함" % (_b["cnt"], _fmt_money(_b["total"], "KRW")))
        lines.append("합계 ≈ %s" % _fmt_money(bd["krw"], "KRW"))
    lines.append("(월 기준환율 = 관리 → 월 기준환율)")
    return "\n".join(lines)


tpl.env.globals["won_short_z104"] = _z75_won


def _z75_glance(s3, lines, ymd, mode, sel_year, sel_q, sel_m, today):
    """한눈에 보기 화면 자료 — 지표(진행·수주·최종)마다 월별 · 사업부 · 고객사 · 연도별."""
    sel = str(sel_year)
    kpi = s3.get("kpi") or {}
    out = []
    for key, label, desc, color, basis in _Z75_METRICS:
        total = float(kpi.get(key) or 0)
        # 월별(고른 해 1~12월) — 고른 기간 밖의 달은 흐리게
        md = (ymd or {}).get(key, {})
        months, acc = [], 0.0
        for mm in range(1, 13):
            v = float(md.get("%s-%02d" % (sel, mm), 0.0))
            acc += v
            future = (sel == str(today.year) and mm > today.month) or (int(sel) > today.year if sel.isdigit() else False)
            months.append({"m": mm, "v": v, "txt": _z75_won(v), "acc": acc, "acc_txt": _z75_won(acc),
                           "in": _sales_period_ok(mm, mode, sel_q, sel_m), "future": future})
        mmax = max([x["v"] for x in months] + [0.0])
        for x in months:
            x["h"] = round(100.0 * x["v"] / mmax, 1) if mmax > 0 and x["v"] > 0 else 0
        done = [x for x in months if x["v"] > 0]
        best = max(done, key=lambda x: x["v"]) if done else None
        # 사업부(큰 순 · 0 은 뺀다)
        # z1191z179: 소모품 = 그 사업부 안(아래 「└ 소모품」 줄로 금액)
        brows = [b for b in (s3.get("biz_merged") or s3.get("biz_rows") or []) if float(b.get(key) or 0) > 0]
        brows = sorted(brows, key=lambda b: -float(b.get(key) or 0))
        bmax = max([float(b.get(key) or 0) for b in brows] + [0.0])
        biz = [{"biz": b["biz"], "label": b["label"], "v": float(b[key]), "txt": _z75_won(b[key]),
                "pct": (100.0 * float(b[key]) / total) if total else 0.0,
                "w": round(100.0 * float(b[key]) / bmax, 1) if bmax else 0,
                "subs": [{"biz": x["biz"], "label": x["label"], "v": float(x.get(key) or 0), "txt": _z75_won(x.get(key) or 0),
                          "pct": (100.0 * float(x.get(key) or 0) / total) if total else 0.0}
                         for x in (b.get("subs") or []) if abs(float(x.get(key) or 0)) >= 0.5]} for b in brows]
        # 고객사(등록명 합산 · 종사업장은 아래 작은 글) — 매출 홈 합계와 같은 줄
        cu, ch = {}, {}
        for x in (lines or []):
            if x[0] != key:
                continue
            cu[x[2]] = cu.get(x[2], 0.0) + x[3]
            if len(x) > 5 and x[5]:
                _c = ch.setdefault(x[2], {})
                _c[x[5]] = _c.get(x[5], 0.0) + x[3]
        cs = sorted([(n, v) for n, v in cu.items() if abs(v) >= 0.5], key=lambda t: (-t[1], t[0]))
        top, rest = cs[:7], cs[7:]
        cmax = max([v for _n, v in top] + [0.0])
        cust = [{"name": n, "v": v, "txt": _z75_won(v), "pct": (100.0 * v / total) if total else 0.0,
                 "w": round(100.0 * v / cmax, 1) if cmax > 0 and v > 0 else 0,
                 "kids": [{"name": k, "txt": _z75_won(kv)} for k, kv in sorted(ch.get(n, {}).items(), key=lambda t: (-t[1], t[0]))]}
                for n, v in top]
        rest_v = sum(v for _n, v in rest)
        # 연도별
        yrs = sorted([{"year": y["year"], "v": float(y.get(key) or 0)} for y in (s3.get("years") or [])], key=lambda y: y["year"])
        ymax = max([y["v"] for y in yrs] + [0.0])
        for y in yrs:
            y["txt"] = _z75_won(y["v"])
            y["h"] = round(100.0 * y["v"] / ymax, 1) if ymax > 0 and y["v"] > 0 else 0
            y["sel"] = (str(y["year"]) == sel)
        # 한 줄 요약
        bits = []
        if biz:
            bits.append("사업부 1위 %s %d%%" % (biz[0]["label"].split(" ", 1)[-1], round(biz[0]["pct"])))
        if cust:
            bits.append("고객사 1위 %s %d%%" % (cust[0]["name"], round(cust[0]["pct"])))
        out.append({"key": key, "label": label, "desc": desc, "color": color, "basis": basis,
                    "total": total, "txt": _z75_won(total),
                    "so": int(kpi.get("%s_so" % key) or 0), "co": int(kpi.get("%s_co" % key) or 0),
                    "months": months, "best": best, "avg_txt": _z75_won(sum(x["v"] for x in done) / len(done)) if done else "0",
                    "n_done": len(done),
                    "biz": biz, "cust": cust, "rest_n": len(rest), "rest_txt": _z75_won(rest_v),
                    "rest_pct": (100.0 * rest_v / total) if total else 0.0, "n_cust": len(cs),
                    "years": yrs, "summary": " · ".join(bits)})
    return out


@app.get("/sales/glance", response_class=HTMLResponse)
async def sales_glance_page(request: Request):
    """z1191z75: 매출영업센터 「📊 한눈에 보기」(읽기만) — 매출 홈과 같은 숫자를 그래프로."""
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_view_sales(u):
        return RedirectResponse("/home?no_perm=sales", 303)
    qp = request.query_params
    mode, sel_year, sel_q, sel_m = _z45_period(qp)
    view = (qp.get("v") or "prog").strip()
    if view not in ("prog", "order", "final"):
        view = "prog"
    today = date.today()
    oi_map, _pi = _board_tax_oi_map()
    lines, ymd = [], {}
    with db_session() as c:
        rates = _fx_load_rates(c)
        if mode == "year":
            s3 = _sales_3way(c, rates, oi_map, mode, sel_year, sel_q, sel_m, detail=lines, ym=ymd)
        else:   # 월별 그래프는 늘 그해 1~12월(고른 기간은 진하게)
            s3 = _sales_3way(c, rates, oi_map, mode, sel_year, sel_q, sel_m, detail=lines)
            _sales_3way(c, rates, oi_map, "year", sel_year, sel_q, sel_m, ym=ymd)
        open_proj = _z40_open_projects(c)
        s3["od_fb181"] = _z181_od_fb(c, s3.get("sel_year"), mode, sel_q, sel_m)   # z1191z181 ⑤
    s3["biz_merged"] = _z179_biz_merged(s3.get("biz_rows"))   # z1191z179
    G = _z75_glance(s3, lines, ymd, mode, sel_year, sel_q, sel_m, today)
    _late = [p for p in (open_proj.get("projects") or []) if p.get("due") and p["due"] < today.isoformat()]
    year_span = sorted(set(s3.get("year_choices") or [])
                       | {str(today.year), str(today.year - 1), str(today.year - 2), str(sel_year)}, reverse=True)
    return ctx(request, "sales_glance.html", user=u, active="sales",
               s3=s3, G=G, view=view, open_proj=open_proj, n_late=len(_late),
               soon=(open_proj.get("projects") or [])[:5], today_iso=today.isoformat(), year_span=year_span)


# ── z1191z45 매출 홈 깊이 보기 (대표 2026-11-17) ─────────────────────────────────────────
#   「사업부별 매출」 사업부 → 고객사별 수주·진행·최종 · 「TOP 5 고객사」 고객사 → 수주(소모품 발주)별.
#   숫자 = _sales_3way 가 매출 홈 합계에 더한 바로 그 줄(detail) — 따로 다시 세지 않는다(합계가 어긋나지 않게).
def _z45_period(qp):
    """매출 홈(/sales)과 같은 기간 읽기 — mode·year·q·m."""
    today = date.today()
    _sy = (qp.get("year") or "").strip()
    sel_year = _sy if (_sy.isdigit() and len(_sy) == 4) else str(today.year)
    mode = (qp.get("mode") or "year").strip().lower()
    if mode not in ("year", "quarter", "month"):
        mode = "year"
    _q = (qp.get("q") or "").strip()
    sel_q = _q if _q in ("1", "2", "3", "4") else str((today.month - 1) // 3 + 1)
    _m = (qp.get("m") or "").strip()
    sel_m = _m if (_m.isdigit() and 1 <= int(_m) <= 12) else str(today.month)
    return mode, sel_year, sel_q, sel_m


def _z45_drill(c, lines, biz, cust, c2=""):
    """detail 줄 → 깊이 보기 표. biz·cust 로 거른 뒤
       cust 없으면 고객사별 [{cust, order, prog, final, n}] · cust 있으면 수주별 [{kind, code, so, …}] + 사업부별 소계."""
    # z1191z73: 줄 = (지표, 사업부, 등록명, 원화, 수주 열쇠, 종사업장 시스템명|None) · cust 는 등록명(합산) 또는 시스템명(그 사업장만)
    _bset = SALES3_BIZ_GRP.get(biz, (biz,))   # z1191z179: TA = 검사기 + 소모품(검사기)
    sel = [x for x in lines if (not biz or x[1] in _bset) and (not cust or x[2] == cust or (len(x) > 5 and x[5] == cust))]
    if c2 and cust:
        # z1191z170 (대표 11-27 「2차 고객사 수주건수를 클릭하면 어떤 수주건인지」): 그 2차가 적힌 수주만 · 금액 = 그 수주의 2차 몫
        #   (매출 홈 TOP5 「└ 2차」 줄과 같은 숫자 — 한 수주에 2차가 여럿이면 대수로 나눈 몫)
        _s2 = []
        for x in sel:
            _parts = [w for n, w in (x[6] if len(x) > 6 else ()) if n == c2]
            if not _parts:
                continue
            _w = sum(_parts)
            _s2.append((x[0], x[1], x[2], _w, x[4], (x[5] if len(x) > 5 else None), ((c2, _w),)))
        sel = _s2
    tot = {"order": 0.0, "prog": 0.0, "final": 0.0}
    for x in sel:
        tot[x[0]] += x[3]
    def _c2add(acc, x):   # z1191z161: 2차 몫(x[6] = ((이름, 원화), …)) 모으기 — 2차가 빈 수주는 몫이 없다
        for _n2, _w2 in (x[6] if len(x) > 6 else ()):
            q2 = acc.setdefault(_n2, {"name": _n2, "order": 0.0, "prog": 0.0, "final": 0.0, "sos": set()})
            q2[x[0]] += _w2
            if x[4]:
                q2["sos"].add(x[4])

    def _c2rows(acc):
        out = sorted(acc.values(), key=lambda q: (-q["prog"], -q["order"], -q["final"], q["name"]))
        for q in out:
            q["n"] = len(q.pop("sos"))
        return out
    if not cust:
        g = {}
        for x in sel:
            m, nm, k, sok = x[0], x[2], x[3], x[4]
            ch = x[5] if len(x) > 5 else None
            r = g.setdefault(nm, {"cust": nm, "order": 0.0, "prog": 0.0, "final": 0.0, "sos": set(), "kids": {}, "c2acc": {}})
            r[m] += k
            if sok:
                r["sos"].add(sok)
            _c2add(r["c2acc"], x)
            if ch:
                kd = r["kids"].setdefault(ch, {"cust": ch, "order": 0.0, "prog": 0.0, "final": 0.0, "sos": set()})
                kd[m] += k
                if sok:
                    kd["sos"].add(sok)
        rows = sorted(g.values(), key=lambda r: (-r["prog"], -r["order"], -r["final"], r["cust"]))
        for r in rows:
            r["n"] = len(r.pop("sos"))
            kids = sorted(r.pop("kids").values(), key=lambda q: (-q["prog"], -q["order"], -q["final"], q["cust"]))
            for q in kids:
                q["n"] = len(q.pop("sos"))
            r["children"] = kids
            r["c2"] = _c2rows(r.pop("c2acc"))   # z1191z161: 「└ 2차」 줄
        return {"kind": "cust", "rows": rows, "tot": tot}
    g, bz, c2all = {}, {}, {}
    for x in sel:
        m, b, k, sok = x[0], x[1], x[3], x[4]
        key = sok or ("?", "", "")
        r = g.setdefault(key, {"kind": key[0], "code": key[1], "so": key[2], "biz": b,
                               "order": 0.0, "prog": 0.0, "final": 0.0, "c2set": []})
        r[m] += k
        _c2add(c2all, x)   # z1191z161: 이 고객사의 2차별 몫
        for _n2, _w2 in (x[6] if len(x) > 6 else ()):
            if _n2 not in r["c2set"]:
                r["c2set"].append(_n2)
        s = bz.setdefault(b, {"biz": b, "label": SALES3_BIZ_LABEL.get(b, b), "order": 0.0, "prog": 0.0, "final": 0.0})
        s[m] += k
    rows = list(g.values())
    # 화면에 보일 프로젝트·소모품 정보(읽기만) — 관리번호 · 수주번호로 찾는다
    codes = sorted({r["code"] for r in rows if r["kind"] == "S" and r["code"]})
    pmap = {}
    for i in range(0, len(codes), 400):
        part = codes[i:i + 400]
        for p in c.execute("SELECT id, mgmt_code, COALESCE(model_name,'') AS model, COALESCE(equip_name,'') AS equip, "
                           "COALESCE(name,'') AS pname FROM projects WHERE mgmt_code IN (%s) "
                           "ORDER BY COALESCE(is_archived,0), id" % ",".join("?" * len(part)), part).fetchall():
            pmap.setdefault(p["mgmt_code"], dict(p))
    sonos = sorted({r["so"] for r in rows if r["kind"] == "S" and r["so"]})
    omap = {}
    for i in range(0, len(sonos), 400):
        part = sonos[i:i + 400]
        # 발주일 = 수주매출이 쓰는 날짜와 같게(호기 → 수주 → 프로젝트 · 수주 발주일 칸이 빈 것이 운영에 있음)
        for o in c.execute("SELECT o.order_no AS order_no, MIN(" + SALES_DD_ORDER + ") AS od "
                           "FROM order_items oi JOIN orders o ON o.id=oi.order_id JOIN projects p ON p.id=o.project_id "
                           "WHERE o.order_no IN (%s) AND COALESCE(o.status,'')<>'CANCELLED' "
                           "GROUP BY o.order_no" % ",".join("?" * len(part)), part).fetchall():
            omap.setdefault(o["order_no"], o["od"] or "")
    conos = sorted({r["so"] for r in rows if r["kind"] == "C" and r["so"]})
    cmap = {}
    for i in range(0, len(conos), 400):
        part = conos[i:i + 400]
        for o in c.execute("SELECT id, co_no, COALESCE(model_name,'') AS model, COALESCE(equip_name,'') AS equip, "
                           "COALESCE(project_name,'') AS pname, COALESCE(order_date,'') AS od FROM consumable_orders "
                           "WHERE co_no IN (%s)" % ",".join("?" * len(part)), part).fetchall():
            cmap.setdefault(o["co_no"], dict(o))
    for r in rows:
        r["label"] = SALES3_BIZ_LABEL.get(r["biz"], r["biz"])
        if r["kind"] == "C":
            o = cmap.get(r["so"]) or {}
            r.update({"id": o.get("id"), "model": o.get("model", ""), "equip": o.get("equip", ""),
                      "pname": o.get("pname", ""), "od": (o.get("od") or "")[:10]})
        else:
            p = pmap.get(r["code"]) or {}
            r.update({"id": p.get("id"), "model": p.get("model", ""), "equip": p.get("equip", ""),
                      "pname": p.get("pname", ""), "od": (omap.get(r["so"]) or "")[:10]})
    for r in rows:
        r["c2"] = ", ".join(r.pop("c2set"))   # z1191z161: 이 수주의 2차(빈 수주 = 빈칸)
    rows.sort(key=lambda r: (-r["prog"], -r["order"], -r["final"], r["od"], r["so"]))
    order = {b: i for i, b in enumerate(SALES3_BIZ)}
    return {"kind": "so", "rows": rows, "tot": tot, "c2": _c2rows(c2all),
            "biz_sub": sorted(bz.values(), key=lambda s: order.get(s["biz"], 99))}


