                    _cq = _cqty.get(r.get("co_id"))
                    r["qty"] = int(_cq) if _cq else None   # 빈값=None → 카드 '수량 —'
                    _st = str(r.get("status") or "").upper()
                    r["status_ko"] = _CO_ST_KO.get(_st, ("진행중" if not _st else _st))
                    r["project_id"] = None
