            if len(_z51_lines) > 7:   # z1191z54: 이음 카드 상한 7줄(6 + 「… 외 N줄」 · 세션 10 v966) — 알림 글도 같은 줄
                _z51_lines = _z51_lines[:6] + ["… 외 %d줄" % (len(_z51_lines) - 6)]
            _z51_chg = []
