# z1191z51 (대표 2026-11-17 「2차 진행해」 · 2-3): 제작요청서 취소 발행 — 사유(필수) · 묶음이면 묶음 전체 · 받은 사람에게 「취소」로 다시 알림.
#   취소한 요청서는 고칠 수 없다(필요하면 새로 작성). 프로젝트 상태는 건드리지 않는다(사람이 판단).
@app.post("/project/{pid}/prod-request/{prid}/cancel")
async def prod_request_cancel(request: Request, pid: int, prid: int):
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_view_sales(u):
        return RedirectResponse(f"/project/{pid}", 303)
    form = await request.form()
    _reason = (form.get("cancel_reason") or "").strip()[:120]
    try:
        with db_session() as _c51:   # 구성원 줄로 들어와도 묶음 전체(대표 줄)
            _lr = _c51.execute("SELECT l.id, l.project_id FROM prod_requests m JOIN prod_requests l ON l.id=m.bundle_id "
                               "WHERE m.id=? AND m.project_id=? AND m.bundle_id IS NOT NULL AND m.bundle_id<>m.id "
                               "AND COALESCE(m.cancel_kind,'')<>'remove'", (prid, pid)).fetchone()
        if _lr:
            prid, pid = int(_lr[0]), int(_lr[1])
    except Exception as _e51:
        print(f"[z1191z51] 대표 줄 찾기 실패: {_e51}")
    _dest = f"/project/{pid}/prod-request/edit?prid={prid}"
    if not _reason:
        return RedirectResponse(_dest + "&prod_cxneed=1", 303)
    from datetime import datetime as _dt51
    _now = _dt51.now().strftime("%Y-%m-%d %H:%M")
    _by = u.get("name") or u.get("login_id") or "—"
    try:
        with db_session() as c:
            pr = c.execute("SELECT id, project_id, COALESCE(team_ids,'') AS team_ids, COALESCE(wt_team_ids,'') AS wt_team_ids, "
                           "COALESCE(user_ids,'') AS user_ids, COALESCE(cust_req,'') AS cust_req, COALESCE(note,'') AS note, "
                           "COALESCE(gist,'') AS gist, COALESCE(cancelled_at,'') AS cancelled_at, COALESCE(cancel_kind,'') AS cancel_kind "
                           "FROM prod_requests WHERE id=? AND project_id=?", (prid, pid)).fetchone()
            if not pr:
                return RedirectResponse(_dest + "&prod_upderr=1", 303)
            pr = dict(pr)
            if pr["cancelled_at"]:
                return RedirectResponse(_dest + "&prod_cancelled=1", 303)
            _z51_snapshot(c, prid, "base", None, None, None, None, None, None, None, None)
            c.execute("UPDATE prod_requests SET cancelled_at=?, cancel_reason=?, cancel_kind='cancel', cancelled_by_name=? "
                      "WHERE (id=? OR bundle_id=?) AND cancelled_at IS NULL", (_now, _reason, _by, prid, prid))
            _z51_snapshot(c, prid, "cancel", _reason, pr["cust_req"], pr["note"], pr["gist"], "취소", u.get("id"), _by, _now)
            _wt = [int(x) for x in pr["wt_team_ids"].replace(";", ",").split(",") if x.strip().isdigit() and int(x) > 0]
            _ui = [int(x) for x in pr["user_ids"].replace(";", ",").split(",") if x.strip().isdigit() and int(x) > 0]
            if not (_wt or _ui):   # 옛 기록: 저장된 부서로
                _wt = [int(x) for x in pr["team_ids"].replace(";", ",").split(",") if x.strip().isdigit() and int(x) > 0]
    except Exception as _e:
        print(f"[z1191z51] 제작요청서 취소 실패: {_e}")
        return RedirectResponse(_dest + "&prod_upderr=1", 303)
    _qs = ["prod_cxdone=1"]
    try:
        _res = _prod_request_notify_core(int(pid), pr["cust_req"], pr["note"], _wt, u, record=False, is_update=True,
                                         user_ids=_ui, prid=prid, gist=pr["gist"], cancel_reason=_reason)
        if _res.get("ok"):
            _qs += [f"prod_sent={_res.get('sent_to', 0)}", f"prod_dept={_res.get('dept_count', 0)}", f"prod_msg={_res.get('msg_sent', 0)}"]
            if _res.get("msg_err"):
                _qs.append("prod_msgerr=1")
        else:
            _qs.append("prod_renotifyerr=1")
    except Exception as _e:
        print(f"[z1191z51] 취소 알림 실패: {_e}")
        _qs.append("prod_renotifyerr=1")
    return RedirectResponse(_dest + "&" + "&".join(_qs), 303)


# v5H226z787 (대표 지시): 제작요청서 '신규 작성'(이 프로젝트에 추가 발행) — 상세의 3종 발주 버튼(검사기/소모품/수리) 대체.
#   프로젝트 서술필드 갱신(full_edit) + 새 제작요청서 1행 발행 + 관련 부서(사업부 자동 라우팅) 통보. 관리번호는 불변.
#   수정 라우트와 동일 필드 파싱 — 차이는 기존 행 UPDATE 대신 notify_core(record=True, is_update=False)로 신규 1행 INSERT.
@app.post("/project/{pid}/prod-request/new")
async def prod_request_new(request: Request, pid: int):
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_view_sales(u):   # 프로젝트 필드 갱신 + 전 부서 통보 → 영업·관리 권한자만
        return RedirectResponse(f"/project/{pid}", 303)
    form = await request.form()
    _cust_req = (form.get("cust_req") or "").strip()
    _note = (form.get("note") or "").strip()
    _server_path = (form.get("server_path") or "").strip()
    _model_name = (form.get("model_name") or "").strip()
    _engraving = (form.get("engraving") or "").strip()
    _full_edit = (form.get("full_edit") or "").strip() == "1"
    _pname = (form.get("name") or "").strip()
    _cc_name = (form.get("cc_name") or "").strip()
    _cc_position = (form.get("cc_position") or "").strip()
    _equip_name = (form.get("equip_name") or "").strip()
    _unit_qty_raw = (form.get("unit_qty") or "").strip()
    _due_date = (form.get("due_date") or "").strip()[:10]
    _ship_form = (form.get("shipment_form") or "").strip().upper()
    _biz_div_v = (form.get("biz_div") or "").strip().upper()
    _is_export_raw = (form.get("is_export") or "").strip()
    _customer_po = (form.get("customer_po") or "").strip()
    _order_date = (form.get("order_date") or "").strip()[:10]
    _cust_id_raw = (form.get("customer_id") or "").strip()
    _cust_name_v = (form.get("customer_name") or "").strip()
    _back = (form.get("_back") or "").strip()
    # v5H226z817 (대표 지시 ②): 새 작성 시 통보 대상 선택 — 안 고르면 None → 현행(사업부 전 부서). 개별 지정 시 그 사람에게만(z815 정밀저장·부서 확대 없음).
    _sel_team_ids = [int(x) for x in form.getlist("add_team_ids") if str(x).strip().isdigit() and int(x) > 0]
    _sel_user_ids = [int(x) for x in form.getlist("add_user_ids") if str(x).strip().isdigit() and int(x) > 0]
    _z49_bp = [int(x) for x in form.getlist("bundle_pids") if str(x).strip().isdigit() and int(x) > 0]   # z1191z49 묶음
    _z49_bm = (form.get("bundle_model") or "").strip()[:120]
    # z1191z48: 요지 · 이 요청서가 가리키는 수주(체크한 것 · 없으면 가장 최근 수주)
    _z48_gist = (form.get("gist") or "").strip()[:200]
    _z48_oids = [int(x) for x in form.getlist("order_ids") if str(x).strip().isdigit() and int(x) > 0]

    def _dest(qs):
        base = _back if (_back.startswith("/") and not _back.startswith("//")) else f"/project/{pid}"
        return base + ("&" if "?" in base else "?") + qs
    # z1191z48c (대표 2026-11-17 「관리번호 수주번호는 필수」): 아무것도 저장하기 전에 묻고, 안 되면 까닭과 함께 작성 화면으로 돌려보낸다
    with db_session() as _c48:
        _z48_nd = _z48_need(_c48, pid, _z48_oids, must_pick=True)
        _z49_bundle = _z49_pick_members(_c48, pid, _z49_bp, form)   # z1191z49: 함께 묶을 관리번호(같은 고객사 · 수주 있음)
    if _z48_nd:
        return RedirectResponse(_dest("new=1&prod_need=" + _z48_nd), 303)
    # z1191z50 (대표 2026-11-17 2차 · 작성 화면 편의): 발행 전에 붙인 참고 이미지 — 발행 뒤 새 요청서(묶음이면 대표 줄)에 붙인다
    _z50_files, _z50_skip = [], 0
    try:
        for _imf in form.getlist("pr_images"):
            _fn = getattr(_imf, "filename", "") or ""
            if not _fn or not hasattr(_imf, "read"):
                continue
            _raw = await _imf.read()
            if (os.path.splitext(_fn)[1].lower() not in _PROD_IMG_EXT) or not _raw or len(_raw) < 50 or len(_raw) > 25 * 1024 * 1024:
                _z50_skip += 1
                continue
            if len(_z50_files) >= 20:
                _z50_skip += 1
                continue
            _z50_files.append((_fn, _raw))
    except Exception as _e50:
        print(f"[z1191z50] 참고 이미지 읽기 실패: {_e50}")
        _z50_files = []
    # 1) 프로젝트 서술필드 갱신 — 통보 본문·상세 표시에 새 값 반영(관리번호 불변). 수정 라우트와 동일 로직.
    try:
        with db_session() as c:
            p = c.execute("SELECT id FROM projects WHERE id=?", (pid,)).fetchone()
            if not p:
                return RedirectResponse("/projects", 303)
            _setcols = ["server_path=?", "model_name=?", "engraving=?"]
            _setvals = [_server_path or None, _model_name or None, _engraving or None]
            if _full_edit:
                if _pname:
                    _setcols.append("name=?"); _setvals.append(_pname)
                for _col, _val in (("cc_name", _cc_name), ("cc_position", _cc_position),
                                   ("equip_name", _equip_name), ("customer_po", _customer_po)):
                    _setcols.append(f"{_col}=?"); _setvals.append(_val or None)
                if _unit_qty_raw.isdigit() and int(_unit_qty_raw) > 0:
                    _setcols.append("unit_qty=?"); _setvals.append(int(_unit_qty_raw))
                if _due_date:
                    _setcols.append("due_date=?"); _setvals.append(_due_date)
                if _order_date:
                    _setcols.append("order_date=?"); _setvals.append(_order_date)
                if _ship_form in ("ASSEMBLY", "SEMI", "PARTS", "ETC"):
                    _setcols.append("shipment_form=?"); _setvals.append(_ship_form)
                if _biz_div_v in ("T", "M", "L", "E", "C", "R"):
                    _setcols.append("biz_div=?"); _setvals.append(_biz_div_v)
                if _is_export_raw in ("0", "1"):
                    _setcols.append("is_export=?"); _setvals.append(int(_is_export_raw))
                # 고객사: 등록 목록에서 고른 유효 customer_id 일 때만 변경(연결 유지·feedback_data_connectivity)
                if _cust_id_raw.isdigit() and int(_cust_id_raw) > 0:
                    _setcols.append("customer_id=?"); _setvals.append(int(_cust_id_raw))
                    _setcols.append("customer_name=?"); _setvals.append(_cust_name_v or None)
            _setvals.append(pid)
            c.execute(f"UPDATE projects SET {', '.join(_setcols)} WHERE id=?", _setvals)
            if "sales_name" in form:   # z1191z69: 영업담당자(작성·수정 화면)
                _z69_set_sales(c, pid, form.get("sales_name"), u)
    except Exception as _e:
        print(f"[z787] 제작요청서 신규 작성(프로젝트 갱신) 실패: {_e}")
        return RedirectResponse(_dest("prod_upderr=1"), 303)
    # 2) 새 제작요청서 발행 + 부서 통보(team_ids=None → 활성 전부서 → 프로젝트 사업부로 자동 라우팅).
    #    record=True(새 1행 INSERT)·is_update=False(신규 발행 표기). 성공 시 새 요청서 페이지로 이동.
    _qs = ["prod_created=1"]
    _z58_groups = []   # z1191z58: 이미 보낸 요청서가 든 관리번호를 묶음 → 「묶어서 다시 발행」(앞 요청서는 묶음으로 바뀜)
    if _z49_bundle:
        try:
            with db_session() as _c58:
                _z58_groups = _z58_covered_groups(_c58, _z58_new_pairs(_c58, int(pid), _z48_oids, _z49_bundle, _z58_now()))
        except Exception as _e58:
            print(f"[z1191z58] 앞 요청서 찾기 실패(새 발행은 계속): {_e58}")
            _z58_groups = []
    try:
        _res = _prod_request_notify_core(int(pid), _cust_req, _note, (_sel_team_ids or None), u,
                                         record=True, is_update=False, image_count=len(_z50_files),
                                         user_ids=(_sel_user_ids or None),
                                         order_ids=(_z48_oids or None), gist=_z48_gist,
                                         bundle=(_z49_bundle or None), bundle_model=_z49_bm,
                                         replaces=([g["lead_id"] for g in _z58_groups] or None))
        if _res.get("ok"):
            _newid = _res.get("pr_id") or 0
            if _z58_groups and _newid:
                try:
                    _qs.append("rebundled=%d" % _z58_mark_replaced(_z58_groups, _newid, u))
                except Exception as _e58b:
                    print(f"[z1191z58] 앞 요청서 바뀜 표시 실패: {_e58b}")
            _qs = ([f"prid={_newid}"] if _newid else []) + [x for x in _qs if x.startswith("rebundled=")] + [
                "prod_created=1",
                f"prod_sent={_res.get('sent_to', 0)}",
                f"prod_dept={_res.get('dept_count', 0)}",
                f"prod_msg={_res.get('msg_sent', 0)}"]
            if _res.get("msg_err"):
                _qs.append("prod_msgerr=1")
            if _res.get("pr_save_err"):
                _qs.append("prod_saveerr=1")
            # z1191z50: 참고 이미지 붙이기 — 실패해도 발행·통보는 그대로(까닭만 화면에)
            if _z50_files or _z50_skip:
                _z50_saved, _z50_bad = 0, _z50_skip
                if _newid and _z50_files:
                    try:
                        _ir = _attach_prod_images(_newid, pid, _z50_files, (u.get("id") if u else None))
                        _z50_saved = int(_ir.get("saved") or 0)
                        _z50_bad += len(_ir.get("skipped") or [])
                    except Exception as _e50:
                        print(f"[z1191z50] 참고 이미지 저장 실패: {_e50}")
                        _z50_bad += len(_z50_files)
                else:
                    _z50_bad += len(_z50_files)
                if _z50_saved:
                    _qs.append(f"prod_img={_z50_saved}")
                if _z50_bad:
                    _qs.append(f"prod_imgskip={_z50_bad}")
        elif _res.get("error") == "need_mgmt_order":   # z1191z49: 묶은 관리번호에 수주가 없음 등(필수)
            _qs = ["new=1", "prod_need=" + str(_res.get("need") or "order")]
        else:
            _qs.append("prod_renotifyerr=1")
    except Exception as _e:
        print(f"[z787] 제작요청서 신규 작성 통보 실패: {_e}")
        _qs.append("prod_renotifyerr=1")
    return RedirectResponse(_dest("&".join(_qs)), 303)


# v5H226z795 (대표 지시): 제작요청 통보 블록(즐겨찾기) — 회사 공용. 생성/수정/삭제 권한=영업·매출 쓰기권한 or 대표/임원.
def _can_make_notify_block(u):
    if not u:
        return False
    if str(u.get("role") or "").lower() in ("ceo", "admin", "executive"):
        return True
    try:
        return bool(can_use_sales(u))
    except Exception:
        return False


def _nb_csv_ids(vals):
    out = []
    for x in (vals or []):
        s = str(x).strip()
        if s.isdigit() and int(s) > 0 and s not in out:
            out.append(s)
    return ",".join(out)


@app.get("/api/notify-blocks")
async def api_notify_blocks_list(request: Request):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login"}, 401)
    rows = []
    try:
        with db_session() as c:
            rows = [dict(r) for r in c.execute(
                "SELECT id, name, COALESCE(team_ids,'') AS team_ids, COALESCE(user_ids,'') AS user_ids, "
                "COALESCE(created_by_name,'') AS created_by_name FROM notify_blocks ORDER BY name").fetchall()]
    except Exception:
        rows = []
    return JSONResponse({"ok": True, "blocks": rows, "can_edit": _can_make_notify_block(u)})


@app.post("/api/notify-blocks")
async def api_notify_block_create(request: Request):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login"}, 401)
    if not _can_make_notify_block(u):
        return JSONResponse({"ok": False, "error": "권한 없음 — 영업·대표·임원만 블록을 만들 수 있습니다."}, 403)
    form = await request.form()
    name = (form.get("name") or "").strip()
    if not name:
        return JSONResponse({"ok": False, "error": "블록 이름을 입력하세요."})
    team_ids = _nb_csv_ids(form.getlist("team_ids"))
    user_ids = _nb_csv_ids(form.getlist("user_ids"))
    if not team_ids and not user_ids:
        return JSONResponse({"ok": False, "error": "팀 또는 인원을 하나 이상 선택하세요."})
    from datetime import datetime as _dtb
    _now = _dtb.now().strftime("%Y-%m-%d %H:%M")
    _by = u.get("name") or u.get("login_id") or "—"
    try:
        with db_session() as c:
            _cur = c.execute(
                "INSERT INTO notify_blocks(name, team_ids, user_ids, created_by, created_by_name, created_at) "
                "VALUES(?,?,?,?,?,?)", (name, team_ids, user_ids, u.get("id"), _by, _now))
            _bid = _cur.lastrowid or 0
        return JSONResponse({"ok": True, "id": _bid, "name": name, "team_ids": team_ids, "user_ids": user_ids})
    except Exception as e:
        return JSONResponse({"ok": False, "error": str(e)[:120]})


@app.post("/api/notify-blocks/{bid}/update")
async def api_notify_block_update(request: Request, bid: int):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login"}, 401)
    if not _can_make_notify_block(u):
        return JSONResponse({"ok": False, "error": "권한 없음"}, 403)
    form = await request.form()
    name = (form.get("name") or "").strip()
    team_ids = _nb_csv_ids(form.getlist("team_ids"))
    user_ids = _nb_csv_ids(form.getlist("user_ids"))
    if not name:
        return JSONResponse({"ok": False, "error": "블록 이름을 입력하세요."})
    if not team_ids and not user_ids:
        return JSONResponse({"ok": False, "error": "팀 또는 인원을 하나 이상 선택하세요."})
    from datetime import datetime as _dtb
    _now = _dtb.now().strftime("%Y-%m-%d %H:%M")
    try:
        with db_session() as c:
            c.execute("UPDATE notify_blocks SET name=?, team_ids=?, user_ids=?, updated_at=? WHERE id=?",
                      (name, team_ids, user_ids, _now, bid))
        return JSONResponse({"ok": True, "id": bid, "name": name, "team_ids": team_ids, "user_ids": user_ids})
    except Exception as e:
        return JSONResponse({"ok": False, "error": str(e)[:120]})


@app.post("/api/notify-blocks/{bid}/delete")
async def api_notify_block_delete(request: Request, bid: int):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login"}, 401)
    if not _can_make_notify_block(u):
        return JSONResponse({"ok": False, "error": "권한 없음"}, 403)
    try:
        with db_session() as c:
            c.execute("DELETE FROM notify_blocks WHERE id=?", (bid,))
        return JSONResponse({"ok": True, "id": bid})
    except Exception as e:
        return JSONResponse({"ok": False, "error": str(e)[:120]})


# v5H226z769 (대표 지시): 제작요청서 독립 편집 페이지 — 설치앱(PWA)서 프로젝트 상세 '제작요청서 카드'가 안 뜨는 문제 우회.
#   상세와 무관한 단독 전체 페이지라 앱에서도 확실히 렌더됨. 헤더 '📋 제작요청서' 버튼이 여기로 링크.
# z1191z58 (대표 2026-11-18 「처음부터 발행할 때 묶어서 발행할 수 있게」 · 고름 = ① 등록 화면에서 묶기 + ② 목록에서 골라 + 이미 보낸 것은 「묶어서 다시 발행」):
#   ① 등록 화면 제작요청 = 지금 발행 / 묶어서 발행(기다림 = prq_waits) / 발행 안 함 → 같은 발주의 마지막 관리번호를 「지금 발행」으로 등록할 때
#      기다리던 관리번호와 한 장으로 「처음 발행」.  ② 작업일정표에서 ☑ 고른 관리번호 → 묶인 새 작성 화면(?with=pid:oid,…).
#   ③ 이미 보낸 요청서가 든 관리번호를 묶으면 수정발행이 아니라 「묶어서 다시 발행」 = 새 요청서 + 앞 요청서는 cancel_kind='replace'
#      (취소 아님 · 「묶음으로 바뀜」 · replaced_by) · 이음 카드에 replaces(앞 요청서 prid) · rebundle.  요청서 화면 「수정하기」의
#      관리번호 붙이기는 「🔗 관리번호 더 묶어서 다시 발행」(?from=prid · 글·받는 사람을 불러온 새 작성)으로 바꿈.
def _z58_tables(c):
    c.execute("CREATE TABLE IF NOT EXISTS prq_waits(project_id INTEGER PRIMARY KEY, by_id INTEGER, by_name TEXT, at TEXT)")


def _z58_now():
    from datetime import datetime as _d58, timezone as _tz58, timedelta as _td58
    return _d58.now(_tz58(_td58(hours=9))).strftime("%Y-%m-%d %H:%M")


def _z58_wait_set(c):
    try:
        _z58_tables(c)
        return {int(r[0]) for r in c.execute("SELECT project_id FROM prq_waits").fetchall()}
    except Exception:
        return set()


def _z58_unwait(c, pids):
    pids = [int(x) for x in (pids or []) if str(x).strip().isdigit()]
    if not pids:
        return
    _z58_tables(c)
    c.execute("DELETE FROM prq_waits WHERE project_id IN (%s)" % ",".join("?" * len(pids)), pids)


def _z58_pairs_of_row(c, row):
    sel = _z48_pick_orders(_z48_project_orders(c, int(row["project_id"])), row.get("order_ids") or "", row.get("created_at") or "")
    return {(int(row["project_id"]), int(o["id"])) for o in sel}


def _z58_new_pairs(c, lead_pid, lead_oids, bundle, at):
    out = set()
    for o in _z48_pick_orders(_z48_project_orders(c, int(lead_pid)), ",".join(str(x) for x in (lead_oids or [])), at):
        out.add((int(lead_pid), int(o["id"])))
    for b in (bundle or []):
        for o in _z48_pick_orders(_z48_project_orders(c, int(b["pid"])), ",".join(str(x) for x in (b.get("order_ids") or [])), at):
            out.add((int(b["pid"]), int(o["id"])))
    return out


def _z58_covered_groups(c, new_pairs):
    """새로 묶어 내는 (관리번호·수주)가 「살아 있는 앞 요청서」 한 장의 (관리번호·수주)를 모두 품으면 그 앞 요청서 → 묶음으로 바뀜 대상.
    일부만 겹치는 앞 요청서는 그대로 둔다(그 요청서의 다른 관리번호가 요청서를 잃지 않게). 반환 [{lead_id, ids, mgmts}]"""
    pids = sorted({p for p, _ in new_pairs})
    if not pids:
        return []
    keys = []
    for r in c.execute("SELECT id, bundle_id, COALESCE(cancel_kind,'') FROM prod_requests WHERE project_id IN (%s) "
                       "AND COALESCE(cancelled_at,'')='' ORDER BY id" % ",".join("?" * len(pids)), pids).fetchall():
        k = int(r[1]) if (r[1] and r[2] != "remove") else int(r[0])
        if k not in keys:
            keys.append(k)
    out = []
    for k in keys:
        grp = [dict(x) for x in c.execute("SELECT id, project_id, COALESCE(order_ids,'') AS order_ids, COALESCE(created_at,'') AS created_at "
                                          "FROM prod_requests WHERE (id=? OR bundle_id=?) AND COALESCE(cancelled_at,'')='' "
                                          "AND COALESCE(cancel_kind,'')<>'remove' ORDER BY id", (k, k)).fetchall()]
        if not grp:
            continue
        gp = set()
        for g in grp:
            gp |= _z58_pairs_of_row(c, g)
        if gp and gp <= new_pairs:
            mg = []
            for g in grp:
                x = c.execute("SELECT COALESCE(mgmt_code,'') FROM projects WHERE id=?", (g["project_id"],)).fetchone()
                mg.append(x[0] if x else "")
            out.append({"lead_id": k, "ids": [g["id"] for g in grp], "mgmts": mg})
    return out


def _z58_mark_replaced(groups, new_id, user):
    if not groups or not new_id:
        return 0
    at = _z58_now()
    by = vname_full(user or {}) or ((user or {}).get("name") or "")
    n = 0
    with db_session() as c:
        for g in groups:
            ids = [int(x) for x in g["ids"]]
            o = c.execute("SELECT COALESCE(cust_req,''), COALESCE(note,''), COALESCE(gist,'') FROM prod_requests WHERE id=?", (g["lead_id"],)).fetchone()
            try:
                _z51_snapshot(c, int(g["lead_id"]), "replace", "묶어서 다시 발행", (o[0] if o else ""), (o[1] if o else ""), (o[2] if o else ""),
                              "묶음 요청서 #%d 로 바뀜" % int(new_id), (user or {}).get("id"), by, at)
            except Exception as _e58:
                print(f"[z1191z58] 이력 남기기 실패(바뀜 표시는 계속): {_e58}")
            c.execute("UPDATE prod_requests SET cancelled_at=?, cancel_kind='replace', cancel_reason=?, cancelled_by_name=?, replaced_by=? "
                      "WHERE id IN (%s)" % ",".join("?" * len(ids)), [at, "묶음 요청서로 다시 발행", by, int(new_id)] + ids)
            try:   # 웍스 알림의 앞 카드도 흑백(수정발행과 같은 표시)
                c.execute("UPDATE notifications SET superseded=1, is_read=1 WHERE kind='prod_request' AND prod_prid IN (%s) "
                          "AND COALESCE(superseded,0)=0" % ",".join("?" * len(ids)), ids)
            except Exception:
                pass
            n += 1
    return n


def _z58_pre(c, p, with_s, from_s):
    """새 작성 화면 미리 채우기 — ?with=pid:oid,…(작업일정표에서 고름) · ?from=prid(그 요청서를 묶어서 다시 발행)."""
    pre = {"pairs": [], "from": None, "text": None, "teams": [], "users": []}
    pairs = []
    fs = str(from_s or "").strip()
    if fs.isdigit():
        r = c.execute("SELECT * FROM prod_requests WHERE id=?", (int(fs),)).fetchone()
        if r:
            r = dict(r)
            if r.get("bundle_id") and int(r["bundle_id"]) != int(r["id"]) and (r.get("cancel_kind") or "") != "remove":
                x = c.execute("SELECT * FROM prod_requests WHERE id=?", (int(r["bundle_id"]),)).fetchone()
                r = dict(x) if x else r
            for m in _z49_bundle_rows(c, r):
                sel = _z48_pick_orders(_z48_project_orders(c, int(m["project_id"])), m.get("order_ids") or "", m.get("created_at") or "")
                pairs.append((int(m["project_id"]), (int(sel[0]["id"]) if sel else None)))
            mg = c.execute("SELECT COALESCE(mgmt_code,'') FROM projects WHERE id=?", (r["project_id"],)).fetchone()
            pre["from"] = {"id": int(r["id"]), "mgmt": (mg[0] if mg else ""), "date": str(r.get("created_at") or "")[:10],
                           "n": len(pairs), "live": not bool(r.get("cancelled_at"))}
            pre["text"] = {"cust_req": r.get("cust_req") or "", "note": r.get("note") or "", "gist": r.get("gist") or "",
                           "bundle_model": r.get("bundle_model") or ""}
            pre["teams"] = [int(t) for t in str(r.get("wt_team_ids") or "").replace(";", ",").split(",") if t.strip().isdigit()]
            pre["users"] = [int(t) for t in str(r.get("user_ids") or "").replace(";", ",").split(",") if t.strip().isdigit()]
    for tok in str(with_s or "").split(","):
        a, _, b = tok.partition(":")
        if a.strip().isdigit():
            pairs.append((int(a), int(b) if b.strip().isdigit() else None))
    seen = set()
    for a, b in pairs:
        if a in seen:
            continue
        seen.add(a)
        pre["pairs"].append([a, b])
    return pre


# z1191z69 (대표 11-19): 제작요청서 — 작성자(발행한 사람)는 제목 줄에 작게 「작성자 기술영업팀 안지연프로」,
#   오른쪽 위 칸은 「영업담당자」 = 프로젝트 영업담당자(projects.sales_name · 관리번호대장 「영업 담당」·작업일정표 「영업담당자」와 같은 값).
def _z69_people(c, p, pr):
    out = {"writer": "", "sales": "", "opts": []}
    try:
        if pr:
            r = None
            if pr.get("issued_by"):
                r = c.execute("SELECT u.name, COALESCE(u.rank,'') AS rank, COALESCE(t.name,'') AS team FROM users u "
                              "LEFT JOIN teams t ON t.id=u.team_id WHERE u.id=?", (int(pr["issued_by"]),)).fetchone()
            if r:
                out["writer"] = ("%s %s%s" % (r["team"], r["name"], r["rank"])).strip()
            else:
                out["writer"] = (pr.get("issued_by_name") or "").strip()
        opts = [dict(x) for x in c.execute(
            "SELECT u.name, COALESCE(u.rank,'') AS rank FROM users u JOIN teams t ON t.id=u.team_id "
            "WHERE COALESCE(u.is_active,1)=1 AND t.name LIKE '%기술영업%' ORDER BY u.name").fetchall()]
        out["opts"] = opts
        nm = str((p or {}).get("sales_name") or "").strip()
        if nm:
            rk = next((o["rank"] for o in opts if o["name"] == nm), None)
            if rk is None:
                x = c.execute("SELECT COALESCE(rank,'') FROM users WHERE name=? AND COALESCE(is_active,1)=1 LIMIT 2", (nm,)).fetchall()
                rk = x[0][0] if len(x) == 1 else ""
            out["sales"] = ("%s %s" % (nm, rk)).strip()
    except Exception as _e:
        print(f"[z1191z69] 작성자·영업담당자 표시 실패: {_e}")
    return out


def _z69_set_sales(c, pid, raw, u):
    """작성·수정 화면 「영업담당자」 → projects.sales_name(이름만 · 「안지연 프로」처럼 직책이 붙어 오면 이름만) · 바뀌면 변경 이력."""
    v = " ".join(str(raw or "").split())[:40]
    if " " in v:
        head = v.split(" ", 1)[0]
        if c.execute("SELECT 1 FROM users WHERE name=? LIMIT 1", (head,)).fetchone():
            v = head
    r = c.execute("SELECT COALESCE(sales_name,'') FROM projects WHERE id=?", (pid,)).fetchone()
    old = (r[0] if r else "") or ""
    if old.strip() == v:
        return
    c.execute("UPDATE projects SET sales_name=? WHERE id=?", (v or None, pid))
    who = vname_full(u) or u.get("name") or ""
    c.execute("INSERT INTO project_history(project_id, changed_by, field, old_value, new_value, note) VALUES(?,?,?,?,?,?)",
              (pid, u.get("id"), "영업담당자", old, v, "z1191z69 제작요청서에서 · %s" % who))


