@app.get("/dept/schedule/timeline")
async def dept_schedule_timeline(request: Request, kind: str = "", ref_id: int = 0):
    """v5H226z499 (Phase 3 #1): 품목별 진행 타임라인 — 한 관리번호의 모든 부서 기록을 날짜순으로 모아보기."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "로그인 필요"}, 401)
    kind = (kind or "").strip()
    if kind not in ("project", "consumable") or not ref_id:
        return JSONResponse({"ok": False, "error": "잘못된 요청"}, 400)
    items, code = [], ""
    try:
        with db_session() as c:
            if kind == "project":
                _cr = c.execute("SELECT mgmt_code FROM projects WHERE id=?", (ref_id,)).fetchone()
            else:
                _cr = c.execute("SELECT mgmt_code FROM consumable_orders WHERE id=?", (ref_id,)).fetchone()
            code = (_cr[0] if _cr else "") or f"{kind}#{ref_id}"
            # z1191b: 어느 수주의 기록인지(수주번호) — 칸이 없으면 빈 글
            _so1191 = ("COALESCE((SELECT o.order_no FROM orders o WHERE o.id=dept_schedule_log.order_id),'')"
                       if "order_id" in {x[1] for x in c.execute("PRAGMA table_info(dept_schedule_log)").fetchall()} else "''")
            for r in c.execute(
                "SELECT log_date, COALESCE(dept,''), COALESCE(log_type,'진행'), COALESCE(content,''), "
                "COALESCE(created_by_name,''), COALESCE(handoff_to,''), COALESCE(unit_label,''), COALESCE(updated_at,''), "
                + _so1191 + " FROM dept_schedule_log WHERE ref_kind=? AND ref_id=? ORDER BY log_date, id",
                    (kind, ref_id)):
                items.append({"date": str(r[0])[:10], "dept": r[1], "type": r[2], "content": r[3],
                              "by": r[4], "to": r[5], "unit": r[6], "ts": r[7], "so": r[8]})
    except Exception as _e:
        return JSONResponse({"ok": False, "error": f"조회 오류: {str(_e)[:80]}"}, 500)
    return JSONResponse({"ok": True, "code": code, "kind": kind, "ref_id": ref_id, "items": items})


# ───────── v5H226z578 (대표 지시): 부서 자체 연구개발(R&D) 과제 — 매출과 별개·관리번호 R 발번 ─────────
_RND_CATEGORIES = ["신제품", "공정개선", "지그·툴", "자동화", "기타"]
_RND_STATUSES = ["기획", "진행", "시험검증", "완료", "보류", "중단"]
_RND_PRIORITIES = ["긴급", "높음", "보통", "낮음"]


def _rnd_dept_options():
    """담당 부서 드롭다운/탭용 — teams 라벨(본사·/베트남·) 목록."""
    out = []
    try:
        with db_session() as c:
            for r in c.execute("SELECT name, COALESCE(entity,'KOR') FROM teams ORDER BY "
                               "(CASE WHEN COALESCE(entity,'KOR')='VN' THEN 1 ELSE 0 END), display_order, name"):
                out.append(_team_label(r[0], r[1]))
    except Exception:
        pass
    return out


@app.get("/rnd", response_class=HTMLResponse)
async def rnd_list(request: Request):
    """부서 연구개발 과제 목록 — 부서 탭·상태 필터·검색. 전 직원 열람."""
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    items = []
    try:
        with db_session() as c:
            for r in c.execute(
                "SELECT id, COALESCE(mgmt_code,''), title, COALESCE(dept,''), COALESCE(owner_name,''), "
                "COALESCE(category,''), COALESCE(status,'기획'), COALESCE(priority,'보통'), "
                "COALESCE(start_date,''), COALESCE(target_date,'') "
                "FROM rnd_projects ORDER BY id DESC"):
                items.append({"id": r[0], "mgmt_code": r[1], "title": r[2], "dept": r[3], "owner_name": r[4],
                              "category": r[5], "status": r[6], "priority": r[7],
                              "start_date": r[8], "target_date": r[9]})
    except Exception:
        items = []
    return ctx(request, "rnd_list.html", user=u, active="rnd", items=items,
               depts=_rnd_dept_options(), categories=_RND_CATEGORIES,
               statuses=_RND_STATUSES, priorities=_RND_PRIORITIES,
               my_dept=_dept_sched_dept_of(u))


@app.post("/rnd/new")
async def rnd_new(request: Request):
    """연구과제 등록 — R 관리번호 자동 발번. 로그인이면 누구나(부서 자체 과제)."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    try:
        b = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "bad_request"}, 400)
    title = (str(b.get("title") or "")).strip()
    if not title:
        return JSONResponse({"ok": False, "error": "과제명을 입력하세요"}, 400)
    dept = (str(b.get("dept") or "")).strip() or _dept_sched_dept_of(u)
    category = (str(b.get("category") or "")).strip()
    purpose = (str(b.get("purpose") or "")).strip()
    start_date = (str(b.get("start_date") or "")).strip()[:10] or None
    target_date = (str(b.get("target_date") or "")).strip()[:10] or None
    priority = (str(b.get("priority") or "보통")).strip()
    if priority not in _RND_PRIORITIES:
        priority = "보통"
    owner_name = (str(b.get("owner_name") or "")).strip() or (u.get("name") or "")
    try:
        from .database import generate_mgmt_code as _gmc
        mgmt_code = _gmc("R", _ref_date_from(start_date))
    except Exception:
        mgmt_code = None
    try:
        with db_session() as c:
            cur = c.execute(
                "INSERT INTO rnd_projects(mgmt_code, title, dept, owner_id, owner_name, category, purpose, "
                "start_date, target_date, priority, status, created_by, created_by_name) "
                "VALUES(?,?,?,?,?,?,?,?,?,?, '기획', ?, ?)",
                (mgmt_code, title, dept, u.get("id"), owner_name, category, purpose,
                 start_date, target_date, priority, u.get("id"), u.get("name") or ""))
            rid = cur.lastrowid
    except Exception as e:
        return JSONResponse({"ok": False, "error": str(e)[:160]}, 500)
    return JSONResponse({"ok": True, "id": rid, "mgmt_code": mgmt_code or ""})


def _ref_date_from(s):
    """'YYYY-MM-DD' → datetime(관리번호 연월 기준). 없으면 None(현재월)."""
    try:
        from datetime import datetime as _dt
        return _dt.strptime(str(s)[:10], "%Y-%m-%d") if s else None
    except Exception:
        return None


@app.get("/rnd/{rid:int}", response_class=HTMLResponse)
async def rnd_detail(request: Request, rid: int):
    """연구과제 상세 — 정보 + 진행 타임라인 + 결과."""
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    with db_session() as c:
        r = c.execute("SELECT * FROM rnd_projects WHERE id=?", (rid,)).fetchone()
        if not r:
            return HTMLResponse("<h3>없는 과제입니다.</h3>", status_code=404)
        p = dict(r)
        # v5H226z800 (대표 지시·규칙): 등록자·담당자 = 이름 직책 부서 [[knk_name_display_rule]].
        #   담당자 입력칸(owner_name)은 폼 round-trip이라 값은 유지하고 호버로만 전체 표시.
        p["created_by_disp"] = user_disp_by_id(c, p.get("created_by"), p.get("created_by_name") or "")
        p["owner_disp"] = user_disp_by_id(c, p.get("owner_id"), p.get("owner_name") or "")
        logs = [dict(x) for x in c.execute(
            "SELECT id, COALESCE(log_date,'') AS log_date, COALESCE(log_type,'진행') AS log_type, "
            "COALESCE(content,'') AS content, hours, COALESCE(created_by_name,'') AS by_name, "
            "COALESCE(created_by,0) AS uid, COALESCE(created_at,'') AS created_at "
            "FROM rnd_logs WHERE rnd_id=? ORDER BY id DESC", (rid,)).fetchall()]
    return ctx(request, "rnd_detail.html", user=u, active="rnd", p=p, logs=logs,
               depts=_rnd_dept_options(), categories=_RND_CATEGORIES,
               statuses=_RND_STATUSES, priorities=_RND_PRIORITIES,
               can_edit=bool(p.get("created_by") == u.get("id") or u.get("role") in ("admin", "ceo")),
               uid=u.get("id"), is_admin=bool(u.get("role") in ("admin", "ceo")))


@app.post("/rnd/{rid:int}/update")
async def rnd_update(request: Request, rid: int):
    """연구과제 정보·상태·결과 수정. 작성자/관리자만."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    try:
        b = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "bad_request"}, 400)
    with db_session() as c:
        row = c.execute("SELECT COALESCE(created_by,0) FROM rnd_projects WHERE id=?", (rid,)).fetchone()
        if not row:
            return JSONResponse({"ok": False, "error": "not_found"}, 404)
        if not (row[0] == u.get("id") or u.get("role") in ("admin", "ceo")):
            return JSONResponse({"ok": False, "error": "작성자만 수정할 수 있습니다"}, 403)
        _sets, _vals = [], []
        _allow = {"title": str, "dept": str, "owner_name": str, "category": str, "purpose": str,
                  "start_date": "date", "target_date": "date", "priority": str, "status": str,
                  "result_summary": str}
        for k, typ in _allow.items():
            if k not in b:
                continue
            v = b.get(k)
            if k == "status" and (v or "") not in _RND_STATUSES:
                continue
            if k == "priority" and (v or "") not in _RND_PRIORITIES:
                continue
            if typ == "date":
                v = (str(v or "").strip()[:10] or None)
            else:
                v = (str(v or "").strip() or None)
            _sets.append(f"{k}=?"); _vals.append(v)
        if not _sets:
            return JSONResponse({"ok": True})
        _vals.append(rid)
        c.execute(f"UPDATE rnd_projects SET {', '.join(_sets)}, updated_at=datetime('now','localtime') WHERE id=?", _vals)
    return JSONResponse({"ok": True})


@app.post("/rnd/{rid:int}/log")
async def rnd_log_add(request: Request, rid: int):
    """연구과제 진행 기록 추가(날짜·유형·내용·소요시간). 로그인이면 누구나(부서 협업)."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    try:
        b = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "bad_request"}, 400)
    content = (str(b.get("content") or "")).strip()
    if not content:
        return JSONResponse({"ok": False, "error": "내용을 입력하세요"}, 400)
    log_date = (str(b.get("log_date") or "")).strip()[:10]
    if not log_date:
        from datetime import date as _d
        log_date = _d.today().isoformat()
    log_type = (str(b.get("log_type") or "진행")).strip()
    if log_type not in ("진행", "완료", "변경", "기타"):
        log_type = "진행"
    try:
        hours = float(str(b.get("hours") or "").replace(",", "").strip())
        if hours <= 0 or hours > 999:
            hours = None
    except Exception:
        hours = None
    with db_session() as c:
        if not c.execute("SELECT 1 FROM rnd_projects WHERE id=?", (rid,)).fetchone():
            return JSONResponse({"ok": False, "error": "not_found"}, 404)
        c.execute("INSERT INTO rnd_logs(rnd_id, log_date, log_type, content, hours, created_by, created_by_name) "
                  "VALUES(?,?,?,?,?,?,?)",
                  (rid, log_date, log_type, content, hours, u.get("id"), u.get("name") or ""))
        c.execute("UPDATE rnd_projects SET updated_at=datetime('now','localtime') WHERE id=?", (rid,))
    return JSONResponse({"ok": True})


@app.post("/rnd/{rid:int}/log/{lid:int}/delete")
async def rnd_log_delete(request: Request, rid: int, lid: int):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    with db_session() as c:
        row = c.execute("SELECT COALESCE(created_by,0) FROM rnd_logs WHERE id=? AND rnd_id=?", (lid, rid)).fetchone()
        if not row:
            return JSONResponse({"ok": True})
        if not (row[0] == u.get("id") or u.get("role") in ("admin", "ceo")):
            return JSONResponse({"ok": False, "error": "작성자만 삭제할 수 있습니다"}, 403)
        c.execute("DELETE FROM rnd_logs WHERE id=?", (lid,))
    return JSONResponse({"ok": True})


@app.post("/rnd/{rid:int}/delete")
async def rnd_delete(request: Request, rid: int):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    with db_session() as c:
        row = c.execute("SELECT COALESCE(created_by,0) FROM rnd_projects WHERE id=?", (rid,)).fetchone()
        if not row:
            return JSONResponse({"ok": True})
        if not (row[0] == u.get("id") or u.get("role") in ("admin", "ceo")):
            return JSONResponse({"ok": False, "error": "작성자/관리자만 삭제할 수 있습니다"}, 403)
        c.execute("DELETE FROM rnd_logs WHERE rnd_id=?", (rid,))
        c.execute("DELETE FROM rnd_projects WHERE id=?", (rid,))
    return JSONResponse({"ok": True})


@app.get("/projects/export.xlsx")
# v5H226z867: async→def 전환(FastAPI 스레드풀 실행·이벤트루프 비블로킹) — 본문 await 0건 AST 확인. 이 함수에 await를 추가하려면 반드시 async def로 되돌릴 것.
def projects_export_xlsx(request: Request, q: str = "", div: str = "",
                               view: str = "", status: str = ""):
    """v5H226z218 (대표 지시): 프로젝트 목록 엑셀 — 보여지는 형태(사업부 책갈피·상태) 그대로.
    상단 제목(사업부·기간·건수) + 상황에 맞는 파일명."""
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_view_sales(u):
        return RedirectResponse("/home", 303)
    _div = (div or "").strip().upper()
    _biz = _div if _div in ("T", "M", "L") else ""
    _ptype = {"E": "OTHER", "C": "CONSUMABLE"}.get(_div, "")
    rows = [dict(r) for r in _logi.projects_list_logi(q=q, biz_div=_biz, stage="",
                                                      status=status, project_type=_ptype)]
    try:   # z1191z157b: 엑셀도 1차 고객사 = 번호의 지금 이름(화면 목록과 같게)
        with db_session() as _c157:
            _logi.fix_customer_names_in(_c157, rows)
    except Exception as _e157:
        print(f"[z1191z157b] 프로젝트 엑셀 고객사 이름 실패: {_e157}")
    # 소모품 병합 — v5H226z254 (대표 지시): '전체' 또는 '소모품' 탭일 때만.
    #   소모품 co 는 진행사업부(biz_div)가 T/M 일 수 있어, 검사기/자동화 탭(_div=T/M/L)에서
    #   biz_div 필터만으로는 끼어들던 문제 → 목록 책갈피(_div=C)와 동일하게 _div 기준으로 제한.
    if _div in ("", "C"):
        try:
            from . import consumables as _co_mod
            _co_map = {"DRAFT": "초기협의", "QUOTED": "견적발행", "CONFIRMED": "진행중",
                       "SHIPPED": "출하", "PAID": "출하", "CANCELLED": "취소", "HOLD": "보류"}
            for cr in _co_mod.co_list(status="", q=q, limit=1000):
                _cb = (cr.get("biz_div") or "").strip().upper() if cr.get("biz_div") else ""
                if _biz and _cb != _biz:
                    continue
                _stl = _co_map.get(cr.get("status") or "DRAFT", "초기협의")
                if status and _stl != status:
                    continue
                rows.append({"_kind": "consumable", "mgmt_code": cr.get("mgmt_code") or "—",
                             "name": (cr.get("customer_name") or "고객사 미정") + " 소모품 수주 (" + (cr.get("co_no") or f"#{cr.get('id')}") + ")",
                             "customer_name": cr.get("customer_name") or "—", "biz_div": _cb or None,
                             "project_type": "CONSUMABLE", "status": _stl,
                             "order_amount": cr.get("total_amount") or 0, "order_date": cr.get("order_date") or "",
                             "currency": (cr.get("currency") or "KRW"),   # z1191z165: 원화 칸에 외화가 섞이지 않게(환산)
                             "equip_name": "", "model_name": "", "shipment_form": ""})
        except Exception:
            pass
    # 상태 책갈피(view) 필터 — 목록과 동일
    def _unconf(r):
        return str(r.get("mgmt_code") or "").strip() in ("", "—", "None", "none")
    if view == "unconfirmed":
        rows = [r for r in rows if _unconf(r)]
    elif view == "ongoing":
        rows = [r for r in rows if (r.get("status") or "") == "진행중"]
    elif view == "done":
        rows = [r for r in rows if (r.get("status") or "") == "출하"]
    elif view == "hold":
        rows = [r for r in rows if (r.get("status") or "") in ("보류", "취소")]
    rows.sort(key=lambda r: (str(r.get("order_date") or ""), str(r.get("mgmt_code") or "")), reverse=True)

    _div_label = {"T": "검사기사업부", "M": "자동화사업부", "L": "라이프밸류사업부",
                  "E": "기타", "C": "소모품"}.get(_div, "전체 사업부")
    _view_label = {"unconfirmed": "미확정", "ongoing": "진행중", "done": "출하", "hold": "보류·취소"}.get(view, "전체")
    _status_label = status or _view_label
    _dates = [str(r.get("order_date") or "") for r in rows if (r.get("order_date") or "").strip()]
    _period = (min(_dates) + " ~ " + max(_dates)) if _dates else "전체 기간"

    from app import knk_xlsx as KX   # z1191z67: KNK 회사 양식
    _sf_lbl = {"ASSEMBLY": "ASS'Y", "PARTS": "부품", "ETC": "기타"}
    # z1191z165 (대표 11-27): 「수주액(원)」 = 살아 있는 수주마다 발주 달 월 기준환율로 원화 환산해 더한 값(공용 _ccy_breakdown · 매출과 같은 기준)
    #   예전엔 projects.order_amount(외화면 외화 숫자)를 통화 표시 없이 원 칸에 넣었다 · 통화별 원금액 칸을 따로 둠 ·
    #   환율이 없어 못 바꾸면 원 칸은 비우고 「확인」 칸에 적음(반쪽 숫자 금지) · 고객사 = 수주 1차 고객 「외 N곳」 · 취소 수주는 빼고 수를 밝힘.
    try:
        with db_session() as _c165:
            _rates165 = _fx_load_rates(_c165)
            _so165 = _pwf.orders_summary(_c165, [int(r["id"]) for r in rows if r.get("_kind") != "consumable" and r.get("id")])
    except Exception as _e165:
        print(f"[z1191z165] 프로젝트 엑셀 수주 요약 실패: {_e165}")
        _rates165, _so165 = {}, {}
    COLS = [{"h": "관리코드", "w": 12, "al": "c", "bold": True}, {"h": "프로젝트명", "w": 32, "wrap": True}, {"h": "장비명", "w": 32, "wrap": True},
            {"h": "모델명", "w": 26, "wrap": True}, {"h": "고객사", "w": 22, "wrap": True}, {"h": "출고형태", "w": 9, "al": "c"},
            {"h": "상태", "w": 9, "al": "c"}, {"h": "수주액(원)", "w": 15, "al": "r", "fmt": "#,##0"}, {"h": "발주일", "w": 12, "al": "c"},
            # 예전 9칸 자리는 그대로(받아 쓰던 엑셀이 안 깨지게) · 새 칸은 뒤에
            {"h": "수주 수", "w": 7, "al": "c"}, {"h": "수주액(통화별)", "w": 26, "wrap": True}, {"h": "확인", "w": 30, "wrap": True}]
    data = []
    for r in rows:
        _sf = (r.get("shipment_form") or "").upper()
        _s = _so165.get(int(r["id"])) if (r.get("_kind") != "consumable" and r.get("id")) else None
        _note = []
        if _s and _s["n"]:
            _bd = _ccy_breakdown(_s["orders"], "total_amount", "currency", date_keys=("order_date", "due_date"), rates=_rates165)
            _cust, _amt_txt, _od, _n = (_s["cust_all"] or "—"), _s["amt_txt"], (_s["date_txt"] or "—"), _s["n"]
            if _s["n_cust_missing"]:
                _note.append("1차 고객 미정 수주 %d건" % _s["n_cust_missing"])
            if _s["n_cancelled"]:
                _note.append("취소 수주 %d건 뺌" % _s["n_cancelled"])
        else:   # 수주가 아직 없는 관리번호(미확정)·소모품 = 그 줄 자체 값
            _one = [{"total_amount": r.get("order_amount") or 0, "currency": (r.get("currency") or "KRW"),
                     "order_date": r.get("order_date") or ""}]
            _bd = _ccy_breakdown(_one, "total_amount", "currency", date_keys=("order_date",), rates=_rates165)
            _cust = r.get("customer_name") or "—"   # z165-ok: 수주가 없을 때만(미확정 · 소모품 줄)
            _c0 = str(_one[0]["currency"] or "KRW").upper()
            _amt_txt = ("%s %s" % (_c0, ("{:,.0f}" if _c0 in ("KRW", "VND", "JPY") else "{:,.2f}").format(float(_one[0]["total_amount"] or 0)))
                        if float(_one[0]["total_amount"] or 0) else "")
            _od, _n = (r.get("order_date") or "—"), (0 if r.get("_kind") != "consumable" else 1)
            if r.get("_kind") != "consumable" and r.get("mgmt_code") not in (None, "", "—"):
                _note.append("수주 없음 — 처음 등록 때 값")
        _krw = _bd.get("krw")
        if _krw is None:
            _note.append("환율 없음(%s) — 원화 칸 비움" % ", ".join("%s %s" % m for m in sorted(_bd.get("missing") or [])))
        data.append([r.get("mgmt_code") or "—", r.get("name") or r.get("project_name") or "—", r.get("equip_name") or "—",
                     r.get("model_name") or "—", _cust, _sf_lbl.get(_sf, "—") if _sf else "—",
                     r.get("status") or "—", (round(_krw) if _krw is not None else None), _od,
                     _n, _amt_txt or "—", " · ".join(_note)])
    wb = KX.new_book(_div_label, "프로젝트 목록")
    KX.table_sheet(wb.active, "프로젝트 목록 — %s" % _div_label,
                   "사업부 %s · 상태 %s · 기간(발주일) %s · %d건 · 내려받은 시각 %s" % (_div_label, _status_label, _period, len(rows), _z61_now()),
                   COLS, data, freeze_cols=1)
    _fn_div = {"T": "검사기", "M": "자동화", "L": "라이프밸류", "E": "기타", "C": "소모품"}.get(_div, "전체")
    _fn_view = "" if view in ("", "all") else f"_{_view_label}"
    fname = f"프로젝트_{_fn_div}{_fn_view}_{date.today().isoformat()}.xlsx"
    return KX.xlsx_response(wb, fname, "KNK_projects.xlsx")


