@app.get("/projects/new", response_class=HTMLResponse)
async def projects_new_form(request: Request,
                            type: str = "", biz_div: str = "", embed: str = ""):
    """v5H148 (2026-05-05) — 대표 직접 지시: 프로젝트 등록 진입점 통합.
    - type 파라미터 없으면 4-카드 chooser (T검사기/M자동화/기타/소모품)
    - type 있으면 기존 폼 + biz_div/project_type 사전 선택
    백워드 호환: 직접 ?type=NEW_EQUIP 진입 정상 동작."""
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    # v5H226z274 (대표 지시): 작업 일정표 '여기서 등록' — embed 모드(메뉴·상단바 없이 폼만, 모달용)
    _embed = str(embed).strip().lower() in ("1", "true", "on", "yes", "y")
    _t = (type or "").strip().upper()
    if not can_use_sales(u):
        # z1191z102 (대표 11-22 「고객사 등록도 기술영업팀만」): z101 의 「권한 없어도 🤝 고객사 카드만」 되돌림 — 예전처럼 홈으로
        return RedirectResponse("/home", 303)
    # type 없으면 chooser 페이지
    if not _t:
        return ctx(request, "project_new_chooser.html",
                   user=u, active="sales_projects", embed=_embed, can_reg_proj=True, can_manual=_can_manual_mgmt(u))
    # v5H221: CONSUMABLE 도 폼 재활용 (project_form.html — 일정/금액 숨김), SERVICE 만 OTHER 흡수
    if _t not in ("NEW_EQUIP", "OTHER", "CONSUMABLE"):
        _t = "OTHER" if _t == "SERVICE" else "NEW_EQUIP"
    _bd = (biz_div or "").strip().upper()
    if _bd not in ("T", "M", "L"):
        _bd = ""
    # v5H226z319 (대표 지시): NEW_EQUIP(검사기/자동화/라이프) 단건 등록은 간편 폼으로 통일 → 리다이렉트.
    #   상세 폼(project_form.html)은 코드 보존, 라우팅만 변경.
    # v5H226z355 (대표 지시): 기타(OTHER)도 동일하게 간편 폼으로(biz_div=E). 일괄등록 엑셀 포함. CONSUMABLE 만 정식 폼 유지.
    if _t == "NEW_EQUIP":
        _q = "/projects/quick?biz_div=" + (_bd or "T") + ("&embed=1" if _embed else "")
        return RedirectResponse(_q, 303)
    if _t == "OTHER":
        _q = "/projects/quick?biz_div=E" + ("&embed=1" if _embed else "")
        return RedirectResponse(_q, 303)
    # 폼이 project.* 로 prefill 을 읽으므로 가벼운 placeholder 객체 전달
    _preset = {
        "project_type": _t,
        "biz_div": _bd,
        "name": "", "customer_name": "", "po_type": "",
        "mgmt_code": "", "stage": "제안작성", "currency": "KRW",
        "id": None, "parent_project_id": None,
    }
    return ctx(request, "project_form.html",
               user=u, active="sales_projects",
               project=None,
               preset=_preset, embed=_embed,
               STAGES=_logi.STAGES, STATUSES=_logi.LOGI_STATUSES,
               PO_TYPES=_logi.PO_TYPES,
               customers=_logi.customers_for_picker())


# =====================================================
# v5H226z885 (대표 지시): 관리번호 '수동발행' — 엑셀 병행 기간(WORKS 완전도입 전) 번호 맞춤용.
#   지정 3명만 등록 시 관리번호를 직접 입력 가능. '수동발행' 체크→검증(형식·사업부문자 일치·중복·봉인)→적용.
#   자동발급이 쓸 접두(사업부문자)와 반드시 일치해야 함(대표 확정: 사업부 글자 일치 필수).
# =====================================================
# 대표 지정 3명 — (번호, 이름). ⚠대표가 '5 김정락' 처럼 준 번호가 '사번(=로그인ID)' 인지 'users.id' 인지 모호하므로
#   사번(employee_no)·로그인ID(username)·users.id 어느 쪽이든 번호가 맞고 + 이름까지 맞을 때만 허용(동일번호 타인 오탐 차단).
_MANUAL_MGMT_PEOPLE = [(5, "김정락"), (67, "안지연"), (306, "이새롬")]


_MANUAL_MGMT_TEAM_ID_Z90 = 1   # 기술영업팀 (teams.id=1 · code '01' · PUNIT_OWNER_TEAM_ID 와 같은 팀)


def _can_manual_mgmt_team_z90(u):
    """z1191z90: 기술영업팀 사람이면 True (팀 번호로만 판정 · 잠긴 계정은 get_user 가 이미 걸러 냄)."""
    try:
        return int((u or {}).get("team_id") or 0) == _MANUAL_MGMT_TEAM_ID_Z90
    except (TypeError, ValueError, AttributeError):
        return False


def _can_manual_mgmt(u):
    """관리번호 수동발행 권한 — 기술영업팀 전원(z1191z90) + 대표 지정 3명.
    ⚠대표가 준 '5 김정락' 등의 번호가 사번(=로그인ID)인지 users.id 인지 모호 → 둘 다 지원.
    ① 사번(employee_no)/로그인ID(username) 매칭 = 유일 식별자라 이름 확인 없이 허용(가장 유력·표기편차 안전).
    ② users.id 매칭 = 이 경우만 이름 일치까지 요구(동일 id 타인 오탐 차단)."""
    if not isinstance(u, dict):
        return False
    # z1191z90 (대표 11-21 「실무자들이 모두 사용할 때는 기술영업팀 사용자 모두 동일하게」 · 오늘 배포):
    #   기술영업팀(teams.id=1) 사람은 모두 수동발행 가능 — 각 영업 담당자가 엑셀에서 매긴 관리번호를 그대로 넣는 길.
    #   (지정 3명 목록은 그대로 둠 — 대표(총괄)는 기술영업팀이 아니어도 계속 가능)
    if _can_manual_mgmt_team_z90(u):
        return True
    _nums = {n for n, _ in _MANUAL_MGMT_PEOPLE}
    # ① 사번 / 로그인ID — 유일 식별자
    for _k in ("employee_no", "username"):
        _v = u.get(_k)
        if _v is None or str(_v).strip() == "":
            continue
        try:
            if int(str(_v).strip()) in _nums:
                return True
        except (ValueError, TypeError):
            pass
    # ② users.id — 이름 일치까지 요구(오탐 차단)
    _name = str(u.get("name") or "").replace(" ", "")
    try:
        _id = int(str(u.get("id")).strip())
    except (ValueError, TypeError):
        _id = None
    if _id is not None:
        for _num, _nm in _MANUAL_MGMT_PEOPLE:
            if _id == _num and _name and (_nm in _name):
                return True
    return False


def _expected_mgmt_letter(project_type, biz_div):
    """수동 관리번호의 사업부 글자 = 자동발급이 쓸 접두(projects_create_logi 동일 로직).
    기타(OTHER)→E · 소모품(CONSUMABLE)→C · 그 외(NEW_EQUIP)→사업부 T/M/L."""
    pt = (project_type or "NEW_EQUIP").strip().upper()
    if pt == "OTHER":
        return "E"
    if pt == "CONSUMABLE":
        return "C"
    bd = (biz_div or "T").strip().upper()
    return bd if bd in ("T", "M", "L") else "T"


def _validate_manual_mgmt_code(raw_code, expect_letter):
    """수동 관리번호 검증. 반환 (ok: bool, code_또는_사유: str).
    형식=NNN(1~4자리)+사업부문자+YYMM(월 01~12) · 사업부문자 일치 · 살아있는(숨김보관 포함) 프로젝트 중복만 차단.
    v5H226z940 (대표 지시): 완전삭제(봉인)됐던 번호라도 지금 그 번호를 쓰는 프로젝트가 없으면 재사용 허용(봉인 차단 제거)."""
    import re as _re
    code = (raw_code or "").strip().upper()
    if not code:
        return (False, "빈 값")
    m = _re.match(r"^(\d{1,4})([A-Z])(\d{2})(\d{2})$", code)
    if not m:
        return (False, "형식 오류 (예: 001T2607)")
    _letter, _mm = m.group(2), m.group(4)
    if not (1 <= int(_mm) <= 12):
        return (False, "형식 오류 (월 01~12)")
    if expect_letter and _letter != expect_letter:
        return (False, f"사업부 불일치 — 이 등록은 '{expect_letter}' 로 시작해야 합니다")
    with db_session() as c:
        # v5H226z1059 (대표 지시): '이미 사용 중'이라고만 하지 말고 **어디서 쓰는지** 알려준다.
        #   숨김보관(폐기)된 프로젝트는 목록·검색엔 안 뜨는데 여기선 막혀서 "안 나오는데 못 쓴다"고 헷갈렸다(001T2607=#1002).
        _pr = c.execute("SELECT id, COALESCE(name,'') AS name, COALESCE(is_archived,0) AS arch "
                        "FROM projects WHERE UPPER(COALESCE(mgmt_code,''))=? LIMIT 1", (code,)).fetchone()
        if _pr:
            _nm = ((_pr["name"] or "").strip() or "(이름 없음)")
            if int(_pr["arch"] or 0):
                return (False, f"숨김보관(폐기)된 프로젝트 '{_nm}' (#{_pr['id']}) 가 쓰는 번호 — 목록엔 안 보이지만 살아 있습니다. "
                               f"그 프로젝트를 완전삭제하면 이 번호를 쓸 수 있습니다.")
            return (False, f"이미 사용 중 — 프로젝트 '{_nm}' (#{_pr['id']}) 가 쓰는 번호입니다.")
        # v5H226z954 (대표 지시): 소모품(consumable_orders)도 같은 관리번호 체계 → 양쪽 중복 검사(소모품 번호는 거기 저장)
        try:
            _co = c.execute("SELECT id, COALESCE(co_no,'') AS co_no FROM consumable_orders "
                            "WHERE UPPER(COALESCE(mgmt_code,''))=? LIMIT 1", (code,)).fetchone()
            if _co:
                return (False, f"이미 사용 중 — 소모품 발주 {(_co['co_no'] or ('#' + str(_co['id'])))} 가 쓰는 번호입니다.")
        except Exception:
            pass
        # v5H226z940 (대표 지시): 완전삭제(봉인)됐던 번호도 '그 번호를 쓰는 살아있는(숨김보관 포함) 프로젝트가 없으면' 재사용 허용.
        #   (엑셀 병행 입력 중 실수로 만든 번호를 지우면 영영 못 쓰던 문제) — 위 projects 중복검사가 '겹치지 않으면'을 보장.
        #   → retired_mgmt_codes 봉인 차단 제거. (자동발번은 여전히 봉인 회피 유지 · 재사용 등록 시 봉인 자동 해제=핸들러)
    return (True, code)


@app.get("/api/mgmt-code/check")
async def api_mgmt_code_check(request: Request, code: str = "", biz_div: str = "", ptype: str = ""):
    """v5H226z885: 수동 관리번호 사용가능 검증(기술영업팀 전원 + 지정 3명 · z1191z90). 화면 [검증] 버튼이 호출."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    if not _can_manual_mgmt(u):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    _expect = _expected_mgmt_letter(ptype, biz_div)
    ok, msg = _validate_manual_mgmt_code(code, _expect)
    # v5H226z1059 (대표 지시): 막힌 번호가 '어디서 쓰이는지' 링크용 정보 — 화면에서 그 프로젝트/소모품으로 바로 가게.
    _used_by = None
    if not ok:
        _cc = (code or "").strip().upper()
        try:
            with db_session() as c:
                _pr = c.execute("SELECT id, COALESCE(name,'') AS name, COALESCE(is_archived,0) AS arch "
                                "FROM projects WHERE UPPER(COALESCE(mgmt_code,''))=? LIMIT 1", (_cc,)).fetchone()
                if _pr:
                    _used_by = {"type": "project", "id": _pr["id"],
                                "name": (_pr["name"] or ""), "archived": bool(int(_pr["arch"] or 0))}
                else:
                    _co = c.execute("SELECT id, COALESCE(co_no,'') AS co_no FROM consumable_orders "
                                    "WHERE UPPER(COALESCE(mgmt_code,''))=? LIMIT 1", (_cc,)).fetchone()
                    if _co:
                        _used_by = {"type": "consumable", "id": _co["id"], "name": (_co["co_no"] or "")}
        except Exception:
            _used_by = None
    return JSONResponse({"ok": True, "available": bool(ok), "expect": _expect,
                         "reason": ("" if ok else msg), "used_by": _used_by,
                         "code": (msg if ok else (code or "").strip().upper())})


# z1191z57 (대표 2026-11-18 등록 화면 ①②):
#   ① 「등록화면을 동시에 열리지 않게 · 누가 열고 작업중이면 누가 열고 있다고 안내」 → 프로젝트 등록 화면은 한 번에 한 사람.
#      화면이 20초마다 「작업 중」 신호(beat) → 75초 끊기면(창 닫힘·잠자기) 풀림 · 10분 동안 입력이 없고 다른 분이 기다리면 넘김.
#      잡은 사람에게는 「등록하면 이 번호」(다음 관리번호·수주번호)를 보여 준다 — 한 사람만 등록하니 보이는 번호 = 받는 번호.
#      잠금 = DB 표(일꾼 2개라 메모리로는 안 됨) · 같은 사람의 다른 탭은 같은 사람으로 본다.
#   ② 프로젝트명·모델명·장비명 옆 ⓘ = 입력 기준(등록 권한자 누구나 고침 · 고친 사람·시각·이력) + 최근 등록 예
import time as _z57_time
_Z57_LOCK = "project_new"
_Z57_TTL = 75
_Z57_IDLE = 600
# z1191z70 (대표 11-19): 잠금은 종류마다 따로 — 「project_new:T」·「:M」·「:L」·「:E」(관리번호·수주번호가 종류별 일련이라 서로 겹치지 않음)
_Z70_BIZ = {"T": "검사기", "M": "자동화", "L": "라이프밸류", "E": "기타"}


def _z70_name(biz):
    b = str(biz or "T").strip().upper()
    return "%s:%s" % (_Z57_LOCK, b if b in _Z70_BIZ else "T")


def _z70_ko(biz):
    b = str(biz or "T").strip().upper()
    return _Z70_BIZ.get(b, "검사기")


_Z57_GKEYS = {"project_name": ("프로젝트명", "name"), "model_name": ("모델명", "model_name"), "equip_name": ("장비명", "equip_name")}


def _z57_tables(c):
    c.execute("CREATE TABLE IF NOT EXISTS screen_locks(name TEXT PRIMARY KEY, user_id INTEGER, user_name TEXT, token TEXT, "
              "opened_at REAL, beat_at REAL, active_at REAL)")
    c.execute("CREATE TABLE IF NOT EXISTS screen_lock_waits(name TEXT, user_id INTEGER, user_name TEXT, beat_at REAL, PRIMARY KEY(name, user_id))")
    c.execute("CREATE TABLE IF NOT EXISTS field_guides(key TEXT PRIMARY KEY, body TEXT, updated_by INTEGER, updated_by_name TEXT, updated_at TEXT)")
    c.execute("CREATE TABLE IF NOT EXISTS field_guide_hist(id INTEGER PRIMARY KEY AUTOINCREMENT, key TEXT, body TEXT, by_id INTEGER, by_name TEXT, at TEXT)")


def _z57_hm(t):
    from datetime import datetime as _d57, timezone as _tz57, timedelta as _td57
    try:
        return _d57.fromtimestamp(float(t), _tz57(_td57(hours=9))).strftime("%H:%M")
    except Exception:
        return ""


def _z57_take(u, token, active=True, biz="T"):
    """등록 화면 잡기·신호(종류마다 따로 · z1191z70). 반환 {held, holder, since, idle_min, waiters, biz_ko}."""
    LK = _z70_name(biz)
    now = _z57_time.time()
    uid = int(u.get("id") or 0)
    nm = vname_full(u) or (u.get("name") or "")
    with db_session() as c:
        _z57_tables(c)
        c.execute("INSERT OR IGNORE INTO screen_locks(name, user_id, user_name, token, opened_at, beat_at, active_at) VALUES(?,?,?,?,?,?,?)",
                  (LK, uid, nm, token, now, now, now))
        cur = c.execute(
            "UPDATE screen_locks SET user_id=?, user_name=?, "
            "opened_at=CASE WHEN token=? THEN opened_at ELSE ? END, "
            "active_at=CASE WHEN token<>? OR ?=1 THEN ? ELSE active_at END, "
            "token=?, beat_at=? "
            "WHERE name=? AND (token=? OR user_id=? OR beat_at<? OR active_at<?)",
            (uid, nm, token, now, token, (1 if active else 0), now, token, now, LK, token, uid, now - _Z57_TTL, now - _Z57_IDLE))
        held = cur.rowcount == 1
        if held:
            c.execute("DELETE FROM screen_lock_waits WHERE name=? AND user_id=?", (LK, uid))
        else:
            c.execute("INSERT OR REPLACE INTO screen_lock_waits(name, user_id, user_name, beat_at) VALUES(?,?,?,?)", (LK, uid, nm, now))
        r = c.execute("SELECT user_name, opened_at, active_at FROM screen_locks WHERE name=?", (LK,)).fetchone()
        waiters = [x[0] for x in c.execute("SELECT user_name FROM screen_lock_waits WHERE name=? AND beat_at>? AND user_id<>? ORDER BY beat_at",
                                            (LK, now - 30, uid)).fetchall()] if held else []
    return {"held": held, "holder": (r[0] if r else ""), "since": _z57_hm(r[1]) if r else "",
            "idle_min": (int((now - float(r[2] or now)) // 60) if r else 0), "waiters": waiters, "biz_ko": _z70_ko(biz)}


def _z57_next_numbers(biz_div, ptype, po_type, order_date, manual):
    """잡은 사람에게 보여 줄 다음 번호 — 저장 때와 같은 함수(관리번호 = 오늘 연월 · 수주번호 = 발주일, 비면 오늘)."""
    out = {"mgmt": "", "so": ""}
    bd = (biz_div or "T").strip().upper()
    try:
        if (po_type or "신규") == "신규" and not manual:
            out["mgmt"] = _logi.generate_mgmt_code(_expected_mgmt_letter(ptype, bd))
    except Exception as e:
        print(f"[z1191z57] 다음 관리번호 계산 실패: {e}")
    try:
        from datetime import date as _dd57, datetime as _dt57
        try:
            od = _dt57.strptime(str(order_date or "")[:10], "%Y-%m-%d").date()
        except Exception:
            od = _dd57.today()
        with db_session() as c:
            out["so"] = _pwf.generate_so_no(c, (bd if bd in ("T", "M", "L", "E", "C") else "T"), od)
    except Exception as e:
        print(f"[z1191z57] 다음 수주번호 계산 실패: {e}")
    return out


def _z57_lock_other(u, token, biz="T"):
    """저장 직전 확인: 같은 종류(z1191z70)를 다른 사람이 살아 있는 잠금으로 쥐고 있으면 그 사람 이름 · 아니면 ''."""
    now = _z57_time.time()
    with db_session() as c:
        _z57_tables(c)
        r = c.execute("SELECT user_id, user_name, token, beat_at FROM screen_locks WHERE name=?", (_z70_name(biz),)).fetchone()
    if not r or float(r[3] or 0) < now - _Z57_TTL:
        return ""
    if (token and r[2] == token) or int(r[0] or 0) == int(u.get("id") or 0):
        return ""
    return r[1] or "다른 분"


def _z57_guides():
    out = {k: {"label": v[0], "body": "", "by": "", "at": ""} for k, v in _Z57_GKEYS.items()}
    try:
        with db_session() as c:
            _z57_tables(c)
            for r in c.execute("SELECT key, COALESCE(body,''), COALESCE(updated_by_name,''), COALESCE(updated_at,'') FROM field_guides").fetchall():
                if r[0] in out:
                    out[r[0]].update({"body": r[1], "by": r[2], "at": r[3]})
    except Exception as e:
        print(f"[z1191z57] 입력 기준 읽기 실패: {e}")
    return out


@app.post("/api/project-reg-lock/beat")
async def api_z57_lock_beat(request: Request):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"ok": False, "error": "permission_denied"}, 403)
    try:
        b = await request.json()
    except Exception:
        b = {}
    tok = str(b.get("token") or "").strip()[:64]
    if len(tok) < 8:
        return JSONResponse({"ok": False, "error": "bad_token"}, 400)
    st = _z57_take(u, tok, active=bool(b.get("active")), biz=b.get("biz_div"))
    if st["held"]:
        st.update(_z57_next_numbers(b.get("biz_div"), b.get("ptype"), b.get("po_type"), b.get("order_date"), bool(b.get("manual"))))
    st["ok"] = True
    return JSONResponse(st)


@app.post("/api/project-reg-lock/release")
async def api_z57_lock_release(request: Request):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False}, 401)
    try:
        import json as _j57
        b = _j57.loads((await request.body()).decode("utf-8") or "{}")
    except Exception:
        b = {}
    tok = str(b.get("token") or "").strip()[:64]
    with db_session() as c:
        _z57_tables(c)
        if tok:   # z1191z70: 이 화면이 잡은 잠금(종류마다 따로)을 푼다
            c.execute("UPDATE screen_locks SET beat_at=0, active_at=0 WHERE token=? AND (name=? OR name LIKE ?)", (tok, _Z57_LOCK, _Z57_LOCK + ":%"))
        if b.get("biz_div"):
            c.execute("DELETE FROM screen_lock_waits WHERE name=? AND user_id=?", (_z70_name(b.get("biz_div")), int(u.get("id") or 0)))
        else:
            c.execute("DELETE FROM screen_lock_waits WHERE (name=? OR name LIKE ?) AND user_id=?", (_Z57_LOCK, _Z57_LOCK + ":%", int(u.get("id") or 0)))
    return JSONResponse({"ok": True})


@app.get("/api/field-guides/examples")
async def api_z57_guide_examples(request: Request, key: str = "", biz: str = ""):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False}, 401)
    if key not in _Z57_GKEYS:
        return JSONResponse({"ok": False, "error": "bad_key"}, 400)
    col = _Z57_GKEYS[key][1]
    bz = (biz or "").strip().upper()
    seen, items = set(), []
    with db_session() as c:
        sql = (f"SELECT mgmt_code, {col} FROM projects WHERE COALESCE(is_archived,0)=0 AND COALESCE(TRIM({col}),'')<>'' "
               + ("AND biz_div=? " if bz in ("T", "M", "L", "E") else "") + "ORDER BY id DESC LIMIT 200")
        for r in c.execute(sql, ((bz,) if bz in ("T", "M", "L", "E") else ())).fetchall():
            v = str(r[1] or "").strip()
            if v.lower() in seen:
                continue
            seen.add(v.lower()); items.append({"mgmt": r[0] or "", "v": v[:120]})
            if len(items) >= 8:
                break
    return JSONResponse({"ok": True, "items": items})


@app.get("/api/field-guides/{key}/history")
async def api_z57_guide_history(request: Request, key: str):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False}, 401)
    if key not in _Z57_GKEYS:
        return JSONResponse({"ok": False, "error": "bad_key"}, 400)
    with db_session() as c:
        _z57_tables(c)
        rows = [{"body": r[0] or "", "by": r[1] or "", "at": r[2] or ""} for r in c.execute(
            "SELECT body, by_name, at FROM field_guide_hist WHERE key=? ORDER BY id DESC LIMIT 10", (key,)).fetchall()]
    return JSONResponse({"ok": True, "items": rows})


@app.post("/api/field-guides/{key}")
async def api_z57_guide_save(request: Request, key: str):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    if not can_use_sales(u):   # 등록 권한 있는 사람 모두(대표 11-18)
        return JSONResponse({"ok": False, "error": "등록 권한이 있는 분만 기준을 고칠 수 있습니다"}, 403)
    if key not in _Z57_GKEYS:
        return JSONResponse({"ok": False, "error": "bad_key"}, 400)
    try:
        b = await request.json()
    except Exception:
        b = {}
    body = str(b.get("body") or "").replace("\r\n", "\n").strip()[:2000]
    from datetime import datetime as _d57s, timezone as _tz57s, timedelta as _td57s
    at = _d57s.now(_tz57s(_td57s(hours=9))).strftime("%Y-%m-%d %H:%M")
    nm = vname_full(u) or (u.get("name") or "")
    with db_session() as c:
        _z57_tables(c)
        old = c.execute("SELECT COALESCE(body,'') FROM field_guides WHERE key=?", (key,)).fetchone()
        if old and (old[0] or "") == body:
            return JSONResponse({"ok": True, "same": True, "guide": {"body": body}})
        c.execute("INSERT INTO field_guides(key, body, updated_by, updated_by_name, updated_at) VALUES(?,?,?,?,?) "
                  "ON CONFLICT(key) DO UPDATE SET body=excluded.body, updated_by=excluded.updated_by, "
                  "updated_by_name=excluded.updated_by_name, updated_at=excluded.updated_at",
                  (key, body, u.get("id"), nm, at))
        c.execute("INSERT INTO field_guide_hist(key, body, by_id, by_name, at) VALUES(?,?,?,?,?)", (key, body, u.get("id"), nm, at))
    return JSONResponse({"ok": True, "guide": {"label": _Z57_GKEYS[key][0], "body": body, "by": nm, "at": at}})


# z1191z61 (대표 2026-11-18 「이화면에서 견적서 등록을 할수있게 만들어서 기존 견적서를 등록하면 견적서에 기록되어있는
#   기본적인 정보들이 자동으로 작성될수있게」): 등록 화면 「📄 견적서로 채우기」.
#   · 올리면 바로 읽어(app/quote_reader.py · AI) 빈 칸만 채운다 — 사람이 확인하고 [등록]
#   · 올린 파일은 표 project_quote_files 에 「아직 프로젝트 없음」으로 두었다가 등록되는 순간 그 프로젝트에 붙는다(대표 「첨부로 보관」)
#   · 파일은 data/project_quotes/ (공개 /uploads 아님) — 단가가 있어 금액 볼 권한(can_view_sales)이 있어야 열린다
#   · 등록 안 하고 떠난 파일은 3일 뒤 지운다(다음에 누가 올릴 때)
from . import quote_reader as _qr61

# z1191z76 (대표 11-19 「견적서 등록은 무조건 엑셀파일만 … 최종 견적서를 등록을해야 향후에 수정할때 최종을 수정할수있어 …
#   등록한 엑셀파일은 다운로드 할수있게」): 올리는 곳(등록·수정 「견적서로 채우기」 · 상세 「＋ 견적서 올리기」) 모두 엑셀만.
#   이름(확장자)만 바꾼 PDF·사진도 막는다 — 엑셀 파일의 첫 바이트(xlsx·xlsm = ZIP 「PK」 · xls·암호 걸린 엑셀 = 「D0 CF 11 E0」)로 확인.
_Z76_XL_EXTS = (".xlsx", ".xlsm", ".xls")
_Z76_XL_MSG = "견적서는 엑셀 파일(xlsx·xls)만 올릴 수 있습니다 — 나중에 고칠 때 최종 견적서를 그대로 고칠 수 있게 엑셀로 보관합니다."


def _z76_is_excel(name, raw):
    """엑셀만 — 확장자 + 파일 첫 바이트. 맞으면 True."""
    if _qr61.ext_of(name or "") not in _Z76_XL_EXTS:
        return False
    head = bytes(raw[:8] or b"")
    return head.startswith(b"PK\x03\x04") or head.startswith(b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1")


def _z61_now():
    from datetime import datetime as _d61, timezone as _tz61, timedelta as _td61
    return _d61.now(_tz61(_td61(hours=9))).strftime("%Y-%m-%d %H:%M")


def _z61_dir():
    from . import database as _db61
    return os.path.join(os.path.dirname(os.path.abspath(_db61.DB_PATH)), "project_quotes")


def _z61_table(c):
    c.execute("""CREATE TABLE IF NOT EXISTS project_quote_files (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        tok TEXT UNIQUE NOT NULL,
        project_id INTEGER,
        orig_name TEXT, stored TEXT, size INTEGER, sha256 TEXT,
        by_id INTEGER, by_name TEXT, created_at TEXT, attached_at TEXT,
        read_json TEXT)""")
    c.execute("CREATE INDEX IF NOT EXISTS ix_pqf_project ON project_quote_files(project_id)")
    _cols = {r[1] for r in c.execute("PRAGMA table_info(project_quote_files)").fetchall()}   # z1191z63: 빼기(숨김) · 누가
    for _cn, _ct in (("removed_at", "TEXT"), ("removed_by", "INTEGER"), ("removed_by_name", "TEXT"),
                     # z1191z105: 수주번호 자리 · 견적 금액 ≠ 수주 금액 「확인했음」 누가·언제
                     # (z1191z156: 새로 올리는 견적서는 모두 order_id 를 가짐 — 비어 있는 것은 옛 자료뿐 · 「⚠ 수주 칸 확인 필요」에서 고름)
                     ("order_id", "INTEGER"), ("amt_ack_by", "INTEGER"), ("amt_ack_name", "TEXT"), ("amt_ack_at", "TEXT")):
        if _cn not in _cols:
            c.execute(f"ALTER TABLE project_quote_files ADD COLUMN {_cn} {_ct}")
    c.execute("CREATE INDEX IF NOT EXISTS ix_pqf_order ON project_quote_files(order_id)")   # z1191z105


def _z61_cleanup(c):
    """등록 안 하고 3일 지난 파일 지우기(행+파일)."""
    from datetime import datetime as _d61, timedelta as _td61
    cut = (_d61.strptime(_z61_now(), "%Y-%m-%d %H:%M") - _td61(days=3)).strftime("%Y-%m-%d %H:%M")
    # z1191z64 (대표 「30일 보관도 하지마」): 뺀 것은 날짜 상관없이 바로 지움(z63 때 빼 둔 것 포함)
    rows = c.execute("SELECT id, stored FROM project_quote_files WHERE (project_id IS NULL AND created_at < ?) "
                     "OR removed_at IS NOT NULL", (cut,)).fetchall()
    for r in rows:
        try:
            fp = os.path.join(_z61_dir(), r[1] or "")
            if r[1] and os.path.isfile(fp):
                os.remove(fp)
        except Exception as _e:
            print(f"[z1191z61] 지난 파일 지우기 실패 {r[1]}: {_e}")
        c.execute("DELETE FROM project_quote_files WHERE id=?", (r[0],))


def _z61_norm_co(s):
    import unicodedata as _ud61, re as _re61
    s = _ud61.normalize("NFC", str(s or "")).lower()
    s = _re61.sub(r"\(주\)|㈜|주식회사|\(유\)|유한회사|co\.?,?\s*ltd\.?|ltd\.?|inc\.?|corp\.?|công\s*ty\s*tnhh|cong\s*ty\s*tnhh|귀중", "", s)
    return _re61.sub(r"[\s\.\,\-_()\[\]·]", "", s)


def _z61_match_customer(c, name):
    """견적서의 업체명 → 등록 고객사. 정확히 하나면 {id,label} · 아니면 후보(최대 6)만."""
    out = {"id": None, "label": "", "cands": []}
    key = _z61_norm_co(name)
    if not key:
        return out
    cols = {r[1] for r in c.execute("PRAGMA table_info(customers)").fetchall()}
    _al = "alias" if "alias" in cols else "''"
    _sb = "sub_biz_no" if "sub_biz_no" in cols else "''"
    rows = c.execute(f"SELECT id, name, COALESCE({_al},'') AS alias, COALESCE({_sb},'') AS sb FROM customers "
                     "WHERE COALESCE(is_active,1)=1").fetchall()

    def _lab(r):
        return (r["alias"] or r["name"] or "") + (f" [{r['sb']}]" if r["sb"] else "")
    exact = [r for r in rows if _z61_norm_co(r["name"]) == key or (r["alias"] and _z61_norm_co(r["alias"]) == key)]
    if len(exact) == 1:
        out["id"], out["label"] = exact[0]["id"], _lab(exact[0])
        return out
    pool = exact or [r for r in rows if len(key) >= 2 and (
        key in _z61_norm_co(r["name"]) or (r["alias"] and key in _z61_norm_co(r["alias"]))
        or (len(_z61_norm_co(r["name"])) >= 2 and _z61_norm_co(r["name"]) in key))]
    out["cands"] = [{"id": r["id"], "label": _lab(r)} for r in pool[:6]]
    return out


@app.post("/api/project-quote/read")
async def api_project_quote_read(req: Request, file: UploadFile = File(...)):
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"ok": False, "error": "forbidden", "message": "등록 권한이 없습니다."}, 403)
    name = _qr61._nfc(file.filename or "견적서")[:200]
    ext = _qr61.ext_of(name)
    if ext not in _Z76_XL_EXTS:   # z1191z76: 엑셀만
        return JSONResponse({"ok": False, "error": "ext", "message": _Z76_XL_MSG})
    raw = await file.read(_qr61.MAX_BYTES + 1)
    if not raw:
        return JSONResponse({"ok": False, "error": "empty", "message": "빈 파일입니다."})
    if len(raw) > _qr61.MAX_BYTES:
        return JSONResponse({"ok": False, "error": "big", "message": "20MB 보다 큰 파일은 올릴 수 없습니다."})
    if not _z76_is_excel(name, raw):   # z1191z76: 이름만 엑셀인 다른 파일
        return JSONResponse({"ok": False, "error": "ext", "message": "엑셀 파일이 아닙니다(이름만 .xlsx 인 PDF·사진 등) — " + _Z76_XL_MSG})
    import secrets as _sc61, hashlib as _hl61
    tok = _sc61.token_hex(12)
    sub = _z61_now()[:7].replace("-", "")
    stored = f"{sub}/{tok}{ext}"
    try:
        os.makedirs(os.path.join(_z61_dir(), sub), exist_ok=True)
        with open(os.path.join(_z61_dir(), stored), "wb") as _f61:
            _f61.write(raw)
    except Exception as _e:
        print(f"[z1191z61] 파일 저장 실패: {_e}")
        return JSONResponse({"ok": False, "error": "save", "message": "파일을 서버에 저장하지 못했습니다 — 다시 올려 주세요."})
    from starlette.concurrency import run_in_threadpool as _rit61
    rd = await _rit61(_qr61.read_quote, raw, name)   # AI 기다림은 DB 를 잡기 전에(쓰기 잠금 쥔 채 기다리지 않기)
    with db_session() as c:
        _z61_table(c)
        try:
            _z61_cleanup(c)
        except Exception as _e:
            print(f"[z1191z61] 정리 실패: {_e}")
        c.execute("INSERT INTO project_quote_files(tok, orig_name, stored, size, sha256, by_id, by_name, created_at, read_json) "
                  "VALUES(?,?,?,?,?,?,?,?,?)",
                  (tok, name, stored, len(raw), _hl61.sha256(raw).hexdigest(), u.get("id"),
                   vname_full(u) or u.get("name"), _z61_now(), _qr61.dumps(rd)))
        _rep121 = _z61_reply(c, u, rd, tok, name, len(raw))
    await _z121_index_tok(tok, raw, name)   # z1191z121: 견적서 내용(앞장·항목·시트) 읽어 두기
    return JSONResponse(_rep121)


def _z61_reply(c, u, rd, tok, name, size):
    """읽기 결과 → 화면 답(올리기 · 비밀번호로 다시 읽기 같은 모양). 비밀번호는 rd 에 없다."""
    f = rd.get("fields") or {}
    warns = rd.get("warnings") or []
    if not can_view_sales(u):   # 금액 볼 권한이 없으면 단가·금액·통화는 돌려주지 않는다(등록 화면에도 그 칸이 없다)
        f = {k: v for k, v in f.items() if k not in ("unit_price", "amount", "currency")}
        warns = [w for w in warns if "금액" not in w]
    cust = _z61_match_customer(c, f.get("customer")) if f.get("customer") else {"id": None, "label": "", "cands": []}
    return {"ok": True, "read_ok": bool(rd.get("ok")), "tok": tok, "name": name, "size": size,
            "need_password": bool(rd.get("need_password")), "bad_password": bool(rd.get("bad_password")),
            "fields": f, "warnings": warns, "message": rd.get("message") or "", "cust": cust}


@app.post("/api/project-quote/reread")
async def api_project_quote_reread(req: Request):
    """z1191z62 (대표 11-18 「암호가 걸려있는 엑셀을 넣으면 업로드 화면에서 비밀번호를 입력하고 등록」):
    올린 파일(표지) + 비밀번호 → 풀어서 다시 읽기. 비밀번호는 읽는 데만 쓰고 저장·기록하지 않는다."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"ok": False, "error": "forbidden", "message": "등록 권한이 없습니다."}, 403)
    form = await req.form()
    tok = (form.get("tok") or "").strip()[:40]
    pw = form.get("password") or ""
    if not tok or not pw:
        return JSONResponse({"ok": False, "message": "비밀번호를 넣어 주세요."})
    with db_session() as c:
        _z61_table(c)
        r = c.execute("SELECT orig_name, stored, size, by_id, project_id FROM project_quote_files WHERE tok=?", (tok,)).fetchone()
    if not r or r["by_id"] != u.get("id") or r["project_id"] is not None:
        return JSONResponse({"ok": False, "message": "그 견적서를 찾지 못했습니다 — 다시 올려 주세요."})
    try:
        with open(os.path.join(_z61_dir(), r["stored"]), "rb") as _f62:
            raw = _f62.read()
    except Exception:
        return JSONResponse({"ok": False, "message": "그 견적서 파일을 찾지 못했습니다 — 다시 올려 주세요."})
    from starlette.concurrency import run_in_threadpool as _rit62
    rd = await _rit62(_qr61.read_quote, raw, r["orig_name"], pw)
    if not rd.get("bad_password"):
        await _z121_index_tok(tok, raw, r["orig_name"], pw)   # z1191z121: 같은 비밀번호로 내용도 읽어 둔다(저장 안 함)
    pw = None
    with db_session() as c:
        c.execute("UPDATE project_quote_files SET read_json=? WHERE tok=?", (_qr61.dumps(rd), tok))
        return JSONResponse(_z61_reply(c, u, rd, tok, r["orig_name"], r["size"]))


# ═══ z1191z156 (대표 11-25 정하고 11-26 「진행하자」): 견적서·고객 발주서 = 수주번호(orders.id)에만 붙인다
#   · 수주 1개 관리번호 = 그 수주를 미리 고름(바꿀 수 있음) · 수주 2개 이상 = 빈칸으로 시작 → 안 고르고 올리면 저장하지 않고 「👉 수주번호를 골라 주세요」
#   · 관리번호에만 붙이는 길(order_id 비움)은 없앰 — 새로 올리는 모든 길이 order_id 를 갖는다
#   · 옛 자료(order_id 없음)는 저절로 아무 수주에나 붙이지 않음 → 「⚠ 수주 칸 확인 필요」(/projects/so-check)에서 사람이 수주를 고름(이력 남김)
_Z156_NEED_SO = "👉 수주번호를 골라 주세요 — 견적서·발주서는 수주번호에만 붙습니다."
_Z156_NO_SO = "👉 이 관리번호에는 아직 수주번호가 없습니다 — 수주를 먼저 등록한 뒤 올려 주세요(견적서·발주서는 수주번호에만 붙습니다)."


def _z156_sos(c, pid):
    """취소 뺀 수주 [{id, order_no}] — 발주일·번호 순."""
    return [dict(r) for r in c.execute("SELECT id, order_no FROM orders WHERE project_id=? AND COALESCE(status,'')<>'CANCELLED' "
                                       "ORDER BY COALESCE(order_date,''), id", (int(pid),)).fetchall()]


def _z156_pick(c, pid, oid_raw, need_explicit=False):
    """붙일 수주 → (oid, 멈춤 답 dict 또는 None).
    고른 수주가 있으면 이 관리번호의 취소 안 된 수주인지 확인 · 안 골랐으면 수주가 딱 1개일 때만 그 수주(need_explicit 이면 그것도 안 함)
    · 수주 0개·2개 이상이면 멈춤(저장하지 않음 · 화면이 「👉 수주번호를 골라 주세요」)."""
    sos = _z156_sos(c, pid)
    try:
        oid = int(str(oid_raw or "").strip() or 0) or None
    except (TypeError, ValueError):
        oid = None
    if oid:
        if any(o["id"] == oid for o in sos):
            return oid, None
        return None, {"ok": False, "need_so": True, "sos": sos,
                      "message": "👉 그 수주번호는 이 관리번호에 없습니다(취소된 수주일 수 있습니다) — 수주번호를 다시 골라 주세요."}
    if not sos:
        return None, {"ok": False, "no_so": True, "sos": [], "message": _Z156_NO_SO}
    if len(sos) == 1 and not need_explicit:
        return sos[0]["id"], None
    return None, {"ok": False, "need_so": True, "sos": sos, "message": _Z156_NEED_SO}


def _z156_sos_view(pid):
    """화면 「수주번호 고르기」 칸 — [{id, order_no, units}] (취소 뺌)."""
    try:
        with db_session() as c:
            out = _z156_sos(c, pid)
            for o in out:
                o["units"] = _z105_units_txt([x[0] for x in c.execute("SELECT unit_label FROM order_items WHERE order_id=? ORDER BY id", (o["id"],))])
            return out
    except Exception as _e:
        print(f"[z1191z156] 수주 목록 실패 pid={pid}: {_e}")
        return []


tpl.env.globals["z156_sos"] = _z156_sos_view


