# z1191z63 (대표 11-18 「견적을 잘못 올려서 삭제할려면」 → 「견적빼기는 견적 등록하는 화면에는 무조건 넣어줘」
#   → 「빼기는 올린사람 또는 관리자 기술영업팀 인원(등록,빼기할때 항상 누가 했는지 이력 남길것)」 → 「견적은 관리자는 빼자」):
#   뺄 수 있는 사람 = 올린 사람 · 기술영업팀(관리자·대표 계정은 남의 것 못 뺌)
#   빼기 = 화면에서 숨김(removed_at·누가) + 프로젝트 변경 이력(누가) · 파일은 30일 보관 뒤 지움 · 「되돌리기」도 같은 사람들 · 이력
def _z63_is_tech_sales(u):
    try:
        tid = (u or {}).get("team_id")
        if not tid:
            return False
        with db_session() as c:
            r = c.execute("SELECT name FROM teams WHERE id=?", (int(tid),)).fetchone()
        return bool(r and "기술영업" in (r["name"] or ""))
    except Exception as _e:
        print(f"[z1191z63] 팀 확인 실패: {_e}")
        return False


def _z63_can_remove(u, row):
    """올린 사람 본인 · 기술영업팀 — 그리고 견적서를 볼 수 있는 사람(금액 권한).
    대표 11-18 「견적은 관리자는 빼자」: 관리자·대표 계정이라고 남의 견적서를 빼지는 못한다(자기가 올린 것은 뺄 수 있음)."""
    if not u or not can_view_sales(u):
        return False
    if row and row.get("by_id") and row.get("by_id") == u.get("id"):
        return True
    return _z63_is_tech_sales(u)


tpl.env.globals["z63_can_remove"] = _z63_can_remove


def _z64_drop(c, fid, stored):
    """견적서 파일·줄을 바로 지움(되돌릴 수 없음 — 대표 「되돌리기 기능은 삭제 · 30일 보관도 하지마」)."""
    try:
        fp = os.path.join(_z61_dir(), stored or "")
        if stored and os.path.isfile(fp):
            os.remove(fp)
    except Exception as _e:
        print(f"[z1191z64] 견적서 파일 지우기 실패 {stored}: {_e}")
    c.execute("DELETE FROM project_quote_files WHERE id=?", (fid,))


@app.post("/api/project-quote/remove/{fid}")
async def api_project_quote_remove(req: Request, fid: int):
    """z1191z63·z64: 견적서 빼기 — 올린 사람·기술영업팀만 · 파일·줄 바로 지움 · 변경 이력에 누가(이름·번호)."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    with db_session() as c:
        _z61_table(c)
        r = c.execute("SELECT id, project_id, orig_name, stored, by_id FROM project_quote_files WHERE id=?", (fid,)).fetchone()
        if not r or r["project_id"] is None:
            return JSONResponse({"ok": False, "message": "그 견적서를 찾지 못했습니다(이미 뺐을 수 있습니다)."}, 404)
        if not _z63_can_remove(u, dict(r)):
            return JSONResponse({"ok": False, "message": "견적서는 올린 사람과 기술영업팀만 뺄 수 있습니다."}, 403)
        who = vname_full(u) or u.get("name")
        c.execute("INSERT INTO project_history(project_id, changed_by, field, old_value, new_value, note) VALUES(?,?,?,?,?,?)",
                  (r["project_id"], u.get("id"), "견적서 파일", r["orig_name"], "", f"z1191z63 견적서 빼기 · {who}"))
        _z64_drop(c, r["id"], r["stored"])
    return JSONResponse({"ok": True})


@app.get("/api/project-quote/{tok}")
async def api_project_quote_state(req: Request, tok: str):
    """등록 화면을 다시 열었을 때(쓰다 만 내용 복원) 그 견적서가 아직 붙을 수 있는지."""
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    with db_session() as c:
        _z61_table(c)
        r = c.execute("SELECT orig_name, project_id, by_id FROM project_quote_files WHERE tok=?", (tok[:40],)).fetchone()
    if not r or r["by_id"] != u.get("id"):
        return JSONResponse({"ok": True, "usable": False})
    return JSONResponse({"ok": True, "usable": r["project_id"] is None, "name": r["orig_name"]})


def _z61_attach(pid, tok, u, note="z1191z61 등록 화면 「견적서로 채우기」", order_id=None, exclude_ids=None, new_after=None):
    """등록·수정된 프로젝트에 견적서 붙이기 — 올린 사람 본인 · 아직 안 붙은 것만. 실패해도 저장은 막지 않는다.
    z1191z156: 수주번호에만 붙임 → True · 붙이지 못함 → False · 수주를 골라야 하는데 안 골랐음 → "need_so"(파일은 그대로 남김 · 저장 안 함)
      · 새 등록(exclude_ids = 추가 품목 수주 · new_after = 등록 전 가장 큰 수주 id) = 이번 등록으로 만든 수주(추가 품목 수주 뺀 것)가 딱 하나일 때 그 수주
        (추가 발주 = 같은 관리번호에 새 수주 — 앞 수주에는 붙이지 않음)
      · 수정 = 고른 수주(order_id) · 안 골랐으면 수주가 딱 하나일 때만 그 수주"""
    tok = (tok or "").strip()[:40]
    if not pid or not tok:
        return False
    try:
        with db_session() as c:
            _z61_table(c)
            r = c.execute("SELECT id, orig_name FROM project_quote_files WHERE tok=? AND project_id IS NULL AND by_id=?",
                          (tok, (u or {}).get("id"))).fetchone()
            if not r:
                return False
            if exclude_ids is not None and not order_id:   # 새 등록
                _ex156 = {int(x) for x in exclude_ids if str(x).strip().isdigit()}
                _main156 = [o for o in _z156_sos(c, pid) if o["id"] not in _ex156 and (new_after is None or o["id"] > int(new_after))]
                _oid156 = _main156[0]["id"] if len(_main156) == 1 else None
                if not _oid156:
                    print(f"[z1191z156] 새 등록 견적서 — 이번 수주를 하나로 못 정함(수주 {len(_main156)}개) pid={pid} · 붙이지 않음")
                    return "need_so" if _main156 else False
            else:
                _oid156, _err156 = _z156_pick(c, pid, order_id)
                if _err156:
                    print(f"[z1191z156] 견적서 붙이기 멈춤 pid={pid}: {_err156.get('message')}")
                    return "need_so" if _err156.get("need_so") else False
            _so156 = (c.execute("SELECT order_no FROM orders WHERE id=?", (_oid156,)).fetchone() or [""])[0] or ""
            # z1191z160: 그 수주에 이미 견적서가 있어도 지우지 않고 함께 남김(여러 장)
            c.execute("UPDATE project_quote_files SET project_id=?, order_id=?, attached_at=? WHERE id=?", (int(pid), _oid156, _z61_now(), r["id"]))
            c.execute("INSERT INTO project_history(project_id, changed_by, field, old_value, new_value, note) VALUES(?,?,?,?,?,?)",
                      (int(pid), (u or {}).get("id"), "견적서 파일", "", r["orig_name"], f"{note} · 수주 {_so156} · {vname_full(u or {}) or (u or {}).get('name') or ''}"))   # z1191z63: 누가
        return True
    except Exception as _e:
        print(f"[z1191z61] 견적서 붙이기 실패 pid={pid}: {_e}")
        return False


def _z61_quote_files(pid):
    try:
        with db_session() as c:
            _z61_table(c)
            for _r64 in c.execute("SELECT id, stored FROM project_quote_files WHERE project_id=? AND removed_at IS NOT NULL", (int(pid),)).fetchall():
                _z64_drop(c, _r64["id"], _r64["stored"])   # z1191z64: z63 때 숨겨 둔 것 → 바로 지움
            out = []
            # z1191z156: 수주번호마다 붙은 견적서 전부(수주 발주일 순) · 수주를 안 고른 옛 것(order_id 없음)은 맨 위에 ⚠ 로
            for r in c.execute("SELECT f.id, f.order_id, f.orig_name, f.size, f.by_id, f.by_name, f.created_at, f.read_json, o.order_no "
                               "FROM project_quote_files f LEFT JOIN orders o ON o.id=f.order_id "
                               "WHERE f.project_id=? AND f.removed_at IS NULL "
                               "ORDER BY (f.order_id IS NOT NULL), COALESCE(o.order_date,''), f.order_id, f.id DESC",   # z1191z160: 수주 안에서 최근 위
                               (int(pid),)).fetchall():
                x = dict(r)
                x["no_so"] = not x.get("order_id")
                try:   # z1191z62 (대표 「등록된 견적은 프로젝트 정보에서 볼수있게」): 읽은 값 요약(품명·금액·견적일)
                    rj = _qr61.json.loads(x.pop("read_json") or "{}")
                except Exception:
                    rj = {}
                fd = rj.get("fields") or {}
                x["item"] = fd.get("item_name") or ""
                x["qdate"] = fd.get("quote_date") or ""
                x["amount"] = fd.get("amount")
                x["cur"] = fd.get("currency") or ""
                x["locked"] = bool(rj.get("locked") or rj.get("need_password"))
                x["kind"] = "pdf" if (x["orig_name"] or "").lower().endswith(".pdf") else ("img" if _qr61.ext_of(x["orig_name"] or "") in (".png", ".jpg", ".jpeg") else "file")
                out.append(x)
            # z1191z160 (대표 11-26 「여러 개가 등록될 수도 있어」): 한 수주에 여러 장이면 모두 같은 자격 — 「최신」 표시 없음
            return out
    except Exception as _e:
        print(f"[z1191z61] 견적서 목록 실패 pid={pid}: {_e}")
        return []


tpl.env.globals["z61_quote_files"] = _z61_quote_files

