@app.post("/api/so-check-file/{kind}/{fid}")
async def api_so_check_file_z156(request: Request, kind: str, fid: int):
    """z1191z156: 수주번호 없이 관리번호에만 붙은 옛 견적서·고객 발주서 → 사람이 고른 수주번호에 붙임(이력 남김).
    수주는 반드시 사람이 고른 것만(수주가 하나여도 화면이 미리 골라 둔 것을 사람이 눌러야 함).
    z1191z160: 그 수주에 이미 견적서가 있어도 막지 않고 함께 붙임(여러 장 · 아무것도 지우지 않음)."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인이 필요합니다."}, 401)
    if not (can_use_sales(u) and can_view_sales(u)):
        return JSONResponse({"ok": False, "message": "권한이 없습니다."}, 403)
    if kind not in ("quote", "po"):
        return JSONResponse({"ok": False, "message": "알 수 없는 요청입니다."}, 400)
    form = await request.form()
    who = vname_full(u) or u.get("name") or ""
    tbl = "project_quote_files" if kind == "quote" else "project_po_files"
    with db_session() as c:
        _z61_table(c)
        _po143.table(c)
        r = c.execute(f"SELECT id, project_id, orig_name FROM {tbl} WHERE id=? AND project_id IS NOT NULL AND order_id IS NULL"
                      + (" AND removed_at IS NULL" if kind == "quote" else ""), (int(fid),)).fetchone()
        if not r:
            return JSONResponse({"ok": False, "message": "그 파일을 찾지 못했습니다(이미 수주번호를 골랐거나 뺐을 수 있습니다) — 화면을 다시 불러오세요."}, 409)
        oid, err = _z156_pick(c, r["project_id"], form.get("order_id"), need_explicit=True)
        if err:
            return JSONResponse(err)
        ono = c.execute("SELECT order_no FROM orders WHERE id=?", (oid,)).fetchone()[0] or ""
        n = c.execute(f"UPDATE {tbl} SET order_id=? WHERE id=? AND order_id IS NULL", (oid, int(fid))).rowcount
        if not n:
            return JSONResponse({"ok": False, "message": "이미 수주번호가 정해졌습니다 — 화면을 다시 불러오세요."}, 409)
        lb = "견적서 파일" if kind == "quote" else "고객 발주서"
        c.execute("INSERT INTO project_history(project_id, changed_by, field, old_value, new_value, note) VALUES(?,?,?,?,?,?)",
                  (r["project_id"], u.get("id"), lb + " 수주번호", "(수주번호 없음 · 관리번호에만)", ono,
                   f"z1191z156 수주 칸 확인 · 「{r['orig_name']}」 → 수주 {ono} · 직접 고름 · {who}"))
    return JSONResponse({"ok": True, "shown": ono})


@app.post("/api/so-check-proj/{pid}")
async def api_so_check_proj_z154(request: Request, pid: int):
    """z1191z154: 「이 관리번호 수주 모두 대표값으로 확정」 — 사람이 누를 때만 · 그 관리번호에서 아직 정해지지 않은 수주 칸만 · 수주마다 이력."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "message": "로그인이 필요합니다."}, 401)
    if not can_use_sales(u):
        return JSONResponse({"ok": False, "message": "권한이 없습니다."}, 403)
    form = await request.form()
    field = (form.get("field") or "").strip()
    if field not in ("end_customer", "po_type"):
        return JSONResponse({"ok": False, "message": "알 수 없는 요청입니다."}, 400)
    who = vname_full(u) or u.get("name") or ""
    with db_session() as c:
        p = c.execute("SELECT secondary_customer, po_type FROM projects WHERE id=?", (int(pid),)).fetchone()
        if not p:
            return JSONResponse({"ok": False, "message": "관리번호를 찾지 못했습니다."}, 404)
        val = (str((p[0] if field == "end_customer" else p[1]) or "").strip())[:100]
        if field == "po_type" and val not in _logi.PO_TYPES:
            return JSONResponse({"ok": False, "message": "관리번호의 PO유형이 비어 있어 확정할 값이 없습니다 — 수주마다 골라 주세요."}, 400)
        guard = "end_customer IS NULL" if field == "end_customer" else "COALESCE(po_type,'')=''"
        rows = c.execute(f"SELECT id, order_no FROM orders WHERE project_id=? AND COALESCE(status,'')<>'CANCELLED' AND {guard}",
                         (int(pid),)).fetchall()
        lb = "2차 고객" if field == "end_customer" else "PO유형"
        for oid, ono in rows:
            c.execute(f"UPDATE orders SET {field}=? WHERE id=?", (val, int(oid)))
            try:
                _logi.log_project_change(c, int(pid), u.get("id"), lb, "(정해지지 않음 · 대표값 보임)", val or "없음",
                                         note=f"z1191z154 수주 {ono} 칸 확인 · 관리번호 수주 모두 대표값으로 확정 · {who}")
            except Exception as _e:
                print(f"[z1191z154] 이력 실패: {_e}")
    return JSONResponse({"ok": True, "n": len(rows), "shown": val or "없음"})


def _z22_set_so_form(pid, shipment_form, exclude_ids=None):
    """새 프로젝트의 수주 중 형태가 비어 있는 것에 등록 화면의 형태를 넣는다(추가 품목 수주는 제외 — 그 품목 형태가 따로 있음)."""
    code = _Z22_SF2SO.get(str(shipment_form or "").strip().upper())
    if not code:
        return 0
    ex = [int(x) for x in (exclude_ids or []) if str(x).isdigit() or isinstance(x, int)]
    try:
        with db_session() as c:
            if "so_form" not in {r[1] for r in c.execute("PRAGMA table_info(orders)").fetchall()}:
                return 0
            q = "UPDATE orders SET so_form=? WHERE project_id=? AND COALESCE(so_form,'')=''"
            if ex:
                q += " AND id NOT IN (%s)" % ",".join("?" * len(ex))
            return c.execute(q, (code, int(pid), *ex)).rowcount
    except Exception as e:   # 형태 저장 실패는 등록을 막지 않는다 — 작업일정표 「형태」 칸에서 고칠 수 있음
        log.warning("z1191z22 형태 저장 실패(pid=%s): %s", pid, e)
        return 0


