async def _projects_new_submit_core(request: Request):
    """v5H52: project_form.html 의 실제 필드명(name/customer_name 등)과
    정합. 콤마 들어간 KRW 입력값도 자동 정리."""
    _u = get_user(request)
    if not _u:
        return RedirectResponse("/login", 303)
    if not can_use_sales(_u):
        return RedirectResponse("/home", 303)
    try:   # z1191z117 ⑤: 등록 전 최대 수주 번호(이번 등록으로 생긴 수주에만 「단가 미정」을 붙이려고)
        with db_session() as _c117:
            _maxoid117 = int(_c117.execute("SELECT COALESCE(MAX(id),0) FROM orders").fetchone()[0] or 0)
    except Exception:
        _maxoid117 = None
    form = await request.form()
    # 템플릿/대체 필드명 둘 다 허용 (호환)
    project_name = (form.get("name") or form.get("project_name") or "").strip()
    # v5H226z212 (대표 지시): 프로젝트명 필수 해제 — 프로젝트 단위가 아닌 경우(장비명·모델명만으로 진행) 多.
    #   비면 장비명 → (부품 품명) → (기타 품명) 순으로 대체. 모두 비면 아래에서 안내.
    if not project_name:
        project_name = ((form.get("equip_name") or "").strip()
                        or (form.get("part_name") or "").strip()
                        or (form.get("etc_name") or "").strip())
    customer = (form.get("customer_name") or form.get("customer") or "").strip()
    biz_div = (form.get("biz_div") or "").strip()
    # v5H192: 필수 필드 종합 검증 (비고 제외) — 빈 항목이 있으면 즉시 안내
    # v5H193: 검증 실패 redirect 시 type/biz_div 보존 (chooser 로 빠지지 않도록)
    _ptype_form = (form.get("project_type") or "NEW_EQUIP").strip().upper()
    if _ptype_form not in ("NEW_EQUIP", "OTHER", "CONSUMABLE", "SERVICE"):
        _ptype_form = "NEW_EQUIP"
    # v5H222: CONSUMABLE 도 projects 테이블에 정상 등록 (다른 3종과 동일 흐름).
    # consumable_orders 분기 제거 — 헤더만 저장 + 라인은 상세에서 추가.
    _back_qs = f"type={_ptype_form}"
    if biz_div:
        _back_qs += f"&biz_div={biz_div}"
    # v5H226z274: embed(모달) 모드면 검증실패 재렌더도 embed 유지
    _embed_q = str(form.get("embed") or "").strip().lower() in ("1", "true", "on", "yes", "y")
    if _embed_q:
        _back_qs += "&embed=1"
    # v5H226z276: 간편(quick) 폼에서 온 검증실패는 간편 폼으로 되돌림(전체폼으로 튕기지 않게)
    _is_quick = str(form.get("quick") or "").strip().lower() in ("1", "true", "on", "yes", "y")
    def _err_redirect(code: str, extra: str = "") -> RedirectResponse:
        if _is_quick:
            url = f"/projects/quick?error={code}" + ("&embed=1" if _embed_q else "")
            if biz_div in ("T", "M", "L", "E"):   # z1191z22: 보던 탭(기타 등)으로 되돌린다 — 예전엔 빠져서 검사기 화면으로 넘어갔다
                url += f"&biz_div={biz_div}"
        else:
            url = f"/projects/new?{_back_qs}&error={code}"
        if extra:
            url += "&" + extra
        return RedirectResponse(url, status_code=303)
    # z1191z57: 다른 분이 등록 화면을 잡고 있으면 저장하지 않는다(화면이 먼저 막지만 서버도 한 번 더 · 입력은 이 기기에 남음)
    try:
        _hold57 = _z57_lock_other(_u, (form.get("lock_token") or "").strip(), biz_div)   # z1191z70: 같은 종류만
    except Exception:
        _hold57 = ""
    if _hold57:
        from urllib.parse import quote as _q57
        return _err_redirect("reg_locked", "holder=" + _q57(_hold57))
    if not project_name:
        return _err_redirect("name_required")
    # v5H218: 진행 사업부는 항상 T 또는 M 이어야 함 (K 기타는 chooser 에서 K 로 들어와도 폼에서 T/M 으로 보정)
    # z1191z22 (이새롬 프로 신고 · 대표 「진행해」): 간편 등록 「기타」 탭(z355)은 E 를 보낸다 — 여기서 막혀 한 번도 등록되지 않았다.
    #   E 는 관리번호 NNN E YYMM · 수주번호 E-YYMMDD-N(project_type OTHER) · 매출 홈·보고서의 「기타」 줄.
    if biz_div not in ("T", "M", "L", "E"):
        return _err_redirect("biz_div_required")
    if not customer:
        return _err_redirect("customer_required")
    # 고객사 화이트리스트 검증
    with db_session() as _cc:
        _ok = _cc.execute(
            "SELECT 1 FROM customers WHERE name=? OR alias=? LIMIT 1", (customer, customer)  # v5H226z654: 상호 또는 시스템명 등록이면 통과
        ).fetchone() or _logi.resolve_customer_by_name(_cc, customer)["id"]   # z1191z157: 옛 이름(이력)도 딱 한 고객사면 통과
    if not _ok:
        from urllib.parse import quote as _q
        return _err_redirect("customer_not_registered", f"cust={_q(customer)}")
    # v5H211: 단계별 차등 검증 — 진행중/출하(또는 즉시 수주확정)면 strict, 그 전 단계는 단가·발주일·납기·환율 옵션
    # 제안 단계(초기협의/제안서전달/견적발행/수주예정/보류/기타)는 추상적 견적이라 강제 입력 부담 제거
    po_type_v = (form.get("po_type") or "").strip()
    order_date_v = (form.get("order_date") or "").strip()
    due_date_v = (form.get("due_date") or "").strip()
    raw_price_v = (form.get("unit_price") or "0").strip().replace(",", "")
    try:
        _up_v = float(raw_price_v) if raw_price_v else 0
    except ValueError:
        _up_v = 0
    # z1171: 단가 칸을 적었나 — 0 을 적으면 무상(통과) · 비우면 아직 안 적은 것(아래 _strict 에서 막음)
    _up_given = bool((form.get("unit_price") or "").strip().replace(",", ""))
    _status_v = (form.get("status") or "초기협의").strip()
    _confirm_now_v = (form.get("confirm_now") or "").strip() in ("1", "on", "true", "yes")
    # v5H226z389 (대표 지시): 호기별(검사기 N대) 단가가 서로 다르면 헤더 '단가'를 비워 보냄(평균 금지).
    #   이 경우 단가 필수 검증을 면제하고 '호기 합계(order_amount)>0' 로 대신 검증한다.
    _multi_v = (form.get("multi_unit") or "").strip() in ("1", "on", "true", "yes")
    # v5H222: 소모품(CONSUMABLE)은 라인이 비어있는 상태로 등록 → 단가/수량 검증 면제
    _is_consumable = (_ptype_form == "CONSUMABLE")
    # v5H226z436 (대표 지시): 형태=상품(부품 PACKING LIST)은 부품 표(품명·모델·수량·단가)로 입력 →
    #   헤더 '단가·발주일·납품일' 강제 면제(금액=부품 합계, 날짜는 후속/상세). 신규·추가발주 공통.
    #   부품 자체는 아래에서 '수주확정' 체크 시 저장(parts_need_confirm 가드).
    _is_parts_reg = (form.get("shipment_form") or "").strip().upper() == "PARTS"
    # v5H226z1050 (대표 지시): 📦제품(SEMI)의 '항목' — 한 수주번호에 서로 다른 품목 N줄.
    #   'AMS THES123모델 소켓' 견적서 한 장 아래 '소켓 2개 / 소켓PCB 3개'(단가 각각).
    #   ⚠**검증보다 먼저** 읽어야 한다 — 항목만 적고 위 단가를 비우면 '단가 필수'에 막힌다(실측으로 잡음).
    #   ⚠제품일 때만 읽는다. 다른 형태에서 값이 섞여 와도 무시(화면도 형태가 바뀌면 지운다).
    _z1050_items = []
    _z1050_blank = False      # z1171: 품명을 적은 줄 가운데 단가를 **비운** 줄이 있나(0 = 무상과 다르다)
    if (form.get("shipment_form") or "").strip().upper() == "SEMI":
        _itn = form.getlist("it_name[]")
        _its = form.getlist("it_spec[]")
        _itq = form.getlist("it_qty[]")
        _itp = form.getlist("it_price[]")
        for _i in range(len(_itn)):
            _nm = (_itn[_i] or "").strip()
            _sp = ((_its[_i] if _i < len(_its) else "") or "").strip()
            if not _nm and not _sp:
                continue                      # 빈 줄은 버린다
            try:
                _q = int(float(((_itq[_i] if _i < len(_itq) else "1") or "1").replace(",", "")))
            except (ValueError, TypeError):
                _q = 1
            _praw = ((_itp[_i] if _i < len(_itp) else "") or "").strip().replace(",", "")
            if not _praw:
                _z1050_blank = True
            try:
                _pr = float(_praw or "0")
            except (ValueError, TypeError):
                _pr = 0.0
