@app.post("/as/new")
async def as_new_submit(request: Request):
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_use_sales(u):
        return RedirectResponse("/home", 303)
    form = await request.form()
    cust_name = (form.get("customer_name") or "").strip()
