@app.post("/customers/import-xlsx")
async def customers_import_xlsx(request: Request, xlsx: UploadFile = File(...)):
    """v5H226z122: 업로드 → 파싱 + 검증 → 미리보기 JSON 반환."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"ok": False, "error": "permission_denied"}, 403)
    if not _can_reg_customer_z102(u):   # z1191z102: 새 고객사 = 기술영업팀 + 대표만
        return JSONResponse({"ok": False, "error": "고객사 일괄 등록은 기술영업팀(또는 대표)만 할 수 있습니다"}, 403)
    try:
        body = await xlsx.read()
        rows = _cust_import_parse_xlsx(body)
    except Exception as e:
        return JSONResponse({"ok": False, "error": f"파싱 실패: {e}"}, 400)
    create_count = sum(1 for r in rows if r["_action"] == "create" and not r["_errors"])
    update_count = sum(1 for r in rows if r["_action"] == "update" and not r["_errors"])
    error_count = sum(1 for r in rows if r["_errors"])
    warning_count = sum(1 for r in rows if r["_warnings"] and not r["_errors"])
    return JSONResponse({
        "ok": True, "rows": rows, "total": len(rows),
        "create_count": create_count, "update_count": update_count,
        "error_count": error_count, "warning_count": warning_count,
    })


def _cust_import_verify_saved(raw_bytes):
    """대표규정(2026-07-28·§4 규칙 47): 고객사 일괄등록 '엑셀 원본 ↔ 저장값' 대조(읽기전용).
    고객사명으로 UPSERT 라 매칭은 이름 정확일치(유일). 엑셀에 '적어 넣은 칸'만 대조(빈 칸은 미갱신이라 제외).
    반환 {checked, ok, diff:[{row,name,field,excel,saved}], skipped, fields}."""
    out = {"checked": 0, "ok": True, "diff": [],
           "fields": "사업자번호·대표·담당자·전화·이메일·주소·업태·종목·팩스·종사업자번호·우편번호·상세주소"}
    try:
        rows = _cust_import_parse_xlsx(raw_bytes)
    except Exception as _e:
        out["skipped"] = f"엑셀을 다시 열지 못했습니다({str(_e)[:60]})"
        return out

    def _add(idx, name, field, ex, sv):
        out["ok"] = False
        if len(out["diff"]) < 20:
            out["diff"].append({"row": idx, "name": str(name or "")[:24], "field": field,
                                "excel": ("" if ex is None else str(ex)), "saved": ("" if sv is None else str(sv))})

    def _s(v):
        return str(v).strip() if v not in (None, "") else ""

    _FIELDS = [("사업자번호", "biz_no"), ("대표", "ceo_name"), ("담당자", "manager_name"),
               ("전화", "phone"), ("이메일", "email"), ("주소", "address"),
               ("업태", "business_type"), ("종목", "business_item"), ("팩스", "fax"),
               ("종사업자번호", "sub_biz_no"), ("우편번호", "zipcode"), ("상세주소", "address_detail")]
    try:
        with db_session() as c:
            _cols = {r[1] for r in c.execute("PRAGMA table_info(customers)").fetchall()}
            for _idx, r in enumerate(rows, 1):
                if r.get("_errors"):
                    continue
                _nm = _s(r.get("name"))
                if not _nm:
                    continue
                _row = c.execute("SELECT * FROM customers WHERE name=?", (_nm,)).fetchone()
                if not _row:
                    _add(_idx, _nm, "고객사명", _nm, "저장 안 됨")
                    continue
                _d = dict(_row)
                out["checked"] += 1
                for _f, _k in _FIELDS:
                    if _k not in _cols:
                        continue
                    _ev = _s(r.get(_k))
                    if _ev and _ev != _s(_d.get(_k)):
                        _add(_idx, _nm, _f, _ev, _s(_d.get(_k)))
    except Exception as _e:
        out["error"] = str(_e)[:120]
    return out


@app.post("/customers/import-verify")
async def customers_import_verify(request: Request, xlsx: UploadFile = File(...)):
    """대표규정(2026-07-28·§4 규칙 47): 고객사 일괄등록 확정 후 '엑셀 원본 ↔ 저장값' 자동 대조. ⛔조회 전용."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "로그인 필요"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"ok": False, "error": "권한 없음"}, 403)
    if not _can_reg_customer_z102(u):   # z1191z102: 새 고객사 = 기술영업팀 + 대표만
        return JSONResponse({"ok": False, "error": "고객사 일괄 등록은 기술영업팀(또는 대표)만 할 수 있습니다"}, 403)
    _raw = await xlsx.read()
    if not _raw:
        return JSONResponse({"ok": False, "error": "빈 파일입니다"}, 200)
    if len(_raw) > 10 * 1024 * 1024:
        return JSONResponse({"ok": False, "error": "파일이 너무 큽니다 (10MB 제한)"}, 200)
    if not (xlsx.filename or "").lower().endswith((".xlsx", ".xlsm")):
        return JSONResponse({"ok": False, "error": "Excel 파일(.xlsx)만 지원합니다"}, 200)
    try:
        _v = _cust_import_verify_saved(_raw)
    except Exception as e:
        return JSONResponse({"ok": False, "error": f"대조 오류: {str(e)[:150]}"}, 200)
    return JSONResponse({"ok": True, "verify": _v})


@app.post("/customers/import-confirm")
async def customers_import_confirm(request: Request):
    """v5H226z122: 미리보기 확정 → INSERT / UPDATE. 담당자 5명 INSERT (중복 이름 skip)."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"ok": False, "error": "permission_denied"}, 403)
    if not _can_reg_customer_z102(u):   # z1191z102: 새 고객사 = 기술영업팀 + 대표만
        return JSONResponse({"ok": False, "error": "고객사 일괄 등록은 기술영업팀(또는 대표)만 할 수 있습니다"}, 403)
    try:
        body = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "invalid_json"}, 400)
    rows = body.get("rows") or []
    if not isinstance(rows, list) or not rows:
        return JSONResponse({"ok": False, "error": "no_rows"}, 400)

    created, updated, failed = [], [], []
    try:
        from . import customer_tier as _ct
    except Exception:
        _ct = None

    with db_session() as c:
        for r in rows:
            try:
                name = (r.get("name") or "").strip()
                if not name:
                    failed.append({"row_no": r.get("row_no"), "name": "",
                                   "error": "고객사명 누락"})
                    continue
                biz_no = (r.get("biz_no") or "").strip()
                ceo = (r.get("ceo_name") or "").strip()
                manager = (r.get("manager_name") or "").strip()
                phone = (r.get("phone") or "").strip()
                email = (r.get("email") or "").strip()
                address = (r.get("address") or "").strip()
                tier = (r.get("tier") or "").strip().upper()
                is_active = int(r.get("is_active") if r.get("is_active") is not None else 1)
                note = (r.get("note") or "").strip()
                # v5H226z147: 추가 사업장 항목
                code = (r.get("code") or "").strip()
                business_type = (r.get("business_type") or "").strip()
                business_item = (r.get("business_item") or "").strip()
                zipcode = (r.get("zipcode") or "").strip()
                address_detail = (r.get("address_detail") or "").strip()
                fax = (r.get("fax") or "").strip()
                sub_biz_no = (r.get("sub_biz_no") or "").strip()

                existing = c.execute(
                    "SELECT id FROM customers WHERE name=?", (name,)
                ).fetchone()
                if not existing and _logi.customer_old_name_match(c, name)["cands"]:   # z1191z157: 옛 이름 = 새로 안 만듦
                    failed.append({"row_no": r.get("row_no"), "name": name,
                                   "error": "옛 이름 — 이름이 바뀐 고객사입니다. 지금 이름으로 고쳐 올리세요(새로 만들지 않음)"})
                    continue
                if existing:
                    cid = existing["id"] if hasattr(existing, "keys") else existing[0]
                    sets, vals = [], []
                    for col, v in (
                        ("biz_no", biz_no), ("ceo_name", ceo),
                        ("manager_name", manager), ("phone", phone),
                        ("email", email), ("address", address),
                        ("note", note),
                        ("business_type", business_type), ("business_item", business_item),
                        ("zipcode", zipcode), ("address_detail", address_detail),
                        ("fax", fax), ("sub_biz_no", sub_biz_no),
                    ):
                        if v:
                            sets.append(f"{col}=?")
                            vals.append(v)
                    sets.append("is_active=?")
                    vals.append(is_active)
                    if sets:
                        vals.append(cid)
                        c.execute(
                            f"UPDATE customers SET {','.join(sets)} WHERE id=?",
                            tuple(vals)
                        )
                    if _ct:
                        try: _ct.refresh_customer_tier(c, cid)
                        except Exception: pass
                    contacts_list = r.get("contacts") or []
                    for ct in contacts_list:
                        ct_name = (ct.get("name") or "").strip()
                        if not ct_name:
                            continue
                        existing_ct = c.execute(
                            "SELECT id FROM customer_contacts WHERE customer_id=? AND name=?",
                            (cid, ct_name)
                        ).fetchone()
                        if existing_ct:
                            continue
                        c.execute(
                            "INSERT INTO customer_contacts(customer_id, name, department, mobile, email, is_primary, role) VALUES(?,?,?,?,?,?,?)",
                            (cid, ct_name, ct.get("department", ""),
                             ct.get("mobile", ""), ct.get("email", ""),
                             int(ct.get("is_primary", 0)), "기타")
                        )
                    updated.append({"row_no": r.get("row_no"), "id": cid, "name": name})
                else:
                    fields = {
                        "name": name, "tier": tier or "일반",
                        "biz_no": biz_no, "ceo_name": ceo,
                        "manager_name": manager, "phone": phone,
                        "email": email, "address": address,
                        "is_active": is_active, "note": note,
                        "business_type": business_type, "business_item": business_item,
                        "zipcode": zipcode, "address_detail": address_detail,
                        "fax": fax, "sub_biz_no": sub_biz_no,
                        "code": code or _gen_customer_code(c),   # 비면 자동 부여
                    }
                    cols = ",".join(fields.keys())
                    ph = ",".join(["?"] * len(fields))
                    c.execute(
                        f"INSERT INTO customers({cols}) VALUES({ph})",
                        tuple(fields.values())
                    )
                    new_id = c.execute("SELECT last_insert_rowid()").fetchone()[0]
                    contacts_list = r.get("contacts") or []
                    for ct in contacts_list:
                        ct_name = (ct.get("name") or "").strip()
                        if not ct_name:
                            continue
                        c.execute(
                            "INSERT INTO customer_contacts(customer_id, name, department, mobile, email, is_primary, role) VALUES(?,?,?,?,?,?,?)",
                            (new_id, ct_name, ct.get("department", ""),
                             ct.get("mobile", ""), ct.get("email", ""),
                             int(ct.get("is_primary", 0)), "기타")
                        )
                    if _ct:
                        try: _ct.refresh_customer_tier(c, new_id)
                        except Exception: pass
                    created.append({"row_no": r.get("row_no"), "id": new_id, "name": name})
            except Exception as e:
                failed.append({"row_no": r.get("row_no"),
                               "name": r.get("name"), "error": str(e)})

    return JSONResponse({
        "ok": True,
        "created_count": len(created),
        "updated_count": len(updated),
        "failed_count": len(failed),
        "created": created,
        "updated": updated,
        "failed": failed,
    })


@app.get("/projects/{pid}/edit", response_class=HTMLResponse)
async def projects_edit_form(request: Request, pid: int):
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_use_sales(u):
        return RedirectResponse("/home", 303)
    # v5H101: 편집 폼 진입 시 SO 기준으로 자가치유
    #   납기/발주일/수주액 = SO 합계·MAX·MIN 으로 정정 후 폼 노출
    sos = []   # v5H226z1034: 아래 확정 수량 계산이 참조 — 조회가 실패해도 NameError 안 나게
    try:
        with db_session() as c2:
            sos = _pwf.get_project_orders(c2, pid)
            if sos:
                so_sum = sum(float(o.get("total_amount") or 0) for o in sos)
                dues = [o.get("due_date") for o in sos if o.get("due_date")]
                ords = [o.get("order_date") for o in sos if o.get("order_date")]
                heal_pairs = [("order_amount", so_sum)]
                if dues:
                    heal_pairs.append(("due_date", max(dues)))
                if ords:
                    heal_pairs.append(("order_date", min(ords)))
                # z1191z153 (대표 11-25 원칙 ③ 「화면 열기만으로 저장 안 함」): 예전엔 여기서 수주액(통화 섞어 단순 합)·납기·발주일을
                #   저장했다 → 계산만 하고 저장 안 함(화면이 확정 수량·금액 표로 보여 줌).
                _heal153 = heal_pairs
    except Exception:
        pass
    p = _logi.projects_get_logi(pid)
    if not p:
        return RedirectResponse("/projects", status_code=303)
    # v5H174: 등록자/등록일시 표시용 — created_by → 사용자명 lookup
    # v5H226z800 (대표 지시·규칙): 등록자 = 이름 직책 부서 [[knk_name_display_rule]]
    p = dict(p)
    try:
        if p.get("created_by"):
            with db_session() as _c:
                _u_row = _c.execute(
                    "SELECT name FROM users WHERE id=?", (p.get("created_by"),)
                ).fetchone()
                if _u_row:
                    p["created_by_name"] = _u_row[0]
                p["created_by_disp"] = user_disp_by_id(_c, p.get("created_by"), p.get("created_by_name") or "")
    except Exception:
        pass
    # v5H103: SO 존재 여부 → 폼 수주액 readonly 안내용
    has_orders = False
    try:
        with db_session() as c3:
            row = c3.execute(
                "SELECT COUNT(*) FROM orders WHERE project_id=?", (pid,)
            ).fetchone()
            has_orders = (row[0] or 0) > 0
    except Exception:
        pass
    # v5H226z1034 (안지연 프로 신고·대표 지시): 폼 ③의 '수량'은 **등록할 때 적은 예상 수량**이라
    #   추가발주가 붙어도 늘지 않는다. 002M2602 는 실제 13대인데 폼이 6대를 보여줘
    #   "6대도 13대도 아닌" 혼란이 났다(상세의 '단가 × 6대 = 31억'도 산수가 안 맞았다).
    #   → 수주가 있으면 **확정 수량·금액**을 넘겨 폼이 사실을 보여주게 한다.
    #   ⚠부품(PARTS)·소모품은 '대' 단위가 아니라 라인 수 개념이라 계산에서 제외(0 = 기존 표시 유지).
    so_qty, so_amount, so_count = 0, 0.0, 0
    try:
        _parts_or_co = ((p.get("shipment_form") or "").upper() == "PARTS"
                        or (p.get("project_type") or "").upper() == "CONSUMABLE")
        if sos and not _parts_or_co:
            so_count = len(sos)
            so_amount = sum(float(o.get("total_amount") or 0) for o in sos)
            for _o in sos:
                _us = _o.get("units") or []
                # z1191z7 (안지연 프로 신고 · 대표 2026-11-06): 호기 수는 **완제품 수주만** 센다 — 상품 수주의 부품 384줄까지
                #   더해 「호기 395대 · 1대 단가 742」가 뜨던 혼합 프로젝트(001M2509) 혼란.
                _hn7 = sum(1 for x in _us if str(x.get("unit_label") or "").strip()[:1].isdigit())
                _lk7 = _pwf.so_form_label_key(so_form=_o.get("so_form"), so_type=_o.get("so_type"),
                                             shipment_form=_o.get("shipment_form"), hogi_n=_hn7,
                                             proj_ptype=(p.get("project_type") or "NEW_EQUIP"))
                if _lk7[1] != "assembly":
                    continue
                so_qty += (sum(int(x.get("qty") or 0) for x in _us) if _us
                           else int(_o.get("unit_qty") or 1))
    except Exception:
        so_qty, so_amount, so_count = 0, 0.0, 0
    # z1191z7: 수주별 표(수주번호·형태·PO유형·고객사·수량·금액) — 수주 2건 이상이면 ③ 확정 금액을 이 표로 보인다
    so_rows, so_mixed = [], False
