@app.post("/projects/{pid}/retire")
async def projects_retire_submit(request: Request, pid: int):
    """v5H226z871 (2026-07-08 대표 지시): 폐기 = 완전삭제 + 관리번호 봉인.
    v5H226z940 (대표 지시): 봉인=자동발번 회피용 기록만 유지 — 수동 재입력은 그 번호를 쓰는 살아있는 프로젝트가 없으면 재사용 허용(_validate_manual_mgmt_code·재사용 시 봉인 자동 해제).
    기존 폐기(숨김·is_archived)를 대체. 안전장치: 세금계산서/출하/수금 등 실거래 기록이 있으면
    confirm=1 재확인 없이는 차단(z176 이 보호하던 범위). 봉인=삭제 전 retired_mgmt_codes 기록 →
    generate_mgmt_code 가 그 번호 재사용 안 함. 권한=can_use_sales(등록권한자)."""
    _u = get_user(request)
    if not _u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    if not can_use_sales(_u):
        return JSONResponse({"ok": False, "error": "권한 없음",
                             "message": "폐기(완전삭제)는 영업 등록권한자만 가능합니다."}, 403)
    _form = await request.form()
    try:
        with db_session() as c:
            _row = c.execute("SELECT mgmt_code, name FROM projects WHERE id=?", (pid,)).fetchone()
    except Exception:
        _row = None
    if not _row:
        return JSONResponse({"ok": False, "error": "없음", "message": "프로젝트를 찾을 수 없습니다."}, 404)
    _mc = (_row[0] or "").strip()
    _pname = (_row[1] or "").strip()
    # v5H226z872 (대표 지시): 출하·세금계산서·수금 등 실거래 기록이 있으면 폐기 완전 차단(비밀번호로도 불가).
    try:
        _fin = _logi.project_financial_flags(pid)
    except Exception:
        _fin = {"any": False}
    if _fin.get("any"):
        _kinds = []
        if _fin.get("ship"): _kinds.append("출하")
        if _fin.get("tax"): _kinds.append("세금계산서")
        if _fin.get("pay"): _kinds.append("수금")
        return JSONResponse({
            "ok": False, "blocked": True, "financial": _kinds,
            "message": f"이 프로젝트에는 {'·'.join(_kinds)} 이력이 있어 폐기(완전삭제)할 수 없습니다. (실거래 기록 보호)"
        }, 409)
    # v5H226z872 (대표 지시): 본인 로그인 비밀번호 재확인 — 맞아야 삭제. 비밀번호는 대조 즉시 폐기(저장·로그 안 함).
    _pw = str(_form.get("password") or "")
    if not _pw:
        return JSONResponse({"ok": False, "need_password": True,
                             "message": "본인 로그인 비밀번호를 입력하세요."}, 401)
    try:
        with db_session() as c:
            _prow = c.execute("SELECT password FROM users WHERE id=?", (_u["id"],)).fetchone()
        if not _prow or not verify_pw(_pw, _prow["password"]):
            return JSONResponse({"ok": False, "bad_password": True,
                                 "message": "비밀번호가 일치하지 않습니다."}, 401)
    except Exception:
        return JSONResponse({"ok": False, "error": "확인 실패",
                             "message": "비밀번호 확인 중 오류가 발생했습니다."}, 500)
    # v5H226z934 (대표 지시): 삭제 전 DB 자동백업 (필수 — 실패 시 중단). 되돌릴 수 없는 완전삭제라 스냅샷 보존.
    try:
        import datetime as _dt2
        # z935: DB_PATH·backup_db_file 둘 다 database 모듈 정의 → 지역 import(z934 'DB_PATH not defined' 버그 수정).
        from .database import DB_PATH as _DB_PATH, backup_db_file as _backup_db_file
        _bdir = os.path.join(os.path.dirname(_DB_PATH), "backups")
        os.makedirs(_bdir, exist_ok=True)
        _bts = _dt2.datetime.now().strftime("%Y%m%d_%H%M%S")
        _backup_db_file(os.path.join(_bdir, f"knk.db.bak_retire_{(_mc or ('id'+str(pid)))}_{_bts}"))
    except Exception as _be:
        return JSONResponse({"ok": False, "error": "백업 실패",
                             "message": f"삭제 전 DB 백업 실패 — 안전을 위해 중단합니다: {str(_be)[:160]}"}, 500)
    _logi.prune_db_backups(_bdir, "knk.db.bak_retire_")   # z1161: 폐기 사본도 최근 7개(대상이 달라도 한 기능 · 9/2 이전 기록용은 남김)
    # 봉인 먼저(번호 재사용 원천 차단) → 완전삭제. 순서 보장: 삭제 실패해도 번호는 봉인(안전측).
    try:
        with db_session() as c:
            _logi.retire_mgmt_code(c, _mc, retired_by=(_u.get("name") or _u.get("username") or ""),
                                   project_name=_pname)
        _logi.projects_delete_logi(pid, force=True)   # force=True: z176 삭제잠금 우회(대표가 폐기=완전삭제로 결정)
    except Exception as e:
        return JSONResponse({"ok": False, "error": "삭제 실패", "message": str(e)}, 500)
    _seal = f" · 관리번호 {_mc} (겹치는 데이터 없으면 재사용 가능)" if _mc else ""
    return JSONResponse({"ok": True, "message": f"완전삭제 완료{_seal}", "redirect": "/projects"})


@app.post("/projects/{pid}/delete")
async def projects_delete_submit(request: Request, pid: int):
    """v5H72: 프로젝트 삭제 — 더 엄격한 can_delete_sales 권한.
    v5H98: 삭제 실패 시 구체적 FK/sqlite 에러 메시지 JSON 으로 반환.
    v5H226l: kind=consumable 이면 legacy consumable_orders 행 삭제로 분기."""
    _u = get_user(request)
    if not _u:
        return RedirectResponse("/login", 303)
    if not can_delete_sales(_u):
        return JSONResponse({"error": "권한 없음",
                              "message": "프로젝트 삭제는 영업팀 팀장 또는 위임받은 등록권한자만 가능합니다."}, 403)
    _form = await request.form()
    _kind = (_form.get("kind") or "project").strip().lower()
    try:
        if _kind == "consumable":
            from . import consumables as _co_mod
            _co_mod.co_delete(pid)
        else:
            _logi.projects_delete_logi(pid)
    except PermissionError as e:
        # v5H226z176: 관리코드(수주확정) 부여 건 — 정책상 삭제 불가
        return JSONResponse({"ok": False, "error": "삭제 불가", "message": str(e)}, 403)
    except Exception as e:
        import traceback
        err_msg = str(e)
        tb = traceback.format_exc()
        # 어느 테이블이 막는지 힌트 추출 (FOREIGN KEY constraint failed)
        hint = ""
        if "FOREIGN KEY" in err_msg or "foreign key" in err_msg.lower():
            hint = ("관련 자식 데이터가 남아 있어 삭제 차단됨. "
                    "잠시 후 다시 시도하거나 시스템 관리자에게 보고하세요.")
        return JSONResponse({
            "ok": False,
            "error": "삭제 실패",
            "message": f"{err_msg}\n{hint}",
            "trace": tb[-500:],  # 마지막 500자만
        }, 500)
    return JSONResponse({"ok": True, "message": "프로젝트 삭제 완료"})


@app.post("/projects/bulk-delete")
async def projects_bulk_delete(request: Request):
    """v5H179: 다건 프로젝트 일괄 삭제. ids=콤마구분 또는 ids[]=반복.
    개별 실패는 무시하고 계속 진행 — 결과 집계 반환."""
    _u = get_user(request)
    if not _u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    if not can_delete_sales(_u):
        return JSONResponse({"error": "권한 없음",
                              "message": "프로젝트 삭제는 영업팀 팀장 또는 위임받은 등록권한자만 가능합니다."}, 403)
    form = await request.form()
    raw = form.getlist("ids[]") or form.getlist("ids")
    if not raw and form.get("ids"):
        raw = [s.strip() for s in str(form.get("ids")).split(",") if s.strip()]
    co_raw = form.getlist("co_ids[]") or form.getlist("co_ids")  # v5H226l: legacy 소모품 묶음
    pids: list[int] = []
    for v in raw:
        try:
            pids.append(int(v))
        except (TypeError, ValueError):
            continue
    co_ids: list[int] = []
    for v in co_raw:
        try:
            co_ids.append(int(v))
        except (TypeError, ValueError):
            continue
    if not pids and not co_ids:
        return JSONResponse({"ok": False, "message": "삭제할 ID 가 없습니다"}, 400)
    if len(pids) + len(co_ids) > 200:
        return JSONResponse({"ok": False, "message": "한 번에 200건 초과 불가"}, 400)
    ok, fail = [], []
    for pid in pids:
        try:
            _logi.projects_delete_logi(pid)
            ok.append(pid)
        except Exception as e:
            fail.append({"id": pid, "kind": "project", "error": str(e)[:200]})
    if co_ids:
        try:
            from . import consumables as _co_mod
        except Exception:
            _co_mod = None
        for cid in co_ids:
            try:
                if _co_mod is None:
                    raise RuntimeError("consumables 모듈 로드 실패")
                _co_mod.co_delete(cid)
                ok.append(cid)
            except Exception as e:
                fail.append({"id": cid, "kind": "consumable", "error": str(e)[:200]})
    return JSONResponse({
        "ok": True,
        "deleted": len(ok),
        "failed": len(fail),
        "fail_details": fail[:20],  # 처음 20건만
        "message": f"{len(ok)}건 삭제 완료" + (f", {len(fail)}건 실패" if fail else ""),
    })


@app.post("/customers/bulk-delete")
async def customers_bulk_delete(request: Request):
    """v5H180: 다건 고객사 일괄 삭제.
    안전 정책:
      - can_delete_sales 권한 필요 (영업팀 팀장/등록권한자)
      - 프로젝트(또는 SO/견적)가 연결된 고객사는 삭제 거부 (FK 안전)
      - 한 번에 200건 제한
      - 개별 실패는 집계 후 계속 진행
    """
    _u = get_user(request)
    if not _u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    if not can_delete_sales(_u):
        return JSONResponse({
            "error": "권한 없음",
            "message": "고객사 삭제는 영업팀 팀장 또는 위임받은 등록권한자만 가능합니다."
        }, 403)
    form = await request.form()
    raw = form.getlist("ids[]") or form.getlist("ids")
    if not raw and form.get("ids"):
        raw = [s.strip() for s in str(form.get("ids")).split(",") if s.strip()]
    cids: list[int] = []
    for v in raw:
        try:
            cids.append(int(v))
        except (TypeError, ValueError):
            continue
    if not cids:
        return JSONResponse({"ok": False, "message": "삭제할 ID 가 없습니다"}, 400)
    if len(cids) > 200:
        return JSONResponse({"ok": False, "message": "한 번에 200건 초과 불가"}, 400)
    ok, fail = [], []
    with db_session() as c:
        for cid in cids:
            try:
                # FK 검증: 프로젝트/SO/견적/PO 연결 여부 확인
                proj_n = (c.execute(
                    "SELECT COUNT(*) FROM projects WHERE customer_id=?", (cid,)
                ).fetchone() or [0])[0]
                ord_n = 0
                try:
                    ord_n = (c.execute(
                        "SELECT COUNT(*) FROM orders WHERE customer_id=?", (cid,)
                    ).fetchone() or [0])[0]
                except Exception:
                    pass
                if proj_n or ord_n:
                    parts = []
                    if proj_n: parts.append(f"프로젝트 {proj_n}건")
                    if ord_n: parts.append(f"수주 {ord_n}건")
                    fail.append({"id": cid,
                                 "error": f"연결 데이터 존재 — {', '.join(parts)}. 먼저 정리 필요"})
                    continue
                # 고객사 담당자 (있으면) → cascade 삭제
                try:
                    c.execute("DELETE FROM customer_contacts WHERE customer_id=?", (cid,))
                except Exception:
                    pass
                c.execute("DELETE FROM customers WHERE id=?", (cid,))
                ok.append(cid)
            except Exception as e:
                fail.append({"id": cid, "error": str(e)[:200]})
    return JSONResponse({
        "ok": True,
        "deleted": len(ok),
        "failed": len(fail),
        "fail_details": fail[:20],
        "message": f"{len(ok)}건 삭제 완료" + (f", {len(fail)}건 실패" if fail else ""),
    })


