@app.post("/sales/receipts-check/record")
async def sales_receipts_check_record_z94(request: Request):
    """[✅ 입금 확인됨] — 입금 한 줄 기록(납품·수금 「수금 입력」과 같은 표) · 받을 돈이 다 차면 수주 = 입금 완료(PAID).
    PAID 판정 = 이 화면 규칙(계산서 금액 부가세 포함 − 받은 돈 ≤ 오차 · 그리고 계산서 합이 수주 금액을 다 채움)."""
    u = _s1_guard(request)
    if not u:
        return JSONResponse({"ok": False, "error": "입금 기록은 매출 등록 권한이 있는 분만 할 수 있습니다"}, 403)
    try:
        j = await request.json()
    except Exception:
        j = {}
    if not isinstance(j, dict):   # z1191z101: 배열 등 엉뚱한 몸통 → 500 대신 400
        j = {}
    try:
        oid = int(j.get("order_id") or 0)
        amount = float(str(j.get("amount") or "0").replace(",", ""))
    except (TypeError, ValueError):
        return JSONResponse({"ok": False, "error": "수주·금액을 읽지 못했습니다"}, 400)
    import math as _m101
    if not _m101.isfinite(amount):   # z1191z101: inf·nan 이 저장되면 그 수주의 받을 돈이 통째로 사라짐
        return JSONResponse({"ok": False, "error": "입금 금액을 숫자로 적어 주세요"}, 400)
    rat = str(j.get("received_at") or "").strip()[:10]
    note = str(j.get("note") or "").strip()[:300]
    from datetime import date as _d94
    try:
        _d94.fromisoformat(rat)
    except ValueError:
        return JSONResponse({"ok": False, "error": "입금일을 골라 주세요"}, 400)
    if oid <= 0 or amount <= 0:
        return JSONResponse({"ok": False, "error": "입금 금액을 0보다 크게 적어 주세요"}, 400)
    # z1191z101 (다시 보기 2번): 화면 경고는 화면을 연 때 값이라 두 사람·두 탭이면 두 번 기록됐다 → 서버가 지금 값으로 한 번 더 본다.
    #   막지 않고 알린다(대표 원칙 「입력하는 순간 실수를 알린다 · 확인했음 한 번」) — confirm 이 오면 기록.
    if not j.get("confirm"):
        _left101 = sum(x["rem"] for x in _rc_rows_z94(u)["rows"] if x["oid"] == oid)
        _warn101 = []
        with db_session() as c:
            _o101 = c.execute("SELECT COALESCE(currency,'KRW'), COALESCE(status,'') FROM orders WHERE id=?", (oid,)).fetchone()
            if not _o101:   # 없는·취소된 수주는 알림보다 먼저 그대로 거절
                return JSONResponse({"ok": False, "error": "수주를 찾지 못했습니다"}, 404)
            if _o101[1] == "CANCELLED":
                return JSONResponse({"ok": False, "error": "취소된 수주입니다"}, 400)
            _ccy101 = (_o101[0] or "KRW").upper()
            _eps101 = 1.0 if _ccy101 == "KRW" else 0.01
            if amount - _left101 > _eps101:
                _warn101.append("이 수주에 남은 받을 돈은 %s 인데 %s 을 적었습니다(남은 돈보다 많음 — 이미 누가 기록했을 수 있습니다)."
                                % (_fmt_money(_left101, _ccy101), _fmt_money(amount, _ccy101)))
            _dup101 = c.execute("SELECT COUNT(*) FROM receipts_payment WHERE order_id=? AND received_at=? AND ABS(amount-?)<=?",
                                (oid, rat, amount, _eps101)).fetchone()[0]
            if _dup101:
                _warn101.append("같은 수주 · 같은 입금일 · 같은 금액의 입금이 이미 %d건 기록되어 있습니다(두 번 기록인지 확인)." % _dup101)
        if _warn101:
            return JSONResponse({"ok": False, "need_confirm": True, "error": " ".join(_warn101)}, 409)
    with db_session() as c:
        o = c.execute("SELECT id, COALESCE(status,'') AS st, COALESCE(currency,'KRW') AS ccy, COALESCE(total_amount,0) AS total "
                      "FROM orders WHERE id=?", (oid,)).fetchone()
        if not o:
            return JSONResponse({"ok": False, "error": "수주를 찾지 못했습니다"}, 404)
        if o["st"] == "CANCELLED":
            return JSONResponse({"ok": False, "error": "취소된 수주입니다"}, 400)
        ccy = (o["ccy"] or "KRW").upper()
        amount = round(amount) if ccy == "KRW" else round(amount, 2)
        nm = vname_full(u) or (u.get("name") or "")
        _rpc = {r[1] for r in c.execute("PRAGMA table_info(receipts_payment)").fetchall()}
        _note = ("[입금 확인 · %s] " % nm) + note
        if "currency" in _rpc and "fx_rate" in _rpc:
            cur = c.execute("INSERT INTO receipts_payment (order_id, received_at, amount, method, received_by, note, currency, fx_rate) "
                            "VALUES (?,?,?,?,?,?,?,NULL)", (oid, rat, amount, "입금 확인", u.get("id"), _note, ccy))
        else:
            cur = c.execute("INSERT INTO receipts_payment (order_id, received_at, amount, method, received_by, note) "
                            "VALUES (?,?,?,?,?,?)", (oid, rat, amount, "입금 확인", u.get("id"), _note))
        try:
            _doc_audit_log(c, "receipts_payment", cur.lastrowid, "RECEIVE", u.get("id"), "z94 입금 확인 %s %s" % (amount, ccy))
        except Exception as _e:
            print(f"[z1191z94] 감사 기록 실패(입금은 저장됨): {_e}")
    # 남은 받을 돈 다시 계산 → 다 찼으면 입금 완료(PAID)
    left = [x for x in _rc_rows_z94(u)["rows"] if x["oid"] == oid]
    new_status = o["st"]
    if not left and o["st"] in ("SHIPPED", "INVOICED"):
        with db_session() as c:
            oic = {r[1] for r in c.execute("PRAGMA table_info(order_items)").fetchall()}
            issued = 0.0
            for n in range(1, _RC_TI_MAX_Z94 + 1):
                ac = "tax_invoice_amt%d" % n
                dc = "tax_invoice_date" if n == 1 else "tax_invoice_date%d" % n
                if ac in oic and dc in oic:   # z1191z101: 발행일 없는 금액은 받을 돈 줄에도 없으므로 여기서도 셈하지 않음
                    issued += float(c.execute("SELECT COALESCE(SUM(%s),0) FROM order_items WHERE order_id=? AND COALESCE(%s,'')<>''"
                                              % (ac, dc), (oid,)).fetchone()[0] or 0)
            eps = 1.0 if ccy == "KRW" else 0.01
            if o["total"] > 0 and issued >= float(o["total"]) - eps:
                if c.execute("UPDATE orders SET status='PAID' WHERE id=? AND status=?", (oid, o["st"])).rowcount == 1:
                    c.execute("INSERT INTO order_status_history (order_id, from_status, to_status, changed_by, note) VALUES (?,?,?,?,?)",
                              (oid, o["st"], "PAID", u.get("id"), "입금 확인 — 받을 돈 다 참(z1191z94)"))
                    new_status = "PAID"
    _fx115 = None   # z1191z115: 외화 입금 → 입금 달 환율 · 환차(알림 글)
    if ccy != "KRW":
        try:
            with db_session() as c:
                _fx115 = _fx_gain_calc_z115(_fx_load_rates(c), ccy, amount, _order_fx_date_z115(c, oid), rat)
        except Exception as _e115:
            print("[z1191z115] 환차 계산 실패(입금은 저장됨):", repr(_e115))
    return JSONResponse({"ok": True, "receipt_id": cur.lastrowid, "status": new_status, "left": len(left),
                         "fx_txt": (_fx115 or {}).get("txt", "")})


@app.get("/sales/shipments-receipts", response_class=HTMLResponse)
async def sales_shipments_receipts_page(req: Request):
    """납품·수금 (수금 관리 2단계·z745) — 작업일정표의 '다음 스텝'.
    한 줄 = 한 수주(SO). 출하=호기 unit_status='출하' 집계, 세금계산서 발행일=_board_tax_oi_map,
    입금예상일 = 세금계산서 발행일 + 고객사 pay_days, 수금=receipts_payment(동일통화), 미수=금액−수금.
    마감이월 = 출하했으나 세금계산서 미발행. 기준월(ym) 필터 + 마감이월·연체·결제조건미설정 상단 고정.
    can_money 마스킹(가격 게이트). 옛 모델(shipments·invoices) → 현 모델로 z745 재구축."""
    u = _s1_guard(req)
    if not u:
        return RedirectResponse("/home", 303)
    can_money = bool(can_view_sales(u))
    today = date.today()
    ym = (req.query_params.get("ym") or "").strip()
    if not (len(ym) == 7 and ym[4] == "-" and ym[:4].isdigit() and ym[5:7].isdigit()):
        ym = today.strftime("%Y-%m")

    oi_map, _proj_iids = _board_tax_oi_map()   # {iid:{stmt,t1d,t1a,...}} 호기별 세금계산서

    def _money(v, ccy):
        return _fmt_money(v, ccy)   # z755: 전역 통화기호 표준('$4,390.73'·'₩1,430,000') 사용

    with db_session() as c:
        ordc = {r[1] for r in c.execute("PRAGMA table_info(orders)").fetchall()}
        cusc = {r[1] for r in c.execute("PRAGMA table_info(customers)").fetchall()}
        oic = {r[1] for r in c.execute("PRAGMA table_info(order_items)").fetchall()}
        _cur = "o.currency" if "currency" in ordc else "'KRW'"
        _pd = "COALESCE(cu.pay_days,0)" if "pay_days" in cusc else "0"
        _pt = "COALESCE(cu.pay_term,'')" if "pay_term" in cusc else "''"   # z1191z95
        _isexp = "COALESCE(oi.is_export,0)" if "is_export" in oic else "0"   # z913 부가세율 판정(수출=영세율)
        rows = c.execute(
            f"""SELECT oi.id AS iid, oi.order_id AS oid,
                       COALESCE(oi.unit_status,'') AS ust,
                       o.order_no, o.project_id, o.order_date,
                       COALESCE(o.total_amount,0) AS total_amount,
                       COALESCE({_cur},'KRW') AS currency,
                       COALESCE(NULLIF(TRIM(cu.alias),''), cu.name, '-') AS customer_name,
                       COALESCE(cu.name,'-') AS customer_legal,
                       {_pd} AS pay_days, {_pt} AS pay_term,
                       {_isexp} AS is_export,
                       COALESCE(pj.mgmt_code,'') AS mgmt_code
                  FROM order_items oi
                  JOIN orders o ON o.id = oi.order_id
                  LEFT JOIN customers cu ON cu.id = o.customer_id
                  LEFT JOIN projects pj ON pj.id = o.project_id
                 WHERE COALESCE(o.status,'') <> 'CANCELLED'
                 ORDER BY o.id, oi.id"""
        ).fetchall()
        pay_rows = c.execute(
            """SELECT order_id AS oid, COALESCE(currency,'KRW') AS ccy,
                      COALESCE(SUM(amount),0) AS paid
                 FROM receipts_payment GROUP BY order_id, COALESCE(currency,'KRW')"""
        ).fetchall()
        hist_rows = c.execute(
            """SELECT order_id AS oid, COALESCE(received_at,'') AS rat,
                      COALESCE(amount,0) AS amt, COALESCE(method,'') AS method,
                      COALESCE(note,'') AS note, COALESCE(currency,'KRW') AS ccy
                 FROM receipts_payment ORDER BY received_at DESC, id DESC"""
        ).fetchall()
    paid_map = {(r["oid"], r["ccy"]): (r["paid"] or 0) for r in pay_rows}
    hist_map = {}   # z745b: 수주별 부분수금 이력(표시용)
    for r in hist_rows:
        hist_map.setdefault(r["oid"], []).append({
            "date": (r["rat"] or "")[:10], "amt_fmt": _money(r["amt"], r["ccy"]),
            "ccy": r["ccy"], "method": r["method"], "note": r["note"]})

    # ── 수주(SO)별 집계 ──
    agg = {}
    for r in rows:
        d = dict(r)
        oid = d["oid"]
        o = agg.get(oid)
        if not o:
            o = {"order_id": oid, "order_no": d["order_no"] or ("#" + str(oid)),
                 "project_id": d.get("project_id"),   # z918 관리번호→프로젝트 상세 링크
                 "mgmt_code": d["mgmt_code"], "customer_name": d["customer_name"],
                 "customer_legal": d["customer_legal"],   # z1191z72
                 "pay_days": int(d["pay_days"] or 0), "pay_term": d.get("pay_term") or "", "currency": d["currency"] or "KRW",
                 "total_amount": d["total_amount"] or 0, "order_date": d["order_date"] or "",
                 "n_total": 0, "n_ship": 0, "issue_date": "", "is_export": 0,
                 # v5H226z908 (대표 지시): 차수별(계약금1·중도금2·잔금3) 발행 집계 — 미발행 잔액 산출용
                 # z1191z24: 차수 1~10
                 **{("t%d%s" % (_n, _k)): (0.0 if _k == "a" else "") for _n in range(1, _TI_MAX + 1) for _k in ("a", "d")}}
            agg[oid] = o
        o["n_total"] += 1
        if d["ust"] == "출하":
            o["n_ship"] += 1
        if d.get("is_export"):
            o["is_export"] = 1
        m = oi_map.get(d["iid"])
        if m:
            for _tk in [str(_n) for _n in range(1, _TI_MAX + 1)]:   # 호기별 차수 발행일·금액 합산(대표 발행일=가장 이른 호기) · z1191z24: 1~10차
                _dv = (m.get("t" + _tk + "d") or "")
                if _dv and not o["t" + _tk + "d"]:
                    o["t" + _tk + "d"] = _dv
                _av = m.get("t" + _tk + "a")
                if _av not in (None, ""):
                    try:
                        o["t" + _tk + "a"] += float(_av)
                    except Exception:
                        pass
            if m.get("t1d"):
                if (not o["issue_date"]) or (m["t1d"] < o["issue_date"]):
                    o["issue_date"] = m["t1d"]   # 대표 발행일 = 가장 이른 호기 세금계산서일

    shipped = [o for o in agg.values() if o["n_ship"] > 0]   # 대상 = 출하 시작된 수주
    for o in shipped:
        paid = paid_map.get((o["order_id"], o["currency"]), 0.0)
        o["paid"] = paid
        o["outstanding"] = (o["total_amount"] or 0) - paid
        o["issued"] = bool(o["issue_date"])
        # v5H226z908 (대표 지시): 차수별 발행합계 + 미발행 잔액(수주금액 − 발행합계).
        #   잔액이 0이 될 때까지 '발행 대기'로 남아 부분 누락(계약금만·중도금 깜빡 등)까지 잡는다.
        _eps = 0.5 if o["currency"] == "KRW" else 0.005
        o["issued_amt"] = round(sum((o.get("t%da" % _n) or 0) for _n in range(1, _TI_MAX + 1)), 2)   # z1191z24: 1~10차
        # v5H226z1137 (이새롬 프로 신고): 발행 판정은 공용 순수 함수 한 곳 — 금액의 부호를 가정하지 않는다.
        _bs = _sr_bill_state(o["total_amount"], o["issued_amt"], _eps)
        o["unbilled"] = _bs["unbilled"]                    # 수주금액 방향으로 남은 금액(마이너스 수주는 −)
        o["billing_due"] = _bs["billing_due"]              # 미발행 잔액 남음(출하 시작 건)
        o["nothing_issued"] = _bs["nothing_issued"]        # 완전 미발행(마감이월)
        o["fully_issued"] = not o["billing_due"]
        # v5H226z913 (대표 지시): 부가세 포함 = 고객 실입금액. 국내 10%·수출/외화 영세율 0%.
        #   청구합계(포함)=발행합계×(1+세율)·미수(포함)=청구합계−수금(입금 대조 기준).
        _vrate = 0.0 if (o["currency"] != "KRW" or o.get("is_export")) else 0.10
        o["vat_rate"] = _vrate
        o["vat"] = round(o["issued_amt"] * _vrate)
        o["billed_incl"] = o["issued_amt"] + o["vat"]
        o["outstanding_incl"] = o["billed_incl"] - paid
        exp = ""
        if o["issued"]:   # z1191z95: 결제 조건 규칙 한 곳(안 고르면 기본 발행 후 60일)
            try:
                idt = datetime.strptime(o["issue_date"][:10], "%Y-%m-%d").date()
                exp = _pay_due_z95(idt, o["pay_term"], o["pay_days"]).isoformat()
            except Exception:
                exp = ""
        o["expected_date"] = exp
        o["pay_label"] = _pay_term_label_z95(o["pay_term"], o["pay_days"])
        o["attn_msg"] = ""
        if o["issued"] and not exp:
            o["attn_msg"] = "발행일 확인"
        if o["billing_due"] and o["nothing_issued"]:
            o["state"] = "마감이월"
        elif o["billing_due"]:
            o["state"] = "발행 대기"
        elif o["outstanding_incl"] <= _eps:
            o["state"] = "수금완료"
        else:
            o["state"] = "수금예정"
        o["dday"] = None
        if exp:
            try:
                o["dday"] = (datetime.strptime(exp, "%Y-%m-%d").date() - today).days
            except Exception:
                o["dday"] = None
        o["total_fmt"] = _money(o["total_amount"], o["currency"])
        o["paid_fmt"] = _money(paid, o["currency"])
        o["out_fmt"] = _money(o["outstanding"] if o["outstanding"] > 0 else 0, o["currency"])
        o["issued_fmt"] = _money(o["issued_amt"], o["currency"])      # z908 발행합계
        o["unbilled_fmt"] = _money(o["unbilled"], o["currency"])      # z908 미발행 잔액
        o["vat_fmt"] = _money(o["vat"], o["currency"])                # z913 부가세
        o["billed_incl_fmt"] = _money(o["billed_incl"], o["currency"])   # z913 청구합계(부가세 포함)
        o["out_incl_fmt"] = _money(o["outstanding_incl"] if o["outstanding_incl"] > 0 else 0, o["currency"])  # z913 미수(포함)
        # z910 → z1191z24 (대표 2026-11-16 · 안지연·이새롬 프로 답 「지금처럼 세금계산서 1차, 2차, 3차 이런 식으로」):
        #   이름 = 그 세금계산서의 차수(1차·2차·…·10차). 예전 계약금·중도금·잔금(z910)은 폐기 — 금액을 비율로
        #   나누지 않고 ＋로 한 장씩 더하므로 「몇 번째 장」이 맞는 이름이다. 발행된 세금계산서만(안 끊은 차수는 숨김).
        _iss = []
        for _tk in [str(_n) for _n in range(1, _TI_MAX + 1)]:
            _td = o.get("t" + _tk + "d") or ""
            _ta = o.get("t" + _tk + "a") or 0
            if _td or (_ta and abs(_ta) > _eps):   # z1137: 마이너스 발행액도 「끊은 것」이다
                _iss.append({"n": int(_tk), "date": _td, "amt": _ta})
        _chips = []
        for _it in _iss:
            _lab = "%d차" % _it["n"]
            _chips.append({"label": _lab, "date": _it["date"],
                           "amt_fmt": (_money(_it["amt"], o["currency"]) if _it["amt"] else "")})
        o["tier_chips"] = _chips   # 빈 리스트 = 미발행
        o["receipts"] = hist_map.get(o["order_id"], [])   # z745b 부분수금 이력
        o["recv_cnt"] = len(o["receipts"])

    # ── 분류: '발행 대기'(미발행 잔액>0)·연체·조건미설정 상단 고정 + 기준월 입금예정 ──
    #   v5H226z908 (대표 지시): '챙길 것' 기준을 '완전 미발행'→'미발행 잔액 남음'으로 확장(부분 누락 포착).
    billing = [o for o in shipped if o.get("billing_due")]
    billing_ids = {o["order_id"] for o in billing}
    overdue = [o for o in shipped if o["issued"] and o["outstanding_incl"] > 0.0001
               and o["dday"] is not None and o["dday"] < 0
               and o["order_id"] not in billing_ids]
    noterm = [o for o in shipped if o["issued"] and (not o["expected_date"])
              and o["outstanding_incl"] > 0.0001 and o["order_id"] not in billing_ids]
    overdue_ids = {o["order_id"] for o in overdue}
    action, seen = [], set()
    # z1191z98 (대표 11-22 「5·6 합치기」): 이 화면 = 🧾 마감(계산서 발행 대기)만 위에 — 예정일 지남·조건 미설정은 💰 입금 → 입금 확인에서
    for o in billing:
        if o["order_id"] in seen:
            continue
        seen.add(o["order_id"])
        action.append(o)

    def _akey(o):
        if o["order_id"] in billing_ids:
            return (0, -abs(o.get("unbilled") or 0), o["order_no"])   # 미발행 잔액 큰 순(z1137: 크기로 — 마이너스 잔액도 챙길 금액)
        if o["order_id"] in overdue_ids:
            return (1, o["dday"] if o["dday"] is not None else 0, o["order_no"])
        return (2, o.get("order_date") or "", o["order_no"])
    action.sort(key=_akey)

    # z920 (대표 지시): 월 제한 제거 — 발행완료·수금 대상 전체(날짜 필터는 클라이언트에서 세금계산서 발행일 기준).
    inmonth = [o for o in shipped
               if o["issued"] and o["order_id"] not in seen]
    inmonth.sort(key=lambda x: ((x["expected_date"] or "9999-99"), x["order_no"]))
    for _i, _o in enumerate(action):        # z916 레코드 줄무늬(홀짝 배경)로 구분 강화
        _o["ridx"] = _i
    for _i, _o in enumerate(inmonth):
        _o["ridx"] = _i

    def _ksum(lst):   # KRW 만 합산(외화 혼합 방지) — 미수(부가세 포함) 기준
        return sum((o["outstanding_incl"] if o["outstanding_incl"] > 0 else 0)
                   for o in lst if o["currency"] == "KRW")
    def _ksum_unb(lst):   # 미발행 잔액 합(KRW)
        return sum((o.get("unbilled") or 0) for o in lst if o["currency"] == "KRW")
    kpi = {"ym": ym,
           "billing_cnt": len(billing), "billing_sum": _fmt_money(_ksum_unb(billing), "KRW"),
           # v5H226z1137 (대표 결정 2026-10-02 「목록과 맞춘다」): 위 숫자 = 아래 목록에서 「마감이월」로 나오는 줄 수.
           #   예전엔 `발행합계 0 이하`를 세어 ① 마이너스로 다 끊은 건 ② 끊을 세금계산서가 없는 0원 수주까지 들어가
           #   위 27건 · 목록 20건으로 어긋났다(운영 실측). 줄의 상태(state)와 **같은 조건**으로 센다 — 따로 세면 또 어긋난다.
           "carryover_cnt": sum(1 for o in shipped if o.get("state") == "마감이월"),
           "expect_sum": _fmt_money(_ksum(inmonth), "KRW"),
           "overdue_cnt": len(overdue), "overdue_sum": _fmt_money(_ksum(overdue), "KRW"),
           "outstanding_sum": _fmt_money(_ksum(shipped), "KRW"),
           "fx_cnt": sum(1 for o in shipped if o["currency"] != "KRW")}

    try:
        _y, _m = int(ym[:4]), int(ym[5:7])
        prev_ym = (date(_y, _m, 1) - timedelta(days=1)).strftime("%Y-%m")
        _ny, _nm = (_y + 1, 1) if _m == 12 else (_y, _m + 1)
        next_ym = "%04d-%02d" % (_ny, _nm)
    except Exception:
        prev_ym = next_ym = ym

    return ctx(req, "sales_shipments_receipts.html", user=u, active="sales_shipments",
               can_money=can_money, ym=ym, prev_ym=prev_ym, next_ym=next_ym,
               today_iso=today.isoformat(), action=action, inmonth=inmonth, kpi=kpi)


@app.post("/sales/shipments")
async def sales_shipments_create(req: Request):
    """출하 등록 (Top3-S1-2차 — shipments INSERT + orders.SHIPPED + history · 1:N 부분출하)"""
    u = _s1_guard(req)
    if not u:
        return JSONResponse({"error": "권한 없음"}, 401)
    form = await req.form()
    order_id = form.get("order_id") or None
    shipped_qty = float(form.get("shipped_qty") or 0)
    tracking = form.get("tracking") or None
    if not order_id:
        return JSONResponse({"error": "order_id 누락"}, 400)
    # v5H112: 출하 수량 검증
    if shipped_qty <= 0:
        return JSONResponse(
            {"error": f"출하 수량은 0보다 커야 합니다 (입력값: {shipped_qty})."}, 400
        )
    with db_session() as c:
        o = c.execute("SELECT status FROM orders WHERE id=?", (order_id,)).fetchone()
        if not o:
            return JSONResponse({"error": "수주 없음"}, 404)
        prev_status = o[0]
        # v5H112: 출하 OVER 차단 — 누적 출하 합계 vs 수주 수량 (orders.unit_qty 또는 order_items SUM)
        try:
            ord_qty_row = c.execute(
                "SELECT COALESCE(unit_qty, "
                "(SELECT SUM(quantity) FROM order_items WHERE order_id=?), 0) AS oq "
                "FROM orders WHERE id=?",
                (order_id, order_id),
            ).fetchone()
            ord_qty = (ord_qty_row[0] or 0) if ord_qty_row else 0
            shipped_so_far_row = c.execute(
                "SELECT COALESCE(SUM(shipped_qty),0) FROM shipments WHERE order_id=?",
                (order_id,),
            ).fetchone()
            shipped_so_far = shipped_so_far_row[0] or 0
            if ord_qty > 0 and (shipped_so_far + shipped_qty) > ord_qty + 0.0001:
                return JSONResponse(
                    {"error": (
                        f"출하 수량 초과 — 수주 {ord_qty} / 기존 출하 {shipped_so_far} / "
                        f"이번 출하 {shipped_qty} = 누적 {shipped_so_far + shipped_qty}. "
                        "수주 수량 내로 입력해주세요."
                    )}, 400,
                )
        except Exception:
            pass  # 검증 실패 시 통과 (backward compatible)
        cur = c.execute(
            """INSERT INTO shipments
               (order_id, shipped_at, shipped_qty, shipped_by, tracking)
               VALUES (?,?,?,?,?)""",
            (order_id, datetime.now().isoformat(timespec="seconds"),
             shipped_qty, u.get("id"), tracking),
        )
        # SHIPPED 으로 전환 (READY_TO_SHIP 또는 IN_PRODUCTION → SHIPPED)
        if prev_status != "SHIPPED":
            c.execute("UPDATE orders SET status='SHIPPED' WHERE id=?", (order_id,))
            c.execute(
                """INSERT INTO order_status_history
                   (order_id, from_status, to_status, changed_by, note)
                   VALUES (?,?,?,?,?)""",
                (order_id, prev_status, "SHIPPED", u.get("id"),
                 f"출하 등록 (수량 {shipped_qty})"),
            )
        _ship_id = cur.lastrowid
    # 알림시스템 통합 (사이클 2026-04-26) — 출하 담당자에게 SALES 알림 (1시간 중복 방지 내장)
    notify_user(
        u.get("id"), "SALES",
        f"🚚 출하 등록 — 수주 {order_id}",
        body=f"수량 {shipped_qty} / 송장 {tracking or '-'}",
        link=f"/sales/orders/{order_id}",
    )
    return JSONResponse({"ok": True, "shipment_id": _ship_id})


@app.post("/sales/receipts")
async def sales_receipts_create(req: Request):
    """수금 등록 (Top3-S1-2차 — receipts_payment INSERT + 합계 비교 → PAID/유지 + history)
    PARTIAL_RECEIPT 별도 enum 폐기 — 합계 < 수주금액이면 SHIPPED 유지, 합계 >= 이면 PAID."""
    u = _s1_guard(req)
    if not u:
        return JSONResponse({"error": "권한 없음"}, 401)
    form = await req.form()
    order_id = form.get("order_id") or None
    amount = float(form.get("amount") or 0)
    method = form.get("method") or None
    note = form.get("note") or None
    # z745b(대표 지시): 수금 일자 입력(선택). 폼 received_at(YYYY-MM-DD)이면 그 날짜(정오), 없으면 현재시각.
    _recv_raw = (form.get("received_at") or "").strip()
    received_at = datetime.now().isoformat(timespec="seconds")
    if len(_recv_raw) == 10:
        try:
            datetime.strptime(_recv_raw, "%Y-%m-%d")
            received_at = _recv_raw + " 12:00:00"
        except Exception:
            pass
    # v5H124: 통화 입력 (화이트리스트, 미입력 시 KRW)
    _ALLOWED_CCY = {"KRW", "USD", "VND", "JPY", "CNY", "EUR"}
    currency = (form.get("currency") or "KRW").strip().upper()
    if currency not in _ALLOWED_CCY:
        return JSONResponse(
            {"error": f"허용되지 않는 통화: {currency}. (KRW/USD/VND/JPY/CNY/EUR 중 선택)"},
            400,
        )
    fx_rate_raw = form.get("fx_rate")
    fx_rate = None
    if fx_rate_raw:
        try:
            fx_rate = float(fx_rate_raw)
            if fx_rate <= 0:
                fx_rate = None
        except Exception:
            fx_rate = None
    # v5H126: fx_rate 미입력 + 비KRW 통화 → exchange_rates 에서 자동 snapshot
    if fx_rate is None and currency != "KRW":
        try:
            from .database import _get_active_fx_rate as _gafx
            _auto = _gafx(currency, ref_date=date.today().isoformat())
            if _auto and _auto > 0:
                fx_rate = _auto
        except Exception:
            pass
    if not order_id:
        return JSONResponse({"error": "order_id 누락"}, 400)
    # v5H112: 음수/0 수금 차단 — 친절한 에러
    if amount <= 0:
        return JSONResponse(
            {"error": f"수금액은 0보다 커야 합니다 (입력값: {amount}). 양수로 입력해주세요."},
            400,
        )
    with db_session() as c:
        # v5H124: orders.currency 함께 조회 (수주 통화 vs 수금 통화 mismatch 검출)
        try:
            o = c.execute(
                "SELECT status, total_amount, COALESCE(currency,'KRW') FROM orders WHERE id=?",
                (order_id,),
            ).fetchone()
        except Exception:
            o = c.execute(
                "SELECT status, total_amount, 'KRW' FROM orders WHERE id=?", (order_id,)
            ).fetchone()
        if not o:
            return JSONResponse({"error": "수주 없음"}, 404)
        prev_status, total, order_ccy = o[0], (o[1] or 0), (o[2] or "KRW")
        # 통화 mismatch 시 audit 경고 (차단 X — 환차 발생 가능, FYI)
        ccy_warn = None
        if currency != order_ccy:
            ccy_warn = (
                f"⚠ 통화 불일치 — 수주 {order_ccy} vs 수금 {currency} "
                f"(환산 누락 시 미수금 계산 오차 위험)"
            )
        # v5H124: receipts_payment 에 currency / fx_rate 가 있으면 함께 INSERT, 없으면 백워드
        rpcols2 = set()
        try:
            rpcols2 = {r[1] for r in c.execute("PRAGMA table_info(receipts_payment)").fetchall()}
        except Exception:
            pass
        if "currency" in rpcols2 and "fx_rate" in rpcols2:
            cur = c.execute(
                """INSERT INTO receipts_payment
                   (order_id, received_at, amount, method, received_by, note, currency, fx_rate)
                   VALUES (?,?,?,?,?,?,?,?)""",
                (order_id, received_at,
                 amount, method, u.get("id"), note, currency, fx_rate),
            )
        else:
            cur = c.execute(
                """INSERT INTO receipts_payment
                   (order_id, received_at, amount, method, received_by, note)
                   VALUES (?,?,?,?,?,?)""",
                (order_id, received_at,
                 amount, method, u.get("id"), note),
            )
        # v5H124: doc_audit_log — 수금 등록 + 통화 mismatch 경고 합성
        try:
            _audit_note = f"amount={amount} {currency}"
            if ccy_warn:
                _audit_note += f" | {ccy_warn}"
            _doc_audit_log(c, "receipts_payment", cur.lastrowid, "RECEIVE",
                           u.get("id"), _audit_note)
        except Exception:
            pass
        # 누적 수금 합계 → PAID 분기 (v5H124 — 수주 통화와 동일 통화만 합산해 PAID 판정)
        if "currency" in rpcols2:
            row = c.execute(
                """SELECT COALESCE(SUM(amount),0) FROM receipts_payment
                   WHERE order_id=? AND COALESCE(currency,'KRW')=?""",
                (order_id, order_ccy),
            ).fetchone()
        else:
            row = c.execute(
                "SELECT COALESCE(SUM(amount),0) FROM receipts_payment WHERE order_id=?",
                (order_id,),
            ).fetchone()
        paid_total = row[0] or 0
        # 통화가 같을 때만 PAID 자동 전환 (이종 통화는 수동 정산 권장)
        new_status = (
            "PAID" if (currency == order_ccy and paid_total >= total and total > 0)
            else prev_status
        )
        if new_status != prev_status:
            c.execute(
                "UPDATE orders SET status=? WHERE id=?", (new_status, order_id)
            )
            c.execute(
                """INSERT INTO order_status_history
                   (order_id, from_status, to_status, changed_by, note)
                   VALUES (?,?,?,?,?)""",
                (order_id, prev_status, new_status, u.get("id"),
                 f"수금 누적 {paid_total}/{total}"),
            )
        return JSONResponse({
            "ok": True, "receipt_id": cur.lastrowid,
            "paid_total": paid_total, "status": new_status,
            "currency": currency, "order_currency": order_ccy,
            "warning": ccy_warn,
        })


# =====================================================
# Top3 S1 3차 — 매출 대시 강화 + 매출 예측 (2026-04-26)
# 외부 차트·numpy 0건. _linear_regression (line 6572) 재사용.
# G1~G5 핫패치 보존, v2 본체 무수정.
# =====================================================

def _sales_monthly_series(c, months: int = 12):
    """최근 N개월 매출 시계열 (orders.order_date + total_amount).
    반환: [{ym, total, cnt}, ...] (오름차순). 빈 달은 0 채움.
    v5H123 (2026-05-04): 통화 혼합 집계 결함 수정 — currency 컬럼 존재 시 KRW 만 합산.
    USD/VND 등은 환율 미반영 단순 합산이 의미 없으므로 KRW 단독 기준이 정확. 폴백: 컬럼 미존재 시 기존 동작."""
    today = date.today()
    out = []
    # currency 컬럼 존재 여부 확인 (v5H92 이후)
    has_currency = False
    try:
        cols = [r[1] for r in c.execute("PRAGMA table_info(orders)").fetchall()]
        has_currency = "currency" in cols
    except Exception:
        pass
    for i in range(months - 1, -1, -1):
        y = today.year
        m = today.month - i
        while m <= 0:
            m += 12
            y -= 1
        ym = f"{y:04d}-{m:02d}"
        if has_currency:
            row = c.execute(
                """SELECT COALESCE(SUM(total_amount),0) AS total, COUNT(*) AS cnt
                   FROM orders WHERE order_date LIKE ?
                     AND status NOT IN ('CANCELLED','DRAFT')
                     AND COALESCE(currency,'KRW')='KRW'""",
                (f"{ym}%",),
            ).fetchone()
        else:
            row = c.execute(
                """SELECT COALESCE(SUM(total_amount),0) AS total, COUNT(*) AS cnt
                   FROM orders WHERE order_date LIKE ?
                     AND status NOT IN ('CANCELLED','DRAFT')""",
                (f"{ym}%",),
            ).fetchone()
        out.append({"ym": ym, "total": row[0] or 0, "cnt": row[1] or 0})
    return out


# z1191z140 (대표 11-24 「매출 예측 옛 화면 → 삭제」): _sales_forecast(선형회귀 예측) 지움 — /sales/forecast 는 매출 홈으로 넘김

def _sales_dashboard_ctx(c):
    """대시보드 + 예측 공통 컨텍스트 (KPI 8 + 차트 데이터 + 파이프라인).
    v5H123 (2026-05-04): 통화 혼합 집계 결함 수정 — orders.currency 컬럼 존재 시
    모든 SUM(total_amount) 쿼리를 KRW 단독으로 제한. 외화(USD/VND/JPY 등)는
    환율 미반영 단순 합산이 잘못된 KPI 를 만들기 때문 (대표 보고: 수주액 정합성).
    by_currency 분포는 별도 ctx 로 전달해 템플릿에서 펼침 가능."""
    today = date.today()
    ym = today.strftime("%Y-%m")
    # 전월
    py, pm = today.year, today.month - 1
    if pm <= 0:
        pm += 12; py -= 1
    prev_ym = f"{py:04d}-{pm:02d}"
    # currency 컬럼 존재 여부 (v5H92 이후)
    has_currency = False
    try:
        cols = [r[1] for r in c.execute("PRAGMA table_info(orders)").fetchall()]
        has_currency = "currency" in cols
    except Exception:
        pass
    krw_filter = " AND COALESCE(currency,'KRW')='KRW'" if has_currency else ""
    month_total = c.execute(
        f"""SELECT COALESCE(SUM(total_amount),0) FROM orders
           WHERE order_date LIKE ? AND status NOT IN ('CANCELLED','DRAFT'){krw_filter}""",
        (f"{ym}%",),
    ).fetchone()[0] or 0
    prev_total = c.execute(
        f"""SELECT COALESCE(SUM(total_amount),0) FROM orders
           WHERE order_date LIKE ? AND status NOT IN ('CANCELLED','DRAFT'){krw_filter}""",
        (f"{prev_ym}%",),
    ).fetchone()[0] or 0
    mom = ((month_total - prev_total) / prev_total * 100.0) if prev_total > 0 else 0.0
    # 통화별 분포 (이번달) — 다통화 거래 가시화
    by_currency = []
    if has_currency:
        try:
            by_currency = [dict(r) for r in c.execute(
                """SELECT COALESCE(currency,'KRW') AS currency,
                          COALESCE(SUM(total_amount),0) AS total,
                          COUNT(*) AS cnt
                   FROM orders WHERE order_date LIKE ?
                     AND status NOT IN ('CANCELLED','DRAFT')
                   GROUP BY COALESCE(currency,'KRW') ORDER BY total DESC""",
                (f"{ym}%",),
            ).fetchall()]
        except Exception:
            by_currency = []
    # 수금률 = 수금 합계 / INVOICED+PAID 수주 합계 (KRW 한정)
    inv_total = c.execute(
        f"""SELECT COALESCE(SUM(total_amount),0) FROM orders
           WHERE status IN ('INVOICED','PAID','SHIPPED'){krw_filter}"""
    ).fetchone()[0] or 0
    rcv_total = c.execute(
        "SELECT COALESCE(SUM(amount),0) FROM receipts_payment"
    ).fetchone()[0] or 0
    rcv_rate = (rcv_total / inv_total * 100.0) if inv_total > 0 else 0.0
    # 평균 결제 일수 (issue_date → 첫 수금)
    avg_days = 0.0
    rows = c.execute(
        """SELECT i.order_id, MIN(i.issue_date) AS iss,
                  MIN(rp.received_at) AS rcv
           FROM invoices i
           LEFT JOIN receipts_payment rp ON rp.order_id = i.order_id
           WHERE i.issue_date IS NOT NULL AND rp.received_at IS NOT NULL
           GROUP BY i.order_id LIMIT 200"""
    ).fetchall()
    if rows:
        days_list = []
        for r in rows:
            try:
                d1 = datetime.strptime(r[1][:10], "%Y-%m-%d")
                d2 = datetime.strptime(r[2][:10], "%Y-%m-%d")
                days_list.append((d2 - d1).days)
            except Exception:
                pass
        if days_list:
            avg_days = sum(days_list) / len(days_list)
    # 미수금 = INVOICED 수주 합 - 수금
    unpaid = max(0.0, inv_total - rcv_total)
    active_orders = c.execute(
        """SELECT COUNT(*) FROM orders
           WHERE status IN ('CONFIRMED','IN_PRODUCTION','READY_TO_SHIP')"""
    ).fetchone()[0] or 0
    in_prod = c.execute(
        "SELECT COUNT(*) FROM production_orders WHERE status='IN_PRODUCTION'"
    ).fetchone()[0] or 0
    # 출하 임박 = due_date 7일 이내 + status IN_PRODUCTION/READY_TO_SHIP
    soon_end = (today + timedelta(days=7)).isoformat()
    ship_soon = c.execute(
        """SELECT COUNT(*) FROM orders
           WHERE due_date IS NOT NULL AND due_date <= ? AND due_date >= ?
             AND status IN ('IN_PRODUCTION','READY_TO_SHIP','CONFIRMED')""",
        (soon_end, today.isoformat()),
    ).fetchone()[0] or 0
    # 파이프라인 9 status 분포
    pipeline = {s: 0 for s in ["DRAFT", "QUOTED", "CONFIRMED", "IN_PRODUCTION",
                                "READY_TO_SHIP", "SHIPPED", "INVOICED", "PAID", "CANCELLED"]}
    for r in c.execute(
        "SELECT status, COUNT(*) AS cnt FROM orders GROUP BY status"
    ).fetchall():
        if r[0] in pipeline:
            pipeline[r[0]] = r[1]
    # 거래처 Top 5 (Pareto) — v5H123 KRW 단독 (통화 혼합 방지)
    if has_currency:
        top_customers = [dict(r) for r in c.execute(
            """SELECT COALESCE(cu.name,'-') AS name,
                      COUNT(*) AS cnt, COALESCE(SUM(o.total_amount),0) AS total
               FROM orders o LEFT JOIN customers cu ON cu.id = o.customer_id
               WHERE o.status NOT IN ('CANCELLED','DRAFT')
                 AND COALESCE(o.currency,'KRW')='KRW'
               GROUP BY o.customer_id ORDER BY total DESC LIMIT 5"""
        ).fetchall()]
    else:
        top_customers = [dict(r) for r in c.execute(
            """SELECT COALESCE(cu.name,'-') AS name,
                      COUNT(*) AS cnt, COALESCE(SUM(o.total_amount),0) AS total
               FROM orders o LEFT JOIN customers cu ON cu.id = o.customer_id
               WHERE o.status NOT IN ('CANCELLED','DRAFT')
               GROUP BY o.customer_id ORDER BY total DESC LIMIT 5"""
        ).fetchall()]
    grand_total = sum(t["total"] for t in top_customers) or 1
    cum = 0.0
    for t in top_customers:
        cum += t["total"]
        t["pct"] = (t["total"] / grand_total * 100.0)
        t["cum_pct"] = (cum / grand_total * 100.0)
    # v5H126: 통화별 미수금 (수주 INVOICED+SHIPPED+PAID - 수금) — 외화 가시화
    outstanding_by_currency = []
    if has_currency:
        try:
            # receipts_payment.currency 컬럼 존재 검사
            rpcols = {r[1] for r in c.execute("PRAGMA table_info(receipts_payment)").fetchall()}
            rcv_ccy = "COALESCE(currency,'KRW')" if "currency" in rpcols else "'KRW'"
            inv_rows = c.execute(
                """SELECT COALESCE(currency,'KRW') AS ccy,
                          COALESCE(SUM(total_amount),0) AS inv
                   FROM orders
                   WHERE status IN ('INVOICED','PAID','SHIPPED')
                   GROUP BY COALESCE(currency,'KRW')"""
            ).fetchall()
            rcv_rows = c.execute(
                f"""SELECT {rcv_ccy} AS ccy,
                           COALESCE(SUM(amount),0) AS rcv
                    FROM receipts_payment
                    GROUP BY {rcv_ccy}"""
            ).fetchall()
            _rcv_map = {r[0]: float(r[1] or 0) for r in rcv_rows}
            for r in inv_rows:
                ccy = r[0]
                inv = float(r[1] or 0)
                rcv = _rcv_map.get(ccy, 0.0)
                out = max(0.0, inv - rcv)
                if inv > 0 or rcv > 0:
                    outstanding_by_currency.append({
                        "currency": ccy, "invoiced": inv,
                        "received": rcv, "outstanding": out,
                    })
            outstanding_by_currency.sort(key=lambda x: -x["outstanding"])
        except Exception:
            outstanding_by_currency = []
    series = _sales_monthly_series(c, 12)
    chart_max = max((s["total"] for s in series), default=1) or 1
    return {
        "kpi": {
            "month_total": month_total, "mom": mom,
            "rcv_rate": rcv_rate, "avg_days": avg_days,
            "unpaid": unpaid, "active_orders": active_orders,
            "in_prod": in_prod, "ship_soon": ship_soon,
        },
        "ym": ym, "prev_ym": prev_ym,
        "pipeline": pipeline,
        "top_customers": top_customers,
        "series": series, "chart_max": chart_max,
        "by_currency": by_currency,  # v5H123 통화별 분포 (KRW 외 외화 노출용)
        "outstanding_by_currency": outstanding_by_currency,  # v5H126 통화별 미수금
        "primary_currency": "KRW",   # v5H123 KPI 통화 기준 명시
    }


