# =====================================================
# Top3 S1 4차 — 미수금 추적 + 수금 알림 자동 (2026-04-26)
# 헬퍼 _outstanding_receivables / check_receivable_alerts.
# 알림 통합 (사이클 2026-04-26 notify_user SALES) 활용 · 1시간 중복 방지 내장.
# G1~G5 핫패치 보존 · v2 본체 무수정 · 외부 자산 0건.
# =====================================================

def _parse_terms_days(terms: str) -> int:
    """payment_terms 문자열 → 일수. NET30/30일/선금 등 휴리스틱.
    매칭 실패 시 30 (기본 NET30)."""
    if not terms:
        return 30
    s = str(terms).upper().replace(" ", "")
    # NET#, #일, #DAYS
    import re
    m = re.search(r"(\d{1,3})", s)
    if m:
        try:
            d = int(m.group(1))
            if 0 < d <= 365:
                return d
        except Exception:
            pass
    if "선금" in str(terms) or "CASH" in s or "현금" in str(terms):
        return 0
    return 30


def _outstanding_receivables(c, only_overdue: bool = False):
    """⚠ z1191z99 부터 화면·알림 어디서도 쓰지 않음 — 받을 돈은 _rc_rows_z94 한 곳(입금 확인·미수 현황·수금 알림·매출 분석·대표 대시).
    미수금 건별 집계 — orders.total_amount - SUM(receipts_payment.amount).
    z745b(대표 지시): 만기 = **세금계산서 발행일 + 고객사 pay_days**(납품·수금 화면과 통일).
      발행일 = 그 수주 호기(order_items.tax_invoice_date) 중 가장 이른 날(없으면 orders 폴백).
      발행일 없으면(미발행) 발주일 기준으로 폴백(보수적). pay_days 미설정(0)이면 레거시 payment_terms 폴백.
    등급: CURRENT(미만기) / D-30 / D-60 / D-90+ (연체일 기준). Returns: list of dicts (overdue desc)."""
    today = date.today()
    oic = {r[1] for r in c.execute("PRAGMA table_info(order_items)").fetchall()}
    ordc = {r[1] for r in c.execute("PRAGMA table_info(orders)").fetchall()}
    cusc = {r[1] for r in c.execute("PRAGMA table_info(customers)").fetchall()}
    _pd = "COALESCE(cu.pay_days,0)" if "pay_days" in cusc else "0"
    _pt = "COALESCE(cu.pay_term,'')" if "pay_term" in cusc else "''"   # z1191z95
    # 발행일 per order: 호기 tax_invoice_date 우선 → orders 폴백, 가장 이른 날
    i_td = "oi.tax_invoice_date" if "tax_invoice_date" in oic else "NULL"
    o_td = "o.tax_invoice_date" if "tax_invoice_date" in ordc else "NULL"
    issue_map = {}
    try:
        for r in c.execute(f"SELECT oi.order_id AS oid, {i_td} AS itd, {o_td} AS otd "
                           f"FROM order_items oi JOIN orders o ON o.id=oi.order_id"):
            d = dict(r)
            dt = (str(d["itd"] or "").strip() or str(d["otd"] or "").strip())[:10]
            if dt:
                oid = d["oid"]
                if oid not in issue_map or dt < issue_map[oid]:
                    issue_map[oid] = dt
    except Exception:
        issue_map = {}
    rows = c.execute(
        f"""SELECT o.id AS order_id, o.order_no, o.order_date, o.due_date,
                  o.total_amount, o.status, o.customer_id,
                  COALESCE(cu.name,'-') AS customer_name,
                  {_pd} AS pay_days, {_pt} AS pay_term,
                  COALESCE((SELECT SUM(amount) FROM receipts_payment rp
                            WHERE rp.order_id=o.id), 0) AS paid_total,
                  COALESCE((SELECT terms FROM payment_terms pt
                            WHERE pt.customer_id=o.customer_id
                            ORDER BY pt.id DESC LIMIT 1), '') AS terms
           FROM orders o
           LEFT JOIN customers cu ON cu.id = o.customer_id
           WHERE o.status IN ('SHIPPED','INVOICED')
             AND o.total_amount > 0"""
    ).fetchall()
    out = []
    for r in rows:
        d = dict(r)
        outstanding = (d["total_amount"] or 0) - (d["paid_total"] or 0)
        if outstanding <= 0:
            continue
        # 만기 기준일 = 세금계산서 발행일(있으면) → 없으면 발주일 폴백
        issue_date = issue_map.get(d["order_id"], "")
        base_iso = issue_date or (d["order_date"] or today.isoformat())
        try:
            base = datetime.strptime(base_iso[:10], "%Y-%m-%d").date()
        except Exception:
            base = today
        # z1191z95: 결제 조건 = 고객사 고른 것(규칙 한 곳) → 안 골랐는데 옛 결제조건 글자가 있으면 그것 → 둘 다 없으면 기본 60일
        if _pay_term_norm_z95(d.get("pay_term"), d.get("pay_days"))[0] or not str(d.get("terms") or "").strip():
            due = _pay_due_z95(base, d.get("pay_term"), d.get("pay_days"))
        else:
            due = base + timedelta(days=_parse_terms_days(d["terms"]))
        days_terms = (due - base).days
        overdue_days = (today - due).days  # 음수 = 만기 이전
        if only_overdue and overdue_days <= 0:
            continue
        if overdue_days <= 0:
            grade = "CURRENT"
        elif overdue_days <= 30:
            grade = "D-30"
        elif overdue_days <= 60:
            grade = "D-60"
        else:
            grade = "D-90+"
        d["outstanding"] = outstanding
        d["issue_date"] = issue_date
        d["due_base"] = "발행일" if issue_date else "발주일(미발행)"
        d["due_date_calc"] = due.isoformat()
        d["overdue_days"] = overdue_days
        d["grade"] = grade
        d["terms_days"] = days_terms
        out.append(d)
    out.sort(key=lambda x: (-x["overdue_days"], -x["outstanding"]))
    return out


def _outstanding_summary(items):
    """등급별 집계 KPI."""
    grades = {"CURRENT": 0.0, "D-30": 0.0, "D-60": 0.0, "D-90+": 0.0}
    counts = {"CURRENT": 0, "D-30": 0, "D-60": 0, "D-90+": 0}
    total = 0.0
    overdue_total = 0.0
    for it in items:
        g = it["grade"]
        amt = it["outstanding"]
        grades[g] = grades.get(g, 0.0) + amt
        counts[g] = counts.get(g, 0) + 1
        total += amt
        if g != "CURRENT":
            overdue_total += amt
    return {
        "by_grade": grades, "counts": counts,
        "total": total, "overdue_total": overdue_total,
        "n_total": len(items),
        "overdue_rate": (overdue_total / total * 100.0) if total > 0 else 0.0,
    }


# =====================================================
# v5H226z929 (대표 지시): 은행 입금내역 대사 — 계좌 엑셀 업로드→파싱→미리보기 (1단계).
#   여러 은행(국민·우리·신한 등) 대응 = 헤더 자동감지 + 컬럼 키워드 매핑(+수동보정 여지).
#   ⛔은행 계정·비번 미사용(대표가 내려받은 파일만). 1단계=미리보기라 저장 안 함(개인정보 보호).
#   다음(2단계)=이 입금들을 미수(부가세 포함)와 자동 매칭→수금 처리.
# =====================================================
_BANK_DATE_KEYS  = ["거래일시", "거래일자", "거래일", "일시", "일자", "날짜", "거래날짜"]
_BANK_DEP_KEYS   = ["입금액", "맡기신금액", "맡기신", "입금(원)", "입금금액", "입금"]
_BANK_WD_KEYS    = ["출금액", "찾으신금액", "찾으신", "출금(원)", "출금금액", "출금"]
_BANK_AMT_KEYS   = ["거래금액", "거래액"]   # 입금/출금 분리 없는 은행의 부호금액 폴백
_BANK_PAYER_KEYS = ["보낸분", "받는분", "의뢰인", "수취인", "상대방", "거래상대", "내용", "기재내용"]
_BANK_MEMO_KEYS  = ["송금메모", "메모", "적요", "내용", "기재사항", "통장표시"]


def _bank_pick_col(headers, keys):
    """헤더 목록에서 keys(우선순위 순) 를 정확일치→부분일치로 찾아 열 index."""
    for k in keys:
        for j, h in enumerate(headers):
            if h == k:
                return j
    for k in keys:
        for j, h in enumerate(headers):
            if k and k in h:
                return j
    return None


def _bank_amt(s):
    import re as _re
    if s is None:
        return 0.0
    t = _re.sub(r"[^0-9.\-]", "", str(s))
    if t in ("", "-", "."):
        return 0.0
    try:
        return float(t)
    except Exception:
        return 0.0


def _bank_date(s):
    import re as _re
    m = _re.search(r"(\d{4})[.\-/년\s]*(\d{1,2})[.\-/월\s]*(\d{1,2})", str(s or ""))
    if m:
        return "%04d-%02d-%02d" % (int(m.group(1)), int(m.group(2)), int(m.group(3)))
    return str(s or "")[:10]


def _parse_bank_excel(raw, filename, override=None):
    """은행 거래내역 엑셀(raw bytes) → 입금건 목록. 여러 은행 대응(헤더 자동감지+컬럼 매핑).
    .xlsx=openpyxl · .xls=xlrd(1.2). ⛔pandas 미사용(NAS 미설치·requirements 는 openpyxl+xlrd).
    반환 dict: ok / headers / header_idx / col_map / deposits[{date,payer,amount,memo}] / n_rows / warning."""
    import io as _io
    ext = (filename or "").lower().rsplit(".", 1)[-1]

    def _grid_openpyxl():
        from openpyxl import load_workbook
        wb = load_workbook(_io.BytesIO(raw), data_only=True, read_only=True)
        ws = wb.active
        g = [[c.value for c in row] for row in ws.iter_rows()]
        wb.close()
        return g

    def _grid_xlrd():
        import xlrd
        book = xlrd.open_workbook(file_contents=raw)
        sh = book.sheet_by_index(0)
        return [[sh.cell_value(r, cc) for cc in range(sh.ncols)] for r in range(sh.nrows)]

    grid = None
    rerr = None
    order = (_grid_xlrd, _grid_openpyxl) if ext == "xls" else (_grid_openpyxl, _grid_xlrd)
    for fn in order:
        try:
            grid = fn()
            if grid:
                break
        except Exception as e:
            rerr = e
            grid = None
    if not grid:
        if ext == "xls":
            return {"ok": False, "warning": "이 .xls 파일을 서버에서 읽지 못했습니다. Excel에서 열어 '다른 이름으로 저장 → .xlsx'로 바꿔 다시 올려주시면 됩니다."}
        return {"ok": False, "warning": "엑셀을 읽지 못했습니다(%s)." % rerr}

    def S(v):
        return "" if v is None else str(v).strip()
    hidx = None
    for i in range(min(25, len(grid))):
        joined = " ".join(S(x) for x in grid[i])
        hits = sum(1 for k in ["거래", "입금", "출금", "잔액", "일시", "일자", "금액", "적요", "의뢰", "받는", "보낸", "맡기신", "찾으신"] if k in joined)
        if hits >= 3:
            hidx = i
            break
    if hidx is None:
        return {"ok": False, "warning": "입금내역 표의 헤더(거래일·입금·출금 등)를 찾지 못했습니다."}
    headers = [S(x) for x in grid[hidx]]
    cm = {
        "date": _bank_pick_col(headers, _BANK_DATE_KEYS),
        "dep": _bank_pick_col(headers, _BANK_DEP_KEYS),
        "wd": _bank_pick_col(headers, _BANK_WD_KEYS),
        "amt": _bank_pick_col(headers, _BANK_AMT_KEYS),
        "payer": _bank_pick_col(headers, _BANK_PAYER_KEYS),
        "memo": _bank_pick_col(headers, _BANK_MEMO_KEYS),
    }
    if override:
        for k in ("date", "dep", "payer", "memo"):
            v = override.get(k)
            if v not in (None, ""):
                try:
                    cm[k] = int(v)
                except Exception:
                    pass
    deposits = []
    for r in range(hidx + 1, len(grid)):
        row = grid[r]

        def _c(role, _row=row):
            j = cm.get(role)
            return _row[j] if (j is not None and j < len(_row)) else None
        dep = _bank_amt(_c("dep")) if cm.get("dep") is not None else 0.0
        if (cm.get("dep") is None) and (cm.get("amt") is not None):
            a = _bank_amt(_c("amt"))
            dep = a if a > 0 else 0.0
        if dep <= 0:
            continue
        deposits.append({
            "date": _bank_date(_c("date")),
            "payer": S(_c("payer")),
            "amount": dep,
            "memo": S(_c("memo")),
        })
    return {"ok": True, "headers": headers, "header_idx": hidx, "col_map": cm,
            "deposits": deposits, "n_rows": max(0, len(grid) - hidx - 1),
            "warning": ("" if deposits else "입금(입금액>0) 건이 없습니다. 파일이 전부 출금이거나 컬럼 매핑이 다를 수 있어요.")}


@app.get("/sales/bank-recon", response_class=HTMLResponse)
async def bank_recon_page(req: Request):
    """은행 입금내역 대사 — 업로드 화면(1단계·미리보기)."""
    u = require(req, ["admin", "ceo", "executive"])
    if u and (u.get("role") or "") == "admin" and not can_use_sales(u):   # z1191g: 관리자는 매출 등록 체크가 있어야
        u = None
    if not u:
        return RedirectResponse("/home", 303)
    return ctx(req, "bank_recon.html", user=u, active="sales", result=None)


@app.post("/sales/bank-recon")
async def bank_recon_upload(req: Request):
    """엑셀 업로드→파싱→미리보기. 저장하지 않음(1단계)."""
    u = require(req, ["admin", "ceo", "executive"])
    if u and (u.get("role") or "") == "admin" and not can_use_sales(u):   # z1191g: 관리자는 매출 등록 체크가 있어야
        u = None
    if not u:
        return RedirectResponse("/home", 303)
    form = await req.form()
    up = form.get("file")
    if up is None or not getattr(up, "filename", ""):
        return ctx(req, "bank_recon.html", user=u, active="sales",
                   result={"ok": False, "warning": "파일을 선택하세요."})
    raw = await up.read()
    override = {k: form.get("col_" + k) for k in ("date", "dep", "payer", "memo")}
    res = _parse_bank_excel(raw, up.filename, override=override)
    res["filename"] = getattr(up, "filename", "")
    if res.get("ok"):
        for d in res["deposits"]:
            d["amount_fmt"] = "{:,.0f}".format(d["amount"])
        res["dep_cnt"] = len(res["deposits"])
        res["dep_total_fmt"] = "{:,.0f}".format(sum(d["amount"] for d in res["deposits"]))
    return ctx(req, "bank_recon.html", user=u, active="sales", result=res)


# =====================================================
# z1191z100 (대표 11-22 「수금 알림은 평일 9시, 안지연 프로만 받게 켜줘 · 담당자 설정을 할 수 있게」)
#   · 평일(주말·공휴일 HOLIDAYS_KR 빼고) 오전 9시(한국시간) 하루 한 번 — 받는 사람마다 묶음 알림 1건
#   · 받는 사람 = app_settings 'ar_alert_recipients_z100'(users.id 목록) · 저장된 적 없으면 안지연 프로(사번 67)
#   · 웍스 🔔 알림함 + 이음 「WORKS 알림」(휴대폰) — 이음 쪽은 웍스 알림 규칙(v968: 김정락·안지연·이새롬만)을 따른다
#   · 계산 = 💰 입금 확인과 같은 줄(_rc_rows_z94) · 하루 한 번 = app_settings 'ar_alert_last_run_z100' 에 날짜를 먼저 잡은 쪽만
# =====================================================
_AR_ALERT_KEY_Z100 = "ar_alert_recipients_z100"
_AR_ALERT_LAST_Z100 = "ar_alert_last_run_z100"
_AR_ALERT_DEFAULT_EMP_Z100 = "67"     # 대표 11-22: 지금은 안지연 프로만
_AR_ALERT_HOUR_Z100 = 9
_AR_ALERT_TAGS_Z100 = ((-1, "🔴 예정일 1일 지남(새로 지남)"), (7, "🟠 예정일 7일 전"),
                       (-30, "🔴 예정일 30일 지남"), (-60, "🔴 예정일 60일 지남"))


def _ar_alert_span_z100(day):
    """오늘 알림이 맡을 날 수 k — 지난 평일(공휴일 빼고) 다음 날부터 오늘까지. 평소 1 · 월요일 3 · 연휴 뒤 더 길게.
    (알림은 평일에만 돌므로, 예정일이 주말·공휴일에 걸린 계산서가 「딱 그날」만 보면 빠진다)"""
    k = 1
    while k < 15 and not _ar_alert_workday_z100(day - timedelta(days=k)):
        k += 1
    return k


def _ar_alert_recipient_ids_z100(c):
    """받는 사람 users.id 목록(일하는 계정만 · 저장 순서). 저장된 적 없으면 안지연 프로(사번 67)."""
    import json as _j100
    row = c.execute("SELECT value FROM app_settings WHERE key=?", (_AR_ALERT_KEY_Z100,)).fetchone()
    if row is not None:
        try:
            ids = [int(x) for x in _j100.loads(row[0] or "[]")]
        except (ValueError, TypeError):
            print("[z1191z100] 수금 알림 받는 사람 설정을 읽지 못함:", repr(row[0])[:80])
            ids = []
    else:
        r = c.execute("SELECT id FROM users WHERE employee_no=? AND COALESCE(is_active,1)=1",
                      (_AR_ALERT_DEFAULT_EMP_Z100,)).fetchone()
        ids = [int(r[0])] if r else []
    if not ids:
        return []
    ph = ",".join("?" * len(ids))
    ok = {int(r[0]) for r in c.execute("SELECT id FROM users WHERE id IN (%s) AND COALESCE(is_active,1)=1" % ph, ids).fetchall()}
    return [i for i in ids if i in ok]


def _ar_alert_digest_z100(rows, span=1):
    """하루 묶음 알림 글. 반환 (새로 챙길 장수, 제목, 본문, 보낼지). 지난 돈도 새 것도 없으면 보내지 않음.
    span = 이번 알림이 맡을 날 수(월요일 3 = 금·토·일 몫) — 각 묶음은 기준일에서 span 일 사이(dd-span < 남은 날 ≤ dd)."""
    from datetime import date as _d100
    span = max(1, int(span or 1))
    lines, n_new = [], 0
    for dd, lab in _AR_ALERT_TAGS_Z100:
        xs = [x for x in rows if x["dday"] is not None and dd - span < x["dday"] <= dd]
        if not xs:
            continue
        n_new += len(xs)
        if span > 1:
            lab += "(주말·휴일 포함 %d일 치)" % span
        lines.append("%s %d장" % (lab, len(xs)))
        for x in xs[:8]:
            lines.append("  · %s %s %s (예정일 %s)" % (x["cname"], x["order_no"], x["rem_fmt"], x["due"]))
        if len(xs) > 8:
            lines.append("  · …외 %d장" % (len(xs) - 8))
    over = {}
    for x in rows:
        if x["dday"] is not None and x["dday"] < 0:
            over[x["ccy"]] = over.get(x["ccy"], 0) + x["rem"]
    n_over_cust = len({x["cid"] for x in rows if x["dday"] is not None and x["dday"] < 0})
    over_txt = " · ".join(_fmt_money(v, k) for k, v in sorted(over.items(), key=lambda kv: (kv[0] != "KRW", kv[0])))
    if over:
        lines.append("전체 예정일 지난 돈: %s (%d곳)" % (over_txt, n_over_cust))
    lines.append("→ 💰 입금 → 입금 확인에서 관리팀 확인 뒤 [✅ 입금 확인됨]")
    md = _d100.today().strftime("%m-%d")
    if n_new:
        title = "💰 수금 확인 %s — 새로 챙길 계산서 %d장" % (md, n_new)
    else:
        title = "💰 수금 확인 %s — 예정일 지난 돈 %s" % (md, over_txt or "없음")
    return n_new, title, "\n".join(lines), bool(n_new or over)


def check_receivable_alerts(recipient_ids=None):
    """수금 알림 — 받는 사람마다 묶음 1건(웍스 🔔 + 이음 WORKS 알림). recipient_ids 없으면 설정값(기본 안지연 프로).
    z1191z99: 계산 = 💰 입금 확인과 같은 줄 · z1191z100: 계산서마다 따로 → 하루 묶음 1건(알림 수십 건 쏟아짐 방지).
    Returns: {sent, skipped, items, new, recipients, messenger, messenger_error}."""
    rc_rows = _rc_rows_z94({})["rows"]
    _today100 = _kst_wall_now().date()
    _span100 = _ar_alert_span_z100(_today100) if _ar_alert_workday_z100(_today100) else 1
    n_new, title, body, has = _ar_alert_digest_z100(rc_rows, _span100)
    with db_session() as c:
        ids = list(recipient_ids) if recipient_ids is not None else _ar_alert_recipient_ids_z100(c)
        emps = []
        if ids:
            ph = ",".join("?" * len(ids))
            emps = [str(r[0]) for r in c.execute(
                "SELECT employee_no FROM users WHERE id IN (%s) AND COALESCE(employee_no,'')<>''" % ph, ids).fetchall()]
    out = {"sent": 0, "skipped": 0, "items": len(rc_rows), "new": n_new, "recipients": len(ids),
           "messenger": None, "messenger_error": ""}
    if not has or not ids:
        return out
    link = "/sales/receipts-check"
    for uid in ids:
        if notify_user(uid, "SALES", title, body=body, link=link):
            out["sent"] += 1
        else:
            out["skipped"] += 1
    if out["sent"] and emps:   # 웍스 알림함에 새로 넣었을 때만 이음으로도(1시간 안 같은 알림 두 번 막기와 같게)
        try:
            from . import sso_client as _sso100
            _pub = os.environ.get("KNK_WORKS_PUBLIC_BASE", "https://works.knknara.co.kr").rstrip("/")
            _m = _sso100.notify_via_messenger(emps, title, body, _pub + link)
            out["messenger"] = bool(_m.get("ok"))
            out["messenger_error"] = _m.get("error") or ""
        except Exception as _e100:
            out["messenger"], out["messenger_error"] = False, repr(_e100)[:160]
        if not out["messenger"]:
            print("[z1191z100] 수금 알림 이음 전달 실패:", out["messenger_error"])
    return out


def _ar_alert_workday_z100(d):
    return d.weekday() < 5 and d.isoformat() not in HOLIDAYS_KR


def _ar_alert_seconds_until_next_z100(now_kst=None):
    """다음 평일(공휴일 빼고) 09:00 한국시간까지 남은 초(최소 60초)."""
    now = now_kst if now_kst is not None else _kst_wall_now()
    for _add in range(0, 20):
        slot = (now + timedelta(days=_add)).replace(hour=_AR_ALERT_HOUR_Z100, minute=0, second=0, microsecond=0)
        if slot > now and _ar_alert_workday_z100(slot.date()):
            return max(60.0, (slot - now).total_seconds())
    return 86400.0


def _ar_alert_claim_z100(day_iso):
    """오늘 몫을 잡는다 — 이미 누가 잡았으면 False(일꾼·재기동이 겹쳐도 하루 한 번)."""
    with db_session() as c:
        c.execute("INSERT OR IGNORE INTO app_settings (key, value) VALUES (?, '')", (_AR_ALERT_LAST_Z100,))
        cur = c.execute("UPDATE app_settings SET value=? WHERE key=? AND COALESCE(value,'')<>?",
                        (day_iso, _AR_ALERT_LAST_Z100, day_iso))
        return cur.rowcount == 1


def _ar_alert_release_z100(day_iso):
    """보내다 실패한 날 — 잡아 둔 오늘 몫을 푼다(다시 시도할 수 있게)."""
    try:
        with db_session() as c:
            c.execute("UPDATE app_settings SET value='' WHERE key=? AND value=?", (_AR_ALERT_LAST_Z100, day_iso))
    except Exception as e:
        print(f"[AR-ALERT release ERR] {e}")


def _ar_alert_retry_z100():
    """실패 뒤 다시 한 번(다음 예약은 원래 시계가 따로 잡고 있으므로 여기서는 다시 걸지 않음)."""
    try:
        now = _kst_wall_now()
        if (not _nas_quiet_now(now)) and _ar_alert_due_now_z100(now) and _ar_alert_claim_z100(now.date().isoformat()):
            r = check_receivable_alerts()
            print("[AR-ALERT] 다시 보냄 %s — 받는 사람 %d · 웍스 %d건" % (now.strftime("%m-%d %H:%M"), r["recipients"], r["sent"]))
    except Exception as e:
        print(f"[AR-ALERT retry ERR] {e}")
        _ar_alert_release_z100(_kst_wall_now().date().isoformat())


def _ar_alert_due_now_z100(now_kst=None):
    """지금 보낼 때인가 — 평일 09:00~17:59(재기동으로 9시를 놓쳐도 그날 안에는 한 번)."""
    now = now_kst if now_kst is not None else _kst_wall_now()
    return _ar_alert_workday_z100(now.date()) and _AR_ALERT_HOUR_Z100 <= now.hour < 18


def _ar_alert_tick_z100():
    import threading as _th
    try:
        now = _kst_wall_now()
        if _nas_quiet_now(now):   # 이중 안전 — 09:00 은 월요일 NAS 백업 시간(02:00~07:30) 밖이지만 계산이 어긋나도 안 돈다
            print("[AR-ALERT] 월요일 NAS 백업 시간 — 이번엔 건너뜀")
        elif _ar_alert_due_now_z100(now) and _ar_alert_claim_z100(now.date().isoformat()):
            try:
                r = check_receivable_alerts()
                print("[AR-ALERT] 수금 알림 %s — 받는 사람 %d · 새로 챙길 %d장 · 웍스 %d건 · 이음 %s"
                      % (now.strftime("%m-%d %H:%M"), r["recipients"], r["new"], r["sent"], r["messenger"]))
            except Exception as e:   # z1191z101: 잡아 둔 오늘 몫을 풀고 10분 뒤 다시(18시 전까지)
                print(f"[AR-ALERT send ERR] {e} — 10분 뒤 다시")
                _ar_alert_release_z100(now.date().isoformat())
                retry = _th.Timer(600, _ar_alert_retry_z100)
                retry.daemon = True
                retry.start()
    except Exception as e:
        print(f"[AR-ALERT tick ERR] {e}")
    delay = _ar_alert_seconds_until_next_z100()
    t = _th.Timer(delay, _ar_alert_tick_z100)
    t.daemon = True
    t.start()


def _start_ar_alert_scheduler_z100():
    """startup 1회 — 다음 평일 09:00 예약. 지금이 평일 09~18시이고 오늘 아직 안 보냈으면 2분 뒤 한 번."""
    import threading as _th
    now = _kst_wall_now()
    delay = _ar_alert_seconds_until_next_z100(now)
    try:
        with db_session() as c:
            r = c.execute("SELECT value FROM app_settings WHERE key=?", (_AR_ALERT_LAST_Z100,)).fetchone()
        if (not _nas_quiet_now(now)) and _ar_alert_due_now_z100(now) and (not r or (r[0] or "") != now.date().isoformat()):
            delay = 120.0
    except Exception as e:
        print(f"[AR-ALERT start ERR] {e}")
    _nxt = (now + timedelta(seconds=delay)).strftime("%m-%d %a %H:%M")
    print(f"[AR-ALERT] 수금 알림 시계 시작 — 다음 {_nxt} (한국시간 · 평일 09:00)")
    t = _th.Timer(delay, _ar_alert_tick_z100)
    t.daemon = True
    t.start()


def _ar_alert_view_z100(u):
    """💰 입금 확인 화면 위 「🔔 수금 알림」 줄 — 받는 사람 이름 · 마지막 보낸 날 · 바꿀 수 있는지 · 고를 사람 목록."""
