@app.post("/api/page-tabs/pinned")
async def page_tabs_pinned_set(req: Request):
    u = get_user(req)
    if not u:
        return JSONResponse({"ok": False}, 401)
    try:
        body = await req.json()
    except Exception:
        body = {}
    items = body.get("pinned") if isinstance(body, dict) else None
    out = []
    if isinstance(items, list):
        for it in items[:10]:                      # 고정은 최대 10개
            if not isinstance(it, dict):
                continue
            _u = str(it.get("u") or "")
            _t = str(it.get("t") or "").strip()
            # 내부 경로만: '/' 시작·'//'(스킴 생략 외부주소) 금지·제어문자/괄호 금지·길이 제한
            if not _u.startswith("/") or _u.startswith("//") or len(_u) > 300:
                continue
            if any(ch in _u for ch in ("\n", "\r", "\t", "<", ">", '"')):
                continue
            out.append({"u": _u, "t": _t[:80]})
    import json as _json989
    try:
        _logi.view_prefs_set(u.get("id"), "page_tabs_pinned", _json989.dumps(out, ensure_ascii=False))
    except Exception as e:
        return JSONResponse({"ok": False, "message": str(e)}, 200)
    return JSONResponse({"ok": True, "n": len(out)})


@app.post("/export/item/{iid:int}/customs")
async def export_item_customs_save(req: Request, iid: int):
    """수출 통관 칸만 저장(order_items) — 판매단가/금액/라벨은 절대 건드리지 않음(별도 흐름)."""
    u = _export_guard(req)
    if not u:
        return JSONResponse({"ok": False, "error": "권한 없음"}, 403)
    form = await req.form()
    with db_session() as c:
        oicols = {r[1] for r in c.execute("PRAGMA table_info(order_items)").fetchall()}
        sets, vals = [], []
        # 텍스트형 통관 칸
        for col in ("hs_code", "origin", "box_no", "pallet_size", "description"):
            if col in oicols and form.get(col) is not None:
                sets.append(f"{col}=?")
                vals.append((form.get(col) or "").strip() or None)
        # 숫자형 통관 칸 (미전송=건너뜀 / 빈값=NULL)
        for col in ("duty_rate", "vat_rate", "invoice_unit_price_usd",
                    "invoice_amount_usd", "duty_krw", "duty_usd",
                    "final_amount_usd", "weight_kg"):
            if col not in oicols:
                continue
            raw = form.get(col)
            if raw is None:
                continue
            raw = (raw or "").strip().replace(",", "")
            if raw == "":
                sets.append(f"{col}=?"); vals.append(None)
            else:
                try:
                    sets.append(f"{col}=?"); vals.append(float(raw))
                except ValueError:
                    pass
        if not sets:
            return JSONResponse({"ok": True, "changed": 0})
        if "updated_at" in oicols:
            sets.append("updated_at=datetime('now','localtime')")
        vals.append(iid)
        c.execute(f"UPDATE order_items SET {','.join(sets)} WHERE id=?", vals)
    return JSONResponse({"ok": True, "changed": 1})


# ------------------------------------------------------------
# v5H226z966 (대표 지시): 베트남 HS코드 사전 + 자동 채움 — 과거 인보이스 확정값(베트남 세관 통과 실적) 재사용.
#   3겹: ①사전 일치(CONFIRMED)=자동 채움 ②AI 추정(사전 미등록 신규만·화면에서 노란 표시·사람 검토 후 저장)
#        ③확정될수록 사전 성장. 시드=app/seed/hs_dict_seed.csv(25.11~26.05 최종파일 19개 전수분석 — 741종·충돌 11종=PENDING).
#   ⚠통관은 법적 신고 — PENDING(충돌)·AI 추정은 자동 확정하지 않음(사람 확인).
# ------------------------------------------------------------
def _hs_norm_key(s) -> str:
    """사전 키 = 규격(모델) 정규화: 공백 제거 + 대문자 (시드 생성 스크립트와 동일 규칙)."""
    import re as _re
    return _re.sub(r"\s+", "", str(s or "")).upper()


def _hs_dict_ensure(c):
    """export_hs_dict 테이블 보장 + 비어있으면 번들 시드 CSV 1회 적재. 반환=시드 적재 건수(0=기존재)."""
    c.execute("""CREATE TABLE IF NOT EXISTS export_hs_dict (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        part_key TEXT NOT NULL UNIQUE,
        model TEXT, name_en TEXT, vn_name TEXT,
        hs_code TEXT, origin TEXT, duty TEXT, vat TEXT,
        status TEXT DEFAULT 'CONFIRMED',
        seen_count INTEGER DEFAULT 1,
        first_seen TEXT, last_seen TEXT, source_file TEXT, note TEXT,
        updated_by INTEGER, updated_at TEXT DEFAULT (datetime('now','localtime')))""")
    # v5H226z1044: 검토표 왕복 추적 — '누가(어느 검토표가) 이 값을 확정했나'.
    #   두 담당자(한국·베트남)가 같은 부품을 다르게 적어 왔을 때 충돌을 알아보려면 이 두 칸이 필요하다.
    _hcols = {r[1] for r in c.execute("PRAGMA table_info(export_hs_dict)").fetchall()}
    # z1191p: hist_reg_at = 「지난 수출 등록」이 넣은 줄의 표시(그 뒤 사람이 고치지 않은 줄만 이력에 맞춰 다시 셈)
    for _cn in ("review_file", "review_at", "hist_reg_at"):
        if _cn not in _hcols:
            try:
                c.execute(f"ALTER TABLE export_hs_dict ADD COLUMN {_cn} TEXT")
            except Exception as _e:   # 두 요청이 동시에 넣으면 한쪽은 'duplicate column' — 이미 있으니 됐다
                if "duplicate column" not in str(_e).lower():
                    raise
    if c.execute("SELECT COUNT(*) FROM export_hs_dict").fetchone()[0]:
        return 0
    import csv as _csv
    from pathlib import Path as _P
    p = _P(__file__).parent / "seed" / "hs_dict_seed.csv"   # ⚠app/data는 .gitignore(data/)라 배포 미반영 → app/seed 사용
    if not p.exists():
        return 0
    n, bad = 0, 0
    with open(p, encoding="utf-8-sig", newline="") as f:
        for row in _csv.DictReader(f):
            try:
                c.execute(
                    "INSERT OR IGNORE INTO export_hs_dict"
                    "(part_key,model,name_en,vn_name,hs_code,origin,duty,vat,status,seen_count,first_seen,last_seen,source_file) "
                    "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",
                    ((row.get("part_key") or "").strip(), row.get("model"), row.get("name_en"), row.get("vn_name"),
                     (row.get("hs_code") or "").strip(), row.get("origin"), row.get("duty"), row.get("vat"),
                     (row.get("status") or "CONFIRMED").strip(), int(row.get("seen_count") or 1),
                     row.get("first_seen"), row.get("last_seen"), row.get("source_file")))
                n += 1
            except Exception:
                bad += 1   # 행 단위 결함은 건너뛰되 개수 기록(아래 로그)
    if bad:
        print(f"[hs_dict] 시드 적재: {n}건 성공 · {bad}건 건너뜀(형식 결함)")
    return n


def _hs_items_for_project(c, pid: int) -> list[dict]:
    """프로젝트의 수출 품목(order_items) — 통관 입력 표와 동일 대상. 사전 매칭에 필요한 칸만."""
    oicols = {r[1] for r in c.execute("PRAGMA table_info(order_items)").fetchall()}
    sel = ["oi.id"]
    for cn in ("spec", "unit_label", "maker", "hs_code", "description", "origin", "duty_rate", "vat_rate"):
        if cn in oicols:
            sel.append("oi." + cn)
    rows = c.execute(
        f"SELECT {', '.join(sel)} FROM order_items oi JOIN orders o ON o.id = oi.order_id "
        f"WHERE o.project_id=? ORDER BY oi.id ASC", (pid,)).fetchall()
    return [dict(r) for r in rows]


@app.post("/export/prep/{pid:int}/hs-autofill")
async def export_hs_autofill(req: Request, pid: int):
    """사전(CONFIRMED) 기반 자동 채움 — 빈 칸만(HS·베트남어명·원산지·관세율·VAT). 서버 저장 후 채운 값 반환(화면 즉시 반영).
    PENDING(충돌 확인대기)은 채우지 않고 개수만 보고."""
    u = _export_guard(req)
    if not u:
        return JSONResponse({"ok": False, "error": "권한 없음"}, 403)
    import re as _re
    def _rate_num(x):
        m = _re.search(r"-?\d+(?:\.\d+)?", str(x or ""))
        return float(m.group(0)) if m else None
    filled, already, pend = 0, 0, 0
    misses, applied = [], []
    with db_session() as c:
        _hs_dict_ensure(c)
        dic = {r["part_key"]: dict(r) for r in c.execute(
            "SELECT part_key, vn_name, hs_code, origin, duty, vat, status FROM export_hs_dict")}
        items = _hs_items_for_project(c, pid)
        oicols = {r[1] for r in c.execute("PRAGMA table_info(order_items)").fetchall()}
        for it in items:
            key = _hs_norm_key(it.get("spec")) or _hs_norm_key(it.get("unit_label"))
            hit = dic.get(key)
            if not hit:
                if not str(it.get("hs_code") or "").strip():
                    misses.append(str(it.get("unit_label") or it.get("spec") or ("#%s" % it["id"])))
                continue
            if (hit.get("status") or "") == "PENDING":
                pend += 1
                continue
            sets, vals, out = [], [], {"iid": it["id"]}
            for col, val in (("hs_code", (hit.get("hs_code") or "").strip()),
                             ("description", (hit.get("vn_name") or "").strip()),
                             ("origin", (hit.get("origin") or "").strip())):
                if col in oicols and val and not str(it.get(col) or "").strip():
                    sets.append(f"{col}=?"); vals.append(val); out[col] = val
            for col, src in (("duty_rate", hit.get("duty")), ("vat_rate", hit.get("vat"))):
                rv = _rate_num(src)
                if rv is not None and col in oicols and it.get(col) in (None, ""):
                    sets.append(f"{col}=?"); vals.append(rv); out[col] = rv
            if sets:
                vals.append(it["id"])
                c.execute(f"UPDATE order_items SET {', '.join(sets)} WHERE id=?", vals)
                filled += 1
                applied.append(out)
            else:
                already += 1
    return JSONResponse({"ok": True, "filled": filled, "already": already, "pending": pend,
                         "miss": len(misses), "miss_names": misses[:30], "applied": applied})


# z1191t (대표 2026-10-28 「AI확정은 근거가 없으니깐 삭제하고 AI확정 이부분은 앞으로도 기록하지 말고 보류하자.. 지금은 베트남법인에
#   내용을 전달하면 법인에서 베트남통관 관련 업체에 품목 확인해서 HS코드 안내받아서 입력하는거라 지금은 이 방법으로 확정한것만 사용」):
#   AI 추정 보류 — AI 를 부르지도 사전에 적지도 않는다(07-15 에 적힌 154줄은 같은 날 운영에서 지움).
#   코드는 지우지 않고 꺼 둔다 · 다시 켜는 것은 대표 결정 뒤.
_HS_AI_SUGGEST_ON = False
_HS_AI_HOLD_MSG = ("AI 추정은 보류 중입니다(대표 2026-10-28) — 사전에 없는 품목의 HS 는 "
                   "베트남 법인이 통관 업체에 확인한 값을 받아 입력합니다")


@app.post("/export/prep/{pid:int}/hs-ai-suggest")
async def export_hs_ai_suggest(req: Request, pid: int):
    """사전에 없는 신규 품목만 AI 추정(베트남 AHTN 8자리 + 베트남어 품명) — DB에 쓰지 않고 '제안만' 반환.
    화면이 노란 표시로 채우고 사람이 검토 후 [전체 저장](법적 신고라 자동 확정 금지). 사전에는 status='AI'로 기록(관리 화면서 확정 가능).
    z1191t: 보류 중(_HS_AI_SUGGEST_ON) — AI 부르기·사전 기록 없이 보류 안내만 돌려준다."""
    u = _export_guard(req)
    if not u:
        return JSONResponse({"ok": False, "error": "권한 없음"}, 403)
    if not _HS_AI_SUGGEST_ON:
        return JSONResponse({"ok": False, "hold": True, "error": _HS_AI_HOLD_MSG})
    from . import ai_client as _ai
    if not _ai.ai_available():
        return JSONResponse({"ok": False, "error": "AI 미설정 — 설정에서 AI 키 등록 후 사용할 수 있습니다"})
    with db_session() as c:
        _hs_dict_ensure(c)
        keys = {r["part_key"] for r in c.execute("SELECT part_key FROM export_hs_dict")}
        items = _hs_items_for_project(c, pid)
    targets = []
    for it in items:
        if str(it.get("hs_code") or "").strip():
            continue
        key = _hs_norm_key(it.get("spec")) or _hs_norm_key(it.get("unit_label"))
        if not key or key in keys:
            continue
        targets.append({"iid": it["id"], "key": key,
                        "name": str(it.get("unit_label") or "").strip(),
                        "spec": str(it.get("spec") or "").strip(),
                        "maker": str(it.get("maker") or "").strip(),
                        # v5H226z1046: 통관 입력표에 **사람이 이미 적어 둔 원산지**를 그대로 들고 간다.
                        #   지금까지 이 값을 버려서 AI 행은 원산지가 통째로 비어 있었다(사전 화면의 '공란').
                        #   ⛔AI 에게 원산지를 추정시키지는 않는다 — 원산지는 세관 신고 항목이다(z1041b: 틀린 값보다 빈 값).
                        "origin": str(it.get("origin") or "").strip()})
    if not targets:
        return JSONResponse({"ok": True, "suggestions": [], "message": "AI 추정 대상(사전 미등록·HS 빈 품목)이 없습니다"})
    targets = targets[:200]   # 1회 상한(비용 가드)
    import json as _json
    import re as _re
    _SYS = ("당신은 한국 산업장비 부품의 베트남 수입통관 HS 분류 보조자입니다. "
            "각 부품에 대해 베트남 AHTN 8자리 HS코드와 베트남어 품명을 추정하세요. "
            "베트남어 품명 형식: 'ENGLISH NAME#&Tên tiếng Việt, mã hàng: <규격>, hãng sx: <메이커>. Mới 100%'. "
            "반드시 JSON 배열만 출력: [{\"i\":0,\"hs\":\"84123100\",\"vn\":\"...\"}] "
            "확신이 낮으면 가장 가까운 코드를 쓰고 vn 끝에 ' (확인필요)'를 붙이세요.")
    suggestions = []
    for s in range(0, len(targets), 40):
        chunk = targets[s:s + 40]
        lines = [f"{i} | 품명: {t['name'] or '-'} | 규격: {t['spec'] or '-'} | 메이커: {t['maker'] or '-'}"
                 for i, t in enumerate(chunk)]
        ok, resp = _ai.ai_chat("\n".join(lines), system=_SYS, max_tokens=3000, temperature=0.1)
        if not ok:
            return JSONResponse({"ok": False, "error": f"AI 호출 실패: {resp}", "suggestions": suggestions})
        m = _re.search(r"\[.*\]", resp, _re.S)
        if not m:
            continue
        try:
            arr = _json.loads(m.group(0))
        except Exception:
            continue
        for a in (arr if isinstance(arr, list) else []):
            try:
                t = chunk[int(a.get("i"))]
            except Exception:
                continue
            hs = _re.sub(r"[^\d]", "", str(a.get("hs") or ""))
            if len(hs) != 8:
                continue
            suggestions.append({"iid": t["iid"], "hs_code": hs, "description": str(a.get("vn") or "").strip()})
            t["_hs"] = hs; t["_vn"] = str(a.get("vn") or "").strip()
    # 사전에 AI 추정으로 기록(확정 아님 — 관리 화면에서 검토·확정)
    if suggestions:
        with db_session() as c:
            _hs_dict_ensure(c)
            for t in targets:
                if not t.get("_hs"):
                    continue
                c.execute(
                    # v5H226z1046: origin 칸 추가 — 지금까지 이 INSERT 에 원산지 컬럼 자체가 없어
                    #   AI 행은 통관 입력표에 값이 있어도 **무조건 공란**이었다.
                    "INSERT OR IGNORE INTO export_hs_dict(part_key,model,name_en,vn_name,hs_code,origin,status,seen_count,source_file,note,updated_by) "
                    "VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                    (t["key"], t["spec"] or t["name"], t["name"], t.get("_vn") or "",
                     t["_hs"], t.get("origin") or "", "AI", 0, "AI",
                     "AI 추정 — 검토 필요" + ("" if t.get("origin") else " (원산지 미기재)"),
                     u.get("id")))
    return JSONResponse({"ok": True, "suggestions": suggestions})


# v5H226z967 (대표 지시): HS 사전 관리 화면 + 최종파일(Invoice&PL) 업로드로 사전 성장.
#   업로드 규칙: 신규 규격=CONFIRMED 추가 / 같은 HS 재출현=횟수·최신정보 갱신(AI였으면 CONFIRMED 승격 — 실적 확인)
#   / 다른 HS 재출현=PENDING 전환(충돌 — 사람 확인 전 자동 채움 제외·note에 양쪽 기록).
def _hs_parse_invoice_xlsx(data: bytes, fname: str) -> list[dict]:
    """베트남 최종 인보이스(xlsx)에서 (규격→HS·베트남어명·원산지) 행 추출 — 19개 전수분석과 동일 헤더탐지.
    반환 행: {model,key,hs,vn,name_en,origin}. 인식 실패 시 빈 리스트."""
    import io as _io
    import re as _re
    import openpyxl as _px
    from . import hs_fill as _hf_p
    HEAD_HS = _re.compile(r"HS\s*CODE|HS\s*code|^HS$", _re.I)
    HEAD_VN = _re.compile(r"T[êe]n\s*h[àa]ng", _re.I)
    HEAD_DESC = _re.compile(r"Description", _re.I)
    HEAD_ORIGIN = _re.compile(r"원산지|Origin", _re.I)
    # v5H226z1041 (대표 지시 · 원본 엑셀 전수 대조로 발견): 아래 두 가지를 고쳤다.
    #   ⛔① 시트 하나만 읽던 것 — 파일에 인보이스 시트가 **2개**인 경우가 있다(시트명이 'INVOICE' 가 아니라
    #      관리번호: 251224=002M2509/003M2509 · 260121=001M2509/002M2509). 첫 시트만 읽어 **427행을 통째로 버렸다**
    #      (부품 22종 누락 + 원산지 'MISUMI' 14건 중 11건이 그 시트에 CHINA/KOREA 로 있어 교정될 값이었다).
    #   ⛔② 베트남어 품명 폴백이 'HS 옆칸' 고정이라 그 칸이 **SIZE(치수)** 인 파일에서 치수를 품명으로 읽었다
    #      (260401·260507 — 'Ф7.5 * 29.8' 같은 값이 세관 신고 품명에 들어갔다. 통관은 법적 신고라 치명적).
    _WS_SKIP = _re.compile(r"PACKING|P/L|CONTENT|COVER|양식|SAMPLE", _re.I)
    _SIZE_HEAD = _re.compile(r"^\s*(SIZE|치수|규격\s*\(?\s*mm\s*\)?|DIMENSION)\s*$", _re.I)

    def _scan_sheet(ws):
        """시트 1장 → 행 목록. 헤더를 못 찾으면 빈 리스트(그 시트는 인보이스가 아님)."""
        cols, header_r = {}, None
        for r in range(1, min(ws.max_row, 45) + 1):
            for cc in range(1, min(ws.max_column, 30) + 1):
                v = ws.cell(r, cc).value
                if v is None:
                    continue
                t = str(v).strip()
                if HEAD_HS.search(t) and len(t) < 20:
                    cols.setdefault("hs", cc)
                    header_r = max(header_r or 0, r)
                if HEAD_VN.search(t):
                    cols.setdefault("vn", cc)
                if HEAD_DESC.search(t):
                    cols.setdefault("model", cc)
                if HEAD_ORIGIN.search(t):
                    cols.setdefault("origin", cc)
        if "model" not in cols or "hs" not in cols:
            return []
        if "vn" not in cols:
            # 2604xx 양식: 'Tên hàng' 헤더가 비어 HS 옆칸을 쓴다. ⚠단 그 칸 머리글이 SIZE(치수)면 품명이 아니다
            #   → 잘못된 값을 세관 신고에 넣느니 **비워 둔다**(사람이 채우게).
            _cand = cols["hs"] + 1
            _head = str(ws.cell(header_r or 33, _cand).value or "").strip()
            cols["vn"] = None if _SIZE_HEAD.match(_head) else _cand
        out = []
        for r in range((header_r or 33) + 1, ws.max_row + 1):
            model = str(ws.cell(r, cols["model"]).value or "").strip()
            if not model:
                continue
            hs = _re.sub(r"[^\d]", "", _re.sub(r"\.0$", "", str(ws.cell(r, cols["hs"]).value or "")))
            if len(hs) == 7:
                hs = "0" + hs
            if len(hs) != 8:
                continue
            # z1191v (대표 「0 , #N/A … 함수로 연결되어서 오는건데 잘못 된거야… HS코드 등록에서 모두 삭제해」): 품명 칸의 원래 값으로
            #   함수 값(「0」·숫자 0·#N/A …)인지 본다 — 그런 줄은 junk 표시(사전 성장 `_hs_learn_invoice_rows` 가 건너뛰고 수만 센다)
            _vraw = ws.cell(r, cols["vn"]).value if cols.get("vn") else None
            _junk = _hf_p.formula_junk(_vraw)
            vn = "" if _junk else str(_vraw or "").strip()
            origin = str(ws.cell(r, cols["origin"]).value or "").strip() if "origin" in cols else ""
            out.append({"model": model, "key": _hs_norm_key(model), "hs": hs, "vn": vn, "junk": _junk,
                        "name_en": (vn.split("#&")[0].strip() if "#&" in vn else ""), "origin": origin,
                        "sheet": ws.title})
        return out

    wb = _px.load_workbook(_io.BytesIO(data), data_only=True)
    out = []
    for s in wb.worksheets:
        if s.sheet_state != "visible" or _WS_SKIP.search(s.title or ""):
            continue   # 패킹리스트·표지 등은 인보이스가 아니다
        out.extend(_scan_sheet(s))   # 헤더 없는 시트는 알아서 빈 리스트
    return out


# ------------------------------------------------------------
# v5H226z1044 (대표 지시): HS 사전 '검토표' 왕복 — 내려받기 → 한국(안지연)·베트남 담당자 확정 → 되올리기.
#   대표 결정 4가지:
#     ①현재 값은 잠그고 **[확정] 칸을 따로** 둔다 → 적힌 칸만 반영(안 적은 줄은 손도 안 댐 — 928행 통째 덮어쓰기 사고 방지)
#     ②되받기는 **같은 [파일 올리기] 버튼**이 머리글로 알아서 구분(검토표 vs 인보이스)
#     ③두 담당자가 서로 다르게 적으면 **'확인 대기(충돌)'** — 값은 그대로 두고 보류(몰래 교체 금지)
#     ④전체 한 장 — 검토 필요한 것(충돌·AI)이 맨 위, 줄 색으로 구분
#   ⚠통관은 법적 신고 — 자동 확정하지 않는다.
# ------------------------------------------------------------
# v5H226z1044b (대표 지적 "이 엑셀파일은 베트남 직원도 사용하는거라 한국어·베트남어 둘 다 있어야"):
#   머리글·안내·상태·사유를 전부 2개 국어로. 머리글은 **한국어 줄 + 베트남어 줄**(같은 칸 두 줄).
#   ⚠되받기 판별은 머리글 글자 대조다 — 베트남어를 붙였으므로 파서를 '같음'에서 **'한국어로 시작'** 으로 바꿨다.
#     (한국어 라벨은 그대로 필수 — 아무 표나 통과하지 않는다. 예전에 받아간 한국어 전용 파일도 계속 인식.)
#   (한국어 머리글, 베트남어, 폭, 담당자 입력칸?)
_HS_REVIEW_COLS = [
    ("#", "", 6, False),
    ("규격(모델)", "Quy cách (Model)", 22, False),
    ("영문 품명", "Tên hàng (EN)", 20, False),
    ("상태", "Trạng thái", 18, False),
    ("확인 사유", "Lý do cần kiểm tra", 32, False),
    ("현재 HS코드", "Mã HS hiện tại", 13, False),
    ("확정 HS코드", "Mã HS xác nhận", 14, True),
    ("현재 원산지", "Xuất xứ hiện tại", 13, False),
    ("확정 원산지", "Xuất xứ xác nhận", 14, True),
    ("현재 베트남어 품명", "Tên hàng (VN) hiện tại", 30, False),
    ("확정 베트남어 품명", "Tên hàng (VN) xác nhận", 30, True),
    ("검토 의견", "Ý kiến rà soát", 26, True),
    ("횟수", "Số lần", 7, False),
    ("최근 출현", "Lần gần nhất", 12, False),
]
_HS_REVIEW_HDR_ROW = 4      # 1=제목 2=검토자 3=쓰는 법 4=머리글 5~=데이터
#   상태·사유도 베트남 담당자가 읽어야 한다(무엇을 왜 봐야 하는지가 여기 있다)
_HS_REVIEW_ST = {"CONFIRMED": "✅ 확정 / Đã xác nhận",
                 "PENDING": "⛔ 확인 대기 / Chờ kiểm tra",
                 "AI": "🟡 AI 추정 / AI dự đoán"}
#   사유(note)는 저장된 한국어 문장이다 — 낱말만 베트남어를 덧붙인다(값·숫자는 건드리지 않는다).
#   ⚠순서 중요: '검토 충돌:' 을 '충돌:' 보다 먼저.
_HS_NOTE_BI = [("검토 충돌:", "검토 충돌 / Xung đột rà soát:"),
               ("검토 확정:", "검토 확정 / Đã xác nhận:"),
               # z1047 세관 — ⚠뒤쪽 낱말 규칙에 **다시 걸리지 않는** 문구로 적을 것
               #   (예: 여기 결과에 '세관 ' 이 남으면 아래 '↔ 세관 ' 규칙이 또 바꿔 이중 표기가 된다)
               ("⭐세관 실적 다름:", "⭐세관 실적 다름 / Khác với tờ khai hải quan:"),
               ("⚠세관 기록도 갈림:", "⚠세관 기록도 갈림 / Tờ khai hải quan không thống nhất:"),
               ("세관 실적 반입:", "세관 실적 반입 / Đã nhập khẩu thực tế:"),
               ("충돌:", "충돌 / Xung đột:"),
               ("HS코드", "HS코드(Mã HS)"),
               ("베트남어 품명", "베트남어 품명(Tên hàng VN)"),
               ("원산지", "원산지(Xuất xứ)"),
               ("사전 ", "사전(từ điển) "), ("↔ 세관 ", "↔ 세관(hải quan) "),
               ("최근 ", "최근(gần nhất) "),
               ("기존", "기존(cũ)"), ("신규", "신규(mới)")]


def _hs_note_bi(s: str) -> str:
    """확인 사유를 한국어+베트남어로. 값·숫자·사람 이름은 그대로 둔다."""
    out = str(s or "")
    for ko, bi in _HS_NOTE_BI:
        out = out.replace(ko, bi)
    return out


def _hs_review_xlsx_build(rows: list) -> bytes:
    """HS 사전 → 검토표(.xlsx) 한 장. (openpyxl 미설치 시 ImportError 전파)"""
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side, Protection
    from openpyxl.utils import get_column_letter as _gcl
    from openpyxl.worksheet.datavalidation import DataValidation
    import io as _io
    wb = Workbook()
    ws = wb.active
    ws.title = "HS검토표"
    knk = PatternFill("solid", fgColor="A5282C")        # 잠금 머리글 = KNK 빨강
    blue = PatternFill("solid", fgColor="1D4ED8")       # 입력 머리글 = 파랑("여기 적으세요")
    f_in = PatternFill("solid", fgColor="EFF6FF")       # 입력칸 = 연한 파랑
    f_pend = PatternFill("solid", fgColor="FDECEC")     # 확인 대기(충돌) 줄
    f_ai = PatternFill("solid", fgColor="FEF9C3")       # AI 추정 줄
    white = Font(color="FFFFFF", bold=True, size=10)
    lockfont = Font(color="6B7280", size=10)            # 잠금 값 = 회색(만지지 말라는 신호)
    thin = Side(style="thin", color="DDDDDD")
    border = Border(left=thin, right=thin, top=thin, bottom=thin)
    unlock = Protection(locked=False)
    ncol = len(_HS_REVIEW_COLS)
    last_col = _gcl(ncol)

    ws["A1"] = ("KNK 베트남 HS코드 검토표 — 파란 칸에만 적어 주세요 (회색 칸은 지금 저장된 값 · 잠겨 있습니다)\n"
                "Bảng rà soát mã HS Việt Nam – KNK | Chỉ điền vào ô màu xanh "
                "(ô màu xám là giá trị đang lưu, đã khóa)")
    ws["A1"].font = Font(bold=True, size=12, color="A5282C")
    ws["A1"].alignment = Alignment(vertical="center", wrap_text=True)
    ws.merge_cells(f"A1:{last_col}1")
    ws.row_dimensions[1].height = 32
    ws["A2"] = "검토자\nNgười rà soát"
    ws["A2"].font = white; ws["A2"].fill = knk; ws["A2"].border = border
    ws["A2"].alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
    ws["B2"] = ""
    ws["B2"].fill = f_in; ws["B2"].border = border; ws["B2"].protection = unlock
    ws["C2"] = ("← 이름을 적어 주세요 (예: 안지연 프로 / 베트남 통관담당). 비우면 파일 이름으로 구분합니다.  |  "
                "Vui lòng ghi tên người rà soát. Nếu để trống sẽ phân biệt bằng tên tệp.")
    ws["C2"].font = Font(color="9A8A5A", italic=True, size=9)
    ws["C2"].alignment = Alignment(vertical="center", wrap_text=True)
    ws.merge_cells(f"C2:{last_col}2")
    ws.row_dimensions[2].height = 28
    ws["A3"] = ("① 고칠 것만 파란 칸에 적으세요 — 빈 칸은 손대지 않습니다.  "
                "② 지금 값이 맞으면 '확정' 칸에 같은 값을 그대로 적어 주시면 '확정'으로 바뀝니다.  "
                "③ HS코드는 숫자 8자리.  ④ 다 적었으면 이 파일 그대로 화면의 [파일 올리기]에 올리면 됩니다.\n"
                "① Chỉ điền vào ô màu xanh những mục cần sửa — ô để trống sẽ không bị thay đổi.  "
                "② Nếu giá trị hiện tại đã đúng, hãy điền lại chính giá trị đó vào ô 'xác nhận' "
                "để chuyển sang trạng thái Đã xác nhận.  "
                "③ Mã HS gồm 8 chữ số.  ④ Điền xong, tải chính tệp này lên bằng nút [Tải tệp lên] trên màn hình.")
    ws["A3"].font = Font(color="1D4ED8", size=9.5, bold=True)
    ws["A3"].alignment = Alignment(vertical="center", wrap_text=True)
    ws.merge_cells(f"A3:{last_col}3")
    ws.row_dimensions[3].height = 34

    hr = _HS_REVIEW_HDR_ROW
    for ci, (h, vn, w, is_in) in enumerate(_HS_REVIEW_COLS, 1):
        cel = ws.cell(hr, ci, (h + "\n" + vn) if vn else h)   # 한국어 줄 + 베트남어 줄
        cel.font = white; cel.fill = blue if is_in else knk
        cel.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
        cel.border = border
        ws.column_dimensions[_gcl(ci)].width = w
    ws.row_dimensions[hr].height = 30
    ws.freeze_panes = ws.cell(hr + 1, 3)     # 머리글 + 번호·규격 고정
    _wrap = Alignment(vertical="top", wrap_text=True)
    for ri, r in enumerate(rows, hr + 1):
        vals = [r.get("id"), r.get("model") or r.get("part_key") or "", r.get("name_en") or "",
                _HS_REVIEW_ST.get(r.get("status") or "", r.get("status") or ""),
                _hs_note_bi(r.get("note") or ""),
                r.get("hs_code") or "", "", r.get("origin") or "", "",
                r.get("vn_name") or "", "", "",
                r.get("seen_count") or 0, (r.get("last_seen") or "")[:10]]
        rowfill = f_pend if r.get("status") == "PENDING" else (f_ai if r.get("status") == "AI" else None)
        for ci, v in enumerate(vals, 1):
            _h, _vn, _w, is_in = _HS_REVIEW_COLS[ci - 1]
            cel = ws.cell(ri, ci, v)
            cel.border = border
            cel.alignment = _wrap
            if is_in:
                cel.fill = f_in
                cel.protection = unlock
            else:
                cel.font = Font(bold=True, size=10) if ci == 2 else lockfont
                if rowfill:
                    cel.fill = rowfill
            if "HS코드" in _h:
                cel.number_format = "@"      # ⚠앞자리 0 이 잘리면 안 된다(04059990)
    lastr = hr + len(rows)
    ws.auto_filter.ref = f"A{hr}:{last_col}{max(lastr, hr)}"
    if rows:
        _hs_col = _gcl([h for h, _v, _w, _i in _HS_REVIEW_COLS].index("확정 HS코드") + 1)
        dv = DataValidation(type="textLength", operator="equal", formula1="8",
                            allow_blank=True, errorStyle="warning",
                            error="HS코드는 숫자 8자리입니다. / Mã HS gồm 8 chữ số.",
                            errorTitle="HS코드 확인 / Kiểm tra mã HS")
        ws.add_data_validation(dv)
        dv.add(f"{_hs_col}{hr + 1}:{_hs_col}{lastr}")
    # 현재 값 칸 잠금(실수로 덮어쓰는 사고 방지). 비밀번호 없음 — 필터·정렬·열너비는 그대로 쓸 수 있게 열어 둔다.
    ws.protection.sheet = True
    for _allow in ("autoFilter", "sort", "formatColumns", "formatRows",
                   "selectLockedCells", "selectUnlockedCells"):
        setattr(ws.protection, _allow, False)
    buf = _io.BytesIO()
    wb.save(buf)
    return buf.getvalue()


def _hs_parse_review_xlsx(data: bytes, fname: str):
    """올린 파일이 '검토표'인지 판별 → (행목록, 검토자). 검토표가 아니면 None(→인보이스 파서로 넘어간다).
    ⚠머리글 엄격 대조 — 위치 폴백 없음(z978 규정). 판별 키 = '규격(모델)' + '확정 HS코드' 두 머리글.
    ⚠z1044b: 머리글이 '한국어 줄 + 베트남어 줄' 두 줄이 되었으므로 **'한국어 라벨로 시작하는가'** 로 찾는다
      (한국어 라벨 자체는 여전히 필수 — 아무 표나 통과하지 않는다. 한국어 전용 구파일도 그대로 인식)."""
    import io as _io
    import re as _re
    import openpyxl as _px

    def _n(v):
        return _re.sub(r"\s+", "", str(v if v is not None else ""))

    def _find(cols: dict, label: str):
        lab = _n(label)
        for t, cc in cols.items():           # 열 순서대로(파이썬 dict는 넣은 순서 유지)
            if t.startswith(lab):
                return cc
        return None

    wb = _px.load_workbook(_io.BytesIO(data), data_only=True)
    for ws in wb.worksheets:
        if ws.sheet_state != "visible":
            continue
        hdr_r, cols = None, {}
        for r in range(1, min(ws.max_row, 12) + 1):
            found = {}
            for cc in range(1, min(ws.max_column, 40) + 1):
                t = _n(ws.cell(r, cc).value)
                if t:
                    found.setdefault(t, cc)
            if _find(found, "규격(모델)") and _find(found, "확정 HS코드"):
                hdr_r, cols = r, found
                break
        if not hdr_r:
            continue          # 이 시트는 검토표가 아니다
        def _col(label):
            return _find(cols, label)
        c_id, c_key = _col("#"), _col("규격(모델)")
        c_hs, c_or = _col("확정 HS코드"), _col("확정 원산지")
        c_vn, c_memo = _col("확정 베트남어 품명"), _col("검토 의견")
        reviewer = ""
        for r in range(1, hdr_r):     # 머리글 위쪽에서 '검토자' 라벨 오른쪽 칸(라벨도 2개 국어라 startswith)
            for cc in range(1, min(ws.max_column, 10) + 1):
                if _n(ws.cell(r, cc).value).startswith("검토자"):
                    reviewer = str(ws.cell(r, cc + 1).value or "").strip()
                    break
            if reviewer:
                break
        out = []
        for r in range(hdr_r + 1, ws.max_row + 1):
            key_raw = str(ws.cell(r, c_key).value or "").strip()
            hs_raw = ws.cell(r, c_hs).value if c_hs else None
            org = str(ws.cell(r, c_or).value or "").strip() if c_or else ""
            vn = str(ws.cell(r, c_vn).value or "").strip() if c_vn else ""
            memo = str(ws.cell(r, c_memo).value or "").strip() if c_memo else ""
            hs_txt = "" if hs_raw is None else _re.sub(r"\.0$", "", str(hs_raw)).strip()
            if not (hs_txt or org or vn or memo):
                continue      # 안 적은 줄 = 건드리지 않는다
            if not key_raw:
                continue
            hs = _re.sub(r"[^\d]", "", hs_txt)
            if len(hs) == 7:
                hs = "0" + hs          # 엑셀이 앞자리 0 을 먹은 경우
            bad = bool(hs_txt) and len(hs) != 8
            rid = None
            if c_id:
                try:
                    rid = int(float(str(ws.cell(r, c_id).value or "").strip() or 0)) or None
                except Exception:
                    rid = None
            out.append({"row": r, "id": rid, "key": _hs_norm_key(key_raw), "model": key_raw,
                        "hs": "" if bad else hs, "origin": org, "vn": vn, "memo": memo, "bad": bad})
        return out, reviewer
    return None


def _hs_apply_review(c, rows: list, who: str, fname: str, today: str, u) -> dict:
    """검토표 반영 — **적힌 칸만**. 다른 검토자가 이미 채워 둔 값과 다르면 값은 그대로 두고 '확인 대기(충돌)'.
    ⚠통관은 법적 신고 — 충돌한 줄은 아무 것도 바꾸지 않는다(사람이 화면에서 최종 선택)."""
    applied = conflict = skipped = bad = 0
    for row in rows:
        if row["bad"]:
            bad += 1
            continue
        ex = None
        if row["id"]:
            ex = c.execute("SELECT * FROM export_hs_dict WHERE id=?", (row["id"],)).fetchone()
            if ex and _hs_norm_key(ex["part_key"]) != row["key"]:
                ex = None       # 번호와 규격이 어긋나면 번호를 믿지 않는다(줄 밀림 사고 방지)
        if ex is None:
            ex = c.execute("SELECT * FROM export_hs_dict WHERE part_key=?", (row["key"],)).fetchone()
        if ex is None:
            skipped += 1        # 사전에 없는 규격 — 검토표로는 새로 만들지 않는다(사전 성장은 인보이스로)
            continue
        wrote = bool(row["hs"] or row["origin"] or row["vn"])
        if not wrote and not row["memo"]:
            skipped += 1
            continue
        diffs = []
        for fld, lab, newv in (("hs_code", "HS코드", row["hs"]),
                               ("origin", "원산지", row["origin"]),
                               ("vn_name", "베트남어 품명", row["vn"])):
            cur = (ex[fld] or "").strip()
            if newv and newv != cur:
                diffs.append((fld, lab, cur, newv))
        prev = ((ex["review_file"] or "").strip() if "review_file" in ex.keys() else "")
        # 충돌 = 다른 검토자가 **이미 채워 놓은 값**을 이번 검토자가 다르게 적은 것.
        #   빈 칸을 채운 것은 충돌이 아니다(서로 나눠 적은 것). 인보이스에서 온 값도 검토자가 고치는 게 맞다.
        clash = [d for d in diffs if d[2]] if (prev and prev != who) else []
        if clash:
            txt = " · ".join(f"{lab} {cur} ↔ {new}" for _f, lab, cur, new in clash)
            c.execute("UPDATE export_hs_dict SET status='PENDING', note=?, review_file=?, review_at=?, "
                      "updated_by=?, updated_at=datetime('now','localtime') WHERE id=?",
                      (f"검토 충돌: {txt} ({prev} ↔ {who})", who, today, u.get("id"), ex["id"]))
            conflict += 1
            continue
        sets, vals = [], []
        for fld, _lab, _cur, newv in diffs:
            sets.append(f"{fld}=?")
            vals.append(newv)
        note = f"검토 확정: {who} ({today})" + (f" — {row['memo'][:200]}" if row["memo"] else "")
        if wrote:
            sets.append("status='CONFIRMED'")   # 값을 적었으면 확정. 의견만 적었으면 상태는 그대로.
        sets += ["note=?", "review_file=?", "review_at=?", "updated_by=?",
                 "updated_at=datetime('now','localtime')"]
        vals += [note, who, today, u.get("id"), ex["id"]]
        c.execute(f"UPDATE export_hs_dict SET {','.join(sets)} WHERE id=?", vals)
        applied += 1
    return {"file": fname, "mode": "review", "reviewer": who, "rows": len(rows),
            "applied": applied, "conflict": conflict, "skipped": skipped, "bad": bad}


# ------------------------------------------------------------
# v5H226z1047 (대표 지시): 베트남 세관 신고 상세 보고서(BÁO CÁO CHI TIẾT HÀNG HÓA) 반영.
#   ⭐**인보이스보다 강한 근거** — 인보이스는 우리가 적어 보낸 것이고, 이건 **세관이 실제로 통과시킨 기록**이다.
#   대표 결정: ①사전에 있는 규격의 HS 가 다르면 → **'확인 대기'로 세우고 세관 실적을 사유에** (값은 안 바꾼다)
#              ②사전에 없는 규격 추가는 **별도 선택**(기본 꺼짐 — 1,167종이 한꺼번에 들어오면 확인이 불가능)
#   ⛔원산지는 이번 판에서 건드리지 않는다 — 세관은 `R.KOREA`, 우리는 `KOREA` 라 **표기 차이가 실제 이견처럼**
#      보인다(cf z1046 SWISS↔SWITZERLAND). 표기 표준화를 정하기 전엔 손대지 않는 것이 안전하다.
#   ⛔세율(관세·부가세)은 저장하지 않는다 — 실측 결과 **같은 HS+원산지인데도 관세율이 26% 쌍에서 갈린다**
#      (0% = 한-베 FTA 특혜세율 = C/O 서류 제출 여부로 갈림). 부가세도 2024년부터 0%/8%/10% 혼재(시점 의존).
#      '물건'이 아니라 '서류·시점'이 정하는 값이라 사전에 박으면 틀린 값을 보여준다.
# ------------------------------------------------------------
def _hs_parse_customs_xls(data: bytes, fname: str):
    """세관 신고 상세 보고서(.xls/.xlsx)인지 판별 → 규격별 집계 또는 None(아니면 다른 파서로).
    반환: {규격키: {hs, hs_all, n, last_date, vn, org, model}}
    ⚠머리글 엄격 대조(z978) — 위치 폴백 없음. 판별 키 = 'Mã HS' + 'Tên hàng' 두 머리글."""
    import io as _io
    import re as _re

    def _grid_xlrd():
        import xlrd
        bk = xlrd.open_workbook(file_contents=data)
        sh = bk.sheet_by_index(0)
        return [[sh.cell_value(r, cc) for cc in range(sh.ncols)] for r in range(sh.nrows)]

    def _grid_openpyxl():
        from openpyxl import load_workbook
        wb = load_workbook(_io.BytesIO(data), data_only=True, read_only=True)
        ws = wb.active
        g = [[c.value for c in row] for row in ws.iter_rows()]
        wb.close()
        return g

    ext = (fname or "").lower().rsplit(".", 1)[-1]
    order = (_grid_xlrd, _grid_openpyxl) if ext == "xls" else (_grid_openpyxl, _grid_xlrd)
    grid = None
    for fn in order:                      # 은행 대사(z929)와 같은 방식 — 확장자가 틀려도 반대쪽으로 한 번 더
        try:
            grid = fn()
            if grid:
                break
        except Exception:
            grid = None
    if not grid:
        return None

    def _n(v):
        return _re.sub(r"\s+", "", str(v if v is not None else ""))

    hdr_r, cols = None, {}
    for r in range(min(len(grid), 30)):
        found = {}
        for cc, v in enumerate(grid[r]):
            t = _n(v)
            if t:
                found.setdefault(t, cc)
        if _n("Mã HS") in found and _n("Tên hàng") in found:
            hdr_r, cols = r, found
            break
    if hdr_r is None:
        return None                        # 세관 보고서가 아니다
    c_hs, c_vn = cols[_n("Mã HS")], cols[_n("Tên hàng")]
    c_org, c_dt = cols.get(_n("Xuất xứ")), cols.get(_n("Ngày ĐK"))
    c_mat = cols.get(_n("Mã NPL/SP"))
    # 세관 품명은 우리 인보이스와 같은 형식: 'ENGLISH#&Tên tiếng Việt, mã hàng: <규격>, hsx: ...'
    MH = _re.compile(r"m[ãa]\s*h[àa]ng\s*[:：]\s*([^,;]+)", _re.I)
    DT = _re.compile(r"^\s*(\d{2})/(\d{2})/(\d{4})")
    out = {}
    for r in range(hdr_r + 1, len(grid)):
        row = grid[r]
        hs = _re.sub(r"[^\d]", "", _re.sub(r"\.0$", "", str(row[c_hs] if c_hs < len(row) else "")))
        if len(hs) == 7:
            hs = "0" + hs
        if len(hs) != 8:
            continue
        vn = str(row[c_vn] if c_vn < len(row) else "").strip()
        m = MH.search(vn)
        if not m:
            continue                       # 규격(mã hàng)이 없으면 우리 사전 키를 만들 수 없다
        key = _hs_norm_key(m.group(1))
        if not key or len(key) < 3:
            continue                       # 너무 짧은 키는 오매칭 위험(실측 'P15' 류)
        d = out.setdefault(key, {"hs": {}, "n": 0, "last": "", "vn": vn, "org": "",
                                 "model": m.group(1).strip()})
        d["n"] += 1
        d["hs"][hs] = d["hs"].get(hs, 0) + 1
        if c_org is not None and c_org < len(row) and not d["org"]:
            d["org"] = str(row[c_org]).strip()
        if c_dt is not None and c_dt < len(row):
            g = DT.match(str(row[c_dt]).strip())
            if g:
                iso = f"{g.group(3)}-{g.group(2)}-{g.group(1)}"
                if iso > d["last"]:
                    d["last"] = iso
                    d["vn"] = vn           # 품명은 가장 최근 신고분을 대표로
        if c_mat is not None and c_mat < len(row):
            d.setdefault("mat", str(row[c_mat]).strip())
    for k, d in out.items():
        d["hs_top"] = max(d["hs"].items(), key=lambda x: (x[1], x[0]))[0]
        d["hs_split"] = len(d["hs"]) > 1   # 세관 자체가 갈리는 건 = 사람이 봐야 한다
    return out


def _hs_apply_customs(c, agg: dict, fname: str, today: str, u, add_new: bool) -> dict:
    """세관 기록 반영 — ①있는 규격의 HS 가 다르면 '확인 대기'+실적 기록 ②없는 규격은 add_new 일 때만 추가.
    ⛔값은 덮지 않는다(z1046 규칙) · ⛔원산지·세율은 손대지 않는다(위 주석 근거)."""
    flagged = matched = added = skipped = split = filled = 0
    for key, d in agg.items():
        ex = c.execute("SELECT id, hs_code, status, origin FROM export_hs_dict WHERE part_key=?",
                       (key,)).fetchone()
        hs_c = d["hs_top"]
        _when = f"{d['n']}회" + (f" · 최근 {d['last']}" if d["last"] else "")
        if d["hs_split"] and (ex is not None or add_new):
            split += 1     # 세관 자체가 한 규격을 두 코드로 신고한 것 — 신규·기존 가리지 않고 센다
        if ex is None:
            if not add_new:
                skipped += 1
                continue
            _note = f"세관 실적 반입: {_when} ({fname})"
            if d["hs_split"]:
                _note = ("⚠세관 기록도 갈림: " + " / ".join(f"{h} {n}회" for h, n in
                                                        sorted(d["hs"].items(), key=lambda x: -x[1]))
                         + f" ({fname})")
            # v5H226z1047b: ⚠origin 칸을 빠뜨려 **새 행 1,167종의 원산지가 전부 공란**이었다
            #   (z1046 에서 AI 저장문에 고친 것과 **같은 실수**를 반복했다 — 파서가 읽어 둔 값을 안 썼다).
            #   ⛔'원산지 안 건드림' 은 **남의 값을 덮지 않는다**는 뜻이지, 빈 칸을 비워 두라는 뜻이 아니다.
            c.execute(
                "INSERT INTO export_hs_dict(part_key,model,name_en,vn_name,hs_code,origin,status,seen_count,"
                "first_seen,last_seen,source_file,note,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (key, d.get("model") or key,
                 (d["vn"].split("#&")[0].strip() if "#&" in d["vn"] else ""), d["vn"], hs_c,
                 d.get("org") or "",
                 # 세관 자체가 갈리면 자동 채움에 쓰면 안 된다 → 확인 대기
                 "PENDING" if d["hs_split"] else "CONFIRMED",
                 d["n"], d["last"] or today, d["last"] or today, fname, _note, u.get("id")))
            added += 1
            continue
        if (ex["hs_code"] or "").strip() == hs_c:
            matched += 1                   # 세관이 우리 값을 확인해 줌 — 바꿀 것이 없다(기존 사유도 보존)
            # ⭐빈 원산지만 채운다(z1046 규칙: 채움은 안전 · 다른 값 덮기는 금지).
            #   이미 올린 공란 행을 **다시 올리면 고쳐지는** 경로이기도 하다.
            if not (ex["origin"] or "").strip() and (d.get("org") or "").strip():
                c.execute("UPDATE export_hs_dict SET origin=?, updated_by=?, "
                          "updated_at=datetime('now','localtime') WHERE id=?",
                          (d["org"].strip(), u.get("id"), ex["id"]))
                filled += 1
            continue
        # 다름 → 값은 그대로 두고 '확인 대기' + 세관 실적을 사유에. 통관은 법적 신고 = 사람이 고른다.
        #   세관 자체가 갈리면(한 규격을 두 코드로 신고) 그 내역을 그대로 보여 준다 — 사람이 판단할 근거다.
        _detail = (" / ".join(f"{h} {n}회" for h, n in sorted(d["hs"].items(), key=lambda x: -x[1]))
                   if d["hs_split"] else _when)
        c.execute(
            "UPDATE export_hs_dict SET status='PENDING', note=?, last_seen=?, "
            "updated_by=?, updated_at=datetime('now','localtime') WHERE id=?",
            (f"⭐세관 실적 다름: 사전 {(ex['hs_code'] or '').strip() or '(공란)'} ↔ 세관 {hs_c} "
             f"({_detail}" + (f" · 최근 {d['last']}" if d["hs_split"] and d["last"] else "") + ")",
             d["last"] or today, u.get("id"), ex["id"]))
        flagged += 1
    return {"file": fname, "mode": "customs", "rows": len(agg), "flagged": flagged,
            "matched": matched, "added": added, "skipped": skipped, "split": split,
            "filled": filled}


@app.get("/export/hs-dict/review.xlsx")
async def export_hs_dict_review_xlsx(req: Request):
    """HS 사전 전체 → 검토표(.xlsx) 내려받기. 한국·베트남 담당자에게 보내 확정칸만 적어 되받는 왕복 양식."""
    u = _export_guard(req)
    if not u:
        return RedirectResponse("/home", 303)
    with db_session() as c:
        _hs_dict_ensure(c)
        rows = [dict(r) for r in c.execute(
            "SELECT * FROM export_hs_dict ORDER BY "
            "CASE status WHEN 'PENDING' THEN 0 WHEN 'AI' THEN 1 ELSE 2 END, "
            "seen_count DESC, part_key")]
        today = c.execute("SELECT strftime('%Y%m%d','now','localtime')").fetchone()[0]
    try:
        buf = _hs_review_xlsx_build(rows)
    except ImportError:
        return JSONResponse({"error": "openpyxl 미설치"}, 500)
    from urllib.parse import quote as _q
    return Response(
        content=buf,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": (
            f'attachment; filename="KNK_HS_review_{today}.xlsx"; '
            f"filename*=UTF-8''{_q(f'KNK_HS검토표_{today}.xlsx')}")},
    )


@app.get("/export/hs-dict", response_class=HTMLResponse)
async def export_hs_dict_page(req: Request):
    """HS 사전 관리 — 검색·상태 필터·인라인 수정(HS·베트남어명·상태)·최종파일 업로드."""
    u = _export_guard(req)
    if not u:
        return RedirectResponse("/home", 303)
    q = (req.query_params.get("q") or "").strip()
    st = (req.query_params.get("status") or "").strip().upper()
    with db_session() as c:
        _hs_dict_ensure(c)
        stats = {r["status"]: r["n"] for r in c.execute(
            "SELECT status, COUNT(*) n FROM export_hs_dict GROUP BY status")}
        sql = "SELECT * FROM export_hs_dict WHERE 1=1"
        vals = []
        if st in ("CONFIRMED", "PENDING", "AI"):
            sql += " AND status=?"; vals.append(st)
        if q:
            sql += " AND (part_key LIKE ? OR model LIKE ? OR name_en LIKE ? OR hs_code LIKE ? OR vn_name LIKE ?)"
            kk = f"%{q}%"
            vals += [f"%{_hs_norm_key(q)}%", kk, kk, kk, kk]
        sql += " ORDER BY CASE status WHEN 'PENDING' THEN 0 WHEN 'AI' THEN 1 ELSE 2 END, seen_count DESC, part_key LIMIT 400"
        rows = [dict(r) for r in c.execute(sql, vals)]
    # v5H226z1045 (표준 반영·가이드 §23 '데이터 입력표=엑셀식 격자·열 폭 조절'):
    #   칸 너비를 계정별로 기억한다. 통관 입력표(z951)와 같은 범용 view_prefs 재사용.
    try:
        col_prefs = _logi.view_prefs_get(u.get("id"), "export_hs_dict_cols") or "{}"
    except Exception:
        col_prefs = "{}"
    return ctx(req, "export_hs_dict.html", user=u, active="export",
               rows=rows, stats=stats, q=q, st=st, col_prefs=col_prefs,
               total=sum(stats.values()))


@app.post("/export/hs-dict/cols")
async def export_hs_dict_cols_save(req: Request):
    """v5H226z1045 (대표 지시·표준 반영): HS 사전 표 칸 너비 계정별 저장.
    통관 입력표(z951 `/export/prep/cols`)와 같은 범용 view_prefs 재사용(key='export_hs_dict_cols').
    ⚠컬럼 키·폭은 화이트리스트만 저장(JSON 을 화면 <script> 로 되돌려 주므로 주입 차단)."""
    u = _export_guard(req)
    if not u:
        return JSONResponse({"ok": False}, 401)
    try:
        body = await req.json()
    except Exception:
        body = {}
    if not isinstance(body, dict):
        body = {}
    import re as _re1045

    def _okk(s):
        return isinstance(s, str) and bool(_re1045.match(r"^[a-z_]{1,24}$", s))

    _w = body.get("w") if isinstance(body.get("w"), dict) else {}
    cfg = {"w": {k: int(v) for k, v in _w.items()
                 if _okk(k) and isinstance(v, (int, float)) and 30 <= v <= 900}}
    try:
        import json as _json1045
        _logi.view_prefs_set(u.get("id"), "export_hs_dict_cols", _json1045.dumps(cfg))
    except Exception as e:
        return JSONResponse({"ok": False, "message": str(e)}, 200)
    return JSONResponse({"ok": True})


@app.post("/export/hs-dict/{did:int}/save")
async def export_hs_dict_save(req: Request, did: int):
    """사전 1건 인라인 수정 — HS·베트남어명·원산지·상태. PENDING/AI를 사람이 확정(CONFIRMED)하는 입구."""
    u = _export_guard(req)
    if not u:
        return JSONResponse({"ok": False, "error": "권한 없음"}, 403)
    form = await req.form()
    import re as _re
    hs = _re.sub(r"[^\d]", "", str(form.get("hs_code") or ""))
    if hs and len(hs) != 8:
        return JSONResponse({"ok": False, "error": "HS코드는 8자리 숫자입니다"}, 400)
    st = (form.get("status") or "").strip().upper()
    if st == "AI":          # z1191t: AI 추정 보류 — 사람이 'AI 추정'으로 적지 않는다(옛 화면에서 와도 확인 대기로)
        st = "PENDING"
    if st not in ("CONFIRMED", "PENDING"):
        st = "CONFIRMED"
    with db_session() as c:
        _hs_dict_ensure(c)
        c.execute(
            "UPDATE export_hs_dict SET hs_code=?, vn_name=?, origin=?, status=?, "
            "updated_by=?, updated_at=datetime('now','localtime') WHERE id=?",
            (hs, (form.get("vn_name") or "").strip(), (form.get("origin") or "").strip(),
             st, u.get("id"), did))
    return JSONResponse({"ok": True})


def _hs_learn_invoice_rows(c, rows: list, fname: str, today: str, u) -> dict:
    """최종 인보이스(법인 회신) 줄 → 사전 성장 — z967 규칙 그대로(새 규격 추가 · 같은 HS 재출현 갱신 ·
    다른 HS 는 '확인 대기') · z1046 원산지 원칙 그대로(다르면 덮지 않고 사유).
    z1191l: `/export/hs-dict/upload` 안에 있던 코드를 함수로 뺐다(회신 반영 단추 `/export/hs-fill/reply` 도 같은 규칙) +
      한 가지 더 — 새 규격이 사전의 **같은 모델**(확정)과 HS 가 다르면 '확인 대기'로 넣는다(아래 주석)."""
    from . import hs_fill as _hf_learn
    _idx_learn = _hf_learn.build_index([dict(r) for r in c.execute(
        "SELECT part_key, model, hs_code, vn_name, status, seen_count FROM export_hs_dict")])
    added = updated = conflict = or_clash = junk = 0
    for row in rows:
        if row.get("junk"):
            # z1191v: 품명이 엑셀 함수 값(「0」·#N/A …)인 줄 = 함수로 끌어온 데이터라 HS 도 믿지 않는다 → 사전에 넣지 않는다
            #   (대표 10-28 「이렇게 나오는 부분들은 HS코드 등록에서 모두 삭제해」 · 수만 세어 결과에 보인다)
            junk += 1
            continue
        ex = c.execute("SELECT id, hs_code, status, origin FROM export_hs_dict WHERE part_key=?",
                       (row["key"],)).fetchone()
        if not ex:
            # z1191l: 규격 전체는 처음이지만 **같은 모델**이 사전에 확정돼 있고 HS 가 다르면 → 확정이 아니라 '확인 대기'로 넣는다.
            #   (소모품 최종 양식은 규격 앞에 분류 글이 붙어 'PARTS OF CONNECTORS SP100F…' 처럼 새 규격이 된다 →
            #    그대로 확정으로 넣으면 같은 모델이 사전에서 서로 다른 HS 로 **말없이 갈라진다** — 10-26 실측 1·2호기 HS 불일치와 같은 모양)
            _way, _e, _memo = _hf_learn.lookup(_idx_learn, row["model"])
            if _way == "token" and _hf_learn.digits(_e.get("hs_code")) != row["hs"]:
                c.execute(
                    "INSERT INTO export_hs_dict(part_key,model,name_en,vn_name,hs_code,origin,status,seen_count,first_seen,last_seen,source_file,note,updated_by) "
                    "VALUES(?,?,?,?,?,?, 'PENDING',1,?,?,?,?,?)",
                    (row["key"], row["model"], row["name_en"], row["vn"], row["hs"],
                     row["origin"], today, today, fname,
                     "충돌: 같은 모델 사전 %s = %s ↔ 신규 %s (%s)" % (_e.get("model") or _e.get("part_key"),
                                                             _hf_learn.digits(_e.get("hs_code")), row["hs"], fname),
                     u.get("id")))
                conflict += 1
                continue
            c.execute(
                "INSERT INTO export_hs_dict(part_key,model,name_en,vn_name,hs_code,origin,status,seen_count,first_seen,last_seen,source_file,updated_by) "
                "VALUES(?,?,?,?,?,?, 'CONFIRMED',1,?,?,?,?)",
                (row["key"], row["model"], row["name_en"], row["vn"], row["hs"],
                 row["origin"], today, today, fname, u.get("id")))
            added += 1
        elif (ex["hs_code"] or "") == row["hs"]:
            # 같은 HS 재출현 — 실적 확인: AI 추정이었다면 CONFIRMED 승격
            # v5H226z1046 (대표 지시): ⛔**원산지를 말없이 덮지 않는다**.
            #   HS 는 다르면 '확인 대기'로 세우면서 원산지만 조용히 마지막 파일 값으로 바꾸고 있었다
            #   (실측 103종). 원산지도 세관 신고 항목이라 같은 원칙이 맞다 —
            #   빈 칸이면 채우고, 같으면 그대로, **다르면 덮지 않고 사유로 알린다**.
            #   ⚠상태는 건드리지 않는다(HS 는 맞으므로 자동 채움은 계속 쓸 수 있어야 한다).
            #   cf [[feedback_data_connectivity]] 자동연결=명확한 단일후보만
            _cur_or = (ex["origin"] or "").strip()
            _new_or = (row["origin"] or "").strip()
            _clash = bool(_cur_or and _new_or and _cur_or != _new_or)
            _sets = ["seen_count=seen_count+1", "last_seen=?", "source_file=?",
                     "vn_name=CASE WHEN ?<>'' THEN ? ELSE vn_name END",
                     "status=CASE WHEN status='AI' THEN 'CONFIRMED' ELSE status END"]
            _vals = [today, fname, row["vn"], row["vn"]]
            if _clash:
                _sets.append("note=?")
                _vals.append(f"⚠원산지 이견: 기존 {_cur_or} ↔ 신규 {_new_or} ({fname})")
                or_clash += 1
            elif _new_or:
                _sets.append("origin=?")      # 비었으면 채우고, 같으면 그대로(무해)
                _vals.append(_new_or)
            _sets += ["updated_by=?", "updated_at=datetime('now','localtime')"]
            _vals += [u.get("id"), ex["id"]]
            c.execute(f"UPDATE export_hs_dict SET {','.join(_sets)} WHERE id=?", _vals)
            updated += 1
        else:
            # 다른 HS 재출현 = 충돌 → PENDING(자동 채움 제외) + note 기록. 몰래 교체 금지(사람 확인).
            c.execute(
                "UPDATE export_hs_dict SET status='PENDING', "
                "note=('충돌: 기존 ' || COALESCE(hs_code,'') || ' ↔ 신규 ' || ? || ' (' || ? || ')'), "
                "last_seen=?, updated_by=?, updated_at=datetime('now','localtime') WHERE id=?",
                (row["hs"], fname, today, u.get("id"), ex["id"]))
            conflict += 1
    return {"file": fname, "rows": len(rows), "added": added,
            "updated": updated, "conflict": conflict, "or_clash": or_clash, "junk": junk}


@app.post("/export/hs-dict/upload")
async def export_hs_dict_upload(req: Request):
    """파일 올리기(여러 개) → 사전 성장. **세 가지**를 머리글로 구분해 받는다:
    ①검토표(내려받은 양식·z1044) = 담당자가 적은 확정칸만 반영
    ②세관 신고 상세 보고서(z1047·.xls 가능) = 실제 통관 실적으로 대조 → 다르면 '확인 대기'
    ③최종 인보이스(z967) = 기존 사전 성장.
    파일별 결과 반환(모드마다 세는 것이 다르다)."""
    u = _export_guard(req)
    if not u:
        return JSONResponse({"ok": False, "error": "권한 없음"}, 403)
    form = await req.form()
    files = form.getlist("files")
    if not files:
        return JSONResponse({"ok": False, "error": "파일이 없습니다"}, 400)
    # z1047: 세관 자료의 '사전에 없는 규격'까지 새로 넣을지 — 기본 꺼짐(대표 지시: 확인 후 따로).
    add_new = str(form.get("customs_add_new") or "").strip().lower() in ("1", "true", "on", "y")
    results = []
    with db_session() as c:
        _hs_dict_ensure(c)
        today = c.execute("SELECT date('now','localtime')").fetchone()[0]
        for f in files[:30]:
            fname = getattr(f, "filename", "") or "upload.xlsx"
            if not fname.lower().endswith((".xlsx", ".xlsm", ".xls")):
                results.append({"file": fname, "error": "엑셀(.xlsx·.xls)만 가능"})
                continue
            try:
                raw = await f.read()
            except Exception as e:
                results.append({"file": fname, "error": f"읽기 실패: {str(e)[:100]}"})
                continue
            # v5H226z1044: ①검토표(내보낸 양식)인가? — 머리글 엄격 대조. 아니면 ②기존 인보이스 파서.
            #   대표 결정: 버튼은 하나 · 화면이 알아서 구분(둘 다 아니면 아래에서 오류로 알림).
            try:
                _rv = _hs_parse_review_xlsx(raw, fname)
            except Exception:
                _rv = None
            if _rv is not None:
                results.append(_hs_apply_review(c, _rv[0], (_rv[1] or fname), fname, today, u))
                continue
            # z1047: ②세관 신고 상세 보고서인가? (.xls 구형식 포함)
            try:
                _cs = _hs_parse_customs_xls(raw, fname)
            except Exception as e:
                log.warning("hs customs parse fail %s: %s", fname, e)
                _cs = None
            if _cs:
                results.append(_hs_apply_customs(c, _cs, fname, today, u, add_new))
                continue
            try:
                rows = _hs_parse_invoice_xlsx(raw, fname)
            except Exception as e:
                results.append({"file": fname, "error": f"파싱 실패: {str(e)[:100]}"})
                continue
            if not rows:
                results.append({"file": fname,
                                "error": "인보이스(HS CODE 헤더)·검토표·세관 보고서(Mã HS) 어느 것도 아닙니다"})
                continue
            if _hs_fill_is_own_output(c, raw):
                # z1191l: ① 자동 채움 파일 그대로면 거절 — 주황(모델만 일치) 값이 법인 확인 없이 확정되지 않게
                results.append({"file": fname, "error": "① 자동 채움에서 받은 파일 그대로입니다 — 법인이 채워 보낸 회신 파일을 올려 주세요"})
                continue
            _res = _hs_learn_invoice_rows(c, rows, fname, today, u)
            # z1191l: 자동 채움으로 보낸 인보이스의 회신이면 '회신 대기'를 푼다(같은 인보이스 번호 · 없으면 파일 이름)
            _res["log"] = _hs_fill_log_mark_reply(c, raw, fname, _res, u)
            # z1191p: 최종 인보이스는 지난 수출 이력에도(같은 번호면 바꿔 넣음 · 사전은 위 z967 규칙 그대로)
            _res["hist"] = _hs_hist_from_raw(c, raw, fname, "dict", u)
            results.append(_res)
    return JSONResponse({"ok": True, "results": results})


# ------------------------------------------------------------
# z1191l (대표 지시 2026-10-26): 베트남 인보이스 HS 자동 채움 — 엑셀 왕복
#   「엑셀 양식은 지금 올려준 양식으로 최종 적용해 … 직원들이 가장 편하고 실수없이 빠르게 할수있는 방법으로」
#   ① 본사가 인보이스(최종 양식: 수책·소모품)를 올린다 → 사전 **확정** 값으로 HS CODE·Tên hàng 칸만 채운 같은 파일
#      (법인이 채울 칸 노랑 · 확인할 칸 주황 — 두 칸 모두 인쇄 영역 A~I 밖이라 세관용 출력에 안 찍힌다)
#   ② 법인은 노란 칸만 채워 이음 방으로 회신 ③ 본사가 회신을 올린다 → 사전 성장(z967 규칙 그대로) + '회신 대기' 풀림
#   ⚠파일은 칸만 바꾼다(사진·병합·수식·인쇄 영역은 바이트 그대로) — app/hs_fill.py
#   ⚠통관은 법적 신고 — 확정 값만 자동. 확인 대기·AI 추정·후보가 갈리는 것은 채우지 않는다.
# ------------------------------------------------------------
_HS_FILL_DIR = os.path.join(BASE, "data", "hs_fill")
_HS_FILL_KEEP_DAYS = 30          # 채운 파일 보관 — 지나면 「다시 받기」만 사라진다(기록은 남음)
_HS_FILL_MAX_MB = 60


def _hs_fill_log_ensure(c):
    """자동 채움 기록 — 어느 인보이스를 언제 채워 보냈고, 법인 회신이 사전에 반영됐는지('회신 대기' 해제)."""
    c.execute("""CREATE TABLE IF NOT EXISTS export_hs_fill_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        invoice_no TEXT, file_name TEXT, form TEXT, stored TEXT, out_sha TEXT,
        n_total INTEGER, n_auto INTEGER, n_check INTEGER, n_need INTEGER, n_keep INTEGER,
        filled_by INTEGER, filled_at TEXT DEFAULT (datetime('now','localtime')),
        reply_file TEXT, reply_by INTEGER, reply_at TEXT,
        reply_added INTEGER, reply_updated INTEGER, reply_conflict INTEGER, reply_empty INTEGER)""")
    # z1191n: 올린 원본(본사 확정 뒤 원본에서 다시 만든다) · 본사가 고른 값({규격 키: HS}) · 예전 채운 파일 지문들(③ 거절용)
    # z1191u: 옛 양식 → 최종 양식 바꿈 요약(JSON · 바꾼 양식 · 원본대로 둔 머리 · 뺀 값 · 못 바꾼 까닭)
    have = {r[1] for r in c.execute("PRAGMA table_info(export_hs_fill_log)")}
    for col in ("orig_stored", "overrides", "out_sha_hist", "conv_note"):
        if col not in have:
            try:
                c.execute("ALTER TABLE export_hs_fill_log ADD COLUMN %s TEXT" % col)
            except Exception as e:      # 두 요청이 동시에 넣으면 한쪽은 'duplicate column' — 이미 있으니 됐다
                if "duplicate column" not in str(e).lower():
                    raise


def _hs_fill_cleanup():
    """보관 기한이 지난 채운 파일을 지운다(기록 줄은 그대로 · 「다시 받기」만 사라짐)."""
    import time as _t
    try:
        lim = _t.time() - _HS_FILL_KEEP_DAYS * 86400
        for fn in os.listdir(_HS_FILL_DIR):
            p = os.path.join(_HS_FILL_DIR, fn)
            if fn.endswith(".xlsx") and os.path.getmtime(p) < lim:
                os.remove(p)
    except FileNotFoundError:
        pass


def _hs_fill_is_own_output(c, raw: bytes) -> bool:
    """올린 파일이 ① 자동 채움이 만든 파일 **그대로**인가(지문 sha256 대조).
    ⚠그대로 회신으로 받으면 주황(모델만 일치) 값이 법인 확인 없이 사전에 확정된다 → 회신 반영·사전 업로드에서 거절."""
    import hashlib as _hl
    _hs_fill_log_ensure(c)
    h = _hl.sha256(raw).hexdigest()
    # z1191n: 본사 확정으로 파일을 다시 만든 뒤에도, 먼저 받아 간 판(예전 지문)까지 거절한다
    return c.execute("SELECT 1 FROM export_hs_fill_log WHERE out_sha=? OR instr(COALESCE(out_sha_hist,''), ?)>0 LIMIT 1",
                     (h, h)).fetchone() is not None


def _hs_fill_log_mark_reply(c, raw: bytes, fname: str, res: dict, u):
    """회신 파일 → 자동 채움 기록 중 같은 인보이스 번호(없으면 파일 이름 앞부분)의 '회신 대기'를 '반영'으로.
    반환 {"id","invoice_no","n"} · 못 찾으면 None(사전 반영은 그대로 됐다) · 기록 실패면 {"error"}(사전 반영은 막지 않는다).
    z1191n: · 번호로 찾으면 그 번호의 '회신 대기'를 모두 반영(같은 인보이스를 ①에 두 번 올린 경우 옛 줄이 영영 대기로 남지 않게)
            · 이름으로 찾을 때는 **후보가 하나일 때만** — 표준 양식을 이름 그대로 쓰면 인보이스마다 이름이 같아
              엉뚱한 기록이 '반영'이 되고 진짜 기록은 '회신 대기'로 남는다 → 여럿이면 {"ambiguous": n}(데이터 연결 = 명확한 단일 후보만)
            · 이미 반영된 기록의 회신을 다시 올리면 {"again": id} — 사전 반영은 그대로 되고 기록은 안 바꾼다."""
    from . import hs_fill as _hf
    try:
        _hs_fill_log_ensure(c)
        ino = _hf.invoice_no_quick(raw)
        ids = []
        if ino:
            ids = [r["id"] for r in c.execute("SELECT id FROM export_hs_fill_log WHERE invoice_no=? AND reply_at IS NULL "
                                              "ORDER BY id DESC", (ino,)).fetchall()]
            if not ids:
                done = c.execute("SELECT id FROM export_hs_fill_log WHERE invoice_no=? AND reply_at IS NOT NULL "
                                 "ORDER BY id DESC LIMIT 1", (ino,)).fetchone()
                if done:
                    return {"again": done["id"], "invoice_no": ino}
        if not ids:
            stem = _hf.file_stem(fname)
            open_c, done_c = [], []
            for r in c.execute("SELECT id, invoice_no, file_name, reply_at FROM export_hs_fill_log "
                               "ORDER BY id DESC LIMIT 200").fetchall():
                if ino and r["invoice_no"] and r["invoice_no"] != ino:
                    continue        # 번호가 다른 인보이스는 이름이 비슷해도 다른 것
                s2 = _hf.file_stem(r["file_name"])
                if stem and s2 and (stem.startswith(s2) or s2.startswith(stem)):
                    (done_c if r["reply_at"] else open_c).append(r)
            if len(open_c) > 1:
                return {"ambiguous": len(open_c)}
            if open_c:
                ids = [open_c[0]["id"]]
            elif len(done_c) == 1:
                return {"again": done_c[0]["id"], "invoice_no": done_c[0]["invoice_no"] or ""}
        if not ids:
            return None
        for i in ids:
            c.execute("UPDATE export_hs_fill_log SET reply_file=?, reply_by=?, reply_at=datetime('now','localtime'), "
                      "reply_added=?, reply_updated=?, reply_conflict=?, reply_empty=? WHERE id=?",
                      (fname, u.get("id"), res.get("added", 0), res.get("updated", 0), res.get("conflict", 0),
                       res.get("empty"), i))
        top = c.execute("SELECT invoice_no FROM export_hs_fill_log WHERE id=?", (ids[0],)).fetchone()
        return {"id": ids[0], "invoice_no": (top["invoice_no"] if top else "") or "", "n": len(ids)}
    except Exception as e:
        log.warning("hs fill log mark fail %s: %s", fname, e)
        return {"error": str(e)[:120]}


def _hs_fill_entries(c) -> list:
    """자동 채움 색인용 사전 줄 — z1191n: 근거 보이기(몇 번 나왔고 마지막이 언제인지)에 seen_count·last_seen."""
    return [dict(r) for r in c.execute(
        "SELECT part_key, model, hs_code, vn_name, status, seen_count, last_seen FROM export_hs_dict")]


def _hs_conv_note(conv: dict):
    """z1191u: hs_form_convert.convert 결과 → 기록·화면용 요약. 이미 최종 양식이면 None.
    ok=True: 바꾼 양식 · 자동 근거 · 늘린 줄 · 사진 · 원본대로 둔 머리 묶음 · 최종 양식 것으로 바꾼 묶음 · 뺀 값(이름 · 수 · 까닭 · 예)
    ok=False: 못 바꾼 까닭(부르는 쪽은 올린 모양 그대로 채웠다)"""
    from . import hs_fill as _hf
    if not conv or conv.get("final"):
        return None
    if conv.get("converted") and conv.get("ok"):
        rp = conv.get("report") or {}
        moved = []
        for m in rp.get("header_moved") or []:
            b = m["block"][3:] if m["block"].startswith("패킹 ") else m["block"]
            if b not in moved:
                moved.append(b)
        return {"ok": True, "kind": _hf.form_name(conv.get("kind")), "auto": bool(conv.get("auto")), "why": conv.get("why") or "",
                "items": rp.get("items", 0), "expanded": rp.get("expanded", 0), "photos": rp.get("photos", 0),
                "photos_dropped": rp.get("photos_dropped", 0), "header_moved": moved, "keep": _HS_FILL_KEEP_DAYS,
                # z1191y: 수량 단위는 올린 파일 그대로(줄마다) · 원본 패킹이 비어 인보이스 품목으로 채운 줄 수
                "units": rp.get("units") or {}, "pl_from_inv": rp.get("pl_from_inv", 0),
                # z1191z: 틀의 남는 빈 품목 칸 줄을 지운 수(인보이스 · 패킹) · 원본 끝 빈 품목 줄(번호만)을 뺀 수
                "rows_cut": rp.get("rows_cut", 0), "pl_rows_cut": rp.get("pl_rows_cut", 0), "tail_cut": rp.get("items_tail_cut", 0),
                "header_final": [d["block"] for d in conv.get("header_diffs") or []],
                "dropped": [{"label": k, "n": v["n"], "why": v["why"], "ex": [str(x)[:40] for x in v["ex"]][:3]}
                            for k, v in (rp.get("dropped") or {}).items()]}
    why = conv.get("error") or ("; ".join((conv.get("bad") or [])[:2]) or "바꾼 파일을 다시 읽어 보니 원본과 달랐습니다")
    return {"ok": False, "why": str(why)[:300], "multi": bool(conv.get("multi"))}


def _hs_fill_payload(lid: int, fname: str, res: dict, extra=None) -> dict:
    """① 결과(그리고 본사 확정 뒤 다시 만든 결과) → 화면이 그리는 JSON.
    z1191n: 셈은 칸 색으로(hs_fill.counts) — 품명만 노란 줄도 '법인 입력' · 노랑·주황이 하나도 없으면 no_reply(받은 파일이 최종).
    z1191p: hist = 지난 수출 이력과 비교(단가 ±20% 넘게 다른 줄 · HS 다른 줄 · 노랑·주황 줄 근거) — 화면에만(이음 글·파일에는 안 넣음)."""
    from . import hs_fill as _hf
    cn = res["counts"]
    forms = sorted({s["form"] for s in res["scan"]["sheets"]})
    # z1191z86 (대표 11-20 「조건을 사용자가 넣을수있게」 · 「허용을 할 건지 말 건지를 선택을 받고 다음을 진행」):
    #   단가 기준 = 사용자가 정한 조건(app/export_price.py · 선적 건 서류 점검과 같은 조건) · 범위 밖 줄은 허용/고치기를 골라야 받기가 열린다
    from . import export_price as _xp
    _ino = res["scan"]["invoice_no"] or ""
    _pkind = _xp.kind_of([_hf.form_name(f) for f in forms])
    with db_session() as c:
        past = _hs_hist_past(c, {a["key"] for a in res["acts"]})
        n_hist = c.execute("SELECT COUNT(*) FROM export_hist_inv").fetchone()[0]
        _rng = _xp.tol(_xp.rules(c), _pkind)
        _skip, _ak = _xp.fixed(c), _xp.acks(c, _ino)
    prices = {(s["title"], it["row"]): it.get("price") for s in res["scan"]["sheets"] for it in s["items"]}
    cmp = _hf.compare(res["acts"], prices, past, _ino, rng=_rng, skip=_skip)
    _pn = _xp.overlay(cmp["price"], _ak)
    with db_session() as c:
        _xp.save_need(c, lid, _ino, cmp["price"])
    attention = []
    for a in res["acts"]:
        cat = _hf.category(a)
        if cat not in (_hf.NEED, _hf.CHECK):
            continue
        attention.append({"sheet": a["sheet"], "row": a["row"], "desc": a["desc"], "st": cat, "status": a["status"],
                          "why": a["why"], "dict_hs": a["dict_hs"], "dict_seen": a["dict_seen"], "dict_last": a["dict_last"],
                          "dict_model": a["dict_model"], "dict_status": a["dict_status"],
                          "hs_written": a["hs_written"], "choices": a["choices"],
                          # z1191n: 고를 때 품명도 근거 — 적힌 품명과 사전 품명이 다르면 화면이 함께 보여 준다
                          "vn_written": (a.get("vn_written") or "")[:160], "dict_vn": (a.get("dict_vn") or "")[:160],
                          # z1191p: 지난 수출 근거(같은 규격이 몇 번 · 어떤 HS · 마지막 인보이스) · z1191r: 그 규격의 마지막 사진
                          "hist_ev": cmp["ev"].get((a["sheet"], a["row"]), ""),
                          "hist_img": cmp["img"].get((a["sheet"], a["row"]), "")})
    hint = ""
    if cn["total"] and cn["keep"] >= cn["total"] * 0.8:
        hint = ("이미 HS 가 거의 다 채워진 파일입니다 — 법인 회신 파일이면 아래 ③ [회신 반영]에 올려 주세요"
                "(여기 ①은 사전에 반영하지 않습니다)")
    cv = (extra or {}).get("conv")
    if "예전 양식" in forms or (cv and not cv.get("ok")):
        h2 = "예전 양식입니다 — "
        if cv and not cv.get("ok"):
            # z1191u: 옛 양식인데 최종 양식으로 못 바꿈(인보이스 여러 장 · 칸 모양이 다름 · 다시 읽어 대조가 다름 …) — 올린 모양 그대로 채웠다
            h2 += "최종 양식으로 바꾸지 못해 올린 모양 그대로 채웠습니다(%s) · " % cv.get("why", "")
        hint = (hint + " · " if hint else "") + h2 + "칸은 머리글로 찾았습니다. 앞으로는 최종 양식(수책통관·일반통관)으로 만들어 주세요"
    ino = res["scan"]["invoice_no"] or fname
    if cn["no_reply"]:
        msg = "[인보이스 전달] %s — HS CODE·Tên hàng 을 사전 확정 값으로 모두 채웠습니다. 회신은 필요 없습니다." % ino
    else:
        msg = "[HS 기재 요청] %s — " % ino
        if cn["auto"]:
            msg += "사전에 있는 품목 %d줄은 HS CODE·Tên hàng 을 미리 채웠습니다. " % cn["auto"]
        if cn["need"]:
            msg += "노란 칸 %d줄만 채워서 회신 부탁드립니다." % cn["need"]
        else:
            msg += "새로 채울 칸은 없습니다. 확인 후 회신 부탁드립니다."
        if cn["check"]:
            msg += " 주황 칸 %d줄은 채운 값이 맞는지 확인해 주세요." % cn["check"]
    out = {"ok": True, "log_id": lid, "file_name": fname, "invoice_no": res["scan"]["invoice_no"],
           "forms": [_hf.form_name(f) for f in forms],   # z1191o: 화면 이름(수책통관·일반통관)
           "sheets": [{"title": s["title"], "items": len(s["items"])} for s in res["scan"]["sheets"]],
           "summary": {k: cn[k] for k in ("total", "auto", "check", "need", "keep")}, "no_reply": cn["no_reply"],
           "attention": attention[:400], "hint": hint, "message": msg,
           "download_url": "/export/hs-fill/%d/download" % lid,
           "hist": {"n_inv": n_hist, "matched": cmp["matched"], "checked": cmp["checked"],
                    "tol": _rng[0] if _rng[0] == _rng[1] else None, "up": _rng[0], "down": _rng[1], "rule": _xp.rule_text(*_rng),
                    "kind": _pkind, "reasons": list(_xp.REASONS), "n_open": _pn["open"], "n_allow": _pn["allow"], "n_fix": _pn["fix"],
                    "price": cmp["price"][:300], "hs": cmp["hs"][:300]}}
    out.update(extra or {})
    return out


@app.get("/export/hs-fill", response_class=HTMLResponse)
async def export_hs_fill_page(req: Request):
    """인보이스 HS 자동 채움 — ① 보내기 전 채우기 · ③ 법인 회신 반영 · 최근 기록(회신 대기)."""
    u = _export_guard(req)
    if not u:
        return RedirectResponse("/home", 303)
    from . import hs_fill as _hf
    with db_session() as c:
        _hs_dict_ensure(c)
        _hs_fill_log_ensure(c)
        stats = {r["status"]: r["n"] for r in c.execute(
            "SELECT status, COUNT(*) n FROM export_hs_dict GROUP BY status")}
        logs = [dict(r) for r in c.execute(
            "SELECT * FROM export_hs_fill_log ORDER BY id DESC LIMIT 30")]
        for lg in logs:
            lg["form_name"] = _hf.form_name(lg.get("form"))   # z1191o: 저장된 「수책」·「소모품」 → 수책통관·일반통관
            lg["filled_name"] = user_disp_by_id(c, lg.get("filled_by"))
            lg["reply_name"] = user_disp_by_id(c, lg.get("reply_by")) if lg.get("reply_by") else ""
            st = lg.get("stored") or ""
            lg["has_file"] = bool(st) and os.path.exists(os.path.join(_HS_FILL_DIR, st))
            # z1191n (대표 「전부 자동이면 법인 회신이 필요없는 사항인데」): 노랑·주황이 하나도 없던(또는 본사가 다 확정한)
            #   인보이스는 회신을 기다리지 않는다 — 받은 파일이 최종 파일
            lg["no_reply"] = (not lg.get("reply_at")) and not (lg.get("n_need") or 0) and not (lg.get("n_check") or 0)
            try:
                lg["conv"] = _json.loads(lg.get("conv_note") or "null")   # z1191u: 옛 양식 → 최종 양식 바꿈 요약
            except ValueError:
                lg["conv"] = None
        hist = _hs_hist_summary(c)
    waiting = sum(1 for lg in logs if not lg.get("reply_at") and not lg.get("no_reply"))
    return ctx(req, "export_hs_fill.html", user=u, active="export", logs=logs, waiting=waiting,
               confirmed=stats.get("CONFIRMED", 0), total=sum(stats.values()), hist=hist)


@app.post("/export/hs-fill")
async def export_hs_fill_run(req: Request):
    """① 인보이스 1개 → 사전 확정 값으로 HS·Tên hàng 칸을 채운 같은 파일(보관) + 결과 요약."""
    u = _export_guard(req)
    if not u:
        return JSONResponse({"ok": False, "error": "권한 없음"}, 403)
    form = await req.form()
    f = form.get("file")
    fname = os.path.basename(getattr(f, "filename", "") or "") if f is not None else ""
    if not fname:
        return JSONResponse({"ok": False, "error": "인보이스 파일을 골라 주세요"}, 400)
    if not fname.lower().endswith(".xlsx"):
        return JSONResponse({"ok": False, "error": "엑셀(.xlsx) 파일만 됩니다 — 예전 형식(.xls)이면 .xlsx 로 저장해서 올려 주세요"}, 400)
    raw = await f.read()
    if len(raw) > _HS_FILL_MAX_MB * 1024 * 1024:
        return JSONResponse({"ok": False, "error": "파일이 너무 큽니다(%dMB 넘음)" % _HS_FILL_MAX_MB}, 400)
    # z1191u: 옛 양식이면 바꿀 최종 양식 — 화면에서 고름(자동 = 칸 모양으로 가름 · 수책통관 · 일반통관)
    want = {"suchaek": "수책", "somo": "소모품"}.get(str(form.get("form_kind") or ""), "auto")
    with db_session() as c:
        _hs_dict_ensure(c)
        entries = _hs_fill_entries(c)
    from . import hs_fill as _hf
    from . import hs_form_convert as _hfc
    from starlette.concurrency import run_in_threadpool
    # z1191u (대표 2026-10-28 「…확인해서 작성한 내용들이 포함된 문서는 항상 최종 양식으로 변경되어 작성이 되도록 적용해줘」):
    #   옛 양식은 최종 양식으로 바꿔서 채운다 — 바꾼 파일을 다시 읽어 칸마다 대조(hs_form_convert.verify) ·
    #   못 바꾸거나(인보이스 여러 장 …) 대조가 다르거나 ① 이 읽은 품목 수가 다르면 올린 모양 그대로 채운다(전과 같음)
    try:
        conv = await run_in_threadpool(_hfc.convert, raw, want)
    except Exception as e:
        log.warning("hs form convert fail %s: %s", fname, e)
        conv = {"converted": False, "ok": False, "error": "최종 양식으로 바꾸다 멈췄습니다 — %s" % str(e)[:150]}
    data, res = raw, None
    if conv.get("converted") and conv.get("ok"):
        try:
            res = await run_in_threadpool(_hf.fill, conv["out"], entries)
            n_fill = sum(len(s["items"]) for s in res["scan"]["sheets"]) if res.get("ok") else -1
            n_src = (conv.get("report") or {}).get("named")
            if not res.get("ok") or n_fill != n_src:
                conv = dict(conv, ok=False, error=(res.get("error") or "바꾼 파일을 채우지 못했습니다") if not res.get("ok")
                            else "바꾼 파일의 품목 수가 원본과 달랐습니다(원본 %s · 바꾼 파일 %d)" % (n_src, n_fill))
                res = None
            else:
                data = conv["out"]
        except Exception as e:
            log.warning("hs fill converted fail %s: %s", fname, e)
            conv = dict(conv, ok=False, error="바꾼 파일을 채우지 못했습니다 — %s" % str(e)[:150])
            res = None
    if res is None:
        try:
            res = await run_in_threadpool(_hf.fill, raw, entries)
        except Exception as e:
            log.warning("hs fill fail %s: %s", fname, e)
            return JSONResponse({"ok": False, "error": "파일을 읽지 못했습니다 — %s" % str(e)[:150]})
    if not res.get("ok"):
        return JSONResponse({"ok": False, "error": res.get("error") or "처리하지 못했습니다"})
    note = _hs_conv_note(conv)
    cn = res["counts"]
    forms = sorted({s["form"] for s in res["scan"]["sheets"]})
    import secrets as _sec
    os.makedirs(_HS_FILL_DIR, exist_ok=True)
    _hs_fill_cleanup()
    tok = _sec.token_hex(16)
    stored, orig = tok + ".xlsx", tok + "_in.xlsx"
    with open(os.path.join(_HS_FILL_DIR, stored), "wb") as fo:
        fo.write(res["out"])
    # z1191n: 올린 원본도 둔다 — 본사가 ① 결과에서 HS 를 고르면 원본에서 다시 만든다(색이 깨끗하게 · 30일 뒤 함께 지움)
    # z1191u: 최종 양식으로 바꿨으면 바꾼 파일을 그 자리에(다시 만들어도 최종 양식) · 올린 파일은 _src 로 따로 둔다(30일 뒤 함께 지움)
    with open(os.path.join(_HS_FILL_DIR, orig), "wb") as fo:
        fo.write(data)
    if data is not raw:
        with open(os.path.join(_HS_FILL_DIR, tok + "_src.xlsx"), "wb") as fo:
            fo.write(raw)
    import hashlib as _hl
    # 지문은 실제로 바뀐 파일만 남긴다 — 바꿀 것이 없어 원본을 그대로 돌려준 경우(법인 회신을 ①에 잘못 올린 때)
    #   그 회신을 ③에 다시 올려도 '자동 채움 파일 그대로'로 오인해 막지 않게.
    out_sha = _hl.sha256(res["out"]).hexdigest() if res["out"] != raw else None
    with db_session() as c:
        _hs_fill_log_ensure(c)
        cur = c.execute(
            "INSERT INTO export_hs_fill_log(invoice_no,file_name,form,stored,orig_stored,out_sha,n_total,n_auto,n_check,n_need,n_keep,filled_by,conv_note) "
            "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",
            (res["scan"]["invoice_no"], fname, "·".join(forms), stored, orig, out_sha, cn["total"], cn["auto"], cn["check"],
             cn["need"], cn["keep"], u.get("id"), _json.dumps(note, ensure_ascii=False) if note else None))
        lid = cur.lastrowid
    extra = {"conv": note} if note else {}
    # z1191p: 노랑·주황이 없으면 받은 파일이 최종 — 지난 수출 이력에도 넣는다(같은 번호면 바꿔 넣음 · 번호 없으면 안 넣음)
    if cn["no_reply"]:
        extra["hist_saved"] = await run_in_threadpool(_hs_hist_record_out, res["out"], fname, u)
    return JSONResponse(_hs_fill_payload(lid, fname, res, extra or None))


# z1191n (대표 2026-10-27 「사전 확정을 하고 싶을때 어떻게해??」 → 「진행해」): ① 결과에서 본사가 그 줄의 HS 를 고른다.
#   고를 수 있는 값 = hs_fill.plan 의 choices(적힌 값 ↔ 사전 값 · 모델만 일치한 값 · 사전에 확인 대기로 있는 값)만.
#   z1191z: + 사전에 없는 KNK-○ 규격이면 같은 묶음(KNK-P …)의 확정 HS — 고르면 품명은 묶음 품명에서 번호만 바꿔 넣는다.
#   z1191z2: + 품명 낱말 예측 HS(kind='predict') — 고르면 품명은 같은 HS 의 가장 비슷한 사전 품명(mã hàng 만 새 규격).
#   → 사전 확정(누가·언제·전 값을 note 에) + 이 인보이스 파일을 **올린 원본에서** 다시 만든다(적힌 값과 다르면 그 칸도).
#   노랑·주황이 다 풀리면 '회신 필요 없음'. ⚠쓰기 잠금을 쥔 채 파일을 다시 만들지 않는다(큰 파일은 1~2초).
import threading as _hsf_thr
_HS_FILL_REGEN_LOCK = _hsf_thr.Lock()   # 같은 기록을 두 사람이 눌러도 늦게 끝난 옛 판이 새 판을 덮지 않게 — 다시 만들기는 한 번에 하나


class _HsFillStop(Exception):
    def __init__(self, msg, code=400):
        super().__init__(msg)
        self.code = code


def _hs_fill_confirm_work(lid: int, sheet: str, row: int, hs: str, u) -> tuple:
    """(응답 코드, JSON) — 막힘(_HsFillStop)은 일꾼 스레드 안에서 받아 값으로 돌려준다.
    ⚠예외를 스레드 밖(비동기 처리기)으로 던지면 예외↔프레임 고리가 요청 처리 틀(압축 처리기 포함)을 붙잡아
      GC 가 늦게 치우며 'Exception ignored in: <gzip …>' 잡음을 남겼다(로컬 starlette 0.38 실측 · 10-27)."""
    try:
        return 200, _hs_fill_confirm_do(lid, sheet, row, hs, u)
    except _HsFillStop as e:
        return e.code, {"ok": False, "error": str(e)}


def _hs_fill_confirm_do(lid: int, sheet: str, row: int, hs: str, u) -> dict:
    """① 검사(쓰기 없음) ② 사전·고른 값 기록(짧게) ③ 원본에서 다시 만들기(DB 밖) ④ 기록 숫자·지문."""
    from . import hs_fill as _hf
    import json as _js
    import hashlib as _hl
    with _HS_FILL_REGEN_LOCK:
        with db_session() as c:
            _hs_dict_ensure(c)
            _hs_fill_log_ensure(c)
            r0 = c.execute("SELECT * FROM export_hs_fill_log WHERE id=?", (lid,)).fetchone()
            lg = dict(r0) if r0 else None
            entries = _hs_fill_entries(c) if lg else []
            today = c.execute("SELECT date('now','localtime')").fetchone()[0]
        if not lg:
            raise _HsFillStop("없는 기록입니다 — 화면을 새로 열어 주세요", 404)
        op = os.path.join(_HS_FILL_DIR, lg.get("orig_stored") or "")
        if not lg.get("orig_stored") or not os.path.exists(op):
            raise _HsFillStop("이 기록은 올린 원본이 없어(보관 %d일이 지났거나 예전 기록) 여기서 확정할 수 없습니다 — "
                              "①에 다시 올리거나 HS 사전 화면에서 고쳐 주세요" % _HS_FILL_KEEP_DAYS, 409)
        with open(op, "rb") as fi:
            raw = fi.read()
        try:
            ov = _js.loads(lg.get("overrides") or "{}")
        except ValueError:
            ov = {}
        if not isinstance(ov, dict):
            ov = {}
        res = _hf.fill(raw, entries, ov)
        if not res.get("ok"):
            raise _HsFillStop(res.get("error") or "원본을 다시 읽지 못했습니다", 409)
        a = next((x for x in res["acts"] if x["sheet"] == sheet and x["row"] == row), None)
        if a is None:
            raise _HsFillStop("그 줄을 찾지 못했습니다 — 화면을 새로 열어 주세요", 404)
        if hs not in [ch.get("hs") for ch in (a.get("choices") or [])]:
            raise _HsFillStop("그 줄에서 고를 수 있는 값이 아닙니다(이미 확정됐을 수 있음) — 화면을 새로 열어 주세요", 409)
        key = a["key"]
        who = (u.get("name") or "") if isinstance(u, dict) else ""
        ino = lg.get("invoice_no") or lg.get("file_name") or ""
        written = _hf.digits(a.get("hs_written"))
        with db_session() as c:
            ex = c.execute("SELECT id, hs_code, status FROM export_hs_dict WHERE part_key=?", (key,)).fetchone()
            prev = (ex["hs_code"] or "") if ex else ""
            prev_lbl = "사전에 없음" if not ex else ((prev or "HS 없음") + (
                "" if ex["status"] == "CONFIRMED" else "(%s)" % {"PENDING": "확인 대기", "AI": "AI 추정"}.get(ex["status"], ex["status"])))
            note = "본사 확정 %s %s: %s → %s (%s %d줄)" % (today, who, prev_lbl, hs, ino, row)
            dict_changed = True
            if ex:
                if (ex["hs_code"] or "") != hs or ex["status"] != "CONFIRMED":
                    c.execute("UPDATE export_hs_dict SET hs_code=?, status='CONFIRMED', note=?, updated_by=?, "
                              "updated_at=datetime('now','localtime') WHERE id=?", (hs, note, u.get("id"), ex["id"]))
                else:
                    dict_changed = False      # 사전은 이미 그 값(확정) — 파일 칸만 그 값으로
            else:
                # 모델만 일치한 후보를 확정 → 이 규격을 새로 넣는다(후보의 베트남어 품명 — 파일에도 그 품명이 주황으로 들어가 있었다)
                _idx = _hf.build_index(entries)
                _way, e, _memo = _hf.lookup(_idx, a["desc"])
                vn = (e.get("vn_name") or "").strip() if (e and _hf.digits(e.get("hs_code")) == hs) else ""
                # z1191z: 같은 묶음(KNK-P …)에서 고른 HS — 품명은 같은 묶음 · 같은 HS 사전 품명에서 번호만 새 규격으로(대표 11-02 「3. 추천」)
                # z1191z2: 예측 HS(kind='predict')를 고르면 품명은 같은 HS 의 가장 비슷한 사전 품명(mã hàng 만 새 규격)
                pick = next((ch for ch in (a.get("choices") or []) if ch.get("kind") in ("family", "predict") and ch.get("hs") == hs), None)
                if not vn and pick:
                    vn = _hf.suggest_vn(_idx, a["desc"], hs)
                    if pick.get("kind") == "family":
                        note += " · 같은 묶음 %s 값(예 %s)" % (pick.get("fam") or "", pick.get("ex") or "")
                    else:
                        note += " · 예측 값(확신 %s · 비슷한 %s)" % (pick.get("conf"), (pick.get("ex") or "")[:40])
                c.execute(
                    "INSERT INTO export_hs_dict(part_key,model,name_en,vn_name,hs_code,origin,status,seen_count,first_seen,last_seen,"
                    "source_file,note,updated_by) VALUES(?,?,?,?,?,'','CONFIRMED',1,?,?,?,?,?)",
                    (key, a["desc"], (vn.split("#&")[0].strip() if "#&" in vn else ""), vn, hs, today, today,
                     lg.get("file_name") or "", note, u.get("id")))
            # 적힌 값과 다른 값을 고르면 이 인보이스 파일의 그 규격 칸도 고른 값으로(적힌 값은 원래 덮지 않는다 — 본사가 고른 규격만)
            if written and written != hs:
                ov[key] = hs
            else:
                ov.pop(key, None)
            c.execute("UPDATE export_hs_fill_log SET overrides=? WHERE id=?", (_js.dumps(ov, ensure_ascii=False), lid))
        with db_session() as c:
            entries2 = _hs_fill_entries(c)
        res2 = _hf.fill(raw, entries2, ov)
        if not res2.get("ok"):
            raise _HsFillStop(res2.get("error") or "파일을 다시 만들지 못했습니다", 409)
        sp = os.path.join(_HS_FILL_DIR, lg["stored"])
        tmp = sp[:-5] + "_tmp.xlsx"
        with open(tmp, "wb") as fo:
            fo.write(res2["out"])
        os.replace(tmp, sp)
        new_sha = _hl.sha256(res2["out"]).hexdigest() if res2["out"] != raw else None
        hist = [x for x in (lg.get("out_sha_hist") or "").split(",") if x]
        if lg.get("out_sha") and lg["out_sha"] not in hist:
            hist.append(lg["out_sha"])
        cn = res2["counts"]
        with db_session() as c:
            c.execute("UPDATE export_hs_fill_log SET out_sha=?, out_sha_hist=?, n_total=?, n_auto=?, n_check=?, n_need=?, n_keep=? "
                      "WHERE id=?", (new_sha, ",".join(hist[-30:]), cn["total"], cn["auto"], cn["check"], cn["need"], cn["keep"], lid))
    extra = {"confirmed": {"row": row, "desc": a["desc"], "hs": hs, "prev": prev, "dict_changed": dict_changed}}
    try:
        cvn = _js.loads(lg.get("conv_note") or "null")      # z1191u: 옛 양식에서 바꾼 기록이면 결과 카드에 그 요약을 그대로
    except ValueError:
        cvn = None
    if cvn:
        extra["conv"] = cvn
    if cn["no_reply"]:
        # z1191p: 본사 확정으로 노랑·주황이 다 풀리면 이 파일이 최종 — 지난 수출 이력에도(같은 번호면 바꿔 넣음)
        extra["hist_saved"] = _hs_hist_record_out(res2["out"], lg.get("file_name") or "", u)
    return _hs_fill_payload(lid, lg.get("file_name") or "", res2, extra)


@app.post("/export/hs-fill/{lid:int}/confirm")
async def export_hs_fill_confirm(req: Request, lid: int):
    """z1191n: ① 결과에서 본사가 고른 HS → 사전 확정 + 이 인보이스 파일을 그 값으로 다시 만든다. 결과는 ①과 같은 모양."""
    u = _export_guard(req)
    if not u:
        return JSONResponse({"ok": False, "error": "권한 없음"}, 403)
    try:
        body = await req.json()
    except Exception:
        body = None
    if not isinstance(body, dict):
        return JSONResponse({"ok": False, "error": "잘못된 요청입니다"}, 400)
    import re as _re_cf
    hs = _re_cf.sub(r"\D", "", str(body.get("hs") or ""))
    try:
        row = int(body.get("row") or 0)
    except (TypeError, ValueError):
        row = 0
    sheet = str(body.get("sheet") or "")
    if len(hs) != 8 or row <= 0 or not sheet:
        return JSONResponse({"ok": False, "error": "HS 8자리 · 줄 번호 · 시트가 필요합니다"}, 400)
    from starlette.concurrency import run_in_threadpool
    code, out = await run_in_threadpool(_hs_fill_confirm_work, lid, sheet, row, hs, u)
    return JSONResponse(out, code)


