# v5H226z968 (대표 지시): 신고용 Invoice&PL 실물 양식(시트 2장) + 수출 서류 정보(헤더블록).
#   안지연 프로가 베트남에 보내는 실제 파일(Invoice&packinglist_VN)과 동일 배치 —
#   B=관리번호 D=규격 F=수량 H=단가 I=금액(USD) K=원산지 M=CATEGORY N=HS code O=Tên hàng.
#   헤더블록(Consignee·항구·Carrier·Sailing·Invoice No·L/C·INCOTERMS)=export_doc_meta(프로젝트당 1행).
# ------------------------------------------------------------
_Z968_SHIPPER = ("KNK CO.,LTD",
                 "2, Gisan-ro 87 beon-gil, Hwaseong-si, Gyeonggi-do, Korea.",
                 "TEL : +82-70-4045-0407   FAX :  +82-31-267-0407",
                 "ATTN : Ji-Yeon, An (+82-10-2739-2660)")


def _doc_meta_ensure(c):
    c.execute("""CREATE TABLE IF NOT EXISTS export_doc_meta (
        project_id INTEGER PRIMARY KEY,
        invoice_no TEXT, invoice_date TEXT,
        consignee TEXT, notify TEXT,
        port_loading TEXT, final_dest TEXT,
        carrier TEXT, sailing_date TEXT,
        lc_no TEXT, payment TEXT, issuing_bank TEXT,
        incoterms TEXT, remarks TEXT,
        updated_by INTEGER, updated_at TEXT)""")
    # z1191z166 (대표 11-27): 수주별 신고 서류 정보 — 옛 관리번호 단위 표(export_doc_meta)는 지우지 않고 「처음 값」으로만 읽는다
    c.execute("""CREATE TABLE IF NOT EXISTS export_doc_meta_so (
        order_id INTEGER PRIMARY KEY, project_id INTEGER,
        invoice_no TEXT, invoice_date TEXT,
        consignee TEXT, notify TEXT,
        port_loading TEXT, final_dest TEXT,
        carrier TEXT, sailing_date TEXT,
        lc_no TEXT, payment TEXT, issuing_bank TEXT,
        incoterms TEXT, remarks TEXT,
        updated_by INTEGER, updated_at TEXT)""")


def _doc_meta_get(c, pid: int, p: dict | None = None, so: dict | None = None) -> dict:
    """프로젝트 수출 서류 정보 — 없으면 실물 관행 기본값으로 채운 dict(저장 전 프리필).
    z1191z166: so(_z166_doc_orders 의 수주 한 줄)를 주면 그 수주 값(export_doc_meta_so) ·
      수주 값이 아직 없으면 옛 관리번호 단위 값을 「처음 값」으로 보여 준다(복사 저장 안 함 · _src='old') ·
      수출 수주가 여럿이면 Invoice No 끝에 -순번(겹치지 않게 · 저장 전 미리 채우기)."""
    import datetime as _dt
    _doc_meta_ensure(c)
    if so:
        row = c.execute("SELECT * FROM export_doc_meta_so WHERE order_id=?", (int(so["id"]),)).fetchone()
        if row:
            d = dict(row)
            d["_src"] = "so"
        else:
            old = c.execute("SELECT * FROM export_doc_meta WHERE project_id=?", (pid,)).fetchone()
            d = dict(old) if old else {}
            d["_src"] = "old" if old else "new"
            if old and (so.get("n_doc") or 1) > 1 and d.get("invoice_no"):
                d["invoice_no"] = "%s-%s" % (d["invoice_no"], so.get("seq") or 1)
        if not d.get("invoice_no"):
            d["invoice_no"] = "KNK-" + _dt.date.today().strftime("%y%m%d") + "-" + str(so.get("seq") or 1)
        if not d.get("consignee"):
            d["consignee"] = so.get("buyer") or ""
        # 받는 곳 첫 줄에 이 수주 구매자 이름이 없으면 알림(막지 않음 · 입력 실수 찾기)
        _b166 = (so.get("buyer") or "").strip()
        d["_consignee_warn"] = bool(_b166 and _b166.lower() not in (d.get("consignee") or "").lower())
        d["order_id"] = int(so["id"])
    else:
        row = c.execute("SELECT * FROM export_doc_meta WHERE project_id=?", (pid,)).fetchone()
        d = dict(row) if row else {}
    if not d.get("invoice_no"):
        d["invoice_no"] = "KNK-" + _dt.date.today().strftime("%y%m%d") + "-1"
    if not d.get("invoice_date"):
        d["invoice_date"] = _dt.date.today().isoformat()
    if not d.get("consignee") and p:
        # z1191z165 (대표 11-27): 받는 곳 기본값 = 수주들의 1차 고객사(정식명 · 여럿이면 수주별 전부) — 관리번호 처음 등록 때 고객 아님 · 미리 채우기만(저장은 사용자가)
        d["consignee"] = _z165_doc_vals(c, pid, 0)["buyer"]
    d.setdefault("notify", "SAME AS ABOVE")
    if not d.get("notify"):
        d["notify"] = "SAME AS ABOVE"
    d["port_loading"] = d.get("port_loading") or "Incheon, Korea"
    d["final_dest"] = d.get("final_dest") or "Hanoi, Vietnam"
    d["payment"] = d.get("payment") or "T/T"
    d["incoterms"] = d.get("incoterms") or "C.I.P"
    for k in ("carrier", "sailing_date", "lc_no", "issuing_bank", "remarks"):
        d.setdefault(k, "")
        if d[k] is None:
            d[k] = ""
    return d


@app.post("/export/prep/{pid:int}/doc-meta")
async def export_doc_meta_save(req: Request, pid: int):
    """수출 서류 정보 저장(upsert) — 통관 화면 '신고 서류 정보' 카드."""
    u = _export_guard(req)
    if not u:
        return JSONResponse({"ok": False, "error": "권한 없음"}, 403)
    form = await req.form()
    cols = ("invoice_no", "invoice_date", "consignee", "notify", "port_loading", "final_dest",
            "carrier", "sailing_date", "lc_no", "payment", "issuing_bank", "incoterms", "remarks")
    vals = [(form.get(k) or "").strip() for k in cols]
    _so166 = (form.get("so") or req.query_params.get("so") or "").strip()
    with db_session() as c:
        _doc_meta_ensure(c)
        # z1191z166 (대표 11-27): 수주별로 저장 — 어느 수주인지 모르면 저장하지 않는다(옛 관리번호 단위 표는 그대로 둠)
        st166, o166, _L166 = _z166_pick(c, pid, _so166)
        if st166 != "ok":
            return JSONResponse({"ok": False, "error": "어느 수주의 서류 정보인지 골라 주세요 — 수주별로 저장합니다(저장하지 않았습니다)"}, 400)
        c.execute(
            f"INSERT INTO export_doc_meta_so(order_id,project_id,{','.join(cols)},updated_by,updated_at) "
            f"VALUES(?,?,{','.join('?' * len(cols))},?,datetime('now','localtime')) "
            f"ON CONFLICT(order_id) DO UPDATE SET project_id=excluded.project_id, "
            + ", ".join(f"{k}=excluded.{k}" for k in cols)
            + ", updated_by=excluded.updated_by, updated_at=excluded.updated_at",
            [o166["id"], pid] + vals + [u.get("id")])
    return JSONResponse({"ok": True, "order_id": o166["id"], "order_no": o166["order_no"]})


# v5H226z970 (대표 지시): 박스별 무게·크기 — 실무는 부품별이 아니라 '박스 단위'로 계량
#   (실물 PACKING LIST: 품목엔 중량 없음·첫 행에 전체 Gross·우측에 박스별 G/W. 구매팀 BOX시트도 박스당 무게 1개).
#   품목별 중량 칸은 유지(안 쓰면 컬럼 숨김) — 박스 무게가 입력돼 있으면 신고용 파일은 박스 무게 우선.
def _export_boxes_ensure(c):
    c.execute("""CREATE TABLE IF NOT EXISTS export_boxes (
        project_id INTEGER NOT NULL,
        box_no TEXT NOT NULL,
        weight_kg REAL, box_size TEXT,
        updated_by INTEGER, updated_at TEXT,
        PRIMARY KEY(project_id, box_no))""")
    # z1191z177 (대표 11-27 「수주 기준으로 고쳐서 진행해」): 박스 무게 = 수주마다(같은 관리번호의 다른 수주가 같은 BOX 번호를 써도 안 섞임)
    #   옛 관리번호 단위 표(export_boxes)는 지우지 않고 「처음 값」으로 보여 주기만(저절로 옮겨 저장하지 않음)
    c.execute("""CREATE TABLE IF NOT EXISTS export_boxes_so (
        order_id INTEGER NOT NULL,
        project_id INTEGER NOT NULL,
        box_no TEXT NOT NULL,
        weight_kg REAL, box_size TEXT,
        updated_by INTEGER, updated_at TEXT,
        PRIMARY KEY(order_id, box_no))""")


def _z177_my_boxes(c, oid):
    """그 수주 품목에 적힌 박스번호(대문자) — 취소 품목 제외."""
    return {str(r[0]).strip().upper() for r in c.execute(
        "SELECT DISTINCT box_no FROM order_items WHERE order_id=? AND COALESCE(unit_status,'')<>'취소' "
        "AND COALESCE(TRIM(box_no),'')<>''", (oid,)).fetchall()}


def _z177_boxes(c, pid, oid):
    """z1191z177: 수주 하나의 박스 무게 → (줄, 출처) · 출처 'so' = 이 수주로 저장한 값 · 'old' = 아직 없어 옛 관리번호 단위 값 중
    이 수주 품목 박스번호만(보여 주기만) · 'none' = 없음."""
    _export_boxes_ensure(c)
    rows = [dict(r) for r in c.execute(
        "SELECT box_no, weight_kg, box_size FROM export_boxes_so WHERE order_id=? ORDER BY box_no", (oid,))]
    if rows:
        return rows, "so"
    mine = _z177_my_boxes(c, oid)
    old = [dict(r) for r in c.execute(
        "SELECT box_no, weight_kg, box_size FROM export_boxes WHERE project_id=? ORDER BY box_no", (pid,))]
    old = [b for b in old if str(b.get("box_no") or "").strip().upper() in mine]
    return old, ("old" if old else "none")


@app.post("/export/prep/{pid:int}/boxes")
async def export_boxes_save(req: Request, pid: int):
    """박스별 무게·크기 저장(그 프로젝트 전체 교체) — 통관 화면 '박스별 무게' 카드."""
    u = _export_guard(req)
    if not u:
        return JSONResponse({"ok": False, "error": "권한 없음"}, 403)
    try:
        body = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "invalid_json"}, 400)
    rows = body.get("boxes")
    if not isinstance(rows, list):
        return JSONResponse({"ok": False, "error": "boxes 형식 오류"}, 400)
    with db_session() as c:   # z1191z177: 어느 수주의 박스인지 — 이 관리번호의 수출 서류 대상 수주만
        st177, o177, _L177 = _z166_pick(c, pid, str(body.get("so") or ""))
    if st177 != "ok" or not o177:
        return JSONResponse({"ok": False, "error": "어느 수주의 박스인지 몰라 저장하지 않았습니다 — 위 「수주별 수출 서류」 표에서 수주를 골라 주세요."}, 400)
    clean, seen = [], set()
    for r in rows[:200]:
        if not isinstance(r, dict):
            continue
        bn = str(r.get("box_no") or "").strip()[:30]
        if not bn or bn.upper() in seen:
            continue
        seen.add(bn.upper())
        try:
            _raw = str(r.get("weight_kg") or "").replace(",", "").strip()
            w = float(_raw) if _raw else None
        except ValueError:
            w = None
        clean.append((bn, w, str(r.get("box_size") or "").strip()[:40]))
    with db_session() as c:
        _export_boxes_ensure(c)
        c.execute("DELETE FROM export_boxes_so WHERE order_id=?", (o177["id"],))   # 이 수주 것만 바꿈(다른 수주·옛 표 그대로)
        for bn, w, sz in clean:
            c.execute(
                "INSERT OR REPLACE INTO export_boxes_so(order_id, project_id, box_no, weight_kg, box_size, updated_by, updated_at) "
                "VALUES(?,?,?,?,?,?,datetime('now','localtime'))",
                (o177["id"], pid, bn, w, sz, u.get("id")))
    return JSONResponse({"ok": True, "saved": len(clean), "order_no": o177.get("order_no") or ""})


def _z968_head_block(ws, title: str, dm: dict, F, thin_border):
    """실물 헤더블록(1~29행) — INVOICE/PACKING LIST 공용. 반환=품목 헤더 시작행(31)."""
    from openpyxl.styles import Alignment as _Al
    ws["A1"] = title
    ws["A1"].font = F(size=16, bold=True)
    ws.merge_cells("A1:O1")
    ws["A1"].alignment = _Al(horizontal="center", vertical="center")
    lab = F(size=9, bold=True, color="555555")
    val = F(size=10)
    def _set(addr, text, fo=None):
        ws[addr] = text
        ws[addr].font = fo or val
    _set("A2", "1) Shipper / Exporter", lab)
    _set("B4", _Z968_SHIPPER[0], F(size=11, bold=True))
    _set("B5", _Z968_SHIPPER[1])
    _set("B6", _Z968_SHIPPER[2])
    _set("B8", _Z968_SHIPPER[3])
    _set("F2", "8) No. & Date of Invoice", lab)
    _set("G4", dm.get("invoice_no") or "", F(size=11, bold=True))
    _set("H4", "DATE:", lab)
    _set("I4", dm.get("invoice_date") or "")
    _set("F7", "9) No. & Date of L/C", lab)
    _set("G8", dm.get("lc_no") or "")
    _set("A10", "2) For Account & Risk of Messrs", lab)
    _set("F10", dm.get("payment") or "T/T")
    for i, ln in enumerate((dm.get("consignee") or "").splitlines()[:5]):
        _set(f"B{12+i}", ln, F(size=10, bold=(i == 0)))
    _set("F13", "10) Issuing Bank", lab)
    _set("G14", dm.get("issuing_bank") or "")
    _set("A19", "3) Notify Party", lab)
    _set("B21", dm.get("notify") or "SAME AS ABOVE")
    _set("F19", "11) Remarks", lab)
    _set("G21", "INCOTERMS : " + (dm.get("incoterms") or ""))
    if (dm.get("remarks") or "").strip():
        _set("G22", dm.get("remarks"))
    _set("A24", "4) Port of Loading", lab)
    _set("D24", "5) Final Destination", lab)
    _set("A25", dm.get("port_loading") or "")
    _set("D25", dm.get("final_dest") or "")
    _set("A28", "6) Carrier", lab)
    _set("D28", "7) Sailing On or About", lab)
    _set("A29", dm.get("carrier") or "")
    _set("D29", dm.get("sailing_date") or "")
    return 31


@app.get("/export/prep/{pid:int}/invoice-pl.xlsx")
async def export_prep_invoice_pl_xlsx(req: Request, pid: int, so: str = ""):
    """신고용 Invoice&PL 실물 양식(시트 2장) — 베트남 전달·수출/수입신고에 그대로 사용.
    INVOICE: B관리번호 D규격 F수량 H단가 I금액(USD) K원산지 M CATEGORY N HS code O Tên hàng.
    PACKING LIST: B관리번호 D규격 F수량 I Gross(kg) + 우측 박스 요약(NO/SIZE/G/W)."""
    u = _export_guard(req)
    if not u:
        return RedirectResponse("/home", 303)
    with db_session() as c:
        st166, o166, L166 = _z166_pick(c, pid, so)   # z1191z166: 수주별
        if st166 != "ok":
            return _z166_pick_page(req, u, c, pid, st166, L166, "invoice-pl", so)
        _sid = o166["id"]
        p, ci, lines = _export_ci_build(c, pid, _sid)
        if not p:
            return RedirectResponse("/export/prep", 303)
        dm = _doc_meta_get(c, pid, p, o166)
        _p2, _pl, pl_lines = _export_pl_build(c, pid, _sid)
        _p3, _pl2, _pll, box_list = _export_ship_boxes(c, pid, _sid)
        # v5H226z970: 박스별 무게(사용자 입력) — 있으면 품목별 중량 대신 이걸 사용(실물 관행)
        # z1191z177: 박스 무게 = 이 수주로 저장한 값(없으면 옛 관리번호 단위 값 중 이 수주 품목 박스만)
        ebx, _bsrc177 = _z177_boxes(c, pid, _sid)
    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font as _Font, PatternFill, Alignment, Border, Side
        import io as _io
    except ImportError:
        return JSONResponse({"error": "openpyxl 미설치"}, 500)
    def F(**kw):
        return _Font(name="Arial", **kw)
    thin = Side(style="thin", color="B7B0A0")
    border = Border(left=thin, right=thin, top=thin, bottom=thin)
    head_fill = PatternFill("solid", fgColor="F4F1E8")
    wb = Workbook()

    # ── 시트1: INVOICE ──
    ws = wb.active
    ws.title = "INVOICE"
    hr = _z968_head_block(ws, "COMMERCIAL  INVOICE", dm, F, border)
    heads = [("A", "12) Marks and\nNumber of PKGS"), ("D", "13) Description of Goods"),
             ("F", "14) Q'ty /Unit"), ("H", "15) Unit Price"), ("I", "16) Amount"),
             ("K", "원산지"), ("M", "CATEGORY"), ("N", "HS code"), ("O", "Tên hàng")]
    for col, t in heads:
        cell = ws[f"{col}{hr}"]
        cell.value = t
        cell.font = F(size=9, bold=True)
        cell.fill = head_fill
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
        cell.border = border
    r = hr + 1
    mgmt = p.get("mgmt_code") or ""
    for l in lines:
        ws[f"B{r}"] = mgmt
        ws[f"D{r}"] = l["spec"] or l["part_name"]
        ws[f"F{r}"] = l["qty"]
        ws[f"G{r}"] = l["unit"]
        ws[f"H{r}"] = l["unit_price"]
        ws[f"I{r}"] = l["amount"]
        ws[f"K{r}"] = l["origin"]
        desc = l.get("description") or ""
        ws[f"M{r}"] = (desc.split("#&")[0].strip() if "#&" in desc else "")
        ws[f"N{r}"] = l["hs_code"]
        ws[f"O{r}"] = desc
        for col in ("H", "I"):
            ws[f"{col}{r}"].number_format = "#,##0.00"
        r += 1
    ws[f"D{r}"] = "TOTAL"
    ws[f"D{r}"].font = F(size=10, bold=True)
    ws[f"F{r}"] = ci["total_qty"]
    ws[f"I{r}"] = ci["total_amount"]
    ws[f"I{r}"].number_format = "#,##0.00"
    ws[f"I{r}"].font = F(size=10, bold=True)
    for w_, col in ((6, "A"), (14, "B"), (4, "C"), (26, "D"), (4, "E"), (8, "F"), (6, "G"),
                    (12, "H"), (13, "I"), (3, "J"), (9, "K"), (9, "L"), (16, "M"), (11, "N"), (52, "O")):
        ws.column_dimensions[col].width = w_

    # ── 시트2: PACKING LIST ──
    ws2 = wb.create_sheet("PACKING LIST")
    hr2 = _z968_head_block(ws2, "PACKING  LIST", dm, F, border)
    heads2 = [("A", "12) Marks and\nNumber of PKGS"), ("D", "13) Description of Goods"),
              ("F", "14) Q'ty /Unit"), ("H", "Net-\nWeight"), ("I", "Gross-\nWeight"),
              ("J", "Measurement"), ("L", "NO."), ("M", "SIZE"), ("N", "G/W")]
    for col, t in heads2:
        cell = ws2[f"{col}{hr2}"]
        cell.value = t
        cell.font = F(size=9, bold=True)
        cell.fill = head_fill
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
        cell.border = border
    r = hr2 + 1
    first_r = r
    br = hr2 + 1   # 우측 박스 요약 행
    # v5H226z970: 박스 요약 = 사용자 입력(export_boxes) 우선 · 없으면 품목별 중량 합산(box_list) 폴백
    has_bw = any((b.get("weight_kg") or 0) for b in (ebx or []))
    if ebx:
        for b in ebx:
            ws2[f"L{br}"] = b.get("box_no")
            ws2[f"M{br}"] = b.get("box_size") or ""
            if b.get("weight_kg"):
                ws2[f"N{br}"] = round(float(b["weight_kg"]), 1)
            br += 1
    else:
        for bx in (box_list or []):
            ws2[f"L{br}"] = bx.get("box")
            _sz = ""
            for it in bx.get("items", []):
                if (it.get("pallet_size") or "").strip():
                    _sz = it["pallet_size"].strip()
                    break
            ws2[f"M{br}"] = _sz
            ws2[f"N{br}"] = round(float(bx.get("weight") or 0), 1)
            br += 1
    tq = tw = 0.0
    for l in (pl_lines or []):
        ws2[f"B{r}"] = mgmt
        ws2[f"D{r}"] = l.get("spec") or l.get("part_name") or ""
        ws2[f"F{r}"] = l.get("qty")
        ws2[f"G{r}"] = l.get("unit") or "EA"
        _w = float(l.get("weight_kg") or 0)
        if _w and not has_bw:
            ws2[f"I{r}"] = _w   # 품목별 중량은 박스 무게가 없을 때만(폴백)
        tq += float(l.get("qty") or 0)
        tw += _w
        r += 1
    if has_bw:
        # 실물 관행: 첫 행에 전체 Gross(=박스 무게 합) 한 번
        tw = sum(float(b.get("weight_kg") or 0) for b in ebx)
        ws2[f"I{first_r}"] = round(tw, 1)
        ws2[f"I{first_r}"].font = F(size=10, bold=True)
    ws2[f"D{r}"] = "TOTAL"
    ws2[f"D{r}"].font = F(size=10, bold=True)
    ws2[f"F{r}"] = round(tq, 2)
    ws2[f"I{r}"] = round(tw, 1)
    ws2[f"I{r}"].font = F(size=10, bold=True)
    for w_, col in ((6, "A"), (14, "B"), (4, "C"), (26, "D"), (4, "E"), (8, "F"), (6, "G"),
                    (9, "H"), (9, "I"), (12, "J"), (3, "K"), (7, "L"), (22, "M"), (9, "N")):
        ws2.column_dimensions[col].width = w_

    buf = _io.BytesIO()
    wb.save(buf)
    buf.seek(0)
    from urllib.parse import quote
    import datetime as _dt
    fn = f"Invoice&packinglist_VN({_dt.date.today().strftime('%y%m%d')})_{mgmt or pid}_{ci.get('so_no') or ''}.xlsx"   # z1191z166: 수주번호
    return StreamingResponse(
        buf, media_type=_XLSX_MIME,
        headers={"Content-Disposition": f"attachment; filename*=UTF-8''{quote(fn)}",
                 "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
                 "Pragma": "no-cache", "Expires": "0"})


