@app.post("/po/{po_id}/items/{iid}/link-project")
async def po_item_link_project_route(request: Request, po_id: int, iid: int):
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_use_logistics(u):
        return RedirectResponse("/home", 303)
    form = await request.form()
    try:
        project_id = int(form.get("project_id") or 0)
    except ValueError:
        project_id = 0
    if not project_id:
        return RedirectResponse(f"/po/{po_id}?error=프로젝트를+선택하세요", 303)
    allocated_qty = form.get("allocated_qty") or None
    allocation_pct = form.get("allocation_pct") or None
    note = (form.get("note") or "").strip() or None
    try:
        _logi.po_item_link_project(
            po_item_id=iid, project_id=project_id,
            allocated_qty=allocated_qty, allocation_pct=allocation_pct,
            note=note,
            user_id=(u.get("id") if isinstance(u, dict) else u["id"]),
        )
    except Exception as e:
        return RedirectResponse(f"/po/{po_id}?error=연결+실패:{e}", 303)
    return RedirectResponse(f"/po/{po_id}#item-{iid}", 303)


@app.post("/po/links/{link_id}/delete")
async def po_item_unlink_project_route(request: Request, link_id: int):
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_use_logistics(u):
        return RedirectResponse("/home", 303)
    po_id = None
    try:
        with db_session() as c:
            row = c.execute(
                """SELECT pi.po_id FROM po_item_project_links l
                   JOIN po_items pi ON l.po_item_id=pi.id
                   WHERE l.id=?""", (link_id,)
            ).fetchone()
            if row:
                po_id = row[0]
    except Exception:
        pass
    try:
        _logi.po_item_unlink_project(link_id)
    except Exception:
        pass
    if po_id:
        return RedirectResponse(f"/po/{po_id}", 303)
    ref = request.headers.get("referer", "/po")
    return RedirectResponse(ref, 303)


@app.get("/api/projects/search")
async def api_projects_search(request: Request, q: str = ""):
    """프로젝트 자동완성 — 관리번호 또는 이름 부분일치.
    PO 라인 → 프로젝트 연결 폼에서 사용."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "auth"}, 401)
    if not (can_use_sales(u) or can_use_logistics(u)):
        return JSONResponse({"ok": False, "error": "forbidden"}, 403)
    q = (q or "").strip()
    rows = []
    try:
        with db_session() as c:
            if q:
                like = f"%{q}%"
                # v5H226z385 (대표 지시): 관리번호 몰라도 쉽게 — 고객사명·모델명·장비명·프로젝트명으로도 검색
                rs = c.execute(
                    """SELECT p.id, p.mgmt_code, p.name, p.equip_type, p.status,
                              p.customer_id, p.biz_div, p.model_name, p.equip_name, p.po_type, p.is_export,
                              cu.name AS customer_name
                       FROM projects p
                       LEFT JOIN customers cu ON p.customer_id=cu.id
                       WHERE (p.mgmt_code LIKE ? OR p.name LIKE ? OR cu.name LIKE ?
                              OR p.model_name LIKE ? OR p.equip_name LIKE ?)
                         AND p.mgmt_code IS NOT NULL AND p.mgmt_code != ''
                       ORDER BY p.id DESC LIMIT 30""",
                    (like, like, like, like, like)
                ).fetchall()
            else:
                rs = c.execute(
                    """SELECT p.id, p.mgmt_code, p.name, p.equip_type, p.status,
                              p.customer_id, p.biz_div, p.model_name, p.equip_name, p.po_type, p.is_export,
                              cu.name AS customer_name
                       FROM projects p
                       LEFT JOIN customers cu ON p.customer_id=cu.id
                       WHERE p.mgmt_code IS NOT NULL AND p.mgmt_code != ''
                       ORDER BY p.id DESC LIMIT 30"""
                ).fetchall()
            rows = [dict(r) for r in rs]
            # z1191 (대표 「등록할 때부터 발주업체를 수주번호별로」): 추가 발주 「지난 발주처」 단추 — 그 관리번호 수주들의 1차·2차
            try:
                _rows_add_so_custs_z1191(c, rows)
            except Exception as _e1191:
                print(f"[z1191] 지난 발주처 목록 실패(단추 없이 계속): {_e1191}")
    except Exception as e:
        return JSONResponse({"ok": False, "error": str(e)}, 500)
    return JSONResponse({"ok": True, "rows": rows})


@app.get("/api/projects/by-mgmt")
async def api_project_by_mgmt(request: Request, code: str = ""):
    """v5H226z166: 관리번호로 기존 프로젝트 + 고객사 담당자 조회 ('확인' 버튼 자동입력용)."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "auth"}, 401)
    code = (code or "").strip().upper()
    if not code:
        return JSONResponse({"ok": True, "found": False})
    with db_session() as c:
        row = c.execute(
            "SELECT id, name, customer_name, customer_id, cc_name, cc_dept, cc_position, "
            "cc_phone, cc_email, cc_note FROM projects WHERE mgmt_code=? LIMIT 1",
            (code,)).fetchone()
        if not row:
            return JSONResponse({"ok": True, "found": False})
        d = dict(row)
        # 담당자가 프로젝트에 없으면(레거시) 고객사 주소록 주담당으로 폴백
        if not (d.get("cc_name") or "").strip() and d.get("customer_name"):
            cc = c.execute(
                "SELECT cc.name, cc.department, cc.position, cc.phone, cc.mobile, "
                "cc.email, cc.note FROM customer_contacts cc "
                "JOIN customers cu ON cc.customer_id=cu.id "
                # z1191z157: 고객 번호로(이름이 바뀌어도·같은 이름 지점이 여러 곳이어도 그 고객사) · 번호 없으면 예전처럼 이름
                + ("WHERE cu.id=? " if d.get("customer_id") else "WHERE cu.name=? ")
                + "ORDER BY cc.is_primary DESC, cc.id LIMIT 1",
                (d["customer_id"] or d["customer_name"],)).fetchone()
            if cc:
                d["cc_name"] = cc["name"] or ""
                d["cc_dept"] = cc["department"] or ""
                d["cc_position"] = cc["position"] or ""
                d["cc_phone"] = cc["phone"] or cc["mobile"] or ""
                d["cc_email"] = cc["email"] or ""
                d["cc_note"] = cc["note"] or ""
    return JSONResponse({"ok": True, "found": True, "project": {
        "id": d["id"], "name": d.get("name") or "",
        "customer_name": d.get("customer_name") or "",
        "cc_name": d.get("cc_name") or "", "cc_dept": d.get("cc_dept") or "",
        "cc_position": d.get("cc_position") or "", "cc_phone": d.get("cc_phone") or "",
        "cc_email": d.get("cc_email") or "", "cc_note": d.get("cc_note") or "",
    }})



