@app.get("/consumables/{co_id:int}", response_class=HTMLResponse)
async def consumables_detail(request: Request, co_id: int):
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not (can_use_logistics(u) or can_use_sales(u)):
        return RedirectResponse("/home", 303)
    co = _co.co_get(co_id)
    if not co:
        return RedirectResponse("/consumables", 303)
    items = _co.coi_list(co_id)
    # v5H226z300/z301 (대표 지시): 미연결 라인에 '등록 자재 추천' + '관리번호(모델 자동매칭) 추천'
    for _it in items:
        if not _it.get("part_id"):
            _it["suggest_part"] = _co.match_part_by_name(_it.get("part_name", ""))
        if not _it.get("linked_project_id"):
            # v5H226z302 (대표 지시): 추천 = 같은 1차 고객사 + 모델명 90%↑ + 장비명 90%↑ (모두 충족)
            _it["suggest_mgmt"] = _co.suggest_mgmt_for_line(
                _it.get("model_use", ""), _it.get("equip_name", ""), co.get("customer_id"))
    # v5H226z292 (대표 지시): 관련부서 통보 — 부서 선택 모달용 팀 목록(활성 인원 있는 팀)
    _teams = []
    try:
        with db_session() as _tc:
            _teams = [dict(r) for r in _tc.execute(
                "SELECT t.id, t.name, t.entity, COUNT(u.id) AS member_count "
                "FROM teams t LEFT JOIN users u ON u.team_id=t.id AND COALESCE(u.is_active,1)=1 "
                "GROUP BY t.id, t.name, t.entity HAVING member_count > 0 "
                "ORDER BY (CASE WHEN COALESCE(t.entity,'KOR')='VN' THEN 1 ELSE 0 END), t.display_order, t.id"
            ).fetchall()]   # z886: 법인(entity) 포함·본사 먼저 → 선택위젯 본사/베트남 탭
    except Exception:
        _teams = []
    # v5H226z890 (대표 지시): 개별 인원 선택 — 팀별 구성원(제작요청 통보와 동일)
    _team_members = {}
    try:
        with db_session() as _tmc:
            for _mr in _tmc.execute(
                "SELECT u.id, u.team_id, u.name, COALESCE(u.name_vi,'') AS name_vi, "
                "COALESCE(u.rank,'') AS rank FROM users u "
                "WHERE COALESCE(u.is_active,1)=1 AND u.team_id IS NOT NULL ORDER BY u.team_id, u.name").fetchall():
                _d = dict(_mr); _team_members.setdefault(_d["team_id"], []).append(_d)
    except Exception:
        _team_members = {}
    _history = _co.co_history_list(co_id)   # v5H226z298: 변경 이력 탭
    # v5H226z299 (대표 지시): 1차 고객사는 등록 고객사 중에서만 선택 — 드롭다운 목록
    _customers = []
    try:
        with db_session() as _cc:
            _customers = [dict(r) for r in _cc.execute(
                "SELECT " + _CUST_PICK_COLS + " FROM customers ORDER BY " + _CUST_PICK_ORDER_SQL).fetchall()]   # z1158
    except Exception:
        _customers = []
    return ctx(request, "consumable_detail.html",
               user=u, active="consumables",
               co=co, items=items, teams=_teams, team_members=_team_members,
               history=_history, customers=_customers,
               STATUS_LABELS=_co.CO_STATUS_LABELS,
               STATUSES=_co.CO_STATUSES,
               project_choices=_co.project_name_choices())     # z1191z3


@app.get("/consumables/{co_id:int}/prod-request", response_class=HTMLResponse)
async def consumable_prod_request_view(request: Request, co_id: int):
    """v5H226z892 (대표 지시): 소모품 '제작요청서' 보기 페이지 — 제작요청서목록 소모품 카드 클릭 시
    편집 상세(소모품 상세) 대신 이 읽기 페이지로 이동(제작요청서와 동일 레이아웃·가격 제외).
    여기서 작업일정표·전사일정표로 이동. 편집은 소모품 상세에서만.
    v5H226z894 (대표 지시): 전사일정표에서 일반 직원이 관리번호를 눌러 이 '제작요청서 보기'로 오므로
    로그인만 하면 누구나 열람(가격 없음·읽기용). 편집(소모품 상세)은 그대로 물류/영업 게이트."""
    u = get_user(request)
    if not u:
        from urllib.parse import quote as _quote
        _nxt = request.url.path + (("?" + request.url.query) if request.url.query else "")
        return RedirectResponse("/login?next=" + _quote(_nxt, safe=""), 303)
    co = _co.co_get(co_id)
    if not co:
        return RedirectResponse("/consumables", 303)
    items = _co.coi_list(co_id) or []
    try:
        _qt = sum(float(it.get("qty") or 0) for it in items)
        qty_total = int(_qt) if abs(_qt - int(_qt)) < 1e-9 else round(_qt, 2)
    except Exception:
        qty_total = ""
    _FORM = {"ASSEMBLY": "🏭 완제품", "SEMI": "📦 제품", "PARTS": "🧰 상품", "ETC": "🗂 기타",
             "제품": "📦 제품", "상품": "🧰 상품", "기타": "🗂 기타"}
    _ft = str(co.get("form_type") or "").strip()
    form_label = _FORM.get(_ft) or _FORM.get(_ft.upper()) or (_ft or "—")
    export_label = "🚢 수출" if co.get("is_export") else "🏠 내수"
    # v5H226z895 (대표 지시): '소모품 상세(편집)' 버튼은 상세를 실제로 열 수 있는 영업·물류 권한자만 활성화.
    #   일반 직원(등록자)은 상세 진입 시 홈으로 튕기므로 버튼을 비활성(회색) 표시.
    _can_open_detail = bool(can_use_logistics(u) or can_use_sales(u))
    # z1191z48 (대표 2026-11-17 「소모품 요청서 … 여기에도 관리번호·수주번호」): 종이 양식 머리 칸에 쓸 값
    # z1191z52 (대표 2026-11-18 「연결 장비 모델 자동」): 줄 모델명 = 연결 장비(관리번호)의 모델명 — 줄에 따로 입력하지 않음(z730)
    try:
        _lp52 = sorted({int(it["linked_project_id"]) for it in items if str(it.get("linked_project_id") or "").isdigit()})
        _mm52 = {}
        if _lp52:
            with db_session() as _c52:
                _mm52 = {r[0]: str(r[1] or "").strip() for r in _c52.execute(
                    "SELECT id, model_name FROM projects WHERE id IN (%s)" % ",".join("?" * len(_lp52)), tuple(_lp52)).fetchall()}
        for it in items:
            it["link_model"] = _mm52.get(int(it["linked_project_id"]), "") if str(it.get("linked_project_id") or "").isdigit() else ""
    except Exception as _e52:
        print(f"[z1191z52] 연결 장비 모델 읽기 실패: {_e52}")
    _z48c = _z48_co_ctx(co, items)
    return ctx(request, "consumable_prod_request.html", user=u, active="consumables", z48c=_z48c,
               co=co, items=items, qty_total=qty_total,
               form_label=form_label, export_label=export_label,
               biz_label=_consumable_biz_label(co.get("biz_div")),   # z1019: 소모품·(진행사업부)
               can_open_detail=_can_open_detail)


def _co_item_of_z1191z9(co_id, iid):
    """z1191z9: 그 품목(iid)이 주소의 소모품(co_id) 것인가 — 아니면 저장·삭제 거부(앞에 본 소모품 번호로 남의 품목을 고치던 사고)."""
    try:
        it = _co.coi_get(iid)
        return bool(it) and int(it.get("co_id") or 0) == int(co_id)
    except Exception:
        return False


_CO_PAGE_MSG_Z1191Z9 = "화면이 바뀌었습니다 — 새로 고침(F5) 뒤 다시 저장해 주세요(이번 저장은 반영 안 됨)"


def _co_page_ok_z1191z9(co_id, b):
    """z1191z9: 저장 요청의 「화면 소모품 번호」(page_co)가 주소 번호와 같은가. 없으면(옛 화면 스크립트) 거부."""
    try:
        return int(str((b or {}).get("page_co") or "0")) == int(co_id)
    except Exception:
        return False


@app.post("/consumables/{co_id:int}/items/{iid:int}/edit")
async def consumables_item_edit(request: Request, co_id: int, iid: int):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "auth"}, 401)
    if not (can_use_logistics(u) or can_use_sales(u)):
        return JSONResponse({"ok": False, "error": "forbidden"}, 403)
    if not _co_item_of_z1191z9(co_id, iid):   # z1191z9: 이 소모품의 품목만
        return JSONResponse({"ok": False, "error": _CO_PAGE_MSG_Z1191Z9}, 409)
    form = await request.form()
    fields = {}
    for k in ("model_use", "equip_name", "part_name", "spec", "unit", "note", "secondary_customer"):  # v5H226z297: 장비명 편집 · z1191z20: 품목 2차
        if k in form:
            fields[k] = (form.get(k) or "").strip()
    for k in ("qty", "unit_price"):
        if k in form and _logi.num_swap_hint(form.get(k)) is not None:   # z1191z56: 점·쉼표 바꿔 친 숫자
            return JSONResponse({"ok": False, "error": _logi.num_swap_msg(form.get(k))}, 400)
    for k in ("qty", "unit_price"):
        if k in form:
            try:
                fields[k] = float((form.get(k) or "0").replace(",", ""))
            except ValueError:
                fields[k] = 0
    for k in ("part_id", "linked_project_id"):
        if k in form:
            v = (form.get(k) or "").strip()
            fields[k] = int(v) if v.isdigit() else None
    _co.coi_update(iid, fields, by_id=u.get("id"), by_name=(u.get("name") or u.get("login_id") or ""))
    co = _co.co_get(co_id)
    return JSONResponse({"ok": True, "total_amount": (co or {}).get("total_amount", 0)})


# v5H226z298 (대표 지시): 소모품수주 정보란(헤더) 인라인 수정 — 작업일정표와 같은 원본을 바꿔 양방향 동기화 + 이력.
@app.post("/consumables/{co_id:int}/edit-field")
async def consumables_edit_field(request: Request, co_id: int):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "auth"}, 401)
    if not (can_use_logistics(u) or can_use_sales(u)):
        return JSONResponse({"ok": False, "error": "forbidden"}, 403)
    try:
        b = await request.json()
    except Exception:
        b = {}
    if not _co_page_ok_z1191z9(co_id, b):   # z1191z9: 화면 번호 ≠ 주소 번호 → 거부
        return JSONResponse({"ok": False, "error": _CO_PAGE_MSG_Z1191Z9}, 409)
    field = (b.get("field") or "").strip()
