# v5H145 (2026-05-05) — 관련부서 통보 발송
# 대표 의도: 영업이 소모품 발주 등록 → 자재구매팀·생산팀이 시스템 알림으로 즉시 인지
# 대상: can_use_logistics=1 (자재팀) + can_use_production=1 (생산팀이 있다면) + role IN admin/ceo
# v5H226z1019 (대표 지시): 소모품 사업부 배지 = '소모품' 유지 + 진행사업부(biz_div) 부기('소모품·검사기').
#   빈값/미지정은 '소모품'만. 목록 카드·소모품 상세·이음 카드 공용(표기 통일).
_CONS_BIZ_SUB = {"T": "검사기", "M": "자동화", "L": "라이프밸류", "E": "기타"}
_TBD117_MAP = {}   # z1191z117 ⑤: {project_id: 단가 미정이고 금액 0} — _proj_free_so_map_z1191z8 가 채운다(같은 요청 안에서 바로 씀)


def _proj_tbd_z117(p):
    try:
        return bool(_TBD117_MAP.get(p.get("id")))
    except Exception:
        return False


def _proj_free_so_map_z1191z8(pids=None):
    """z1191z8: 프로젝트별 「수주가 전부 무상인가」 {project_id: bool} — 호기(order_items) 분할 줄이 안 나오는
    단일 수주·호기 없는 프로젝트 줄용. 수주 무상 = 호기 있으면 단가·금액 전부 0(NULL 아님) · 호기 없으면 수주금액이 0 으로 적힘.
    수주가 없는 프로젝트는 빠짐(→ projects 값으로 판정)."""
    out = {}
    try:
        with db_session() as _c:
            _tbdc = ("COALESCE(o.price_tbd,0)" if "price_tbd" in {x[1] for x in _c.execute("PRAGMA table_info(orders)").fetchall()} else "0")   # z1191z117 ⑤
            for r in _c.execute(
                "SELECT o.project_id AS pid, o.total_amount AS tot, " + _tbdc + " AS tbd, COUNT(oi.id) AS n, "
                "SUM(CASE WHEN oi.unit_price IS NULL AND oi.amount IS NULL THEN 1 ELSE 0 END) AS nn, "
                "SUM(CASE WHEN COALESCE(oi.unit_price,0)<>0 OR COALESCE(oi.amount,0)<>0 THEN 1 ELSE 0 END) AS nz "
                "FROM orders o LEFT JOIN order_items oi ON oi.order_id=o.id "
                "WHERE o.project_id IS NOT NULL AND COALESCE(o.status,'')<>'CANCELLED'" + _board_in_frag("o.project_id", pids) +
                " GROUP BY o.id"):
                d = dict(r)
                _zero117 = ((d["n"] or 0) > 0 and (d["nz"] or 0) == 0) or ((d["n"] or 0) == 0 and float(d["tot"] or 0) == 0)
                if d.get("tbd"):   # z1191z117 ⑤: 단가 미정 수주 = 무상 아님 · 금액이 아직 0 이면 [미정]
                    _TBD117_MAP[d["pid"]] = _TBD117_MAP.get(d["pid"], True) and _zero117
                    out[d["pid"]] = False
                    continue
                _free = ((d["n"] or 0) > 0 and (d["nn"] or 0) == 0 and (d["nz"] or 0) == 0) or                         ((d["n"] or 0) == 0 and d["tot"] is not None and float(d["tot"] or 0) == 0)
                out[d["pid"]] = out.get(d["pid"], True) and bool(_free)
    except Exception:
        return {}
    return out


def _proj_free_z1191z8(p, so_map=None):
    """z1191z8: 수주(SO) 분할 줄이 없는 프로젝트 줄 — 수주가 있으면 그 수주 전부 무상일 때(so_map) ·
    수주가 없으면 projects 단가·금액을 **둘 다 0 으로 적었을 때만** 무상(NULL=안 적음 · 단가 있고 금액 0 은 아님)."""
    try:
        if so_map and p.get("id") in so_map:
            return bool(so_map[p.get("id")])
        return (p.get("order_amount") is not None and float(p.get("order_amount") or 0) == 0
                and p.get("unit_price") is not None and float(p.get("unit_price") or 0) == 0)
    except Exception:
        return False


def _co_free_ids_z1191z8():
    """z1191z8 (이새롬 프로 요청 · 대표 승인 2026-11-06): 「무상」 소모품 id 집합 —
    품목이 1줄 이상 있고 **단가를 전부 0 으로 적은** 건(단가 NULL 은 '아직 안 적음'이라 제외). 운영 4건(012C2603 등)."""
    try:
        with db_session() as _c:
            return {r[0] for r in _c.execute(
                "SELECT co_id FROM consumable_order_items GROUP BY co_id "
                "HAVING SUM(unit_price IS NULL)=0 AND SUM(CASE WHEN COALESCE(unit_price,0)<>0 OR COALESCE(amount,0)<>0 THEN 1 ELSE 0 END)=0")}
    except Exception:
        return set()


def _board_cbiz_apply_z1191z8(rows, biz, cbiz):
    """z1191z8: 소모품 탭(biz=C) 안 하위 책갈피 — 진행 사업부(consumable_orders.biz_div T/M) 건수와 필터.
    반환 (rows, cbiz, cbiz_counts). biz 가 C 가 아니면 필터 없음(cbiz='')."""
    _cb = (cbiz or "").strip().upper()
    _cnt = {"all": 0, "T": 0, "M": 0, "": 0}
    for r in rows:
        if r.get("div") == "C":
            _cnt["all"] += 1
            _k = (r.get("cbiz") or "")
            _cnt[_k if _k in ("T", "M") else ""] += 1
    if biz == "C" and _cb in ("T", "M"):
        rows = [r for r in rows if (r.get("cbiz") or "") == _cb]
    else:
        _cb = ""
    return rows, _cb, _cnt


def _consumable_biz_label(biz_div):
    _sub = _CONS_BIZ_SUB.get(str(biz_div or "").strip().upper())
    return "소모품·" + _sub if _sub else "소모품"


def _consumable_notify_send(co, items, team_ids, user_ids, user):
    """v5H226z890 (대표 지시): 소모품 통보를 제작요청서 체계로 편입.
    - 부서(team_ids 전체 구성원) + 개별(user_ids) 수신자에게 WORKS 벨 📋 카드 알림(kind=consumable_request)
      + 이음(KNK Eum) 카드 푸시(type=prod_request 로 제작요청과 동일 카드 렌더).
    - ⛔가격 제외(제작요청 규약·전직원 가격 게이트). 수신부서/명단 스냅샷을 consumable_orders 에 저장.
    반환 dict {ok, sent_to, dept_count, msg_sent, recipients, co_no, [error]}"""
    from datetime import datetime as _dt2
    co_id = co.get("id")
    sender_id = user.get("id") or -1
    by_name = user.get("name") or user.get("username") or "—"
    now_str = _dt2.now().strftime("%Y-%m-%d %H:%M")
    # z1191z48c (대표 2026-11-17 「관리번호 수주번호는 필수」): 둘 중 하나라도 없으면 소모품 요청서를 내보내지 않는다
    if not str(co.get("mgmt_code") or "").strip() or not str(co.get("co_no") or "").strip():
        return {"ok": False, "error": "need_mgmt_order",
                "message": "관리번호·수주번호가 없는 소모품 수주입니다 — 둘 다 있어야 소모품 요청서를 발행할 수 있습니다(필수)."}
    mgmt = co.get("mgmt_code") or "—"
    co_no = co.get("co_no") or f"CO-{co_id}"
    model = co.get("model_name") or "소모품"
    equip = co.get("equip_name") or ""
    cust = co.get("customer_name") or "—"
    cc_nm = co.get("cc_name") or ""
    due = (str(co.get("due_date") or "")[:10]) or "—"
    note = (co.get("note") or "").strip()
    line_count = len(items or [])
    # v5H226z1019 (대표 지시): 소모품 수량은 '항목별'(합산 표기 폐지 — 제작요청서 화면 z896과 통일)
    qty_disp = "항목별"
    # 본문 = 제작요청 ■-포맷 미러(가격 제외)
    _SEP = "━━━━━━━━━━━━━━━━━"
    _SUB = "─────────────────"
    title = f"📋 소모품 요청 [{mgmt}] {model}"
    body = f"📋 소모품 요청서 · {mgmt} · {model}\n{_SEP}\n"
    _cust_line = f"■ 고객사 : {cust}"
    if cc_nm:
        _cust_line += f" · 담당자 {cc_nm}"
    body += _cust_line + "\n"
    body += f"■ 품목 : 라인 {line_count}건 · 항목별\n"
    if equip:
        body += f"■ 장비 : {equip}\n"
    body += f"■ 일정 : {due} · 수주 {co_no}\n"
    if note:
        body += f"{_SUB}\n📝 기타 : {note}\n"
    body += f"{_SEP}\n요청자 {by_name} · {now_str}"
    link = f"/consumables/{co_id}"
    team_ids = [int(t) for t in (team_ids or []) if str(t).strip().lstrip("-").isdigit()]
    user_ids = [int(x) for x in (user_ids or []) if str(x).strip().lstrip("-").isdigit()]
    uids = set()
    _dept_ids = set()
    recipients_parts = []
    dept_names = ""
    emp_nos = []
    sent_to = 0
    dept_count = 0
    msg_sent = 0
    msg_err = ""
    try:
        with db_session() as c:
            # 부서 전체 → 그 팀 활성 구성원(발신자 제외) + 구성원 있는 팀만 부서 카운트/이름
            if team_ids:
                ph = ",".join("?" * len(team_ids))
                for r in c.execute(
                    f"SELECT id FROM users WHERE team_id IN ({ph}) "
                    f"AND COALESCE(is_active,1)=1 AND id != ?", (*team_ids, sender_id)).fetchall():
                    uids.add(r[0] if not isinstance(r, dict) else r["id"])
                _drs = c.execute(
                    f"SELECT DISTINCT t.id, t.name FROM teams t JOIN users u ON u.team_id=t.id "
                    f"AND COALESCE(u.is_active,1)=1 AND u.id != ? WHERE t.id IN ({ph})",
                    (sender_id, *team_ids)).fetchall()
                _dept_ids = {(dr[0] if not isinstance(dr, dict) else dr["id"]) for dr in _drs}
                _tn = sorted({(dr[1] if not isinstance(dr, dict) else dr["name"]) for dr in _drs
                              if (dr[1] if not isinstance(dr, dict) else dr["name"])})
                dept_names = ", ".join(_tn)
                for _n in _tn:
                    recipients_parts.append("🏢 " + _n)
            # 개별 인원(발신자 제외·부서로 이미 포함되면 중복 방지) — 명단은 개별로 표기(이름 직책 부서)
            if user_ids:
                ph2 = ",".join("?" * len(user_ids))
                for r in c.execute(
                    f"SELECT * FROM users WHERE id IN ({ph2}) AND COALESCE(is_active,1)=1 AND id != ?",
                    (*user_ids, sender_id)).fetchall():
                    rd = dict(r)
                    uids.add(rd["id"])
                    recipients_parts.append("👤 " + vname_full(rd))
            recipients = " · ".join(recipients_parts)
            dept_count = len(_dept_ids)
            # WORKS 벨 알림 — kind=consumable_request(📋), 본문=제작요청형
            for uid in uids:
                c.execute(
                    "INSERT INTO notifications(user_id, kind, title, body, link) VALUES(?,?,?,?,?)",
                    (uid, "consumable_request", title, body, link))
                sent_to += 1
            # 이음 사번 수집(있는 인원만)
            if uids:
                ph3 = ",".join("?" * len(uids))
                for er in c.execute(
                    f"SELECT employee_no FROM users WHERE id IN ({ph3}) AND COALESCE(employee_no,'')<>''",
                    tuple(uids)).fetchall():
                    emp_nos.append(er[0] if not isinstance(er, dict) else er["employee_no"])
            # 수신부서·명단 스냅샷 저장(제작요청 상세처럼 표시용)
            c.execute(
                "UPDATE consumable_orders SET notify_recipients=?, notify_dept_names=?, notify_sent_to=?, "
                "notify_dept_count=?, notify_user_ids=?, notify_team_ids=?, notify_at=?, notify_by_name=? WHERE id=?",
                (recipients, dept_names, sent_to, dept_count,
                 ",".join(str(x) for x in sorted(user_ids)),
                 ",".join(str(x) for x in sorted(team_ids)),
                 now_str, by_name, co_id))
    except Exception as e:
        return {"ok": False, "error": f"db_error: {str(e)[:120]}"}
    # 이음(KNK Eum) 카드 푸시 — 제작요청과 동일 카드 형태(type=prod_request). 실패해도 벨 알림은 유지.
    try:
        from . import sso_client
        _pub = os.environ.get("KNK_WORKS_PUBLIC_BASE", "https://works.knknara.co.kr").rstrip("/")
        _full = f"{_pub}{link}"
        _ST_KO = {"DRAFT": "작성중", "QUOTED": "견적", "CONFIRMED": "진행중", "SHIPPED": "출하",
                  "PAID": "출하", "CANCELLED": "취소", "HOLD": "보류"}
        _card = {
            "type": "prod_request", "title": "소모품 요청서",
            "mgmt": mgmt, "customer": cust, "cc_name": cc_nm, "author": by_name,
            "model": model, "equip": equip,
            "biz": _consumable_biz_label(co.get("biz_div")), "biz_code": "C", "po_type": "소모품",
            "status": _ST_KO.get(str(co.get("status") or "").upper(), "진행중"),
            "qty": qty_disp, "due": due, "so_nos": [co_no],
            "cust_req": "", "note": note, "issued_at": now_str, "link": _full,
        }
        if emp_nos:
            _mres = sso_client.notify_via_messenger(emp_nos, title, body, _full, card=_card)
            if _mres.get("ok"):
                msg_sent = _mres.get("sent", 0)
            else:
                msg_err = _mres.get("error", "")
        # 발행자 본인에게도 이음 카드(발행 확인) — 통보 수 미포함
        try:
            with db_session() as c2:
                _ar = c2.execute("SELECT employee_no FROM users WHERE id=? AND COALESCE(employee_no,'')<>''",
                                 (sender_id,)).fetchone()
            if _ar:
                _self_emp = _ar[0] if not isinstance(_ar, dict) else _ar["employee_no"]
                _self_ttl = f"✅ 내가 발행한 소모품 요청 · {mgmt} — {sent_to}명 통보"
                sso_client.notify_via_messenger([_self_emp], _self_ttl, body, _full, card=_card)
        except Exception:
            pass
    except Exception as _e:
        msg_err = str(_e)[:100]
    try:
        with db_session() as c3:
            c3.execute("UPDATE consumable_orders SET notify_msg_sent=? WHERE id=?", (msg_sent, co_id))
    except Exception:
        pass
    return {"ok": True, "sent_to": sent_to, "dept_count": dept_count, "msg_sent": msg_sent,
            "recipients": recipients, "co_no": co_no, "msg_err": msg_err}


@app.post("/consumables/{co_id:int}/notify")
async def consumables_notify(request: Request, co_id: int):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "auth"}, 401)
    if not (can_use_logistics(u) or can_use_sales(u)):
        return JSONResponse({"ok": False, "error": "forbidden"}, 403)
    co = _co.co_get(co_id)
    if not co:
        return JSONResponse({"ok": False, "error": "not_found"}, 404)
    items = _co.coi_list(co_id) or []
    try:
        _b = await request.json()
    except Exception:
        _b = {}
    team_ids = _b.get("team_ids") or []
    user_ids = _b.get("user_ids") or []   # z890: 개별 인원 추가(제작요청과 동일)
    if not team_ids and not user_ids:
        return JSONResponse({"ok": False, "error": "no_target",
                             "message": "통보할 부서 또는 인원을 선택하세요"}, 400)
    res = _consumable_notify_send(co, items, team_ids, user_ids, u)
    if not res.get("ok"):
        return JSONResponse(res, 400 if res.get("error") == "need_mgmt_order" else 500)   # z48c: 필수값 없음 = 요청 쪽 문제
    return JSONResponse(res)


@app.post("/consumables/{co_id:int}/delete")
async def consumables_delete(request: Request, co_id: int):
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not (can_use_logistics(u) or can_use_sales(u)):
        return RedirectResponse("/home", 303)
    _co.co_delete(co_id)
    return RedirectResponse("/consumables", 303)


@app.get("/api/parts/search")
async def api_parts_search(request: Request, q: str = ""):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "auth"}, 401)
    q = (q or "").strip()
    rows = []
    try:
        with db_session() as c:
            if q:
                like = f"%{q}%"
                rs = c.execute(
                    "SELECT id, part_no, part_name, std_price, unit FROM parts "
                    "WHERE (part_no LIKE ? OR part_name LIKE ?) "
                    "  AND COALESCE(is_active,1)=1 LIMIT 30",
                    (like, like)
                ).fetchall()
            else:
                rs = c.execute(
                    "SELECT id, part_no, part_name, std_price, unit FROM parts "
                    "WHERE COALESCE(is_active,1)=1 ORDER BY id DESC LIMIT 30"
                ).fetchall()
            rows = [dict(r) for r in rs]
    except Exception as e:
        return JSONResponse({"ok": False, "error": str(e)}, 500)
    return JSONResponse({"ok": True, "rows": rows})

